public class VideoHandler : MonoBehaviour
{
	public VideoClip[] clips;

	private int currentClip;

	private VideoPlayer vp;

	private SpriteRenderer spriteRen;

	private RenderTexture renderTarget;

	public AnimationCurve fadeoutAnimation01;

	private float timeSinceVideoSwap;

	private bool swapVideo;

	private void Awake()
	{
		vp = GetComponent<VideoPlayer>();
		spriteRen = GetComponent<SpriteRenderer>();
		currentClip = 0;
		vp.clip = clips[0];
		GenerateRenderTarget();
		vp.targetTexture = renderTarget;
		vp.Play();
		swapVideo = false;
		float time = fadeoutAnimation01.keys[fadeoutAnimation01.length - 1].time;
		timeSinceVideoSwap = time;
	}

	private void Update()
	{
		float time = fadeoutAnimation01.keys[fadeoutAnimation01.length - 1].time;
		_ = swapVideo;
		if (swapVideo && timeSinceVideoSwap < time)
		{
			spriteRen.material.SetFloat("_ColorBlend", fadeoutAnimation01.Evaluate(timeSinceVideoSwap));
		}
		else if (swapVideo && vp.isPrepared)
		{
			swapVideo = false;
			vp.targetTexture = renderTarget;
			vp.Play();
		}
		if (!swapVideo)
		{
			float value = 1f - Mathf.Clamp01(fadeoutAnimation01.Evaluate(timeSinceVideoSwap - time));
			spriteRen.material.SetFloat("_ColorBlend", value);
		}
		timeSinceVideoSwap += Time.deltaTime;
	}

	private void GenerateRenderTarget()
	{
		if (renderTarget != null)
		{
			RenderTexture obj = renderTarget;
			renderTarget = null;
			UnityEngine.Object.DestroyImmediate(obj);
		}
		VideoClip videoClip = clips[currentClip];
		renderTarget = new RenderTexture((int)videoClip.width, (int)videoClip.height, 0, RenderTextureFormat.ARGB32)
		{
			filterMode = FilterMode.Bilinear
		};
		spriteRen.material.SetTexture("_Tex", renderTarget);
	}
}
public class AirwaveCaster_DEBUG : MonoUpdatable
{
	public Fix CastFrequency = (Fix)4L;

	private FixTransform fixTrans;

	private Fix timePassed;

	public FixTransform airwavePrefab;

	private void Start()
	{
	}

	public void OnDrawGizmos()
	{
		Gizmos.DrawWireSphere(base.transform.position, 1f);
		if (timePassed > CastFrequency / (Fix)3L)
		{
			Gizmos.DrawWireSphere(base.transform.position, 2f);
		}
		if (timePassed > CastFrequency * (Fix)2L / (Fix)3L)
		{
			Gizmos.DrawWireSphere(base.transform.position, 3f);
		}
	}

	public override void Init()
	{
		timePassed = Fix.Zero;
	}

	private void Awake()
	{
		fixTrans = GetComponent<FixTransform>();
		Updater.RegisterUpdatable(this);
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		timePassed += SimDeltaTime;
		if (timePassed > CastFrequency)
		{
			FixTransform.InstantiateFixed(airwavePrefab, fixTrans.position);
			timePassed = Fix.Zero;
		}
	}
}
public class AnimatorChild : MonoBehaviour
{
	public AnimationData data;

	public string animationNamePrefix;

	private SpriteAnimator spriteAnim;

	private SpriteRenderer spriteRen;

	private void Awake()
	{
		spriteAnim = base.transform.GetComponentInParent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
	}

	private void Update()
	{
		if (spriteAnim.childAnimationSuffix != null)
		{
			string animationName = animationNamePrefix + spriteAnim.childAnimationSuffix;
			int num = spriteAnim.CurrentSpriteIndex();
			SpriteFrame[] animation = data.GetAnimation(animationName);
			spriteRen.sprite = animation[num].sprite;
		}
	}
}
public enum BeamState
{
	enter,
	loop,
	exit
}
public class Beam : MonoUpdatable, IAbilityComponent
{
	[SerializeField]
	private AnimationData animData;

	[SerializeField]
	private AnimationData orbAnimData;

	[SerializeField]
	private AnimationData orbAnimDataAir;

	public SpriteRenderer handRenderer;

	public SpriteAnimator OrbEffectPrefab;

	[SerializeField]
	private SpriteAnimator sparksAnimator;

	[SerializeField]
	private SpriteRenderer preGlowRen;

	[SerializeField]
	private SpriteRenderer preGlowRen_refl;

	private PlayerInfo playerInfo;

	private Player player;

	private Fix timeSinceActivation = (Fix)0L;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private ShakableCamera shakeCam;

	private DPhysicsBox hurtbox;

	private PlayerCollision playerCol;

	private Vec2 origFixTransOffset;

	private Vec2 origExtents;

	private BeamState state;

	private bool inAir;

	private SpriteAnimator orbEffect;

	private FixTransform orbEFfectPos;

	public Fix shakeDuration;

	public Fix shakeStr;

	public float camShakeStr;

	private OrbAnimation orbAnim;

	private DisableIfNotHeld_deter orbHandle;

	private UnityEngine.Color playerColor;

	private InterruptableAudio loadingSound;

	private bool beamAimedUp;

	public Fix upAlignmentUntilUpAnimationIsUsed;

	public Fix minGroundedAngle;

	private ShakablePlatform shakablePlatform;

	private StickyRoundedRectangle currentGround;

	public PlayerColors playerColors;

	public BeamColorList playerBeamColors;

	private DetPhysics.BeamColors playerBeamColor;

	private int beamIndex;

	public AnimationCurveFixed exitScaleAnim;

	public Fix beamOffset;

	public Vec2 hurtBoxExtentsAir;

	public Vec2 hurtBoxOffsetAir;

	private Vec2 staffDir;

	private Vec2 relativeStaffDir;

	public Sprite exitSprite;

	private PhysicsParent[] circleHitBuffer = new PhysicsParent[1];

	public Fix angularAimSpeed;

	public AnimationCurveFixed angularAimSpeedAnim01;

	public Fix onExitUpSpeed;

	public Fix maxAngle01;

	private Fix timeSinceBeamStart;

	private Fix timeSinceEnter;

	public float handBaseRotation;

	public float handBaseRotationUp;

	private bool beamMovedThisFrame;

	public Fix maxTime;

	public Fix maxTimeAir;

	public AnimationCurve preGlowAnim;

	private float timeSinceGlowAppeared;

	public float glowEffectExitFadeSpeed;

	public Fix exitScaleTime;

	private bool onFirstFrame;

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		playerCol = GetComponent<PlayerCollision>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		shakeCam = UnityEngine.Object.FindObjectOfType<ShakableCamera>();
		hurtbox = GetComponent<DPhysicsBox>();
		origFixTransOffset = GetComponent<FixTransform>().offset;
		origExtents = hurtbox.CalcExtents();
		physics.OnAttachedToGround += OnGrounded;
		physics.OnNoLongerGrounded += OnUngrounded;
	}

	private void OnUngrounded(Fix prevRotation)
	{
		if (!inAir)
		{
			relativeStaffDir = Vec2.ComplexMul(staffDir, new Vec2(body.right.x, -body.right.y));
			SetFacingDirection(staffDir);
		}
	}

	private void OnGrounded(RaycastInformation raycastInfo)
	{
		if (inAir)
		{
			ExitAbility(new AbilityExitInfo
			{
				justlanded = true
			});
		}
		else
		{
			relativeStaffDir = Vec2.ComplexMul(staffDir, new Vec2(body.right.x, -body.right.y));
			SetFacingDirection(staffDir);
		}
	}

	private Vec2 FirePos()
	{
		return body.position + staffDir * (Fix)2.8 * body.fixtrans.Scale;
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		handRenderer.material = playerInfo.playerMaterial;
		playerColor = playerInfo.playerMaterial.GetColor("_ShadowColor");
		Vec2 selfImposedVelocity = playerInfo.selfImposedVelocity;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		animator.enabled = true;
		beamIndex = -1;
		timeSinceBeamStart = Fix.Zero;
		timeSinceEnter = Fix.Zero;
		onFirstFrame = true;
		SetFacingDirection(player.AimVector());
		playerCol.IgnoreBeamId(base.HierarchyNumber);
		timeSinceGlowAppeared = 0f;
		currentGround = null;
		state = BeamState.enter;
		if (playerInfo.isGrounded && playerInfo.currentlyAttachedGround != null && !playerInfo.currentlyAttachedGround.IsDestroyed)
		{
			handRenderer.gameObject.SetActive(value: true);
			body.selfImposedVelocity = selfImposedVelocity;
			body.fixtrans.offset = origFixTransOffset;
			hurtbox.SetExtents(origExtents);
			inAir = false;
			currentGround = physics.getAttachedGround();
			shakablePlatform = currentGround?.GetComponent<ShakablePlatform>();
			InitStartDir(player.AimVector());
			animator.beginAnimThenDoAction(animData.GetAnimation("enterFrame1"), OnLeftFirstFrame);
			animator.StartChildAnimations("enter");
		}
		else
		{
			handRenderer.gameObject.SetActive(value: false);
			body.selfImposedVelocity = Vec2.zero;
			body.fixtrans.offset = hurtBoxOffsetAir;
			hurtbox.SetExtents(hurtBoxExtentsAir);
			inAir = true;
			animator.beginAnimThenDoAction(animData.GetAnimation("enterAir"), StartBeam);
			if (player.AimVector() == Vec2.zero)
			{
				staffDir = Vec2.down;
				relativeStaffDir = Vec2.down;
			}
			else
			{
				staffDir = player.AimVector();
				relativeStaffDir = player.AimVector();
			}
			beamAimedUp = false;
		}
		AudioManager.Get().PlayRandomWithPrefix("beamSparks");
		loadingSound = AudioManager.Get().PlayInterruptable("beamCharge" + player.Id);
		preGlowRen_refl.gameObject.SetActive(value: false);
		preGlowRen.gameObject.SetActive(value: false);
		calcPlayerBeamColor();
		sparksAnimator.beginAnimThenDoAction(orbAnimData.GetAnimation("sparks"), delegate
		{
			sparksAnimator.gameObject.SetActive(value: false);
		});
		sparksAnimator.gameObject.SetActive(value: true);
		sparksAnimator.spriteRen.color = playerBeamColor.orange;
		if (orbEffect == null)
		{
			orbEffect = FixTransform.InstantiateFixed(OrbEffectPrefab, FirePos());
			orbEFfectPos = orbEffect.GetComponent<FixTransform>();
			orbAnim = orbEffect.GetComponent<OrbAnimation>();
			orbHandle = orbEffect.GetComponent<DisableIfNotHeld_deter>();
			orbAnim.hitbox.ManualInit();
		}
		orbAnim.hitbox.enabled = false;
		orbHandle.HoldThisFrame(this);
		orbAnim.SetColors(playerBeamColor);
		orbAnim.SetScale((float)hurtbox.Scale);
		orbAnim.SetOwnerId(player.Id);
		orbEffect.gameObject.SetActive(value: true);
		StartOrbAnimation();
	}

	private void InitStartDir(Vec2 aimVector)
	{
		if (aimVector == Vec2.zero)
		{
			aimVector = (playerInfo.isFacingRight ? body.right : (-body.right));
		}
		SetStartDir(aimVector);
	}

	private void SetStartDir(Vec2 aimVector)
	{
		staffDir = aimVector;
		Fix fix = Vec2.NormalizedVectorAngle(Vec2.ComplexMul(staffDir, new Vec2(body.right.x, -body.right.y)));
		if (fix < Fix.Pi + minGroundedAngle || fix > Fix.PiTimes2 - minGroundedAngle)
		{
			staffDir = new Vec2(fix);
		}
		else if (base.transform.localScale.x >= 0f)
		{
			staffDir = new Vec2(Fix.PiTimes2 - minGroundedAngle);
		}
		else
		{
			staffDir = new Vec2(Fix.Pi + minGroundedAngle);
		}
		staffDir = Vec2.ComplexMul(staffDir, body.right);
		relativeStaffDir = Vec2.ComplexMul(staffDir, new Vec2(body.right.x, -body.right.y));
		beamAimedUp = Vec2.Dot(relativeStaffDir, Vec2.up) > upAlignmentUntilUpAnimationIsUsed;
	}

	private void OnLeftFirstFrame()
	{
		if (beamAimedUp)
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("enterUp"), StartBeam);
			animator.StartChildAnimations("enter");
		}
		else
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("enter"), StartBeam);
			animator.StartChildAnimations("enter");
		}
		SetFacingDirection(player.AimVector());
		UpdateSim(Fix.Zero);
		onFirstFrame = false;
	}

	private void SetFacingDirection(Vec2 aimVector)
	{
		if (aimVector == Vec2.zero)
		{
			aimVector = (playerInfo.isFacingRight ? body.right : (-body.right));
		}
		if (Vec2.Dot(aimVector, body.right) > 0L)
		{
			base.transform.localScale = new Vector3(1f, base.transform.localScale.y, base.transform.localScale.z);
		}
		else
		{
			base.transform.localScale = new Vector3(-1f, base.transform.localScale.y, base.transform.localScale.z);
		}
	}

	private void StartBeam()
	{
		AudioManager.Get().Play("beamFire");
		orbAnim.hitbox.enabled = true;
		body.fixtrans.offset = hurtBoxOffsetAir;
		timeSinceBeamStart = Fix.Zero;
		state = BeamState.loop;
		if (!inAir)
		{
			if (Vec2.Dot(staffDir, body.right) > 0L)
			{
				base.transform.localScale = new Vector3(1f, base.transform.localScale.y, base.transform.localScale.z);
			}
			else
			{
				base.transform.localScale = new Vector3(-1f, base.transform.localScale.y, base.transform.localScale.z);
			}
		}
		if (inAir)
		{
			animator.beginAnimation(animData.GetAnimation("loopAir"));
		}
		else if (beamAimedUp)
		{
			staffDir = body.right * (playerInfo.isFacingRight ? Fix.One : (-Fix.One));
			animator.beginAnimation(animData.GetAnimation("loopUp"));
			animator.StartChildAnimations("loopUp");
		}
		else
		{
			staffDir = body.right * (playerInfo.isFacingRight ? Fix.One : (-Fix.One));
			animator.beginAnimation(animData.GetAnimation("loop"));
			animator.StartChildAnimations("loop");
		}
	}

	private void StartOrbAnimation()
	{
		orbEffect.StartChildAnimations("Enter");
		orbEffect.beginAnimThenDoAction(inAir ? orbAnimDataAir.GetAnimation("whiteEnter") : orbAnimData.GetAnimation("whiteEnter"), ContinueOrbAnim);
	}

	private void ContinueOrbAnim()
	{
		orbEffect.StartChildAnimations("");
		orbEffect.beginAnimation(orbAnimData.GetAnimation("white"));
	}

	private void StopOrbAnim()
	{
		if (!(orbAnim != null) || !(orbAnim.hitbox != null) || orbAnim.hitbox.IsDestroyed)
		{
			return;
		}
		orbAnim.hitbox.enabled = false;
		if (beamAimedUp)
		{
			orbEffect.StartChildAnimations("Exit");
		}
		else
		{
			orbEffect.StartChildAnimations("Exit");
		}
		orbEffect.beginAnimThenDoAction(orbAnimData.GetAnimation("whiteExit"), delegate
		{
			if (orbAnim.hitbox != null && !orbAnim.hitbox.IsDestroyed)
			{
				Updater.DestroyFix(orbEffect.gameObject);
			}
		});
	}

	private void calcPlayerBeamColor()
	{
		int key = 7;
		for (int i = 0; i < playerColors.playerColors.Length; i++)
		{
			if (playerColors.playerColors[i].playerMaterial.GetColor("_ShadowColor") == playerColor)
			{
				key = i;
			}
		}
		playerBeamColor = playerBeamColors[key];
		if (playerBeamColor.red == UnityEngine.Color.black)
		{
			preGlowRen_refl.color = new UnityEngine.Color(0.2f, 0.2f, 0.2f, 1f);
			preGlowRen.color = new UnityEngine.Color(0.2f, 0.2f, 0.2f, 1f);
		}
		else
		{
			preGlowRen_refl.color = playerBeamColor.red;
			preGlowRen.color = playerBeamColor.red;
		}
	}

	private void UpdateBeam(Fix simDeltaTime)
	{
		Vec2 vec = FirePos();
		Fix fix = Fix.One;
		Fix fix2 = (inAir ? maxTimeAir : maxTime);
		if (timeSinceBeamStart + exitScaleTime > fix2 && state == BeamState.loop && timeSinceBeamStart + exitScaleTime > fix2)
		{
			Fix t = (exitScaleTime - (fix2 - timeSinceBeamStart)) / exitScaleTime;
			fix = exitScaleAnim.Evaluate(t);
		}
		if (vec.y >= Constants.WATER_HEIGHT || Constants.leveltype == LevelType.space)
		{
			beamIndex = DetPhysics.Get().AddBeamBody(new DetPhysics.BeamBody
			{
				position = vec + staffDir * beamOffset,
				direction = staffDir,
				scale = body.fixtrans.Scale * fix,
				colors = playerBeamColor,
				timePassed = timeSinceBeamStart,
				id = base.HierarchyNumber,
				ownerId = player.Id,
				ground = currentGround
			});
		}
		else
		{
			beamIndex = -1;
		}
		timeSinceBeamStart += simDeltaTime;
	}

	private void Update()
	{
		if (state == BeamState.enter && !GameTime.IsTimeStoppedFor(player.Id))
		{
			player.Rumble(Rumble.Big);
		}
		if (beamIndex > 0)
		{
			DetPhysics.BeamRole beamRole = DetPhysics.Get().beamRoles[beamIndex];
			if ((beamRole == DetPhysics.BeamRole.Child || beamRole == DetPhysics.BeamRole.MaybeChild || beamRole == DetPhysics.BeamRole.ParentAndChild) && state == BeamState.loop)
			{
				AudioManager.Get().PlayOrContinueLoop("beamLoopBig");
			}
		}
		if (state == BeamState.loop)
		{
			AudioManager.Get().PlayOrContinueLoop("beamLoop");
		}
		if (state == BeamState.loop && beamMovedThisFrame)
		{
			AudioManager.Get().PlayOrContinueLoop("beamLoopHP");
		}
	}

	private void OnDrawGizmos()
	{
		Vector3 vector = base.transform.position + (Vector3)hurtBoxOffsetAir;
		Vector3 vector2 = base.transform.right * (float)hurtBoxExtentsAir.x;
		Vector3 vector3 = base.transform.up * (float)hurtBoxExtentsAir.y;
		Vector3 vector4 = vector + vector2 + vector3;
		Vector3 vector5 = vector + vector2 - vector3;
		Vector3 vector6 = vector - vector2 + vector3;
		Vector3 vector7 = vector - vector2 - vector3;
		Gizmos.color = UnityEngine.Color.red;
		Gizmos.DrawLine(vector4, vector5);
		Gizmos.DrawLine(vector5, vector7);
		Gizmos.DrawLine(vector7, vector6);
		Gizmos.DrawLine(vector6, vector4);
		Gizmos.color = UnityEngine.Color.green;
		Gizmos.DrawWireSphere(base.transform.position + 4f * (Vector3)staffDir, 0.5f);
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		body.selfImposedVelocity += Vec2.up * onExitUpSpeed;
		if (loadingSound.timesPlayed == AudioManager.Get().TimesSoundsPlayed(loadingSound))
		{
			loadingSound.source.Stop();
		}
		body.rotation = Fix.Zero;
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.position = body.position;
		exitInfo.isFacingRight = playerInfo.isFacingRight;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		if (inAir)
		{
			exitInfo.lastSprite = exitSprite;
		}
		else
		{
			exitInfo.lastSprite = null;
		}
		if (exitInfo.isGrounded)
		{
			exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		}
		exitInfo.radius = physics.radius;
		ability.ExitAbility(exitInfo);
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	private void MovePlayer(Fix deltaTime)
	{
		Vec2 inputVector = Vec2.zero;
		if (!inAir && state == BeamState.exit)
		{
			inputVector = player.InputVector();
		}
		if (!physics.IsGrounded() && inAir)
		{
			physics.AirealMovement(Fix.Zero, deltaTime);
			bool flag = physics.VelocityBasedRaycasts(attachToGroundIfHit: true, deltaTime);
			if (DetPhysics.Get().circleCastRoundedRect(body.position, physics.radius, ref circleHitBuffer) > 0)
			{
				flag = true;
				physics.AttachToGround(circleHitBuffer[0].fixTrans.GetComponent<StickyRoundedRectangle>(), body.position);
			}
			if (flag)
			{
				AbilityExitInfo exitInfo = default(AbilityExitInfo);
				body.rotation = (Fix)0L;
				exitInfo.justlanded = true;
				exitInfo.groundedSpeed = physics.groundedSpeed;
				exitInfo.isGrounded = physics.IsGrounded();
				exitInfo.position = body.position;
				exitInfo.externalVelocity = body.externalVelocity;
				exitInfo.selfImposedVelocity = body.selfImposedVelocity;
				exitInfo.currentlyAttachedGround = physics.getAttachedGround();
				exitInfo.lastSprite = spriteRen.sprite;
				exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
				exitInfo.radius = physics.radius;
				ExitAbility(exitInfo);
			}
		}
		else if (!inAir && !physics.IsGrounded())
		{
			physics.AddGravityFactor();
			physics.Move(inputVector, deltaTime);
		}
		else
		{
			physics.Move(inputVector, deltaTime);
		}
	}

	private void UpdateGlowEffect(SpriteRenderer ren, Vector2 pos, Vector2 dir, float length)
	{
		ren.transform.position = pos;
		ren.transform.right = dir;
		Vector3 localScale = ren.transform.localScale;
		localScale.x = length / base.transform.localScale.x;
		ren.transform.localScale = localScale;
		float value = preGlowAnim.Evaluate(timeSinceGlowAppeared);
		ren.material.SetFloat("_Scale", length);
		ren.material.SetFloat("_NoiseFreq", value);
	}

	private void UpdateGlowEffects()
	{
		Vec2 vec = FirePos();
		if (!(vec.y >= Constants.WATER_HEIGHT) && Constants.leveltype != LevelType.space)
		{
			return;
		}
		Vec2 vec2 = vec + staffDir * beamOffset;
		Vec2 vec3 = staffDir;
		Fix beamLength;
		Fix beamRefl;
		bool num = DetPhysics.Get().RaycastBeam(vec2, vec3, out beamLength, out beamRefl);
		UpdateGlowEffect(preGlowRen, (Vector2)vec2, (Vector2)vec3, (float)beamLength);
		if (num)
		{
			Vec2 vec4 = vec2 + vec3 * beamLength;
			Vec2 vec5 = vec3;
			vec5.y = -vec5.y;
			UpdateGlowEffect(preGlowRen_refl, (Vector2)vec4, (Vector2)vec5, (float)beamRefl);
			if (!preGlowRen_refl.gameObject.activeSelf)
			{
				preGlowRen_refl.gameObject.SetActive(value: true);
			}
		}
	}

	public override void LateUpdateSim(Fix SimDeltaTime)
	{
		if (!(orbEffect != null) || orbEffect.IsDestroyed)
		{
			return;
		}
		if (inAir)
		{
			if (state == BeamState.loop)
			{
				orbEFfectPos.position = FirePos();
			}
			else if (state == BeamState.enter && animator.getNumberOfPassedSprites() >= 10)
			{
				orbEFfectPos.position = body.position + staffDir * (Fix)3.1 * body.fixtrans.Scale;
			}
			else if (state == BeamState.enter && animator.getNumberOfPassedSprites() >= 9)
			{
				Vec2 vec = new Vec2((Fix)0.1, -(Fix)2L);
				orbEFfectPos.position = body.position + Vec2.ComplexMul(body.right, new Vec2(vec.x * ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One), vec.y)) * hurtbox.Scale;
			}
			else if (state == BeamState.enter && animator.getNumberOfPassedSprites() >= 8)
			{
				Vec2 vec2 = new Vec2((Fix)0.1, -(Fix)2.3);
				orbEFfectPos.position = body.position + Vec2.ComplexMul(body.right, new Vec2(vec2.x * ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One), vec2.y)) * hurtbox.Scale;
			}
			else if (state == BeamState.enter)
			{
				orbEFfectPos.position = FirePos();
			}
		}
		else if (beamAimedUp)
		{
			if (state == BeamState.loop)
			{
				orbEFfectPos.position = FirePos();
			}
			else if (state == BeamState.enter && animator.getNumberOfPassedSprites() >= 8)
			{
				orbEFfectPos.position = body.position + Vec2.ComplexMul(body.right, new Vec2((Fix)0.9 * ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One), (Fix)0.6)) * hurtbox.Scale;
			}
			else if (state == BeamState.enter && animator.getNumberOfPassedSprites() >= 7)
			{
				orbEFfectPos.position = body.position + Vec2.ComplexMul(body.right, new Vec2((Fix)1.28 * ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One), (Fix)0.4)) * hurtbox.Scale;
			}
			else if (state == BeamState.enter)
			{
				orbEFfectPos.position = body.position + Vec2.ComplexMul(body.right, new Vec2((Fix)2.0 * ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One), -(Fix)0.05)) * hurtbox.Scale;
			}
		}
		else if (state == BeamState.loop)
		{
			orbEFfectPos.position = FirePos();
		}
		else if (state == BeamState.enter && animator.getNumberOfPassedSprites() >= 7)
		{
			orbEFfectPos.position = body.position + Vec2.ComplexMul(body.right, new Vec2((Fix)1.28 * ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One), (Fix)0.26)) * hurtbox.Scale;
		}
		else if (state == BeamState.enter)
		{
			orbEFfectPos.position = body.position + Vec2.ComplexMul(body.right, new Vec2((Fix)2.0 * ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One), -(Fix)0.05)) * hurtbox.Scale;
		}
		if (state == BeamState.enter)
		{
			timeSinceGlowAppeared += (float)GameTime.FixedDeltaTime(player.Id, SimDeltaTime);
			timeSinceGlowAppeared = Mathf.Min(timeSinceGlowAppeared, preGlowAnim.Duration());
			if (!preGlowRen.gameObject.activeSelf)
			{
				preGlowRen.gameObject.SetActive(value: true);
			}
			UpdateGlowEffects();
		}
		else if (state == BeamState.loop)
		{
			if (preGlowRen.gameObject.activeSelf)
			{
				preGlowRen.gameObject.SetActive(value: false);
			}
			if (preGlowRen_refl.gameObject.activeSelf)
			{
				preGlowRen_refl.gameObject.SetActive(value: false);
			}
		}
		else if (state == BeamState.exit && preGlowRen.gameObject.activeSelf)
		{
			timeSinceGlowAppeared -= (float)GameTime.FixedDeltaTime(player.Id, SimDeltaTime) * glowEffectExitFadeSpeed;
			UpdateGlowEffects();
		}
		orbEFfectPos.transform.localScale = new Vector3((float)body.fixtrans.Scale, (float)body.fixtrans.Scale, 1f);
		orbEFfectPos.transform.up = base.transform.up;
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		orbAnim.SetScale((float)hurtbox.Scale);
		if (orbHandle != null && !orbHandle.IsDestroyed)
		{
			orbHandle.HoldThisFrame(this);
		}
		if (GameTime.IsTimeStopped() && !player.isProtectedFromTimeStop)
		{
			_ = state;
			_ = 1;
			return;
		}
		beamMovedThisFrame = false;
		Fix angularIncrement = angularAimSpeed * angularAimSpeedAnim01.Evaluate(timeSinceEnter);
		timeSinceEnter += SimDeltaTime;
		if (player.AimVector() != Vec2.zero)
		{
			if (inAir)
			{
				Vec2 vec = Vec2.ApproachNormalizedVector(staffDir, player.AimVector(), angularIncrement);
				if (vec != staffDir)
				{
					beamMovedThisFrame = true;
				}
				relativeStaffDir = vec;
				staffDir = vec;
			}
			else
			{
				if (onFirstFrame)
				{
					InitStartDir(player.AimVector());
				}
				Vec2 target = Vec2.ComplexMul(u: new Vec2(body.right.x, -body.right.y), v: player.AimVector());
				Vec2 vec2 = Vec2.ApproachNormalizedVector(relativeStaffDir, target, angularIncrement);
				Fix fix = Vec2.NormalizedVectorAngle(vec2);
				if (!(fix < Fix.Pi + minGroundedAngle) && !(fix > Fix.PiTimes2 - minGroundedAngle))
				{
					vec2 = relativeStaffDir;
				}
				if (vec2 != relativeStaffDir)
				{
					beamMovedThisFrame = true;
				}
				relativeStaffDir = vec2;
			}
		}
		if (!inAir)
		{
			staffDir = Vec2.ComplexMul(body.right, relativeStaffDir);
		}
		if (inAir)
		{
			if (staffDir.y > 1L || staffDir.y < -1L)
			{
				body.up = Vec2.up;
			}
			else
			{
				body.up = -staffDir;
			}
		}
		else if (beamAimedUp)
		{
			handRenderer.transform.right = (Vector3)staffDir * ((!(base.transform.localScale.x < 0f)) ? 1 : (-1));
			handRenderer.transform.Rotate(new Vector3(0f, 0f, 0f - handBaseRotationUp));
		}
		else
		{
			handRenderer.transform.right = (Vector3)staffDir * ((!(base.transform.localScale.x < 0f)) ? 1 : (-1));
			handRenderer.transform.Rotate(new Vector3(0f, 0f, 0f - handBaseRotation));
		}
		if (state == BeamState.enter)
		{
			if (!inAir)
			{
				shakablePlatform?.AddShake(shakeDuration, shakeStr);
			}
			shakeCam.AddMinTrauma(camShakeStr);
		}
		if ((state == BeamState.enter || state == BeamState.loop) && !player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012))
		{
			Stop();
		}
		MovePlayer(SimDeltaTime);
		switch (state)
		{
		case BeamState.loop:
			UpdateBeam(SimDeltaTime);
			if (player.jumpButton_PressedThisFrame())
			{
				StopOrbAnim();
				ExitAbility(new AbilityExitInfo
				{
					enterJump = true
				});
				return;
			}
			break;
		case BeamState.exit:
			if (player.jumpButton_PressedThisFrame())
			{
				StopOrbAnim();
				ExitAbility(new AbilityExitInfo
				{
					enterJump = true
				});
				return;
			}
			break;
		}
		Fix fix2 = (inAir ? maxTimeAir : maxTime);
		if (timeSinceBeamStart + exitScaleTime > fix2 && state == BeamState.loop && timeSinceBeamStart > fix2 && state == BeamState.loop)
		{
			Stop();
		}
	}

	private void Stop()
	{
		StopOrbAnim();
		state = BeamState.exit;
		if (inAir)
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("exitAir"), ExitAbility);
		}
		else if (beamAimedUp)
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("exitUp"), ExitAbility);
			animator.StartChildAnimations("exitUp");
		}
		else
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("exit"), ExitAbility);
			animator.StartChildAnimations("exit");
		}
	}
}
public class beamAfterEffect : MonoBehaviour
{
	public AnimationCurve anim;

	[NonSerialized]
	public SpriteRenderer spriteRen;

	private float timePassed;

	private UnityEngine.Color red;

	private UnityEngine.Color orange;

	private void Awake()
	{
		spriteRen = GetComponent<SpriteRenderer>();
	}

	public void SetColors(UnityEngine.Color orange, UnityEngine.Color red)
	{
		this.red = red;
		this.orange = orange;
		Update();
	}

	private void Update()
	{
		float value = anim.Evaluate(timePassed);
		spriteRen.material.SetFloat("_NoiseFreq", value);
		timePassed += (float)GameTime.PlayerTimeScale * Time.deltaTime;
		float num = timePassed / anim.Duration();
		spriteRen.color = UnityEngine.Color.Lerp(orange, red, num);
		if (num >= 1f)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}
}
public class BeamEffect : MonoBehaviour
{
	public SpriteRenderer white;

	public SpriteRenderer yellow;

	public SpriteRenderer orange;

	public SpriteRenderer red;

	public SpriteRenderer additiveGlow;

	public AnimationCurve whiteScale;

	public AnimationCurve whiteAura;

	public ParticleSystem particleFlareTOP;

	public ParticleSystem particleFlareBOT;

	public float beamLength;

	private float prevOffset;

	public float particleRadiusScaling;

	public float particleRadiusOffset;

	public float whiteBaseAura;

	public float orangeBaseAura;

	public float yellowBaseAura;

	public float redBaseAura;

	public float additiveBaseAura;

	public float auraMultiplier = 1f;

	private int framesAlive;

	public UnityEngine.Color redCol => red.color;

	public UnityEngine.Color orangeCol => orange.color;

	private void Awake()
	{
	}

	public void Init()
	{
		framesAlive = 0;
		particleFlareBOT.Stop();
		particleFlareTOP.Stop();
		particleFlareBOT.Clear();
		particleFlareTOP.Clear();
	}

	public void SetColors(DetPhysics.BeamColors colors)
	{
		if (orange.color != colors.orange)
		{
			Init();
		}
		white.color = colors.white;
		orange.color = colors.orange;
		yellow.color = colors.yellow;
		red.color = colors.red;
		additiveGlow.color = colors.red;
		ParticleSystem.MainModule main = particleFlareTOP.main;
		main.startColor = colors.orange;
		ParticleSystem.MainModule main2 = particleFlareBOT.main;
		main2.startColor = colors.orange;
	}

	private void LateUpdate()
	{
		float num = whiteScale.Evaluate(Time.timeSinceLevelLoad);
		float y = white.transform.localScale.y + num - prevOffset;
		float y2 = yellow.transform.localScale.y + num - prevOffset;
		prevOffset = num;
		white.transform.localScale = new Vector3(beamLength, y);
		yellow.transform.localScale = new Vector3(beamLength, y2);
		orange.transform.localScale = new Vector3(beamLength + 2.8f, orange.transform.localScale.y);
		red.transform.localScale = new Vector3(beamLength, red.transform.localScale.y);
		additiveGlow.transform.localScale = new Vector3(white.transform.localScale.x, additiveGlow.transform.localScale.y, 1f);
		white.material.SetFloat("_Scale", white.transform.localScale.x);
		orange.material.SetFloat("_Scale", orange.transform.localScale.x);
		yellow.material.SetFloat("_Scale", yellow.transform.localScale.x);
		red.material.SetFloat("_Scale", red.transform.localScale.x);
		additiveGlow.material.SetFloat("_Scale", additiveGlow.transform.localScale.x);
		if (auraMultiplier >= 1f)
		{
			white.material.SetFloat("_Aura", whiteAura.Evaluate(Time.timeSinceLevelLoad) * auraMultiplier);
			orange.material.SetFloat("_Aura", orangeBaseAura * auraMultiplier);
			yellow.material.SetFloat("_Aura", yellowBaseAura * auraMultiplier);
		}
		else
		{
			white.material.SetFloat("_Aura", 0f);
			orange.material.SetFloat("_Aura", 0f);
			yellow.material.SetFloat("_Aura", 0f);
		}
		red.material.SetFloat("_NoiseFreq", auraMultiplier);
		additiveGlow.material.SetFloat("_Aura", additiveBaseAura * auraMultiplier);
		if (framesAlive > 1)
		{
			ParticleSystem.MainModule main = particleFlareBOT.main;
			float y3 = base.transform.localScale.y;
			main.startSizeX = 4f * y3;
			main.startSizeY = 4f * y3;
			ParticleSystem.MainModule main2 = particleFlareTOP.main;
			float y4 = base.transform.localScale.y;
			main2.startSizeX = 4f * y4;
			main2.startSizeY = 4f * y4;
			if (beamLength < 8f && particleFlareTOP.isPlaying)
			{
				particleFlareTOP.Stop();
			}
			if (beamLength >= 8f && !particleFlareTOP.isPlaying)
			{
				particleFlareTOP.Play();
			}
			if (beamLength < 8f && particleFlareBOT.isPlaying)
			{
				particleFlareBOT.Stop();
			}
			if (beamLength >= 8f && !particleFlareBOT.isPlaying)
			{
				particleFlareBOT.Play();
			}
		}
		additiveGlow.enabled = beamLength > 2f;
		framesAlive++;
	}
}
