	public int beamId;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
		beamEffect = GetComponent<BeamEffect>();
		hitbox = GetComponent<DPhysicsBox>();
		explosion = GetComponent<Explosion>();
	}

	public void Initialize()
	{
		hitbox.ManualInit();
		beamEffect.Init();
	}

	public void SetDimensions(Vec2 basePos, Fix width, Vec2 direction, Fix distance, Fix age, AnimationCurveFixed scaleAnim, int playerId, int beamId)
	{
		explosion.PlayerOwnerId = playerId;
		this.beamId = beamId;
		Fix fix = scaleAnim.Evaluate(age);
		width *= baseWidth01 * fix;
		fixTrans.position = basePos;
		base.transform.localScale = new Vector3(base.transform.localScale.x, (float)width, 1f);
		fixTrans.offset = new Vec2(distance * (Fix)0.5 + extraLength, Fix.Zero);
		hitbox.SetExtents(new Vec2(distance * (Fix)0.5 + extraLength, width));
		hitbox.right = Vec2.NormalizedSafe(direction);
		beamEffect.beamLength = (float)distance - visualOffset;
		hitbox.UpdatePhysicsPositions();
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}
}
public class Boulder : MonoUpdatable
{
	public Fix bouncinessWhenDropped01 = Fix.One;

	private bool isDropped;

	private bool shouldDrop;

	public DPhysicsRoundedRect hitbox;

	[NonSerialized]
	public BoplBody body;

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (!isDropped && shouldDrop && hitbox.initHasBeenCalled)
		{
			Drop();
			isDropped = true;
		}
		shouldDrop = true;
	}

	public void Hold()
	{
		shouldDrop = false;
	}

	public bool HasBeenDropped()
	{
		return isDropped;
	}

	public void Drop()
	{
		if (!(hitbox == null) && !hitbox.IsDestroyed && hitbox.initHasBeenCalled)
		{
			hitbox.SetGravityScale(Fix.One);
			hitbox.SetBounciness(bouncinessWhenDropped01);
		}
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		shouldDrop = false;
		body = GetComponent<BoplBody>();
	}
}
