	private bool isInited;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
	}

	public override void Init()
	{
	}

	public void HoldThisFrame(MonoUpdatable holder)
	{
		this.holder = holder;
		isHeld = true;
		isInited = true;
		if (!base.gameObject.activeSelf)
		{
			base.gameObject.SetActive(value: true);
		}
