public class Drill : MonoUpdatable, IAbilityComponent
{
	[Serializable]
	public struct PlatformColors
	{
		public PlatformType type;

		public UnityEngine.Color dark;

		public UnityEngine.Color medium;

		public UnityEngine.Color light;
	}

	public ParticleSystem particleSystemPrefab;

	public List<PlatformColors> platformDependentColors;

	[SerializeField]
	private SpriteRenderer slimeTrail_dark;

	[SerializeField]
	private SpriteRenderer slimeTrail_medium;

	[SerializeField]
	private SpriteRenderer slimeTrail_light;

	private ParticleSystem burrowParticle;

	private ParticleSystem burrowParticle_child;

	private ParticleSystem burrowParticle_childchild;

	private PlayerInfo playerInfo;

	private Player player;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private SpriteAnimator animator;

	private DPhysicsBox hurtbox;

	private HitboxCombo hitboxCombo;

	public ParticleSystem dustCloudParticlePrefab;

	public AnimationData animData;

	public Vec2 drillOffset;

	public Vec2 drillHitbox;

	private bool isDrilling;

	private static PhysicsParent[] collisionBuffer = new PhysicsParent[1];

	public LayerMask drillables;

	private bool isUnderground;

	private bool stuckInGround;

	private Fix timeUnderground;

	public Fix gravityStr;

	public Fix drillstr;

	public Fix rotationSpeed;

	public Fix rotationSpeedAir;

	public Fix leaveGroundSpeedMultiplier = Fix.One;

	public Fix EnterGroundSpeedMultiplier = Fix.One;

	public AnimationCurveFixed SpeedToRotationSpeed01;

	public Fix minSpeedBeforeDustCloud;

	public Fix minSpeedBeforeDustCloudOnEntry;

	public float particleOffsetOnEntry;

	public Vec2 onEnterOffset;

	public Fix minUndergroundSpeed;

	private PlatformType currentPlatformType;

	private StickyRoundedRectangle currentPlatform;

	private Fix timePassed;

	public Fix keepStrongGravitySeconds;

	public Fix strongGravity;

	public Fix maxEarlyFallSpeed;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		animator = GetComponent<SpriteAnimator>();
		hurtbox = GetComponent<DPhysicsBox>();
		hitboxCombo = GetComponent<HitboxCombo>();
		burrowParticle = UnityEngine.Object.Instantiate(particleSystemPrefab, particleSystemPrefab.transform.position, Quaternion.identity);
		burrowParticle_child = burrowParticle.transform.GetChild(0).GetComponent<ParticleSystem>();
		burrowParticle_childchild = burrowParticle_child.transform.GetChild(0).GetComponent<ParticleSystem>();
	}

	public void ExitAbility(AbilityExitInfo info)
	{
		hitboxCombo.SetActiveHitboxes(active: false);
		burrowParticle?.Stop();
		info.selfImposedVelocity = body.selfImposedVelocity;
		info.externalVelocity = body.externalVelocity;
		info.isFacingRight = Vec2.Dot(body.Velocity, Vec2.right) >= 0L;
		ability.ExitAbility(info);
	}

	public override void Init()
	{
	}

	private void Update()
	{
		if (burrowParticle != null)
		{
			burrowParticle.transform.position = base.transform.position + base.transform.rotation * particleSystemPrefab.transform.position * (float)player.Scale;
			burrowParticle.transform.rotation = base.transform.rotation;
		}
		slimeTrail_dark.enabled = isUnderground;
		slimeTrail_medium.enabled = isUnderground;
		slimeTrail_light.enabled = isUnderground;
		if (!GameTime.IsTimeStopped() || player.isProtectedFromTimeStop)
		{
			if (isUnderground)
			{
				AudioManager.Get().PlayOrContinueLoop("drill_underground_loop");
			}
			else if (isDrilling)
			{
				AudioManager.Get().PlayOrContinueLoop("drill_loop");
			}
		}
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		body.rotation = playerInfo.rotation;
		AudioManager.Get().Play("drill_start");
		animator.beginAnimThenDoAction(animData.GetAnimation("enter"), startDrill);
		isDrilling = false;
		timePassed = Fix.Zero;
		isUnderground = false;
		body.externalVelocity = playerInfo.externalVelocity;
		body.selfImposedVelocity = playerInfo.selfImposedVelocity;
		body.position = playerInfo.position + Vec2.ComplexMul(onEnterOffset * player.Scale, Vec2.MulByNegI(playerInfo.upVector));
		hurtbox.UpdatePhysicsPositions();
		base.transform.position = (Vector3)body.position;
		hitboxCombo.SpawnHitboxesIfNotYetSpawned(playerInfo.playerId);
		hitboxCombo.SetActiveHitboxes(active: false);
		hitboxCombo.UpdateHitBoxPositionsAndScale();
		hitboxCombo.SyncPhysicsPosition();
	}

	private void OnDrawGizmos()
	{
		float num = ((player == null) ? 1f : ((float)player.Scale));
		Gizmos.DrawWireCube(base.transform.position + (Vector3)drillOffset, (Vector3)drillHitbox * 2f * num);
		if (isUnderground)
		{
			Vec2 externalVelocity = body.externalVelocity;
			UnityEngine.Debug.DrawLine(base.transform.position, base.transform.position + (Vector3)externalVelocity, UnityEngine.Color.magenta);
		}
	}

	private void startDrill()
	{
		animator.beginAnim(animData.GetAnimation("loop"), null);
		isDrilling = true;
		hitboxCombo.SetActiveHitboxes(active: true);
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
		if (burrowParticle != null)
		{
			burrowParticle.transform.localScale *= (float)scaleMultiplier;
			burrowParticle_child.transform.localScale *= (float)scaleMultiplier;
			burrowParticle_childchild.transform.localScale *= (float)scaleMultiplier;
		}
	}

	private void spawnDustCloud(Vector3 pos, Vector3 normal)
	{
		ParticleSystem particleSystem = UnityEngine.Object.Instantiate(dustCloudParticlePrefab, base.transform.position, base.transform.rotation);
		particleSystem.transform.position = pos;
		particleSystem.transform.up = normal;
		particleSystem.transform.localScale = particleSystem.transform.localScale * (float)player.Scale;
		particleSystem.transform.GetChild(0).localScale = particleSystem.transform.GetChild(0).localScale * (float)player.Scale;
		particleSystem.transform.GetChild(0).GetChild(0).localScale = particleSystem.transform.GetChild(0).GetChild(0).localScale * (float)player.Scale;
		for (int i = 0; i < platformDependentColors.Count; i++)
		{
			if (currentPlatformType == PlatformType.slime && currentPlatform != null && !currentPlatform.IsDestroyed)
			{
				UnityEngine.Color color = currentPlatform.GetSpriteRenderer().color;
				ParticleSystem.MainModule main = particleSystem.main;
				main.startColor = color;
				ParticleSystem component = particleSystem.transform.GetChild(0).GetComponent<ParticleSystem>();
				ParticleSystem.MainModule main2 = component.main;
				main2.startColor = UnityEngine.Color.Lerp(color, UnityEngine.Color.black, 0.4f);
				ParticleSystem.MainModule main3 = component.transform.GetChild(0).GetComponent<ParticleSystem>().main;
				main3.startColor = color;
			}
			else if (platformDependentColors[i].type == currentPlatformType)
			{
				ParticleSystem.MainModule main4 = particleSystem.main;
				main4.startColor = platformDependentColors[i].light;
				ParticleSystem component2 = particleSystem.transform.GetChild(0).GetComponent<ParticleSystem>();
				ParticleSystem.MainModule main5 = component2.main;
				main5.startColor = platformDependentColors[i].dark;
				ParticleSystem.MainModule main6 = component2.transform.GetChild(0).GetComponent<ParticleSystem>().main;
				main6.startColor = platformDependentColors[i].light;
				break;
			}
		}
	}

	private void OnEnable()
	{
		if (isUnderground && isDrilling && burrowParticle != null)
		{
			burrowParticle.gameObject.SetActive(value: true);
			burrowParticle.Play();
		}
	}

	private void OnDestroy()
	{
		if (burrowParticle != null)
		{
			ParticleSystem.MainModule main = burrowParticle.main;
			main.stopAction = ParticleSystemStopAction.Destroy;
			burrowParticle.Play();
			burrowParticle.Stop();
		}
	}

	private void OnDisable()
	{
		if (burrowParticle != null)
		{
			burrowParticle.Play();
			burrowParticle.Stop();
		}
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		SimDeltaTime = GameTime.FixedDeltaTime(ability.GetPlayerId(), SimDeltaTime);
		if (!base.gameObject.activeSelf)
		{
			return;
		}
		if (!hitboxCombo.AreHitboxesActive() && isDrilling)
		{
			hitboxCombo.SetActiveHitboxes(active: true);
		}
		if (SimDeltaTime == Fix.Zero)
		{
			hitboxCombo.UpdateHitBoxPositionsAndScale();
			return;
		}
		timePassed += SimDeltaTime;
		if (timePassed > AchievementHandler.timeInDrillBeforeAcheivementIsAwarded && player.IsLocalPlayer)
		{
			AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.StayInDrillFormFor10Seconds);
		}
		Box b = new Box
		{
			center = body.position + Vec2.ComplexMul(drillOffset * player.Scale, body.right),
			right = body.right * drillHitbox.x * player.Scale,
			up = body.up * drillHitbox.y * player.Scale,
			inverseExtents = new Vec2(Fix.One / (drillHitbox.x * player.Scale), Fix.One / (drillHitbox.y * player.Scale)),
			layer = LayerMask.NameToLayer("Player")
		};
		int num = 0;
		stuckInGround = false;
		if (isDrilling)
		{
			num = DetPhysics.Get().CollideBox(b, ref collisionBuffer, drillables);
		}
		else
		{
			num = DetPhysics.Get().CollideBox(b, ref collisionBuffer, drillables);
			if (num > 0)
			{
				stuckInGround = true;
			}
		}
		if (num > 0)
		{
			StickyRoundedRectangle stickyRoundedRectangle = collisionBuffer[0].fixTrans?.GetComponent<StickyRoundedRectangle>();
			if (stickyRoundedRectangle != null)
			{
				currentPlatform = stickyRoundedRectangle;
				currentPlatformType = stickyRoundedRectangle.platformType;
			}
		}
		player.CustomAimAbilityPosition = body.position;
		Vec2 vec = player.AimVector();
		if (vec != Vec2.zero)
		{
			Fix fix = SpeedToRotationSpeed01.Evaluate(Vec2.Magnitude(body.selfImposedVelocity));
			Fix angularIncrement = (isUnderground ? (rotationSpeedAir * fix * SimDeltaTime) : (rotationSpeedAir * SimDeltaTime));
			Vec2 vec2 = Vec2.ApproachNormalizedVector(-body.up, vec, angularIncrement);
			body.up = -vec2;
		}
		if (stuckInGround)
		{
			body.selfImposedVelocity = Vec2.zero;
		}
		bool flag = false;
		if (num > 0 && !stuckInGround)
		{
			bool num2 = isUnderground;
			isUnderground = true;
			if (!num2 && isUnderground)
			{
				if (collisionBuffer[0].fixTrans != null)
				{
					StickyRoundedRectangle stickyRoundedRectangle2 = currentPlatform;
					if (stickyRoundedRectangle2 != null && Vec2.Dot(stickyRoundedRectangle2.currentNormal(body), body.up) <= 0L)
					{
						exitAbility(useOffset: false);
						return;
					}
				}
				burrowParticle?.Play();
				if (Vec2.SqrMagnitude(body.selfImposedVelocity) < minUndergroundSpeed * minUndergroundSpeed)
				{
					body.selfImposedVelocity = Vec2.NormalizedSafe(body.selfImposedVelocity) * minUndergroundSpeed;
				}
				body.selfImposedVelocity *= EnterGroundSpeedMultiplier;
				body.externalVelocity = Vec2.zero;
				if (Vec2.SqrMagnitude(body.selfImposedVelocity) > minSpeedBeforeDustCloudOnEntry)
				{
					Vector3 normal = -base.transform.up;
					Vector3 pos = base.transform.position - base.transform.up * (dustCloudParticlePrefab.transform.position.y + particleOffsetOnEntry);
					spawnDustCloud(pos, normal);
					AudioManager.Get().Play("drill_underground_enter");
					AudioManager.Get().Play("debris");
				}
			}
			timeUnderground += SimDeltaTime;
		}
		else
		{
			if (isUnderground)
			{
				body.selfImposedVelocity *= leaveGroundSpeedMultiplier;
				if (Vec2.SqrMagnitude(body.selfImposedVelocity) > minSpeedBeforeDustCloud)
				{
					Vector3 up = base.transform.up;
					Vector3 pos2 = base.transform.position + base.transform.up * (dustCloudParticlePrefab.transform.position.y * (float)player.Scale);
					spawnDustCloud(pos2, up);
					AudioManager.Get().Play("drill_underground_exit");
					AudioManager.Get().Play("debris");
				}
				flag = true;
			}
			burrowParticle?.Stop();
			isUnderground = false;
		}
		if (isUnderground)
		{
			body.selfImposedVelocity = -body.up * Vec2.Magnitude(body.selfImposedVelocity);
			body.selfImposedVelocity += -body.up * drillstr * SimDeltaTime;
		}
		else if (body.ropeBody == null || !body.ropeBody.enabled)
		{
			if (timePassed < keepStrongGravitySeconds && body.selfImposedVelocity.y < maxEarlyFallSpeed)
			{
				body.selfImposedVelocity += Vec2.down * strongGravity * SimDeltaTime;
			}
			else
			{
				body.selfImposedVelocity += Vec2.down * gravityStr * SimDeltaTime;
			}
		}
		if (num > 0 && currentPlatform != null)
		{
			StickyRoundedRectangle stickyRoundedRectangle3 = currentPlatform;
			body.position += stickyRoundedRectangle3.VelocityAtPos(body.position) * SimDeltaTime;
			if (burrowParticle != null)
			{
				for (int i = 0; i < platformDependentColors.Count; i++)
				{
					if (stickyRoundedRectangle3.platformType == platformDependentColors[i].type)
					{
						slimeTrail_dark.color = platformDependentColors[i].dark;
						slimeTrail_medium.color = platformDependentColors[i].medium;
						slimeTrail_light.color = platformDependentColors[i].light;
						ParticleSystem.MainModule main = burrowParticle.main;
						main.startColor = platformDependentColors[i].light;
						ParticleSystem.MainModule main2 = burrowParticle_child.main;
						main2.startColor = platformDependentColors[i].light;
						ParticleSystem.MainModule main3 = burrowParticle_childchild.main;
						UnityEngine.Color light = platformDependentColors[i].light;
						light.a = main3.startColor.color.a;
						main3.startColor = light;
						break;
					}
					if (stickyRoundedRectangle3.platformType == PlatformType.slime)
					{
						slimeTrail_light.color = stickyRoundedRectangle3.GetSpriteRenderer().color;
						slimeTrail_medium.color = UnityEngine.Color.Lerp(slimeTrail_light.color, UnityEngine.Color.black, 0.4f);
						slimeTrail_dark.color = UnityEngine.Color.Lerp(slimeTrail_light.color, UnityEngine.Color.black, 0.8f);
						ParticleSystem.MainModule main4 = burrowParticle.main;
						main4.startColor = slimeTrail_light.color;
						ParticleSystem.MainModule main5 = burrowParticle_child.main;
						main5.startColor = slimeTrail_light.color;
						ParticleSystem.MainModule main6 = burrowParticle_childchild.main;
						UnityEngine.Color color = slimeTrail_medium.color;
						color.a = main6.startColor.color.a;
						main6.startColor = color;
						break;
					}
				}
			}
		}
		if (body.ropeBody != null && body.ropeBody.enabled && isUnderground)
		{
			body.AttachRope(null, body.topAttachment);
		}
		if (!player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012) && !isUnderground && isDrilling)
		{
			if (flag)
			{
				exitAbility(useOffset: false);
				return;
			}
			isDrilling = false;
			AudioManager.Get().Play("drill_end");
			animator.beginAnimThenDoAction(animData.GetAnimation("exit"), delegate
			{
				exitAbility(useOffset: true);
			});
		}
		hitboxCombo.UpdateHitBoxPositionsAndScale();
	}

	private void exitAbility(bool useOffset)
	{
		AbilityExitInfo info = new AbilityExitInfo
		{
			position = body.position
		};
		if (useOffset)
		{
			info.position -= Vec2.ComplexMul(onEnterOffset * player.Scale, Vec2.MulByNegI(body.up));
		}
		ExitAbility(info);
	}
}
public class DuplicatePlatformEffect : MonoUpdatable
{
	private SpriteRenderer flashSpriteRen;

	public SpriteRenderer platformShaderEffectPrefab;

	private SpriteRenderer platformShaderEffect;

	public SpriteRenderer resizablePlatformShaderEffectPrefab;

	public ParticleSystem platformSpawnInEffectPrefab;

	private bool hasSpawnedPlatformEffect;

	public float platformSpawnFlashScale;

	private FixTransform fixTrans;

	private StickyRoundedRectangle srr;

	private Fix srrScaleOnInitialize;

	private Fix duration;

	private Fix srrRotationOnInitialize;

	private Fix effectScale;

	private bool hasBeenInitialized;

	private Vec2 newPlatformPos;

	public AnimationCurve flashAlphaAnim;

	public float flashScale = 0.1f;

	private bool resizable;

	private bool isBoulder;

	private int hierarchyNumberOfGunTransform;

	private Vec2 cloneDir;

	private Vec2 origUp;

	private Vec2 origRight;

	private Vec2 origStartPos;

	private Quaternion origRotation;

	public Fix platformOverlapForce;

	private static PhysicsParent[] hitBuffer = new PhysicsParent[10];

	private Vector3 effectShake;

	private bool srrStillAlive = true;

	private Fix srrDestroyedTimestamp;

	public Fix scaleLossSpeed = (Fix)0.2;

	private ParticleSystem spawnInEffect;

	public AnimationCurve alphaAnim;

	public AnimationCurve progressAnim01;

	private Vector3 effectOrigScale;

	private Vector3 effectOrigPos;

	private Fix time;

	private Vec2 originalExtents;

	private Fix originalRadius;

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
		flashSpriteRen = GetComponent<SpriteRenderer>();
	}

	private void ScaleEffect(Fix newScale)
	{
		Fix scale = srr.rr.Scale;
		DPhysicsRoundedRect dPhysicsRoundedRect = srr.DPhysicsShape();
		dPhysicsRoundedRect.Scale = newScale;
		srrScaleOnInitialize = newScale;
		platformShaderEffect.transform.localScale = srr.transform.localScale;
		effectOrigScale = srr.transform.localScale;
		originalExtents = srr.rr.CalcExtents();
		originalRadius = srr.rr.radius;
		newPlatformPos = ShootDuplicator.PlatformSpawnPos(cloneDir, origRight, origUp, origStartPos, srr);
		fixTrans.position = origStartPos;
		platformShaderEffect.transform.position = (Vector3)origStartPos;
		Vector2 vector = (Vector2)(newPlatformPos - fixTrans.position) * platformShaderEffect.sprite.pixelsPerUnit;
		Tools.Debug_DrawPos_fu((Vec2)vector, UnityEngine.Color.yellow);
		vector = Quaternion.Inverse(origRotation) * vector;
		vector.x /= platformShaderEffect.sprite.texture.width;
		vector.y /= platformShaderEffect.sprite.texture.height;
		Vector2 normalized = vector.normalized;
		float value = vector.magnitude / (float)srr.DPhysicsShape().Scale;
		platformShaderEffect.transform.localScale = srr.transform.localScale;
		effectOrigScale = srr.transform.localScale;
		DPhysicsRoundedRect dPhysicsRoundedRect2 = srr.DPhysicsShape();
		float x = (float)(dPhysicsRoundedRect2.CalcExtents().x + dPhysicsRoundedRect2.radius) * flashScale;
		float y = (float)(dPhysicsRoundedRect2.CalcExtents().y + dPhysicsRoundedRect2.radius) * flashScale;
		base.transform.localScale = new Vector3(x, y, 1f);
		if (resizable)
		{
			platformShaderEffect.transform.localScale = srr.transform.localScale;
			platformShaderEffect.material.SetFloat("_Scale", srr.transform.localScale.x);
			platformShaderEffect.material.SetFloat("_BevelRadius", (float)srr.rr.radius * 2f);
			platformShaderEffect.material.SetFloat("_RHeight", (float)originalExtents.y * 2f);
			platformShaderEffect.material.SetFloat("_RWidth", (float)originalExtents.x * 2f);
			platformShaderEffect.color = srr.GetSpriteRenderer().color;
			effectOrigScale = srr.transform.localScale;
			DPhysicsRoundedRect dPhysicsRoundedRect3 = srr.DPhysicsShape();
			float x2 = (float)(dPhysicsRoundedRect3.CalcExtents().x + dPhysicsRoundedRect3.radius) * flashScale;
			float y2 = (float)(dPhysicsRoundedRect3.CalcExtents().y + dPhysicsRoundedRect3.radius) * flashScale;
			base.transform.localScale = new Vector3(x2, y2, 1f);
			fixTrans.rotation = dPhysicsRoundedRect3.rotation;
		}
		platformShaderEffect.material.SetVector("_Direction", new Vector4(normalized.x, normalized.y, 0f, 0f));
		platformShaderEffect.material.SetFloat("_UVOffset", value);
		dPhysicsRoundedRect.Scale = scale;
	}

	public void Initialize(StickyRoundedRectangle srr, Vec2 cloneDir, Fix duration, int hierarchyNumberOfGunTransform)
	{
		resizable = srr.CompareTag("ResizablePlatform");
		isBoulder = srr.CompareTag("boulder");
		this.cloneDir = cloneDir;
		origUp = srr.rr.up;
		origRight = srr.rr.right;
		origStartPos = srr.rr.position;
		origRotation = srr.transform.rotation;
		Vec2 vec = ShootDuplicator.PlatformSpawnPos(cloneDir, origRight, origUp, origStartPos, srr);
		hasSpawnedPlatformEffect = false;
		srrStillAlive = true;
		this.srr = srr;
		srr.currentDuplicatePlatformEffect = this;
		this.hierarchyNumberOfGunTransform = hierarchyNumberOfGunTransform;
		DPhysicsRoundedRect dPhysicsRoundedRect = srr.DPhysicsShape();
		fixTrans.position = dPhysicsRoundedRect.position;
		srrScaleOnInitialize = Fix.One;
		srrRotationOnInitialize = dPhysicsRoundedRect.rotation;
		effectScale = dPhysicsRoundedRect.Scale;
		this.duration = duration;
		hasBeenInitialized = true;
		newPlatformPos = vec;
		originalExtents = srr.rr.CalcExtents();
		originalRadius = srr.rr.radius;
		if (resizable)
		{
			platformShaderEffect = UnityEngine.Object.Instantiate(resizablePlatformShaderEffectPrefab, (Vector3)fixTrans.position, srr.transform.rotation);
			platformShaderEffect.transform.localScale = srr.transform.localScale;
			platformShaderEffect.material.SetFloat("_Scale", srr.transform.localScale.x);
			platformShaderEffect.material.SetFloat("_BevelRadius", (float)srr.rr.radius * 2f);
			platformShaderEffect.material.SetFloat("_RHeight", (float)originalExtents.y * 2f);
			platformShaderEffect.material.SetFloat("_RWidth", (float)originalExtents.x * 2f);
			platformShaderEffect.color = srr.GetSpriteRenderer().color;
			effectOrigScale = srr.transform.localScale;
			DPhysicsRoundedRect dPhysicsRoundedRect2 = srr.DPhysicsShape();
			float x = (float)(dPhysicsRoundedRect2.CalcExtents().x + dPhysicsRoundedRect2.radius) * flashScale;
			float y = (float)(dPhysicsRoundedRect2.CalcExtents().y + dPhysicsRoundedRect2.radius) * flashScale;
			base.transform.localScale = new Vector3(x, y, 1f);
			fixTrans.rotation = dPhysicsRoundedRect2.rotation;
		}
		else
		{
			platformShaderEffect = UnityEngine.Object.Instantiate(platformShaderEffectPrefab, (Vector3)fixTrans.position, srr.transform.rotation);
			platformShaderEffect.sprite = srr.GetSpriteRenderer().sprite;
			Vector2 vector = (Vector2)(newPlatformPos - fixTrans.position) * platformShaderEffect.sprite.pixelsPerUnit;
			vector = Quaternion.Inverse(srr.transform.rotation) * vector;
			vector.x /= platformShaderEffect.sprite.texture.width;
			vector.y /= platformShaderEffect.sprite.texture.height;
			Vector2 normalized = vector.normalized;
			float value = vector.magnitude / (float)srr.DPhysicsShape().Scale;
			platformShaderEffect.transform.localScale = srr.transform.localScale;
			effectOrigScale = srr.transform.localScale;
			DPhysicsRoundedRect dPhysicsRoundedRect3 = srr.DPhysicsShape();
			float x2 = (float)(dPhysicsRoundedRect3.CalcExtents().x + dPhysicsRoundedRect3.radius) * flashScale;
			float y2 = (float)(dPhysicsRoundedRect3.CalcExtents().y + dPhysicsRoundedRect3.radius) * flashScale;
			base.transform.localScale = new Vector3(x2, y2, 1f);
			fixTrans.rotation = dPhysicsRoundedRect3.rotation;
			Tools.Debug_DrawPos((Vec2)normalized, UnityEngine.Color.blue, 10f);
			platformShaderEffect.material.SetVector("_Direction", new Vector4(normalized.x, normalized.y, 0f, 0f));
			platformShaderEffect.material.SetFloat("_UVOffset", value);
		}
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (GameTime.IsTimeStopped() || !hasBeenInitialized)
		{
			return;
		}
		if (platformShaderEffect != null && !platformShaderEffect.enabled)
		{
			platformShaderEffect.enabled = true;
		}
		if ((srr == null || srr.IsDestroyed) && srrStillAlive)
		{
			srrStillAlive = false;
			srrDestroyedTimestamp = time;
		}
		if (srr != null && !srr.IsDestroyed)
		{
			effectScale = Fix.Min(effectScale, Fix.Lerp(effectScale, Fix.One, scaleLossSpeed));
			ScaleEffect(effectScale);
			DPhysicsRoundedRect dPhysicsRoundedRect = srr.DPhysicsShape();
			dPhysicsRoundedRect.Scale = Fix.Min(dPhysicsRoundedRect.Scale, Fix.Lerp(dPhysicsRoundedRect.Scale, Fix.One, scaleLossSpeed));
		}
		time += SimDeltaTime;
		float num = progressAnim01.Evaluate((float)time);
		UnityEngine.Color color = flashSpriteRen.color;
		color.a = flashAlphaAnim.Evaluate((float)time);
		float num2 = 1f;
		if (!srrStillAlive)
		{
			num2 = 1f - (float)(time - srrDestroyedTimestamp) / (float)(duration - srrDestroyedTimestamp);
			color.a *= num2;
		}
		flashSpriteRen.color = color;
		if (platformShaderEffect != null)
		{
			UnityEngine.Color color2 = platformShaderEffect.color;
			if (resizable)
			{
				platformShaderEffect.transform.position = Vector3.Lerp(fixTrans.transform.position, (Vector3)newPlatformPos, num);
			}
			else
			{
				platformShaderEffect.material.SetFloat("_Progress01", num);
			}
			color2.a = alphaAnim.Evaluate(num) * num2;
			platformShaderEffect.color = color2;
			if (time < duration)
			{
				platformShaderEffect.transform.position -= effectShake;
				effectShake = num * (Vector3)UnityEngine.Random.insideUnitCircle * 0.3f;
				platformShaderEffect.transform.position += effectShake;
			}
		}
		if (spawnInEffect != null)
		{
			spawnInEffect.transform.position = (Vector3)newPlatformPos;
		}
		if (srr != null && !srr.IsDestroyed)
		{
			RoundedRect rr = srr.DPhysicsShape().AsRoundedRect();
			rr.radius += Fix.One;
			int num3 = DetPhysics.Get().roundedRectCastRoundedRects(newPlatformPos, rr, ref hitBuffer);
			for (int i = 0; i < num3; i++)
			{
				Vec2 vec = Vec2.NormalizedSafe(hitBuffer[i].fixTrans.position - srr.DPhysicsShape().position);
				BoplBody component = hitBuffer[i].fixTrans.GetComponent<BoplBody>();
				if (component != null)
				{
					component.AddForce(vec * platformOverlapForce / ((component.InverseMass == 0L) ? Fix.One : component.InverseMass));
				}
				hitBuffer[i].fixTrans.GetComponent<AnimateVelocity>()?.ActAsFloatingPlatformForAFrame();
				Tools.Debug_DrawLine_fu(hitBuffer[i].fixTrans.position, hitBuffer[i].fixTrans.position + vec * platformOverlapForce, UnityEngine.Color.yellow);
			}
			DebugRR();
		}
		if (time > duration)
		{
			if (srr != null && !srr.IsDestroyed && !resizable)
			{
				Camera camera = null;
				RenderTexture targetTexture = null;
				if (!isBoulder)
				{
					camera = srr.transform.GetChild(0).GetComponent<PlatformSlimeTrailCamera>().GetComponent<Camera>();
					targetTexture = camera.targetTexture;
					camera.targetTexture = null;
				}
				DPhysicsRoundedRect dPhysicsRoundedRect2 = srr.DPhysicsShape();
				dPhysicsRoundedRect2.manuallyCallInit = true;
				List<Transform> list = new List<Transform>();
				Transform transform = srr.gameObject.transform;
				for (int j = 0; j < transform.childCount; j++)
				{
					Transform child = transform.GetChild(j);
					if (child.gameObject.layer == LayerMask.NameToLayer("LethalTerrain") || child.gameObject.layer == LayerMask.NameToLayer("NonLethalTerrain"))
					{
						list.Add(child);
					}
				}
				for (int k = 0; k < list.Count; k++)
				{
					list[k].parent = null;
				}
				DetPhysics.Get().DeleteObjectFromDuplicateListWithId(hierarchyNumberOfGunTransform, 20);
				GameObject gameObject = ShootDuplicator.DuplicateObject(newPlatformPos, srr.gameObject, 1800, allowOnlyASingleCopyWithInifinteLifespan: true, hierarchyNumberOfGunTransform);
				for (int l = 0; l < list.Count; l++)
				{
					list[l].parent = transform;
				}
				dPhysicsRoundedRect2.manuallyCallInit = false;
				if (!isBoulder)
				{
					camera.targetTexture = targetTexture;
				}
				if (!isBoulder)
				{
					Camera component2 = gameObject.transform.GetChild(0).GetComponent<PlatformSlimeTrailCamera>().GetComponent<Camera>();
					Graphics.CopyTexture(camera.targetTexture, component2.targetTexture);
				}
				StickyRoundedRectangle component3 = gameObject.GetComponent<StickyRoundedRectangle>();
				component3.GetGroundBody();
				DPhysicsRoundedRect dPhysicsRoundedRect3 = component3.DPhysicsShape();
				dPhysicsRoundedRect3.radius = originalRadius / srrScaleOnInitialize;
				dPhysicsRoundedRect3.SetExtents(originalExtents / srrScaleOnInitialize);
				dPhysicsRoundedRect3.Initialize();
				dPhysicsRoundedRect3.Scale = srrScaleOnInitialize;
				dPhysicsRoundedRect3.rotation = srrRotationOnInitialize;
			}
			else if (srr != null && !srr.IsDestroyed && resizable)
			{
				DPhysicsRoundedRect dPhysicsRoundedRect4 = srr.DPhysicsShape();
				dPhysicsRoundedRect4.manuallyCallInit = true;
				List<Transform> list2 = new List<Transform>();
				Transform transform2 = srr.gameObject.transform;
				for (int m = 0; m < transform2.childCount; m++)
				{
					Transform child2 = transform2.GetChild(m);
					if (child2.gameObject.layer == LayerMask.NameToLayer("LethalTerrain") || child2.gameObject.layer == LayerMask.NameToLayer("NonLethalTerrain"))
					{
						list2.Add(child2);
					}
				}
				for (int n = 0; n < list2.Count; n++)
				{
					list2[n].parent = null;
				}
				DetPhysics.Get().DeleteObjectFromDuplicateListWithId(hierarchyNumberOfGunTransform, 20);
				GameObject gameObject2 = ShootDuplicator.DuplicateObject(newPlatformPos, srr.gameObject, 1800, allowOnlyASingleCopyWithInifinteLifespan: true, hierarchyNumberOfGunTransform);
				for (int num4 = 0; num4 < list2.Count; num4++)
				{
					list2[num4].parent = transform2;
				}
				dPhysicsRoundedRect4.manuallyCallInit = false;
				StickyRoundedRectangle component4 = gameObject2.GetComponent<StickyRoundedRectangle>();
				BoplBody groundBody = component4.GetGroundBody();
				DPhysicsRoundedRect dPhysicsRoundedRect5 = component4.DPhysicsShape();
				FixTransform component5 = groundBody.GetComponent<FixTransform>();
				component5.startScale = effectOrigScale;
				dPhysicsRoundedRect5.Initialize();
				dPhysicsRoundedRect5.Scale = srrScaleOnInitialize;
				dPhysicsRoundedRect5.rotation = srrRotationOnInitialize;
				component5.SyncTransform();
				FollowTransform followTransform = spawnInEffect.gameObject.AddComponent<FollowTransform>();
				followTransform.Leader = gameObject2.transform;
				followTransform.DestroyWhenLeaderIsDestroyed = false;
				followTransform.transform.position = Vector3.zero;
				followTransform.Init();
				dPhysicsRoundedRect5.GetComponent<ResizablePlatform>().ResizePlatform(originalExtents.y, originalExtents.x, originalRadius, resizeChildren: false);
			}
			if (spawnInEffect != null)
			{
				spawnInEffect.transform.position = (Vector3)newPlatformPos;
			}
			SelfDestruct();
		}
		else if (!hasSpawnedPlatformEffect && time > duration - (Fix)0.35f && srr != null && !srr.IsDestroyed)
		{
			AudioManager.Get().Play("duplicatePlatform");
			hasSpawnedPlatformEffect = true;
			if (resizable)
			{
				SpawnOnSpawnEffectResizable();
			}
			else
			{
				SpawnOnSpawnEffect();
			}
		}
	}

	public void SelfDestruct()
	{
		Updater.DestroyFix(base.gameObject);
		UnityEngine.Object.Destroy(platformShaderEffect.gameObject);
	}

	private void SpawnOnSpawnEffect()
	{
		spawnInEffect = UnityEngine.Object.Instantiate(platformSpawnInEffectPrefab, (Vector3)newPlatformPos, srr.transform.rotation);
		spawnInEffect.transform.localScale = new Vector3(2.5f * effectOrigScale.x, 2.5f * effectOrigScale.y, 1f);
		ParticleSystem component = spawnInEffect.transform.GetChild(1).GetComponent<ParticleSystem>();
		ParticleSystem.ShapeModule shape = component.shape;
		Vector2 vector = (Vector2)(originalExtents + originalRadius * new Vec2(Fix.One, Fix.One));
		shape.scale = 2f * (new Vector3(vector.x, vector.y, 1f) / spawnInEffect.transform.localScale.x);
		ParticleSystem.EmissionModule emission = component.emission;
		ParticleSystem.Burst burst = emission.GetBurst(0);
		burst.count = Mathf.Sqrt(Mathf.Max(shape.scale.y, shape.scale.x));
		emission.SetBurst(0, burst);
		ParticleSystem.MainModule main = spawnInEffect.transform.GetChild(0).GetComponent<ParticleSystem>().main;
		main.startSizeX = vector.x * platformSpawnFlashScale / effectOrigScale.x;
		main.startSizeY = vector.y * platformSpawnFlashScale / effectOrigScale.y;
		main.startRotation = (0f - spawnInEffect.transform.rotation.eulerAngles.z) * (MathF.PI / 180f);
		spawnInEffect.Play();
	}

	private void SpawnOnSpawnEffectResizable()
	{
		spawnInEffect = UnityEngine.Object.Instantiate(platformSpawnInEffectPrefab, (Vector3)newPlatformPos, srr.transform.rotation);
		spawnInEffect.transform.localScale = new Vector3(1f, 1f, 1f);
		ParticleSystem component = spawnInEffect.transform.GetChild(1).GetComponent<ParticleSystem>();
		ParticleSystem.ShapeModule shape = component.shape;
		Vector2 vector = (Vector2)(srr.DPhysicsShape().CalcExtents() + srr.DPhysicsShape().radius * new Vec2(Fix.One, Fix.One));
		shape.scale = 2f * new Vector3(vector.x, vector.y, 1f);
		ParticleSystem.EmissionModule emission = component.emission;
		ParticleSystem.Burst burst = emission.GetBurst(0);
		burst.count = Mathf.Sqrt(Mathf.Max(shape.scale.y, shape.scale.x));
		emission.SetBurst(0, burst);
		ParticleSystem.MainModule main = component.main;
		main.startSize = main.startSize.constant * 2f;
		ParticleSystem component2 = spawnInEffect.transform.GetChild(0).GetComponent<ParticleSystem>();
		float num = (float)srr.DPhysicsShape().Scale;
		ParticleSystem.MainModule main2 = component2.main;
		main2.startSizeX = num * 50f * vector.x * platformSpawnFlashScale / effectOrigScale.x;
		main2.startSizeY = num * 50f * vector.y * platformSpawnFlashScale / effectOrigScale.y;
		main2.startRotation = (0f - spawnInEffect.transform.rotation.eulerAngles.z) * (MathF.PI / 180f);
		spawnInEffect.Play();
	}

	private void DebugRR()
	{
		if (!(srr == null))
		{
			DPhysicsRoundedRect dPhysicsRoundedRect = srr.DPhysicsShape();
			Fix one = Fix.One;
			Vec2 vec = dPhysicsRoundedRect.CalcExtents() * one;
			Vector3 vector = srr.transform.right * ((float)vec.x + (float)dPhysicsRoundedRect.radius * (float)one);
			Vector3 vector2 = srr.transform.up * ((float)vec.y + (float)dPhysicsRoundedRect.radius * (float)one);
			Vector3 vector3 = srr.transform.right * (float)vec.x;
			Vector3 vector4 = srr.transform.up * (float)vec.y;
			Vector3 vector5 = (Vector3)newPlatformPos;
			Vector3 start = vector5 + vector3 + vector2;
			Vector3 end = vector5 - vector3 + vector2;
			Vector3 start2 = vector5 + vector3 - vector2;
			Vector3 end2 = vector5 - vector3 - vector2;
			UnityEngine.Debug.DrawLine(start, end);
			UnityEngine.Debug.DrawLine(start2, end2);
			start = vector5 + vector + vector4;
			end = vector5 - vector + vector4;
			start2 = vector5 + vector - vector4;
			end2 = vector5 - vector - vector4;
			UnityEngine.Debug.DrawLine(end, end2);
			UnityEngine.Debug.DrawLine(start, start2);
		}
	}
}
public class ErrorHandlingTextDisconnect : MonoBehaviour
{
	private TextMeshProUGUI text;

	private bool setText;

	private static string message;

	private void Awake()
	{
		text = GetComponent<TextMeshProUGUI>();
		setText = true;
	}

	private void Start()
	{
		if (!setText)
		{
			return;
		}
		if (Host.disconnectedPlayerId != -1)
		{
			text.enabled = true;
			text.UpdateFontAsset();
			if (Settings.Get().Hide == 0)
			{
				text.SetText("game stopped: " + Host.disconnectedPlayerName + " was disconnected");
			}
			else
			{
				text.SetText("game stopped: player " + Host.disconnectedPlayerId + " was disconnected");
			}
		}
		else
		{
			text.enabled = false;
		}
		Host.disconnectedPlayerId = -1;
		Host.disconnectedPlayerName = null;
	}

	public static void SetMainMenuLogMessage(string msg)
	{
		message = msg;
	}

	private void Update()
	{
		if (message != null)
		{
			text.enabled = true;
			text.UpdateFontAsset();
			text.SetText(message);
			message = null;
		}
	}
}
public class Fireball : MonoUpdatable, ICollisionCallback
{
	private Vec2 direction = Vec2.right;

	private Vec2 velocity = Vec2.right;

	private int wallLayer;

	private SpriteRenderer spriteRen;

	private DPhysicsCircle hitbox;

	public Fix speed;

	public Fix angularTurnSpeed;

	public Fix undergroundSpeedIncrease;

	private Vec2 turnRotation;

	public Fix sizeIncrease;

	public Fix undergroundSpeed;

	private Fix timeSpentUnderground;

	private bool wasUnderground;

	private bool underground;

	private Vec2 groundPos;

	private Vec2 groundUp;

	public override void Init()
	{
	}

	public void Initialize(Vec2 direction)
	{
		this.direction = direction;
		velocity = speed * direction;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		hitbox = GetComponent<DPhysicsCircle>();
		spriteRen = GetComponent<SpriteRenderer>();
		hitbox.RegisterCollisionCallback(this);
		underground = false;
		turnRotation = new Vec2(angularTurnSpeed);
		wallLayer = LayerMask.NameToLayer("wall");
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (underground)
		{
			spriteRen.color = UnityEngine.Color.blue;
			Vec2.NormalizedSafe(groundPos - hitbox.position);
			hitbox.Scale += sizeIncrease * GameTime.PlayerTimeScale * SimDeltaTime;
			wasUnderground = true;
		}
		else
		{
			timeSpentUnderground = Fix.Zero;
			wasUnderground = false;
		}
		hitbox.position += velocity * GameTime.PlayerTimeScale * SimDeltaTime;
		underground = false;
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (collision.layer == wallLayer)
		{
			underground = true;
			groundPos = collision.colliderPP.fixTrans.position;
			groundUp = collision.colliderPP.fixTrans.up;
		}
	}
}
