public class HeldMagnetParticle : MonoBehaviour
{
	[NonSerialized]
	public ParticleSystem particle;

	[NonSerialized]
	public ParticleSystem particle_child;

	public float particleStopDelay;

	private float timer = -1f;

	private bool isUpdating;

	private void Awake()
	{
		particle = GetComponent<ParticleSystem>();
		particle_child = base.transform.GetChild(0).GetComponent<ParticleSystem>();
		base.enabled = false;
		isUpdating = false;
	}

	public void SetRenderer(SpriteRenderer spriteRen)
	{
		ParticleSystem.ShapeModule shape = particle.shape;
		shape.spriteRenderer = spriteRen;
		ParticleSystem.ShapeModule shape2 = particle_child.shape;
		shape2.spriteRenderer = spriteRen;
	}

	public void DelayedStop()
	{
		if (!base.enabled && particle.isPlaying && !particle.isStopped)
		{
			timer = particleStopDelay;
			base.enabled = true;
			isUpdating = true;
		}
	}

	public void reset()
	{
		timer = -1f;
		base.enabled = false;
		isUpdating = false;
		ParticleSystem.ShapeModule shape = particle.shape;
		shape.enabled = true;
		ParticleSystem.ShapeModule shape2 = particle_child.shape;
		shape2.enabled = true;
		particle.Stop();
		particle_child.Stop();
	}

	public void SetScale(float invScale, float shapeScaleMultiplier)
	{
		ParticleSystem.ShapeModule shape = particle.shape;
		shape.scale = Vector3.one * invScale * shapeScaleMultiplier;
		ParticleSystem.ShapeModule shape2 = particle_child.shape;
		shape2.scale = Vector3.one * invScale * shapeScaleMultiplier;
		ParticleSystem.MainModule main = particle.main;
		main.startSizeX = 2.15f * invScale;
		main.startSizeY = 2.5f * invScale;
		ParticleSystem.MainModule main2 = particle_child.main;
		main2.startSize = 2.5f * invScale;
	}

	public void Update()
	{
		if (particle.shape.spriteRenderer == null)
		{
			ParticleSystem.ShapeModule shape = particle.shape;
			shape.enabled = false;
			ParticleSystem.ShapeModule shape2 = particle_child.shape;
			shape2.enabled = false;
			particle.Stop();
			particle_child.Stop();
			base.enabled = false;
			isUpdating = false;
			timer = -1f;
		}
		if (isUpdating)
		{
			bool num = timer > 0f;
			timer -= Time.deltaTime;
			bool flag = timer > 0f;
			if (num && !flag)
			{
				particle.Stop();
				particle_child.Stop();
				isUpdating = false;
			}
		}
	}
}
