public class HitboxCombo : MonoBehaviour
{
	[Serializable]
	public struct Box
	{
		public Vec2 offset;

		public Vec2 extents;
	}

	public List<Box> hitBoxDefinitions;

	public DPhysicsBox hitboxPrefab;

	private List<DPhysicsBox> physicsBoxes;

	private FixTransform fixtrans;

	private PlayerCollision playerCol;

	public List<DPhysicsBox> HitboxesList()
	{
		return physicsBoxes;
	}

	public void SpawnHitboxesIfNotYetSpawned(int playerId)
	{
		if (physicsBoxes != null)
		{
			if (0 < hitBoxDefinitions.Count)
			{
				playerCol.IgnoreCollider(physicsBoxes[0], PlayerCollision.IgnoreColliderInd.combo0);
			}
			if (1 < hitBoxDefinitions.Count)
			{
				playerCol.IgnoreCollider(physicsBoxes[1], PlayerCollision.IgnoreColliderInd.combo1);
			}
			if (2 < hitBoxDefinitions.Count)
			{
				playerCol.IgnoreCollider(physicsBoxes[2], PlayerCollision.IgnoreColliderInd.combo2);
			}
			return;
		}
		physicsBoxes = new List<DPhysicsBox>();
		for (int i = 0; i < hitBoxDefinitions.Count; i++)
		{
			physicsBoxes.Add(FixTransform.InstantiateFixed(hitboxPrefab, fixtrans.position + hitBoxDefinitions[i].offset, Fix.Zero));
			physicsBoxes[i].SetExtents(hitBoxDefinitions[i].extents);
			physicsBoxes[i].ManualInit();
		}
		if (0 < hitBoxDefinitions.Count)
		{
			playerCol.IgnoreCollider(physicsBoxes[0], PlayerCollision.IgnoreColliderInd.combo0);
		}
		if (1 < hitBoxDefinitions.Count)
		{
			playerCol.IgnoreCollider(physicsBoxes[1], PlayerCollision.IgnoreColliderInd.combo1);
		}
		if (2 < hitBoxDefinitions.Count)
		{
			playerCol.IgnoreCollider(physicsBoxes[2], PlayerCollision.IgnoreColliderInd.combo2);
		}
		for (int j = 0; j < physicsBoxes.Count; j++)
		{
			physicsBoxes[j].GetComponent<Hitbox>().Initialize(this, playerId);
		}
	}

	public bool AreHitboxesActive()
	{
		return physicsBoxes[0].gameObject.activeSelf;
	}

	public void SetActiveHitboxes(bool active)
	{
		for (int i = 0; i < physicsBoxes.Count; i++)
		{
			physicsBoxes[i].gameObject.SetActive(active);
		}
	}

	public void UpdateHitBoxPositionsAndScale()
	{
		for (int i = 0; i < physicsBoxes.Count; i++)
		{
			physicsBoxes[i].position = fixtrans.position + Vec2.ComplexMul(hitBoxDefinitions[i].offset * fixtrans.Scale, fixtrans.right);
			physicsBoxes[i].rotation = fixtrans.rotation;
			if (physicsBoxes[i].Scale != fixtrans.Scale)
			{
				physicsBoxes[i].Scale = fixtrans.Scale;
			}
		}
	}

	public void SyncPhysicsPosition()
	{
		for (int i = 0; i < physicsBoxes.Count; i++)
		{
			physicsBoxes[i].UpdatePhysicsPositions();
		}
	}

	private void OnDrawGizmos()
	{
		float num = ((fixtrans == null) ? 1f : ((float)fixtrans.Scale));
		for (int i = 0; i < hitBoxDefinitions.Count; i++)
		{
			Vector3 vector = base.transform.right * (float)hitBoxDefinitions[i].extents.x * num;
			Vector3 vector2 = base.transform.up * (float)hitBoxDefinitions[i].extents.y * num;
			Vector3 vector3 = base.transform.position + base.transform.rotation * ((Vector3)hitBoxDefinitions[i].offset * num);
			Vector3 vector4 = vector3 + vector + vector2;
			Vector3 vector5 = vector3 - vector + vector2;
			Vector3 vector6 = vector3 + vector - vector2;
			Vector3 to = vector3 - vector - vector2;
			Gizmos.DrawLine(vector4, vector5);
			Gizmos.DrawLine(vector6, to);
			Gizmos.DrawLine(vector5, to);
			Gizmos.DrawLine(vector4, vector6);
		}
	}

	private void Awake()
	{
		fixtrans = GetComponent<FixTransform>();
		playerCol = GetComponent<PlayerCollision>();
	}
}
public class HookshotInstant : MonoUpdatable
{
	public Rope ropePrefab;

	public RopeHook hookPrefab;

	private FixTransform fixTrans;

	private InstantAbility instantAbility;

	private PlayerInfo playerInfo;

	public LayerMask layermask;

	public static int player1Ropes;

	public Fix hookSpawnOffset;

	public Fix hookSpeed;

	public int framesBetweenReelIns;

	private int framesSinceReelIn;

	private bool hasHadCooldownSet;

	public Fix startingSegmentSeparation;

	public Fix reeledInSegmentSeparation;

	public Fix ReelInSpeed;

	public Fix minimumSqrdRopeLength;

	public Fix separationBeforeReelinDeletion;

	public Fix cooldown;

	private int tickWhenUsedLast;

	private uint firedRopeNumber;

	private RopeBody ropeBody;

	private void Awake()
	{
		fixTrans = GetComponent<FixTransform>();
		instantAbility = GetComponent<InstantAbility>();
	}

	public void UpdateCooldowns(PlayerBody body)
	{
		if (!hasHadCooldownSet && (body.ropeBody == null || !body.ropeBody.enabled || body.ropeBody.ownerId != instantAbility.GetPlayerId() || ropeBody == null || ropeBody.number != body.ropeBody.number))
		{
			hasHadCooldownSet = true;
			instantAbility?.SetCoolDown(cooldown);
		}
		else if (!hasHadCooldownSet)
		{
			instantAbility?.SetCoolDown(Fix.Zero);
		}
	}

	private bool ReelInSegment(RopeBody ropeBody, bool topAttachment)
	{
		ropeBody.segmentSeparation -= ReelInSpeed;
		if (ropeBody.segmentSeparation < reeledInSegmentSeparation)
		{
			ropeBody.segmentSeparation = reeledInSegmentSeparation;
			return true;
		}
		return false;
	}

	public void UseAbility()
	{
		playerInfo = instantAbility.playerInfo;
		if (ropeBody != null && playerInfo.ropeBody != null && ropeBody.enabled && playerInfo.ropeBody.enabled && playerInfo.ropeBody.number == firedRopeNumber && ropeBody.ownerId == playerInfo.playerId)
		{
			if (tickWhenUsedLast + 60 < Updater.SimulationTicks)
			{
				AudioManager.Get().Play("reelInFire");
			}
			tickWhenUsedLast = Updater.SimulationTicks;
			int num = (playerInfo.topAttachment ? (ropeBody.segmentCount - 1) : 0);
			framesSinceReelIn++;
			if (framesSinceReelIn < framesBetweenReelIns)
			{
				return;
			}
			ropeBody.segmentSeparation = Fix.Max(ropeBody.segmentSeparation - ReelInSpeed / (Fix)ropeBody.segmentCount, reeledInSegmentSeparation);
			bool flag = true;
			if (ropeBody.segmentSeparation < separationBeforeReelinDeletion)
			{
				flag = ropeBody.ReelInSegment(8);
			}
			if (!flag)
			{
				Vec2 vec = Vec2.NormalizedSafe(ropeBody.segment[num] - playerInfo.slimeController.body.position) * (Fix)0.1;
				if (!playerInfo.isGrounded)
				{
					playerInfo.slimeController.body.position = ropeBody.segment[num] + vec;
				}
				ropeBody.enabled = false;
				ropeBody.disabledThisFrame = true;
				ropeBody = null;
				AudioManager.Get().Play("hookshotLetGo");
			}
			framesSinceReelIn = 0;
		}
		else
		{
			FireHook();
		}
	}

	private void FireHook()
	{
		hasHadCooldownSet = false;
		Player player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		AudioManager.Get().Play("hookshotFire");
		if (playerInfo.useRopeOnOtherPlayer)
		{
			Vec2 vec = playerInfo.playerToUseRopeOn.fixTrans.position + player.AimVector() * hookSpawnOffset;
			Rope rope = FixTransform.InstantiateFixed(ropePrefab, vec);
			int playerId = playerInfo.playerToUseRopeOn.fixTrans.GetComponent<IPlayerIdHolder>().GetPlayerId();
			RopeBody ropeBody = rope.Initialize(vec, playerInfo.playerToUseRopeOn.fixTrans.position, playerInfo.isGrounded, playerInfo.playerId, startingSegmentSeparation, playerInfo.playerMaterial);
			firedRopeNumber = ropeBody.number;
			FixTransform.InstantiateFixed(hookPrefab, vec).Initialize(ropeBody, topAttachment: true, ((player.AimVector() == Vec2.zero) ? Vec2.right : player.AimVector()) * hookSpeed, rope, playerId);
			playerInfo.slimeController.body.selfImposedVelocity = Vec2.zero;
			PlayerBody component = playerInfo.playerToUseRopeOn.fixTrans.GetComponent<PlayerBody>();
			if (component != null)
			{
				component.selfImposedVelocity = Vec2.zero;
				component.AttachRope(null, topAttachment: false);
				component.AttachRope(ropeBody, topAttachment: false);
			}
			else
			{
				BounceBall component2 = playerInfo.playerToUseRopeOn.fixTrans.GetComponent<BounceBall>();
				component2?.AttachRope(null, topAttachment: false);
				component2?.AttachRope(ropeBody, topAttachment: false);
			}
			hasHadCooldownSet = true;
			instantAbility?.SetCoolDown(cooldown);
		}
		else
		{
			Vec2 vec2 = fixTrans.position + player.AimVector() * hookSpawnOffset;
			Rope rope2 = FixTransform.InstantiateFixed(ropePrefab, vec2);
			RopeBody ropeBody = rope2.Initialize(vec2, playerInfo.slimeController.body.position, playerInfo.isGrounded, playerInfo.playerId, startingSegmentSeparation, playerInfo.playerMaterial);
			firedRopeNumber = ropeBody.number;
			FixTransform.InstantiateFixed(hookPrefab, vec2).Initialize(ropeBody, topAttachment: true, ((player.AimVector() == Vec2.zero) ? Vec2.right : player.AimVector()) * hookSpeed, rope2, playerInfo.playerId);
			playerInfo.slimeController.body.selfImposedVelocity = Vec2.zero;
			playerInfo.slimeController.body.AttachRope(null, topAttachment: false);
			playerInfo.slimeController.body.AttachRope(ropeBody, topAttachment: false);
			this.ropeBody = ropeBody;
		}
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}
}
