public class Invisibility : MonoBehaviour
{
	private Ability ability;

	private InstantAbility ia;

	public Fix cooldown;

	public const int duration = 5;

	private static AnimationCurve fadeOutAnim = AnimationCurve.EaseInOut(0f, 1f, 1f, 0f);

	private void Awake()
	{
		ia = GetComponent<InstantAbility>();
	}

	public void CastInvisibility()
	{
		Player player = PlayerHandler.Get().GetPlayer(ia.GetPlayerId());
		player.isInvisible = true;
		player.timeSpentInvisible = Fix.Zero;
		player.timeSinceEnteredAbility = Fix.Zero;
		ia.SetCoolDown((Fix)10000L);
	}

	public void OnInvisibiltyEnded()
	{
		if (ia != null && !ia.IsDestroyed)
		{
			ia.SetCoolDown(cooldown);
		}
	}

	public static void SetAlphaBasedOnPlayerInvisibiltyTime(Player player, SpriteRenderer spriteRen)
	{
		if (player == null)
		{
			return;
		}
		if (player.isInvisible)
		{
			if (!(spriteRen == null))
			{
				float num = 5f - (float)player.timeSpentInvisible;
				float num2 = ((!(num <= 1f)) ? fadeOutAnim.Evaluate((float)player.timeSinceEnteredAbility) : fadeOutAnim.Evaluate(num));
				if (GameLobby.isOnlineGame && player.IsLocalPlayer)
				{
					num2 = Mathf.Max(0.2f, num2);
				}
				UnityEngine.Color color = spriteRen.color;
				color.a = num2;
				spriteRen.color = color;
			}
		}
		else if (!(spriteRen == null))
		{
			UnityEngine.Color color2 = spriteRen.color;
			color2.a = 1f;
			spriteRen.color = color2;
		}
	}
}
public class Katana : MonoUpdatable, IAbilityComponent
{
	private PlayerInfo playerInfo;

	private Player player;

	private SpriteRenderer spriteRen;

	private PlayerPhysics physics;

	private PlayerBody body;

	private Ability ability;

	private SpriteAnimator animator;

	private DPhysicsBox hurtbox;

	public AnimationData animData;

	private bool hasAttacked;

	public Vec2 localAttackOffset;

	[SerializeField]
	private DPhysicsBox swordSwipePrefab;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		spriteRen = GetComponent<SpriteRenderer>();
		physics = GetComponent<PlayerPhysics>();
		body = GetComponent<PlayerBody>();
		animator = GetComponent<SpriteAnimator>();
		hurtbox = GetComponent<DPhysicsBox>();
		ability = GetComponent<Ability>();
	}

	public void ExitAbility(AbilityExitInfo info)
	{
		info.selfImposedVelocity = body.selfImposedVelocity;
		info.externalVelocity = body.externalVelocity;
		info.isFacingRight = base.transform.localScale.x >= 0f;
		info.position = body.position;
		info.groundedSpeed = physics.groundedSpeed;
		info.isGrounded = physics.IsGrounded();
		info.currentlyAttachedGround = physics.getAttachedGround();
		info.lastSprite = spriteRen.sprite;
		info.groundedLocalPosition = physics.LocalPlatformPos;
		info.radius = physics.radius;
		ability.ExitAbility(info);
	}

	public void OnEnterAbility()
	{
		hasAttacked = false;
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		body.rotation = playerInfo.rotation;
		float num = (playerInfo.isFacingRight ? 1 : (-1));
		base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * num, base.transform.localScale.y, base.transform.localScale.z);
		if (!playerInfo.isGrounded)
		{
			body.selfImposedVelocity *= (Fix)0.05f;
			body.externalVelocity *= (Fix)0.05f;
		}
		animator.beginAnimation(animData.GetAnimation("charge"));
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	public override void Init()
	{
	}

	private void attack()
	{
		animator.beginAnimThenDoAction(animData.GetAnimation("attack"), ExitAbility);
		Vec2 vec = getAttackOffset();
		Vec2 vec2;
		if (player.AimVector() != Vec2.zero)
		{
			vec2 = player.AimVector();
			vec = body.position + vec2 * Vec2.Magnitude(vec - body.position);
		}
		else
		{
			vec2 = Vec2.NormalizedSafe(vec - body.position);
		}
		DPhysicsBox dPhysicsBox = FixTransform.InstantiateFixed(swordSwipePrefab, vec);
		dPhysicsBox.Initialize();
		dPhysicsBox.Scale = hurtbox.Scale;
		dPhysicsBox.up = vec2;
	}

	private Vec2 getAttackOffset()
	{
		Vec2 u = localAttackOffset;
		u.x *= ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One);
		u = Vec2.ComplexMul(body.right, u);
		Fix fix = Fix.Clamp(body.fixtrans.Scale / (Fix)3L, Fix.One, (Fix)2L);
		return body.position + fix * u;
	}

	private void OnDrawGizmos()
	{
		Vec2 vec = localAttackOffset;
		Gizmos.DrawWireSphere(base.transform.position + (Vector3)vec, 0.5f);
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (!player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012) && !hasAttacked)
		{
			attack();
			hasAttacked = true;
		}
		physics.AddGravityFactor();
		physics.Move(Vec2.zero, SimDeltaTime, moveAlongSurface: false);
	}
}
