}
public class MachoThrow2 : MonoUpdatable, IAbilityComponent
{
	public enum ThrowState
	{
		enter,
		pickup,
		idle,
		walk,
		turn,
		throwAnticipation,
		exit
	}

	public NamedSpriteList boulders;

	public AnimationData animData;

	private PlayerInfo playerInfo;

	private Player player;

	private DPhysicsBox hurtbox;

	private PlayerCollision playerCol;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private ThrowState state;

	private ShakableCamera shakeyCam;

	[SerializeField]
	private SpriteRenderer boulderDummy;

	[SerializeField]
	private SpriteRenderer slimeTrail;

	public Vec2[] dummyPositions;

	public Vec2[] dummyPositionsPrepareThrow;

	private Vec2 currentDummyPos;

	public UnityEngine.Color[] boulderSmokeColors;

	public SpriteRenderer smokeEffectPrefab;

	private int abilityButtonIndex;

	public Fix forceFromBoulder;

	private bool HasReleasedFirstAbilityButtonClick;

	private Fix chargeTime = Fix.Zero;

	private bool isGrabbingDirt;

	public Fix playerRadiusHack = Fix.One;

	public int framesBeforeYouCanMoveAfterThrowing = 8;

	public int framesBeforeYouCanJumpAfterThrowing = 8;

	public Fix rotationVelOnThrow = Fix.One;

	private bool facingRight;

	private PlatformType boulderType;

	private UnityEngine.Color createdPlatfromColor;

	private SpriteRenderer smokeEffect;

	public Fix angVelMultiplierOnGround01;

	public Fix maxDistToPickupAttachable = Fix.One;

	private bool pickedUpRope;

	private GameObject pickedupAttachable;

	public int framesUntilPlatformShrinks = 5;

	[SerializeField]
	private Boulder boulderPrefab;

	public Vec2 projectileSpawnPos;

	public Vec2 projectileSpawnPos_low;

	public Fix throwSpeed;

	private const int maxRocks = 10;

	private RingBufferSimple<Boulder> ringBuffer = new RingBufferSimple<Boulder>(10);

	private Boulder heldBoulder;

	public Vec2 minThrowVector;

	public Fix proportionOfExtraStrFromScale = Fix.One;

	public Fix quickThrowStr = Fix.One;

	public Fix quickThrowChargeScaling = Fix.One;

	public Fix scaleReductionOnGroundPlatform = Fix.One;

	public Fix distfromGroundToHands;

	public int spritesBeforeWeSwapToDummyPosition = 4;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		hurtbox = GetComponent<DPhysicsBox>();
		shakeyCam = Camera.main.transform.parent.gameObject.GetComponent<ShakableCamera>();
		playerCol = GetComponent<PlayerCollision>();
	}

	public override void Init()
	{
	}

	private void UpdateDirection(Vec2 direction)
	{
		StickyRoundedRectangle attachedGround = physics.getAttachedGround();
		if (!(attachedGround == null))
		{
			Vec2 v = attachedGround.forwardsDirection(body);
			Vector3 localScale = base.transform.localScale;
			Fix fix = Vec2.Dot(v, direction);
			if (fix > 0L)
			{
				facingRight = true;
				localScale.x = Mathf.Abs(localScale.x);
				base.transform.localScale = localScale;
			}
			else if (fix < 0L)
			{
				facingRight = false;
				localScale.x = 0f - Mathf.Abs(localScale.x);
				base.transform.localScale = localScale;
			}
		}
	}

	public override void LateUpdateSim(Fix SimDeltaTime)
	{
		int numberOfPassedSprites = animator.getNumberOfPassedSprites();
		if (state == ThrowState.pickup && numberOfPassedSprites < dummyPositions.Length)
		{
			currentDummyPos = dummyPositions[numberOfPassedSprites];
		}
		else if (state == ThrowState.throwAnticipation && numberOfPassedSprites < dummyPositionsPrepareThrow.Length)
		{
			currentDummyPos = dummyPositionsPrepareThrow[numberOfPassedSprites];
		}
		else
		{
			currentDummyPos = dummyPositions[dummyPositions.Length - 1];
		}
		if (heldBoulder != null && heldBoulder.HasBeenDropped())
		{
			heldBoulder = null;
		}
		UpdateHeldBoulder();
	}

	private void Update()
	{
		if (!(body == null) && !body.IsDestroyed)
		{
			Vec2 u = currentDummyPos * body.fixtrans.Scale;
			u.x = (facingRight ? u.x : (-u.x));
			boulderDummy.transform.position = base.transform.position + (Vector3)Vec2.ComplexMul(body.right, u);
			if (Mathf.Abs(boulderDummy.transform.lossyScale.x) < (float)boulderPrefab.hitbox.MinScale)
			{
				float num = Mathf.Abs((float)boulderPrefab.hitbox.MinScale / base.transform.localScale.x);
				boulderDummy.transform.localScale = new Vector3(base.transform.localScale.x * num, num, 1f);
			}
			Vector3 localScale = boulderDummy.transform.localScale;
			localScale.x = Mathf.Sign(base.transform.localScale.x) * Mathf.Abs(localScale.x);
			boulderDummy.transform.localScale = localScale;
			if (smokeEffect != null)
			{
				smokeEffect.transform.position = base.transform.position - (float)physics.radius * base.transform.up;
			}
		}
	}

	private void UpdateHeldBoulder()
	{
		if (heldBoulder != null && !heldBoulder.IsDestroyed)
		{
			heldBoulder.hitbox.position = heldPos();
			heldBoulder.hitbox.rotation = body.rotation;
			Vec2 velocity = heldBoulder.hitbox.velocity;
			heldBoulder.hitbox.velocity = Vec2.zero;
			heldBoulder.hitbox.angularVelocity = Fix.Zero;
			physics.AddForce(velocity * forceFromBoulder / physics.inverseMass01);
		}
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		Vec2 inputVector = Vec2.zero;
		Vec2 vec = player.InputVector();
		Fix fix = physics.InputGroundAlignment(vec);
		bool flag = fix > 0L;
		bool flag2 = Fix.Abs(fix) >= Constants.GROUNDALIGNMENTDEADZONE;
		player.CustomAimAbilityPosition = heldPos();
		if (!HasReleasedFirstAbilityButtonClick && !player.AbilityButtonIsDown(abilityButtonIndex))
		{
			HasReleasedFirstAbilityButtonClick = true;
		}
		if (heldBoulder != null && heldBoulder.HasBeenDropped())
		{
			heldBoulder = null;
		}
		UpdateHeldBoulder();
		if (heldBoulder != null)
		{
			heldBoulder.Hold();
			if (!heldBoulder.isActiveAndEnabled && !heldBoulder.IsDestroyed)
			{
				heldBoulder.Drop();
				heldBoulder = null;
			}
			else if (heldBoulder.body.magnetGunHolder != null && !heldBoulder.IsDestroyed)
			{
				heldBoulder.Drop();
				heldBoulder = null;
			}
		}
		if (state == ThrowState.idle || state == ThrowState.turn || state == ThrowState.walk)
		{
			if (HasReleasedFirstAbilityButtonClick)
			{
				state = ThrowState.throwAnticipation;
				animator.beginAnimThenDoAction(animData.GetAnimation("beginThrow"), delegate
				{
					UpdateDirection(player.AimVector());
					Fire(quickThrow: false);
					state = ThrowState.exit;
					animator.beginAnimThenDoAction(animData.GetAnimation("exit"), delegate
					{
						ExitAbility(default(AbilityExitInfo));
					});
				});
			}
		}
		else if (state == ThrowState.pickup && HasReleasedFirstAbilityButtonClick)
		{
			UpdateDirection(player.AimVector());
			Fire(quickThrow: true);
			state = ThrowState.exit;
			animator.beginAnimThenDoAction(animData.GetAnimation("exit"), delegate
			{
				ExitAbility(default(AbilityExitInfo));
			});
		}
		switch (state)
		{
		case ThrowState.enter:
		{
			int numberOfPassedSprites = animator.getNumberOfPassedSprites();
			if (isGrabbingDirt && numberOfPassedSprites > framesUntilPlatformShrinks)
			{
				shrinkPlatform(SimDeltaTime);
			}
			break;
		}
		case ThrowState.idle:
			if (!AchievementHandler.IsAchieved(AchievementHandler.AchievementEnum.BuildATowerOfMachoSlime) && physics.IsGrounded())
			{
				StickyRoundedRectangle attachedGround = physics.getAttachedGround();
				if (attachedGround != null && !attachedGround.IsDestroyed && attachedGround.CompareTag("boulder"))
				{
					Boulder component = attachedGround.GetComponent<Boulder>();
					if (component != null && !component.IsDestroyed && !component.HasBeenDropped())
					{
						AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.BuildATowerOfMachoSlime);
					}
				}
			}
			if (Fix.Abs(fix) >= Constants.DEADZONE)
			{
				state = ThrowState.walk;
				animator.beginAnimThenPlayAnim(animData.GetAnimation("idleToWalk"), animData.GetAnimation("walk"));
			}
			break;
		case ThrowState.walk:
			if (!flag2)
			{
				state = ThrowState.idle;
				animator.beginAnim(animData.GetAnimation("idle"), null);
			}
			else if ((flag && !facingRight) || (!flag && facingRight))
			{
				facingRight = !facingRight;
				state = ThrowState.turn;
				animator.beginAnimThenDoAction(animData.GetAnimation("turn"), delegate
				{
					Vector3 localScale2 = base.transform.localScale;
					localScale2.x *= -1f;
					base.transform.localScale = localScale2;
					state = ThrowState.walk;
					animator.beginAnim(animData.GetAnimation("walk"), null);
				});
			}
			inputVector = vec;
			break;
		case ThrowState.turn:
			if (!flag2)
			{
				state = ThrowState.idle;
				Vector3 localScale = base.transform.localScale;
				localScale.x *= -1f;
				base.transform.localScale = localScale;
				animator.beginAnim(animData.GetAnimation("idle"), null);
			}
			inputVector = vec;
			break;
		case ThrowState.exit:
			if (animator.getNumberOfPassedSprites() > framesBeforeYouCanMoveAfterThrowing)
			{
				inputVector = vec;
			}
			if (animator.getNumberOfPassedSprites() > framesBeforeYouCanJumpAfterThrowing && player.jumpButton_PressedThisFrame())
			{
				physics.Jump();
				ExitAbility(new AbilityExitInfo
				{
					isGrounded = false
				});
				return;
			}
			break;
		}
		Fix roundedness = Fix.One;
		if (physics.getAttachedGround() != null && !physics.getAttachedGround().IsDestroyed && physics.getAttachedGround().inCorner(body.position))
		{
			roundedness = Fix.Min(physics.getAttachedGround().rr.radius * playerRadiusHack, (Fix)10L) / (Fix)10L;
		}
		heldPos();
		if (!heldBoulder || heldBoulder.IsDestroyed)
		{
			_ = (Fix)0.1;
		}
		else
		{
			_ = heldBoulder.hitbox.radius;
		}
		physics.MachoMove(inputVector, SimDeltaTime, roundedness);
	}

	public void OnEnterAbility()
	{
		pickedUpRope = false;
		pickedupAttachable = null;
		heldBoulder = null;
		boulderDummy.gameObject.SetActive(value: false);
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		abilityButtonIndex = playerInfo.AbilityButtonUsedIndex012;
		HasReleasedFirstAbilityButtonClick = false;
		spriteRen.material = playerInfo.playerMaterial;
		Vec2 selfImposedVelocity = playerInfo.selfImposedVelocity;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		body.selfImposedVelocity = selfImposedVelocity;
		state = ThrowState.enter;
		player.InMachoThrow = true;
		slimeTrail.material = player.Color;
		boulderDummy.transform.GetChild(0).GetComponent<SpriteRenderer>().sprite = null;
		boulderDummy.transform.GetChild(0).localScale = Vector3.one;
		StickyRoundedRectangle attachedGround = physics.getAttachedGround();
		if (attachedGround != null)
		{
			boulderType = attachedGround.platformType;
			createdPlatfromColor = attachedGround.GetComponent<SpriteRenderer>().color;
			boulderDummy.sprite = boulders.sprites[(int)boulderType].sprite;
			boulderDummy.color = createdPlatfromColor;
		}
		isGrabbingDirt = false;
		StickyRoundedRectangle ground = physics.getAttachedGround();
		if ((bool)ground && !ground.IsDestroyed && ground.CompareTag("boulder"))
		{
			ground.rr.angularVelocity *= angVelMultiplierOnGround01;
		}
		animator.beginAnimThenDoAction(animData.GetAnimation("enter"), delegate
		{
			GameObject gameObject = FixTransform.InstantiateFixed(smokeEffectPrefab.gameObject, body.position - body.up * physics.radius, body.rotation);
			smokeEffect = gameObject.GetComponent<SpriteRenderer>();
			smokeEffect.transform.localScale = base.transform.localScale;
			AudioManager.Get().Play("pickupBoulder");
			if (boulderType == PlatformType.slime)
			{
				smokeEffect.color = createdPlatfromColor;
			}
			else
			{
				smokeEffect.color = boulderSmokeColors[(int)boulderType];
			}
			if (ground != null && !ground.IsDestroyed)
			{
				pickUpNearbyAttachables(ground);
			}
			isGrabbingDirt = true;
			animator.beginAnimThenDoAction(animData.GetAnimation("grab"), delegate
			{
				isGrabbingDirt = false;
				state = ThrowState.pickup;
				boulderDummy.gameObject.SetActive(value: true);
				animator.beginAnimThenDoAction(animData.GetAnimation("pickup"), delegate
				{
					state = ThrowState.idle;
					SpawnBoulder();
					boulderDummy.gameObject.SetActive(value: false);
					animator.beginAnimation(animData.GetAnimation("idle"));
				});
			});
		});
		facingRight = playerInfo.isFacingRight;
		float num = (facingRight ? 1 : (-1));
		base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * num, base.transform.localScale.y, base.transform.localScale.z);
		UpdateDirection(player.AimVector());
	}

	private void pickUpNearbyAttachables(StickyRoundedRectangle srr)
	{
		srr.UpdateBounds();
		Fix fix = srr.Circumference();
		GameObject gameObject = null;
		Fix fix2 = Fix.MaxValue;
		for (int i = 0; i < srr.transform.childCount; i++)
		{
			GameObject gameObject2 = srr.transform.GetChild(i).gameObject;
			if (gameObject2.layer == LayerMask.NameToLayer("LethalTerrain") || gameObject2.layer == LayerMask.NameToLayer("NonLethalTerrain"))
			{
				Fix fix3 = Fix.Abs(gameObject2.GetComponent<IPlatformAttachable>().LocalPlatformPosition - physics.LocalPlatformPos);
				fix3 = Fix.Min(fix3, Fix.One - fix3);
				if (fix3 * fix < maxDistToPickupAttachable && fix3 < fix2)
				{
					fix2 = fix3;
					gameObject = gameObject2;
				}
			}
		}
		int num = LayerMask.NameToLayer("Rope");
		pickedUpRope = false;
		for (int j = 0; j < Updater.updatables.Count; j++)
		{
			if (Updater.updatables[j].gameObject.layer != num)
			{
				continue;
			}
			RopeAttachment component = Updater.updatables[j].GetComponent<RopeAttachment>();
			if (!(component != null) || !component.IsPlatformAttachment())
			{
				continue;
			}
			StickyRoundedRectangle platformParent = component.GetPlatformParent();
			StickyRoundedRectangle attachedGround = physics.getAttachedGround();
			if (attachedGround != null && !attachedGround.IsDestroyed && platformParent != null && !platformParent.IsDestroyed && platformParent.HierarchyNumber == attachedGround.HierarchyNumber)
			{
				Fix fix4 = Fix.Abs(component.LocalPlatformPosition - physics.LocalPlatformPos);
				fix4 = Fix.Min(fix4, Fix.One - fix4);
				if (fix4 * fix < maxDistToPickupAttachable && fix4 < fix2)
				{
					fix2 = fix4;
					gameObject = component.gameObject;
					pickedUpRope = true;
				}
			}
		}
		if (pickedUpRope)
		{
			pickedupAttachable = gameObject;
		}
		else
		{
			if (!(gameObject != null))
			{
				return;
			}
			pickedupAttachable = gameObject;
			SimpleSparkNode component2 = gameObject.GetComponent<SimpleSparkNode>();
			SpikeAttack component3 = gameObject.GetComponent<SpikeAttack>();
			RocketEngine component4 = gameObject.GetComponent<RocketEngine>();
			pickedupAttachable.transform.parent = null;
			pickedupAttachable.SetActive(value: false);
			pickedupAttachable.GetComponent<FixTransform>().startScale = Vector3.one;
			if ((bool)component2)
			{
				int instanceId = gameObject.GetComponent<DPhysicsCircle>().GetPhysicsParent().instanceId;
				CompositeBody compositeParent = DetPhysics.Get().circles.physicsBodies[DetPhysics.Get().circles.ColliderIndex(instanceId)].compositeParent;
				DetPhysics.Get().RemoveCircleFromComposite(instanceId, compositeParent);
			}
			else if ((bool)component3)
			{
				int instanceId2 = gameObject.GetComponent<DPhysicsBox>().GetPhysicsParent().instanceId;
				CompositeBody compositeParent2 = DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(instanceId2)].compositeParent;
				DetPhysics.Get().RemoveBoxFromComposite(instanceId2, compositeParent2);
			}
			else if ((bool)component4)
			{
				int instanceId3 = gameObject.GetComponent<DPhysicsBox>().GetPhysicsParent().instanceId;
				CompositeBody compositeParent3 = DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(instanceId3)].compositeParent;
				DetPhysics.Get().RemoveBoxFromComposite(instanceId3, compositeParent3);
			}
			Transform child = boulderDummy.transform.GetChild(0);
			child.GetComponent<SpriteRenderer>().sprite = pickedupAttachable.GetComponent<SpriteRenderer>().sprite;
			child.localScale = (float)pickedupAttachable.GetComponent<FixTransform>().Scale / base.transform.localScale.y * Vector3.one;
			if ((bool)component2)
			{
				child.transform.rotation = base.transform.rotation;
				child.localPosition = new Vector3(0f, 2.5f + (float)pickedupAttachable.GetComponent<IPlatformAttachable>().SurfaceOffset / base.transform.localScale.y, 1f);
			}
			else if ((bool)component3)
			{
				child.transform.rotation = Quaternion.Euler(0f, 0f, 180f) * base.transform.rotation;
				child.localPosition = new Vector3(0f, 1.05f + (float)pickedupAttachable.GetComponent<IPlatformAttachable>().SurfaceOffset / base.transform.localScale.y, 1f);
			}
			else if ((bool)component4)
			{
				if (facingRight)
				{
					child.transform.rotation = Quaternion.Euler(0f, 0f, 90f) * base.transform.rotation;
				}
				else
				{
					child.transform.rotation = Quaternion.Euler(0f, 0f, 270f) * base.transform.rotation;
				}
				child.localPosition = new Vector3(-2.5f - (float)pickedupAttachable.GetComponent<IPlatformAttachable>().SurfaceOffset / base.transform.localScale.y, 0f, 1f);
			}
		}
	}

	private void DoThrow()
	{
		UpdateDirection(player.AimVector());
		Fire(quickThrow: false);
	}

	private void shrinkPlatform(Fix deltaTime)
	{
		StickyRoundedRectangle attachedGround = physics.getAttachedGround();
		if (attachedGround != null && !attachedGround.IsDestroyed)
		{
			Fix fix = attachedGround.rr.PlatformArea();
			attachedGround.rr.Scale -= attachedGround.rr.Scale * deltaTime * scaleReductionOnGroundPlatform / fix;
			if (attachedGround.rr.Scale <= attachedGround.rr.MinScale)
			{
				Updater.DestroyFix(attachedGround.gameObject);
			}
		}
	}

	private void attachPickupedAttachableToBoulder(StickyRoundedRectangle boulderSrr)
	{
		if (pickedupAttachable == null)
		{
			return;
		}
		SimpleSparkNode component = pickedupAttachable.GetComponent<SimpleSparkNode>();
		SpikeAttack component2 = pickedupAttachable.GetComponent<SpikeAttack>();
		RocketEngine component3 = pickedupAttachable.GetComponent<RocketEngine>();
		RopeAttachment component4 = pickedupAttachable.GetComponent<RopeAttachment>();
		pickedupAttachable.gameObject.SetActive(value: true);
		if ((bool)component4)
		{
			Vec2 pos = component4.GetComponent<FixTransform>().position - body.up * (Fix)100L;
			Vec2 position = component4.GetFixTrans().position;
			boulderSrr.UpdateBounds();
			component4.AttachToPlatform(pos, boulderSrr, component4.GetInitializedRopeBody(), component4.topAttachment);
			component4.LocalPlatformPosition = Fix.One / (Fix)2L;
			component4.RepositionOnParent();
			Vec2 position2 = component4.GetFixTrans().position;
			RopeBody initializedRopeBody = component4.GetInitializedRopeBody();
			Vec2 vec = position2 - position;
			_ = initializedRopeBody.segmentCount;
			for (int i = 0; i < initializedRopeBody.segmentCount / 2; i++)
			{
				initializedRopeBody.segment[i] += vec;
			}
			for (int j = 0; j < initializedRopeBody.segmentCount; j++)
			{
				initializedRopeBody.segmentPrev[j] = initializedRopeBody.segment[j];
			}
			DetPhysics.Get().SimulateRope(initializedRopeBody, null);
		}
		else if ((bool)component)
		{
			component.transform.parent = boulderSrr.transform;
			FixTransform component5 = component.GetComponent<FixTransform>();
			Fix scale = component5.Scale;
			component5.rotation = Fix.Zero;
			int num = DetPhysics.Get().circles.ColliderIndex(component.gameObject.GetInstanceID());
			DetPhysics.Get().circles.physicsBodies[num].orientation = Fix.Zero;
			component.Initialize(component.GetPlayerId(), component.childNode, component.SurfaceOffset / scale, Fix.Zero, boulderSrr, scale, skipInit: true);
		}
		else if ((bool)component2)
		{
			component2.transform.parent = boulderSrr.transform;
			FixTransform component6 = component2.GetComponent<FixTransform>();
			Fix scale2 = component6.Scale;
			component6.rotation = boulderSrr.GetGroundBody().rotation + Fix.Pi;
			component2.Initialize(component6.position - component6.up * (Fix)1000L, component2.SurfaceOffset / scale2, boulderSrr, scale2, updateStartScale: true, skipInit: true);
		}
		else if ((bool)component3)
		{
			component3.transform.parent = boulderSrr.transform;
			FixTransform component7 = component3.GetComponent<FixTransform>();
			Fix scale3 = component7.Scale;
			component7.rotation = boulderSrr.GetGroundBody().rotation + Fix.PiOver2 + (facingRight ? Fix.Zero : Fix.Pi);
			int num2 = DetPhysics.Get().boxes.ColliderIndex(component3.gameObject.GetInstanceID());
			DetPhysics.Get().boxes.physicsBodies[num2].orientation = component7.rotation;
			component3.RocketEngineInit(boulderSrr, component3.SurfaceOffset / scale3, component7.position + component7.up * (Fix)1000L, scale3, component3.ownerId, updateStartScale: true, skipInit: true);
		}
	}

	private void SpawnBoulder()
	{
		Vec2 pos = heldPos();
		heldBoulder = FixTransform.InstantiateFixed(boulderPrefab, pos);
		heldBoulder.hitbox.position = heldPos();
		StickyRoundedRectangle component = heldBoulder.GetComponent<StickyRoundedRectangle>();
		component.platformType = boulderType;
		SpriteRenderer component2 = heldBoulder.GetComponent<SpriteRenderer>();
		component2.sprite = boulderDummy.sprite;
		component2.color = boulderDummy.color;
		heldBoulder.hitbox.Scale = body.fixtrans.Scale;
		ringBuffer.Add(heldBoulder);
		heldBoulder.hitbox.ManualInit();
		attachPickupedAttachableToBoulder(component);
	}

	private void Fire(bool quickThrow)
	{
		Boulder boulder;
		DPhysicsRoundedRect dPhysicsRoundedRect;
		if (quickThrow)
		{
			Vec2 pos = (quickThrow ? quickThrowFirePos() : firePos());
			boulder = FixTransform.InstantiateFixed(boulderPrefab, pos);
			dPhysicsRoundedRect = boulder.hitbox;
			dPhysicsRoundedRect.Scale = body.fixtrans.Scale;
			ringBuffer.Add(boulder);
			dPhysicsRoundedRect.ManualInit();
			dPhysicsRoundedRect.Scale = body.fixtrans.Scale;
			StickyRoundedRectangle component = dPhysicsRoundedRect.GetComponent<StickyRoundedRectangle>();
			component.platformType = boulderType;
			SpriteRenderer component2 = dPhysicsRoundedRect.GetComponent<SpriteRenderer>();
			component2.sprite = boulderDummy.sprite;
			component2.color = boulderDummy.color;
			attachPickupedAttachableToBoulder(component);
		}
		else
		{
			boulder = heldBoulder;
			dPhysicsRoundedRect = heldBoulder?.hitbox;
		}
		if (boulder == null || !boulder.isActiveAndEnabled)
		{
			return;
		}
		boulder.Drop();
		AudioManager.Get().Play("throwBoulder");
		Vec2 v = (quickThrow ? Vec2.right : Vec2.NormalizedSafe(minThrowVector));
		Vec2 vec = player.AimVector();
		if (vec == Vec2.zero)
		{
			vec = body.right * (facingRight ? Fix.One : (-Fix.One));
		}
		if (Vec2.Dot(body.up, vec) < Vec2.Dot(v, Vec2.up))
		{
			if (Vec2.Dot(body.right, vec) < Fix.Zero)
			{
				v.x *= -Fix.One;
				vec = Vec2.ComplexMul(v, body.right);
			}
			else
			{
				vec = Vec2.ComplexMul(v, body.right);
			}
		}
		Fix fix = (quickThrow ? (quickThrowStr + (Fix)animator.getNumberOfPassedSprites() * quickThrowChargeScaling) : throwSpeed);
		Fix fix2 = (hurtbox.Scale + (proportionOfExtraStrFromScale - Fix.One)) / proportionOfExtraStrFromScale;
		dPhysicsRoundedRect.velocity = vec * fix * fix2 * dPhysicsRoundedRect.inverseMass;
		dPhysicsRoundedRect.angularVelocity = (facingRight ? (-rotationVelOnThrow) : rotationVelOnThrow);
		boulderDummy.gameObject.SetActive(value: false);
		heldBoulder = null;
	}

	private void OnDrawGizmos()
	{
		Vec2 v = Vec2.NormalizedSafe(minThrowVector);
		if (player != null)
		{
			Vec2 vec = player.AimVector();
			if (Vec2.Dot(body.up, vec) < Vec2.Dot(v, Vec2.up))
			{
				if (Vec2.Dot(body.right, vec) < Fix.Zero)
				{
					v.x *= -Fix.One;
					vec = Vec2.ComplexMul(v, body.right);
				}
				else
				{
					vec = Vec2.ComplexMul(v, body.right);
				}
			}
			UnityEngine.Debug.DrawLine((Vector3)heldPos(), (Vector3)heldPos() + (Vector3)vec * 10f);
		}
		for (int i = 0; i < dummyPositionsPrepareThrow.Length; i++)
		{
			Gizmos.DrawWireSphere(base.transform.position + (Vector3)dummyPositionsPrepareThrow[i], 1.5f);
		}
	}

	private Vec2 firePos()
	{
		Vec2 u = projectileSpawnPos * body.fixtrans.Scale;
		u.x = (facingRight ? u.x : (-u.x));
		return body.position + Vec2.ComplexMul(body.right, u);
	}

	private Vec2 quickThrowFirePos()
	{
		int numberOfPassedSprites = animator.getNumberOfPassedSprites();
		Vec2 u = projectileSpawnPos_low * body.fixtrans.Scale;
		if (numberOfPassedSprites > spritesBeforeWeSwapToDummyPosition)
		{
			u = currentDummyPos;
		}
		u.x = (facingRight ? u.x : (-u.x));
		return body.position + Vec2.ComplexMul(body.right, u);
	}

	private Vec2 heldPos()
	{
		Vec2 u = currentDummyPos * body.fixtrans.Scale;
		u.x = (facingRight ? u.x : (-u.x));
		if (heldBoulder != null)
		{
			u.y += boulderPrefab.hitbox.radius * (heldBoulder.hitbox.Scale - Fix.One) + distfromGroundToHands * (body.fixtrans.Scale - Fix.One);
		}
		return body.position + Vec2.ComplexMul(body.right, u);
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		if (heldBoulder != null)
		{
			heldBoulder.Drop();
		}
		player.InMachoThrow = false;
		body.rotation = Fix.Zero;
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.position = body.position;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.lastSprite = spriteRen.sprite;
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		exitInfo.isFacingRight = facingRight;
		UpdateDirection(player.InputVector());
		ability.ExitAbility(exitInfo);
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}
}
