public class Orb : MonoUpdatable, ICollisionCallback
{
	public enum OrbState
	{
		charging,
		released,
		bounced
	}

	public enum OrbType
	{
		orb,
		blink,
		grow,
		shrink,
		duplicator,
		beam
	}

	public struct HitObject
	{
		public int hierarchyNumber;

		public int simulationTickOfLastBounce;
	}

	private OrbState state;

	private UnityEngine.Color[] orbTypeColors = new UnityEngine.Color[6]
	{
		UnityEngine.Color.black,
		UnityEngine.Color.cyan,
		(UnityEngine.Color.green + UnityEngine.Color.yellow) * 0.5f,
		(UnityEngine.Color.red + UnityEngine.Color.yellow) * 0.5f,
		UnityEngine.Color.blue,
		UnityEngine.Color.red
	};

	[NonSerialized]
	public OrbType orbType;

	public Fix speed;

	private Vector3 innerLocalPos;

	private SpriteRenderer innerCircle;

	public Vector2 innerLocalPos0;

	public Vector2 innerLocalPos1;

	public Vector2 innerLocalPos2;

	private Fix prevScaleMod;

	private Vec2 dir;

	public Fix friction01;

	public Fix stopFriction01;

	public Fix stoppingAcc;

	public Fix stopSize;

	public Fix travelSize;

	public Fix scaleLerpFactor01;

	public Fix playerForce;

	public Fix exitScaleTime;

	public AnimationCurveFixed exitScaleAnim;

	private ShootQuantum shootQuantum;

	private ShootScaleChange[] shootScaleChanges;

	private ShootDuplicator shootDuplicator;

	private const int ringBuffersize = 30;

	private HitObject[] colliders = new HitObject[30];

	private int ringBufferHead;

	private int lastPlayerClonedId;

	private int lastPlayerClonedTick;

	private const int maxBouncesBeforeSelfDestroy = 30;

	private int bounces;

	private const int ticksBetweenBounces = 20;

	private int simTicksAtLastDuplication = -1000;

	private Fix timeSinceBeamStart;

	public Fix beamDuration;

	private DetPhysics.BeamColors beamColors;

	public Fix wallAcc;

	private SpriteRenderer arrow;

	private SpriteRenderer spriteRen;

	[NonSerialized]
	public FixTransform fixTrans;

	private Projectile projectile;

	private DPhysicsCircle hitbox;

	private BoplBody body;

	private bool delayedEnable;

	private int framesUntilEnable;

	private bool isFiringBeam;

	private Fix beamCharge01;

	public Fix beamChargeRate01;

	public void Initialize(Player player, int abilityButton012)
	{
		projectile.SetPlayerId(player.Id);
		body.velocity = Vec2.zero;
		arrow.enabled = true;
		state = OrbState.charging;
		prevScaleMod = Fix.One;
		ModifyScale(stopSize);
		hitbox.ManualInit();
		innerLocalPos = abilityButton012 switch
		{
			1 => innerLocalPos1, 
			0 => innerLocalPos0, 
			_ => innerLocalPos2, 
		};
		innerCircle = base.transform.GetChild(1).GetComponent<SpriteRenderer>();
		UpdateInnerCirclePos();
		orbType = OrbType.orb;
		updateColor();
	}

	private void UpdateInnerCirclePos()
	{
		innerCircle.transform.position = innerLocalPos * (float)fixTrans.Scale + base.transform.position;
	}

	private void ModifyScale(Fix scaleMod)
	{
		Fix scale = scaleMod * fixTrans.Scale / prevScaleMod;
		hitbox.Scale = scale;
		prevScaleMod = scaleMod;
	}

	private void updateColor()
	{
		spriteRen.color = orbTypeColors[(int)orbType];
		arrow.color = orbTypeColors[(int)orbType];
		innerCircle.color = orbTypeColors[(int)orbType];
	}

	public void SetDirection(Vec2 dir)
	{
		if (dir == Vec2.zero)
		{
			dir = Vec2.up;
		}
		this.dir = dir;
		fixTrans.up = dir;
	}

	public void SetOrbType(OrbType type)
	{
		orbType = type;
		updateColor();
	}

	public override void Init()
	{
	}

	private void LateUpdate()
	{
		UpdateInnerCirclePos();
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (delayedEnable && framesUntilEnable <= 0)
		{
			arrow.enabled = true;
			delayedEnable = false;
		}
		framesUntilEnable--;
		if (GameTime.IsTimeStopped())
		{
			return;
		}
		if (state == OrbState.charging)
		{
			body.velocity *= stopFriction01;
			ModifyScale(Fix.Lerp(prevScaleMod, stopSize, scaleLerpFactor01));
		}
		else
		{
			body.velocity *= friction01;
		}
		if (isFiringBeam)
		{
			Fix fix = Fix.One;
			Fix fix2 = beamDuration;
			if (timeSinceBeamStart + exitScaleTime > fix2 && timeSinceBeamStart + exitScaleTime > fix2)
			{
				Fix t = (exitScaleTime - (fix2 - timeSinceBeamStart)) / exitScaleTime;
				fix = exitScaleAnim.Evaluate(t);
			}
			DetPhysics.BeamBody beamBody = new DetPhysics.BeamBody
			{
				ownerId = projectile.PlayerOwnerId,
				colors = beamColors,
				direction = Vec2.down,
				scale = Fix.One * fix,
				position = body.position + Vec2.down * (hitbox.radius + (Fix)0.1),
				distance = DetPhysics.Get().maxBeamDistance,
				timePassed = timeSinceBeamStart,
				id = base.HierarchyNumber
			};
			if (beamBody.position.y >= Constants.WATER_HEIGHT || Constants.leveltype == LevelType.space)
			{
				DetPhysics.Get().AddBeamBody(beamBody);
			}
			timeSinceBeamStart += SimDeltaTime;
			if (timeSinceBeamStart > beamDuration)
			{
				isFiringBeam = false;
				timeSinceBeamStart = Fix.Zero;
			}
		}
		if (bounces > 30)
		{
			Updater.DestroyFix(base.gameObject);
		}
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		projectile = GetComponent<Projectile>();
		fixTrans = GetComponent<FixTransform>();
		hitbox = GetComponent<DPhysicsCircle>();
		body = GetComponent<BoplBody>();
		spriteRen = GetComponent<SpriteRenderer>();
		hitbox.RegisterCollisionCallback(this);
		arrow = base.transform.GetChild(0).GetComponent<SpriteRenderer>();
		arrow.enabled = false;
		shootQuantum = GetComponent<ShootQuantum>();
		shootScaleChanges = GetComponents<ShootScaleChange>();
		shootDuplicator = GetComponent<ShootDuplicator>();
	}

	private bool ignoreCollision(int hierarchyNumber)
	{
		int simulationTicks = Updater.SimulationTicks;
		bool flag = false;
		for (int i = 0; i < colliders.Length; i++)
		{
			flag |= colliders[i].hierarchyNumber == hierarchyNumber;
			if (colliders[i].hierarchyNumber == hierarchyNumber && simulationTicks > colliders[i].simulationTickOfLastBounce + 20)
			{
				colliders[i].simulationTickOfLastBounce = simulationTicks;
				return false;
			}
		}
		if (!flag)
		{
			colliders[ringBufferHead] = new HitObject
			{
				hierarchyNumber = hierarchyNumber,
				simulationTickOfLastBounce = simulationTicks
			};
			ringBufferHead = (ringBufferHead + 1) % 30;
			return false;
		}
		return true;
	}

	void ICollisionCallback.OnCollide(CollisionInformation collision)
	{
		bool flag = collision.layer == LayerMask.NameToLayer("wall");
		if (collision.layer == LayerMask.NameToLayer("Explosion") || collision.layer == LayerMask.NameToLayer("Rope"))
		{
			return;
		}
		if (orbType == OrbType.orb)
		{
			AudioManager.Get().PlayWithRandomPitchVariation("spawnOrb");
		}
		if (ignoreCollision(collision.colliderPP.hierarchyNumber))
		{
			return;
		}
		if (flag)
		{
			collision.normal = collision.colliderPP.fixTrans.GetComponent<StickyRoundedRectangle>().currentNormal(collision.contactPoint);
		}
		if (flag)
		{
			body.velocity = wallAcc * collision.normal;
		}
		else
		{
			collision.normal = Vec2.NormalizedSafe(collision.colliderPP.fixTrans.position - fixTrans.position);
			body.velocity = -wallAcc * collision.normal;
		}
		if (collision.layer == LayerMask.NameToLayer("Player"))
		{
			PlayerBody component = collision.colliderPP.fixTrans.GetComponent<PlayerBody>();
			if ((bool)component)
			{
				component.AddForce(collision.normal * playerForce);
			}
		}
		Tools.Debug_DrawLine(collision.contactPoint, collision.contactPoint + body.velocity / (Fix)4L, UnityEngine.Color.red, 4f);
		bounces++;
		if (orbType == OrbType.duplicator && collision.colliderPP.fixTrans.IsDuplicated && simTicksAtLastDuplication + 20 > Updater.SimulationTicks)
		{
			return;
		}
		switch (orbType)
		{
		case OrbType.blink:
		{
			RaycastInformation hit3 = new RaycastInformation
			{
				pp = collision.colliderPP,
				farDist = Fix.Zero,
				farPos = collision.contactPoint,
				layer = collision.layer,
				nearDist = Fix.Zero,
				nearPos = collision.contactPoint
			};
			bool hasFired3 = true;
			shootQuantum.BlinkObject(hit3, collision.contactPoint, dir, dir, ref hasFired3, projectile.PlayerOwnerId, alreadyHitWater: true);
			shootQuantum.spawnRayCastEffect((Vector2)collision.contactPoint, (Vector2)dir, 0f, didHit: true, collision.normal);
			AudioManager.Get().Play("laserShoot");
			break;
		}
		case OrbType.grow:
		{
			RaycastInformation hit4 = new RaycastInformation
			{
				pp = collision.colliderPP,
				farDist = Fix.Zero,
				farPos = collision.contactPoint,
				layer = collision.layer,
				nearDist = Fix.Zero,
				nearPos = collision.contactPoint
			};
			bool hasFired4 = true;
			ShootScaleChange obj2 = shootScaleChanges[0];
			obj2.ApplyScaleChange(hit4, collision.contactPoint, dir, ref hasFired4, projectile.PlayerOwnerId);
			obj2.spawnRayCastEffect((Vector2)collision.contactPoint, (Vector2)dir, 0f, didHit: true);
			AudioManager.Get().Play("grow");
			AudioManager.Get().Play("shrink");
			break;
		}
		case OrbType.shrink:
		{
			RaycastInformation hit2 = new RaycastInformation
			{
				pp = collision.colliderPP,
				farDist = Fix.Zero,
				farPos = collision.contactPoint,
				layer = collision.layer,
				nearDist = Fix.Zero,
				nearPos = collision.contactPoint
			};
			bool hasFired2 = true;
			ShootScaleChange obj = shootScaleChanges[1];
			obj.ApplyScaleChange(hit2, collision.contactPoint, dir, ref hasFired2, projectile.PlayerOwnerId);
			obj.spawnRayCastEffect((Vector2)collision.contactPoint, (Vector2)dir, 0f, didHit: true);
			AudioManager.Get().Play("shrink");
			break;
		}
		case OrbType.duplicator:
		{
			RaycastInformation hit = new RaycastInformation
			{
				pp = collision.colliderPP,
				farDist = Fix.Zero,
				farPos = collision.contactPoint,
				layer = collision.layer,
				nearDist = Fix.Zero,
				nearPos = collision.contactPoint
			};
			bool hasFired = true;
			if (collision.layer == LayerMask.NameToLayer("Player"))
			{
				int playerId = collision.colliderPP.fixTrans.GetComponent<IPlayerIdHolder>().GetPlayerId();
				if (Updater.SimulationTicks < lastPlayerClonedTick + 20 && lastPlayerClonedId == playerId)
				{
					break;
				}
				lastPlayerClonedId = playerId;
				lastPlayerClonedTick = Updater.SimulationTicks;
			}
			simTicksAtLastDuplication = Updater.SimulationTicks;
			shootDuplicator.ApplyDuplicationEffect(hit, collision.colliderPP.fixTrans.position, collision.contactPoint, collision.colliderPP.fixTrans.gameObject, -collision.normal, fixTrans.position, collision.layer, projectile.PlayerOwnerId, ref hasFired, forceSingleClone: true);
			shootDuplicator.spawnRayCastEffect((Vector2)collision.contactPoint, (Vector2)collision.normal, 0.01f, didHit: true);
			AudioManager.Get().PlayRandomWithPrefix("beamSparks");
			break;
		}
		case OrbType.orb:
			break;
		}
	}

	public void Release(Vec2 dir)
	{
		if (dir == Vec2.zero)
		{
			dir = Vec2.up;
		}
		this.dir = dir;
		body.velocity = dir * speed;
		projectile.canHurtOwner = true;
		arrow.enabled = false;
		state = OrbState.released;
		ModifyScale(travelSize);
	}

	public void Stop()
	{
		state = OrbState.charging;
		arrow.enabled = false;
		delayedEnable = true;
		framesUntilEnable = 1;
	}

	public bool killsOnContact()
	{
		return orbType == OrbType.orb;
	}

	public void ApplyBeam(DetPhysics.BeamBody beamBody)
	{
		if (orbType != OrbType.beam)
		{
			beamCharge01 = Fix.Zero;
			orbType = OrbType.beam;
			isFiringBeam = false;
			beamColors = beamBody.colors;
			updateColor();
		}
		beamCharge01 += beamChargeRate01 * GameTime.FixedTimeStep;
		if (beamCharge01 > Fix.One)
		{
			beamCharge01 = Fix.One;
			isFiringBeam = true;
		}
	}
}
