public class Rope : MonoUpdatable
{
	public float ropeVisualWidth;

	private FixTransform fixTrans;

	private MeshFilter meshFilter;

	private MeshRenderer meshRen;

	public Sprite sprite;

	public float uvSpacing = 1f;

	public UnityEngine.Color color;

	private RopeBody ropeBody;

	public int nrOfSegments = 5;

	public static uint ropeNumber;

	public int maxRopesPerPlayer;

	private Vec2 fireDirection;

	private int startSegCount;

	public float darkness01;

	private Fix timeSinceLastReelOut;

	private bool reelIn;

	public Fix ReelOutSpeed;

	private Fix timePassed;

	private Vec2 prevSegmentVel;

	public int segmentsAffectedByReelOut;

	public int segmentWaveLength;

	public Fix reelOutSegmentSpeed;

	public Fix angularSprinklerSpeed;

	public Fix sprinklerSpeed;

	public Fix maxTravelTime;

	public bool hookArrived;

	private bool meshDirty;

	public Fix playerMass01;

	private void Awake()
	{
		fixTrans = GetComponent<FixTransform>();
		meshFilter = GetComponent<MeshFilter>();
		meshRen = GetComponent<MeshRenderer>();
		Updater.RegisterUpdatable(this);
		meshRen.material.SetTexture("_MainTex", sprite.texture);
	}

	public override void Init()
	{
	}

	private void CheckIfDestroyed()
	{
		if (!base.IsDestroyed && !(meshFilter == null) && (ropeBody == null || !ropeBody.enabled))
		{
			meshFilter.mesh = null;
			if (ropeBody != null)
			{
				ropeBody.enabled = false;
				ropeBody.disabledThisFrame = true;
				ropeBody.hasBeenDettached = true;
			}
			Updater.DestroyFix(base.gameObject);
		}
	}

	public RopeBody Initialize(Vec2 basePos, Vec2 playerPos, bool isGrounded, int playerId, Fix startingSegmentSeparation, Material playerMaterial)
	{
		if (Constants.leveltype == LevelType.grass)
		{
			meshRen.material.color = UnityEngine.Color.black;
		}
		else
		{
			meshRen.material.color = color;
		}
		DetPhysics detPhysics = DetPhysics.Get();
		ropeBody = detPhysics.ropes.AddRope(nrOfSegments);
		ropeBody.timeSinceHookArrived = -Fix.One;
		ropeBody.ownerId = (byte)playerId;
		ropeNumber++;
		ropeBody.number = ropeNumber;
		startSegCount = nrOfSegments;
		ropeBody.mass_start = Fix.Zero;
		ropeBody.mass_end = Fix.Zero;
		ropeBody.timeSinceHookArrived = -Fix.One;
		ropeBody.hasBeenDettached = false;
		ropeBody.segmentSeparation = startingSegmentSeparation;
		int num = 0;
		int num2 = 0;
		uint num3 = 10000u;
		for (int i = 0; i < detPhysics.ropes.ropeBodies.Length; i++)
		{
			if (detPhysics.ropes.ropeBodies[i].enabled && detPhysics.ropes.ropeBodies[i].ownerId == playerId)
			{
				num++;
				if (detPhysics.ropes.ropeBodies[i].number < num3)
				{
					num2 = i;
					num3 = detPhysics.ropes.ropeBodies[i].number;
				}
			}
		}
		if (num > maxRopesPerPlayer)
		{
			detPhysics.ropes.ropeBodies[num2].disabledThisFrame = true;
			detPhysics.ropes.ropeBodies[num2].enabled = false;
			detPhysics.ropes.ropeBodies[num2].number = 0u;
			detPhysics.ropes.ropeBodies[num2].ownerId = 0;
		}
		if (!isGrounded)
		{
			ropeBody.timeInAir_end = (Fix)100L;
		}
		fixTrans.position = basePos;
		base.transform.position = (Vector3)basePos;
		UnityEngine.Debug.DrawLine((Vector2)basePos, (Vector2)playerPos, UnityEngine.Color.red, 5f);
		for (int j = 0; j < ropeBody.segmentCount; j++)
		{
			ropeBody.segment[j] = basePos + (playerPos - basePos) * (Fix)j / (Fix)ropeBody.segmentCount;
			ropeBody.segmentPrev[j] = ropeBody.segment[j];
			UnityEngine.Debug.DrawRay((Vector2)ropeBody.segment[j], Vector2.right, UnityEngine.Color.green, 100f);
		}
		ropeBody.ropeMesh.UpdateMesh(ropeBody, Constants.leveltype);
		ropeBody.ropeMesh.SetMeshValues(ropeBody.segmentCount);
		return ropeBody;
	}

	private bool isOffscreen(Vec2 p)
	{
		if (!(p.x > SceneBounds.BlastZone_XMax) && !(p.x < SceneBounds.BlastZone_XMin) && !(p.y > SceneBounds.BlastZone_YMax))
		{
			return p.y < SceneBounds.WaterHeight;
		}
		return true;
	}

	private bool isFarOffscreen(Vec2 p)
	{
		Fix fix = (Fix)2L;
		if (!(p.x > SceneBounds.BlastZone_XMax * fix) && !(p.x < SceneBounds.BlastZone_XMin * fix) && !(p.y > SceneBounds.BlastZone_YMax * fix))
		{
			return p.y < SceneBounds.WaterHeight * fix;
		}
		return true;
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (ropeBody != null && ropeBody.enabled)
		{
			timeSinceLastReelOut += SimDeltaTime;
			timePassed += SimDeltaTime;
			if (hookArrived)
			{
				reelIn = true;
			}
			else if (timePassed > maxTravelTime)
			{
				ropeBody.enabled = false;
				ropeBody.disabledThisFrame = true;
				ropeBody.hasBeenDettached = true;
				ropeBody = null;
				CheckIfDestroyed();
				return;
			}
			if (ropeBody.timeSinceHookArrived >= 0L)
			{
				ropeBody.timeSinceHookArrived += SimDeltaTime;
			}
			if (!reelIn)
			{
				Vec2 vec = Vec2.NormalizedSafe(ropeBody.segment[ropeBody.segmentCount - 1] - ropeBody.segment[0]);
				Vec2 vec2 = Vec2.MulByI(vec) * sprinklerSpeed * SimDeltaTime;
				int num = 0;
				bool flag = true;
				for (int i = 0; i < ropeBody.segmentCount - 1; i++)
				{
					if (num >= segmentWaveLength)
					{
						flag = !flag;
						num = 0;
					}
					num++;
					if (i >= ropeBody.segmentCount - segmentsAffectedByReelOut)
					{
						Vec2 vec3 = (flag ? Fix.One : (-Fix.One)) * vec2;
						UnityEngine.Debug.DrawRay((Vector3)ropeBody.segment[i], (Vector3)vec3, UnityEngine.Color.green);
						Vec2 vec4 = vec * reelOutSegmentSpeed * SimDeltaTime;
						vec4 += vec3 * sprinklerSpeed * SimDeltaTime;
						ropeBody.segment[i] += vec4;
					}
				}
				if (timeSinceLastReelOut > ReelOutSpeed)
				{
					timeSinceLastReelOut = Fix.Zero;
					Vec2 vec5 = ropeBody.segment[ropeBody.segmentCount - 2] - ropeBody.segment[ropeBody.segmentCount - 1];
					Vec2 spawnPos = ropeBody.segment[ropeBody.segmentCount - 1] + vec5 * (Fix)0.5;
					if (!ropeBody.SpawnAdditionalSegment(spawnPos))
					{
						reelIn = true;
					}
				}
			}
			ropeBody.transformPos = base.transform.position;
			if ((isOffscreen(ropeBody.segment[0]) && isOffscreen(ropeBody.segment[ropeBody.segmentCount - 1])) || isFarOffscreen(ropeBody.segment[0]) || isFarOffscreen(ropeBody.segment[ropeBody.segmentCount - 1]))
			{
				ropeBody.enabled = false;
				ropeBody.disabledThisFrame = true;
			}
			meshDirty = true;
		}
		CheckIfDestroyed();
	}

	private void Update()
	{
		if (meshDirty)
		{
			if (ropeBody.enabled)
			{
				ropeBody.ropeMesh.SetMeshValues(ropeBody.segmentCount);
				meshFilter.mesh = ropeBody.ropeMesh.mesh;
			}
			meshDirty = false;
		}
	}

	private void OnDrawGizmos()
	{
		if (fixTrans != null && ropeBody != null)
		{
			Vec2 vec = ropeBody.segment[0];
			Gizmos.color = UnityEngine.Color.white;
			for (int i = 1; i < ropeBody.segmentCount; i++)
			{
				Gizmos.DrawLine((Vector3)vec, (Vector3)ropeBody.segment[i]);
				vec = ropeBody.segment[i];
			}
			Vector3 vector = (Vector3)ropeBody.segment[0];
			Vector3 vector2 = (Vector3)ropeBody.segment[ropeBody.segmentCount - 1];
			Gizmos.color = UnityEngine.Color.red;
			Gizmos.DrawLine(vector, vector + (Vector3)ropeBody.force_start * 1f);
			Gizmos.color = UnityEngine.Color.blue;
			Gizmos.DrawLine(vector2, vector2 + (Vector3)ropeBody.force_end * 1f);
			Gizmos.color = UnityEngine.Color.white;
		}
		for (int j = 0; j < ropeBody.segmentCount; j++)
		{
			Gizmos.DrawWireSphere((Vector3)ropeBody.segment[j], 0.1f);
		}
	}
}
public class RopeAttachment : MonoUpdatable, IPlatformAttachable
{
	private FixTransform fixTrans;

	private bool isPlatformAttachment;

	private SpriteRenderer spriteRen;

	[NonSerialized]
	public BlackHole blackHole;

	public Fix pullStr;

	public Fix platformPullStr;

	public Fix boulderPullStr;

	public Fix platformHeavinessScaling;

	public Fix stretchBeforeBreak;

	public Fix stretchBeforeBreak_platform;

	private int reelInFrame;

	private Vec2 prevVel;

	private BoplBody body;

	private StickyRoundedRectangle platform;

	private RopeBody ropeBody;

	[HideInInspector]
	public bool topAttachment;

	public Fix platformMass01;

	private Fix effectivePlatformPullStr;

	private FixTransform parentObject;

	private Vec2 unscaledParentOffset;

	private Vec2 baseUp;

	public Fix nonPlatformMass;

	public Fix SurfaceOffset { get; set; }

	public Fix LocalPlatformPosition { get; set; }

	public FixTransform GetFixTrans()
	{
		return fixTrans;
	}

	public bool IsPlatformAttachment()
	{
		if (isPlatformAttachment)
		{
			if (platform != null && !platform.IsDestroyed)
			{
				return platform.gameObject.activeInHierarchy;
			}
			return false;
		}
		return false;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (ropeBody == null || !ropeBody.enabled)
		{
			Updater.DestroyFix(base.gameObject);
			return;
		}
		if (isPlatformAttachment && (platform == null || platform.IsDestroyed || !platform.gameObject.activeInHierarchy))
		{
			Deattach();
			return;
		}
		if (!isPlatformAttachment && (parentObject == null || parentObject.IsDestroyed || !parentObject.gameObject.activeInHierarchy))
		{
			Deattach();
			return;
		}
		int num = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
		int num2 = (topAttachment ? 1 : (ropeBody.segmentCount - 2));
		if (ropeBody != null && ropeBody.enabled && ropeBody.hookHasArrived && !ropeBody.hasBeenDettached && !GameTime.IsTimeStopped())
		{
			if (body != null)
			{
				Vec2 f = (ropeBody.segment[num] - ropeBody.segment[num2]) * (isPlatformAttachment ? effectivePlatformPullStr : pullStr);
				body.AddForceAtPosition(f, fixTrans.position);
			}
			if (blackHole != null && !blackHole.IsDestroyed)
			{
				if (blackHole.GetMass() > Fix.Zero)
				{
					reelInFrame++;
					if (((reelInFrame > 60 && reelInFrame % 3 == 0) || (reelInFrame <= 60 && reelInFrame % 8 == 0) || ropeBody.segmentCount < 8) && !ropeBody.ReelInSegment(3))
					{
						fixTrans.position = blackHole.dCircle.position;
						int num3 = (topAttachment ? (ropeBody.segmentCount - 1) : 0);
						ropeBody.segment[num3] = blackHole.dCircle.position;
					}
				}
				else
				{
					blackHole = null;
					Deattach();
				}
			}
		}
		if (isPlatformAttachment)
		{
			ropeBody.SetTimeInAir(Fix.Zero, topAttachment);
			ropeBody.SetMass01(platformMass01, topAttachment, platformHeavinessScaling / body.InverseMass);
			ropeBody.SetForce(Vec2.zero, topAttachment);
			RepositionOnParent();
			num = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
			ropeBody.segment[num] = fixTrans.position;
		}
		else
		{
			fixTrans.position = parentObject.position + parentObject.up * unscaledParentOffset.y * parentObject.Scale + parentObject.right * unscaledParentOffset.x * parentObject.Scale;
		}
		Fix fix = (isPlatformAttachment ? stretchBeforeBreak_platform : stretchBeforeBreak);
		for (int i = 0; i < ropeBody.segmentCount - 2; i++)
		{
			if (Vec2.SqrMagnitude(ropeBody.segment[i] - ropeBody.segment[i + 1]) > fix)
			{
				Deattach();
				break;
			}
		}
	}

	private void Deattach()
	{
		if (ropeBody != null)
		{
			ropeBody.SetMass01((Fix)0.5, topAttachment, Fix.One);
			ropeBody.SetTimeInAir((Fix)100L, topAttachment);
			ropeBody.SetForce(Vec2.zero, topAttachment);
			ropeBody.Dettach(topAttachment);
		}
		Updater.DestroyFix(base.gameObject);
	}

	public override void LateUpdateSim(Fix SimDeltaTime)
	{
		if (isPlatformAttachment)
		{
			RepositionOnParent();
		}
		else
		{
			fixTrans.position = parentObject.position + parentObject.up * unscaledParentOffset.y * parentObject.Scale + parentObject.right * unscaledParentOffset.x * parentObject.Scale;
		}
		int num = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
		ropeBody.segment[num] = fixTrans.position;
	}

	public RopeBody GetInitializedRopeBody()
	{
		return ropeBody;
	}

	public StickyRoundedRectangle GetPlatformParent()
	{
		return platform;
	}

	public void AttachToPlatform(Vec2 pos, StickyRoundedRectangle platform, RopeBody ropeBody, bool topAttachment)
	{
		if (platform.CompareTag("boulder"))
		{
			effectivePlatformPullStr = boulderPullStr;
		}
		else
		{
			effectivePlatformPullStr = platformPullStr;
		}
		LocalPlatformPosition = platform.LocalPlayerPosFromPos(pos, Fix.Zero);
		this.platform = platform;
		this.ropeBody = ropeBody;
		this.topAttachment = topAttachment;
		body = platform.GetGroundBody();
		RepositionOnParent();
		prevVel = body.velocity;
		isPlatformAttachment = true;
	}

	public void AttachToNonPlatform(FixTransform parentObject, Vec2 unScaledOffset, RopeBody ropeBody, bool topAttachment)
	{
		effectivePlatformPullStr = platformPullStr;
		unscaledParentOffset = unScaledOffset;
		this.parentObject = parentObject;
		platform = null;
		this.ropeBody = ropeBody;
		this.topAttachment = topAttachment;
		isPlatformAttachment = false;
		baseUp = parentObject.up;
		body = parentObject.GetComponent<BoplBody>();
		ropeBody.SetTimeInAir(Fix.One, topAttachment);
		ropeBody.SetMass01(nonPlatformMass, topAttachment, parentObject.Scale);
		ropeBody.SetForce(Vec2.zero, topAttachment);
	}

	public void RepositionOnParent()
	{
		if (!(platform == null) && !platform.IsDestroyed && !(platform.GetGroundBody() == null) && platform.GetGroundBody().HasBeenInitialized)
		{
			Vec2 vec = platform.PositionFromLocalPlayerPos(LocalPlatformPosition, Fix.Zero);
			fixTrans.position = vec;
			base.transform.position = (Vector3)vec;
		}
	}
}
public class RopeHook : MonoUpdatable, ICollisionCallback
{
	private DPhysicsCircle hitbox;

	private FixTransform fixTrans;

	public ParticleSystem onHitParticlePrefab;

	public int segmentsAffectedBySpeed = 8;

	public Fix segmentSpeedFalloff01;

	public Fix timeUntilFall;

	private Fix timePassed;

	private Vec2 velocity;

	private int endPlayerId;

	private bool topAttachment;

	private RopeBody ropeBody;

	private RopeAttachment ropeAttachment;

	private Rope rope;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		hitbox = GetComponent<DPhysicsCircle>();
		fixTrans = GetComponent<FixTransform>();
		ropeAttachment = GetComponent<RopeAttachment>();
		hitbox.RegisterCollisionCallback(this);
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (!(this == null) && !base.IsDestroyed)
		{
			ropeBody.SetTimeInAir(Fix.Zero, topAttachment);
			Fix fix = segmentSpeedFalloff01;
			for (int i = 2; i < ropeBody.segmentCount && i < segmentsAffectedBySpeed; i++)
			{
				ropeBody.segment[ropeBody.segmentCount - i] += velocity * SimDeltaTime * fix;
				fix *= segmentSpeedFalloff01;
			}
			timePassed += SimDeltaTime;
			if (timePassed > timeUntilFall)
			{
				Updater.DestroyFix(rope.gameObject);
				Updater.DestroyFix(base.gameObject);
				ropeBody.enabled = false;
				ropeBody.disabledThisFrame = true;
			}
			else
			{
				hitbox.position += velocity * SimDeltaTime;
			}
		}
	}

	public void Initialize(RopeBody ropeBody, bool topAttachment, Vec2 velocity, Rope rope, int endPlayerId)
	{
		this.endPlayerId = endPlayerId;
		this.ropeBody = ropeBody;
		this.velocity = velocity;
		this.topAttachment = topAttachment;
		this.rope = rope;
		if (Constants.leveltype == LevelType.grass)
		{
			ropeAttachment.GetComponent<SpriteRenderer>().color = UnityEngine.Color.black;
		}
		else
		{
			ropeAttachment.GetComponent<SpriteRenderer>().color = UnityEngine.Color.white;
		}
		hitbox.ManualInit();
		ropeAttachment.AttachToNonPlatform(fixTrans, Vec2.zero, ropeBody, topAttachment);
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (this == null || base.IsDestroyed || ropeBody == null || !ropeBody.enabled)
		{
			return;
		}
		Vec2 vec = collision.collider.Pos();
		if (collision.layer == LayerMask.NameToLayer("LethalTerrain") || collision.layer == LayerMask.NameToLayer("NonLethalTerrain") || collision.layer == LayerMask.NameToLayer("wall"))
		{
			if (!collision.collider.OverlapPoint(fixTrans.position))
			{
				return;
			}
			vec = fixTrans.position;
		}
		else
		{
			UnityEngine.Debug.DrawRay((Vector3)fixTrans.position, Vector2.up * 2f, UnityEngine.Color.cyan, 10f);
			UnityEngine.Debug.DrawRay((Vector3)fixTrans.position, Vector2.right * 2f, UnityEngine.Color.cyan, 10f);
			UnityEngine.Debug.DrawRay((Vector3)fixTrans.position, -Vector2.up * 2f, UnityEngine.Color.cyan, 10f);
			UnityEngine.Debug.DrawRay((Vector3)fixTrans.position, -Vector2.right * 2f, UnityEngine.Color.cyan, 10f);
		}
		if (collision.layer == LayerMask.NameToLayer("Player"))
		{
			IPlayerIdHolder component = collision.colliderPP.fixTrans.GetComponent<IPlayerIdHolder>();
			if (component == null || component.GetPlayerId() == endPlayerId || component.GetPlayerId() == ropeBody.ownerId)
			{
				return;
			}
		}
		UnityEngine.Object.Instantiate(onHitParticlePrefab, (Vector2)collision.contactPoint, Quaternion.identity).transform.up = ((Vector2)base.transform.position - (Vector2)collision.contactPoint).normalized;
		if (rope != null)
		{
			rope.hookArrived = true;
		}
		if (collision.layer == LayerMask.NameToLayer("wall"))
		{
			ropeBody.mass_start = Fix.One;
			ropeBody.force_start = Vec2.zero;
			if (ropeBody.timeSinceHookArrived < 0L)
			{
				ropeBody.timeSinceHookArrived = Fix.Zero;
			}
			AudioManager.Get().Play("hookshotOnHit");
			ropeAttachment.AttachToPlatform(fixTrans.position, collision.colliderPP.fixTrans.GetComponent<StickyRoundedRectangle>(), ropeBody, topAttachment: true);
		}
		else if (collision.layer == LayerMask.NameToLayer("Player"))
		{
			AudioManager.Get().Play("hookshotHitPlayer");
			PlayerBody component2 = collision.colliderPP.fixTrans.GetComponent<PlayerBody>();
			if (!(component2 == null))
			{
				if (component2.ropeBody != null && component2.ropeBody.number != ropeBody.number)
				{
					component2.ropeBody.Dettach(topAttachment: true);
					component2.ropeBody.Dettach(topAttachment: false);
					component2.ropeBody = null;
				}
				component2.AttachRope(ropeBody, topAttachment: true);
				if (ropeBody.timeSinceHookArrived < 0L)
				{
					ropeBody.timeSinceHookArrived = Fix.Zero;
				}
				Updater.DestroyFix(base.gameObject);
				return;
			}
			ropeBody.mass_start = Fix.One;
			ropeBody.force_start = Vec2.zero;
			Vec2 v = vec - collision.colliderPP.fixTrans.position;
			Vec2 u = new Vec2(-collision.colliderPP.fixTrans.rotation);
			v = Vec2.ComplexMul(v, u) / collision.colliderPP.fixTrans.Scale;
			ropeAttachment.AttachToNonPlatform(collision.colliderPP.fixTrans, v, ropeBody, topAttachment: true);
			if (ropeBody.timeSinceHookArrived < 0L)
			{
				ropeBody.timeSinceHookArrived = Fix.Zero;
			}
		}
		else
		{
			if (collision.layer != LayerMask.NameToLayer("LethalTerrain") && collision.layer != LayerMask.NameToLayer("NonLethalTerrain") && collision.layer != LayerMask.NameToLayer("Projectile") && collision.layer != LayerMask.NameToLayer("item") && collision.layer != LayerMask.NameToLayer("RigidBodyAffector") && collision.layer != LayerMask.NameToLayer("orb"))
			{
				return;
			}
			ropeBody.mass_start = Fix.One;
			ropeBody.force_start = Vec2.zero;
			AudioManager.Get().Play("hookshotOnHit");
			Vec2 v2 = vec - collision.colliderPP.fixTrans.position;
			Vec2 u2 = new Vec2(-collision.colliderPP.fixTrans.rotation);
			v2 = Vec2.ComplexMul(v2, u2) / collision.colliderPP.fixTrans.Scale;
			ropeAttachment.AttachToNonPlatform(collision.colliderPP.fixTrans, v2, ropeBody, topAttachment: true);
			ropeAttachment.blackHole = collision.colliderPP.fixTrans.GetComponent<BlackHole>();
			if (ropeBody.timeSinceHookArrived < 0L)
			{
				ropeBody.timeSinceHookArrived = Fix.Zero;
			}
		}
		if (hitbox != null && !hitbox.IsDestroyed)
		{
			Updater.DestroyFix(hitbox);
		}
		if (!base.IsDestroyed)
		{
			Updater.DestroyFix(this);
		}
	}

	public override void Init()
	{
	}
}
public class ScaleBasedOnCameraWidth : MonoBehaviour
{
	public float min = 1.3f;

	public float max = 2f;

	public float scaleSpeed = 0.7f;

	public float baseSize = 1.3f;

	private Camera main;

	private void Start()
	{
		main = Camera.main;
	}

	private void Update()
	{
		if (main != null)
		{
			float aspect = main.aspect;
			float num = Mathf.Lerp(min, max, aspect * scaleSpeed);
			base.transform.localScale = new Vector3(baseSize + num, base.transform.localScale.y, base.transform.localScale.z);
		}
	}
}
public class ScaleBGBasedOnScreenRes : MonoBehaviour
{
	private float maxAspRatio = 1.8f;

	public float scaleX = 1.2f;

	private Camera main;

	private void Awake()
	{
		main = Camera.main;
		UpdateResolution();
	}

	private void Start()
	{
		UpdateResolution();
	}

	public void UpdateResolution()
	{
		if (main != null)
		{
			if (main.aspect > maxAspRatio)
			{
				base.transform.localScale = new Vector3(scaleX, 1f, 1f);
			}
			else
			{
				base.transform.localScale = Vector3.one;
			}
		}
	}
}
public class ScaleParticleShape : MonoBehaviour
{
	public float ScalingSpeed = 1f;

	private ParticleSystem particle;

	private void Awake()
	{
		particle = GetComponent<ParticleSystem>();
	}

	private void Update()
	{
		ParticleSystem.ShapeModule shape = particle.shape;
		shape.scale = base.transform.lossyScale * ScalingSpeed;
	}
}
public class AchievementHandler : MonoBehaviour
{
	public enum AchievementEnum
	{
		WinAGameWith3Dashes,
		WinAGameAgainstAPlayerWith3Dashes,
		WinAGameWithoutDoingAnything,
		PlayAGameWhereEveryoneOnlyPickedBlinkGuns,
		PlayAGameWhereEveryPlayerSelectedOnlyRANDOM,
		CloneYourself16Times,
		GrowthRayYourself,
		GetAKillWithTheEngineAbility,
		LandALongRangeArrow,
		BuildATowerOfMachoSlime,
		WinAGameWithNoOffensiveAbilities,
		StayInDrillFormFor10Seconds,
		MoonwalkLikeABoss,
		CreateAVeryBigBlackHole,
		CreateAWhiteHole,
		create10consecutiveSmokeExplosions,
		ClearTheTutorialInLessThan9Seconds,
		HoldAGrenadeUntilItExplodes,
		KillTwoPlayersAtOnce,
		KillThreePlayersAtTheSameTime,
		HaveAGameEndInA4personDraw,
		Get2KillsRightAfterATimeStopHasEnded,
		Get2KillsWith1UseOfRock,
		WinA1v3,
		Reach100Wins,
		GustAGrenadeIntoAPlayer,
		EatAPlayer,
		Eat3Players
	}

	private static string[] achievementNames = new string[28]
	{
		"WinAGameWith3Dashes", "WinAGameAgainstAPlayerWith3Dashes", "WinAGameWithoutDoingAnything", "PlayAGameWhereEveryoneOnlyPickedBlinkGuns", "PlayAGameWhereEveryPlayerSelectedOnlyRANDOM", "CloneYourself16Times", "GrowthRayYourself", "GetAKillWithTheEngineAbility", "LandALongRangeArrow", "BuildATowerOfMachoSlime",
		"WinAGameWithNoOffensiveAbilities", "StayInDrillFormFor10Seconds", "MoonwalkLikeABoss", "CreateAVeryBigBlackHole", "CreateAWhiteHole", "create10consecutiveSmokeExplosions", "ClearTheTutorialInLessThan9Seconds", "HoldAGrenadeUntilItExplodes", "KillTwoPlayersAtOnce", "KillThreePlayersAtTheSameTime",
		"HaveAGameEndInA4personDraw", "Get2KillsRightAfterATimeStopHasEnded", "Get2KillsWith1UseOfRock", "WinA1v3", "Reach100Wins", "GustAGrenadeIntoAPlayer", "EatAPlayer", "Eat3Players"
	};

	private static Achievement[] achievements = new Achievement[28];

	private static bool[] isAchieved = new bool[28];

	public static Fix timeInDrillBeforeAcheivementIsAwarded = (Fix)10L;

	private static bool isInitialized;

	public bool isTestStage;

	private Player.InputProfile[] inputProfiles;

	private bool[] playerIsAfk;

	public NamedSpriteList abilityIcons;

	private static AchievementHandler instance;

	public int lastSmokeExplosionCasterPlayerId;

	private int smokeExplosions;

	private float timeSinceLastSmokeExplosion;

	private const float maxTimeInBetweenExplosions = 0.4f;

	private int timeStopperId;

	private int killsWhenTimeStopEnded;

	private float timeSinceTimeStopEnded = 100000000f;

	private static int[] killsThisFrame = new int[4];

	public static void InitializeAchievements()
	{
		if (isInitialized)
		{
			return;
		}
		isInitialized = true;
		foreach (Achievement achievement in SteamUserStats.Achievements)
		{
			for (int i = 0; i < achievementNames.Length; i++)
			{
				if (achievementNames[i].Equals(achievement.Identifier))
				{
					isAchieved[i] = achievement.State;
					achievements[i] = achievement;
				}
			}
		}
	}

	public static void TryAwardAchievement(AchievementEnum achievement)
	{
		if (!isAchieved[(int)achievement] && SteamManager.instance.dlc.HasDLC() && !GameLobby.isPlayingAReplay)
		{
			achievements[(int)achievement].Trigger();
			isAchieved[(int)achievement] = true;
		}
	}

	public static bool IsAchieved(AchievementEnum achievement)
	{
		return isAchieved[(int)achievement];
	}

	private void Awake()
	{
		instance = this;
	}

	private void Start()
	{
		if (isTestStage)
		{
			InitializeAchievements();
		}
		timeSinceTimeStopEnded = 10000000f;
		if (!IsAchieved(AchievementEnum.WinAGameWithoutDoingAnything))
		{
			PlayerHandler playerHandler = PlayerHandler.Get();
			inputProfiles = new Player.InputProfile[playerHandler.PlayerList().Count];
			playerIsAfk = new bool[playerHandler.PlayerList().Count];
			for (int i = 0; i < playerHandler.PlayerList().Count; i++)
			{
				inputProfiles[i] = new Player.InputProfile();
				inputProfiles[i].UsesMouse = playerHandler.PlayerList()[i].GetRawInputProfile().UsesMouse;
				playerIsAfk[i] = true;
			}
		}
	}

	private void onStartedAGame()
	{
		PlayerHandler playerHandler = PlayerHandler.Get();
		List<Player> list = playerHandler.PlayerList();
		if (playerHandler.NumberOfTeams() <= 1)
		{
			return;
		}
		if (!IsAchieved(AchievementEnum.PlayAGameWhereEveryoneOnlyPickedBlinkGuns))
		{
			bool flag = true;
			for (int i = 0; i < list.Count; i++)
			{
				List<Sprite> list2 = list[i].AbilityIcons;
				if (list2.Count != 3)
				{
					flag = false;
				}
				for (int j = 0; j < list2.Count; j++)
				{
					if (list2[j] == null || !(abilityIcons.sprites[abilityIcons.IndexOf(list2[j])].name == "Blink gun"))
					{
						flag = false;
						break;
					}
				}
			}
			if (flag)
			{
				TryAwardAchievement(AchievementEnum.PlayAGameWhereEveryoneOnlyPickedBlinkGuns);
			}
		}
		if (IsAchieved(AchievementEnum.PlayAGameWhereEveryPlayerSelectedOnlyRANDOM))
		{
			return;
		}
		bool flag2 = true;
		for (int k = 0; k < list.Count; k++)
		{
			List<Sprite> list3 = list[k].AbilityIcons;
			_ = list[k].Abilities;
			if (list3.Count != 3)
			{
				flag2 = false;
			}
			for (int l = 0; l < list3.Count; l++)
			{
				if (list3[l] == null || !(abilityIcons.sprites[abilityIcons.IndexOf(list3[l])].name == "Random"))
				{
					flag2 = false;
					break;
				}
			}
		}
		if (flag2)
		{
			TryAwardAchievement(AchievementEnum.PlayAGameWhereEveryPlayerSelectedOnlyRANDOM);
		}
	}

	private int numberOfPlayersInTeam(int team)
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		int num = 0;
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].Team == team)
			{
				num++;
			}
		}
		return num;
	}

	private void OnWinRound()
	{
		PlayerHandler playerHandler = PlayerHandler.Get();
		List<Player> list = playerHandler.PlayerList();
		int num = playerHandler.NumberOfTeams();
		Player player = null;
		if (num == 1)
		{
			return;
		}
		bool flag = false;
		for (int i = 0; i < list.Count; i++)
		{
			Player player2 = list[i];
			if (player2.WonThisRound && player2.IsLocalPlayer)
			{
				flag = true;
				player = player2;
			}
		}
		bool flag2 = false;
		int num2 = -1;
		for (int j = 0; j < list.Count; j++)
		{
			Player player3 = list[j];
			if (player3.WonThisRound)
			{
				if (num2 != player3.Team && num2 != -1)
				{
					flag2 = true;
				}
				num2 = player3.Team;
			}
		}
		if (!flag)
		{
			return;
		}
		if (!IsAchieved(AchievementEnum.Reach100Wins))
		{
			for (int k = 0; k < list.Count; k++)
			{
				if (list[k].WonThisRound && list[k].IsLocalPlayer && list[k].GamesWon >= 100)
				{
					TryAwardAchievement(AchievementEnum.Reach100Wins);
				}
			}
		}
		if (flag2)
		{
			return;
		}
		if (!IsAchieved(AchievementEnum.WinA1v3) && num == 2 && playerHandler.NumberOfPlayers() == 4 && numberOfPlayersInTeam(player.Team) == 1)
		{
			TryAwardAchievement(AchievementEnum.WinA1v3);
		}
		if (!IsAchieved(AchievementEnum.WinAGameWithoutDoingAnything))
		{
			for (int l = 0; l < playerIsAfk.Length; l++)
			{
				Player player4 = list[l];
				if (playerIsAfk[l] && player4.WonThisRound && numberOfPlayersInTeam(player4.Team) == 1)
				{
					TryAwardAchievement(AchievementEnum.WinAGameWithoutDoingAnything);
					break;
				}
			}
		}
		if (!IsAchieved(AchievementEnum.WinAGameWith3Dashes))
		{
			List<Player> list2 = playerHandler.PlayerList();
			bool flag3 = true;
			for (int m = 0; m < list2.Count; m++)
			{
				if (!list2[m].WonThisRound)
				{
					continue;
				}
				List<Sprite> list3 = list2[m].AbilityIcons;
				if (list3.Count != 3)
				{
					flag3 = false;
				}
				for (int n = 0; n < list3.Count; n++)
				{
					if (list3[n] == null || !(abilityIcons.sprites[abilityIcons.IndexOf(list3[n])].name == "Dash"))
					{
						flag3 = false;
						break;
					}
				}
				if (flag3)
				{
					TryAwardAchievement(AchievementEnum.WinAGameWith3Dashes);
					break;
				}
			}
		}
		if (!IsAchieved(AchievementEnum.WinAGameAgainstAPlayerWith3Dashes))
		{
			List<Player> list4 = playerHandler.PlayerList();
			for (int num3 = 0; num3 < list4.Count; num3++)
			{
				if (list4[num3].IsAlive)
				{
					continue;
				}
				List<Sprite> list5 = list4[num3].AbilityIcons;
				bool flag4 = list5.Count == 3;
				for (int num4 = 0; num4 < list5.Count; num4++)
				{
					if (list5[num4] == null || !(abilityIcons.sprites[abilityIcons.IndexOf(list5[num4])].name == "Dash"))
					{
						flag4 = false;
					}
				}
				if (flag4)
				{
					TryAwardAchievement(AchievementEnum.WinAGameAgainstAPlayerWith3Dashes);
				}
			}
		}
		if (IsAchieved(AchievementEnum.WinAGameWithNoOffensiveAbilities))
		{
			return;
		}
		List<Player> list6 = playerHandler.PlayerList();
		bool flag5 = true;
		int num5 = 0;
		for (int num6 = 0; num6 < list6.Count; num6++)
		{
			if (list6[num6].IsAlive)
			{
				num5++;
			}
		}
		for (int num7 = 0; num7 < list6.Count; num7++)
		{
			if (!list6[num7].WonThisRound || num5 != 1)
			{
				continue;
			}
			List<Sprite> list7 = list6[num7].AbilityIcons;
			for (int num8 = 0; num8 < list7.Count; num8++)
			{
				if (list7[num8] == null || abilityIcons.sprites[abilityIcons.IndexOf(list7[num8])].isOffensiveAbility)
				{
					flag5 = false;
					break;
				}
			}
			if (flag5)
			{
				TryAwardAchievement(AchievementEnum.WinAGameWithNoOffensiveAbilities);
				break;
			}
		}
	}

	public static void CheckAchievementsOnWinRound()
	{
		instance.OnWinRound();
	}

	public static void OnRoundEnded()
	{
		SteamManager.instance?.networkClient?.SaveReplay();
	}

	public static void OnStartedAGame()
	{
		instance.onStartedAGame();
	}

	public static void RegisterSmokeExplosion(int playerId)
	{
		instance.smokeExplosions++;
		instance.timeSinceLastSmokeExplosion = 0f;
		instance.lastSmokeExplosionCasterPlayerId = playerId;
	}

	private void Update()
	{
		if (GameSessionHandler.HasGameEnded())
		{
			return;
		}
		List<Player> list = PlayerHandler.Get().PlayerList();
		if (!IsAchieved(AchievementEnum.WinAGameWithoutDoingAnything))
		{
			for (int i = 0; i < list.Count; i++)
			{
				Player player = list[i];
				if (player.IsLocalPlayer)
				{
					if (!player.GetRawInputProfile().Equals_ignoringMousePos(inputProfiles[i]))
					{
						playerIsAfk[i] = false;
					}
					player.GetRawInputProfile().Clone(inputProfiles[i]);
				}
				else
				{
					playerIsAfk[i] = false;
				}
			}
		}
		if (!IsAchieved(AchievementEnum.CloneYourself16Times))
		{
			for (int j = 0; j < list.Count; j++)
			{
				if (list[j].IsLocalPlayer && list[j].playersAndClonesStillAlive >= 16)
				{
					TryAwardAchievement(AchievementEnum.CloneYourself16Times);
				}
			}
		}
		if (!IsAchieved(AchievementEnum.create10consecutiveSmokeExplosions))
		{
			timeSinceLastSmokeExplosion += Time.deltaTime;
			if (timeSinceLastSmokeExplosion > 0.4f)
			{
				smokeExplosions = 0;
			}
			Player player2 = PlayerHandler.Get().GetPlayer(lastSmokeExplosionCasterPlayerId);
			if (smokeExplosions >= 10 && PlayerHandler.Get().GetPlayer(lastSmokeExplosionCasterPlayerId) != null && player2 != null && player2.IsLocalPlayer)
			{
				TryAwardAchievement(AchievementEnum.create10consecutiveSmokeExplosions);
			}
		}
		if (!IsAchieved(AchievementEnum.KillThreePlayersAtTheSameTime) || !IsAchieved(AchievementEnum.KillTwoPlayersAtOnce))
		{
			for (int k = 0; k < killsThisFrame.Length; k++)
			{
				Player player3 = PlayerHandler.Get().GetPlayer(k + 1);
				if (killsThisFrame[k] >= 2 && player3 != null && player3.IsLocalPlayer)
				{
					TryAwardAchievement(AchievementEnum.KillTwoPlayersAtOnce);
				}
				if (killsThisFrame[k] >= 3 && player3 != null && player3.IsLocalPlayer)
				{
					TryAwardAchievement(AchievementEnum.KillThreePlayersAtTheSameTime);
				}
			}
			for (int l = 0; l < killsThisFrame.Length; l++)
			{
				killsThisFrame[l] = 0;
			}
		}
		if (IsAchieved(AchievementEnum.Get2KillsRightAfterATimeStopHasEnded))
		{
			return;
		}
		if (!GameTime.IsTimeStopped())
		{
			timeSinceTimeStopEnded += Time.deltaTime;
		}
		if (timeSinceTimeStopEnded < 1f)
		{
			Player player4 = PlayerHandler.Get().GetPlayer(timeStopperId);
			if (player4 != null && player4.IsLocalPlayer && player4.IsAlive && player4.Kills >= killsWhenTimeStopEnded + 2)
			{
				TryAwardAchievement(AchievementEnum.Get2KillsRightAfterATimeStopHasEnded);
			}
		}
	}

	public static void RegisterTimeStopEnded(int casterId)
	{
		instance.timeSinceTimeStopEnded = 0f;
		instance.timeStopperId = casterId;
		instance.killsWhenTimeStopEnded = PlayerHandler.Get().GetPlayer(casterId).Kills;
	}

	public static void RegisterKill(int playerId)
	{
		if (playerId >= 1 && playerId <= 4)
		{
			killsThisFrame[playerId - 1]++;
		}
	}
}
