[CreateAssetMenu(fileName = "Data", menuName = "2DAnimation/AnimationData", order = 1)]
public class AnimationData : ScriptableObject
{
	public int defaultFrameDuration;

	public Animation[] animations;

	public VAnimation[] velocityAnimations;

	public Animation2D[] animation2Ds;

	private Dictionary<string, SpriteFrame[]> spriteFrames = new Dictionary<string, SpriteFrame[]>();

	private Dictionary<string, VelocityFrame[]> velocityFrames = new Dictionary<string, VelocityFrame[]>();

	private Dictionary<string, Animation2DFrame[]> animation2DFrames = new Dictionary<string, Animation2DFrame[]>();

	private void OnEnable()
	{
		if (animations != null && animations.Length != 0)
		{
			for (int i = 0; i < animations.Length; i++)
			{
				spriteFrames.Add(animations[i].name, animations[i].animation);
			}
		}
		if (velocityAnimations != null && velocityAnimations.Length != 0)
		{
			for (int j = 0; j < velocityAnimations.Length; j++)
			{
				velocityFrames.Add(velocityAnimations[j].name, velocityAnimations[j].animation);
			}
		}
		if (animation2Ds != null && animation2Ds.Length != 0)
		{
			for (int k = 0; k < animation2Ds.Length; k++)
			{
				animation2DFrames.Add(animation2Ds[k].name, animation2Ds[k].animation2D);
			}
		}
	}

	public SpriteFrame[] GetAnimation(string animationName)
	{
		if (spriteFrames.TryGetValue(animationName, out var value))
		{
			return value;
		}
		throw new Exception("animation '" + animationName + " is not specified");
	}

	public VelocityFrame[] GetVelocityMap(string animationName)
	{
		if (velocityFrames.TryGetValue(animationName, out var value))
		{
			return value;
		}
		throw new Exception("Velocity animation '" + animationName + "' is not specified");
	}

	public Animation2DFrame[] Get2DAnimation(string animationName)
	{
		if (animation2DFrames.TryGetValue(animationName, out var value))
		{
			return value;
		}
		throw new Exception("2danimation '" + animationName + " is not specified");
	}
}
[RequireComponent(typeof(SpriteAnimator))]
public class PlayAnimation : MonoUpdatable
{
	public string animationToPlay;

	public string animationOnEnd;

	public AnimationData data;

	public bool SelfDestructOnAnimationEnd;

	public bool SelfDeactivateOnAnimationEnd;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
	}

	private void SelfDestruct()
	{
		Updater.DestroyFix(base.gameObject);
	}

	public override void Init()
	{
		SpriteAnimator component = GetComponent<SpriteAnimator>();
		if (SelfDestructOnAnimationEnd)
		{
			component.beginAnimThenDoAction(data.GetAnimation(animationToPlay), SelfDestruct);
		}
		else if (SelfDeactivateOnAnimationEnd)
		{
			component.beginAnimThenDoAction(data.GetAnimation(animationToPlay), delegate
			{
				base.gameObject.SetActive(value: false);
			});
		}
		else if (!string.IsNullOrEmpty(animationOnEnd))
		{
			component.beginAnimThenPlayAnim(data.GetAnimation(animationToPlay), data.GetAnimation(animationOnEnd));
		}
		else
		{
			component.beginAnimation(data.GetAnimation(animationToPlay));
		}
		component.childAnimationSuffix = string.Empty;
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}

	public override bool IsEnabled()
	{
		return false;
	}
}
