[RequireComponent(typeof(SpriteRenderer))]
public class SpriteAnimator : MonoUpdatable
{
	public enum AnimationType
	{
		looped,
		speedMapX,
		speedMapY,
		speedMapXY,
		rotationMap,
		nonlooped2D
	}

	public int defaultFrameDuration = 10;

	private IPlayerIdHolder idHolder;

	private int fps = 60;

	private SpriteFrame[] currentAnim;

	private int currentSpriteIndex;

	[NonSerialized]
	public SpriteRenderer spriteRen;

	private int currentSpritePos;

	private AnimationType animType;

	private SpriteFrame[] nextAnim;

	private bool swappedAnim;

	private Action animationSwappedCallBack;

	private SpeedContainer animatedBody;

	private VelocityFrame[][] currentVAnim;

	private Animation2DFrame[] animation2D;

	private int currentSpritePosY;

	private bool anim2DGoingRight;

	private int anim2DtargetAnim;

	private Fix[] XSpeeds;

	private Fix minXSpeed;

	private int animationSwapTiming;

	private bool callBackOnLastFrame;

	public bool AlwaysStopDuringTimeStop;

	private int curr2DAnimPos;

	private int currAnimIndex;

	[HideInInspector]
	public string childAnimationSuffix;

	public bool swappedAnimationThisUpdate => swappedAnim;

	public override void Init()
	{
	}

	public void Awake()
	{
		Updater.RegisterUpdatable(this);
		spriteRen = GetComponent<SpriteRenderer>();
		currentSpritePos = 0;
		currentSpriteIndex = 0;
		idHolder = GetComponentInParent<IPlayerIdHolder>();
	}

	public override void UpdateSim(Fix deltaTime)
	{
		if (GameTime.IsTimeStopped())
		{
			if (idHolder != null && !AlwaysStopDuringTimeStop)
			{
				Player player = PlayerHandler.Get().GetPlayer(idHolder.GetPlayerId());
				if (player != null && player.isProtectedFromTimeStop)
				{
					UpdateAnimations();
				}
			}
		}
		else
		{
			UpdateAnimations();
		}
	}

	public void UpdateAnimations()
	{
		if (animType == AnimationType.looped)
		{
			loopedAnimation();
		}
		else if (animType == AnimationType.speedMapY)
		{
			speedBasedAnimation();
		}
		else if (animType == AnimationType.speedMapXY)
		{
			speedBasedXYAnimation();
		}
		else if (animType == AnimationType.rotationMap)
		{
			rotationAnimation();
		}
		else if (animType == AnimationType.nonlooped2D)
		{
			Animation2D();
		}
	}

	private void SetFirstFrame(AnimationType type)
	{
		if (animType == AnimationType.looped)
		{
			spriteRen.sprite = currentAnim[0].sprite;
			spriteRen.flipX = currentAnim[0].frameDuration < 0;
		}
		else if (animType == AnimationType.speedMapY)
		{
			speedBasedAnimation();
		}
		else if (animType == AnimationType.rotationMap)
		{
			rotationAnimation();
		}
		else if (animType == AnimationType.nonlooped2D)
		{
			spriteRen.sprite = animation2D[currAnimIndex].animation[currentSpriteIndex].sprite;
		}
	}

	private void rotationAnimation()
	{
		int num = 45;
		Fix fix = (animatedBody.rotation + (Fix)num) % (Fix)360L;
		int num2 = 0;
		Fix zero = Fix.Zero;
		int num3 = 0;
		for (num3 = 0; num3 < currentAnim.Length; num3++)
		{
			zero += Fix.Abs((Fix)currentAnim[num3].frameDuration);
			if (zero > fix)
			{
				num2 = num3 - 1;
				if (num2 < 0)
				{
					num2 = currentAnim.Length - 1;
				}
				break;
			}
		}
		if (num3 == currentAnim.Length)
		{
			num2 = currentAnim.Length - 1;
		}
		spriteRen.sprite = currentAnim[num2].sprite;
		if (currentAnim[num2].frameDuration < 0)
		{
			spriteRen.flipY = true;
		}
		else
		{
			spriteRen.flipY = false;
		}
	}

	public void SkipToSpriteOfIndex(int index)
	{
		currentSpriteIndex = index;
		currentSpritePos = 0;
	}

	private void loopedAnimation()
	{
		if (currentAnim == null)
		{
			return;
		}
		_ = currentSpritePos;
		currentSpritePos++;
		swappedAnim = false;
		bool flag = false;
		for (int i = currentSpriteIndex; i < currentAnim.Length; i++)
		{
			int num = Math.Abs(currentAnim[currentSpriteIndex].frameDuration);
			if (currentSpritePos <= num)
			{
				break;
			}
			currentSpritePos -= num;
			currentSpriteIndex++;
			if (currentSpriteIndex >= currentAnim.Length)
			{
				flag = true;
				currentSpriteIndex = 0;
				if (nextAnim != null)
				{
					currentAnim = nextAnim;
					nextAnim = null;
					swappedAnim = true;
				}
			}
		}
		if (!(callBackOnLastFrame && flag))
		{
			spriteRen.sprite = currentAnim[currentSpriteIndex].sprite;
			spriteRen.flipX = currentAnim[currentSpriteIndex].frameDuration < 0;
		}
		if (flag && animationSwappedCallBack != null)
		{
			Action action = animationSwappedCallBack;
			animationSwappedCallBack = null;
			action();
		}
	}

	private void speedBasedAnimation()
	{
		currAnimIndex = 0;
		Fix y = animatedBody.velocity.y;
		VelocityFrame[] array = currentVAnim[currAnimIndex];
		int num = 0;
		int i;
		for (i = 0; i < array.Length; i++)
		{
			if (y >= array[i].speedFrom && y <= array[i].speedTo)
			{
				num = i;
				break;
			}
		}
		if (y > array[0].speedTo)
		{
			num = 0;
		}
		else if (i >= array.Length)
		{
			loopedAnimation();
			return;
		}
		if (num >= array.Length - 1)
		{
			spriteRen.sprite = array[^1].sprite;
			if (animationSwappedCallBack != null)
			{
				animationSwappedCallBack();
			}
		}
		else
		{
			num = Mathf.Min(num, array.Length - 1);
			num = Mathf.Max(num, 0);
			spriteRen.sprite = currentVAnim[currAnimIndex][num].sprite;
		}
	}

	public void Setanim2DtargetAnim(int x)
	{
		anim2DtargetAnim = x;
	}

	private void Animation2D()
	{
		if (animation2D == null)
		{
			return;
		}
		if (currAnimIndex < anim2DtargetAnim)
		{
			currentSpritePosY++;
			for (int i = currAnimIndex; i < anim2DtargetAnim; i++)
			{
				int num = Math.Abs(animation2D[currAnimIndex].frameDuration);
				if (currentSpritePosY <= num)
				{
					break;
				}
				currentSpritePosY -= num;
				currAnimIndex++;
				if (currAnimIndex >= animation2D.Length)
				{
					currAnimIndex = animation2D.Length - 1;
				}
			}
		}
		else if (currAnimIndex > anim2DtargetAnim)
		{
			currentSpritePosY++;
			while (currAnimIndex > anim2DtargetAnim)
			{
				int num2 = Math.Abs(animation2D[currAnimIndex].frameDuration);
				if (currentSpritePosY <= num2)
				{
					break;
				}
				currentSpritePosY -= num2;
				currAnimIndex--;
				if (currAnimIndex >= animation2D.Length)
				{
					currAnimIndex = animation2D.Length - 1;
				}
			}
		}
		if (currentSpriteIndex != animation2D[currAnimIndex].animation.Length - 1)
		{
			currentSpritePos++;
		}
		for (int j = currentSpriteIndex; j < animation2D[currAnimIndex].animation.Length; j++)
		{
			int num3 = Math.Abs(animation2D[currAnimIndex].animation[currentSpriteIndex].frameDuration);
			if (currentSpritePos <= num3)
			{
				break;
			}
			currentSpritePos -= num3;
			currentSpriteIndex++;
			if (currentSpriteIndex >= animation2D[currAnimIndex].animation.Length)
			{
				currentSpriteIndex = animation2D[currAnimIndex].animation.Length - 1;
			}
		}
		if (animation2D[currAnimIndex].frameDuration < 0 || animation2D[currAnimIndex].animation[currentSpriteIndex].frameDuration < 0)
		{
			spriteRen.flipX = true;
		}
		else
		{
			spriteRen.flipX = false;
		}
		spriteRen.sprite = animation2D[currAnimIndex].animation[currentSpriteIndex].sprite;
	}

	public bool XYAnimIsLeftOfMidPoint()
	{
		return currAnimIndex >= currentVAnim.Length / 2;
	}

	private void speedBasedXYAnimation()
	{
		curr2DAnimPos++;
		bool num = curr2DAnimPos >= animationSwapTiming;
		Fix x = animatedBody.velocity.x;
		if (num)
		{
			Fix fix = minXSpeed;
			for (int i = 0; i < XSpeeds.Length; i++)
			{
				if (x >= fix && x <= XSpeeds[i])
				{
					currAnimIndex = i;
					break;
				}
				fix = XSpeeds[i];
			}
			currAnimIndex = Mathf.Min(currAnimIndex, currentVAnim.Length - 1);
			currAnimIndex = Mathf.Max(currAnimIndex, 0);
			curr2DAnimPos = 0;
		}
		Fix y = animatedBody.velocity.y;
		VelocityFrame[] array = currentVAnim[currAnimIndex];
		for (int j = 0; j < array.Length; j++)
		{
			if (y >= array[j].speedFrom && y <= array[j].speedTo)
			{
				currentSpriteIndex = j;
				break;
			}
		}
		if (currentSpriteIndex >= array.Length - 1)
		{
			spriteRen.sprite = array[^1].sprite;
			if (animationSwappedCallBack != null)
			{
				animationSwappedCallBack();
			}
		}
		else
		{
			currentSpriteIndex = Mathf.Min(currentSpriteIndex, array.Length - 1);
			currentSpriteIndex = Mathf.Max(currentSpriteIndex, 0);
			spriteRen.sprite = currentVAnim[currAnimIndex][currentSpriteIndex].sprite;
		}
	}

	public Sprite getCurrentSprite()
	{
		return currentAnim[currentSpriteIndex].sprite;
	}

	public int getNumberOfPassedSprites()
	{
		return currentSpriteIndex + 1;
	}

	public int CurrentSpriteIndex()
	{
		return currentSpriteIndex;
	}

	public SpriteFrame[] GetCurrentAnimation()
	{
		return currentAnim;
	}

	public void beginAnimation(SpriteFrame[] anim)
	{
		animType = AnimationType.looped;
		currentSpritePos = 0;
		currentSpriteIndex = 0;
		currentAnim = anim;
		nextAnim = null;
		animationSwappedCallBack = null;
		callBackOnLastFrame = false;
		spriteRen.flipX = false;
		SetFirstFrame(AnimationType.looped);
	}

	public void beginAnimThenPlayAnim(SpriteFrame[] anim, SpriteFrame[] anim2, Action OnAnimationSwapped)
	{
		animType = AnimationType.looped;
		currentSpritePos = 0;
		currentSpriteIndex = 0;
		currentAnim = anim;
		nextAnim = anim2;
		spriteRen.flipX = false;
		animationSwappedCallBack = OnAnimationSwapped;
		SetFirstFrame(AnimationType.looped);
	}

	public void beginAnimThenPlayAnim(SpriteFrame[] anim, SpriteFrame[] anim2)
	{
		animType = AnimationType.looped;
		currentSpritePos = 0;
		currentSpriteIndex = 0;
		currentAnim = anim;
		nextAnim = anim2;
		spriteRen.flipX = false;
		animationSwappedCallBack = null;
		SetFirstFrame(AnimationType.looped);
	}

	public void beginAnimation(string anim, AnimationData data)
	{
		beginAnimation(data.GetAnimation(anim));
	}

	public void beginAnim(SpriteFrame[] anim, Action onAnimationSwapped)
	{
		beginAnimation(anim);
		animationSwappedCallBack = onAnimationSwapped;
	}

	public void beginAnimThenPlayAnim(string anim, string anim2, AnimationData data)
	{
		beginAnimThenPlayAnim(data.GetAnimation(anim), data.GetAnimation(anim2));
	}

	public void beginAnimThenDoAction(SpriteFrame[] anim, Action action)
	{
		beginAnimation(anim);
		callBackOnLastFrame = true;
		animationSwappedCallBack = action;
	}

	public void beginYSpeedBasedAnimation(VelocityFrame[] anim, SpriteFrame[] endOfAnimLoop, SpeedContainer body)
	{
		beginYSpeedBasedAnimation(anim, endOfAnimLoop, null, body);
	}

	public void beginYSpeedBasedAnimation(VelocityFrame[] anim, SpriteFrame[] endOfAnimLoop, Sprite anticipationFrame, SpeedContainer body)
	{
		currentVAnim = new VelocityFrame[1][] { anim };
		currentSpritePos = 0;
		currentSpriteIndex = 0;
		currentAnim = endOfAnimLoop;
		animType = AnimationType.speedMapY;
		animatedBody = body;
		spriteRen.flipX = false;
		nextAnim = null;
		animationSwappedCallBack = null;
		if (anticipationFrame == null)
		{
			SetFirstFrame(AnimationType.speedMapY);
		}
		else
		{
			spriteRen.sprite = anticipationFrame;
		}
	}

	public void beginXYSpeedBasedAnimation(VelocityFrame[][] anim2D, Fix[] xSpeeds, Fix minXSpeed, int animationSwapTiming, Sprite anticipationFrame, SpeedContainer body, bool flipX)
	{
		currAnimIndex = 0;
		currentVAnim = anim2D;
		currentSpritePos = 0;
		currentSpriteIndex = 0;
		currentAnim = null;
		animType = AnimationType.speedMapXY;
		animatedBody = body;
		animationSwappedCallBack = null;
		this.animationSwapTiming = animationSwapTiming;
		spriteRen.sprite = anticipationFrame;
		spriteRen.flipX = flipX;
		this.minXSpeed = minXSpeed;
		XSpeeds = xSpeeds;
	}

	public void beginImmediateXYSpeedBasedAnimation(VelocityFrame[][] anim2D, Fix[] xSpeeds, Fix minXSpeed, int animationSwapTiming, SpeedContainer body, bool flipX)
	{
		currAnimIndex = 0;
		currentVAnim = anim2D;
		currentSpritePos = 0;
		currentSpriteIndex = 0;
		currentAnim = null;
		animType = AnimationType.speedMapXY;
		animatedBody = body;
		animationSwappedCallBack = null;
		this.animationSwapTiming = animationSwapTiming;
		this.minXSpeed = minXSpeed;
		XSpeeds = xSpeeds;
		spriteRen.flipX = flipX;
		speedBasedXYAnimation();
	}

	public void beginAnimation2D(Animation2DFrame[] anim2D, int startX, int startY, bool goingRight, int targetYIndex)
	{
		animation2D = anim2D;
		anim2DGoingRight = goingRight;
		anim2DtargetAnim = targetYIndex;
		currentSpriteIndex = startX;
		currAnimIndex = startY;
		currentAnim = null;
		animType = AnimationType.nonlooped2D;
		nextAnim = null;
		animationSwappedCallBack = null;
		callBackOnLastFrame = false;
		spriteRen.flipX = false;
		currentSpritePos = 0;
		currentSpritePosY = 0;
		SetFirstFrame(AnimationType.nonlooped2D);
	}

	public void beginAnimation2D(Animation2DFrame[] anim2D, int startX, int startY, bool goingRight, int targetYIndex, Sprite anticipationFrame)
	{
		beginAnimation2D(anim2D, startX, startY, goingRight, targetYIndex);
		spriteRen.sprite = anticipationFrame;
	}

	public void beginRotationAnimation(SpriteFrame[] anim, SpeedContainer body)
	{
		currentSpritePos = 0;
		currentSpriteIndex = 0;
		currentAnim = anim;
		nextAnim = null;
		animType = AnimationType.rotationMap;
		animatedBody = body;
		spriteRen.flipX = false;
		animationSwappedCallBack = null;
		SetFirstFrame(AnimationType.rotationMap);
	}

	public void StartChildAnimations(string name)
	{
		childAnimationSuffix = name;
	}
}
[Serializable]
public struct KeyFrameF
{
	public Fix value;

	public Fix time;

	public Fix inTangent;

	public Fix outTangent;
}
[Serializable]
public class AnimationCurveFixed
{
	[SerializeField]
	private AnimationCurve Anim;

	public KeyFrameF[] keys;

	public Fix Evaluate(Fix t)
	{
		if (keys.Length >= 2 && t <= keys[0].time)
		{
			Fix time = keys[0].time;
			Fix fix = keys[keys.Length - 1].time - time;
			switch (Anim.preWrapMode)
			{
			case WrapMode.Loop:
				t -= time;
				t = fix - Fix.SlowMod(Fix.SlowAbs(t), fix);
				t += time;
				break;
			case WrapMode.PingPong:
			{
				t -= time;
				int num = (int)(long)Fix.SlowAbs(t / fix);
				t = fix - Fix.SlowMod(Fix.SlowAbs(t), fix);
				t = Fix.SlowMod(t, fix);
				if (num % 2 == 0)
				{
					t = fix - t;
				}
				t += time;
				break;
			}
			default:
				return keys[0].value;
			}
		}
		else if (keys.Length >= 2 && t >= keys[keys.Length - 1].time)
		{
			Fix time2 = keys[0].time;
			Fix fix2 = keys[keys.Length - 1].time - time2;
			switch (Anim.postWrapMode)
			{
			case WrapMode.Loop:
				t -= time2;
				t = Fix.SlowMod(t, fix2);
				t += time2;
				break;
			case WrapMode.PingPong:
			{
				t -= time2;
				int num2 = (int)(long)Fix.SlowAbs(t / fix2);
				t = Fix.SlowMod(t, fix2);
				if (num2 % 2 != 0)
				{
					t = fix2 - t;
				}
				t += time2;
				break;
			}
			default:
				return keys[keys.Length - 1].value;
			}
		}
		for (int i = 1; i < keys.Length; i++)
		{
			if (t <= keys[i].time)
			{
				return Evaluate(t, keys[i - 1], keys[i]);
			}
		}
		return Fix.Zero;
	}

	private Fix Evaluate(Fix t, KeyFrameF key1, KeyFrameF key2)
	{
		Fix fix = key2.time - key1.time;
		t = (t - key1.time) / fix;
		Fix fix2 = key1.outTangent * fix;
		Fix fix3 = key2.inTangent * fix;
		Fix fix4 = t * t;
		Fix fix5 = fix4 * t;
		Fix fix6 = (Fix)2L * fix5 - (Fix)3L * fix4 + Fix.One;
		Fix fix7 = fix5 - (Fix)2L * fix4 + t;
		Fix fix8 = fix5 - fix4;
		Fix fix9 = -(Fix)2L * fix5 + (Fix)3L * fix4;
		return fix6 * key1.value + fix7 * fix2 + fix8 * fix3 + fix9 * key2.value;
	}

	public void Init()
	{
		keys = new KeyFrameF[Anim.length];
		for (int i = 0; i < Anim.length; i++)
		{
			keys[i] = new KeyFrameF
			{
				value = (Fix)Anim.keys[i].value,
				time = (Fix)Anim.keys[i].time,
				inTangent = (Fix)Anim.keys[i].inTangent,
				outTangent = (Fix)Anim.keys[i].outTangent
			};
		}
	}
}
[RequireComponent(typeof(IPhysicsCollider), typeof(FixTransform))]
public class BoplBody : MonoUpdatable
{
	[SerializeField]
	private Fix mass = Fix.One;

	public Fix bounciness = (Fix)0.5f;

	public Fix friction = (Fix)0.3f;

	public Fix dynamicFriction = (Fix)0.4f;

	[SerializeField]
	public Fix momentOfInertia = Fix.One;

	public Fix gravityScale = Fix.One;

	public Fix airFriction01 = Fix.One;

	public Fix rotationalDrag01 = Fix.One;

	private IPhysicsCollider physicsCollider;

	private FixTransform fixTrans;

	private bool isResizable;

	public Vec2 StartVelocity;

	public Fix StartAngularVelocity;

	public ForceArrow ForceArrowPrefab;

	private ForceArrow forceArrow;

	private Fix prevScale = Fix.One;

	private long framesUntilDrop = -1L;

	[NonSerialized]
	public MagnetGun magnetGunHolder;

	private string originalSortingLayerName;

	private int originalSortingOrder;

	public Vec2 position
	{
		get
		{
			return fixTrans.position;
