	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		physicsCollider = GetComponent<IPhysicsCollider>();
		fixTrans = GetComponent<FixTransform>();
		if (ForceArrowPrefab != null)
		{
			forceArrow = UnityEngine.Object.Instantiate(ForceArrowPrefab, base.transform.position, Quaternion.identity, base.transform);
		}
		else
		{
			forceArrow = GetComponentInChildren<ForceArrow>();
		}
		isResizable = base.gameObject.CompareTag("ResizablePlatform");
	}

	public PhysicsBody NewPhysicsBody(Fix orientation)
	{
		return new PhysicsBody
		{
			inverseMass = ((mass == Fix.Zero) ? Fix.Zero : (Fix.One / mass)),
			inverseMomentOfInertia = ((momentOfInertia == Fix.Zero) ? Fix.Zero : (Fix.One / momentOfInertia)),
			velocity = StartVelocity,
			bounciness = bounciness,
			staticFriction = friction,
			dynamicFriction = dynamicFriction,
			orientation = orientation,
			airDrag = airFriction01,
			rotationalDrag = rotationalDrag01,
			gravityScale = gravityScale,
			angularVelocity = StartAngularVelocity
		};
	}

	public FixTransform GetFixTransform()
	{
		return fixTrans;
	}

	public void AddForce(Vec2 f, ForceMode2D forceMode = ForceMode2D.Force)
	{
		if (forceMode == ForceMode2D.Impulse)
		{
			f *= (Fix)60L;
		}
		physicsCollider.AddForce(f);
	}

	public void AddForceAtPosition(Vec2 f, Vec2 pos, ForceMode2D forceMode = ForceMode2D.Force)
	{
		physicsCollider.AddForceAtPosition(f, pos, forceMode);
	}

	public PhysicsBody PhysicsBody()
	{
		return physicsCollider.GetBody();
	}

	private void Update()
	{
		if (forceArrow == null)
		{
			return;
		}
		if (GameTime.IsTimeStopped())
		{
			forceArrow.gameObject.SetActive(value: true);
		}
		if (forceArrow.gameObject.activeSelf)
		{
			if (GameTime.IsTimeStopped() && physicsCollider.initHasBeenCalled && !GameSessionHandler.GameIsPaused)
			{
				PhysicsBody body = physicsCollider.GetBody();
				forceArrow.SetForce((Vector2)body.velocity);
			}
			else
			{
				forceArrow.gameObject.SetActive(value: false);
			}
		}
	}

	public override void Init()
	{
	}

	public void Drop()
	{
		if (framesUntilDrop >= 0)
		{
			magnetGunHolder = null;
			SpriteRenderer component = GetComponent<SpriteRenderer>();
			if (component != null)
			{
				component.sortingLayerName = originalSortingLayerName;
				component.sortingOrder = originalSortingOrder;
			}
		}
		framesUntilDrop = -1L;
	}

	public void Hold(long framesToHoldFor, MagnetGun magnetHolder, bool changeSortingLayer = true)
	{
		if (framesUntilDrop <= 0)
		{
			SpriteRenderer component = GetComponent<SpriteRenderer>();
			if (component != null)
			{
				originalSortingOrder = component.sortingOrder;
				originalSortingLayerName = component.sortingLayerName;
				if (changeSortingLayer)
				{
					component.sortingLayerName = "Player";
					component.sortingOrder = 0;
				}
			}
		}
		magnetGunHolder = magnetHolder;
		framesUntilDrop = framesToHoldFor;
	}

	public bool IsBeingHeld()
	{
		return framesUntilDrop >= 0;
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		framesUntilDrop--;
		if (framesUntilDrop == 0L)
		{
			Drop();
		}
		if (!isResizable && physicsCollider.initHasBeenCalled && mass != Fix.Zero && momentOfInertia != Fix.Zero && prevScale != fixTrans.Scale)
		{
			if (physicsCollider.IsComposite() && physicsCollider.shape != Shape.RoundedRect)
			{
				prevScale = fixTrans.Scale;
				return;
			}
			Fix scale = fixTrans.Scale;
			Fix fix = prevScale / scale;
			physicsCollider.inverseMass *= fix;
			physicsCollider.inverseMomentOfInertia *= fix;
			prevScale = fixTrans.Scale;
		}
	}
}
public class CompositeBody
{
	public PhysicsBody combinedBody;

	public Vec2 position;

	public List<int> circleIds;

	public List<int> boxIds;

	public List<int> roundedRectIds;

	public bool IsDestroyed;

	private CompositeBody()
	{
		combinedBody = default(PhysicsBody);
		circleIds = new List<int>(10);
		boxIds = new List<int>(10);
		roundedRectIds = new List<int>(10);
		IsDestroyed = false;
	}

	public void Reset()
	{
		circleIds.Clear();
		roundedRectIds.Clear();
		boxIds.Clear();
		IsDestroyed = true;
		position = Vec2.zero;
		combinedBody = default(PhysicsBody);
	}

	public int BodyCount()
	{
		return boxIds.Count + circleIds.Count + roundedRectIds.Count;
	}

	public static CompositeBody CreateNewComposite(List<CompositeBody> composites)
	{
		CompositeBody compositeBody = null;
		for (int i = 0; i < composites.Count; i++)
		{
			if (composites[i].IsDestroyed)
			{
				compositeBody = composites[i];
				compositeBody.IsDestroyed = false;
				return compositeBody;
			}
		}
		if (compositeBody == null)
		{
			compositeBody = new CompositeBody();
			composites.Add(compositeBody);
		}
		return compositeBody;
	}
}
