public class AABBXComparer : IComparer<AABB>
{
	public int Compare(AABB a, AABB b)
	{
		int num = Fix.Sign(a.min.x - b.min.x);
		if (num == 0)
		{
			num = a.shape - b.shape;
			if (num != 0)
			{
				return num;
			}
			return a.id - b.id;
		}
		return num;
	}
}
public class AABBYComparer : IComparer<AABB>
{
	public int Compare(AABB a, AABB b)
	{
		int num = Fix.Sign(a.min.y - b.min.y);
		if (num == 0)
		{
			num = a.shape - b.shape;
			if (num != 0)
			{
				return num;
			}
			return a.id - b.id;
		}
		return num;
	}
}
