public struct Box : IShape
{
	public Vec2 center;

	public Vec2 right;

	public Vec2 up;

	public Vec2 inverseExtents;

	public int layer;

	public void Translate(Vec2 pos)
	{
		center += pos;
	}

	public Vec2 Pos()
	{
		return center;
	}

	public int Layer()
	{
		return layer;
	}

	public void SetRotation(Fix radians)
	{
		Vec2 u = new Vec2(radians);
		right = Vec2.ComplexMul(Vec2.right / inverseExtents.x, u);
		up = Vec2.ComplexMul(Vec2.up / inverseExtents.y, u);
	}

	public void UpdateExtents(Vec2 extents)
	{
		right *= inverseExtents.x;
		up *= inverseExtents.y;
		inverseExtents = new Vec2(Fix.One / extents.x, Fix.One / extents.y);
		right *= extents.x;
		up *= extents.y;
	}

	public bool OverlapPoint(Vec2 point)
	{
		return PhysTools.OverlapPoint(this, point);
	}
}
public struct RoundedRect : IShape
{
	public Box box;

	public Fix radius;

	public int layer;

	public void Translate(Vec2 pos)
	{
		box.center += pos;
	}

	public Vec2 Pos()
	{
		return box.center;
	}

	public void SetRotation(Fix radians)
	{
		Vec2 u = new Vec2(radians);
		box.right = Vec2.ComplexMul(Vec2.right / box.inverseExtents.x, u);
		box.up = Vec2.ComplexMul(Vec2.up / box.inverseExtents.y, u);
	}

	public int Layer()
	{
		return layer;
	}

	public bool OverlapPoint(Vec2 point)
	{
		return PhysTools.OverlapPoint(this, point);
	}

	public Vec2 GetClosestPoint(Vec2 p)
	{
		Vec2 center = box.center;
		Vec2 vec = box.up * box.inverseExtents.y;
		Vec2 vec2 = box.right * box.inverseExtents.x;
		Vec2 up = box.up;
		Vec2 right = box.right;
		Fix fix = Vec2.Dot(right, right);
		Fix fix2 = Vec2.Dot(up, up);
		Fix fix3 = Vec2.Dot(p - center, vec2);
		Fix fix4 = Vec2.Dot(p - center, vec);
		Fix fix5 = (Fix)Fix.Sign2(fix3) * fix3 * fix3;
		Fix fix6 = (Fix)Fix.Sign2(fix4) * fix4 * fix4;
		if (fix5 <= -fix)
		{
			if (fix6 >= fix2)
			{
				Vec2 vec3 = center - right + up;
				return vec3 + Vec2.Normalized(p - vec3) * radius;
			}
			if (fix6 <= -fix2)
			{
				Vec2 vec4 = center - right - up;
				return vec4 + Vec2.Normalized(p - vec4) * radius;
			}
			return center - right - vec2 * radius + vec * fix4;
		}
		if (fix5 >= fix)
		{
			if (fix6 >= fix2)
			{
				Vec2 vec5 = center + right + up;
				return vec5 + Vec2.Normalized(p - vec5) * radius;
			}
			if (fix6 <= -fix2)
			{
				Vec2 vec6 = center + right - up;
				return vec6 + Vec2.Normalized(p - vec6) * radius;
			}
			return center + right + vec2 * radius + vec * fix4;
		}
		if (fix4 >= 0L)
		{
			return center + up + vec * radius + vec2 * fix3;
		}
		return center - up - vec * radius + vec2 * fix3;
	}
}
public class RopeBody : IDisposable
{
	public Vec2[] segment = new Vec2[40];

	public Vec2[] segmentPrev = new Vec2[40];

	public int segmentCount;

	public bool enabled;

	public RopeMesh ropeMesh;

	public byte ownerId;

	public uint number;

	public int indexInArray;

	public Vec2 force_end;

	public Fix timeInAir_end;

	public Fix mass_end;

	public Vec2 force_start;

	public Fix timeInAir_start;

	public Fix mass_start;

	public Vector2 transformPos;

	public bool hasBeenDettached;

	public Fix timeSinceHookArrived;

	public bool disabledThisFrame;

	public Fix segmentSeparation;

	public int[] collidingRoundedRects = new int[32];

	public int nrOfCollidingRects;

	public const int MaxSegments = 40;

	public bool hookHasArrived => timeSinceHookArrived > 0L;

	public void SetForce(Vec2 force, bool topAttachment)
	{
		if (topAttachment)
		{
			force_start = force;
		}
		else
		{
			force_end = force;
		}
	}

	public void SetTimeInAir(Fix time, bool topAttachment)
	{
		if (topAttachment)
		{
			timeInAir_start = time;
		}
		else
		{
			timeInAir_end = time;
		}
	}

	public void SetMass01(Fix mass01, bool topAttachment, Fix scale)
	{
		mass01 = Fix.Clamp01(mass01 + scale * (Fix)0.1 - (Fix)0.1);
		if (topAttachment)
		{
			mass_start = mass01;
		}
		else
		{
			mass_end = mass01;
		}
	}

	public void Dettach(bool topAttachment)
	{
		hasBeenDettached = true;
		Fix fix = (Fix)0.5;
		if (topAttachment)
		{
			mass_end = fix;
		}
		else
		{
			mass_start = fix;
		}
	}

	public bool SpawnAdditionalSegment(Vec2 spawnPos)
	{
		if (segmentCount >= segment.Length)
		{
			return false;
		}
		segmentCount++;
		segment[segmentCount - 1] = segment[segmentCount - 2];
		segmentPrev[segmentCount - 1] = segmentPrev[segmentCount - 2];
		segment[segmentCount - 2] = spawnPos;
		segmentPrev[segmentCount - 2] = spawnPos;
		return true;
	}

	public bool ReelInSegment(int minSegments)
	{
		if (segmentCount <= minSegments)
		{
			return false;
		}
		segment[segmentCount - 2] = segment[segmentCount - 1];
		segmentPrev[segmentCount - 2] = segmentPrev[segmentCount - 1];
		segmentCount--;
		return true;
	}

	public bool ReverseReelInSegment(int minSegments)
	{
		if (segmentCount <= minSegments)
		{
			return false;
		}
		for (int i = 1; i < segmentCount - 1; i++)
		{
			segment[i] = segment[i + 1];
			segmentPrev[i] = segmentPrev[i + 1];
		}
		segmentCount--;
		return true;
	}

	public void Dispose()
	{
		ropeMesh.Dispose();
	}
}
public class RopeMesh : IDisposable
{
	public NativeArray<Vector3> vertices = new NativeArray<Vector3>(80, Allocator.Persistent);

	public NativeArray<Vector2> uvs = new NativeArray<Vector2>(80, Allocator.Persistent);

	public int[] triangles = new int[234];

	public Mesh mesh = new Mesh();

	public void Dispose()
	{
		vertices.Dispose();
		uvs.Dispose();
	}

	public void SetMeshValues(int nrOfSegments)
	{
		int length = nrOfSegments * 2;
		int trianglesLength = (nrOfSegments - 1) * 6;
		mesh.Clear();
		mesh.SetVertices(vertices, 0, length);
		mesh.SetUVs(0, uvs, 0, length);
		mesh.SetTriangles(triangles, 0, trianglesLength, 0);
	}

	public void UpdateMesh(RopeBody ropeBody, LevelType levelType)
	{
		if (!ropeBody.enabled)
		{
			return;
		}
		int segmentCount = ropeBody.segmentCount;
		Vec2[] segment = ropeBody.segment;
		float num = 0.2f;
		float num2 = 0.25f;
		int num3 = segmentCount * 2;
		Vector3 vector = -ropeBody.transformPos;
		Vector3 normalized = ((Vector3)(segment[1] - segment[0])).normalized;
		vertices[0] = new Vector3(normalized.y, 0f - normalized.x) * num + (Vector3)segment[0] + vector;
		vertices[1] = new Vector3(0f - normalized.y, normalized.x) * num + (Vector3)segment[0] + vector;
		for (int i = 1; i < segmentCount - 1; i++)
		{
			Vector3 normalized2 = ((Vector3)(segment[i] - segment[i - 1])).normalized;
			vertices[2 * i] = new Vector3(normalized2.y, 0f - normalized2.x) * num + (Vector3)segment[i] + vector;
			vertices[2 * i + 1] = new Vector3(0f - normalized2.y, normalized2.x) * num + (Vector3)segment[i] + vector;
		}
		Vector3 normalized3 = ((Vector3)segment[segmentCount - 1] - (Vector3)segment[segmentCount - 3]).normalized;
		vertices[2 * (segmentCount - 1)] = new Vector3(normalized3.y, 0f - normalized3.x) * num + (Vector3)segment[segmentCount - 1] + vector;
		vertices[2 * (segmentCount - 1) + 1] = new Vector3(0f - normalized3.y, normalized3.x) * num + (Vector3)segment[segmentCount - 1] + vector;
		if (levelType != LevelType.space)
		{
			float num4 = (float)Constants.WATER_HEIGHT - ropeBody.transformPos.y;
			for (int j = 0; j < num3; j++)
			{
				Vector3 value = vertices[j];
				value.y = ((value.y < num4) ? num4 : value.y);
				vertices[j] = value;
			}
		}
		for (int k = 0; k < segmentCount - 1; k++)
		{
			triangles[k * 6] = 2 * k;
			triangles[k * 6 + 1] = 2 * k + 2;
			triangles[k * 6 + 2] = 2 * k + 1;
			triangles[k * 6 + 3] = 2 * k + 1;
			triangles[k * 6 + 4] = 2 * k + 2;
			triangles[k * 6 + 5] = 2 * k + 3;
		}
		for (int l = 0; l < segmentCount; l++)
		{
			uvs[2 * l] = new Vector2(0f, (float)l * num2);
			uvs[2 * l + 1] = new Vector2(1f, (float)l * num2);
		}
	}
}
public class RopeBodyList : IDisposable
{
	public RopeBody[] ropeBodies;

	public RopeBodyList()
	{
		ropeBodies = new RopeBody[128];
		for (int i = 0; i < ropeBodies.Length; i++)
		{
			ropeBodies[i] = new RopeBody();
			ropeBodies[i].ropeMesh = new RopeMesh();
		}
	}

	public RopeBody AddRope(int nrOfSegments)
	{
		for (int i = 0; i < ropeBodies.Length; i++)
		{
			if (!ropeBodies[i].enabled && !ropeBodies[i].disabledThisFrame)
			{
				ropeBodies[i].segmentCount = nrOfSegments;
				ropeBodies[i].enabled = true;
				ropeBodies[i].indexInArray = i;
				ropeBodies[i].force_end = Vec2.zero;
				ropeBodies[i].force_start = Vec2.zero;
				ropeBodies[i].disabledThisFrame = false;
				ropeBodies[i].hasBeenDettached = false;
				ropeBodies[i].segmentSeparation = Fix.Zero;
				ropeBodies[i].timeInAir_end = Fix.Zero;
				ropeBodies[i].timeInAir_start = Fix.Zero;
				ropeBodies[i].timeSinceHookArrived = Fix.Zero;
				ropeBodies[i].transformPos = Vector2.zero;
				return ropeBodies[i];
			}
		}
		UnityEngine.Debug.LogError("created too many ropes! overflow!");
		return null;
	}

	public void RemoveRope(RopeBody rope)
	{
		rope.enabled = false;
		rope.disabledThisFrame = true;
	}

	public void SimulateRopes(Fix gravityStr, Fix SimDeltaTime, int relaxationIterations, Fix playerMass01, Fix segmentLength)
	{
		DetPhysics detPhysics = DetPhysics.Get();
		if (SimDeltaTime == Fix.Zero)
		{
			SimDeltaTime = GameTime.FixedTimeStep * (Fix)0.1;
		}
		for (int i = 0; i < ropeBodies.Length; i++)
		{
			if (!ropeBodies[i].enabled)
			{
				continue;
			}
			Vec2 vec = Vec2.down * gravityStr;
			RopeBody ropeBody = ropeBodies[i];
			int num = ropeBody.segmentCount - 1;
			Vec2 vec2 = ropeBody.segment[0];
			ropeBody.segment[0] = (Fix)2L * ropeBody.segment[0] - ropeBody.segmentPrev[0] + SimDeltaTime * ropeBody.force_start;
			ropeBody.segmentPrev[0] = vec2;
			for (int j = 1; j < num; j++)
			{
				Vec2 vec3 = ropeBody.segment[j];
				ropeBody.segment[j] = (Fix)2L * ropeBody.segment[j] - ropeBody.segmentPrev[j] + SimDeltaTime * vec;
				ropeBody.segmentPrev[j] = vec3;
			}
			Vec2 vec4 = ropeBody.segment[num];
			ropeBody.segment[num] = (Fix)2L * ropeBody.segment[num] - ropeBody.segmentPrev[num] + SimDeltaTime * ropeBody.force_end;
			ropeBody.segmentPrev[num] = vec4;
			Fix fix = (Fix)0.5f;
			for (int k = 0; k < relaxationIterations; k++)
			{
				Vec2 vec5 = ropeBody.segment[1] - ropeBody.segment[0];
				Fix fix2 = Vec2.Magnitude(vec5);
				if (fix2 == Fix.Zero)
				{
					continue;
				}
				Fix fix3 = -fix2;
				Vec2 vec6 = vec5 / fix2;
				ropeBody.segment[1] += fix3 * vec6 * ropeBody.mass_start;
				ropeBody.segment[0] -= fix3 * vec6 * (Fix.One - ropeBody.mass_start);
				for (int l = 1; l < ropeBody.segmentCount - 2; l++)
				{
					vec5 = ropeBody.segment[l] - ropeBody.segment[l + 1];
					fix2 = Vec2.Magnitude(vec5);
					if (!(fix2 == Fix.Zero))
					{
						fix3 = segmentLength - fix2;
						vec6 = vec5 / fix2;
						ropeBody.segment[l] += fix3 * vec6 * fix;
						ropeBody.segment[l + 1] -= fix3 * vec6 * fix;
					}
				}
				vec5 = ropeBody.segment[ropeBody.segmentCount - 2] - ropeBody.segment[ropeBody.segmentCount - 1];
				fix2 = Vec2.Magnitude(vec5);
				if (!(fix2 == Fix.Zero))
				{
					fix3 = -fix2;
					vec6 = vec5 / fix2;
					ropeBody.segment[ropeBody.segmentCount - 2] += fix3 * vec6 * ropeBody.mass_end;
					ropeBody.segment[ropeBody.segmentCount - 1] -= fix3 * vec6 * (Fix.One - ropeBody.mass_end);
				}
			}
			for (int m = 0; m < detPhysics.roundedRects.Length; m++)
			{
				for (int n = 1; n < ropeBody.segmentCount - 1; n++)
				{
					if (detPhysics.roundedRects.colliders[m].OverlapPoint(ropeBody.segment[n]))
					{
						Vec2 closestPoint = detPhysics.roundedRects.physicsParents[m].fixTrans.GetComponent<StickyRoundedRectangle>().GetClosestPoint(ropeBody.segment[n]);
						ropeBody.segment[n] = closestPoint;
						Fix fix4 = Vec2.SqrMagnitude(ropeBody.segment[n] - ropeBody.segment[n - 1]);
						Fix fix5 = ropeBody.segmentSeparation * ropeBody.segmentSeparation;
						Fix t = Fix.Clamp01(fix4 * detPhysics.platformStretchiness / fix5) * (Fix)0.5;
						ropeBody.segment[n] = Vec2.Lerp(ropeBody.segment[n], ropeBody.segment[n - 1], t);
						closestPoint = detPhysics.roundedRects.physicsParents[m].fixTrans.GetComponent<StickyRoundedRectangle>().GetClosestPoint(ropeBody.segment[n]);
						ropeBody.segment[n] = closestPoint;
					}
				}
			}
		}
	}

	public void Dispose()
	{
		for (int i = 0; i < ropeBodies.Length; i++)
		{
			ropeBodies[i].Dispose();
		}
	}
}
public struct PhysicsBody
{
	public Fix inverseMass;

	public Vec2 velocity;

	public Vec2 force;

	public Fix angularVelocity;

	public Fix orientation;

	public Fix inverseMomentOfInertia;

	public Fix bounciness;

	public Fix staticFriction;

	public Fix dynamicFriction;

	public Fix gravityScale;

	public Fix airDrag;

	public Fix rotationalDrag;

	public CompositeBody compositeParent;

	public Vec2 relativePos;

	public Fix relativeOrientation;

	public bool IsTrigger()
	{
		return Fix.Sign2(inverseMass) < 0;
	}

	public bool IsComposite()
	{
		if (compositeParent != null)
		{
			return !compositeParent.IsDestroyed;
		}
		return false;
	}

	public bool SameCompositeAs(PhysicsBody b)
	{
		if (compositeParent == b.compositeParent && IsComposite())
		{
			return b.IsComposite();
		}
		return false;
	}

	public PhysicsBody(Fix inverseMass, Fix inverseMomentOfInertia, Fix orientation, Fix bounciness, Fix staticFriction, Fix dynamicFriction, Fix gravityScale, Fix airFriction, Fix rotationalDrag)
	{
		this.inverseMass = inverseMass;
		this.orientation = orientation;
		this.inverseMomentOfInertia = inverseMomentOfInertia;
		this.bounciness = bounciness;
		this.staticFriction = staticFriction;
		this.dynamicFriction = dynamicFriction;
		velocity = Vec2.zero;
		force = Vec2.zero;
		angularVelocity = Fix.Zero;
		airDrag = airFriction;
		this.rotationalDrag = rotationalDrag;
		this.gravityScale = gravityScale;
		relativePos = Vec2.zero;
		relativeOrientation = Fix.Zero;
		compositeParent = null;
	}
}
