	[Serializable]
	public struct BeamColors
	{
		public UnityEngine.Color white;

		public UnityEngine.Color yellow;

		public UnityEngine.Color orange;

		public UnityEngine.Color red;

		public BeamColors Mix(BeamColors colors)
		{
			UnityEngine.Color color = new UnityEngine.Color(Mathf.Min(white.r, colors.white.r), Mathf.Min(white.g, colors.white.g), Mathf.Min(white.b, colors.white.b), Mathf.Max(white.a, colors.white.a));
			return new BeamColors
			{
				orange = Mix(orange, colors.orange),
				red = Mix(red, colors.red),
				yellow = Mix(yellow, colors.yellow),
				white = color
			};
		}

		private UnityEngine.Color Mix(UnityEngine.Color c1, UnityEngine.Color c2)
		{
			UnityEngine.Color.RGBToHSV(c1, out var H, out var S, out var V);
			UnityEngine.Color.RGBToHSV(c2, out var H2, out var S2, out var V2);
			float h = (H + H2) / 2f;
			float s = Mathf.Max(S, S2);
			float v = Mathf.Max(V, V2) + 0.1f;
			return UnityEngine.Color.HSVToRGB(h, s, v);
		}
	}

