	public void SimulateRope(RopeBody body, ParallelLoopState loopstate)
	{
		if (!body.enabled)
		{
			return;
		}
		Vec2 vec;
		Vec2 vec2;
		Fix fix;
		Fix fix2;
		if (body.hookHasArrived)
		{
			vec = body.force_start;
			vec2 = body.force_end;
			fix = body.mass_start;
			fix2 = body.mass_end;
		}
		else
		{
			vec = Vec2.zero;
			vec2 = Vec2.zero;
			fix = Fix.One;
			fix2 = Fix.One;
		}
		Vec2 vec3 = Vec2.down * ropeGravity * ((levelTypeThisFrame == LevelType.space) ? ((Fix)0.5) : Fix.One);
		int num = body.segmentCount - 1;
		Vec2 vec4 = body.segment[0];
		body.segment[0] = (Fix)2L * body.segment[0] - body.segmentPrev[0] + SimDeltaTimeThisFrame * vec;
		body.segmentPrev[0] = vec4;
		_ = Fix.One / (Fix)num;
		for (int i = 1; i < num; i++)
		{
			Vec2 vec5 = body.segment[i];
			body.segment[i] = (Fix)2L * body.segment[i] - body.segmentPrev[i] + SimDeltaTimeThisFrame * vec3;
			body.segmentPrev[i] = vec5;
		}
		Vec2 vec6 = body.segment[num];
		body.segment[num] = (Fix)2L * body.segment[num] - body.segmentPrev[num] + SimDeltaTimeThisFrame * vec2;
		body.segmentPrev[num] = vec6;
		Fix fix3 = (Fix)0.5f;
		for (int j = 0; j < ropeRelaxationIterations; j++)
		{
			Vec2 vec7 = body.segment[1] - body.segment[0];
			Fix fix4 = Vec2.Magnitude(vec7);
			if (fix4 == Fix.Zero)
			{
				continue;
			}
			Fix fix5 = -fix4;
			Vec2 vec8 = vec7 / fix4;
			body.segment[1] += fix5 * vec8 * fix;
			body.segment[0] -= fix5 * vec8 * (Fix.One - fix);
			for (int k = 1; k < body.segmentCount - 2; k++)
			{
				vec7 = body.segment[k] - body.segment[k + 1];
				fix4 = Vec2.Magnitude(vec7);
				if (!(fix4 == Fix.Zero))
				{
					fix5 = body.segmentSeparation - fix4;
					vec8 = vec7 / fix4;
					body.segment[k] += fix5 * vec8 * fix3;
					body.segment[k + 1] -= fix5 * vec8 * fix3;
				}
			}
			vec7 = body.segment[body.segmentCount - 2] - body.segment[body.segmentCount - 1];
			fix4 = Vec2.Magnitude(vec7);
			if (!(fix4 == Fix.Zero))
			{
				fix5 = -fix4;
				vec8 = vec7 / fix4;
				body.segment[body.segmentCount - 2] += fix5 * vec8 * fix2;
				body.segment[body.segmentCount - 1] -= fix5 * vec8 * (Fix.One - fix2);
			}
		}
		Fix fix6 = Get().platformStretchiness / (body.segmentSeparation * body.segmentSeparation);
		for (int l = 0; l < body.nrOfCollidingRects; l++)
		{
			RoundedRect roundedRect = roundedRects.colliders[body.collidingRoundedRects[l]];
			for (int m = 1; m < body.segmentCount - 1; m++)
			{
				if (roundedRect.OverlapPoint(body.segment[m]))
				{
					Vec2 closestPoint = roundedRect.GetClosestPoint(body.segment[m]);
					body.segment[m] = closestPoint;
					if (!(body.mass_end == fix3) && !(body.mass_start == fix3))
					{
						Fix t = Fix.Clamp01(Vec2.SqrMagnitude(body.segment[m] - body.segment[m - 1]) * fix6) * (Fix)0.5;
						body.segment[m] = Vec2.Lerp(body.segment[m], body.segment[m - 1], t);
						closestPoint = roundedRect.GetClosestPoint(body.segment[m]);
						body.segment[m] = closestPoint;
					}
				}
			}
		}
		body.nrOfCollidingRects = 0;
	}

	public int AddBeamBody(BeamBody body)
	{
		beamBodies[beamsThisFrame] = body;
		return beamsThisFrame++;
	}

	public void UpdateBeams()
	{
		for (int i = 0; i < totalBeamsLastFrame; i++)
		{
			beamRolesLastFrame[i] = beamRoles[i];
		}
		Array.Copy(lineIdtoInd.keys, map_keysLastFrame, lineIdtoInd.entryCount);
		Array.Copy(lineIdtoInd.values, map_ValuesLastFrame, lineIdtoInd.entryCount);
		keyCountLastFrame = lineIdtoInd.entryCount;
		Array.Clear(beamWasReflected, 0, beamWasReflected.Length);
		idReflectedLastFrame.Clear();
		for (int j = 0; j < keyCountLastFrame; j++)
		{
			if (lineIdtoInd.GetIndex(map_keysLastFrame[j]) >= 0 && beamIsReflected[map_ValuesLastFrame[j]])
			{
				idReflectedLastFrame.Add(map_keysLastFrame[j]);
			}
		}
		lineIdtoInd.Clear();
		Array.Clear(beamRoles, 0, beamRoles.Length);
		for (int k = 0; k < Math.Max(totalBeamsLastFrame, beamsThisFrame); k++)
		{
			beamParentInd[k] = -1;
		}
		for (int l = 0; l < beamsThisFrame; l++)
		{
			lineIdtoInd.Add(beamBodies[l].id, (short)l);
		}
		initialBeamCount = beamsThisFrame;
		for (int m = 0; m < beamsThisFrame; m++)
		{
			RaycastBeam(m);
		}
		for (int n = 0; n < idReflectedLastFrame.Count; n++)
		{
			if (lineIdtoInd.TryGetValue(idReflectedLastFrame[n], out var value))
			{
				beamWasReflected[value] = true;
			}
		}
		for (int num = 0; num < crossingsLastFrameCount; num++)
		{
			if (lineIdtoInd.TryGetValue(crossingsLastFrame[num].idA, out var value2) && lineIdtoInd.TryGetValue(crossingsLastFrame[num].idB, out var value3) && IntersectBeams(value2, value3, out var distAlongAB))
			{
				crossBeams(value2, value3, crossingsLastFrame[num].ageTicks, distAlongAB);
			}
		}
		for (int num2 = 0; num2 < initialBeamCount; num2++)
		{
			if (beamRoles[num2] != BeamRole.Single && beamRoles[num2] != BeamRole.MaybeChild)
			{
				continue;
			}
			int num3 = -1;
			Vec2 distAlongAB2 = new Vec2(Fix.MaxValue, Fix.MaxValue);
			for (int num4 = num2 + 1; num4 < initialBeamCount; num4++)
			{
				if (beamRoles[num4] == BeamRole.Single || beamRoles[num4] == BeamRole.MaybeChild)
				{
					short indA = (short)num2;
					short num5 = (short)num4;
					if (IntersectBeams(indA, num5, out var distAlongAB3) && distAlongAB3.x < distAlongAB2.x)
					{
						distAlongAB2 = distAlongAB3;
						num3 = num5;
					}
				}
			}
			if (num3 >= 0)
			{
				crossBeams(num2, num3, 0, distAlongAB2);
				AudioManager.Get().Play("beamsCrossed");
			}
		}
		for (int num6 = 0; num6 < crossingsThisFrameCount; num6++)
		{
			crossingsLastFrame[num6] = new BeamCrossingRecord
			{
				ageTicks = crossingsThisFrame[num6].ageTicks + 1,
				idA = beamBodies[crossingsThisFrame[num6].indA].id,
				idB = beamBodies[crossingsThisFrame[num6].indB].id
			};
		}
		for (int num7 = 0; num7 < beamsThisFrame; num7++)
		{
			if (beamRoles[num7] != BeamRole.MaybeChild && beamRoles[num7] != BeamRole.Child)
			{
				continue;
			}
			for (int num8 = beamParentInd[num7]; num8 >= 0; num8 = beamParentInd[num8])
			{
				BeamRole beamRole = beamRoles[num8];
				beamBodies[num8].scale += beamBodies[num7].scale;
				if (beamRoles[num7] == BeamRole.MaybeChild)
				{
					beamBodies[num8].colors = beamBodies[num8].colors.Mix(beamBodies[num7].colors);
				}
				if (beamRole != BeamRole.MaybeChild && beamRole != BeamRole.Child && beamRole != BeamRole.ParentAndChild)
				{
					break;
				}
			}
		}
		int num9 = 0;
		for (int num10 = 0; num10 < beamsThisFrame; num10++)
		{
			if (beamIsReflected[num10])
			{
				if (!beamWasReflected[num10])
				{
					AudioManager.Get().PlayRandomWithPrefix("beamSparks");
				}
				BeamBody beamBody = beamBodies[num10];
				beamBody.position += beamBody.direction * (beamBody.distance - beamReflectionDistance[num10]);
				beamBody.distance = beamReflectionDistance[num10];
				beamBody.direction = new Vec2(beamBody.direction.x, -beamBody.direction.y);
				beamBody.id = -beamBody.id;
				beamBodies[beamsThisFrame + num9] = beamBody;
				beamBodies[num10].distance -= beamReflectionDistance[num10];
				beamRoles[beamsThisFrame + num9] = beamRoles[num10];
				beamRoles[num10] = ((beamRoles[num10] != BeamRole.Child) ? beamRoles[num10] : BeamRole.Single);
				beamRoles[num10] = ((beamRoles[num10] == BeamRole.ParentAndChild) ? BeamRole.Parent : beamRoles[num10]);
				beamRoles[num10] = ((beamRoles[num10] != BeamRole.ChildWithEffect) ? beamRoles[num10] : BeamRole.Single);
				beamRoles[num10] = ((beamRoles[num10] != BeamRole.MaybeChild) ? beamRoles[num10] : BeamRole.Single);
				beamIsReflected[beamsThisFrame + num9] = false;
				beamRaycastHitRRs[beamsThisFrame + num9] = beamRaycastHitRRs[num10];
				lineIdtoInd.Add(beamBody.id, (short)(beamsThisFrame + num9));
				num9++;
			}
		}
		for (int num11 = 0; num11 < beamsThisFrame + num9; num11++)
		{
			UnityEngine.Debug.DrawLine((Vector2)beamBodies[num11].position, (Vector2)beamBodies[num11].position + (Vector2)(beamBodies[num11].direction * beamBodies[num11].distance), UnityEngine.Color.magenta, (float)GameTime.FixedTimeStep);
		}
		renderBeams(num9);
		totalBeamsLastFrame = beamsThisFrame;
		crossingsLastFrameCount = crossingsThisFrameCount;
		crossingsThisFrameCount = 0;
		beamsThisFrame = 0;
	}

	private void renderBeams(int reflectedBeamsThisFrame)
	{
		int num = beamsThisFrame + reflectedBeamsThisFrame;
		for (int i = 0; i < keyCountLastFrame; i++)
		{
			int num2 = map_ValuesLastFrame[i];
			if (lineIdtoInd.ContainsKey(map_keysLastFrame[i]))
			{
				beamAfterEffect obj = UnityEngine.Object.Instantiate(beamAfterEffectPrefab, beamObjectPool[num2].transform.position, beamObjectPool[num2].transform.rotation);
				obj.transform.localScale = beamObjectPool[num2].beamEffect.red.transform.localScale;
				obj.SetColors(beamObjectPool[num2].beamEffect.orangeCol, beamObjectPool[num2].beamEffect.redCol);
				obj.spriteRen.material.SetFloat("_Scale", beamObjectPool[num2].beamEffect.red.transform.localScale.x);
				AudioManager.Get().Play("beamEnd");
				if (beamHitEffectPool[num2] != null && beamRolesLastFrame[num2] != BeamRole.MaybeChild && beamRolesLastFrame[num2] != BeamRole.Child && beamRolesLastFrame[num2] != BeamRole.ParentAndChild)
				{
					ParticleSystem particleSystem = UnityEngine.Object.Instantiate(beamAfterHitEffectPrefab, beamHitEffectPool[num2].transform.position, beamHitEffectPool[num2].transform.rotation);
					particleSystem.transform.localScale = beamHitEffectPool[num2].transform.localScale;
					ParticleSystem.ColorOverLifetimeModule colorOverLifetime = particleSystem.colorOverLifetime;
					UnityEngine.Color color = beamHitEffectPool[num2].orange.spriteRen.color;
					UnityEngine.Color color2 = beamHitEffectPool[num2].red.spriteRen.color;
					color.a = 0.25f;
					color2.a = 0.25f;
					colorOverLifetime.color = new ParticleSystem.MinMaxGradient(color, color2);
				}
			}
		}
		for (int j = 0; j < num; j++)
		{
			if (beamObjectPool[j] == null || beamObjectPool[j].IsDestroyed)
			{
				BeamBody beamBody = beamBodies[j];
				beamObjectPool[j] = FixTransform.InstantiateFixed(beamObjectPrefab, beamBody.position);
				beamObjectPool[j].SetDimensions(beamBody.position, beamWidth * beamBody.scale, beamBody.direction, beamBody.distance, beamBody.timePassed, beamWidthAnim, beamBody.ownerId, beamBody.id);
				beamObjectPool[j].beamEffect.SetColors(beamBody.colors);
				beamObjectPool[j].Initialize();
			}
			else if (!beamObjectPool[j].gameObject.activeSelf)
			{
				beamObjectPool[j].gameObject.SetActive(value: true);
			}
		}
		for (int k = num; k < beamObjectPool.Length && beamObjectPool[k] != null && !beamObjectPool[k].IsDestroyed && beamObjectPool[k].gameObject.activeSelf; k++)
		{
			beamObjectPool[k].gameObject.SetActive(value: false);
		}
		for (int l = 0; l < num; l++)
		{
			BeamBody beamBody2 = beamBodies[l];
			if (beamRoles[l] == BeamRole.Parent || beamRoles[l] == BeamRole.ParentAndChild)
			{
				beamBody2.position += beamBody2.direction * beamParentOffset;
				beamBody2.distance -= beamParentOffset;
			}
			beamObjectPool[l].SetDimensions(beamBody2.position, beamWidth * beamBody2.scale, beamBody2.direction, beamBody2.distance, beamBody2.timePassed, beamWidthAnim, beamBody2.ownerId, beamBody2.id);
			beamObjectPool[l].beamEffect.SetColors(beamBody2.colors);
		}
		for (int m = 0; m < num; m++)
		{
			if (beamHitEffectPool[m] == null)
			{
				Vec2 vec = beamBodies[m].position + beamBodies[m].direction * beamBodies[m].distance;
				beamHitEffectPool[m] = UnityEngine.Object.Instantiate(hitEffectPrefab, (Vector3)vec, Quaternion.identity);
			}
			else
			{
				beamHitEffectPool[m].gameObject.SetActive(value: true);
			}
		}
		for (int n = num; n < beamHitEffectPool.Length; n++)
		{
			if (beamHitEffectPool[n] != null && beamHitEffectPool[n].gameObject.activeSelf)
			{
				beamHitEffectPool[n].gameObject.SetActive(value: false);
			}
		}
		for (int num3 = 0; num3 < num; num3++)
		{
			if (beamRoles[num3] == BeamRole.Child || beamRoles[num3] == BeamRole.ParentAndChild || beamRoles[num3] == BeamRole.MaybeChild)
			{
				beamHitEffectPool[num3].gameObject.SetActive(value: false);
			}
		}
		for (int num4 = 0; num4 < num; num4++)
		{
			if (beamRoles[num4] == BeamRole.Child || beamRoles[num4] == BeamRole.ParentAndChild || beamRoles[num4] == BeamRole.MaybeChild)
			{
				continue;
			}
			Vec2 vec2 = beamBodies[num4].position + beamBodies[num4].direction * beamBodies[num4].distance;
			Vec2 vec3 = beamBodies[num4].direction;
			if (beamIsReflected[num4] && num4 < beamsThisFrame)
			{
				vec3 = -Vec2.up;
			}
			else if (beamRaycastHitRRs[num4] != null && !beamRaycastHitRRs[num4].IsDestroyed && beamRoles[num4] != BeamRole.ChildWithEffect)
			{
				if (beamRaycastHitRRs[num4].gameObject.layer == wallLayer || beamRaycastHitRRs[num4].gameObject.layer == terrainLayer || beamRaycastHitRRs[num4].gameObject.layer == lethalterrainLayer)
				{
					IPhysicsCollider component = beamRaycastHitRRs[num4].GetComponent<IPhysicsCollider>();
					if (component != null && !component.IsDestroyed && vec2.y > Constants.WATER_HEIGHT + (Fix)1L && !GameTime.IsTimeStoppedFor(beamBodies[num4].ownerId))
					{
						Fix fix = Fix.Min(beamBodies[num4].scale, (Fix)40L);
						component.AddForce(vec3 * beamPlatformPushForce * fix);
						vec3 = -component.NormalAtPoint(vec2);
					}
				}
				else if (beamRaycastHitRRs[num4].gameObject.layer == orbLayer)
				{
					Orb component2 = beamRaycastHitRRs[num4].GetComponent<Orb>();
					if (component2 != null && !component2.IsDestroyed)
					{
						component2.ApplyBeam(beamBodies[num4]);
					}
				}
				else if (beamRaycastHitRRs[num4].gameObject.layer == affectorLayer && !GameTime.IsTimeStoppedFor(beamBodies[num4].ownerId))
				{
					BlackHole component3 = beamRaycastHitRRs[num4].GetComponent<BlackHole>();
					if (component3 != null && !component3.IsDestroyed)
					{
						Fix fix2 = Fix.Min(beamBodies[num4].scale, (Fix)40L);
						component3.AddForceLessMassInfluence(vec3 * beamBlackHolePushForce * fix2);
					}
				}
				else if (beamRaycastHitRRs[num4].gameObject.layer == playerLayer)
				{
					BoplBody component4 = beamRaycastHitRRs[num4].GetComponent<BoplBody>();
					if (component4 != null && !component4.IsDestroyed)
					{
						Fix fix3 = Fix.Min(beamBodies[num4].scale, (Fix)40L);
						component4.AddForce(vec3 * beamRigidBodyPushFOrce * fix3);
					}
				}
			}
			Quaternion rotation = Quaternion.FromToRotation(Vector3.right, (Vector3)vec3);
			beamHitEffectPool[num4].transform.position = (Vector3)vec2;
			beamHitEffectPool[num4].transform.rotation = rotation;
			float num5 = (float)beamBodies[num4].scale * 0.6f + 0.4f;
			beamHitEffectPool[num4].transform.localScale = new Vector3(num5, num5, 1f);
			beamHitEffectPool[num4].SetColors(beamBodies[num4].colors);
		}
	}

	private bool IntersectBeams(int indA, int indB, out Vec2 distAlongAB)
	{
		Vec2 position = beamBodies[indA].position;
		Vec2 direction = beamBodies[indA].direction;
		Fix fix = beamBodies[indA].distance - (beamIsReflected[indA] ? beamReflectionDistance[indA] : Fix.Zero);
		Vec2 position2 = beamBodies[indB].position;
		Vec2 direction2 = beamBodies[indB].direction;
		Fix fix2 = beamBodies[indB].distance - (beamIsReflected[indB] ? beamReflectionDistance[indB] : Fix.Zero);
		bool flag = beamWasReflected[indA] && beamIsReflected[indA];
		bool flag2 = (beamWasReflected[indB] && beamIsReflected[indB]) || !flag;
		distAlongAB = Vec2.zero;
		int num = 0;
		Fix fix3 = Fix.MaxValue;
		Vec2 distAlongAB2 = new Vec2(Fix.MaxValue, Fix.MaxValue);
		Vec2 distAlongAB3 = new Vec2(Fix.MaxValue, Fix.MaxValue);
		Vec2 distAlongAB4 = new Vec2(Fix.MaxValue, Fix.MaxValue);
		Vec2 distAlongAB5 = new Vec2(Fix.MaxValue, Fix.MaxValue);
		if (PhysTools.LineToLineIntersection(position, direction, fix, position2, direction2, fix2, out distAlongAB2))
		{
			num++;
			if (flag2)
			{
				fix3 = distAlongAB2.x;
				distAlongAB = distAlongAB2;
			}
			else if (!flag2)
			{
				fix3 = distAlongAB2.y;
				distAlongAB = distAlongAB2;
			}
		}
		if (beamIsReflected[indA])
		{
			Vec2 posA = position + direction * fix;
			Vec2 dirA = new Vec2(direction.x, -direction.y);
			Fix lengthA = beamReflectionDistance[indA];
			if (PhysTools.LineToLineIntersection(posA, dirA, lengthA, position2, direction2, fix2, out distAlongAB3))
			{
				distAlongAB3.x += fix;
				num++;
				if (flag2 && distAlongAB3.x < fix3)
				{
					fix3 = distAlongAB3.x;
					distAlongAB = distAlongAB3;
				}
				else if (!flag2 && distAlongAB3.y < fix3)
				{
					fix3 = distAlongAB3.y;
					distAlongAB = distAlongAB3;
				}
			}
		}
		if (beamIsReflected[indB])
		{
			Vec2 posB = position2 + direction2 * fix2;
			Vec2 dirB = new Vec2(direction2.x, -direction2.y);
			Fix lengthB = beamReflectionDistance[indB];
			if (PhysTools.LineToLineIntersection(position, direction, fix, posB, dirB, lengthB, out distAlongAB4))
			{
				distAlongAB4.y += fix2;
				num++;
				if (flag2 && distAlongAB4.x < fix3)
				{
					fix3 = distAlongAB4.x;
					distAlongAB = distAlongAB4;
				}
				else if (!flag2 && distAlongAB2.y < fix3)
				{
					fix3 = distAlongAB4.y;
					distAlongAB = distAlongAB4;
				}
			}
		}
		if (beamIsReflected[indA] && beamIsReflected[indB])
		{
			Vec2 posA2 = position + direction * fix;
			Vec2 dirA2 = new Vec2(direction.x, -direction.y);
			Fix lengthA2 = beamReflectionDistance[indA];
			Vec2 posB2 = position2 + direction2 * fix2;
			Vec2 dirB2 = new Vec2(direction2.x, -direction2.y);
			Fix lengthB2 = beamReflectionDistance[indB];
			if (PhysTools.LineToLineIntersection(posA2, dirA2, lengthA2, posB2, dirB2, lengthB2, out distAlongAB5))
			{
				distAlongAB5.x += fix;
				distAlongAB5.y += fix2;
				num++;
				if (flag2 && distAlongAB5.x < fix3)
				{
					fix3 = distAlongAB5.x;
					distAlongAB = distAlongAB5;
				}
				else if (!flag2 && distAlongAB5.y < fix3)
				{
					fix3 = distAlongAB5.y;
					distAlongAB = distAlongAB5;
				}
			}
		}
		return num > 0;
	}

	private bool IntersectBeams_minimizedAlongB(int indA, int indB, out Vec2 distAlongAB)
	{
		Vec2 position = beamBodies[indA].position;
		Vec2 direction = beamBodies[indA].direction;
		Fix fix = beamBodies[indA].distance - (beamIsReflected[indA] ? beamReflectionDistance[indA] : Fix.Zero);
		Vec2 position2 = beamBodies[indB].position;
		Vec2 direction2 = beamBodies[indB].direction;
		Fix fix2 = beamBodies[indB].distance - (beamIsReflected[indB] ? beamReflectionDistance[indB] : Fix.Zero);
		distAlongAB = Vec2.zero;
		int num = 0;
		Fix fix3 = Fix.MaxValue;
		Vec2 distAlongAB2 = new Vec2(Fix.MaxValue, Fix.MaxValue);
		Vec2 distAlongAB3 = new Vec2(Fix.MaxValue, Fix.MaxValue);
		Vec2 distAlongAB4 = new Vec2(Fix.MaxValue, Fix.MaxValue);
		Vec2 distAlongAB5 = new Vec2(Fix.MaxValue, Fix.MaxValue);
		if (PhysTools.LineToLineIntersection(position, direction, fix, position2, direction2, fix2, out distAlongAB2))
		{
			num++;
			fix3 = distAlongAB2.y;
			distAlongAB = distAlongAB2;
		}
		if (beamIsReflected[indA])
		{
			Vec2 posA = position + direction * fix;
			Vec2 dirA = new Vec2(direction.x, -direction.y);
			Fix lengthA = beamReflectionDistance[indA];
			if (PhysTools.LineToLineIntersection(posA, dirA, lengthA, position2, direction2, fix2, out distAlongAB3))
			{
				distAlongAB3.x += fix;
				num++;
				if (distAlongAB3.y < fix3)
				{
					fix3 = distAlongAB3.y;
					distAlongAB = distAlongAB3;
				}
			}
		}
		if (beamIsReflected[indB])
		{
			Vec2 posB = position2 + direction2 * fix2;
			Vec2 dirB = new Vec2(direction2.x, -direction2.y);
			Fix lengthB = beamReflectionDistance[indB];
			if (PhysTools.LineToLineIntersection(position, direction, fix, posB, dirB, lengthB, out distAlongAB4))
			{
				distAlongAB4.y += fix2;
				num++;
				if (distAlongAB2.y < fix3)
				{
					fix3 = distAlongAB4.y;
					distAlongAB = distAlongAB4;
				}
			}
		}
		if (beamIsReflected[indA] && beamIsReflected[indB])
		{
			Vec2 posA2 = position + direction * fix;
			Vec2 dirA2 = new Vec2(direction.x, -direction.y);
			Fix lengthA2 = beamReflectionDistance[indA];
			Vec2 posB2 = position2 + direction2 * fix2;
			Vec2 dirB2 = new Vec2(direction2.x, -direction2.y);
			Fix lengthB2 = beamReflectionDistance[indB];
			if (PhysTools.LineToLineIntersection(posA2, dirA2, lengthA2, posB2, dirB2, lengthB2, out distAlongAB5))
			{
				distAlongAB5.x += fix;
				distAlongAB5.y += fix2;
				num++;
				if (distAlongAB5.y < fix3)
				{
					fix3 = distAlongAB5.y;
					distAlongAB = distAlongAB5;
				}
			}
		}
		return num > 0;
	}

	private void crossBeams(int indA, int indB, int ageTicks, Vec2 distAlongAB)
	{
		beamRoles[indA] = BeamRole.Child;
		beamRoles[indB] = BeamRole.Child;
		BeamBody beamBody = beamBodies[indA];
		BeamBody beamBody2 = beamBodies[indB];
		Fix fix = beamBody.distance - beamReflectionDistance[indA];
		Fix fix2 = beamBody2.distance - beamReflectionDistance[indB];
		Fix fix3 = distAlongAB.x - fix;
		Fix fix4 = distAlongAB.y - fix2;
		Fix x = distAlongAB.x;
		Fix y = distAlongAB.y;
		Vec2 v = beamBody.direction;
		Vec2 u = beamBody2.direction;
		Vec2 vec3;
		Vec2 vec4;
		if (x > fix && y > fix2)
		{
			Vec2 vec = new Vec2(beamBody2.direction.x, -beamBody2.direction.y);
			Vec2 vec2 = new Vec2(beamBody.direction.x, -beamBody.direction.y);
			vec3 = beamBody.position + beamBody.direction * fix + vec2 * fix3;
			vec4 = Vec2.nlerp(vec, vec2, (Fix)0.5);
			beamReflectionDistance[indA] = fix3;
			beamReflectionDistance[indB] = fix4;
			beamIsReflected[indA] = true;
			beamIsReflected[indB] = true;
			v = vec2;
			u = vec;
		}
		else if (x > fix)
		{
			vec3 = beamBody2.position + beamBody2.direction * y;
			Vec2 vec5 = new Vec2(beamBody.direction.x, -beamBody.direction.y);
			vec4 = Vec2.nlerp(beamBody2.direction, vec5, (Fix)0.5);
			beamReflectionDistance[indA] = fix3;
			beamReflectionDistance[indB] = Fix.Zero;
			beamIsReflected[indA] = true;
			beamIsReflected[indB] = false;
			v = vec5;
		}
		else if (y > fix2)
		{
			vec3 = beamBody.position + beamBody.direction * x;
			Vec2 vec6 = new Vec2(beamBody2.direction.x, -beamBody2.direction.y);
			vec4 = Vec2.nlerp(beamBody.direction, vec6, (Fix)0.5);
			beamReflectionDistance[indA] = Fix.Zero;
			beamReflectionDistance[indB] = fix4;
			beamIsReflected[indA] = false;
			beamIsReflected[indB] = true;
			v = vec6;
		}
		else
		{
			vec3 = beamBody2.position + beamBody2.direction * y;
			vec4 = Vec2.nlerp(beamBody2.direction, beamBody.direction, (Fix)0.5);
			beamIsReflected[indA] = false;
			beamIsReflected[indB] = false;
			beamReflectionDistance[indA] = Fix.Zero;
			beamReflectionDistance[indB] = Fix.Zero;
		}
		beamBodies[indA].distance = distAlongAB.x;
		beamBodies[indB].distance = distAlongAB.y;
		Fix fix5 = -(Fix)0.5;
		int num;
		if (Vec2.Dot(v, u) < fix5)
		{
			crossingsThisFrame[crossingsThisFrameCount] = new BeamCrossing
			{
				ageTicks = ageTicks,
				indA = (short)indA,
				indB = (short)indB
			};
			crossingsThisFrameCount++;
			num = indA;
			beamRoles[indA] = BeamRole.ChildWithEffect;
			beamRoles[indB] = BeamRole.ChildWithEffect;
		}
		else
		{
			AddBeamBody(new BeamBody
			{
				scale = Fix.Zero,
				colors = beamBody2.colors.Mix(beamBody.colors),
				position = vec3 + vec4 * crossBeamOffset,
				timePassed = (Fix)ageTicks * GameTime.FixedTimeStep,
				distance = maxBeamDistance,
				direction = vec4,
				id = int.MaxValue - crossingsThisFrameCount - 1,
				ownerId = Constants.ENVIRONMENTAL_PLAYER_ID
			});
			num = beamsThisFrame - 1;
			lineIdtoInd.Add(beamBodies[num].id, (short)num);
			crossingsThisFrame[crossingsThisFrameCount] = new BeamCrossing
			{
				ageTicks = ageTicks,
				indA = (short)indA,
				indB = (short)indB
			};
			crossingsThisFrameCount++;
			beamRoles[num] = BeamRole.Parent;
			RaycastBeam(num);
			beamWasReflected[num] = false;
		}
		beamParentInd[indA] = (short)num;
		beamParentInd[indB] = (short)num;
		for (int i = 0; i < num; i++)
		{
			if (i == indA || i == indB || beamRoles[i] == BeamRole.Single || beamRoles[i] == BeamRole.MaybeChild || !IntersectBeams_minimizedAlongB(num, i, out distAlongAB))
			{
				continue;
			}
			fix = beamBodies[num].distance - beamReflectionDistance[num];
			fix2 = beamBodies[i].distance - beamReflectionDistance[i];
			fix3 = distAlongAB.x - fix;
			fix4 = distAlongAB.y - fix2;
			if (distAlongAB.x < beamBodies[num].distance)
			{
				beamBodies[num].distance = distAlongAB.x;
				beamRoles[num] = BeamRole.ParentAndChild;
				beamParentInd[num] = (short)i;
				if (fix3 <= Fix.Zero)
				{
					beamIsReflected[num] = false;
					beamReflectionDistance[num] = Fix.Zero;
				}
				else
				{
					beamIsReflected[num] = true;
					beamReflectionDistance[num] = fix3;
				}
			}
		}
		for (int j = 0; j < initialBeamCount; j++)
		{
			if ((beamRoles[j] != BeamRole.Single && beamRoles[j] != BeamRole.MaybeChild) || j == indA || j == indB)
			{
				continue;
			}
			if (IntersectBeams_minimizedAlongB(num, j, out distAlongAB))
			{
				fix = beamBodies[num].distance - beamReflectionDistance[num];
				fix2 = beamBodies[j].distance - beamReflectionDistance[j];
				fix3 = distAlongAB.x - fix;
				fix4 = distAlongAB.y - fix2;
				if (distAlongAB.y < beamBodies[j].distance)
				{
					beamBodies[j].distance = distAlongAB.y;
					beamRoles[j] = BeamRole.MaybeChild;
					beamParentInd[j] = (short)num;
					if (fix4 <= Fix.Zero)
					{
						beamIsReflected[j] = false;
						beamReflectionDistance[j] = Fix.Zero;
					}
					else
					{
						beamIsReflected[j] = true;
						beamReflectionDistance[j] = fix4;
					}
				}
			}
			if (IntersectBeams_minimizedAlongB(indA, j, out distAlongAB))
			{
				fix = beamBodies[indA].distance - beamReflectionDistance[indA];
				fix2 = beamBodies[j].distance - beamReflectionDistance[j];
				fix3 = distAlongAB.x - fix;
				fix4 = distAlongAB.y - fix2;
				if (distAlongAB.y < beamBodies[j].distance)
				{
					beamBodies[j].distance = distAlongAB.y;
					beamParentInd[j] = (short)indA;
					beamRoles[j] = BeamRole.MaybeChild;
					if (fix4 <= Fix.Zero)
					{
						beamIsReflected[j] = false;
						beamReflectionDistance[j] = Fix.Zero;
					}
					else
					{
						beamIsReflected[j] = true;
						beamReflectionDistance[j] = fix4;
					}
				}
			}
			if (!IntersectBeams_minimizedAlongB(indB, j, out distAlongAB))
			{
				continue;
			}
			fix = beamBodies[indB].distance - beamReflectionDistance[indB];
			fix2 = beamBodies[j].distance - beamReflectionDistance[j];
			fix3 = distAlongAB.x - fix;
			fix4 = distAlongAB.y - fix2;
			if (distAlongAB.y < beamBodies[j].distance)
			{
				beamBodies[j].distance = distAlongAB.y;
				beamRoles[j] = BeamRole.MaybeChild;
				beamParentInd[j] = (short)indB;
				if (fix4 <= Fix.Zero)
				{
					beamIsReflected[j] = false;
					beamReflectionDistance[j] = Fix.Zero;
				}
				else
				{
					beamIsReflected[j] = true;
					beamReflectionDistance[j] = fix4;
				}
			}
		}
	}

	public bool RaycastBeam(Vec2 pos, Vec2 dir, out Fix beamLength, out Fix beamRefl)
	{
		RaycastInformation raycastInformation = RaycastToClosest(pos, dir, maxBeamDistance, beamHitMask);
		bool num = raycastInformation;
		if (raycastInformation.nearDist > maxBeamDistance)
		{
			raycastInformation.nearDist = maxBeamDistance;
		}
		beamRefl = Fix.Zero;
		beamLength = raycastInformation.nearDist;
		if (!num || raycastInformation.nearPos.y < Constants.WATER_HEIGHT)
		{
			raycastInformation.nearPos = pos + dir * maxBeamDistance;
			if (Constants.leveltype != LevelType.space && raycastInformation.nearPos.y < Constants.WATER_HEIGHT)
			{
				Fix fix = Constants.WATER_HEIGHT - pos.y;
				Vec2 vec = dir * maxBeamDistance;
				if (vec.y == 0L)
				{
					vec.y = (Fix)0.001;
				}
				Vec2 vec2 = new Vec2(vec.x * fix / vec.y, fix) + pos;
				Vec2 dir2 = dir;
				dir2.y = -dir2.y;
				if (Vec2.Dot(dir, Vec2.down) >= (Fix)0.997)
				{
					beamLength = Vec2.Distance(vec2, pos);
					return false;
				}
				RaycastInformation raycastInformation2 = RaycastToClosest(vec2, dir2, maxBeamDistance, beamHitMask);
				if (raycastInformation2.nearDist > maxBeamDistance)
				{
					raycastInformation2.nearDist = maxBeamDistance;
				}
				beamLength = Vec2.Distance(vec2, pos);
				beamRefl = raycastInformation2.nearDist;
				return true;
			}
		}
		return false;
	}

	private void RaycastBeam(int ind)
	{
		RaycastInformation raycastInformation = RaycastToClosest(beamBodies[ind].position, beamBodies[ind].direction, maxBeamDistance, beamHitMask);
		bool num = raycastInformation;
		if (raycastInformation.nearDist > maxBeamDistance)
		{
			raycastInformation.nearDist = maxBeamDistance;
		}
		beamIsReflected[ind] = false;
		beamReflectionDistance[ind] = Fix.Zero;
		beamRaycastHitRRs[ind] = raycastInformation.pp.fixTrans;
		if (!num || raycastInformation.nearPos.y < Constants.WATER_HEIGHT)
		{
			raycastInformation.nearPos = beamBodies[ind].position + beamBodies[ind].direction * maxBeamDistance;
			if (Constants.leveltype != LevelType.space && raycastInformation.nearPos.y < Constants.WATER_HEIGHT)
			{
				Fix fix = Constants.WATER_HEIGHT - beamBodies[ind].position.y;
				Vec2 vec = beamBodies[ind].direction * maxBeamDistance;
				if (vec.y == 0L)
				{
					vec.y = (Fix)0.001;
				}
				Vec2 vec2 = new Vec2(vec.x * fix / vec.y, fix) + beamBodies[ind].position;
				Vec2 direction = beamBodies[ind].direction;
				direction.y *= -Fix.One;
				if (Vec2.Dot(beamBodies[ind].direction, Vec2.down) >= (Fix)0.997)
				{
					beamBodies[ind].distance = Vec2.Distance(vec2, beamBodies[ind].position) + beamReflectionDistance[ind];
					return;
				}
				RaycastInformation raycastInformation2 = RaycastToClosest(vec2, direction, maxBeamDistance, beamHitMask);
				if (raycastInformation2.nearDist > maxBeamDistance)
				{
					raycastInformation2.nearDist = maxBeamDistance;
				}
				beamIsReflected[ind] = true;
				beamReflectionDistance[ind] = raycastInformation2.nearDist;
				beamRaycastHitRRs[ind] = raycastInformation2.pp.fixTrans;
				raycastInformation.nearDist = Vec2.Distance(vec2, beamBodies[ind].position) + beamReflectionDistance[ind];
			}
		}
		beamBodies[ind].distance = raycastInformation.nearDist;
	}

	public void AddObjectToDeleteList(FixTransform go, int frames)
	{
		duplicatedObjects.Add(new DatedMonoUpdatable
		{
			obj = go,
			lifespanFrames = frames,
			offsetLastFrame = Vec2.zero,
			HierarchyNumberIfPermanent = -1
		});
		go.IsDuplicated = true;
	}

	public void AddObjectToDeleteList_lifespanUntilCalledAgain(FixTransform go, int HierarchyNumber)
	{
		duplicatedObjects.Add(new DatedMonoUpdatable
		{
			obj = go,
			lifespanFrames = int.MaxValue,
			offsetLastFrame = Vec2.zero,
			HierarchyNumberIfPermanent = HierarchyNumber
		});
		go.IsDuplicated = true;
	}

	public void DeleteObjectFromDuplicateListWithId(int HierarchyNumber, int additionalDelayFrames)
	{
		for (int i = 0; i < duplicatedObjects.Count; i++)
		{
			DatedMonoUpdatable value = duplicatedObjects[i];
			if (value.HierarchyNumberIfPermanent == HierarchyNumber && value.lifespanFrames > framesBeforeDuplicatesStartShaking + additionalDelayFrames)
			{
				value.lifespanFrames = framesBeforeDuplicatesStartShaking + additionalDelayFrames;
				duplicatedObjects[i] = value;
				break;
			}
		}
	}

	private void DeleteDuplicatedObject(DatedMonoUpdatable dobj)
	{
		AudioManager.Get().PlayWithRandomPitchVariation("spawnOutDuplicate", 0.25f);
		ParticleSystem particleSystem = UnityEngine.Object.Instantiate(duplicatorParticlePrefab, (Vector3)dobj.obj.position, Quaternion.identity);
		SpriteRenderer component = dobj.obj.GetComponent<SpriteRenderer>();
		ParticleSystem.ShapeModule shape = particleSystem.shape;
		shape.sprite = component.sprite;
		particleSystem.transform.rotation = dobj.obj.transform.rotation;
		Vector2 vector = component.bounds.size;
		if (dobj.obj.CompareTag("ResizablePlatform"))
		{
			DPhysicsRoundedRect component2 = component.GetComponent<DPhysicsRoundedRect>();
			Vector3 scale = (Vector3)(component2.CalcExtents() + new Vec2(component2.radius, component2.radius)) * 2f;
			scale.z = 1f;
			int num = (int)(Mathf.Max(vector.x * vector.y * 0.5f, 2f) * (float)component2.Scale * (float)component2.Scale);
			ParticleSystem component3 = particleSystem.transform.GetChild(0).GetComponent<ParticleSystem>();
			ParticleSystem.ShapeModule shape2 = component3.shape;
			ParticleSystem.EmissionModule emission = component3.emission;
			shape2.shapeType = ParticleSystemShapeType.Rectangle;
			shape2.scale = scale;
			ParticleSystem.Burst burst = emission.GetBurst(0);
			burst.count = num;
			emission.SetBurst(0, burst);
			num = (int)(Mathf.Max(vector.x * vector.y * 0.02f, 2f) * (float)component2.Scale * (float)component2.Scale);
			ParticleSystem.ShapeModule shape3 = particleSystem.shape;
			ParticleSystem.EmissionModule emission2 = particleSystem.emission;
			ParticleSystem.Burst burst2 = emission2.GetBurst(0);
			burst2.count = num;
			shape3.shapeType = ParticleSystemShapeType.Rectangle;
			shape3.scale = scale;
			emission2.SetBurst(0, burst2);
		}
		else
		{
			int num2 = (int)Mathf.Max(vector.x * vector.y * 0.5f, 2f);
			ParticleSystem component4 = particleSystem.transform.GetChild(0).GetComponent<ParticleSystem>();
			ParticleSystem.ShapeModule shape4 = component4.shape;
			ParticleSystem.EmissionModule emission3 = component4.emission;
			shape4.scale = new Vector3(shape4.scale.x * (float)dobj.obj.Scale, shape4.scale.y * (float)dobj.obj.Scale, 1f);
			shape4.sprite = component.sprite;
			ParticleSystem.Burst burst3 = emission3.GetBurst(0);
			burst3.count = num2;
			emission3.SetBurst(0, burst3);
			num2 = (int)Mathf.Max(vector.x * vector.y * 0.02f, 2f);
			ParticleSystem.ShapeModule shape5 = particleSystem.shape;
			ParticleSystem.EmissionModule emission4 = particleSystem.emission;
			shape5.sprite = component.sprite;
			shape5.scale = new Vector3(shape5.scale.x * (float)dobj.obj.Scale, shape5.scale.y * (float)dobj.obj.Scale, 1f);
			ParticleSystem.Burst burst4 = emission4.GetBurst(0);
			burst4.count = num2;
			emission4.SetBurst(0, burst4);
		}
		particleSystem.Play();
		Updater.DestroyFix(dobj.obj.gameObject);
	}

	public void UpdateDuplicatedObjects()
	{
		for (int num = duplicatedObjects.Count - 1; num >= 0; num--)
		{
			if (duplicatedObjects[num].obj == null || duplicatedObjects[num].obj.IsDestroyed)
			{
				duplicatedObjects.RemoveAt(num);
			}
			else
			{
				DatedMonoUpdatable datedMonoUpdatable = duplicatedObjects[num];
				datedMonoUpdatable.lifespanFrames--;
				duplicatedObjects[num] = datedMonoUpdatable;
				if (datedMonoUpdatable.lifespanFrames < 0)
				{
					DeleteDuplicatedObject(datedMonoUpdatable);
				}
				else if (datedMonoUpdatable.lifespanFrames < framesBeforeDuplicatesStartShaking)
				{
					Fix fix = Fix.One - (Fix)datedMonoUpdatable.lifespanFrames / (Fix)framesBeforeDuplicatesStartShaking;
					datedMonoUpdatable.obj.position -= datedMonoUpdatable.offsetLastFrame;
					datedMonoUpdatable.offsetLastFrame = Updater.RandomUnitVector() * fix * (Fix)0.25;
					datedMonoUpdatable.obj.position += datedMonoUpdatable.offsetLastFrame;
					duplicatedObjects[num] = datedMonoUpdatable;
				}
			}
		}
	}

	public void AddCircleToRR(int circleId, int roundedRectId)
