	public void RemoveCircleFromComposite(int circleId, CompositeBody b)
	{
		int num = circles.ColliderIndex(circleId);
		b.circleIds.Remove(circleId);
		CompositeBody compositeBody = CreateMultiComposite(b.circleIds, b.boxIds, b.roundedRectIds);
		if (compositeBody != null)
		{
			compositeBody.combinedBody.angularVelocity = b.combinedBody.angularVelocity;
			compositeBody.combinedBody.velocity = b.combinedBody.velocity;
		}
		b.Reset();
		circles.physicsBodies[num].compositeParent = null;
	}

	public void RemoveBoxFromComposite(int boxId, CompositeBody b)
	{
		int num = boxes.ColliderIndex(boxId);
		b.boxIds.Remove(boxId);
		CompositeBody compositeBody = CreateMultiComposite(b.circleIds, b.boxIds, b.roundedRectIds);
		if (compositeBody != null)
		{
			compositeBody.combinedBody.angularVelocity = b.combinedBody.angularVelocity;
			compositeBody.combinedBody.velocity = b.combinedBody.velocity;
		}
		b.Reset();
		boxes.physicsBodies[num].compositeParent = null;
	}

	public void RemoveRoundedRectFromComposite(int rrId, CompositeBody b)
	{
		int num = roundedRects.ColliderIndex(rrId);
		b.roundedRectIds.Remove(rrId);
		CompositeBody compositeBody = CreateMultiComposite(b.circleIds, b.boxIds, b.roundedRectIds);
		if (compositeBody != null)
		{
			compositeBody.combinedBody.angularVelocity = b.combinedBody.angularVelocity;
			compositeBody.combinedBody.velocity = b.combinedBody.velocity;
		}
		b.Reset();
		roundedRects.physicsBodies[num].compositeParent = null;
	}

	private CompositeBody CreateMultiComposite(List<int> circleIds, List<int> boxIds, List<int> roundedRectIds)
	{
		switch (circleIds.Count + boxIds.Count + roundedRectIds.Count)
		{
		case 0:
			return null;
		case 1:
			if (circleIds.Count == 1)
			{
				circles.physicsBodies[circles.ColliderIndex(circleIds[0])].compositeParent = null;
			}
			else if (boxIds.Count == 1)
			{
				boxes.physicsBodies[boxes.ColliderIndex(boxIds[0])].compositeParent = null;
			}
			else
			{
				roundedRects.physicsBodies[roundedRects.ColliderIndex(roundedRectIds[0])].compositeParent = null;
			}
			return null;
		default:
		{
			CompositeBody compositeBody = CompositeBody.CreateNewComposite(composites);
			int num = roundedRects.ColliderIndex(roundedRectIds[0]);
			compositeBody.combinedBody = roundedRects.physicsBodies[num];
			compositeBody.position = roundedRects.colliders[num].Pos();
			roundedRects.physicsBodies[num].compositeParent = compositeBody;
			compositeBody.roundedRectIds.Add(roundedRectIds[0]);
			for (int i = 0; i < circleIds.Count; i++)
			{
				AttachCirleToComposite(circleIds[i], compositeBody);
			}
			for (int j = 0; j < boxIds.Count; j++)
			{
				AttachBoxToComposite(boxIds[j], compositeBody);
			}
			return compositeBody;
		}
		}
	}

	private void AttachCirleToComposite(int circleId, CompositeBody b2)
	{
		int num = circles.ColliderIndex(circleId);
		Vec2 center = circles.colliders[num].center;
		Vec2 position = b2.position;
		b2.circleIds.Add(circleId);
		circles.physicsBodies[num].compositeParent = b2;
		CombineBodies(ref circles.physicsBodies[num], ref b2.combinedBody, center, position, b2);
	}

	private void AttachBoxToComposite(int boxId, CompositeBody b2)
	{
		int num = boxes.ColliderIndex(boxId);
		Vec2 center = boxes.colliders[num].center;
		Vec2 position = b2.position;
		b2.boxIds.Add(boxId);
		boxes.physicsBodies[num].compositeParent = b2;
		CombineBodies(ref boxes.physicsBodies[num], ref b2.combinedBody, center, position, b2);
	}

	private void CombineBodies(ref PhysicsBody small, ref PhysicsBody big, Vec2 smallPos, Vec2 bigPos, CompositeBody newComposite)
	{
		Fix fix = Fix.One / small.inverseMass;
		Fix fix2 = Fix.One / big.inverseMass;
		Fix fix3 = Fix.One / small.inverseMomentOfInertia;
		Fix fix4 = Fix.One / big.inverseMomentOfInertia;
		Fix fix5 = Fix.One / (fix + fix2);
		Vec2 vec = (smallPos * fix + bigPos * fix2) * fix5;
		Vec2 vec2 = fix * small.velocity;
		Vec2 vec3 = fix2 * big.velocity;
		_ = (vec2 + vec3) * fix5;
		_ = smallPos - vec;
		_ = bigPos - vec;
		big.relativeOrientation = Fix.Zero;
		newComposite.combinedBody.orientation = big.orientation;
		small.relativeOrientation = small.orientation - big.orientation;
		big.relativePos = Vec2.zero;
		small.relativePos = Vec2.ComplexMul(smallPos - bigPos, new Vec2(-newComposite.combinedBody.orientation));
		newComposite.position = bigPos;
		Fix inverseMomentOfInertia = Fix.One / (fix3 + fix4);
		newComposite.combinedBody.force = big.force;
		if (!small.IsComposite())
		{
			small.force = Vec2.zero;
		}
		if (!big.IsComposite())
		{
			big.force = Vec2.zero;
		}
		newComposite.combinedBody.dynamicFriction = big.dynamicFriction;
		newComposite.combinedBody.staticFriction = big.staticFriction;
		newComposite.combinedBody.bounciness = big.bounciness;
		newComposite.combinedBody.inverseMomentOfInertia = inverseMomentOfInertia;
		newComposite.combinedBody.inverseMass = fix5;
		newComposite.combinedBody.gravityScale = big.gravityScale;
		newComposite.combinedBody.airDrag = big.airDrag;
		newComposite.combinedBody.rotationalDrag = big.rotationalDrag;
		newComposite.combinedBody.angularVelocity = big.angularVelocity;
		newComposite.combinedBody.velocity = big.velocity;
		newComposite.combinedBody.compositeParent = null;
	}

	private void AttachCircleToRoundedRect(int circleId, int rrId)
	{
		int num = circles.ColliderIndex(circleId);
		int num2 = roundedRects.ColliderIndex(rrId);
		PhysicsBody physicsBody = circles.physicsBodies[num];
		PhysicsBody physicsBody2 = roundedRects.physicsBodies[num2];
		if (!physicsBody.IsComposite() || !physicsBody2.IsComposite())
		{
			if (!physicsBody.IsComposite() && !physicsBody2.IsComposite())
			{
				CompositeBody compositeBody = CompositeBody.CreateNewComposite(composites);
				circles.physicsBodies[num].compositeParent = compositeBody;
				roundedRects.physicsBodies[num2].compositeParent = compositeBody;
				Vec2 center = circles.colliders[num].center;
				Vec2 center2 = roundedRects.colliders[num2].box.center;
				compositeBody.circleIds.Add(circleId);
				compositeBody.roundedRectIds.Add(rrId);
				CombineBodies(ref circles.physicsBodies[num], ref roundedRects.physicsBodies[num2], center, center2, compositeBody);
			}
			else if (!physicsBody.IsComposite() || physicsBody2.IsComposite())
			{
				AttachCirleToComposite(circleId, physicsBody2.compositeParent);
			}
		}
	}

	private void AttachBoxToRoundedRect(int boxId, int rrId)
	{
		int num = boxes.ColliderIndex(boxId);
		int num2 = roundedRects.ColliderIndex(rrId);
		PhysicsBody physicsBody = roundedRects.physicsBodies[num2];
		PhysicsBody physicsBody2 = boxes.physicsBodies[num];
		if (!physicsBody.IsComposite() || !physicsBody2.IsComposite())
		{
			if (!physicsBody.IsComposite() && !physicsBody2.IsComposite())
			{
				CompositeBody compositeBody = CompositeBody.CreateNewComposite(composites);
				boxes.physicsBodies[num].compositeParent = compositeBody;
				roundedRects.physicsBodies[num2].compositeParent = compositeBody;
				Vec2 center = boxes.colliders[num].center;
				Vec2 center2 = roundedRects.colliders[num2].box.center;
				compositeBody.roundedRectIds.Add(rrId);
				compositeBody.boxIds.Add(boxId);
				CombineBodies(ref boxes.physicsBodies[num], ref roundedRects.physicsBodies[num2], center, center2, compositeBody);
			}
			else if (physicsBody.IsComposite() && !physicsBody2.IsComposite())
			{
				AttachBoxToComposite(boxId, physicsBody.compositeParent);
			}
		}
	}

	private void AttachCircles(int circleId1, int circleId2)
	{
		int num = circles.ColliderIndex(circleId1);
		int num2 = circles.ColliderIndex(circleId2);
		PhysicsBody physicsBody = circles.physicsBodies[num];
		PhysicsBody physicsBody2 = circles.physicsBodies[num2];
		if (!physicsBody.IsComposite() || !physicsBody2.IsComposite())
		{
			if (!physicsBody.IsComposite() && !physicsBody2.IsComposite())
			{
				CompositeBody compositeBody = CompositeBody.CreateNewComposite(composites);
				Vec2 center = circles.colliders[num].center;
				Vec2 center2 = circles.colliders[num2].center;
				compositeBody.circleIds.Add(circleId1);
				compositeBody.circleIds.Add(circleId2);
				circles.physicsBodies[num].compositeParent = compositeBody;
				circles.physicsBodies[num2].compositeParent = compositeBody;
				CombineBodies(ref circles.physicsBodies[num], ref circles.physicsBodies[num2], center, center2, compositeBody);
			}
			else if (physicsBody.IsComposite() && !physicsBody2.IsComposite())
			{
				AttachCirleToComposite(circleId2, physicsBody.compositeParent);
			}
			else
			{
				AttachCirleToComposite(circleId1, physicsBody2.compositeParent);
			}
		}
	}

	public void DestroyCircle(PhysicsParent physicsParent)
	{
		int num = circles.ColliderIndex(physicsParent.instanceId);
		CompositeBody compositeParent = circles.physicsBodies[num].compositeParent;
		if (compositeParent != null && !compositeParent.IsDestroyed)
		{
			SynCompositeToFixTransAndRelativeValues(compositeParent);
			RemoveCircleFromComposite(physicsParent.instanceId, compositeParent);
		}
		circles.RemoveCollider(physicsParent);
	}

	public void DestroyBox(PhysicsParent physicsParent)
	{
		int num = boxes.ColliderIndex(physicsParent.instanceId);
		CompositeBody compositeParent = boxes.physicsBodies[num].compositeParent;
		if (compositeParent != null && !compositeParent.IsDestroyed)
		{
			SynCompositeToFixTransAndRelativeValues(compositeParent);
			RemoveBoxFromComposite(physicsParent.instanceId, compositeParent);
		}
		boxes.RemoveCollider(physicsParent);
	}

	public void DestroyRoundedRect(PhysicsParent physicsParent)
	{
		int num = roundedRects.ColliderIndex(physicsParent.instanceId);
		CompositeBody compositeParent = roundedRects.physicsBodies[num].compositeParent;
		if (compositeParent != null && !compositeParent.IsDestroyed)
		{
			for (int i = 0; i < compositeParent.boxIds.Count; i++)
			{
				if (boxes.ContainsParent(compositeParent.boxIds[i]))
				{
					int num2 = boxes.ColliderIndex(compositeParent.boxIds[i]);
					PhysicsParent obj = boxes.physicsParents[num2];
					boxes.RemoveCollider(obj);
				}
			}
			for (int j = 0; j < compositeParent.circleIds.Count; j++)
			{
				if (circles.ContainsParent(compositeParent.circleIds[j]))
				{
					int num3 = circles.ColliderIndex(compositeParent.circleIds[j]);
					PhysicsParent obj2 = circles.physicsParents[num3];
					circles.RemoveCollider(obj2);
				}
			}
			compositeParent.Reset();
		}
		roundedRects.RemoveCollider(physicsParent);
	}

	private Vec2 IntegrateBody(ref PhysicsBody body, Fix deltaTime)
	{
		body.velocity += deltaTime * new Vec2(Fix.Zero, gravityAccel * body.gravityScale) + GameTime.FixedTimeStep * body.force * body.inverseMass;
		body.orientation += deltaTime * body.angularVelocity;
		body.orientation = (body.orientation % Fix.PiTimes2 + Fix.PiTimes2) % Fix.PiTimes2;
		body.velocity *= ((deltaTime == Fix.Zero) ? Fix.One : body.airDrag);
		body.angularVelocity *= ((deltaTime == Fix.Zero) ? Fix.One : body.rotationalDrag);
		body.force = Vec2.zero;
		return deltaTime * body.velocity;
	}

	private static void SyncGameObject(IShape shape, ref PhysicsParent pp, ref PhysicsBody body)
	{
		pp.fixTrans.rotation = body.orientation;
		pp.fixTrans.position = shape.Pos() - Vec2.ComplexMul(pp.fixTrans.right, pp.fixTrans.offset);
	}

	public static bool IsActive(PhysicsParent pp)
	{
		if (pp.fixTrans != null && pp.fixTrans.gameObject.activeInHierarchy)
		{
			return pp.monobehaviourCollider.enabled;
		}
		return false;
	}

	public int CollideBox(Box b, ref PhysicsParent[] hitObjects, LayerMask mask)
	{
		Vector3 vector = (Vector3)b.right;
		Vector3 vector2 = (Vector3)b.up;
		Vector3 vector3 = (Vector3)b.center;
		Vector3 start = vector3 + vector + vector2;
		Vector3 vector4 = vector3 - vector + vector2;
		Vector3 vector5 = vector3 + vector - vector2;
		Vector3 end = vector3 - vector - vector2;
		UnityEngine.Debug.DrawLine(start, vector4, UnityEngine.Color.green, (float)GameTime.FixedTimeStep);
		UnityEngine.Debug.DrawLine(vector5, end, UnityEngine.Color.green, (float)GameTime.FixedTimeStep);
		UnityEngine.Debug.DrawLine(vector4, end, UnityEngine.Color.green, (float)GameTime.FixedTimeStep);
		UnityEngine.Debug.DrawLine(start, vector5, UnityEngine.Color.green, (float)GameTime.FixedTimeStep);
		_ = hitObjects.Length;
		int num = 0;
		for (int i = 0; i < circles.Length; i++)
		{
			if (((int)mask & (1 << circles.colliders[i].layer)) != 0 && IsActive(circles.physicsParents[i]) && PhysTools.CollisionTest(circles.colliders[i], b))
			{
				hitObjects[num] = circles.physicsParents[i];
				num++;
				if (num == hitObjects.Length)
				{
					return num;
				}
			}
		}
		for (int j = 0; j < boxes.Length; j++)
		{
			if (((int)mask & (1 << boxes.colliders[j].layer)) != 0 && IsActive(boxes.physicsParents[j]) && PhysTools.CollisionTest(b, boxes.colliders[j]))
			{
				hitObjects[num] = boxes.physicsParents[j];
				num++;
				if (num == hitObjects.Length)
				{
					return num;
				}
			}
		}
		for (int k = 0; k < roundedRects.Length; k++)
		{
			if (((int)mask & (1 << roundedRects.colliders[k].layer)) != 0 && IsActive(roundedRects.physicsParents[k]) && PhysTools.CollisionTest(b, roundedRects.colliders[k]))
			{
				hitObjects[num] = roundedRects.physicsParents[k];
				num++;
				if (num == hitObjects.Length)
				{
					return num;
				}
			}
		}
		return num;
	}

	public RaycastInformation RaycastToClosestRoundedRect(Vec2 origin, Vec2 dir, Fix distance)
	{
		RemoveDestroyedColliders();
		RaycastInformation result = new RaycastInformation
		{
			nearDist = Fix.MaxValue
		};
		Fix fix = Fix.MaxValue;
		for (int i = 0; i < roundedRects.Length; i++)
		{
			if (IsActive(roundedRects.physicsParents[i]))
			{
				Fix distNear = (Fix)1000000L;
				Fix distFar = (Fix)2000000L;
				if (Raycast.RayCastRoundedRect(origin, dir, roundedRects.colliders[i], out distNear, out distFar) && distNear < fix && distNear <= distance)
				{
					fix = distNear;
					result = new RaycastInformation
					{
						nearPos = origin + distNear * dir,
						farPos = origin + distFar * dir,
						nearDist = distNear,
						farDist = distFar,
						layer = roundedRects.colliders[i].layer,
						pp = roundedRects.physicsParents[i]
					};
