	public bool CircleCastClosestPlayers(Vec2 pos, Fix radius, Fix circlesMultiplier, int ignoreThisInstanceId, ref PhysicsParent hit)
	{
		RemoveDestroyedColliders();
		Circle circle = new Circle
		{
			center = pos,
			radius = radius
		};
		int num = LayerMask.NameToLayer("Player");
		Fix fix = (Fix)100000L;
		bool result = false;
		for (int i = 0; i < boxes.Length; i++)
		{
			if (num == boxes.colliders[i].layer && IsActive(boxes.physicsParents[i]) && boxes.physicsParents[i].instanceId != ignoreThisInstanceId && PhysTools.CollisionTest(circle, boxes.colliders[i]) && Vec2.SqrMagnitude(boxes.colliders[i].center - pos) < fix)
			{
				hit = boxes.physicsParents[i];
				result = true;
			}
		}
		circle.radius *= circlesMultiplier;
		for (int j = 0; j < circles.Length; j++)
		{
			if (circles.colliders[j].layer == num && IsActive(circles.physicsParents[j]) && circles.physicsParents[j].instanceId != ignoreThisInstanceId && PhysTools.CollisionTest(circle, circles.colliders[j]) && Vec2.SqrMagnitude(circles.colliders[j].center - pos) < fix)
			{
				hit = circles.physicsParents[j];
				result = true;
			}
		}
		return result;
	}

