	public RaycastInformation RaycastToClosestTriple(Vec2 origin, Vec2 dir, Fix distance, LayerMask mask, Fix radius)
	{
		RaycastInformation result = RaycastToClosest(origin, dir, distance, mask);
		RaycastInformation result2 = RaycastToClosest(origin + Vec2.MulByI(dir) * radius, dir, distance, mask);
		RaycastInformation result3 = RaycastToClosest(origin + Vec2.MulByNegI(dir) * radius, dir, distance, mask);
		Tools.Debug_DrawLine(origin, result.nearPos, UnityEngine.Color.red, 5f);
		Tools.Debug_DrawLine(origin + Vec2.MulByI(dir) * radius, result2.nearPos, UnityEngine.Color.green, 5f);
		Tools.Debug_DrawLine(origin + Vec2.MulByNegI(dir) * radius, result3.nearPos, UnityEngine.Color.blue, 5f);
		if (result.nearDist < result2.nearDist && result.nearDist < result3.nearDist)
		{
			return result;
		}
		if (result2.nearDist < result.nearDist && result2.nearDist < result3.nearDist)
		{
			return result2;
		}
		if (result3.nearDist < result2.nearDist && result3.nearDist < result.nearDist)
		{
			return result3;
		}
		return result;
	}

	public RaycastInformation RaycastToClosest(Vec2 origin, Vec2 dir, Fix distance, LayerMask mask)
	{
		RemoveDestroyedColliders();
		RaycastInformation result = new RaycastInformation
		{
			nearDist = Fix.MaxValue
		};
		Fix fix = Fix.MaxValue;
		for (int i = 0; i < roundedRects.Length; i++)
		{
			if (Tools.LayerMaskContains(mask, roundedRects.colliders[i].layer) && IsActive(roundedRects.physicsParents[i]))
			{
				Fix distNear = (Fix)1000000L;
				Fix distFar = (Fix)2000000L;
				if (Raycast.RayCastRoundedRect(origin, dir, roundedRects.colliders[i], out distNear, out distFar) && distNear < fix && distNear <= distance)
				{
					fix = distNear;
					result = new RaycastInformation
					{
						nearPos = origin + distNear * dir,
						farPos = origin + distFar * dir,
						nearDist = distNear,
						farDist = distFar,
						layer = roundedRects.colliders[i].layer,
						pp = roundedRects.physicsParents[i]
					};
				}
			}
		}
		for (int j = 0; j < circles.Length; j++)
		{
			if (Tools.LayerMaskContains(mask, circles.colliders[j].layer) && IsActive(circles.physicsParents[j]))
			{
				Fix shortDist = (Fix)1000000L;
				Fix longDist = (Fix)2000000L;
				if (Raycast.RayCastCircle(origin, dir, circles.colliders[j], ref shortDist, ref longDist) && shortDist < fix && shortDist <= distance)
				{
					fix = shortDist;
					result = new RaycastInformation
					{
						nearPos = origin + shortDist * dir,
						farPos = origin + longDist * dir,
						nearDist = shortDist,
						farDist = longDist,
						layer = circles.colliders[j].layer,
						pp = circles.physicsParents[j]
					};
				}
			}
		}
		for (int k = 0; k < boxes.Length; k++)
		{
			if (Tools.LayerMaskContains(mask, boxes.colliders[k].layer) && IsActive(boxes.physicsParents[k]))
			{
				Fix distNear2 = (Fix)1000000L;
				Fix distFar2 = (Fix)2000000L;
				if (Raycast.RayCastBox(origin, dir, boxes.colliders[k], ref distNear2, ref distFar2) && distNear2 < fix && distNear2 <= distance)
				{
					fix = distNear2;
					result = new RaycastInformation
					{
						nearPos = origin + distNear2 * dir,
						farPos = origin + distFar2 * dir,
						nearDist = distNear2,
						farDist = distFar2,
						layer = boxes.colliders[k].layer,
						pp = boxes.physicsParents[k]
					};
				}
			}
		}
		return result;
	}

	public bool RaycastAll(Vec2 origin, Vec2 dir, Fix distance, LayerMask mask, List<RaycastInformation> output, int casterInstanceId = 0)
	{
		RemoveDestroyedColliders();
		RaycastInformation raycastInformation = new RaycastInformation
		{
			nearDist = Fix.MaxValue
		};
		for (int i = 0; i < roundedRects.Length; i++)
		{
			if (Tools.LayerMaskContains(mask, roundedRects.colliders[i].layer) && IsActive(roundedRects.physicsParents[i]) && roundedRects.physicsParents[i].instanceId != casterInstanceId)
			{
				Fix distNear = (Fix)1000000L;
				Fix distFar = (Fix)2000000L;
				if (Raycast.RayCastRoundedRect(origin, dir, roundedRects.colliders[i], out distNear, out distFar) && distNear <= distance)
				{
					raycastInformation = new RaycastInformation
					{
						nearPos = origin + distNear * dir,
						farPos = origin + distFar * dir,
						nearDist = distNear,
						farDist = distFar,
						layer = roundedRects.colliders[i].layer,
						pp = roundedRects.physicsParents[i]
					};
					output.Add(raycastInformation);
				}
			}
		}
		for (int j = 0; j < circles.Length; j++)
		{
			if (Tools.LayerMaskContains(mask, circles.colliders[j].layer) && IsActive(circles.physicsParents[j]) && circles.physicsParents[j].instanceId != casterInstanceId)
			{
				Fix shortDist = (Fix)1000000L;
				Fix longDist = (Fix)2000000L;
				if (Raycast.RayCastCircle(origin, dir, circles.colliders[j], ref shortDist, ref longDist) && shortDist <= distance)
				{
					raycastInformation = new RaycastInformation
					{
						nearPos = origin + shortDist * dir,
						farPos = origin + longDist * dir,
						nearDist = shortDist,
						farDist = longDist,
						layer = circles.colliders[j].layer,
						pp = circles.physicsParents[j]
					};
					output.Add(raycastInformation);
				}
			}
		}
		for (int k = 0; k < boxes.Length; k++)
		{
			if (Tools.LayerMaskContains(mask, boxes.colliders[k].layer) && IsActive(boxes.physicsParents[k]) && boxes.physicsParents[k].instanceId != casterInstanceId)
			{
				Fix distNear2 = (Fix)1000000L;
				Fix distFar2 = (Fix)2000000L;
				if (Raycast.RayCastBox(origin, dir, boxes.colliders[k], ref distNear2, ref distFar2) && distNear2 <= distance)
				{
					raycastInformation = new RaycastInformation
					{
						nearPos = origin + distNear2 * dir,
						farPos = origin + distFar2 * dir,
						nearDist = distNear2,
						farDist = distFar2,
						layer = boxes.colliders[k].layer,
						pp = boxes.physicsParents[k]
					};
					output.Add(raycastInformation);
				}
			}
		}
		output.Sort(comparer);
		return raycastInformation;
	}

	private void SortAndSweepXAxis(int bbCount)
	{
		Array.Sort(boundingBoxes, 0, bbCount, boundingBoxComparerX);
		activeIds.Add(0);
		for (int i = 1; i < bbCount; i++)
		{
			int num = 0;
			while (num < activeIds.Count)
			{
				if (boundingBoxes[activeIds[num]].max.x <= boundingBoxes[i].min.x)
				{
					activeIds.RemoveAt(num);
					continue;
				}
				if (!Physics2D.GetIgnoreLayerCollision(boundingBoxes[activeIds[num]].layer, boundingBoxes[i].layer) && boundingBoxes[activeIds[num]].max.y > boundingBoxes[i].min.y && boundingBoxes[activeIds[num]].min.y < boundingBoxes[i].max.y)
				{
					switch (boundingBoxes[activeIds[num]].shape)
					{
					case Shape.Circle:
						switch (boundingBoxes[i].shape)
						{
						case Shape.Circle:
							potentialColliderIds_CircleCircle.Add(new IdPair(boundingBoxes[activeIds[num]].id, boundingBoxes[i].id));
							break;
						case Shape.Box:
							potentialColliderIds_CircleBox.Add(new IdPair(boundingBoxes[activeIds[num]].id, boundingBoxes[i].id));
							break;
						case Shape.RoundedRect:
							potentialColliderIds_CircleRR.Add(new IdPair(boundingBoxes[activeIds[num]].id, boundingBoxes[i].id));
							break;
						}
						break;
					case Shape.Box:
						switch (boundingBoxes[i].shape)
						{
						case Shape.Circle:
							potentialColliderIds_CircleBox.Add(new IdPair(boundingBoxes[i].id, boundingBoxes[activeIds[num]].id));
							break;
						case Shape.Box:
							potentialColliderIds_BoxBox.Add(new IdPair(boundingBoxes[activeIds[num]].id, boundingBoxes[i].id));
							break;
						case Shape.RoundedRect:
							potentialColliderIds_BoxRR.Add(new IdPair(boundingBoxes[activeIds[num]].id, boundingBoxes[i].id));
							break;
						}
						break;
					case Shape.RoundedRect:
						switch (boundingBoxes[i].shape)
						{
						case Shape.Circle:
							potentialColliderIds_CircleRR.Add(new IdPair(boundingBoxes[i].id, boundingBoxes[activeIds[num]].id));
							break;
						case Shape.Box:
							potentialColliderIds_BoxRR.Add(new IdPair(boundingBoxes[i].id, boundingBoxes[activeIds[num]].id));
							break;
						case Shape.RoundedRect:
							potentialColliderIds_RR_RR.Add(new IdPair(boundingBoxes[activeIds[num]].id, boundingBoxes[i].id));
							break;
						}
						break;
					}
				}
				num++;
			}
			activeIds.Add(i);
		}
		activeIds.Clear();
	}

