	private void SortAndSweepXAxis_ropes(int bbCount)
	{
		Array.Sort(bb_rope_rr, 0, bbCount, boundingBoxComparerX);
		activeIds.Add(0);
		for (int i = 1; i < bbCount; i++)
		{
			int num = 0;
			while (num < activeIds.Count)
			{
				if (bb_rope_rr[activeIds[num]].max.x <= bb_rope_rr[i].min.x)
				{
					activeIds.RemoveAt(num);
					continue;
				}
				if (bb_rope_rr[activeIds[num]].max.y > bb_rope_rr[i].min.y && bb_rope_rr[activeIds[num]].min.y < bb_rope_rr[i].max.y)
				{
					switch (bb_rope_rr[activeIds[num]].shape)
					{
					case Shape.RoundedRect:
						if (bb_rope_rr[i].shape == Shape.Rope)
						{
							RopeBody ropeBody2 = ropes.ropeBodies[bb_rope_rr[i].id];
							if (ropeBody2.nrOfCollidingRects < ropeBody2.collidingRoundedRects.Length)
							{
								ropeBody2.collidingRoundedRects[ropeBody2.nrOfCollidingRects] = bb_rope_rr[activeIds[num]].id;
								ropeBody2.nrOfCollidingRects++;
							}
						}
						break;
					case Shape.Rope:
						if (bb_rope_rr[i].shape == Shape.RoundedRect)
						{
							RopeBody ropeBody = ropes.ropeBodies[bb_rope_rr[activeIds[num]].id];
							if (ropeBody.nrOfCollidingRects < ropeBody.collidingRoundedRects.Length)
							{
								ropeBody.collidingRoundedRects[ropeBody.nrOfCollidingRects] = bb_rope_rr[i].id;
								ropeBody.nrOfCollidingRects++;
							}
						}
						break;
					}
				}
				num++;
			}
			activeIds.Add(i);
		}
		activeIds.Clear();
	}

