	public void PrepareCollisionCallBacks(CollisionManifold manifold, IShape shapeA, IShape shapeB, PhysicsParent p1, PhysicsParent p2, Vec2 velA, Vec2 velB)
	{
		if (p1.collisionCallback != null && !p1.collisionCallback.IsDestroyed)
		{
			CollisionInformation item = new CollisionInformation
			{
				collider = shapeB,
				colliderImpactVelocity = velB,
				contactPoint = manifold.contactPoint,
				layer = shapeB.Layer(),
				normal = manifold.normal,
				penetration = manifold.penetration,
				colliderPP = p2,
				pp = p1
			};
			ToMakeCallBacks.Add(item);
		}
		if (p2.collisionCallback != null && !p1.collisionCallback.IsDestroyed)
		{
			CollisionInformation item2 = new CollisionInformation
			{
				collider = shapeA,
				colliderImpactVelocity = velA,
				contactPoint = manifold.contactPoint,
				layer = shapeA.Layer(),
				normal = manifold.normal,
				penetration = manifold.penetration,
				colliderPP = p1,
				pp = p2
			};
			ToMakeCallBacks.Add(item2);
		}
	}

	public void RemoveDestroyedColliders()
	{
		for (int i = 0; i < circles.Length; i++)
		{
			if (circles.physicsParents[i].fixTrans == null || circles.physicsParents[i].monobehaviourCollider.IsDestroyed)
			{
				DestroyCircle(circles.physicsParents[i]);
				i--;
			}
		}
		for (int j = 0; j < roundedRects.Length; j++)
		{
			if (roundedRects.physicsParents[j].fixTrans == null || roundedRects.physicsParents[j].monobehaviourCollider.IsDestroyed)
			{
				DestroyRoundedRect(roundedRects.physicsParents[j]);
				j--;
			}
		}
		for (int k = 0; k < boxes.Length; k++)
		{
			if (boxes.physicsParents[k].fixTrans == null || boxes.physicsParents[k].monobehaviourCollider.IsDestroyed)
			{
				DestroyBox(boxes.physicsParents[k]);
				k--;
			}
		}
	}

	public void SynCompositeToFixTransAndRelativeValues(CompositeBody b)
	{
		if (!b.IsDestroyed && b.roundedRectIds.Count >= 1)
		{
			int num = roundedRects.ColliderIndex(b.roundedRectIds[0]);
			FixTransform fixTrans = roundedRects.physicsParents[num].fixTrans;
			b.position = fixTrans.position;
			b.combinedBody.orientation = fixTrans.rotation;
			roundedRects.colliders[num].box.SetRotation(fixTrans.rotation);
			roundedRects.colliders[num].box.center = fixTrans.position;
			roundedRects.physicsBodies[num].orientation = fixTrans.rotation;
			Vec2 right = fixTrans.right;
			for (int i = 0; i < b.boxIds.Count; i++)
			{
				int num2 = boxes.ColliderIndex(b.boxIds[i]);
				Vec2 vec = Vec2.ComplexMul(boxes.physicsBodies[num2].relativePos, right);
				boxes.colliders[num2].center = b.position + vec;
				boxes.physicsBodies[num2].orientation = fixTrans.rotation + boxes.physicsBodies[num2].relativeOrientation;
				boxes.colliders[num2].SetRotation(boxes.physicsBodies[num2].orientation);
			}
			for (int j = 0; j < b.circleIds.Count; j++)
			{
				int num3 = circles.ColliderIndex(b.circleIds[j]);
				Vec2 vec2 = Vec2.ComplexMul(circles.physicsBodies[num3].relativePos, right);
				circles.colliders[num3].center = b.position + vec2;
				circles.physicsBodies[num3].orientation = fixTrans.rotation + circles.physicsBodies[num3].relativeOrientation;
				circles.colliders[num3].SetRotation(circles.physicsBodies[num3].orientation);
			}
		}
	}

	private void SyncAllPhysicsObjectsToFixTransformPosition()
	{
		for (int i = 0; i < roundedRects.Length; i++)
		{
			if (!roundedRects.physicsBodies[i].IsComposite())
			{
				roundedRects.colliders[i].box.SetRotation(roundedRects.physicsParents[i].fixTrans.rotation);
				roundedRects.colliders[i].box.center = roundedRects.physicsParents[i].fixTrans.position;
				roundedRects.physicsBodies[i].orientation = roundedRects.physicsParents[i].fixTrans.rotation;
			}
		}
		for (int j = 0; j < circles.Length; j++)
		{
			if (!circles.physicsBodies[j].IsComposite())
			{
				circles.colliders[j].SetRotation(circles.physicsParents[j].fixTrans.rotation);
				circles.colliders[j].center = circles.physicsParents[j].fixTrans.position + Vec2.ComplexMul(circles.physicsParents[j].fixTrans.right, circles.physicsParents[j].fixTrans.offset);
				circles.physicsBodies[j].orientation = circles.physicsParents[j].fixTrans.rotation;
			}
		}
		for (int k = 0; k < boxes.Length; k++)
		{
			if (!boxes.physicsBodies[k].IsComposite())
			{
				boxes.colliders[k].SetRotation(boxes.physicsParents[k].fixTrans.rotation);
				boxes.colliders[k].center = boxes.physicsParents[k].fixTrans.position + Vec2.ComplexMul(boxes.physicsParents[k].fixTrans.right, boxes.physicsParents[k].fixTrans.offset);
				boxes.physicsBodies[k].orientation = boxes.physicsParents[k].fixTrans.rotation;
			}
		}
		for (int l = 0; l < composites.Count; l++)
		{
			SynCompositeToFixTransAndRelativeValues(composites[l]);
		}
	}

	public void MoveObjectOutOfWalls(IPhysicsCollider bodyToMove)
	{
		bodyToMove.UpdatePhysicsPositions();
		switch (bodyToMove.shape)
		{
		case Shape.Circle:
			MoveObjectOutOfWalls((DPhysicsCircle)bodyToMove);
			break;
		case Shape.Box:
			MoveObjectOutOfWalls((DPhysicsBox)bodyToMove);
			break;
		case Shape.RoundedRect:
			MoveObjectOutOfWalls((DPhysicsRoundedRect)bodyToMove);
			break;
		}
	}

	public void MoveObjectOutOfWalls(DPhysicsCircle bodyToMove)
	{
		RemoveDestroyedColliders();
		int instanceId = bodyToMove.GetPhysicsParent().instanceId;
		int num = circles.ColliderIndex(instanceId);
		for (int i = 0; i < roundedRects.Length; i++)
		{
			if (IsActive(roundedRects.physicsParents[i]))
			{
				CollisionManifold collisionManifold = new CollisionManifold
				{
					colliderIndexA = num,
					colliderIndexB = i
				};
				if (PhysTools.CollisionTest(circles.colliders[num], roundedRects.colliders[i], ref collisionManifold))
				{
					Vec2Pair vec2Pair = PhysTools.FullPositionalCorrection(collisionManifold, Fix.One, Fix.Zero);
					bodyToMove.position = circles.colliders[num].Pos() + vec2Pair.a;
					return;
				}
			}
		}
		int mask = LayerMask.GetMask("wall", "LethalTerrain", "NonLethalTerrain");
		for (int j = 0; j < circles.Length; j++)
		{
			if (((1 << circles.colliders[j].layer) & mask) != 0 && IsActive(circles.physicsParents[j]) && j != num)
			{
				CollisionManifold collisionInfo = new CollisionManifold
				{
					colliderIndexA = num,
					colliderIndexB = j
				};
				if (PhysTools.CollisionTest(circles.colliders[num], circles.colliders[j], ref collisionInfo))
				{
					Vec2Pair vec2Pair2 = PhysTools.FullPositionalCorrection(collisionInfo, Fix.One, Fix.Zero);
					bodyToMove.position = circles.colliders[num].Pos() + vec2Pair2.a;
					return;
				}
			}
		}
		for (int k = 0; k < boxes.Length; k++)
		{
			if (((1 << boxes.colliders[k].layer) & mask) != 0 && IsActive(boxes.physicsParents[k]))
			{
				CollisionManifold collisionManifold2 = new CollisionManifold
				{
					colliderIndexA = num,
					colliderIndexB = k
				};
				if (PhysTools.CollisionTest(circles.colliders[num], boxes.colliders[k], ref collisionManifold2))
				{
					Vec2Pair vec2Pair3 = PhysTools.FullPositionalCorrection(collisionManifold2, Fix.One, Fix.Zero);
					bodyToMove.position = circles.colliders[num].Pos() + vec2Pair3.a;
					break;
				}
			}
		}
	}

