	public void Simulate(Fix deltaTime)
	{
		RemoveDestroyedColliders();
		ToMakeCallBacks.Clear();
		SyncAllPhysicsObjectsToFixTransformPosition();
		if (circles.Length + boxes.Length + roundedRects.Length <= 0)
		{
			return;
		}
		if (GameTime.IsTimeStopped())
		{
			deltaTime = Fix.Zero;
		}
		for (int i = 0; i < roundedRects.Length; i++)
		{
			if (IsActive(roundedRects.physicsParents[i]) && !(roundedRects.physicsBodies[i].inverseMass <= Fix.Zero) && !roundedRects.physicsBodies[i].IsComposite())
			{
				Vec2 pos = IntegrateBody(ref roundedRects.physicsBodies[i], deltaTime);
				roundedRects.colliders[i].Translate(pos);
				roundedRects.colliders[i].SetRotation(roundedRects.physicsBodies[i].orientation);
			}
		}
		for (int j = 0; j < circles.Length; j++)
		{
			if (IsActive(circles.physicsParents[j]) && !(circles.physicsBodies[j].inverseMass <= Fix.Zero) && !circles.physicsBodies[j].IsComposite())
			{
				Vec2 pos2 = IntegrateBody(ref circles.physicsBodies[j], deltaTime);
				circles.colliders[j].Translate(pos2);
			}
		}
		for (int k = 0; k < boxes.Length; k++)
		{
			if (IsActive(boxes.physicsParents[k]) && !(boxes.physicsBodies[k].inverseMass <= Fix.Zero) && !boxes.physicsBodies[k].IsComposite())
			{
				Vec2 pos3 = IntegrateBody(ref boxes.physicsBodies[k], deltaTime);
				boxes.colliders[k].Translate(pos3);
				boxes.colliders[k].SetRotation(boxes.physicsBodies[k].orientation);
			}
		}
		for (int l = 0; l < composites.Count; l++)
		{
			if (!(composites[l].combinedBody.inverseMass != Fix.Zero) || composites[l].IsDestroyed)
			{
				continue;
			}
			int num = roundedRects.ColliderIndex(composites[l].roundedRectIds[0]);
			if (IsActive(roundedRects.physicsParents[num]) && !(roundedRects.physicsBodies[num].inverseMass <= Fix.Zero))
			{
				for (int m = 0; m < composites[l].roundedRectIds.Count; m++)
				{
					int num2 = roundedRects.ColliderIndex(composites[l].roundedRectIds[m]);
					composites[l].combinedBody.force += roundedRects.physicsBodies[num2].force;
					roundedRects.physicsBodies[num2].force = Vec2.zero;
				}
				composites[l].combinedBody.velocity += deltaTime * new Vec2(Fix.Zero, gravityAccel * composites[l].combinedBody.gravityScale) + GameTime.FixedTimeStep * composites[l].combinedBody.force * composites[l].combinedBody.inverseMass;
				Vec2 vec = composites[l].combinedBody.velocity * deltaTime;
				composites[l].combinedBody.force = Vec2.zero;
				composites[l].position += vec;
				composites[l].combinedBody.orientation += deltaTime * composites[l].combinedBody.angularVelocity;
				composites[l].combinedBody.orientation = (composites[l].combinedBody.orientation % Fix.PiTimes2 + Fix.PiTimes2) % Fix.PiTimes2;
				composites[l].combinedBody.velocity *= ((deltaTime == Fix.Zero) ? Fix.One : composites[l].combinedBody.airDrag);
				composites[l].combinedBody.angularVelocity *= ((deltaTime == Fix.Zero) ? Fix.One : composites[l].combinedBody.rotationalDrag);
				UnityEngine.Debug.DrawRay((Vector3)composites[l].position, Vector3.up * 0.15f, UnityEngine.Color.magenta);
				UnityEngine.Debug.DrawRay((Vector3)composites[l].position, Vector3.down * 0.15f, UnityEngine.Color.magenta);
				UnityEngine.Debug.DrawRay((Vector3)composites[l].position, Vector3.left * 0.15f, UnityEngine.Color.magenta);
				UnityEngine.Debug.DrawRay((Vector3)composites[l].position, Vector3.right * 0.15f, UnityEngine.Color.magenta);
				Vec2 u = new Vec2(composites[l].combinedBody.orientation);
				for (int n = 0; n < composites[l].roundedRectIds.Count; n++)
				{
					int num3 = roundedRects.ColliderIndex(composites[l].roundedRectIds[n]);
					roundedRects.colliders[num3].Translate(vec);
					roundedRects.physicsBodies[num3].orientation = composites[l].combinedBody.orientation;
					roundedRects.colliders[num3].SetRotation(roundedRects.physicsBodies[num3].orientation);
				}
				for (int num4 = 0; num4 < composites[l].circleIds.Count; num4++)
				{
					int num5 = circles.ColliderIndex(composites[l].circleIds[num4]);
					Vec2 vec2 = Vec2.ComplexMul(circles.physicsBodies[num5].relativePos, u);
					circles.colliders[num5].center = composites[l].position + vec2;
					circles.physicsBodies[num5].orientation = composites[l].combinedBody.orientation + circles.physicsBodies[num5].relativeOrientation;
				}
				for (int num6 = 0; num6 < composites[l].boxIds.Count; num6++)
				{
					int num7 = boxes.ColliderIndex(composites[l].boxIds[num6]);
					Vec2 vec3 = Vec2.ComplexMul(boxes.physicsBodies[num7].relativePos, u);
					boxes.colliders[num7].center = composites[l].position + vec3;
					boxes.physicsBodies[num7].orientation = composites[l].combinedBody.orientation + boxes.physicsBodies[num7].relativeOrientation;
					boxes.colliders[num7].SetRotation(boxes.physicsBodies[num7].orientation);
				}
			}
		}
		bbCount = 0;
		Vec2 vec4 = default(Vec2);
		for (int num8 = 0; num8 < roundedRects.Length; num8++)
		{
			if (IsActive(roundedRects.physicsParents[num8]))
			{
				boundingBoxes[bbCount] = PhysTools.ComputeBoundingBox(roundedRects.colliders[num8], num8);
				bb_rope_rr[bbCount] = boundingBoxes[bbCount];
				bbCount++;
				vec4 += roundedRects.colliders[num8].Pos();
			}
		}
		roundedRectangleBBs = bbCount;
		for (int num9 = 0; num9 < circles.Length; num9++)
		{
			if (IsActive(circles.physicsParents[num9]))
			{
				boundingBoxes[bbCount] = PhysTools.ComputeBoundingBox(circles.colliders[num9], num9);
				bbCount++;
				vec4 += circles.colliders[num9].Pos();
			}
		}
		for (int num10 = 0; num10 < boxes.Length; num10++)
		{
			if (IsActive(boxes.physicsParents[num10]))
			{
				boundingBoxes[bbCount] = PhysTools.ComputeBoundingBox(boxes.colliders[num10], num10);
				bbCount++;
				vec4 += boxes.colliders[num10].Pos();
			}
		}
		int layer = LayerMask.NameToLayer("effect");
		for (int num11 = 0; num11 < ropes.ropeBodies.Length; num11++)
		{
			if (ropes.ropeBodies[num11].enabled)
			{
				bb_rope_rr[roundedRectangleBBs] = PhysTools.ComputeBoundingBox(ropes.ropeBodies[num11], layer);
				roundedRectangleBBs++;
			}
		}
		if (roundedRectangleBBs == 0)
		{
			roundedRectangleBBs = 1;
		}
		if (bbCount == 0)
		{
			bbCount = 1;
		}
		vec4 /= (Fix)bbCount;
		Vec2 vec5 = default(Vec2);
		for (int num12 = 0; num12 < roundedRects.Length; num12++)
		{
			Vec2 vec6 = vec4 - roundedRects.colliders[num12].Pos();
			vec6.x *= vec6.x;
			vec6.y *= vec6.y;
			vec5 += vec6;
		}
		sweepX_roundedRectanglesOnly = vec5.x > vec5.y;
		for (int num13 = 0; num13 < circles.Length; num13++)
		{
			Vec2 vec7 = vec4 - circles.colliders[num13].Pos();
			vec7.x *= vec7.x;
			vec7.y *= vec7.y;
			vec5 += vec7;
		}
		for (int num14 = 0; num14 < boxes.Length; num14++)
		{
			Vec2 vec8 = vec4 - boxes.colliders[num14].Pos();
			vec8.x *= vec8.x;
			vec8.y *= vec8.y;
			vec5 += vec8;
		}
		potentialColliderIds_BoxBox.Clear();
		potentialColliderIds_BoxRR.Clear();
		potentialColliderIds_CircleBox.Clear();
		potentialColliderIds_CircleCircle.Clear();
		potentialColliderIds_CircleRR.Clear();
		potentialColliderIds_RR_RR.Clear();
		if (vec5.x > vec5.y)
		{
			SortAndSweepXAxis(bbCount);
		}
		else
		{
			SortAndSweepYAxis(bbCount);
		}
		if (sweepX_roundedRectanglesOnly)
		{
			SortAndSweepXAxis_ropes(roundedRectangleBBs);
		}
		else
		{
			SortAndSweepYAxis_ropes(roundedRectangleBBs);
		}
		SimulateRopes_parallel(deltaTime);
		UpdateBeams();
		for (int num15 = 0; num15 < potentialColliderIds_RR_RR.Count; num15++)
		{
			int id = potentialColliderIds_RR_RR[num15].id1;
			int id2 = potentialColliderIds_RR_RR[num15].id2;
			if (!roundedRects.physicsBodies[id].SameCompositeAs(roundedRects.physicsBodies[id2]) && PhysTools.CollisionTest(roundedRects.colliders[id], roundedRects.colliders[id2], ref collisions[collisionCount]))
			{
				collisions[collisionCount].colliderIndexA = id;
				collisions[collisionCount].colliderIndexB = id2;
				Vector3 start = (Vector3)collisions[collisionCount].contactPoint;
				UnityEngine.Debug.DrawRay(start, Vector3.up * 0.15f, UnityEngine.Color.green);
				UnityEngine.Debug.DrawRay(start, Vector3.down * 0.15f, UnityEngine.Color.green);
				UnityEngine.Debug.DrawRay(start, Vector3.left * 0.15f, UnityEngine.Color.green);
				UnityEngine.Debug.DrawRay(start, Vector3.right * 0.15f, UnityEngine.Color.green);
				collisionCount++;
			}
		}
		for (int num16 = 0; num16 < collisionCount; num16++)
		{
			PrepareCollisionCallBacks(collisions[num16], roundedRects.colliders[collisions[num16].colliderIndexA], roundedRects.colliders[collisions[num16].colliderIndexB], roundedRects.physicsParents[collisions[num16].colliderIndexA], roundedRects.physicsParents[collisions[num16].colliderIndexB], roundedRects.physicsBodies[collisions[num16].colliderIndexA].velocity, roundedRects.physicsBodies[collisions[num16].colliderIndexB].velocity);
		}
		for (int num17 = 0; num17 < collisionCount; num17++)
		{
			if (!roundedRects.physicsBodies[collisions[num17].colliderIndexA].IsTrigger() && !roundedRects.physicsBodies[collisions[num17].colliderIndexB].IsTrigger())
			{
				PhysTools.ResolveCollision(collisions[num17], ref roundedRects.physicsBodies[collisions[num17].colliderIndexA], ref roundedRects.physicsBodies[collisions[num17].colliderIndexB], roundedRects.colliders[collisions[num17].colliderIndexA].box.center, roundedRects.colliders[collisions[num17].colliderIndexB].box.center);
				Vec2Pair vec2Pair = PhysTools.PositionalCorrection(collisions[num17], roundedRects.physicsBodies[collisions[num17].colliderIndexA].inverseMass, roundedRects.physicsBodies[collisions[num17].colliderIndexB].inverseMass);
				roundedRects.colliders[collisions[num17].colliderIndexA].box.center += vec2Pair.a;
				roundedRects.colliders[collisions[num17].colliderIndexB].box.center += vec2Pair.b;
				if (roundedRects.physicsBodies[collisions[num17].colliderIndexA].IsComposite())
				{
					roundedRects.physicsBodies[collisions[num17].colliderIndexA].compositeParent.position += vec2Pair.a;
				}
				if (roundedRects.physicsBodies[collisions[num17].colliderIndexB].IsComposite())
				{
					roundedRects.physicsBodies[collisions[num17].colliderIndexB].compositeParent.position += vec2Pair.b;
				}
			}
		}
		collisionCount = 0;
		for (int num18 = 0; num18 < potentialColliderIds_BoxRR.Count; num18++)
		{
			int id3 = potentialColliderIds_BoxRR[num18].id1;
			int id4 = potentialColliderIds_BoxRR[num18].id2;
			if (!boxes.physicsBodies[id3].SameCompositeAs(roundedRects.physicsBodies[id4]) && PhysTools.CollisionTest(boxes.colliders[id3], roundedRects.colliders[id4], ref collisions[collisionCount]))
			{
				collisions[collisionCount].colliderIndexA = id3;
				collisions[collisionCount].colliderIndexB = id4;
				Vector3 start2 = (Vector3)collisions[collisionCount].contactPoint;
