public class DPhysicsBox : MonoUpdatable, ICollisionCallback, IPhysicsCollider
{
	[SerializeField]
	private Vec2 startExtents;

	private PhysicsParent pp_local;

	private BoplBody body;

	private FixTransform fixTrans;

	public bool manuallyCallInit;

	[HideInInspector]
	public Fix minimumExtents = (Fix)0.001f;

	public List<ICollisionCallback> OnCollisionCallbackers = new List<ICollisionCallback>();

	private Fix scale = Fix.One;

	public Fix MaxScale = (Fix)5L;

	public Fix MinScale = (Fix)0.1f;

	public PhysicsParent pp
	{
		get
		{
			return pp_local;
		}
		set
		{
			pp_local = value;
		}
	}

	public Box physicsBox
	{
		get
		{
			return DetPhysics.Get().boxes.colliders[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)];
		}
		set
		{
			DetPhysics.Get().boxes.colliders[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)] = value;
		}
	}

	public Vec2 position
	{
		get
		{
			return fixTrans.position;
		}
		set
		{
			fixTrans.position = value;
		}
	}

	public Fix rotation
	{
		get
		{
			return fixTrans.rotation;
		}
		set
		{
			fixTrans.rotation = value;
		}
	}

	public Vec2 up
	{
		get
		{
			return fixTrans.up;
		}
		set
		{
			fixTrans.up = value;
		}
	}

	public Vec2 right
	{
		get
		{
			return fixTrans.right;
		}
		set
		{
			fixTrans.right = value;
		}
	}

	public Vec2 velocity
	{
		get
		{
			PhysicsBody physicsBody = DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)];
			if (!physicsBody.IsComposite())
			{
				return physicsBody.velocity;
			}
			return physicsBody.compositeParent.combinedBody.velocity;
		}
		set
		{
			if (DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].IsComposite())
			{
				DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].compositeParent.combinedBody.velocity = value;
			}
			else
			{
				DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].velocity = value;
			}
		}
	}

	public Fix angularVelocity
	{
		get
		{
			PhysicsBody physicsBody = DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)];
			if (!physicsBody.IsComposite())
			{
				return physicsBody.angularVelocity;
			}
			return physicsBody.compositeParent.combinedBody.angularVelocity;
		}
		set
		{
			if (DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].IsComposite())
			{
				DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].compositeParent.combinedBody.angularVelocity = value;
			}
			else
			{
				DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].angularVelocity = value;
			}
		}
	}

	public Fix inverseMass
	{
		get
		{
			PhysicsBody physicsBody = DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)];
			if (!physicsBody.IsComposite())
			{
				return physicsBody.inverseMass;
			}
			return physicsBody.compositeParent.combinedBody.inverseMass;
		}
		set
		{
			if (DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].IsComposite())
			{
				DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].compositeParent.combinedBody.inverseMass = value;
			}
			else
			{
				DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].inverseMass = value;
			}
		}
	}

	public Fix inverseMomentOfInertia
	{
		get
		{
			PhysicsBody physicsBody = DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)];
			if (!physicsBody.IsComposite())
			{
				return physicsBody.inverseMomentOfInertia;
			}
			return physicsBody.compositeParent.combinedBody.inverseMomentOfInertia;
		}
		set
		{
			if (DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].IsComposite())
			{
				DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].compositeParent.combinedBody.inverseMomentOfInertia = value;
			}
			else
			{
				DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].inverseMomentOfInertia = value;
			}
		}
	}

	public Fix Scale
	{
		get
		{
			return scale;
		}
		set
		{
			Fix fix = Fix.One / scale;
			scale = Fix.Min(Fix.Max(value, MinScale), MaxScale);
			fixTrans.SetScale_DPhysicsOnly(scale);
			fixTrans.GetComponent<IPlatformAttachable>()?.RepositionOnParent();
			Fix fix2 = fix * scale;
			if (initHasBeenCalled)
			{
				DetPhysics.Get().boxes.colliders[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].right *= fix2;
				DetPhysics.Get().boxes.colliders[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].up *= fix2;
				DetPhysics.Get().boxes.colliders[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].inverseExtents /= fix2;
			}
			else
			{
				startExtents *= fix2;
			}
		}
	}

	public Shape shape => Shape.Box;

	public bool initHasBeenCalled { get; set; }

	public Vec2 GetStartExtents()
	{
		return startExtents;
	}

	public Vec2 CalcExtents()
	{
		if (initHasBeenCalled)
		{
			Vec2 inverseExtents = DetPhysics.Get().boxes.colliders[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].inverseExtents;
			inverseExtents.x = Fix.One / inverseExtents.x;
			inverseExtents.y = Fix.One / inverseExtents.y;
			return inverseExtents;
		}
		return startExtents;
	}

	public void SetExtents(Vec2 newExtents)
	{
		if (newExtents.x == 0L)
		{
			newExtents.x = minimumExtents;
		}
		if (newExtents.y == 0L)
		{
			newExtents.y = minimumExtents;
		}
		if (initHasBeenCalled)
		{
			DetPhysics.Get().boxes.colliders[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].UpdateExtents(newExtents);
		}
		else
		{
			startExtents = newExtents;
		}
	}

	public void UpdatePhysicsPositions()
	{
		if (initHasBeenCalled)
		{
			PhysicsBodyList<Box> boxes = DetPhysics.Get().boxes;
			if (IsComposite())
			{
				DetPhysics.Get().SynCompositeToFixTransAndRelativeValues(boxes.physicsBodies[boxes.ColliderIndex(pp.instanceId)].compositeParent);
				return;
			}
			int num = boxes.ColliderIndex(pp_local.instanceId);
			boxes.colliders[num].SetRotation(fixTrans.rotation);
			boxes.colliders[num].center = fixTrans.position + Vec2.ComplexMul(fixTrans.right, fixTrans.offset);
			boxes.physicsBodies[num].orientation = fixTrans.rotation;
		}
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		body = GetComponent<BoplBody>();
		fixTrans = GetComponent<FixTransform>();
		pp_local = new PhysicsParent
		{
			fixTrans = fixTrans,
			monobehaviourCollider = this,
			instanceId = base.gameObject.GetInstanceID(),
			collisionCallback = this,
			hierarchyNumber = base.HierarchyNumber
		};
	}

	public void ManualInit()
	{
		Initialize();
	}

	public override void Init()
	{
		if (!manuallyCallInit)
		{
			Initialize();
		}
	}

	public void Initialize()
	{
		pp_local = new PhysicsParent
		{
			fixTrans = fixTrans,
			monobehaviourCollider = this,
			instanceId = base.gameObject.GetInstanceID(),
			collisionCallback = this,
			hierarchyNumber = base.HierarchyNumber
		};
		if (startExtents.x == 0L)
		{
			startExtents.x = minimumExtents;
		}
		if (startExtents.y == 0L)
		{
			startExtents.y = minimumExtents;
		}
		if (body == null)
		{
			DetPhysics.Get().boxes.AddBody(pp_local, Box(), new PhysicsBody
			{
				inverseMass = -Fix.One,
				orientation = fixTrans.rotation
			});
		}
		else
		{
			DetPhysics.Get().boxes.AddBody(pp_local, Box(), body.NewPhysicsBody(fixTrans.rotation));
		}
		initHasBeenCalled = true;
	}

	private Box Box()
	{
		Vec2 vec = fixTrans.right * startExtents.x;
		Vec2 vec2 = fixTrans.up * startExtents.y;
		Vec2 inverseExtents = new Vec2(Fix.Abs(Fix.One / startExtents.x), Fix.Abs(Fix.One / startExtents.y));
		return new Box
		{
			center = fixTrans.position + Vec2.ComplexMul(fixTrans.offset, fixTrans.right),
			right = vec,
			up = vec2,
			inverseExtents = inverseExtents,
			layer = base.gameObject.layer
		};
	}

	public override bool IsEnabled()
	{
		return false;
	}

	public override void UpdateSim(Fix deltaTime)
	{
	}

	public PhysicsParent GetPhysicsParent()
	{
		return pp;
	}

	public void RegisterCollisionCallback(ICollisionCallback callback)
	{
		OnCollisionCallbackers.Add(callback);
		int num = 0;
		for (int num2 = OnCollisionCallbackers.Count - 2; num2 >= 0; num2--)
		{
			if (OnCollisionCallbackers[num2].HierarchyNumber > callback.HierarchyNumber)
			{
				num++;
			}
		}
		int num3 = OnCollisionCallbackers.Count - num - 1;
		ICollisionCallback value = callback;
		for (int i = num3; i < OnCollisionCallbackers.Count; i++)
		{
			ICollisionCallback collisionCallback = OnCollisionCallbackers[i];
			OnCollisionCallbackers[i] = value;
			value = collisionCallback;
		}
	}

	public void UnRegisterCollisionCallback(ICollisionCallback callback)
	{
		OnCollisionCallbackers.Remove(callback);
	}

	public void OnCollide(CollisionInformation colInfo)
	{
		for (int i = 0; i < OnCollisionCallbackers.Count; i++)
		{
			OnCollisionCallbackers[i]?.OnCollide(colInfo);
		}
	}

	private void OnDrawGizmos()
	{
		FixTransform component = GetComponent<FixTransform>();
		Vector2 vector = (Vector2)CalcExtents();
		Vector3 vector2 = base.transform.right * vector.x;
		Vector3 vector3 = base.transform.up * vector.y;
		Vector3 obj = ((component == null) ? base.transform.position : (base.transform.position + base.transform.up * (float)component.offset.y + base.transform.right * (float)component.offset.x));
		Vector3 vector4 = obj + vector2 + vector3;
		Vector3 vector5 = obj + vector2 - vector3;
		Vector3 vector6 = obj - vector2 + vector3;
		Vector3 vector7 = obj - vector2 - vector3;
		Gizmos.color = UnityEngine.Color.green;
		Gizmos.DrawLine(vector4, vector5);
		Gizmos.DrawLine(vector5, vector7);
		Gizmos.DrawLine(vector7, vector6);
		Gizmos.DrawLine(vector6, vector4);
	}

	public void AddForceAtPosition(Vec2 f, Vec2 pos, ForceMode2D forceMode)
	{
		if (forceMode == ForceMode2D.Impulse)
		{
			f *= (Fix)60L;
		}
		Vec2 contactVector = Vec2.NormalizedSafe(pos - position);
		PhysicsBody physicsBody = DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)];
		if (physicsBody.IsComposite())
		{
			PhysTools.ApplyImpulseToBody(f, contactVector, ref physicsBody.compositeParent.combinedBody);
		}
		else
		{
			PhysTools.ApplyImpulseToBody(f, contactVector, ref DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)]);
		}
	}

	public void SetRelativePositionOfChildBody(Vec2 relativePos, Vec2 relativeRightVector)
	{
		DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].relativePos = relativePos + Vec2.ComplexMul(relativeRightVector, fixTrans.offset);
	}

	public void SetRelativeOrientationOfChildBody(Fix rotation)
	{
		DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].relativeOrientation = rotation;
	}

	public PhysicsBody GetBody()
	{
		PhysicsBody result = DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)];
		if (!result.IsComposite())
		{
			return result;
		}
		return result.compositeParent.combinedBody;
	}

	public void AddForce(Vec2 force)
	{
		int num = DetPhysics.Get().boxes.ColliderIndex(pp.instanceId);
		PhysicsBodyList<Box> boxes = DetPhysics.Get().boxes;
		if (boxes.physicsBodies[num].IsComposite())
		{
			boxes.physicsBodies[num].compositeParent.combinedBody.force += force;
		}
		else
		{
			boxes.physicsBodies[num].force += force;
		}
	}

	public int Cast(ref PhysicsParent[] hitObjects, LayerMask mask)
	{
		int num = DetPhysics.Get().boxes.ColliderIndex(pp.instanceId);
		return DetPhysics.Get().CollideBox(DetPhysics.Get().boxes.colliders[num], ref hitObjects, mask);
	}

	public bool IsComposite()
	{
		return DetPhysics.Get().boxes.physicsBodies[DetPhysics.Get().boxes.ColliderIndex(pp.instanceId)].IsComposite();
	}

	bool IPhysicsCollider.get_enabled()
	{
		return base.enabled;
	}

	void IPhysicsCollider.set_enabled(bool value)
	{
		base.enabled = value;
	}
}
public interface IPhysicsCollider
{
	Vec2 position { get; set; }

	Fix rotation { get; set; }

	Vec2 up { get; set; }

	Vec2 right { get; set; }

	Vec2 velocity { get; set; }

	Fix angularVelocity { get; set; }

	bool enabled { get; set; }

	bool IsDestroyed { get; set; }

