	PhysicsBody GetBody();

	void AddForce(Vec2 force);

	void SetRelativePositionOfChildBody(Vec2 relativePos, Vec2 relativeRightVector);

	void SetRelativeOrientationOfChildBody(Fix rotation);

	void UpdatePhysicsPositions();

	bool IsComposite();
}
