public class DPhysicsRoundedRect : MonoUpdatable, ICollisionCallback, IPhysicsCollider
{
	[SerializeField]
	private Vec2 startExtents;

	[SerializeField]
	private Fix startRadius = (Fix)0.3f;

	private PhysicsParent pp_local;

	private BoplBody body;

	private FixTransform fixTrans;

	private StickyRoundedRectangle stickyRR;

	private int lethalTerrainLayer;

	private int nonLethalTerrainLayer;

	private int projectileLayer;

	public bool manuallyCallInit;

	private Fix scale = Fix.One;

	public Fix MaxScale = (Fix)5L;

	public Fix MinScale = (Fix)0.1f;

	[NonSerialized]
	public Fix timeSinceLastScaledUp;

	public List<ICollisionCallback> OnCollisionCallbackers = new List<ICollisionCallback>();

	public PhysicsParent pp
	{
		get
		{
			return pp_local;
		}
		set
		{
			pp_local = value;
		}
	}

	public bool initHasBeenCalled { get; set; }

	public Fix radius
	{
		get
		{
			if (!initHasBeenCalled)
			{
				return startRadius;
			}
			return DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)].radius;
		}
		set
		{
			if (initHasBeenCalled)
			{
				DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)].radius = value;
			}
			else
			{
				startRadius = value;
			}
		}
	}

	public Shape shape => Shape.RoundedRect;

	public Fix Scale
	{
		get
		{
			return scale;
		}
		set
		{
			if (stickyRR != null && scale > stickyRR.baseScaleForPlatform && scale < value)
			{
				timeSinceLastScaledUp = Fix.Zero;
			}
			Fix fix = Fix.One / scale;
			scale = Fix.Min(Fix.Max(value, MinScale), MaxScale);
			fixTrans.SetScale_DPhysicsOnly(scale);
			Fix fix2 = fix * scale;
			if (stickyRR != null)
			{
				int childCount = base.transform.childCount;
				float num = 1f / (float)fix2;
				_ = (float)fix;
				_ = (float)scale;
				for (int i = 0; i < childCount; i++)
				{
					Transform child = base.transform.GetChild(i);
					if (child.gameObject.layer != lethalTerrainLayer && child.gameObject.layer != nonLethalTerrainLayer && child.gameObject.layer != projectileLayer)
					{
						continue;
					}
					IPlatformAttachable component = child.GetComponent<IPlatformAttachable>();
					if (component != null)
					{
						float x = child.transform.localScale.x * num;
						float y = child.transform.localScale.y * num;
						child.transform.localScale = new Vector3(x, y, 1f);
						IPhysicsCollider component2 = child.GetComponent<IPhysicsCollider>();
						if (component2 != null)
						{
							component2.GetPhysicsParent().fixTrans.startScale *= num;
						}
						component.RepositionOnParent();
					}
				}
			}
			radius *= fix2;
			if (initHasBeenCalled)
			{
				DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)].box.right *= fix2;
				DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)].box.up *= fix2;
				DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)].box.inverseExtents /= fix2;
			}
			else
			{
				startExtents *= fix2;
			}
		}
	}

	public Vec2 position
	{
		get
		{
			return fixTrans.position;
		}
		set
		{
			fixTrans.position = value;
		}
	}

	public Fix rotation
	{
		get
		{
			return fixTrans.rotation;
		}
		set
		{
			fixTrans.rotation = value;
		}
	}

	public Vec2 up
	{
		get
		{
			return fixTrans.up;
		}
		set
		{
			fixTrans.up = value;
		}
	}

	public Vec2 right
	{
		get
		{
			return fixTrans.right;
		}
		set
		{
			fixTrans.right = value;
		}
	}

