	public void ManualInit()
	{
		Initialize();
	}

	public override void Init()
	{
		if (!manuallyCallInit)
		{
			Initialize();
		}
	}

	public void Initialize()
	{
		pp_local = new PhysicsParent
		{
			fixTrans = fixTrans,
			monobehaviourCollider = this,
			instanceId = base.gameObject.GetInstanceID(),
			collisionCallback = this,
			hierarchyNumber = base.HierarchyNumber
		};
		if (body == null)
		{
			DetPhysics.Get().roundedRects.AddBody(pp_local, RoundedRect(), new PhysicsBody
			{
				inverseMass = -Fix.One,
				orientation = fixTrans.rotation
			});
		}
		else
		{
			DetPhysics.Get().roundedRects.AddBody(pp_local, RoundedRect(), body.NewPhysicsBody(fixTrans.rotation));
		}
		initHasBeenCalled = true;
	}

	public Vec2 CalcExtents()
	{
		if (initHasBeenCalled)
		{
			Vec2 inverseExtents = DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)].box.inverseExtents;
			inverseExtents.x = Fix.One / inverseExtents.x;
			inverseExtents.y = Fix.One / inverseExtents.y;
			return inverseExtents;
		}
		return startExtents;
	}

	public void SetExtents(Vec2 newExtents)
	{
		if (initHasBeenCalled)
		{
			DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)].box.UpdateExtents(newExtents);
		}
		else
		{
			startExtents = newExtents;
		}
	}

	public void SetBounciness(Fix newBounciness)
	{
		if (initHasBeenCalled)
		{
			DetPhysics.Get().roundedRects.physicsBodies[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)].bounciness = newBounciness;
		}
		else
		{
			body.bounciness = newBounciness;
		}
	}

	public void UpdatePhysicsPositions()
	{
		if (initHasBeenCalled)
		{
			PhysicsBodyList<RoundedRect> roundedRects = DetPhysics.Get().roundedRects;
			if (IsComposite())
			{
				DetPhysics.Get().SynCompositeToFixTransAndRelativeValues(roundedRects.physicsBodies[roundedRects.ColliderIndex(pp.instanceId)].compositeParent);
				return;
			}
			int num = roundedRects.ColliderIndex(pp_local.instanceId);
			roundedRects.colliders[num].SetRotation(fixTrans.rotation);
			roundedRects.colliders[num].box.center = fixTrans.position + Vec2.ComplexMul(fixTrans.right, fixTrans.offset);
			roundedRects.physicsBodies[num].orientation = fixTrans.rotation;
		}
	}

	private RoundedRect RoundedRect()
	{
		Vec2 vec = fixTrans.right * startExtents.x;
		Vec2 vec2 = fixTrans.up * startExtents.y;
		Fix value = ((startExtents.x == Fix.Zero) ? Fix.Zero : (Fix.One / startExtents.x));
		Fix value2 = ((startExtents.y == Fix.Zero) ? Fix.Zero : (Fix.One / startExtents.y));
		Vec2 inverseExtents = new Vec2(Fix.Abs(value), Fix.Abs(value2));
		Box box = new Box
		{
			center = fixTrans.position + Vec2.ComplexMul(fixTrans.offset, fixTrans.right),
			right = vec,
			up = vec2,
			inverseExtents = inverseExtents,
			layer = base.gameObject.layer
		};
		return new RoundedRect
		{
			box = box,
			radius = startRadius,
			layer = base.gameObject.layer
		};
	}

	public RoundedRect AsRoundedRect()
	{
		Vec2 vec = CalcExtents();
		Vec2 vec2 = fixTrans.right * vec.x;
		Vec2 vec3 = fixTrans.up * vec.y;
		Fix value = ((vec.x == Fix.Zero) ? Fix.Zero : (Fix.One / vec.x));
		Fix value2 = ((vec.y == Fix.Zero) ? Fix.Zero : (Fix.One / vec.y));
		vec = new Vec2(Fix.Abs(value), Fix.Abs(value2));
		Box box = new Box
		{
			center = fixTrans.position + Vec2.ComplexMul(fixTrans.offset, fixTrans.right),
			right = vec2,
			up = vec3,
			inverseExtents = vec,
			layer = base.gameObject.layer
		};
		return new RoundedRect
		{
			box = box,
			radius = startRadius,
			layer = base.gameObject.layer
		};
	}

	private void OnValidate()
	{
		if (startExtents.x < (Fix)0.01f)
		{
			startExtents.x = (Fix)0.01f;
		}
		if (startExtents.y < (Fix)0.01f)
		{
			startExtents.y = (Fix)0.01f;
		}
		if (startRadius < Fix.Zero)
		{
			startRadius = Fix.Zero;
		}
	}

