	public void RegisterCollisionCallback(ICollisionCallback callback)
	{
		OnCollisionCallbackers.Add(callback);
		int num = 0;
		for (int num2 = OnCollisionCallbackers.Count - 2; num2 >= 0; num2--)
		{
			if (OnCollisionCallbackers[num2].HierarchyNumber > callback.HierarchyNumber)
			{
				num++;
			}
		}
		int num3 = OnCollisionCallbackers.Count - num - 1;
		ICollisionCallback value = callback;
		for (int i = num3; i < OnCollisionCallbackers.Count; i++)
		{
			ICollisionCallback collisionCallback = OnCollisionCallbackers[i];
			OnCollisionCallbackers[i] = value;
			value = collisionCallback;
		}
	}

	public void UnRegisterCollisionCallback(ICollisionCallback callback)
	{
		OnCollisionCallbackers.Remove(callback);
	}

	public void OnCollide(CollisionInformation colInfo)
	{
		for (int i = 0; i < OnCollisionCallbackers.Count; i++)
		{
			OnCollisionCallbackers[i]?.OnCollide(colInfo);
		}
	}

	private void OnDrawGizmos()
	{
		Fix fix = Fix.One;
		if (!initHasBeenCalled)
		{
			GrowOnStart component = GetComponent<GrowOnStart>();
			if (component != null)
			{
				fix = component.scaleUp;
			}
		}
		Vec2 vec = CalcExtents() * fix;
		Vector3 vector = base.transform.right * ((float)vec.x + (float)radius * (float)fix);
		Vector3 vector2 = base.transform.up * ((float)vec.y + (float)radius * (float)fix);
		Vector3 vector3 = base.transform.right * (float)vec.x;
		Vector3 vector4 = base.transform.up * (float)vec.y;
		FixTransform component2 = GetComponent<FixTransform>();
		Vector3 obj = ((component2 == null) ? base.transform.position : (base.transform.position + base.transform.up * (float)component2.offset.y + base.transform.right * (float)component2.offset.x));
		Vector3 vector5 = obj + vector3 + vector2;
		Vector3 to = obj - vector3 + vector2;
		Vector3 vector6 = obj + vector3 - vector2;
		Vector3 to2 = obj - vector3 - vector2;
		Gizmos.DrawLine(vector5, to);
		Gizmos.DrawLine(vector6, to2);
		vector5 = obj + vector + vector4;
		to = obj - vector + vector4;
		vector6 = obj + vector - vector4;
		to2 = obj - vector - vector4;
		Gizmos.DrawLine(to, to2);
		Gizmos.DrawLine(vector5, vector6);
		vector5 = obj + vector3 + vector4;
		to = obj - vector3 + vector4;
		vector6 = obj + vector3 - vector4;
		to2 = obj - vector3 - vector4;
		Gizmos.DrawWireSphere(vector5, (float)radius * (float)fix);
		Gizmos.DrawWireSphere(vector6, (float)radius * (float)fix);
		Gizmos.DrawWireSphere(to, (float)radius * (float)fix);
		Gizmos.DrawWireSphere(to2, (float)radius * (float)fix);
	}

	public RoundedRect GetRoundedRect()
	{
		return DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)];
