	public void AddForceAtPosition(Vec2 f, Vec2 pos, ForceMode2D forceMode)
	{
		if (forceMode == ForceMode2D.Impulse)
		{
			f *= (Fix)60L;
		}
		Vec2 contactVector = Vec2.NormalizedSafe(pos - position);
		PhysicsBody physicsBody = DetPhysics.Get().roundedRects.physicsBodies[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)];
		if (physicsBody.IsComposite())
		{
			PhysTools.ApplyImpulseToBody(f, contactVector, ref physicsBody.compositeParent.combinedBody);
		}
		else
		{
			PhysTools.ApplyImpulseToBody(f, contactVector, ref DetPhysics.Get().roundedRects.physicsBodies[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)]);
		}
	}

	public PhysicsBody GetBody()
	{
		PhysicsBody result = DetPhysics.Get().roundedRects.physicsBodies[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)];
		if (!result.IsComposite())
		{
			return result;
		}
		return result.compositeParent.combinedBody;
	}

	public void SetGravityScale(Fix newGravityScale)
	{
		int num = DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId);
		PhysicsBodyList<RoundedRect> roundedRects = DetPhysics.Get().roundedRects;
		roundedRects.physicsBodies[num].gravityScale = newGravityScale;
		if (roundedRects.physicsBodies[num].IsComposite())
		{
			roundedRects.physicsBodies[num].compositeParent.combinedBody.gravityScale = newGravityScale;
		}
	}

	public void AddForce(Vec2 force)
	{
		int num = DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId);
		PhysicsBodyList<RoundedRect> roundedRects = DetPhysics.Get().roundedRects;
		if (roundedRects.physicsBodies[num].IsComposite())
		{
			roundedRects.physicsBodies[num].compositeParent.combinedBody.force += force;
		}
		else
		{
			roundedRects.physicsBodies[num].force += force;
		}
	}

	public Fix PlatformArea()
	{
		RoundedRect roundedRect = GetRoundedRect();
		Fix rHeight = Fix.One / roundedRect.box.inverseExtents.y;
		Fix rWidth = Fix.One / roundedRect.box.inverseExtents.x;
		return PlatformArea(rWidth, rHeight, roundedRect.radius);
	}

	public Fix PlatformArea(Fix rWidth, Fix rHeight, Fix radius)
	{
		Fix fix = (Fix)2L * rHeight * radius;
		Fix fix2 = ((Fix)2L * rHeight + (Fix)2L * radius) * (Fix)2L * rWidth;
		Fix fix3 = Fix.Pi * radius * radius;
		return fix * (Fix)2L + fix2 + fix3;
	}

	public void SetRelativePositionOfChildBody(Vec2 relativePos, Vec2 relativeRightVector)
	{
	}

	public void SetRelativeOrientationOfChildBody(Fix rotation)
	{
	}

	public Fix ApproximateMOI(Fix w, Fix h, Fix r)
	{
		w += r;
		h += r;
		Fix fix = Fix.Max(w, h);
		return Fix.Min(w, h) * fix * fix * (Fix)0.2f + (Fix)40L;
	}

	public bool IsComposite()
	{
		return DetPhysics.Get().roundedRects.physicsBodies[DetPhysics.Get().roundedRects.ColliderIndex(pp.instanceId)].IsComposite();
	}

