public class FixTransform : MonoBehaviour, ISerializationCallbackReceiver
{
	[NonSerialized]
	public Vec2 position;

	public Vec2 offset;

	private Fix rotationInner;

	private Vec2 upInner;

	private Vec2 rightInner;

	[HideInInspector]
	[SerializeField]
	private Vec2 _position;

	[HideInInspector]
	[SerializeField]
	private Fix _rotation;

	[HideInInspector]
	[SerializeField]
	private Vec2 _up;

	[HideInInspector]
	[SerializeField]
	private Vec2 _right;

	private Fix scale = Fix.One;

	public Fix rotation
	{
		get
		{
			return rotationInner;
		}
		set
		{
			rotationInner = value;
			rightInner = new Vec2(value);
			upInner = Vec2.MulByI(rightInner);
		}
	}

	public Vec2 up
	{
		get
		{
			return upInner;
		}
		set
		{
			upInner = value;
			rightInner = Vec2.MulByNegI(upInner);
			rotationInner = Vec2.NormalizedVectorAngle(rightInner);
		}
	}

	public Vec2 right
	{
		get
		{
			return rightInner;
		}
		set
		{
			rightInner = value;
			upInner = Vec2.MulByI(rightInner);
			rotationInner = Vec2.NormalizedVectorAngle(rightInner);
		}
	}

	public Vec2 serializedPosition => _position;

	public Fix serializedRotation => _rotation;

	public Fix Scale => scale;

	public Vector3 startScale { get; set; }

	public bool IsDestroyed { get; set; }

	public bool IsDuplicated { get; set; }

	public void Awake()
	{
		position = _position;
		rotationInner = _rotation;
		upInner = _up;
		rightInner = _right;
		startScale = base.transform.localScale;
	}

	public void SetScale_DPhysicsOnly(Fix scale)
	{
		Fix fix = this.scale;
		offset *= scale / fix;
		this.scale = scale;
		float num = (float)scale;
		float num2 = Mathf.Sign(base.transform.localScale.x);
		float num3 = Mathf.Sign(base.transform.localScale.y);
		base.transform.localScale = new Vector3(startScale.x * num * num2, startScale.y * num * num3, 1f);
	}

	public void LateUpdate()
	{
		SyncTransform();
	}

	public void SyncTransform()
	{
		base.transform.SetPositionAndRotation((Vector3)position, Quaternion.AngleAxis((float)rotationInner * 57.29578f, Vector3.forward));
	}

	public static T InstantiateFixed<T>(T prefab, Vec2 pos, Fix rotation) where T : MonoBehaviour
	{
		Updater.BeginRegisterPrefab();
		T val = UnityEngine.Object.Instantiate(prefab, (Vector3)pos, Quaternion.AngleAxis((float)rotation * 57.29578f, Vector3.forward));
		Updater.EndRegisterPrefab();
		FixTransform component = val.GetComponent<FixTransform>();
		component.position = pos;
		component.rotation = rotation;
		return val;
	}

	public static GameObject InstantiateFixed(GameObject prefab, Vec2 pos, Fix rotation)
	{
		Updater.BeginRegisterPrefab();
		GameObject gameObject = UnityEngine.Object.Instantiate(prefab, (Vector3)pos, Quaternion.AngleAxis((float)rotation * 57.29578f, Vector3.forward));
		if (!gameObject.activeSelf)
		{
			gameObject.SetActive(value: true);
			gameObject.SetActive(value: false);
		}
		Updater.EndRegisterPrefab();
		FixTransform component = gameObject.GetComponent<FixTransform>();
		component.position = pos;
		component.rotation = rotation;
		return gameObject;
	}

	public static T InstantiateFixed<T>(T prefab, Vec2 pos) where T : MonoBehaviour
	{
		Updater.BeginRegisterPrefab();
		T val = UnityEngine.Object.Instantiate(prefab, (Vector3)pos, Quaternion.identity);
		Updater.EndRegisterPrefab();
		FixTransform component = val.GetComponent<FixTransform>();
		component.position = pos;
		component.rotationInner = Fix.Zero;
		component.upInner = Vec2.up;
		component.rightInner = Vec2.right;
		return val;
	}

	public static GameObject InstantiateFixed(GameObject prefab, Vec2 pos)
	{
		Updater.BeginRegisterPrefab();
		GameObject gameObject = UnityEngine.Object.Instantiate(prefab, (Vector3)pos, Quaternion.identity);
		if (!gameObject.activeSelf)
		{
			gameObject.SetActive(value: true);
			gameObject.SetActive(value: false);
		}
		Updater.EndRegisterPrefab();
		FixTransform component = gameObject.GetComponent<FixTransform>();
		component.position = pos;
		component.rotationInner = Fix.Zero;
		component.upInner = Vec2.up;
		component.rightInner = Vec2.right;
		return gameObject;
	}

	public Fix ComputeCheckSum()
	{
		return position.x * (Fix)2L + position.y * (Fix)3L + rotation * (Fix)5L;
	}

	public void OnValidate()
	{
		updateFixedValues();
	}

	private void Reset()
	{
		updateFixedValues();
	}

	public void updateFixedValues()
	{
	}

	public void OnBeforeSerialize()
	{
		updateFixedValues();
	}

	public void OnAfterDeserialize()
	{
	}
