public class PhysicsBodyList<T>
{
	private int nrOfColliders;

	public T[] colliders;

	public PhysicsBody[] physicsBodies;

	public PhysicsParent[] physicsParents;

	private Dictionary<int, int> instanceIdToColliderIndex;

	public int Length => nrOfColliders;

	public int ColliderIndex(int id)
	{
		return instanceIdToColliderIndex[id];
	}

	public PhysicsBodyList()
	{
		colliders = new T[1024];
		physicsParents = new PhysicsParent[1024];
		instanceIdToColliderIndex = new Dictionary<int, int>(1024);
		physicsBodies = new PhysicsBody[1024];
	}

	public PhysicsBodyList(int capacity)
	{
		colliders = new T[capacity];
		physicsParents = new PhysicsParent[capacity];
		instanceIdToColliderIndex = new Dictionary<int, int>(capacity);
		physicsBodies = new PhysicsBody[capacity];
	}

	public void AddCollider(PhysicsParent obj, T collider)
	{
		colliders[nrOfColliders] = collider;
		physicsParents[nrOfColliders] = obj;
		instanceIdToColliderIndex.Add(obj.instanceId, nrOfColliders);
		nrOfColliders++;
	}

	public void UpdateCollider(PhysicsParent obj, T collider)
	{
		colliders[instanceIdToColliderIndex[obj.instanceId]] = collider;
	}

	public void RemoveCollider(PhysicsParent obj)
	{
		int num = instanceIdToColliderIndex[obj.instanceId];
		instanceIdToColliderIndex.Remove(obj.instanceId);
		if (nrOfColliders - num - 1 >= 0)
		{
			for (int i = num + 1; i < nrOfColliders; i++)
			{
				instanceIdToColliderIndex[physicsParents[i].instanceId]--;
			}
			Array.Copy(colliders, num + 1, colliders, num, nrOfColliders - num - 1);
			Array.Copy(physicsParents, num + 1, physicsParents, num, nrOfColliders - num - 1);
			Array.Copy(physicsBodies, num + 1, physicsBodies, num, nrOfColliders - num - 1);
			nrOfColliders--;
		}
	}

	public void AddBody(PhysicsParent obj, T collider, PhysicsBody body)
	{
		physicsBodies[nrOfColliders] = body;
		AddCollider(obj, collider);
	}

	public void UpdateBody(PhysicsParent obj, T collider, PhysicsBody body)
	{
		int num = instanceIdToColliderIndex[obj.instanceId];
		colliders[num] = collider;
		physicsBodies[num] = body;
	}

	public bool ContainsParent(int instanceId)
	{
		return instanceIdToColliderIndex.ContainsKey(instanceId);
	}
}
public struct CollisionManifold
{
	public int colliderIndexA;

	public int colliderIndexB;

	public Fix penetration;

	public Vec2 normal;

