public class RaycastComparer : IComparer<RaycastInformation>
{
	public int Compare(RaycastInformation x, RaycastInformation y)
	{
		if (!(x.nearDist == y.nearDist))
		{
			return Fix.Sign(x.nearDist - y.nearDist);
		}
		return x.pp.hierarchyNumber - y.pp.hierarchyNumber;
	}
}
public struct RaycastInformation
{
	public Vec2 nearPos;

	public Vec2 farPos;

	public Fix nearDist;

	public Fix farDist;

	public int layer;

	public PhysicsParent pp;

	public static implicit operator bool(RaycastInformation hit)
	{
		return hit.nearDist != Fix.MaxValue;
	}

	public bool HitSomething()
	{
		return this;
	}

	public static RaycastInformation Empty()
	{
		return new RaycastInformation
		{
			nearDist = Fix.MaxValue
		};
	}
}
public static class PhysTools
{
	private static readonly Fix posCorrectionStr = (Fix)0.3f;

	private static readonly Fix slop = (Fix)0.01f;

	public const float RadiansToDegrees = 180f / MathF.PI;

	public const float DegreesToRadians = MathF.PI / 180f;

	public static bool LineToLineIntersection(Vec2 posA, Vec2 dirA, Fix lengthA, Vec2 posB, Vec2 dirB, Fix lengthB, out Vec2 distAlongAB)
	{
		posB -= posA;
		Vec2 vec = Vec2.MulByI(dirB);
		Vec2 vec2 = Vec2.Dot(posB, vec) * vec;
		Fix fix = Vec2.Dot(vec2, dirA);
		if (fix == 0L)
		{
			distAlongAB = Vec2.zero;
			return false;
		}
		Fix fix2 = Vec2.Dot(vec2, vec2) / fix;
		Fix fix3 = Vec2.Dot(dirA * fix2 - posB, dirB);
		distAlongAB = new Vec2(fix2, fix3);
		if (fix2 > 0L && fix2 < lengthA && fix3 > 0L)
		{
			return fix3 < lengthB;
		}
		return false;
	}

	public static bool CollisionTest(Circle c1, Circle c2)
	{
		Fix fix = c1.radius + c2.radius;
		fix *= fix;
		return Vec2.SqrMagnitude(c2.center - c1.center) < fix;
	}

	public static bool CollisionTest(Circle c1, Circle c2, ref CollisionManifold collisionInfo)
	{
		Fix fix = c1.radius + c2.radius;
		fix *= fix;
		Vec2 vec = c2.center - c1.center;
		Fix fix2 = Vec2.SqrMagnitude(vec);
		if (fix2 > fix)
		{
			return false;
		}
		Fix fix3 = Fix.Sqrt(fix2);
		if (fix3 != Fix.Zero)
		{
			collisionInfo.normal = vec / fix3;
			collisionInfo.penetration = c1.radius + c2.radius - fix3;
			collisionInfo.contactPoint = c1.center + collisionInfo.normal * c1.radius;
			return true;
		}
		collisionInfo.normal = Vec2.right;
		collisionInfo.penetration = c1.radius + c2.radius;
		collisionInfo.contactPoint = c1.center;
		return true;
	}

	public static bool CollisionTest(AABB r1, AABB r2)
	{
		if (r1.max.x > r2.min.x && r1.min.x < r2.max.x && r1.max.y > r2.min.y)
		{
			return r1.min.y < r2.max.y;
		}
		return false;
	}

	public static bool CollisionTest(AABB r1, AABB r2, ref CollisionManifold collisionInfo)
	{
		if (!CollisionTest(r1, r2))
		{
			return false;
		}
		Vec2 vec = (r1.max - r1.min) * (Fix)0.5f;
		Vec2 vec2 = (r2.max - r2.min) * (Fix)0.5f;
		Vec2 vec3 = r1.min + vec;
		Vec2 vec4 = r2.min + vec2 - vec3;
		Fix fix = vec.x + vec2.x - Fix.Abs(vec4.x);
		Fix fix2 = vec.y + vec2.y - Fix.Abs(vec4.y);
		if (fix < fix2)
		{
			collisionInfo.normal = new Vec2((vec4.x > Fix.Zero) ? Fix.One : (-Fix.One), Fix.Zero);
			collisionInfo.penetration = fix;
		}
		else
		{
			collisionInfo.normal = new Vec2(Fix.Zero, (vec4.y > Fix.Zero) ? Fix.One : (-Fix.One));
			collisionInfo.penetration = fix2;
		}
		vec.x *= (Fix)Fix.Sign(vec4.x);
		vec.y *= (Fix)Fix.Sign(vec4.y);
		collisionInfo.contactPoint = vec3 + vec;
		return true;
	}

	public static bool CollisionTest(Box b1, RoundedRect r2, ref CollisionManifold collisionManifold)
	{
		return CollisionTest(new RoundedRect
		{
			box = b1,
			radius = Fix.Zero
		}, r2, ref collisionManifold);
	}

	public static bool CollisionTest(Box b1, RoundedRect r2)
	{
		return CollisionTest(new RoundedRect
		{
			box = b1,
			radius = Fix.Zero
		}, r2);
	}

	public static bool CollisionTest(AABB r, Box r2)
	{
		Vec2 vec = (r.max - r.min) * (Fix)0.5;
		Vec2 center = r.min + vec;
		Vec2 inverseExtents = new Vec2(Fix.One / vec.x, Fix.One / vec.y);
		return CollisionTest(new Box
		{
			center = center,
			right = Vec2.right * vec.x,
			up = Vec2.up * vec.y,
			inverseExtents = inverseExtents
		}, r2);
	}

	public static bool CollisionTest(AABB r, RoundedRect r2, ref CollisionManifold collisionManifold)
	{
		Vec2 vec = (r.max - r.min) * (Fix)0.5;
		Vec2 center = r.min + vec;
		Vec2 inverseExtents = new Vec2(Fix.One / vec.x, Fix.One / vec.y);
		return CollisionTest(new RoundedRect
		{
			box = new Box
			{
				center = center,
				right = Vec2.right * vec.x,
				up = Vec2.up * vec.y,
				inverseExtents = inverseExtents
			},
			radius = Fix.Zero
		}, r2, ref collisionManifold);
	}

	public static bool CollisionTest(RoundedRect r1, RoundedRect r2, ref CollisionManifold collisionManifold)
	{
		Vec2 vec = r1.box.center + r1.box.right + r1.box.up;
		Vec2 vec2 = r1.box.center + r1.box.right - r1.box.up;
		Vec2 vec3 = r1.box.center - r1.box.right + r1.box.up;
		Vec2 bl = r1.box.center - r1.box.right - r1.box.up;
		Vec2 vec4 = r2.box.center + r2.box.right + r2.box.up;
		Vec2 vec5 = r2.box.center + r2.box.right - r2.box.up;
		Vec2 vec6 = r2.box.center - r2.box.right + r2.box.up;
		Vec2 bl2 = r2.box.center - r2.box.right - r2.box.up;
		Vec2 vec7 = r1.box.right * r1.box.inverseExtents.x;
		Fix minPen = Fix.MaxValue;
		Vec2 minDir = vec7;
		Vec2 minMax = MinMaxProjection(vec, vec3, vec7);
		Vec2 minMax2 = MinMaxProjection(vec4, vec5, vec6, bl2, vec7);
		minMax.x -= r1.radius;
		minMax.y += r1.radius;
		minMax2.x -= r2.radius;
		minMax2.y += r2.radius;
		if (SATRR(minMax, minMax2, vec7, ref minPen, ref minDir))
		{
			return false;
		}
		Vec2 vec8 = r1.box.up * r1.box.inverseExtents.y;
		Vec2 minMax3 = MinMaxProjection(vec, vec2, vec8);
		Vec2 minMax4 = MinMaxProjection(vec4, vec5, vec6, bl2, vec8);
		minMax3.x -= r1.radius;
		minMax3.y += r1.radius;
		minMax4.x -= r2.radius;
		minMax4.y += r2.radius;
		if (SATRR(minMax3, minMax4, vec8, ref minPen, ref minDir))
		{
			return false;
		}
		Vec2 vec9 = r2.box.right * r2.box.inverseExtents.x;
		Vec2 minMax5 = MinMaxProjection(vec, vec2, vec3, bl, vec9);
		Vec2 minMax6 = MinMaxProjection(vec4, vec6, vec9);
		minMax5.x -= r1.radius;
		minMax5.y += r1.radius;
		minMax6.x -= r2.radius;
		minMax6.y += r2.radius;
		if (SATRR(minMax5, minMax6, vec9, ref minPen, ref minDir))
		{
			return false;
		}
		Vec2 vec10 = r2.box.up * r2.box.inverseExtents.y;
		Vec2 minMax7 = MinMaxProjection(vec, vec2, vec3, bl, vec10);
		Vec2 minMax8 = MinMaxProjection(vec4, vec5, vec10);
		minMax7.x -= r1.radius;
		minMax7.y += r1.radius;
		minMax8.x -= r2.radius;
		minMax8.y += r2.radius;
		if (SATRR(minMax7, minMax8, vec10, ref minPen, ref minDir))
		{
			return false;
		}
		Fix fix = Fix.MaxValue;
		Vec2 vec11 = default(Vec2);
		Vec2 bestFaceNormal;
		Vec2Pair vec2Pair = CollisionFace(vec, vec2, vec3, bl, minDir, r1.box.inverseExtents, out bestFaceNormal);
		Vec2 bestFaceNormal2;
		Vec2Pair vec2Pair2 = CollisionFace(vec4, vec5, vec6, bl2, -minDir, r2.box.inverseExtents, out bestFaceNormal2);
		Vec2 vec12 = vec2Pair.a - vec2Pair2.a;
		Fix fix2 = Vec2.SqrMagnitude(vec12);
		if (fix2 < fix)
		{
			vec11 = vec12;
			fix = fix2;
		}
		vec12 = vec2Pair.a - vec2Pair2.b;
		fix2 = Vec2.SqrMagnitude(vec12);
		if (fix2 < fix)
		{
			vec11 = vec12;
			fix = fix2;
		}
		vec12 = vec2Pair.b - vec2Pair2.b;
		fix2 = Vec2.SqrMagnitude(vec12);
		if (fix2 < fix)
		{
			vec11 = vec12;
			fix = fix2;
		}
		vec12 = vec2Pair.b - vec2Pair2.a;
		fix2 = Vec2.SqrMagnitude(vec12);
		if (fix2 < fix)
		{
			vec11 = vec12;
			fix = fix2;
		}
		Vec2 vec13 = vec11 / Fix.Sqrt(fix);
		Vec2 minMax9 = MinMaxProjection(vec, vec2, vec3, bl, vec13);
		Vec2 minMax10 = MinMaxProjection(vec4, vec5, vec6, bl2, vec13);
		minMax9.x -= r1.radius;
		minMax9.y += r1.radius;
		minMax10.x -= r2.radius;
		minMax10.y += r2.radius;
		if (SATRR(minMax9, minMax10, vec13, ref minPen, ref minDir))
		{
			return false;
		}
		collisionManifold.penetration = minPen;
		collisionManifold.normal = minDir;
		vec2Pair.a += minDir * r1.radius;
		vec2Pair.b += minDir * r1.radius;
		vec2Pair2.a -= minDir * r2.radius;
		vec2Pair2.b -= minDir * r2.radius;
		if (Fix.Abs(Vec2.Dot(bestFaceNormal, minDir)) > Fix.Abs(Vec2.Dot(bestFaceNormal2, minDir)))
		{
			collisionManifold.contactPoint = ClipIncidentFace(vec2Pair, vec2Pair2, bestFaceNormal, -minDir);
		}
		else
		{
			collisionManifold.contactPoint = ClipIncidentFace(vec2Pair2, vec2Pair, bestFaceNormal2, minDir);
		}
		return true;
	}

	public static bool CollisionTest(RoundedRect r1, RoundedRect r2)
	{
