		Vec2 bl2 = r2.box.center - r2.box.right - r2.box.up;
		Vec2 vec7 = r1.box.right * r1.box.inverseExtents.x;
		Fix minPen = Fix.MaxValue;
		Vec2 minDir = vec7;
		Vec2 minMax = MinMaxProjection(vec, vec3, vec7);
