		minMax.x -= r1.radius;
		minMax.y += r1.radius;
		minMax2.x -= r2.radius;
		minMax2.y += r2.radius;
		if (SATRR(minMax, minMax2, vec7, ref minPen, ref minDir))
		{
			return false;
		}
		Vec2 vec8 = r1.box.up * r1.box.inverseExtents.y;
		Vec2 minMax3 = MinMaxProjection(vec, vec2, vec8);
		Vec2 minMax4 = MinMaxProjection(vec4, vec5, vec6, bl2, vec8);
		minMax3.x -= r1.radius;
		minMax3.y += r1.radius;
		minMax4.x -= r2.radius;
		minMax4.y += r2.radius;
		if (SATRR(minMax3, minMax4, vec8, ref minPen, ref minDir))
		{
			return false;
		}
		Vec2 vec9 = r2.box.right * r2.box.inverseExtents.x;
		Vec2 minMax5 = MinMaxProjection(vec, vec2, vec3, bl, vec9);
		Vec2 minMax6 = MinMaxProjection(vec4, vec6, vec9);
		minMax5.x -= r1.radius;
		minMax5.y += r1.radius;
		minMax6.x -= r2.radius;
		minMax6.y += r2.radius;
		if (SATRR(minMax5, minMax6, vec9, ref minPen, ref minDir))
		{
			return false;
		}
		Vec2 vec10 = r2.box.up * r2.box.inverseExtents.y;
		Vec2 minMax7 = MinMaxProjection(vec, vec2, vec3, bl, vec10);
		Vec2 minMax8 = MinMaxProjection(vec4, vec5, vec10);
		minMax7.x -= r1.radius;
		minMax7.y += r1.radius;
		minMax8.x -= r2.radius;
