		Vec2Pair vec2Pair = CollisionFace(vec, vec2, vec3, bl, minDir, r1.box.inverseExtents, out bestFaceNormal);
		Vec2 bestFaceNormal2;
		Vec2Pair vec2Pair2 = CollisionFace(vec4, vec5, vec6, bl2, -minDir, r2.box.inverseExtents, out bestFaceNormal2);
		Vec2 vec12 = vec2Pair.a - vec2Pair2.a;
		Fix fix2 = Vec2.SqrMagnitude(vec12);
		if (fix2 < fix)
		{
			vec11 = vec12;
			fix = fix2;
		}
		vec12 = vec2Pair.a - vec2Pair2.b;
		fix2 = Vec2.SqrMagnitude(vec12);
		if (fix2 < fix)
		{
			vec11 = vec12;
			fix = fix2;
		}
		vec12 = vec2Pair.b - vec2Pair2.b;
		fix2 = Vec2.SqrMagnitude(vec12);
		if (fix2 < fix)
		{
			vec11 = vec12;
			fix = fix2;
		}
		vec12 = vec2Pair.b - vec2Pair2.a;
		fix2 = Vec2.SqrMagnitude(vec12);
		if (fix2 < fix)
		{
			vec11 = vec12;
			fix = fix2;
		}
		Vec2 vec13 = vec11 / Fix.Sqrt(fix);
		Vec2 minMax9 = MinMaxProjection(vec, vec2, vec3, bl, vec13);
		Vec2 minMax10 = MinMaxProjection(vec4, vec5, vec6, bl2, vec13);
		minMax9.x -= r1.radius;
		minMax9.y += r1.radius;
		minMax10.x -= r2.radius;
		minMax10.y += r2.radius;
		if (SATRR(minMax9, minMax10, vec13, ref minPen, ref minDir))
		{
			return false;
		}
		return true;
	}

	private static bool SATRR(Vec2 minMax1, Vec2 minMax2, Vec2 newDir, ref Fix minPen, ref Vec2 minDir)
	{
		Fix fix = minMax1.y - minMax2.x;
		Fix fix2 = minMax2.y - minMax1.x;
		if (fix < Fix.Zero || fix2 < Fix.Zero)
		{
			return true;
		}
		if (fix < minPen && fix < fix2)
		{
			minPen = fix;
			minDir = newDir;
		}
		if (fix2 < minPen)
		{
			minPen = fix2;
			minDir = -newDir;
		}
		return false;
	}

	public static AABB ComputeBoundingBox(Circle c, int id)
	{
		AABB result = new AABB
		{
			id = id,
			shape = Shape.Circle,
			layer = c.layer
		};
		result.min = c.center;
		result.max = c.center;
		result.min.x -= c.radius;
		result.min.y -= c.radius;
		result.max.x += c.radius;
		result.max.y += c.radius;
		return result;
	}

	public static AABB ComputeBoundingBox(Box b, int id)
	{
		AABB result = new AABB
		{
			id = id,
			shape = Shape.Box,
			layer = b.layer
		};
		Fix fix = Fix.Abs(b.up.x);
		Fix fix2 = Fix.Abs(b.right.x);
		Fix fix3 = Fix.Abs(b.up.y);
		Fix fix4 = Fix.Abs(b.right.y);
		Vec2 vec = new Vec2(fix2 + fix, fix4 + fix3);
		result.min = b.center - vec;
		result.max = b.center + vec;
		return result;
	}

	public static AABB ComputeBoundingBox(RoundedRect b, int id)
	{
		AABB result = new AABB
		{
			id = id,
			shape = Shape.RoundedRect,
			layer = b.layer
		};
		Fix fix = Fix.Abs(b.box.up.x);
		Fix fix2 = Fix.Abs(b.box.right.x);
		Fix fix3 = Fix.Abs(b.box.up.y);
		Fix fix4 = Fix.Abs(b.box.right.y);
		Vec2 vec = new Vec2(fix2 + fix + b.radius, fix4 + fix3 + b.radius);
		result.min = b.box.center - vec;
		result.max = b.box.center + vec;
		return result;
	}

	public static AABB ComputeBoundingBox(RopeBody ropeBody, int layer)
	{
		AABB result = new AABB
		{
			id = ropeBody.indexInArray,
			shape = Shape.Rope,
			layer = layer
		};
		Fix fix = ropeBody.segment[1].x;
		Fix fix2 = ropeBody.segment[1].x;
		Fix fix3 = ropeBody.segment[1].y;
		Fix fix4 = ropeBody.segment[1].y;
		for (int i = 2; i < ropeBody.segmentCount - 1; i++)
		{
			Vec2 vec = ropeBody.segment[i];
			fix = ((vec.x > fix) ? vec.x : fix);
			fix3 = ((vec.y > fix3) ? vec.y : fix3);
			fix2 = ((vec.x < fix2) ? vec.x : fix2);
			fix4 = ((vec.y < fix4) ? vec.y : fix4);
		}
		result.max = new Vec2(fix, fix3);
		result.min = new Vec2(fix2, fix4);
		return result;
	}

	public static bool CollisionTest(Box b1, Box b2)
	{
		Vec2 vec = b1.center + b1.right + b1.up;
		Vec2 vec2 = b1.center + b1.right - b1.up;
		Vec2 vec3 = b1.center - b1.right + b1.up;
		Vec2 bl = b1.center - b1.right - b1.up;
		Vec2 vec4 = b2.center + b2.right + b2.up;
		Vec2 vec5 = b2.center + b2.right - b2.up;
		Vec2 vec6 = b2.center - b2.right + b2.up;
		Vec2 bl2 = b2.center - b2.right - b2.up;
		Vec2 right = b1.right;
		Vec2 vec7 = MinMaxProjection(vec, vec3, right);
		Vec2 vec8 = MinMaxProjection(vec4, vec5, vec6, bl2, right);
		if (vec8.x > vec7.y || vec7.x > vec8.y)
		{
			return false;
		}
		Vec2 up = b1.up;
		Vec2 vec9 = MinMaxProjection(vec, vec2, up);
		Vec2 vec10 = MinMaxProjection(vec4, vec5, vec6, bl2, up);
		if (vec10.x > vec9.y || vec9.x > vec10.y)
		{
			return false;
		}
		Vec2 right2 = b2.right;
		Vec2 vec11 = MinMaxProjection(vec, vec2, vec3, bl, right2);
		Vec2 vec12 = MinMaxProjection(vec4, vec6, right2);
		if (vec12.x > vec11.y || vec11.x > vec12.y)
		{
			return false;
		}
		Vec2 up2 = b2.up;
		Vec2 vec13 = MinMaxProjection(vec, vec2, vec3, bl, up2);
		Vec2 vec14 = MinMaxProjection(vec4, vec5, up2);
		if (vec14.x > vec13.y || vec13.x > vec14.y)
		{
			return false;
		}
		return true;
	}

	public static bool CollisionTest(Box b1, Box b2, ref CollisionManifold collisionInfo)
	{
