		Vec2 vec2 = b1.center + b1.right - b1.up;
		Vec2 vec3 = b1.center - b1.right + b1.up;
		Vec2 bl = b1.center - b1.right - b1.up;
		Vec2 vec4 = b2.center + b2.right + b2.up;
		Vec2 vec5 = b2.center + b2.right - b2.up;
		Vec2 vec6 = b2.center - b2.right + b2.up;
		Vec2 bl2 = b2.center - b2.right - b2.up;
		Vec2 right = b1.right;
		Fix minPen = Fix.MaxValue;
		Vec2 minDir = right;
		Vec2 minMax = MinMaxProjection(vec, vec3, right);
		Vec2 minMax2 = MinMaxProjection(vec4, vec5, vec6, bl2, right);
		if (SATobb(minMax, minMax2, right, ref minPen, ref minDir, b1.inverseExtents.x))
		{
			return false;
		}
		Vec2 up = b1.up;
		Vec2 minMax3 = MinMaxProjection(vec, vec2, up);
		Vec2 minMax4 = MinMaxProjection(vec4, vec5, vec6, bl2, up);
		if (SATobb(minMax3, minMax4, up, ref minPen, ref minDir, b1.inverseExtents.y))
		{
			return false;
		}
		Vec2 right2 = b2.right;
		Vec2 minMax5 = MinMaxProjection(vec, vec2, vec3, bl, right2);
		Vec2 minMax6 = MinMaxProjection(vec4, vec6, right2);
		if (SATobb(minMax5, minMax6, right2, ref minPen, ref minDir, b2.inverseExtents.x))
		{
			return false;
		}
		Vec2 up2 = b2.up;
		Vec2 minMax7 = MinMaxProjection(vec, vec2, vec3, bl, up2);
		Vec2 minMax8 = MinMaxProjection(vec4, vec5, up2);
		if (SATobb(minMax7, minMax8, up2, ref minPen, ref minDir, b2.inverseExtents.y))
		{
			return false;
		}
		collisionInfo.normal = minDir;
		collisionInfo.penetration = Fix.Abs(minPen);
		Vec2 bestFaceNormal;
		Vec2Pair vec2Pair = CollisionFace(vec, vec2, vec3, bl, minDir, b1.inverseExtents, out bestFaceNormal);
		Vec2 bestFaceNormal2;
		Vec2Pair vec2Pair2 = CollisionFace(vec4, vec5, vec6, bl2, -minDir, b2.inverseExtents, out bestFaceNormal2);
		if (Fix.Abs(Vec2.Dot(bestFaceNormal, minDir)) > Fix.Abs(Vec2.Dot(bestFaceNormal2, minDir)))
		{
			collisionInfo.contactPoint = ClipIncidentFace(vec2Pair, vec2Pair2, bestFaceNormal, -minDir);
		}
		else
		{
			collisionInfo.contactPoint = ClipIncidentFace(vec2Pair2, vec2Pair, bestFaceNormal2, minDir);
		}
		return true;
	}

	private static Vec2 ClipIncidentFace(Vec2Pair referenceFace, Vec2Pair incidentFace, Vec2 referenceNormal, Vec2 penetrationNormal)
	{
		Vec2 vec = Vec2.MulByNegI(referenceNormal);
		Fix fix = Vec2.Dot(vec, incidentFace.a);
		Fix fix2 = Vec2.Dot(vec, incidentFace.b);
		Fix fix3 = Vec2.Dot(vec, referenceFace.a);
		Fix fix4 = Vec2.Dot(vec, referenceFace.b);
		if (fix < fix3)
		{
			Fix fix5 = fix3 - fix;
			incidentFace.a += fix5 * vec;
		}
		else if (fix > fix4)
		{
			Fix fix6 = fix - fix4;
			incidentFace.a -= fix6 * vec;
		}
		if (fix2 < fix3)
		{
			Fix fix7 = fix3 - fix2;
			incidentFace.b += fix7 * vec;
		}
		else if (fix2 > fix4)
		{
			Fix fix8 = fix2 - fix4;
			incidentFace.b -= fix8 * vec;
		}
		Fix fix9 = Vec2.Dot(penetrationNormal, incidentFace.a);
		Fix fix10 = Vec2.Dot(penetrationNormal, incidentFace.b);
		if (!(fix9 > fix10))
		{
			return incidentFace.b;
		}
		return incidentFace.a;
	}

	private static Vec2Pair CollisionFace(Vec2 tr, Vec2 br, Vec2 tl, Vec2 bl, Vec2 p, Vec2 inverseExtents, out Vec2 bestFaceNormal)
	{
		inverseExtents *= (Fix)0.5f;
		Vec4 vec = new Vec4
		{
			x = Vec2.Dot(p, tr),
			y = Vec2.Dot(p, br),
			z = Vec2.Dot(p, tl),
			w = Vec2.Dot(p, bl)
		};
		if (vec.x >= vec.y && vec.x >= vec.z && vec.x >= vec.w)
		{
			Vec2 vec2 = Vec2.MulByI(br - tr) * inverseExtents.y;
			Vec2 vec3 = Vec2.MulByI(tr - tl) * inverseExtents.x;
			if (Fix.Abs(Vec2.Dot(vec2, p)) > Fix.Abs(Vec2.Dot(vec3, p)))
			{
				bestFaceNormal = vec2;
				return new Vec2Pair(tr, br);
			}
			bestFaceNormal = vec3;
			return new Vec2Pair(tl, tr);
		}
		if (vec.y >= vec.x && vec.y >= vec.z && vec.y >= vec.w)
		{
			Vec2 vec4 = Vec2.MulByI(br - tr) * inverseExtents.y;
			Vec2 vec5 = Vec2.MulByI(bl - br) * inverseExtents.x;
			if (Fix.Abs(Vec2.Dot(vec4, p)) > Fix.Abs(Vec2.Dot(vec5, p)))
			{
				bestFaceNormal = vec4;
				return new Vec2Pair(tr, br);
			}
			bestFaceNormal = vec5;
			return new Vec2Pair(br, bl);
		}
		if (vec.z >= vec.x && vec.z >= vec.y && vec.z >= vec.w)
		{
			Vec2 vec6 = Vec2.MulByI(tl - bl) * inverseExtents.y;
			Vec2 vec7 = Vec2.MulByI(tr - tl) * inverseExtents.x;
			if (Fix.Abs(Vec2.Dot(vec6, p)) > Fix.Abs(Vec2.Dot(vec7, p)))
			{
				bestFaceNormal = vec6;
				return new Vec2Pair(bl, tl);
			}
			bestFaceNormal = vec7;
			return new Vec2Pair(tl, tr);
		}
		Vec2 vec8 = Vec2.MulByI(tl - bl) * inverseExtents.y;
		Vec2 vec9 = Vec2.MulByI(bl - br) * inverseExtents.x;
		if (Fix.Abs(Vec2.Dot(vec8, p)) > Fix.Abs(Vec2.Dot(vec9, p)))
		{
			bestFaceNormal = vec8;
			return new Vec2Pair(bl, tl);
		}
		bestFaceNormal = vec9;
		return new Vec2Pair(br, bl);
	}

	private static bool SATobb(Vec2 minMax1, Vec2 minMax2, Vec2 newDir, ref Fix minPen, ref Vec2 minDir, Fix invDirMag)
	{
		Fix fix = minMax1.y - minMax2.x;
		Fix fix2 = minMax2.y - minMax1.x;
		if (fix < Fix.Zero || fix2 < Fix.Zero)
		{
			return true;
		}
		fix *= invDirMag;
		fix2 *= invDirMag;
		if (fix < minPen)
		{
			minPen = fix;
			minDir = newDir * invDirMag;
		}
		if (fix2 < minPen)
		{
			minPen = fix2;
			minDir = -newDir * invDirMag;
		}
		return false;
	}

	public static bool CollisionTest(Circle c, RoundedRect rb, ref CollisionManifold collisionManifold)
	{
		Box box = rb.box;
		c.radius += rb.radius;
		Vec2 vec = box.center + box.right + box.up;
		Vec2 vec2 = box.center + box.right - box.up;
		Vec2 vec3 = box.center - box.right + box.up;
		_ = box.center - box.right - box.up;
		Vec2 vec4 = ClosestPointOnLine(vec2, vec, c.center, (Fix)0.5 * box.inverseExtents.y);
		Vec2 vec5 = ClosestPointOnLine(vec3, vec, c.center, (Fix)0.5 * box.inverseExtents.x);
		Vec2 vec6 = vec4 - box.right - box.right;
		Vec2 vec7 = vec5 - box.up - box.up;
		Vec2 vec8 = vec4 - c.center;
		Vec2 vec9 = vec6 - c.center;
		Vec2 vec10 = vec5 - c.center;
		Vec2 vec11 = vec7 - c.center;
		Fix fix = Vec2.SqrMagnitude(vec8);
		Fix fix2 = Vec2.SqrMagnitude(vec9);
		Fix fix3 = Vec2.SqrMagnitude(vec10);
		Fix fix4 = Vec2.SqrMagnitude(vec11);
		Vec2 vec12 = vec8;
		Fix fix5 = fix;
		if (fix2 < fix5)
		{
			fix5 = fix2;
			vec12 = vec9;
		}
		if (fix3 < fix5)
		{
			fix5 = fix3;
			vec12 = vec10;
		}
		if (fix4 < fix5)
		{
			fix5 = fix4;
			vec12 = vec11;
		}
		Fix fix6 = c.radius * c.radius;
		if (vec4 != vec && vec4 != vec2 && vec5 != vec3 && vec5 != vec)
		{
			if (fix5 == Fix.Zero)
			{
				collisionManifold.penetration = c.radius;
				collisionManifold.normal = -Vec2.Normalized(rb.box.center - c.center);
				collisionManifold.contactPoint = c.center + collisionManifold.normal * (c.radius - rb.radius);
				return true;
			}
			fix5 = Fix.Sqrt(fix5);
			collisionManifold.penetration = fix5 + c.radius;
			collisionManifold.normal = -vec12 / fix5;
			collisionManifold.contactPoint = c.center + collisionManifold.normal * (c.radius - rb.radius);
			return true;
		}
		if (fix5 > fix6)
		{
			return false;
		}
		if (fix5 == Fix.Zero)
		{
			collisionManifold.penetration = c.radius;
			collisionManifold.normal = Vec2.Normalized(rb.box.center - c.center);
			collisionManifold.contactPoint = c.center + collisionManifold.normal * (c.radius - rb.radius);
			return true;
		}
		fix5 = Fix.Sqrt(fix5);
		collisionManifold.penetration = c.radius - fix5;
		collisionManifold.normal = vec12 / fix5;
		collisionManifold.contactPoint = c.center + collisionManifold.normal * (c.radius - rb.radius);
		return true;
	}

	public static bool CollisionTest(Circle c, RoundedRect rb)
	{
		Box box = rb.box;
		c.radius += rb.radius;
		return CollisionTest(c, box);
	}

	public static bool CollisionTest(Circle c, Box b, ref CollisionManifold collisionManifold)
	{
		Vec2 vec = b.center + b.right + b.up;
		Vec2 vec2 = b.center + b.right - b.up;
		Vec2 vec3 = b.center - b.right + b.up;
		_ = b.center - b.right - b.up;
		Vec2 vec4 = ClosestPointOnLine(vec2, vec, c.center, (Fix)0.5 * b.inverseExtents.y);
		Vec2 vec5 = ClosestPointOnLine(vec3, vec, c.center, (Fix)0.5 * b.inverseExtents.x);
		Vec2 vec6 = vec4 - b.right - b.right;
		Vec2 vec7 = vec5 - b.up - b.up;
		Vec2 v = vec4 - c.center;
		Vec2 v2 = vec6 - c.center;
		Vec2 v3 = vec5 - c.center;
		Vec2 v4 = vec7 - c.center;
		Fix fix = Vec2.SqrMagnitude(v);
		Fix fix2 = Vec2.SqrMagnitude(v2);
		Fix fix3 = Vec2.SqrMagnitude(v3);
		Fix fix4 = Vec2.SqrMagnitude(v4);
		Vec2 vec8 = b.right * b.inverseExtents.x;
		Fix fix5 = fix;
		if (fix2 < fix5)
		{
			fix5 = fix2;
			vec8 = -vec8;
		}
		if (fix3 < fix5)
		{
			fix5 = fix3;
			vec8 = b.up * b.inverseExtents.y;
		}
		if (fix4 < fix5)
		{
			fix5 = fix4;
			vec8 = -b.up * b.inverseExtents.y;
		}
		Fix fix6 = c.radius * c.radius;
		if (vec4 != vec && vec4 != vec2 && vec5 != vec3 && vec5 != vec)
		{
			fix5 = Fix.Sqrt(fix5);
			collisionManifold.penetration = fix5 + c.radius;
			collisionManifold.normal = -vec8;
			collisionManifold.contactPoint = c.center + collisionManifold.normal * c.radius;
			return true;
		}
		if (fix5 > fix6)
		{
			return false;
		}
		fix5 = Fix.Sqrt(fix5);
		collisionManifold.penetration = c.radius - fix5;
		collisionManifold.normal = -vec8;
		collisionManifold.contactPoint = c.center + collisionManifold.normal * c.radius;
		return true;
	}

	public static bool CollisionTest(Circle c, Box b)
	{
		Vec2 vec = b.center + b.right + b.up;
		Vec2 vec2 = b.center + b.right - b.up;
		Vec2 vec3 = b.center - b.right + b.up;
		_ = b.center - b.right - b.up;
		Vec2 vec4 = ClosestPointOnLine(vec2, vec, c.center, (Fix)0.5 * b.inverseExtents.y);
		Vec2 vec5 = vec4 - b.right - b.right;
		Vec2 vec6 = ClosestPointOnLine(vec3, vec, c.center, (Fix)0.5 * b.inverseExtents.x);
		Vec2 vec7 = vec6 - b.up - b.up;
		Vec4 vec8 = new Vec4
		{
			x = Vec2.SqrMagnitude(vec4 - c.center),
			y = Vec2.SqrMagnitude(vec5 - c.center),
			z = Vec2.SqrMagnitude(vec6 - c.center),
			w = Vec2.SqrMagnitude(vec7 - c.center)
		};
		Fix x = vec8.x;
		x = ((vec8.y < x) ? vec8.y : x);
		x = ((vec8.z < x) ? vec8.z : x);
		x = ((vec8.w < x) ? vec8.w : x);
		if (!(x < c.radius * c.radius))
		{
			if (vec4 != vec && vec4 != vec2 && vec6 != vec3)
			{
				return vec6 != vec;
			}
			return false;
		}
		return true;
	}

	public static Vec2 ClosestPointOnLine(Vec2 a, Vec2 b, Vec2 x, Fix inverseLength)
	{
		Vec2 vec = b - a;
		Fix fix = Vec2.Dot(a, vec);
		Fix fix2 = Vec2.Dot(b, vec);
		Fix fix3 = Vec2.Dot(x, vec);
		if (fix3 > fix2)
		{
			return b;
		}
		if (fix3 < fix)
		{
			return a;
		}
		vec *= inverseLength;
		return a + vec * (fix3 - fix) * inverseLength;
	}

	public static Vec2 ClosestPointOnLineToOrigin(Vec2 a, Vec2 b, Fix inverseSqrdDist)
	{
		Vec2 vec = b - a;
		Fix fix = Vec2.Dot(a, vec);
		Fix fix2 = Vec2.Dot(b, vec);
		if (Fix.Zero > fix2)
		{
			return b;
		}
		if (Fix.Zero < fix)
		{
			return a;
		}
		return a + vec * -fix * inverseSqrdDist;
	}

	private static Vec2 MinMaxProjection(Vec2 v, Vec2 u, Vec2 p)
	{
		Fix fix = Vec2.Dot(p, v);
		Fix fix2 = Vec2.Dot(p, u);
		if (!(fix2 < fix))
		{
			return new Vec2(fix, fix2);
		}
		return new Vec2(fix2, fix);
	}

	public static Vec2 MinMaxProjection(Vec2 tr, Vec2 br, Vec2 tl, Vec2 bl, Vec2 p)
	{
		Vec4 vec = new Vec4
		{
			x = Vec2.Dot(p, tr),
			y = Vec2.Dot(p, br),
			z = Vec2.Dot(p, tl),
			w = Vec2.Dot(p, bl)
		};
		if (vec.x > vec.y)
		{
			Fix x = vec.x;
			vec.x = vec.y;
			vec.y = x;
		}
		if (vec.z > vec.w)
		{
			Fix z = vec.z;
			vec.z = vec.w;
			vec.w = z;
		}
		if (vec.x > vec.z)
		{
			Fix x2 = vec.x;
			vec.x = vec.z;
			vec.z = x2;
		}
		if (vec.y > vec.w)
		{
			Fix y = vec.y;
			vec.y = vec.w;
			vec.w = y;
		}
		return new Vec2(vec.x, vec.w);
	}

	public static bool CollisionTest(Circle c, AABB r)
	{
		Vec2 vec = (r.max - r.min) * (Fix)0.5;
		Vec2 vec3;
		Vec2 vec2 = (vec3 = r.min + vec - c.center);
		vec3.x = ((vec3.x > vec.x) ? vec.x : vec3.x);
		vec3.x = ((vec3.x < -vec.x) ? (-vec.x) : vec3.x);
		vec3.y = ((vec3.y > vec.y) ? vec.y : vec3.y);
		vec3.y = ((vec3.y < -vec.y) ? (-vec.y) : vec3.y);
		Fix fix = Vec2.SqrMagnitude(vec2 - vec3);
		if (!(vec2 == vec3))
		{
			return fix < c.radius * c.radius;
		}
		return true;
	}

	public static bool CollisionTest(Circle c, AABB r, ref CollisionManifold collisionInfo)
	{
		Vec2 vec = (r.max - r.min) * (Fix)0.5;
		Vec2 vec2 = r.min + vec;
		Vec2 vec3 = c.center - vec2;
		Vec2 vec4 = vec3;
		vec4.x = ((vec4.x > vec.x) ? vec.x : vec4.x);
		vec4.x = ((vec4.x < -vec.x) ? (-vec.x) : vec4.x);
		vec4.y = ((vec4.y > vec.y) ? vec.y : vec4.y);
		vec4.y = ((vec4.y < -vec.y) ? (-vec.y) : vec4.y);
		if (vec4 == vec3)
		{
			Fix fix = vec.y - Fix.Abs(vec3.y);
			Fix fix2 = vec.x - Fix.Abs(vec3.x);
			if (fix2 < fix)
			{
				collisionInfo.normal = ((vec3.x > Fix.Zero) ? Vec2.right : Vec2.left);
				collisionInfo.penetration = fix2 + c.radius;
			}
			else
			{
				collisionInfo.normal = ((vec3.y > Fix.Zero) ? Vec2.up : Vec2.down);
				collisionInfo.penetration = fix + c.radius;
			}
			return true;
		}
		Vec2 vec5 = vec4 - vec3;
		Fix radius = c.radius;
		Fix fix3 = Vec2.SqrMagnitude(vec5);
		if (fix3 > radius * radius)
		{
			return false;
		}
		Fix fix4 = Fix.Sqrt(fix3);
		vec5 /= fix4;
		collisionInfo.normal = vec5;
		collisionInfo.penetration = radius - fix4;
		return true;
	}

	public static void ApplyImpulseToBody(Vec2 Impulse, Vec2 contactVector, ref PhysicsBody body)
	{
		if (body.IsComposite())
		{
			body.compositeParent.combinedBody.velocity += body.compositeParent.combinedBody.inverseMass * Impulse;
			body.compositeParent.combinedBody.angularVelocity += body.compositeParent.combinedBody.inverseMomentOfInertia * Vec2.Cross(contactVector, Impulse);
		}
		else
		{
			body.velocity += body.inverseMass * Impulse;
			body.angularVelocity += body.inverseMomentOfInertia * Vec2.Cross(contactVector, Impulse);
		}
	}

	public static void ResolveCollision(CollisionManifold collisionInfo, ref PhysicsBody bodyA, ref PhysicsBody bodyB, Vec2 posA, Vec2 posB)
	{
		PhysicsBody physicsBody = bodyA;
		if (bodyA.IsComposite())
		{
			physicsBody = bodyA.compositeParent.combinedBody;
			posA = bodyA.compositeParent.position;
		}
		PhysicsBody physicsBody2 = bodyB;
		if (bodyB.IsComposite())
		{
			physicsBody2 = bodyB.compositeParent.combinedBody;
			posB = bodyB.compositeParent.position;
		}
		UnityEngine.Debug.DrawRay((Vector3)posA, -(Vector3)(collisionInfo.normal * collisionInfo.penetration), UnityEngine.Color.yellow);
		UnityEngine.Debug.DrawRay((Vector3)posB, (Vector3)(collisionInfo.normal * collisionInfo.penetration), UnityEngine.Color.red);
		Vec2 vec = Vec2.NormalizedSafe(collisionInfo.contactPoint - posA);
		Vec2 vec2 = Vec2.NormalizedSafe(collisionInfo.contactPoint - posB);
		Vec2 v = physicsBody2.velocity + Vec2.CrossProduct2(physicsBody2.angularVelocity, vec2) - physicsBody.velocity - Vec2.CrossProduct2(physicsBody.angularVelocity, vec);
		Fix fix = Vec2.Dot(v, collisionInfo.normal);
		if (!(fix > Fix.Zero))
		{
			Fix fix2 = Fix.One + ((physicsBody.bounciness > physicsBody2.bounciness) ? physicsBody.bounciness : physicsBody2.bounciness);
			Fix fix3 = Vec2.Cross(vec, collisionInfo.normal);
			fix3 = fix3 * fix3 * physicsBody.inverseMomentOfInertia;
			Fix fix4 = Vec2.Cross(vec2, collisionInfo.normal);
			fix4 = fix4 * fix4 * physicsBody2.inverseMomentOfInertia;
			Fix fix5 = Fix.One / (physicsBody.inverseMass + physicsBody2.inverseMass + fix3 + fix4);
			Fix fix6 = -fix2 * fix * fix5;
			Vec2 vec3 = fix6 * collisionInfo.normal;
			UnityEngine.Debug.DrawRay((Vector3)posA, -(Vector3)vec3 * 2f, UnityEngine.Color.cyan);
			UnityEngine.Debug.DrawRay((Vector3)posB, (Vector3)vec3 * 2f, UnityEngine.Color.cyan);
			ApplyImpulseToBody(-vec3, vec, ref bodyA);
			ApplyImpulseToBody(vec3, vec2, ref bodyB);
			v = physicsBody2.velocity + Vec2.CrossProduct2(physicsBody2.angularVelocity, vec2) - physicsBody.velocity - Vec2.CrossProduct2(physicsBody.angularVelocity, vec);
			Vec2 vec4 = new Vec2(-collisionInfo.normal.y, collisionInfo.normal.x);
			vec4 = (Fix)Fix.Sign(Vec2.Dot(vec4, v)) * vec4;
			fix = -Vec2.Dot(vec4, v);
			Fix fix7 = fix * fix5;
			Fix fix8 = Fix.Max(physicsBody.staticFriction, physicsBody2.staticFriction);
			Vec2 vec5;
			if (Fix.Abs(fix7) < fix6 * fix8)
			{
				vec5 = fix7 * vec4;
			}
			else
			{
				fix8 = Fix.Max(physicsBody.dynamicFriction, physicsBody2.dynamicFriction);
				vec5 = -fix6 * vec4 * fix8;
			}
			UnityEngine.Debug.DrawRay((Vector3)posA, -(Vector3)vec5 * 2f, UnityEngine.Color.blue);
			UnityEngine.Debug.DrawRay((Vector3)posB, (Vector3)vec5 * 2f, UnityEngine.Color.blue);
			ApplyImpulseToBody(-vec5, vec, ref bodyA);
			ApplyImpulseToBody(vec5, vec2, ref bodyB);
		}
	}

	public static Vec2Pair PositionalCorrection(CollisionManifold collisionInfo, Fix invMassA, Fix invMassB)
	{
		Fix fix = collisionInfo.penetration - slop;
		fix = ((fix < Fix.Zero) ? Fix.Zero : fix);
		Vec2 vec = fix / (invMassA + invMassB) * posCorrectionStr * collisionInfo.normal;
		Vec2 a = -invMassA * vec;
		Vec2 b = invMassB * vec;
		return new Vec2Pair(a, b);
	}

	public static Vec2Pair FullPositionalCorrection(CollisionManifold collisionInfo, Fix invMassA, Fix invMassB)
	{
		Fix fix = collisionInfo.penetration - slop;
		fix = ((fix < Fix.Zero) ? Fix.Zero : fix);
		Vec2 vec = fix / (invMassA + invMassB) * Fix.One * collisionInfo.normal;
		Vec2 a = -invMassA * vec;
		Vec2 b = invMassB * vec;
		return new Vec2Pair(a, b);
	}

	public static bool OverlapPoint(Circle c, Vec2 point)
	{
		return Vec2.SqrMagnitude(c.center - point) < c.radius * c.radius;
	}

	public static bool OverlapPoint(Box b, Vec2 point)
	{
		Vec2 center = b.center;
		Vec2 u = b.up * b.inverseExtents.y;
		Fix value = Vec2.Dot(u: b.right * b.inverseExtents.x, v: center - point) * b.inverseExtents.x;
		Fix value2 = Vec2.Dot(center - point, u) * b.inverseExtents.y;
		if (Fix.Abs(value) <= 1L)
		{
			return Fix.Abs(value2) <= 1L;
		}
		return false;
	}

	public static bool OverlapPoint(RoundedRect rr, Vec2 point)
	{
		Vec2 center = rr.box.center;
		Vec2 u = rr.box.up * rr.box.inverseExtents.y;
		Vec2 u2 = rr.box.right * rr.box.inverseExtents.x;
		Fix fix = Fix.One + rr.radius * rr.box.inverseExtents.y;
		Fix fix2 = Fix.One + rr.radius * rr.box.inverseExtents.x;
		Fix fix3 = Fix.Abs(Vec2.Dot(center - point, u2) * rr.box.inverseExtents.x);
		Fix fix4 = Fix.Abs(Vec2.Dot(center - point, u) * rr.box.inverseExtents.y);
		bool flag = fix3 <= fix2 && fix4 <= 1L;
		bool flag2 = fix3 <= 1L && fix4 <= fix;
		if (!(fix3 <= fix2) || !(fix4 <= fix))
		{
			return false;
		}
		if (flag2 || flag)
		{
			return true;
		}
		Vec2 vec = center + rr.box.right + rr.box.up;
		Vec2 vec2 = center + rr.box.right - rr.box.up;
		Vec2 vec3 = center - rr.box.right + rr.box.up;
		Vec2 vec4 = center - rr.box.right - rr.box.up;
		Fix fix5 = rr.radius * rr.radius;
		if (!(Vec2.SqrMagnitude(vec - point) < fix5) && !(Vec2.SqrMagnitude(vec2 - point) < fix5) && !(Vec2.SqrMagnitude(vec3 - point) < fix5))
		{
			return Vec2.SqrMagnitude(vec4 - point) < fix5;
		}
		return true;
	}

	public static Vec2 NormalAtPoint(Vec2 pos, Circle c)
	{
		return Vec2.NormalizedSafe(pos - c.center);
	}

	public static Vec2 NormalAtPoint(this IPhysicsCollider icollider, Vec2 pos)
	{
		return icollider.shape switch
		{
			Shape.Circle => NormalAtPoint(pos, DetPhysics.Get().circles.colliders[DetPhysics.Get().circles.ColliderIndex(icollider.GetPhysicsParent().instanceId)]), 
			Shape.Box => NormalAtPoint(pos, DetPhysics.Get().boxes.colliders[DetPhysics.Get().boxes.ColliderIndex(icollider.GetPhysicsParent().instanceId)]), 
			Shape.RoundedRect => NormalAtPoint(pos, DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(icollider.GetPhysicsParent().instanceId)]), 
			_ => Vec2.up, 
		};
	}

	public static Vec2 NormalAtPoint(Vec2 pos, Box b)
	{
		Vec2 center = b.center;
		Vec2 vec = b.up * b.inverseExtents.y;
		Vec2 vec2 = b.right * b.inverseExtents.x;
		Fix fix = -Vec2.Dot(center - pos, vec2) * b.inverseExtents.x;
		Fix fix2 = -Vec2.Dot(center - pos, vec) * b.inverseExtents.y;
		Fix fix3 = Fix.Max(Fix.Abs(fix), (Fix)0.001f);
		Fix fix4 = Fix.Max(Fix.Abs(fix2), (Fix)0.001f);
		bool flag = fix / fix4 >= 1L;
		bool flag2 = fix / fix4 <= -1L;
		bool flag3 = fix2 / fix3 <= -1L;
		if (fix2 / fix3 >= 1L)
		{
			return vec;
		}
		if (flag)
		{
			return vec2;
		}
		if (flag2)
		{
			return -vec2;
		}
		if (flag3)
		{
			return -vec;
		}
		return Vec2.up;
	}

	public static Vec2 NormalAtPoint(Vec2 pos, RoundedRect rr)
	{
		Vec2 center = rr.box.center;
		Vec2 u = rr.box.up * rr.box.inverseExtents.y;
		Vec2 u2 = rr.box.right * rr.box.inverseExtents.x;
		_ = Fix.One + rr.radius * rr.box.inverseExtents.y;
		_ = Fix.One + rr.radius * rr.box.inverseExtents.x;
		Fix fix = -Vec2.Dot(center - pos, u2) * rr.box.inverseExtents.x;
		Fix fix2 = -Vec2.Dot(center - pos, u) * rr.box.inverseExtents.y;
		Fix fix3 = Fix.Abs(fix);
		bool flag = Fix.Abs(fix2) <= 1L;
		bool flag2 = fix3 <= 1L;
		bool flag3 = fix >= 1L && fix2 >= 1L;
		bool flag4 = fix >= 1L && fix2 <= -1L;
		bool flag5 = fix <= -1L && fix2 >= 1L;
		bool flag6 = fix <= -1L && fix2 <= -1L;
		if (flag)
		{
			return rr.box.right * (Fix)Fix.Sign2(fix);
		}
		if (flag2)
		{
			return rr.box.up * (Fix)Fix.Sign2(fix2);
		}
		if (flag3)
		{
			Vec2 vec = center + rr.box.right + rr.box.up;
			return Vec2.NormalizedSafe(pos - vec);
		}
		if (flag4)
		{
			Vec2 vec2 = center + rr.box.right - rr.box.up;
			return Vec2.NormalizedSafe(pos - vec2);
		}
		if (flag5)
		{
			Vec2 vec3 = center - rr.box.right + rr.box.up;
			return Vec2.NormalizedSafe(pos - vec3);
		}
		if (flag6)
		{
			Vec2 vec4 = center - rr.box.right - rr.box.up;
			return Vec2.NormalizedSafe(pos - vec4);
		}
		return Vec2.up;
	}

	public static Vec2 SupportFun_box(Box b, Vec2 dir)
	{
		Fix fix = Vec2.Dot(b.right, dir);
		Fix fix2 = Vec2.Dot(b.up, dir);
		bool flag = fix < Fix.Zero;
		bool flag2 = fix2 < Fix.Zero;
		if (!flag && !flag2)
		{
			return b.center + b.right + b.up;
		}
		if (flag && !flag2)
		{
			return b.center - b.right + b.up;
		}
		if (flag2 && !flag)
		{
			return b.center + b.right - b.up;
		}
		return b.center - b.right - b.up;
	}

	public static bool IsApproximatelyZero(Fix x)
	{
		if (x < Fix.FromRaw(6L))
		{
			return x > Fix.FromRaw(-6L);
		}
		return false;
	}

	public static Vec2 SupportFun_RoundedRect_slow(RoundedRect rb1, Vec2 dir_normalized)
	{
		Fix fix = Vec2.Dot(rb1.box.right, dir_normalized);
		Fix fix2 = Vec2.Dot(rb1.box.up, dir_normalized);
		bool flag = fix < Fix.Zero;
		bool flag2 = fix2 < Fix.Zero;
		Fix fix3 = Fix.FromRaw(6L);
		Fix fix4 = Fix.FromRaw(-6L);
		bool flag3 = fix < fix3 && fix > fix4;
		bool flag4 = fix2 < fix3 && fix2 > fix4;
		if (flag3 || flag4)
		{
			if (flag3 && flag2)
			{
				UnityEngine.Debug.Log("bl");
				return rb1.box.center - rb1.box.right - rb1.box.up + dir_normalized * rb1.radius;
			}
			if (flag3 && !flag2)
			{
				UnityEngine.Debug.Log("tr");
				return rb1.box.center + rb1.box.right + rb1.box.up + dir_normalized * rb1.radius;
			}
			if (flag4 && flag)
			{
				UnityEngine.Debug.Log("tl");
				return rb1.box.center - rb1.box.right + rb1.box.up + dir_normalized * rb1.radius;
			}
			UnityEngine.Debug.Log("br");
			return rb1.box.center + rb1.box.right - rb1.box.up + dir_normalized * rb1.radius;
		}
		if (!flag && !flag2)
		{
			return rb1.box.center + rb1.box.right + rb1.box.up + dir_normalized * rb1.radius;
		}
		if (flag && !flag2)
		{
			return rb1.box.center - rb1.box.right + rb1.box.up + dir_normalized * rb1.radius;
		}
		if (flag2 && !flag)
		{
			return rb1.box.center + rb1.box.right - rb1.box.up + dir_normalized * rb1.radius;
		}
		return rb1.box.center - rb1.box.right - rb1.box.up + dir_normalized * rb1.radius;
	}

	public static Vec2 SupportFun_RoundedRect(RoundedRect rb1, Vec2 dir_normalized)
	{
