	public static Vec2 TripleProduct(Vec2 a, Vec2 b, Vec2 c)
	{
		return new Vec2(a.y * (b.x * c.y - b.y * c.x), a.x * (b.y * c.x - b.x * c.y));
	}

	public static Vec2 SupportFun_box(Vec2 right, Vec2 up, Vec2 tr, Vec2 tl, Vec2 br, Vec2 bl, Vec2 dir)
	{
		bool flag = Vec2.Dot(right, dir) < Fix.Zero;
		bool flag2 = Vec2.Dot(up, dir) < Fix.Zero;
		if (!flag && !flag2)
		{
			return tr;
		}
		if (flag && !flag2)
		{
			return tl;
		}
		if (flag2 && !flag)
		{
			return br;
		}
		return bl;
	}

	public static Vec2 SupportFun_line(Vec2 a, Vec2 b, Vec2 dir)
	{
		if (!(Vec2.Dot(b - a, dir) < Fix.Zero))
		{
			return b;
		}
		return a;
	}
