	public static bool RayCastCircle(Vec2 origin, Vec2 dir, Circle c)
	{
		Fix fix = c.radius * c.radius;
		Vec2 vec = c.center - origin;
		Fix fix2 = Vec2.Dot(vec, dir);
		if (!(fix > Vec2.SqrMagnitude(vec)))
		{
			if (fix2 > Fix.Zero)
			{
				return Vec2.SqrMagnitude(dir * fix2 - vec) < fix;
			}
			return false;
		}
		return true;
	}

	public static bool RayCastCircle(Vec2 origin, Vec2 dir, Circle c, ref Fix shortDist, ref Fix longDist)
	{
		Vec2 vec = c.center - origin;
		Fix fix = Vec2.Dot(vec, dir);
		Fix fix2 = c.radius * c.radius;
		Fix fix3 = fix2 - Vec2.SqrMagnitude(dir * fix - vec);
		if (fix3 < Fix.Zero)
		{
			return false;
		}
		fix3 = Fix.Sqrt(fix3);
		if (fix2 > Vec2.SqrMagnitude(vec))
		{
			shortDist = Fix.Zero;
			longDist = fix + fix3;
		}
		else
		{
			if (fix < Fix.Zero)
			{
				return false;
			}
			shortDist = fix - fix3;
			longDist = fix + fix3;
		}
		return true;
	}

	public static bool RayCastAABB(Vec2 origin, Vec2 dir, AABB b)
	{
		b.max -= origin;
		b.min -= origin;
		int num = Fix.Sign(Vec2.Cross(b.max, dir));
		int num2 = Fix.Sign(Vec2.Cross(b.min, dir));
		int num3 = Fix.Sign(Vec2.Cross(new Vec2(b.min.x, b.max.y), dir));
		int num4 = Fix.Sign(Vec2.Cross(new Vec2(b.max.x, b.min.y), dir));
		if (num == num2 && num == num3)
		{
			return num != num4;
		}
		return true;
	}

	public static bool RayCastBox(Vec2 origin, Vec2 dir, Box b, ref Fix distNear, ref Fix distFar)
