		Tools.Debug_DrawLine(vec4 + origin, vec + origin, UnityEngine.Color.cyan, 10f);
		Vec2 vec5 = b.right * b.inverseExtents.x;
		Vec2 vec6 = Vec2.MulByNegI(vec5);
