			if (fix7 > Fix.Zero && fix8 > fix9 && fix8 < fix10)
			{
				if (flag)
				{
					distFar = ((fix7 > distFar) ? fix7 : distFar);
					distNear = ((fix7 < distNear) ? fix7 : distNear);
