				}
				distNear = fix7;
				distFar = fix7;
				flag = true;
			}
		}
		if (fix != Fix.Zero)
		{
			Fix fix11 = -Vec2.Dot(vec3, vec6) / fix;
			Fix fix12 = Vec2.Dot(dir * fix11, -vec5);
			Fix fix13 = Vec2.Dot(vec3, -vec5);
			Fix fix14 = Vec2.Dot(vec4, -vec5);
			if (fix11 > Fix.Zero && fix12 > fix13 && fix12 < fix14)
			{
				if (flag)
				{
					distFar = ((fix11 > distFar) ? fix11 : distFar);
					distNear = ((fix11 < distNear) ? fix11 : distNear);
					return true;
