		if (fix2 != Fix.Zero)
		{
			Fix fix15 = Vec2.Dot(vec, vec5) / fix2;
			Fix fix16 = Vec2.Dot(dir * fix15, -vec6);
			Fix fix17 = Vec2.Dot(vec4, -vec6);
			Fix fix18 = Vec2.Dot(vec, -vec6);
			if (fix15 > Fix.Zero && fix16 > fix17 && fix16 < fix18)
			{
				if (flag)
				{
					distFar = ((fix15 > distFar) ? fix15 : distFar);
					distNear = ((fix15 < distNear) ? fix15 : distNear);
					return true;
				}
				distNear = fix15;
				distFar = fix15;
