	}

	public static bool RayCastBox(Vec2 origin, Vec2 dir, Box b)
	{
		b.center -= origin;
		Vec2 v = b.center - b.right + b.up;
		Vec2 v2 = b.center + b.right + b.up;
		Vec2 v3 = b.center + b.right - b.up;
		Vec2 v4 = b.center - b.right - b.up;
		Vec2 vec = b.right * b.inverseExtents.x;
		Vec2 vec2 = Vec2.MulByNegI(vec);
		Fix fix = Vec2.Cross(vec, dir);
		Fix fix2 = Vec2.Cross(vec2, dir);
		if (fix == Fix.Zero)
		{
			Fix fix3 = -Vec2.Dot(v2, vec2) / fix;
			Fix fix4 = Vec2.Dot(dir * fix3, vec);
			Fix fix5 = Vec2.Dot(v, vec);
			Fix fix6 = Vec2.Dot(v2, vec);
			if (fix3 > Fix.Zero && fix4 > fix5 && fix4 < fix6)
			{
				return true;
			}
		}
		if (fix2 == Fix.Zero)
		{
			Fix fix7 = Vec2.Dot(v2, vec) / fix2;
			Fix fix8 = Vec2.Dot(dir * fix7, vec2);
			Fix fix9 = Vec2.Dot(v2, vec2);
			Fix fix10 = Vec2.Dot(v3, vec2);
			if (fix7 > Fix.Zero && fix8 > fix9 && fix8 < fix10)
			{
				return true;
			}
		}
		if (fix == Fix.Zero)
		{
			Fix fix11 = -Vec2.Dot(v3, vec2) / fix;
			Fix fix12 = Vec2.Dot(dir * fix11, -vec);
			Fix fix13 = Vec2.Dot(v3, -vec);
			Fix fix14 = Vec2.Dot(v4, -vec);
			if (fix11 > Fix.Zero && fix12 > fix13 && fix12 < fix14)
			{
				return true;
			}
		}
		if (fix2 == Fix.Zero)
		{
			Fix fix15 = Vec2.Dot(v, vec) / fix2;
			Fix fix16 = Vec2.Dot(dir * fix15, -vec2);
			Fix fix17 = Vec2.Dot(v4, -vec2);
			Fix fix18 = Vec2.Dot(v, -vec2);
			if (fix15 > Fix.Zero && fix16 > fix17 && fix16 < fix18)
			{
				return true;
			}
		}
