	}

	public static bool RayCastRoundedRect(Vec2 origin, Vec2 dir, RoundedRect r)
	{
		Vec2 vec = r.box.right * r.box.inverseExtents.x;
		Vec2 vec2 = Vec2.MulByNegI(vec);
		r.box.center -= origin;
		Fix fix = Vec2.Cross(vec, dir);
		Fix fix2 = Vec2.Cross(vec2, dir);
		if (fix != Fix.Zero)
		{
			Vec2 vec3 = r.box.center - r.box.right + r.box.up - vec2 * r.radius;
			Vec2 vec4 = r.box.center + r.box.right + r.box.up - vec2 * r.radius;
			UnityEngine.Debug.DrawLine((Vector3)vec3, (Vector3)vec4, UnityEngine.Color.cyan);
			Fix fix3 = -Vec2.Dot(vec4, vec2) / fix;
			Fix fix4 = Vec2.Dot(dir * fix3, vec);
			Fix fix5 = Vec2.Dot(vec3, vec);
			Fix fix6 = Vec2.Dot(vec4, vec);
			if (fix3 > Fix.Zero && fix4 > fix5 && fix4 < fix6)
			{
				return true;
			}
		}
		if (fix2 != Fix.Zero)
		{
			Vec2 vec5 = r.box.center + r.box.right + r.box.up + vec * r.radius;
			Vec2 vec6 = r.box.center + r.box.right - r.box.up + vec * r.radius;
			UnityEngine.Debug.DrawLine((Vector3)vec5, (Vector3)vec6, UnityEngine.Color.cyan);
			Fix fix7 = Vec2.Dot(vec5, vec) / fix2;
			Fix fix8 = Vec2.Dot(dir * fix7, vec2);
			Fix fix9 = Vec2.Dot(vec5, vec2);
			Fix fix10 = Vec2.Dot(vec6, vec2);
			if (fix7 > Fix.Zero && fix8 > fix9 && fix8 < fix10)
			{
				return true;
			}
		}
		if (fix != Fix.Zero)
		{
			Vec2 vec7 = r.box.center + r.box.right - r.box.up + vec2 * r.radius;
			Vec2 vec8 = r.box.center - r.box.right - r.box.up + vec2 * r.radius;
			UnityEngine.Debug.DrawLine((Vector3)vec7, (Vector3)vec8, UnityEngine.Color.cyan);
			Fix fix11 = -Vec2.Dot(vec7, vec2) / fix;
			Fix fix12 = Vec2.Dot(dir * fix11, -vec);
			Fix fix13 = Vec2.Dot(vec7, -vec);
			Fix fix14 = Vec2.Dot(vec8, -vec);
			if (fix11 > Fix.Zero && fix12 > fix13 && fix12 < fix14)
			{
				return true;
			}
		}
		if (fix2 != Fix.Zero)
		{
			Vec2 vec9 = r.box.center - r.box.right - r.box.up - vec * r.radius;
			Vec2 vec10 = r.box.center - r.box.right + r.box.up - vec * r.radius;
			UnityEngine.Debug.DrawLine((Vector3)vec9, (Vector3)vec10, UnityEngine.Color.cyan);
			Fix fix15 = Vec2.Dot(vec10, vec) / fix2;
			Fix fix16 = Vec2.Dot(dir * fix15, -vec2);
			Fix fix17 = Vec2.Dot(vec9, -vec2);
			Fix fix18 = Vec2.Dot(vec10, -vec2);
			if (fix15 > Fix.Zero && fix16 > fix17 && fix16 < fix18)
			{
				return true;
			}
		}
		Fix radSqrd = r.radius * r.radius;
		if (RaycastCircleSub(r.box.center + r.box.right + r.box.up, dir, radSqrd))
		{
			return true;
		}
		if (RaycastCircleSub(r.box.center + r.box.right - r.box.up, dir, radSqrd))
		{
			return true;
		}
		if (RaycastCircleSub(r.box.center - r.box.right + r.box.up, dir, radSqrd))
		{
			return true;
		}
		if (RaycastCircleSub(r.box.center - r.box.right - r.box.up, dir, radSqrd))
		{
			return true;
		}
		return false;
	}

	private static bool RaycastCircleSub(Vec2 localCenter, Vec2 dir, Fix radSqrd)
	{
		Fix fix = Vec2.Dot(localCenter, dir);
		if (!(radSqrd > Vec2.SqrMagnitude(localCenter)))
		{
			if (fix > Fix.Zero)
			{
				return Vec2.SqrMagnitude(dir * fix - localCenter) < radSqrd;
			}
			return false;
		}
		return true;
	}

	private static bool RaycastCircleSub(Vec2 localCenter, Vec2 dir, Fix radSqrd, out Fix SqrdDistance)
	{
		Fix fix = Vec2.Dot(localCenter, dir);
		SqrdDistance = Vec2.SqrMagnitude(dir * fix - localCenter);
		if (!(radSqrd > Vec2.SqrMagnitude(localCenter)))
		{
			if (fix > Fix.Zero)
			{
				return SqrdDistance < radSqrd;
			}
			return false;
		}
		return true;
	}

	public static bool RayCastRoundedRect(Vec2 origin, Vec2 dir, RoundedRect r, out Fix distNear, out Fix distFar)
