public struct Vec2 : IEquatable<Vec2>
{
	public Fix x;

	public Fix y;

	public static readonly Vec2 zero = new Vec2(Fix.Zero, Fix.Zero);

	public static readonly Vec2 up = new Vec2(Fix.Zero, Fix.One);

	public static readonly Vec2 down = new Vec2(Fix.Zero, -Fix.One);

	public static readonly Vec2 left = new Vec2(-Fix.One, Fix.Zero);

	public static readonly Vec2 right = new Vec2(Fix.One, Fix.Zero);

	public Vec2(Fix x, Fix y)
	{
		this.x = x;
		this.y = y;
	}

	public Vec2(Fix angleRadians)
	{
		x = Fix.FastCos(angleRadians);
		y = Fix.FastSin(angleRadians);
	}

	public static Vec2 operator +(Vec2 v, Vec2 u)
	{
		return new Vec2(v.x + u.x, v.y + u.y);
	}

	public static Vec2 operator -(Vec2 v, Vec2 u)
	{
		return new Vec2(v.x - u.x, v.y - u.y);
	}

	public static Vec2 operator -(Vec2 v)
	{
		return new Vec2(-v.x, -v.y);
	}

	public static Vec2 operator *(Fix s, Vec2 v)
	{
		return new Vec2(s * v.x, s * v.y);
	}

	public static Vec2 operator *(Vec2 v, Fix s)
	{
		return new Vec2(s * v.x, s * v.y);
	}

	public static Vec2 operator /(Vec2 v, Fix s)
	{
		return new Vec2(v.x / s, v.y / s);
	}

	public static bool operator ==(Vec2 v, Vec2 u)
	{
		if (v.x == u.x)
		{
			return v.y == u.y;
		}
		return false;
	}

	public static bool operator !=(Vec2 v, Vec2 u)
	{
		if (!(v.x != u.x))
		{
			return v.y != u.y;
		}
		return true;
	}

	public static Fix Dot(Vec2 v, Vec2 u)
	{
		return v.x * u.x + v.y * u.y;
	}

	public static Fix Cross(Vec2 v, Vec2 u)
	{
		return v.x * u.y - v.y * u.x;
	}

	public static Vec2 CrossProduct2(Fix s, Vec2 v)
	{
		return new Vec2(-s * v.y, s * v.x);
	}

	public static Vec2 CrossProduct2(Vec2 v, Fix s)
	{
		return new Vec2(s * v.y, -s * v.x);
	}

	public static Vec2 Normalized(Vec2 v)
	{
		return v / Magnitude(v);
	}

	public static Vec2 NormalizedSafe(Vec2 v)
	{
		Fix fix = Magnitude(v);
		if (fix == Fix.Zero)
		{
			return v;
		}
		return v / fix;
	}

	public static Fix Magnitude(Vec2 v)
	{
		return Fix.Sqrt(v.x * v.x + v.y * v.y);
	}

	public static Fix SqrMagnitude(Vec2 v)
	{
		return v.x * v.x + v.y * v.y;
	}

	public static Fix Distance(Vec2 v, Vec2 u)
	{
		return Magnitude(v - u);
	}

	public static Vec2 MulByI(Vec2 v)
	{
		return new Vec2(-v.y, v.x);
	}

	public static Vec2 MulByNegI(Vec2 v)
	{
		return new Vec2(v.y, -v.x);
	}

	public static Vec2 ComplexMul(Vec2 v, Vec2 u)
	{
		return new Vec2(v.x * u.x - v.y * u.y, v.y * u.x + v.x * u.y);
	}

	public static Vec2 Lerp(Vec2 v, Vec2 u, Fix t)
	{
		return new Vec2(Fix.Lerp(v.x, u.x, t), Fix.Lerp(v.y, u.y, t));
	}

	public static Vec2 ApproachNormalizedVector(Vec2 v, Vec2 target, Fix angularIncrement)
	{
		Fix fix = Cross(v, target);
		Vec2 u = ((fix < 0L) ? new Vec2(-angularIncrement) : new Vec2(angularIncrement));
		v = ComplexMul(v, u);
		Fix fix2 = Cross(v, target);
		if (fix * fix2 <= 0L)
		{
			v = target;
		}
		return v;
	}

	public static Vec2 Slerp(Vec2 v, Vec2 u, Fix s)
	{
		Fix fix = Fix.Acos(Fix.Min(Fix.Clamp(Dot(v, u), -Fix.One, Fix.One), (Fix)0.9999f));
		Fix fix2 = Fix.Sin(fix);
		fix2 = ((fix2 == Fix.Zero) ? ((Fix)1E-05f) : fix2);
		Fix fix3 = Fix.One / fix2;
		return v * Fix.Sin((Fix.One - s) * fix) * fix3 + u * Fix.Sin(s * fix) * fix3;
	}

	public static Vec2 nlerp(Vec2 v, Vec2 u, Fix t)
	{
		return NormalizedSafe(Lerp(v, u, t));
	}

	public static Fix NormalizedVectorAngle(Vec2 v)
	{
		Fix fix = Fix.FromRaw(Fix.One.m_rawValue + 1);
		v.x = Fix.SlowMod(v.x, fix);
		Fix fix2 = Fix.Acos(Dot(v, right));
		if (!(v.y > 0L))
		{
			return Fix.PiTimes2 - fix2;
		}
		return fix2;
	}

	public override bool Equals(object obj)
	{
		if (obj is Vec2)
		{
			return Equals((Vec2)obj);
		}
		return false;
	}

	public bool Equals(Vec2 other)
	{
		if (x.Equals(other.x))
		{
			return y.Equals(other.y);
		}
		return false;
	}

	public override int GetHashCode()
	{
		return (1502939027 * -1521134295 + EqualityComparer<Fix>.Default.GetHashCode(x)) * -1521134295 + EqualityComparer<Fix>.Default.GetHashCode(y);
	}

	public override string ToString()
	{
		string[] obj = new string[5] { "(", null, null, null, null };
		Fix fix = x;
		obj[1] = fix.ToString();
		obj[2] = ", ";
		fix = y;
		obj[3] = fix.ToString();
		obj[4] = ")";
		return string.Concat(obj);
	}

	public static explicit operator Vec2(Vector2 v)
	{
		return new Vec2((Fix)v.x, (Fix)v.y);
	}

	public static explicit operator Vector2(Vec2 v)
	{
		return new Vector2((float)v.x, (float)v.y);
	}

	public static explicit operator Vec2(Vector3 v)
	{
		return new Vec2((Fix)v.x, (Fix)v.y);
	}

	public static explicit operator Vector3(Vec2 v)
	{
		return new Vector3((float)v.x, (float)v.y, 0f);
	}
