public class Arrow : MonoUpdatable, IPlatformAttachable, ICollisionCallback
{
	private BoplBody body;

	private DPhysicsCircle hitbox;

	private Projectile proj;

	private FixTransform fixTrans;

	private DestroyIfOutsideSceneBounds destroyIfOutside;

	public LayerMask StickTo;

	private bool hasLanded;

	private StickyRoundedRectangle stuckToGround;

	public Fix SurfaceOffset { get; private set; }

	public Fix LocalPlatformPosition { get; private set; }

	public Vec2 HitNormal { get; private set; } = Vec2.up;

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		hitbox = GetComponent<DPhysicsCircle>();
		if (hitbox == null || hitbox.IsDestroyed)
		{
			hasLanded = true;
			if (base.transform.parent != null && base.transform.parent.gameObject.layer == LayerMask.NameToLayer("wall") && !base.transform.parent.CompareTag("ResizablePlatform"))
			{
				base.transform.localScale = base.transform.localScale * base.transform.parent.localScale.x;
			}
		}
		else
		{
			hitbox.RegisterCollisionCallback(this);
			body = GetComponent<BoplBody>();
			proj = GetComponent<Projectile>();
			fixTrans = GetComponent<FixTransform>();
			destroyIfOutside = GetComponent<DestroyIfOutsideSceneBounds>();
		}
	}

	private void Start()
	{
		if (hasLanded && base.transform.parent != null && base.transform.parent.CompareTag("ResizablePlatform"))
		{
			FixTransform component = base.transform.parent.GetComponent<FixTransform>();
			if (component != null && !component.IsDestroyed)
			{
				base.transform.localScale = base.transform.localScale * (float)component.Scale;
			}
		}
	}

	public override void UpdateSim(Fix fixedDeltaTime)
	{
		if (!body.IsBeingHeld())
		{
			Fix fix = Vec2.Magnitude(body.velocity);
			Vec2 up = ((fix == 0L) ? Vec2.up : (body.velocity / fix));
			body.up = up;
		}
	}

	public override bool IsEnabled()
	{
		if (base.IsEnabled())
		{
			return !hasLanded;
		}
		return false;
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (!Tools.LayerMaskContains(StickTo, collision.layer) || hasLanded)
		{
			return;
		}
		if (body != null && !body.IsDestroyed)
		{
			body.Drop();
		}
		if ((collision.layer == LayerMask.NameToLayer("Player") && collision.colliderPP.fixTrans.GetComponent<BoplBody>() == null) || collision.colliderPP.fixTrans == null || collision.colliderPP.fixTrans.IsDestroyed)
		{
			return;
		}
		base.transform.position = (Vector3)collision.contactPoint;
		base.transform.SetParent(collision.colliderPP.fixTrans.transform);
		if (collision.layer == LayerMask.NameToLayer("wall"))
		{
			stuckToGround = collision.colliderPP.fixTrans.GetComponent<StickyRoundedRectangle>();
			LocalPlatformPosition = stuckToGround.LocalPlayerPosFromPos(collision.contactPoint, Fix.Zero);
			RepositionOnParent();
		}
		if (collision.colliderPP.fixTrans.transform.childCount > 80)
		{
			int num = 0;
			Transform child = collision.colliderPP.fixTrans.transform.GetChild(num);
			while (child != null)
			{
				Arrow component = child.GetComponent<Arrow>();
				if (component != null)
				{
					Updater.DestroyFix(component.gameObject);
					break;
				}
				num++;
				child = collision.colliderPP.fixTrans.transform.GetChild(num);
			}
		}
		AudioManager.Get().Play("arrowHit");
		Updater.DestroyFix(body);
		Updater.DestroyFix(hitbox);
		Updater.DestroyFix(proj);
		Updater.DestroyFix(destroyIfOutside);
		Updater.DestroyFix(fixTrans);
		hasLanded = true;
		for (int i = 0; i < base.transform.childCount; i++)
		{
			UnityEngine.Object.Destroy(base.transform.GetChild(i).gameObject);
		}
	}

	public void RepositionOnParent()
	{
		if ((bool)stuckToGround)
		{
			Vec2 vec = stuckToGround.PositionFromLocalPlayerPos(LocalPlatformPosition, Fix.Zero);
			base.transform.position = (Vector3)vec;
		}
	}
}
public class BlackHole : MonoUpdatable, ICollisionCallback
{
	public Fix startingMass = (Fix)1L;

	private Fix mass;

	public Fix G = (Fix)1000L;

	public Fix platformMultiplier = (Fix)10L;

	public Fix minDistance = (Fix)0.3f;

	public Fix growth = (Fix)0.3f;

	public Fix baseGrowth = (Fix)3f;

	public Fix SizeGrowthMultiplier = (Fix)2f;

	public Fix ExtraBlackHoleMergeGrowth = (Fix)10L;

	public AnimationCurveFixed SizeGrowthAnim;

	public UnityEngine.Color blackHoleColor;

	public UnityEngine.Color whiteHoleColor;

	private static int wallLayer;

	private static int projectileLayer;

	private static int itemLayer;

	private static int affectorLayer;

	private static int playerLayer;

	private static int abilityLayer;

	private static int orbLayer;

	private static int spellLayer;

	private Fix targetSize;

	private Fix prevTargetSize;

	private int ownerId = Constants.ENVIRONMENTAL_PLAYER_ID;

	[NonSerialized]
	public DPhysicsCircle dCircle;

	[HideInInspector]
	public SpriteRenderer spriteRen;

	[SerializeField]
	private ParticleSystem OnEatParticle;

	[SerializeField]
	private ParticleSystem OnEatParticlePrefab;

	private Fix startRadius;

	private ForceArrow forceArrow;

	public ForceArrow ForceArrowPrefab;

	[NonSerialized]
	public MagnetGun magnetGunHolder;

	private long holdForTicks;

	private static int BlackHoleIndex;

	private Fix timeSinceLastGrowth;

	public Fix minSize = (Fix)0.01f;

	public Fix drag01 = (Fix)0.99;

	private int holeBrightnessId = Shader.PropertyToID("_HoleBrightness");

	private int distortionId = Shader.PropertyToID("_Distortion");

	private float currentMassDist;

	public float distortionAnimationSpeed = 1f;

	public Fix ropePullStr;

	public Fix playerForce = Fix.One;

	public Fix influenceRadiusMultiplier = (Fix)4L;

	private Vec2 velocity;

	public float particlesPerArea = 100f;

	private const float maxParticles = 1000f;

	private List<ParticleSystem> onEatParticles = new List<ParticleSystem>();

	public int OwnerId
	{
		get
		{
			return ownerId;
		}
		set
		{
			ownerId = value;
		}
	}

	public void Hold(MagnetGun holder, int ticks)
	{
		magnetGunHolder = null;
		holdForTicks = ticks;
	}

	private void Update()
	{
		if (forceArrow == null)
		{
			return;
		}
		if (GameTime.IsTimeStopped())
		{
			forceArrow.gameObject.SetActive(value: true);
		}
		if (forceArrow.gameObject.activeSelf)
		{
			if (GameTime.IsTimeStopped() && dCircle.initHasBeenCalled && !GameSessionHandler.GameIsPaused)
			{
				forceArrow.SetForce((Vector2)velocity);
			}
			else
			{
				forceArrow.gameObject.SetActive(value: false);
			}
		}
	}

	private void Awake()
	{
		if (ForceArrowPrefab != null)
		{
			forceArrow = UnityEngine.Object.Instantiate(ForceArrowPrefab, base.transform.position, Quaternion.identity, base.transform);
		}
		Updater.RegisterUpdatable(this);
		mass = startingMass;
		wallLayer = LayerMask.NameToLayer("wall");
		projectileLayer = LayerMask.NameToLayer("Projectile");
		itemLayer = LayerMask.NameToLayer("item");
		affectorLayer = LayerMask.NameToLayer("RigidBodyAffector");
		playerLayer = LayerMask.NameToLayer("Player");
		abilityLayer = LayerMask.NameToLayer("Ability");
		orbLayer = LayerMask.NameToLayer("orb");
		spellLayer = LayerMask.NameToLayer("spell");
		spriteRen = GetComponent<SpriteRenderer>();
		dCircle = GetComponent<DPhysicsCircle>();
		startRadius = dCircle.GetStartRadius();
		dCircle.RegisterCollisionCallback(this);
	}

	public override void Init()
	{
		BlackHoleIndex++;
		spriteRen.sortingOrder = -1000 + BlackHoleIndex;
		prevTargetSize = (Fix)0.1f;
		targetSize = (Fix)100L;
		updateTargetSize();
		timeSinceLastGrowth = Fix.Zero;
		UpdateSize();
		dCircle.ManualInit();
	}

	public static void OnNewLevel()
	{
		BlackHoleIndex = 0;
	}

	private Fix UnClampedLerp(Fix a, Fix b, Fix t)
	{
		return a * (Fix.One - t) + b * t;
	}

	private bool UpdateSize()
	{
		Fix t = SizeGrowthAnim.Evaluate(timeSinceLastGrowth);
		t = UnClampedLerp(prevTargetSize, targetSize, t);
		t = Fix.Max(t, minSize);
		base.transform.localScale = new Vector3((float)t, (float)t, 1f);
		Fix fix = startRadius * (Fix)0.01f;
		if (t * fix < minSize)
		{
			return true;
		}
		dCircle.radius = Fix.Max(t * fix, minSize);
		return false;
	}

	private bool TooCloseToCenter(CollisionInformation collision)
	{
		return collision.collider.OverlapPoint(dCircle.position);
	}

	public void GrowIncrementally(Fix growth)
	{
		Fix fix = mass;
		mass += growth;
		if (mass > 800L)
		{
			AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.CreateAVeryBigBlackHole);
		}
		if (mass < 0L)
		{
			AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.CreateAWhiteHole);
		}
		if (mass != Fix.Zero)
		{
			velocity = Vec2.NormalizedSafe(velocity) * Fix.Sqrt(Fix.Abs(fix * Vec2.SqrMagnitude(velocity) / mass));
		}
		updateTargetSize();
	}

	public Fix GetMass()
	{
		return mass;
	}

	public void SetMass(Fix newMass)
	{
		Fix fix = mass;
		mass = newMass;
		if (mass != Fix.Zero)
		{
			velocity = Vec2.NormalizedSafe(velocity) * Fix.Sqrt(Fix.Abs(fix * Vec2.SqrMagnitude(velocity) / mass));
		}
		updateTargetSize();
	}

	public void Grow(Fix inverseMass, Fix extra)
	{
		Fix fix = Fix.One / inverseMass;
		AudioManager.Get().Play("blackHoleSuck");
		Fix fix2 = mass;
		mass += fix + baseGrowth + extra;
		if (mass > 800L)
		{
			AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.CreateAVeryBigBlackHole);
		}
		if (mass < 0L)
		{
			AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.CreateAWhiteHole);
		}
		if (mass != Fix.Zero)
		{
			velocity = Vec2.NormalizedSafe(velocity) * Fix.Sqrt(Fix.Abs(fix2 * Vec2.SqrMagnitude(velocity) / mass));
		}
		updateTargetSize();
		timeSinceLastGrowth = Fix.Zero;
	}

	private void updateTargetSize()
	{
		prevTargetSize = targetSize;
		targetSize = (Fix)100L + Fix.Abs(mass) * growth;
	}

	private Fix GravityForce(int layer, Fix inverseMass, FixTransform fixTrans)
	{
		Fix fix = Fix.One / inverseMass;
		Fix result = G * fix * mass;
		if (layer == wallLayer)
		{
			bool flag = false;
			if (fixTrans != null && !fixTrans.IsDestroyed)
			{
				AnimateVelocity component = fixTrans.GetComponent<AnimateVelocity>();
				flag = component != null && component.isBeingControlled;
			}
			if (flag)
			{
				result *= platformMultiplier;
			}
		}
		return result;
	}

	public override void UpdateSim(Fix deltaTime)
	{
		timeSinceLastGrowth += (GameTime.IsTimeStopped() ? Fix.Zero : deltaTime);
		UpdateSize();
		float b = 0f - Mathf.Clamp((float)mass, -1f, 1f);
		currentMassDist = Mathf.Lerp(currentMassDist, b, (float)deltaTime * distortionAnimationSpeed);
		if (mass < 0L)
		{
			spriteRen.color = whiteHoleColor;
			spriteRen.material.SetFloat(holeBrightnessId, 1f);
			spriteRen.material.SetFloat(distortionId, currentMassDist);
			if (OnEatParticle != null && OnEatParticle.isPlaying)
			{
				OnEatParticle.Stop();
			}
		}
		else
		{
			spriteRen.color = blackHoleColor;
			spriteRen.material.SetFloat(holeBrightnessId, 0f);
			spriteRen.material.SetFloat(distortionId, currentMassDist);
		}
		for (int num = onEatParticles.Count - 1; num >= 0; num--)
		{
			if (onEatParticles[num] == null)
			{
				onEatParticles.RemoveAt(num);
			}
			else
			{
				ParticleSystem.VelocityOverLifetimeModule velocityOverLifetime = onEatParticles[num].velocityOverLifetime;
				Vector2 vector = base.transform.position - onEatParticles[num].transform.position;
				velocityOverLifetime.orbitalOffsetX = vector.x / onEatParticles[num].transform.localScale.x;
				velocityOverLifetime.orbitalOffsetY = vector.y / onEatParticles[num].transform.localScale.y;
			}
		}
		if (GameTime.IsTimeStopped())
		{
			return;
		}
		if (magnetGunHolder != null && !magnetGunHolder.IsDestroyed)
		{
			holdForTicks--;
			if (holdForTicks <= 0)
			{
				magnetGunHolder = null;
			}
		}
		dCircle.position += velocity * deltaTime;
		velocity *= drag01;
		DetPhysics detPhysics = DetPhysics.Get();
		for (int i = 0; i < detPhysics.circles.Length; i++)
		{
			IPhysicsCollider monobehaviourCollider = detPhysics.circles.physicsParents[i].monobehaviourCollider;
			if (monobehaviourCollider == null || monobehaviourCollider.IsDestroyed || !DetPhysics.IsActive(detPhysics.circles.physicsParents[i]) || detPhysics.circles.physicsParents[i].instanceId == base.gameObject.GetInstanceID())
			{
				continue;
			}
			Vec2 vec = dCircle.position - detPhysics.circles.colliders[i].center;
			Fix fix = Vec2.SqrMagnitude(vec);
			Fix fix2 = GravityForce(detPhysics.circles.colliders[i].layer, detPhysics.circles.physicsBodies[i].inverseMass, detPhysics.circles.physicsParents[i].fixTrans);
			if (fix == 0L)
			{
				continue;
			}
			fix = Fix.Sqrt(fix);
			if (fix >= dCircle.radius * influenceRadiusMultiplier)
			{
				continue;
			}
			Fix fix3 = fix * fix * fix;
			if (fix3 == 0L)
			{
				continue;
			}
			Vec2 vec2 = vec * fix2 / fix3;
			if (detPhysics.circles.colliders[i].layer == orbLayer)
			{
				Orb.OrbType orbType = detPhysics.circles.physicsParents[i].fixTrans.GetComponent<Orb>().orbType;
				if (orbType == Orb.OrbType.shrink || orbType == Orb.OrbType.grow)
				{
					continue;
				}
			}
			else if (detPhysics.circles.colliders[i].layer == spellLayer)
			{
				continue;
			}
			detPhysics.circles.physicsBodies[i].force += vec2;
		}
		for (int j = 0; j < detPhysics.boxes.Length; j++)
		{
			IPhysicsCollider monobehaviourCollider2 = detPhysics.boxes.physicsParents[j].monobehaviourCollider;
			if (monobehaviourCollider2 == null || monobehaviourCollider2.IsDestroyed || !DetPhysics.IsActive(detPhysics.boxes.physicsParents[j]))
			{
				continue;
			}
			Vec2 vec3 = dCircle.position - detPhysics.boxes.colliders[j].center;
			Fix fix4 = Vec2.SqrMagnitude(vec3);
			Fix fix5 = GravityForce(detPhysics.boxes.colliders[j].layer, detPhysics.boxes.physicsBodies[j].inverseMass, detPhysics.boxes.physicsParents[j].fixTrans);
			if (fix4 == 0L)
			{
				continue;
			}
			fix4 = Fix.Sqrt(fix4);
			if (fix4 >= dCircle.radius * influenceRadiusMultiplier)
			{
				continue;
			}
			Fix fix6 = fix4 * fix4 * fix4;
			if (fix6 == 0L)
			{
				continue;
			}
			Vec2 vec4 = vec3 * fix5 / fix6;
			detPhysics.boxes.physicsBodies[j].force += vec4;
			if (detPhysics.boxes.colliders[j].layer == playerLayer || detPhysics.boxes.colliders[j].layer == abilityLayer)
			{
				PlayerPhysics component = detPhysics.boxes.physicsParents[j].fixTrans.GetComponent<PlayerPhysics>();
				if (component != null)
				{
					component.AddForce(-vec4 * playerForce);
				}
				else
				{
					detPhysics.boxes.physicsParents[j].fixTrans.GetComponent<PlayerBody>()?.AddForce(-vec4 * playerForce);
				}
			}
		}
		for (int k = 0; k < detPhysics.roundedRects.Length; k++)
		{
			IPhysicsCollider monobehaviourCollider3 = detPhysics.roundedRects.physicsParents[k].monobehaviourCollider;
			if (monobehaviourCollider3 == null || monobehaviourCollider3.IsDestroyed || !DetPhysics.IsActive(detPhysics.roundedRects.physicsParents[k]))
			{
				continue;
			}
			Vec2 vec5 = dCircle.position - detPhysics.roundedRects.colliders[k].box.center;
			Fix fix7 = Vec2.SqrMagnitude(vec5);
			Fix fix8 = GravityForce(detPhysics.roundedRects.colliders[k].layer, detPhysics.roundedRects.physicsBodies[k].inverseMass, detPhysics.roundedRects.physicsParents[k].fixTrans);
			if (!(fix7 == 0L) && (!(fix7 >= dCircle.radius * influenceRadiusMultiplier) || !dCircle.gameObject.CompareTag("boulder")))
			{
				fix7 = Fix.Sqrt(fix7);
				Fix fix9 = fix7 * fix7 * fix7;
				if (!(fix9 == 0L))
				{
					Vec2 vec6 = vec5 * fix8 / fix9;
					detPhysics.roundedRects.physicsBodies[k].force += vec6;
				}
			}
		}
	}

	public void AddForce(Vec2 force)
	{
		velocity += force / mass;
	}

	public void AddForceLessMassInfluence(Vec2 force)
	{
		velocity += (Fix)Fix.Sign2(mass) * force / Fix.Sqrt(Fix.Abs(mass));
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (mass < 0L)
		{
			return;
		}
		if (collision.layer == affectorLayer)
		{
			BlackHole component = collision.colliderPP.fixTrans.GetComponent<BlackHole>();
			if ((component.mass == mass && spriteRen.sortingOrder > component.spriteRen.sortingOrder) || mass > component.mass)
			{
				Grow(collision.colliderPP.monobehaviourCollider.inverseMass, ExtraBlackHoleMergeGrowth);
				Updater.DestroyFix(collision.colliderPP.fixTrans.gameObject);
				OnEatParticle.Stop();
			}
			return;
		}
		if (collision.layer == playerLayer)
		{
			PlayerCollision component2 = collision.colliderPP.fixTrans.gameObject.GetComponent<PlayerCollision>();
			Grow(collision.colliderPP.monobehaviourCollider.inverseMass, Fix.Zero);
			OnEatParticle.Stop();
			SpriteRenderer spriteRenderer = ((!collision.colliderPP.fixTrans.CompareTag("Player")) ? collision.colliderPP.fixTrans.GetComponent<SpriteRenderer>() : collision.colliderPP.fixTrans.GetComponentInChildren<SlimeController>().GetPlayerSprite());
			if (spriteRenderer != null)
			{
				SpawnParticle(spriteRenderer);
			}
			if (component2 != null)
			{
				Ability component3 = collision.colliderPP.fixTrans.GetComponent<Ability>();
				if (component3 != null)
				{
					FixTransform component4 = component3.GetComponent<FixTransform>();
					component3.ExitAbility(new AbilityExitInfo
					{
						position = component4.position,
						isDead = true,
						killerId = ownerId
					});
				}
				else
				{
					component2.killPlayer(OwnerId, spawnEffect: false, ignoreInvulnerability: true);
				}
			}
			else
			{
				Ability component5 = collision.colliderPP.fixTrans.gameObject.GetComponent<Ability>();
				component5?.GetComponent<FixTransform>();
				component5?.ExitAbility(new AbilityExitInfo
				{
					position = component5.GetComponent<FixTransform>().position,
					isDead = true,
					killerId = OwnerId,
					isGrounded = false
				});
			}
			return;
		}
		if (collision.layer == LayerMask.NameToLayer("wall"))
		{
			if (TooCloseToCenter(collision))
			{
				SpriteRenderer component6 = collision.colliderPP.fixTrans.GetComponent<SpriteRenderer>();
				if (component6 != null)
				{
					if (component6.CompareTag("ResizablePlatform"))
					{
						DPhysicsRoundedRect component7 = component6.GetComponent<DPhysicsRoundedRect>();
						Vec2 vec = component7.CalcExtents();
						ParticleSystem particleSystem = UnityEngine.Object.Instantiate(OnEatParticlePrefab, component6.transform.position, Quaternion.identity);
						ParticleSystem.VelocityOverLifetimeModule velocityOverLifetime = particleSystem.velocityOverLifetime;
						ParticleSystem.ShapeModule shape = particleSystem.shape;
						shape.shapeType = ParticleSystemShapeType.Rectangle;
						float x = (float)vec.x * 2f + (float)component7.radius * Mathf.Sqrt(2f);
						float y = (float)vec.y * 2f + (float)component7.radius * Mathf.Sqrt(2f);
						shape.scale = new Vector3(x, y, 1f);
						shape.rotation = component6.transform.rotation.eulerAngles;
						Vector2 vector = base.transform.position - particleSystem.transform.position;
						velocityOverLifetime.orbitalOffsetX = vector.x;
						velocityOverLifetime.orbitalOffsetY = vector.y;
					}
					else
					{
						SpawnParticle(component6);
					}
				}
				Grow(collision.colliderPP.monobehaviourCollider.inverseMass, Fix.Zero);
				Updater.DestroyFix(collision.colliderPP.fixTrans.gameObject);
				OnEatParticle.Stop();
			}
			else if (!OnEatParticle.isPlaying)
			{
				OnEatParticle.Play();
			}
			return;
		}
		if (collision.layer == orbLayer)
		{
			Orb.OrbType orbType = collision.colliderPP.fixTrans.GetComponent<Orb>().orbType;
			if (orbType == Orb.OrbType.shrink || orbType == Orb.OrbType.grow || orbType == Orb.OrbType.blink)
			{
				return;
			}
		}
		if (collision.colliderPP.monobehaviourCollider.inverseMass > Fix.Zero)
		{
			SpriteRenderer component8 = collision.colliderPP.fixTrans.GetComponent<SpriteRenderer>();
			if (component8 != null)
			{
				SpawnParticle(component8);
			}
			Grow(collision.colliderPP.monobehaviourCollider.inverseMass, Fix.Zero);
			Updater.DestroyFix(collision.colliderPP.fixTrans.gameObject);
			OnEatParticle.Stop();
		}
	}

	private void SpawnParticle(SpriteRenderer ren)
	{
		float num = Mathf.Min(4f * ren.sprite.bounds.extents.x * ren.sprite.bounds.extents.y * particlesPerArea, 1000f);
		ParticleSystem particleSystem = UnityEngine.Object.Instantiate(OnEatParticlePrefab, ren.transform.position, Quaternion.identity);
		particleSystem.transform.localScale = ren.transform.localScale;
		ParticleSystem.VelocityOverLifetimeModule velocityOverLifetime = particleSystem.velocityOverLifetime;
		ParticleSystem.ShapeModule shape = particleSystem.shape;
		ParticleSystem.EmissionModule emission = particleSystem.emission;
		ParticleSystem.Burst burst = emission.GetBurst(0);
		burst.count = num;
		emission.SetBursts(new ParticleSystem.Burst[1] { burst });
		shape.sprite = ren.sprite;
		shape.rotation = ren.transform.rotation.eulerAngles;
		Vector2 vector = base.transform.position - particleSystem.transform.position;
		velocityOverLifetime.orbitalOffsetX = vector.x / ren.transform.localScale.x;
		velocityOverLifetime.orbitalOffsetY = vector.y / ren.transform.localScale.y;
		onEatParticles.Add(particleSystem);
	}
}
public class BlackHoleClap : MonoUpdatable, IAbilityComponent
{
	[SerializeField]
	private AnimationData animData;

	[SerializeField]
	private Vec2 blackholeOffset;

	[SerializeField]
	private BlackHole blackHolePrefab;

	private PlayerInfo playerInfo;

	private Player player;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private DPhysicsBox hurtbox;

	private bool enteredGrounded;

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		hurtbox = GetComponent<DPhysicsBox>();
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		body.rotation = playerInfo.rotation;
		float num = (playerInfo.isFacingRight ? 1 : (-1));
		base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * num, base.transform.localScale.y, base.transform.localScale.z);
		if (!playerInfo.isGrounded)
		{
			body.selfImposedVelocity *= (Fix)0.05f;
			body.externalVelocity *= (Fix)0.05f;
		}
		if (physics.IsGrounded())
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("enter"), Fire);
		}
		else
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("enterAir"), FireAir);
		}
		enteredGrounded = playerInfo.isGrounded;
	}

	private void Fire()
	{
		FireCommon();
		animator.beginAnimThenDoAction(animData.GetAnimation("exit"), Finish);
	}

	private void FireCommon()
	{
		Vec2 u = blackholeOffset;
		u.x *= ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One);
		u = Vec2.ComplexMul(body.right, u);
		Fix fix = Fix.Clamp(body.fixtrans.Scale / (Fix)3L, Fix.One, (Fix)2L);
		Vec2 pos = body.position + fix * u;
		FixTransform.InstantiateFixed(blackHolePrefab, pos).OwnerId = playerInfo.playerId;
		AudioManager.Get().Play("spawnBlackHole");
		ability.isCastable = false;
	}

	private void FireAir()
	{
		FireCommon();
		animator.beginAnimThenDoAction(animData.GetAnimation("exitAir"), Finish);
	}

	private void Finish()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	private void Idle()
	{
		animator.beginAnimation(animData.GetAnimation("idle"));
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (!physics.IsGrounded())
		{
			if (physics.VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime))
			{
				AbilityExitInfo info = default(AbilityExitInfo);
				body.rotation = Fix.Zero;
				info.justlanded = true;
				info.groundedSpeed = physics.groundedSpeed;
				info.isGrounded = physics.IsGrounded();
				info.isFacingRight = true;
				info.position = body.position;
				info.selfImposedVelocity = body.selfImposedVelocity;
				info.externalVelocity = body.externalVelocity;
				info.currentlyAttachedGround = physics.getAttachedGround();
				info.lastSprite = spriteRen.sprite;
				info.groundedLocalPosition = physics.LocalPlatformPos;
				info.radius = physics.radius;
				ability.ExitAbility(info);
				return;
			}
		}
		else if (physics.getAttachedGround() == null || physics.getAttachedGround().IsDestroyed || !physics.getAttachedGround().gameObject.activeSelf)
		{
			AbilityExitInfo info2 = default(AbilityExitInfo);
			body.rotation = Fix.Zero;
			info2.isGrounded = false;
			info2.isFacingRight = true;
			info2.position = body.position;
			info2.selfImposedVelocity = body.selfImposedVelocity;
			info2.externalVelocity = body.externalVelocity;
			info2.currentlyAttachedGround = null;
			info2.lastSprite = spriteRen.sprite;
			info2.radius = physics.radius;
			ability.ExitAbility(info2);
			return;
		}
		physics.Move(Vec2.zero, simDeltaTime);
	}

	public void ExitAbility(AbilityExitInfo info)
	{
		info.selfImposedVelocity = body.selfImposedVelocity;
		info.externalVelocity = body.externalVelocity;
		info.isFacingRight = base.transform.localScale.x >= 0f;
		info.position = body.position;
		info.groundedSpeed = physics.groundedSpeed;
		info.isGrounded = physics.IsGrounded();
		info.currentlyAttachedGround = physics.getAttachedGround();
		info.lastSprite = spriteRen.sprite;
		info.groundedLocalPosition = physics.LocalPlatformPos;
		info.radius = physics.radius;
		ability.ExitAbility(info);
	}
}
[RequireComponent(typeof(DPhysicsCircle))]
public class BounceBall : MonoUpdatable, IAbilityComponent, ICollisionCallback
{
	private PlayerInfo playerInfo;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private BoplBody body;

	private Ability ability;

	private SpriteRenderer slimeTrail;

	private DPhysicsCircle collisionCircle;

	private Player player;

	public Fix maxDuration = (Fix)10L;

	public AnimationCurveFixed scaleOnEnter;

	public bool IsCancellable = true;

	[HideInInspector]
	public int playersKilledThisUse;

	[HideInInspector]
	public RopeBody ropeBody;

	[HideInInspector]
	public bool topAttachment;

	private uint ropeNumberOnEnter;

	public Fix minRopeLength;

	public Fix ropePullStr;

	public Fix sqrdMaxRopeSeparation;

	public Fix RopePlayerMass01 = (Fix)0.5;

	private Vec2 prevPlayerVel;

	private List<Projectile> projectileChildren = new List<Projectile>();

	[NonSerialized]
	public Fix timeSinceActivation;

	private bool IsExiting;

	private Fix timeSinceExitStarted = Fix.Zero;

	public Fix exitTime = (Fix)0.2f;

	public AnimationCurveFixed ScaleOnExit;

	private Fix scaleSum = Fix.Zero;

	private Fix exitScale = Fix.One;

	private Fix scaleLastFrame = Fix.One;

	public Fix playerCollisionBounce = (Fix)10L;

	public Fix shockwaveForce = (Fix)100L;

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	public Player getPlayer()
	{
		return player;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<BoplBody>();
		collisionCircle = GetComponent<DPhysicsCircle>();
		collisionCircle.RegisterCollisionCallback(this);
		ability = GetComponent<Ability>();
		slimeTrail = GetComponentsInChildren<SpriteRenderer>(includeInactive: true)[1];
	}

	public void OnEnterAbility()
	{
		if (!collisionCircle.initHasBeenCalled)
		{
			collisionCircle.ManualInit();
		}
		playersKilledThisUse = 0;
		AudioManager.Get().Play("rockBounce");
		IsExiting = false;
		timeSinceExitStarted = Fix.Zero;
		timeSinceActivation = Fix.Zero;
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		ropeBody = playerInfo.ropeBody;
		if (playerInfo.ropeBody != null)
		{
			ropeNumberOnEnter = playerInfo.ropeBody.number;
		}
		else
		{
			ropeNumberOnEnter = 0u;
		}
		topAttachment = playerInfo.topAttachment;
		spriteRen.material = playerInfo.playerMaterial;
		slimeTrail.material = playerInfo.playerMaterial;
		body.rotation = Fix.Zero;
		scaleSum = Fix.Zero;
		Fix fix = (Fix)((Vec2.Dot(Vec2.right, playerInfo.selfImposedVelocity) <= 0L) ? 1 : (-1));
		Vec2 vec = (prevPlayerVel = playerInfo.externalVelocity + playerInfo.selfImposedVelocity);
		if (playerInfo.isGrounded)
		{
			Vec2 vec2 = playerInfo.currentlyAttachedGround.PositionFromLocalPlayerPos(playerInfo.groundedLocalPosition, playerInfo.radius) + collisionCircle.GetStartRadius() * playerInfo.upVector * scaleOnEnter.Evaluate(Fix.Zero);
			body.position = vec2;
			base.transform.position = (Vector3)vec2;
			body.angularVelocity = Vec2.Magnitude(playerInfo.externalVelocity + playerInfo.selfImposedVelocity) * fix * collisionCircle.GetStartRadius() * (Fix)0.2f;
			body.velocity = vec * (Fix)0.6667f;
		}
		else
		{
			body.position = playerInfo.position;
			base.transform.position = (Vector3)playerInfo.position;
			body.velocity = vec;
			body.angularVelocity = Vec2.Magnitude(vec) * fix * collisionCircle.GetStartRadius() * (Fix)0.2f;
		}
		body.angularVelocity /= player.Scale;
		if (ropeBody != null)
		{
			body.angularVelocity = Fix.Zero;
			if (ropeBody.segmentSeparation * (Fix)ropeBody.segmentCount < minRopeLength * collisionCircle.Scale)
			{
				ropeBody.segmentSeparation = collisionCircle.Scale * minRopeLength / (Fix)ropeBody.segmentCount;
			}
		}
	}

	public void UpdateRopeAttachment(Fix simDelta)
	{
		if (ropeBody != null && ropeNumberOnEnter != ropeBody.number)
		{
			ropeBody = null;
		}
		int num = 0;
		if (ropeBody != null)
		{
			num = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
		}
		if (ropeBody != null && ropeBody.enabled)
		{
			Player player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
			if (player.Id == ropeBody.ownerId && player.jumpButton_PressedThisFrame())
			{
				body.velocity = (ropeBody.segment[num] - ropeBody.segmentPrev[num]) / GameTime.FixedTimeStep;
				AttachRope(null, topAttachment);
				AudioManager.Get().Play("hookshotLetGo");
			}
		}
		if (ropeBody == null || !ropeBody.enabled)
		{
			return;
		}
		ropeBody.SetTimeInAir((Fix)100L, topAttachment);
		ropeBody.SetMass01((RopePlayerMass01 == Fix.Zero) ? ((Fix)0.5) : RopePlayerMass01, topAttachment, collisionCircle.Scale);
		ropeBody.SetForce(body.velocity - prevPlayerVel, topAttachment);
		prevPlayerVel = body.velocity;
		int num2 = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
		if (!ropeBody.hasBeenDettached)
		{
			body.up = -Vec2.NormalizedSafe(body.position - ropeBody.segment[ropeBody.segmentCount - 1 - num2]);
		}
		if (ropeBody.hookHasArrived && !GameTime.IsTimeStopped() && !ropeBody.hasBeenDettached && ropeBody.hookHasArrived)
		{
			Vec2 vec = body.position - ropeBody.segment[num2];
			if (Vec2.SqrMagnitude(vec) > sqrdMaxRopeSeparation)
			{
				vec = Vec2.NormalizedSafe(vec) * sqrdMaxRopeSeparation;
			}
			body.AddForce(vec * ropePullStr * body.Scale, ForceMode2D.Impulse);
			ropeBody.segment[num2] = body.position;
		}
		else
		{
			ropeBody.segment[num2] = body.position;
		}
	}

	public void AttachRope(RopeBody rope, bool topAttachment)
	{
		if (ropeBody != null)
		{
			if (topAttachment)
			{
				ropeBody.timeInAir_start = (Fix)100L;
				ropeBody.force_start = Vec2.down * DetPhysics.Get().ropeGravity;
			}
			else
			{
				ropeBody.timeInAir_end = (Fix)100L;
				ropeBody.force_end = Vec2.down * DetPhysics.Get().ropeGravity;
			}
			ropeBody.SetMass01((RopePlayerMass01 == Fix.Zero) ? ((Fix)0.5) : RopePlayerMass01, topAttachment, Fix.One);
		}
		ropeBody = rope;
		this.topAttachment = topAttachment;
	}

	public void EnterAbilityClearRope()
	{
		prevPlayerVel = body.velocity;
		ropeBody = null;
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		playersKilledThisUse = 0;
		body.Scale = exitScale;
		body.rotation = Fix.Zero;
		exitInfo.groundedSpeed = Vec2.Magnitude(body.velocity);
		exitInfo.isGrounded = false;
		exitInfo.isFacingRight = body.velocity.x >= 0L;
		exitInfo.position = body.position;
		exitInfo.selfImposedVelocity = body.velocity;
		exitInfo.externalVelocity = Vec2.zero;
		exitInfo.currentlyAttachedGround = null;
		exitInfo.ropeAttachment = ropeBody;
		exitInfo.topAttachment = topAttachment;
		EnterAbilityClearRope();
		GetComponentsInChildren(projectileChildren);
		for (int i = 0; i < projectileChildren.Count; i++)
		{
			Updater.DestroyFix(projectileChildren[i].gameObject);
		}
		ability.ExitAbility(exitInfo);
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		UpdateRopeAttachment(SimDeltaTime);
	}

	public override void LateUpdateSim(Fix SimDeltaTime)
	{
		int num = 0;
		if (ropeBody != null)
		{
			num = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
		}
		if (ropeBody != null && ropeBody.enabled)
		{
			for (int i = 0; i < ropeBody.segmentCount - 2; i++)
			{
				if (Vec2.SqrMagnitude(ropeBody.segment[i] - ropeBody.segment[i + 1]) > DetPhysics.Get().maxStretchLength)
				{
					body.velocity = (ropeBody.segment[num] - ropeBody.segmentPrev[num]) / GameTime.FixedTimeStep;
					AttachRope(null, topAttachment);
					break;
				}
			}
		}
		if (((!player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012) && IsCancellable) || timeSinceActivation > maxDuration) && !IsExiting)
		{
			IsExiting = true;
			exitScale = collisionCircle.Scale - scaleSum;
		}
		timeSinceActivation += GameTime.FixedDeltaTime(playerInfo.playerId, SimDeltaTime);
		if (IsExiting)
		{
			timeSinceExitStarted += GameTime.FixedDeltaTime(playerInfo.playerId, SimDeltaTime);
			if (timeSinceExitStarted > exitTime)
			{
				ExitAbility(default(AbilityExitInfo));
				return;
			}
		}
		if (IsExiting)
		{
			Fix fix = collisionCircle.Scale - scaleLastFrame;
			exitScale += fix;
			Fix scale = ScaleOnExit.Evaluate(timeSinceExitStarted) * exitScale;
			collisionCircle.Scale = scale;
		}
		else
		{
			Fix scale = scaleOnEnter.Evaluate(timeSinceActivation);
			Fix fix2 = scale;
			collisionCircle.Scale += fix2;
			scaleSum += fix2;
		}
		scaleLastFrame = collisionCircle.Scale;
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (ropeBody == null)
		{
			if (collision.layer == LayerMask.NameToLayer("Player"))
			{
				body.AddForce(collision.normal * playerCollisionBounce, ForceMode2D.Impulse);
			}
			else if (collision.layer == LayerMask.NameToLayer("Projectile"))
			{
				body.AddForce(collision.normal * playerCollisionBounce * (Fix)0.1f, ForceMode2D.Impulse);
			}
		}
	}
}
[RequireComponent(typeof(Ability))]
public class BowTransform : MonoUpdatable, IAbilityComponent
{
	public Fix RotationSpeed;

	public Vec2 FirepointOffset;

	public int KnockBack;

	public Fix airealControlBlend = (Fix)0.5f;

	public AnimationData animData;

	private Vec2 inputVector = new Vec2(Fix.Zero, Fix.One);

	private PlayerInfo playerInfo;

	private Player player;

	private bool hasFired;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private DPhysicsBox hurtbox;

	private bool isLoading;

	private int loadingFrame;

	private InterruptableAudio loadingSound;

	[SerializeField]
	private BoplBody Arrow;

	[SerializeField]
	private Fix ArrowSpeed = Fix.One;

	[SerializeField]
	private int maxNumberOfArrows = 20;

	private RingBuffer<BoplBody> Arrows;

	[SerializeField]
	private Fix TimeBeforeArrowsHurtOwner = (Fix)0.3f;

	private bool releasedButton;

	public Fix maxSlowMoSpeed = (Fix)9f;

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		hurtbox = GetComponent<DPhysicsBox>();
		Arrows = new RingBuffer<BoplBody>(maxNumberOfArrows);
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		isLoading = false;
		loadingFrame = 0;
		body.rotation = (Fix)0L;
		body.externalVelocity = Vec2.zero;
		animator.beginAnimThenDoAction(animData.GetAnimation("transform"), Loading);
		if (!playerInfo.isGrounded)
		{
			physics.gravity_modifier = (Fix)0.03f;
			body.selfImposedVelocity = playerInfo.selfImposedVelocity * (Fix)0.1f;
			body.externalVelocity = playerInfo.externalVelocity * (Fix)0.1f;
		}
		inputVector = playerInfo.upVector;
		releasedButton = false;
		hasFired = false;
		body.rotation = Fix.Zero;
	}

	private void Loading()
	{
		isLoading = true;
		loadingSound = AudioManager.Get().PlayInterruptable("arrowLoad");
		animator.beginAnimThenPlayAnim(animData.GetAnimation("load"), animData.GetAnimation("loop"), FinishedLoading);
	}

	private void FinishedLoading()
	{
		loadingFrame = 4;
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		body.rotation = Fix.Zero;
		physics.UnGround(nullRotation: true, playSoundEffect: false);
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.isFacingRight = inputVector.x >= 0L;
		exitInfo.position = body.position;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.lastSprite = spriteRen.sprite;
		exitInfo.radius = physics.radius;
		ability.ExitAbility(exitInfo);
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawWireSphere((Vector2)CurrentFirePoint(), 0.3f);
	}

	private Vec2 CurrentFirePoint()
	{
		return body.position + FirepointOffset.y * body.up * body.fixtrans.Scale + FirepointOffset.x * body.right * body.fixtrans.Scale;
	}

	private void Fire(Vec2 inputVector)
	{
		if (isLoading && loadingSound.timesPlayed == AudioManager.Get().TimesSoundsPlayed(loadingSound))
		{
			loadingSound.source.Stop();
		}
		isLoading = false;
		hasFired = true;
		inputVector = Vec2.Normalized(inputVector);
		Shoot(inputVector);
		AudioManager.Get().Play("arrowShoot");
		physics.gravity_modifier = Fix.One;
		if (physics.IsGrounded())
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("fireGround"), ExitAbility);
			body.selfImposedVelocity = -physics.getAttachedGround().currentNormal(body) * (Fix)KnockBack;
			physics.UnGround(nullRotation: false);
		}
		else
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("fireAir"), ExitAbility);
			body.selfImposedVelocity = -inputVector * (Fix)KnockBack;
		}
	}

	private void Shoot(Vec2 dir)
	{
		Vec2 pos = body.position + FirepointOffset.x * body.right + FirepointOffset.y * body.up;
		BoplBody boplBody = FixTransform.InstantiateFixed(Arrow, pos, body.rotation);
		boplBody.Scale = body.fixtrans.Scale;
		Fix fix = Fix.One + (body.fixtrans.Scale - Fix.One) / (Fix)2L;
		Arrows.Add(boplBody);
		boplBody.GetComponent<IPlayerIdHolder>().SetPlayerId(playerInfo.playerId);
		boplBody.GetComponent<SpriteRenderer>().material = playerInfo.playerMaterial;
		boplBody.StartVelocity = dir * ((Fix)loadingFrame + Fix.One) * ArrowSpeed * fix + body.selfImposedVelocity;
		boplBody.GetComponent<Projectile>().DelayedEnableHurtOwner(TimeBeforeArrowsHurtOwner * fix / Vec2.Magnitude(boplBody.StartVelocity));
		boplBody.rotation = body.rotation;
		hasFired = true;
	}

	private void OldUpdate()
	{
		Vec2 v = player.AimVector();
		if (Vec2.Magnitude(v) > Constants.DEADZONE && !releasedButton)
		{
			inputVector = Vec2.Normalized(v);
		}
		if (!player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012) && !hasFired)
		{
			releasedButton = true;
		}
		if (releasedButton && !hasFired && (loadingFrame > 0 || animator.getNumberOfPassedSprites() > 2))
		{
			Fire(inputVector);
		}
		UnityEngine.Debug.DrawRay((Vector2)CurrentFirePoint(), (Vector2)Vec2.Normalized(inputVector) * 20f);
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		OldUpdate();
		if (isLoading && loadingFrame < 4)
		{
			loadingFrame = animator.getNumberOfPassedSprites();
		}
		if (physics.IsGrounded() && (Vec2.SqrMagnitude(body.selfImposedVelocity) > (Fix)1E-06f || physics.getAttachedGround() == null || !physics.getAttachedGround().isActiveAndEnabled))
		{
			physics.gravity_modifier = (Fix)0.03f;
			physics.UnGround(nullRotation: false);
		}
		if (!physics.IsGrounded())
		{
			physics.AddGravityFactor();
			if (physics.VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime) && hasFired)
			{
				AbilityExitInfo info = default(AbilityExitInfo);
				body.rotation = Fix.Zero;
				info.justlanded = true;
				info.groundedSpeed = physics.groundedSpeed;
				info.isGrounded = physics.IsGrounded();
				info.isFacingRight = inputVector.x >= 0L;
				info.position = body.position;
				info.selfImposedVelocity = body.selfImposedVelocity;
				info.externalVelocity = body.externalVelocity;
				info.currentlyAttachedGround = physics.getAttachedGround();
				info.lastSprite = spriteRen.sprite;
				info.groundedLocalPosition = physics.LocalPlatformPos;
				info.radius = physics.radius;
				ability.ExitAbility(info);
			}
		}
		if (physics.IsGrounded())
		{
			physics.Move(Vec2.zero, simDeltaTime);
		}
		if (!hasFired)
		{
			body.up = inputVector;
			if (Vec2.Magnitude(body.selfImposedVelocity) > maxSlowMoSpeed)
			{
				body.selfImposedVelocity = Vec2.Normalized(body.selfImposedVelocity) * maxSlowMoSpeed;
			}
		}
		else
		{
			Vec2 selfImposedVelocity = body.selfImposedVelocity;
			Fix inputHorz = player.HorizontalAxis();
			physics.AirealMovement(inputHorz, simDeltaTime);
			Vec2 selfImposedVelocity2 = body.selfImposedVelocity;
			body.selfImposedVelocity = Vec2.Lerp(selfImposedVelocity, selfImposedVelocity2, airealControlBlend);
		}
		if (Vec2.Magnitude(body.selfImposedVelocity) > physics.Speed)
		{
			body.selfImposedVelocity = Vec2.Normalized(body.selfImposedVelocity) * physics.Speed;
		}
		if (physics.IsGrounded())
		{
			physics.DropPlatformTest();
		}
	}
}
public class CastSpell : MonoUpdatable, IAbilityComponent
{
	[SerializeField]
	private AnimationData animData;

	[SerializeField]
	private DarknessAura Aura;

	[SerializeField]
	private Fix castTime;

	[SerializeField]
	private GameObject spell;

	[SerializeField]
	private Vec2 centerOffset;

	[SerializeField]
	private Vec2 ExitAbilityOffset;

	[SerializeField]
	private bool affectMusicVolume;

	[SerializeField]
	private Fix timeBeforeMuted;

	[SerializeField]
	private AnimationCurve cameraShake;

	[SerializeField]
	private Fix OscillateAmplitude = (Fix)0.2f;

	[SerializeField]
	private Fix OscillateFrequency = (Fix)3L;

	[SerializeField]
	private string soundEffectOnCast;

	[SerializeField]
	private Fix delayBeforeOnCastSoundEffect = Fix.Zero;

	[SerializeField]
	private string soundLoopOnEntry;

	[SerializeField]
	private float musicFadeStrength = 0.5f;

	[SerializeField]
	private Fix delayBeforeMusicFadeIn = Fix.Zero;

	[SerializeField]
	private bool onlyCastableOnce;

	private PlayerInfo playerInfo;

	private bool hasFired;

	private bool isCastingSpell;

	private Fix timeSinceActivation = Fix.Zero;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private DPhysicsCircle bigCollider;

	private ShakableCamera shakeCam;

	private FixTransform fixTrans;

	private PlayerCollision playerCol;

	private Vec2 positionOnEntry;

	private bool hasPlayedSound;

	private Player player;

	public LayerMask platformPushLayerMask;

	public LayerMask squishLayerMask;

	public Fix pushOutOfPlatformsSpeed = Fix.One;

	public Fix airResistance01 = Fix.One;

	private PhysicsParent[] circleCastResults = new PhysicsParent[5];

	public Fix inverseMass;

	private bool hasStartedUnstable;

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		playerCol = GetComponent<PlayerCollision>();
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		bigCollider = GetComponent<DPhysicsCircle>();
		shakeCam = UnityEngine.Object.FindObjectOfType<ShakableCamera>();
		fixTrans = GetComponent<FixTransform>();
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		bigCollider.UpdatePhysicsPositions();
		body.selfImposedVelocity = Vec2.zero;
		body.externalVelocity = Vec2.zero;
		timeSinceActivation = Fix.Zero;
		positionOnEntry = fixTrans.position;
		if (playerInfo.isGrounded)
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("idleToFall"), BeginChanneling);
		}
		else
		{
			BeginChanneling();
		}
		hasFired = false;
		isCastingSpell = false;
		hasStartedUnstable = false;
	}

	private void BeginChanneling()
	{
		physics.UnGround(nullRotation: true, playSoundEffect: false);
		body.rotation = Fix.Zero;
		physics.gravity_modifier = Fix.Zero;
		Aura.gameObject.SetActive(value: true);
		Aura.RestartEffects();
		animator.beginAnimThenPlayAnim(animData.GetAnimation("fallToLoop"), animData.GetAnimation("loop"));
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		if (player.RumbleState == Rumble.BuildTension)
		{
			player.Rumble(Rumble.None);
		}
		body.rotation = Fix.Zero;
		Aura.gameObject.SetActive(value: false);
		physics.UnGround(nullRotation: true, playSoundEffect: false);
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.position = body.position + ExitAbilityOffset * player.Scale;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = Vec2.zero;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		exitInfo.lastSprite = null;
		ability.ExitAbility(exitInfo);
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (physics.IsGrounded() && physics.getAttachedGround() != null && !physics.getAttachedGround().IsDestroyed)
		{
			physics.MoveAlongCurrentPlatForm(simDeltaTime);
		}
		else
		{
			if (GameTime.IsTimeStopped() && !player.isProtectedFromTimeStop)
			{
				return;
			}
			int num = DetPhysics.Get().CircleCastAll(fixTrans.position, bigCollider.radius, platformPushLayerMask, ref circleCastResults);
			if (num > 0)
			{
				for (int i = 0; i < num; i++)
				{
					PhysicsParent physicsParent = circleCastResults[i];
					DetPhysics detPhysics = DetPhysics.Get();
					if (physicsParent.monobehaviourCollider.shape == Shape.RoundedRect)
					{
						int num2 = detPhysics.circles.ColliderIndex(bigCollider.pp.instanceId);
						int num3 = detPhysics.roundedRects.ColliderIndex(circleCastResults[i].instanceId);
						CollisionManifold collisionManifold = default(CollisionManifold);
						if (PhysTools.CollisionTest(detPhysics.circles.colliders[num2], detPhysics.roundedRects.colliders[num3], ref collisionManifold))
						{
							body.AddForce(-collisionManifold.normal * collisionManifold.penetration * inverseMass);
						}
					}
				}
			}
			num = DetPhysics.Get().CircleCastAll(fixTrans.position, bigCollider.radius, squishLayerMask, ref circleCastResults);
			if (num >= 2)
			{
				for (int j = 0; j < num; j++)
				{
					PhysicsParent physicsParent2 = circleCastResults[j];
					DetPhysics detPhysics2 = DetPhysics.Get();
					bool flag = false;
					switch (physicsParent2.monobehaviourCollider.shape)
					{
					case Shape.Circle:
						flag = detPhysics2.circles.colliders[detPhysics2.circles.ColliderIndex(physicsParent2.instanceId)].OverlapPoint(fixTrans.position);
						break;
					case Shape.Box:
						flag = detPhysics2.boxes.colliders[detPhysics2.boxes.ColliderIndex(physicsParent2.instanceId)].OverlapPoint(fixTrans.position);
						break;
					case Shape.RoundedRect:
						flag = detPhysics2.roundedRects.colliders[detPhysics2.roundedRects.ColliderIndex(physicsParent2.instanceId)].OverlapPoint(fixTrans.position);
						break;
					}
					if (flag)
					{
						playerCol.killPlayer(Constants.ENVIRONMENTAL_PLAYER_ID, spawnEffect: true, ignoreInvulnerability: true, CauseOfDeath.Squished);
						return;
					}
				}
			}
			body.selfImposedVelocity *= airResistance01;
			body.externalVelocity *= airResistance01;
			if (Vec2.SqrMagnitude(body.Velocity) > (Fix)35L)
			{
				body.selfImposedVelocity *= airResistance01;
				body.externalVelocity *= airResistance01;
			}
		}
		timeSinceActivation += GameTime.FixedDeltaTime(playerInfo.playerId, simDeltaTime);
		if (!isCastingSpell && (!player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012) || timeSinceActivation > castTime))
		{
			hasFired = timeSinceActivation > castTime;
			if (!hasFired)
			{
				Aura.CancelEffect();
				Aura.gameObject.SetActive(value: false);
				ExitAbility();
				return;
			}
			animator.beginAnimThenDoAction(animData.GetAnimation("castSpell"), Cast);
			isCastingSpell = true;
		}
		if (timeSinceActivation >= castTime - (Fix)2f && !hasStartedUnstable)
		{
			Aura.StartUnstableAnimation(isUnstable: true);
			hasStartedUnstable = true;
			player.Rumble(Rumble.BuildTension);
		}
		shakeCam.GetTrauma();
		shakeCam.AddMinTrauma(cameraShake.Evaluate((float)timeSinceActivation / (float)castTime));
	}

	private void Update()
	{
		if (affectMusicVolume)
		{
			AudioManager.Get().FadeOutMusicTick(musicFadeStrength);
		}
		if (!GameTime.IsTimeStopped() || player.isProtectedFromTimeStop)
		{
			AudioManager.Get().PlayOrContinueLoop(soundLoopOnEntry);
		}
	}

	private void Cast()
	{
		if (onlyCastableOnce)
		{
			ability.isCastable = false;
		}
		if (player.RumbleState == Rumble.BuildTension)
		{
			player.Rumble(Rumble.None);
		}
		AudioManager.Get().Play(soundEffectOnCast);
		if (spell != null)
		{
			GameObject obj = FixTransform.InstantiateFixed(spell, fixTrans.position + centerOffset * fixTrans.Scale);
			obj.GetComponent<IPlayerIdHolder>()?.SetPlayerId(playerInfo.playerId);
			BlackHole component = obj.GetComponent<BlackHole>();
			if (component != null)
			{
				component.OwnerId = playerInfo.playerId;
			}
		}
		Aura.ExitEffect();
		Aura.gameObject.SetActive(value: false);
		animator.beginAnimThenDoAction(animData.GetAnimation("easeOutSpellCast"), ExitAbility);
	}
}
public class ControlPlatform : MonoUpdatable, IAbilityComponent
{
	[SerializeField]
	private AnimationData animData;

	[SerializeField]
	private Fix upSensitivity = (Fix)0.5f;

	[SerializeField]
	private Fix downSensitivity = (Fix)0.5f;

