	private Fix timeSinceActivation = (Fix)0L;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private ShakableCamera shakeCam;

	private DPhysicsBox hurtbox;

	[SerializeField]
	private ParticleSystem sweatParticle;

	[SerializeField]
	private float particlePositionRadius = 4f;

	private bool isChanneling;

	public Fix platformForce = (Fix)10L;

	public Fix SceneBoundLimitOffset = (Fix)5f;

	public Fix boulderForceMul01 = (Fix)0.5f;

	public Fix homePositionLerpSpeed = (Fix)1L;

	public int updatesBeforeAnimationUpdate = 2;

	private int updateCount;

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
