	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		body.rotation = Fix.Zero;
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.position = body.position;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.lastSprite = null;
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		exitInfo.isFacingRight = playerInfo.isFacingRight;
		ability.ExitAbility(exitInfo);
	}

	private void ExitAbility()
	{
		StickyRoundedRectangle attachedGround = physics.getAttachedGround();
		if (attachedGround != null)
		{
			AnimateVelocity component = attachedGround.GetComponent<AnimateVelocity>();
			if (component != null)
			{
				component.isBeingControlled = false;
			}
		}
		ExitAbility(default(AbilityExitInfo));
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		body.externalVelocity *= (Fix)0.8;
		physics.Move(Vec2.zero, simDeltaTime);
		if (GameTime.IsTimeStopped() && !player.isProtectedFromTimeStop)
		{
			return;
		}
		if (!physics.IsGrounded())
		{
			ExitAbility();
			return;
		}
		Vec2 vec = player.InputVector();
		Vec2 vec2 = vec * platformForce;
		if (Vec2.Magnitude(vec) < Constants.DEADZONE)
		{
			if (sweatParticle.isPlaying)
			{
				sweatParticle.Stop();
			}
			vec2 = Vec2.zero;
		}
		else if (!sweatParticle.isPlaying)
		{
			sweatParticle.Play();
		}
		BoplBody groundBody = physics.getAttachedGround().GetGroundBody();
		AnimateVelocity component = groundBody.GetComponent<AnimateVelocity>();
		AnimateGround component2 = groundBody.GetComponent<AnimateGround>();
		if (component != null)
		{
			component.isBeingControlled = true;
		}
		if (component != null && !GameSessionHandler.SuddenDeathInProgress)
		{
			Vec2 vec3 = Vec2.Lerp(groundBody.position, component.HomePosition, GameTime.FixedDeltaTime(playerInfo.playerId, simDeltaTime) * homePositionLerpSpeed);
			vec3 = new Vec2(Fix.Clamp(vec3.x, SceneBounds.Camera_XMin + SceneBoundLimitOffset, SceneBounds.Camera_XMax - SceneBoundLimitOffset), Fix.Clamp(vec3.y, (Fix)(-10000L), SceneBounds.Camera_YMax - SceneBoundLimitOffset));
			component.HomePosition = vec3;
			groundBody.AddForceAtPosition(vec2, body.position);
		}
		else
		{
			groundBody.AddForceAtPosition(vec2 * boulderForceMul01, body.position);
		}
		if (component2 != null)
		{
			component2.enabled = false;
		}
		OldUpdate(simDeltaTime);
	}

	private void OldUpdate(Fix SimdeltaTime)
	{
		timeSinceActivation += GameTime.FixedDeltaTime(playerInfo.playerId, SimdeltaTime);
		if (isChanneling && physics.getAttachedGround() != null)
		{
			updateCount++;
			Vec2 inputVector = player.InputVector();
			int direction = DetermineDirection(inputVector);
			if (updateCount > updatesBeforeAnimationUpdate)
			{
				updateCount = 0;
				UpdateAnimation(direction);
				UpdateParticlePosition(direction);
			}
		}
		if (!player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012))
		{
			ExitAbility();
		}
	}

	private void UpdateAnimation(int direction)
	{
		int num = direction - 1;
		SpriteFrame[] animation = animData.GetAnimation("groundPositions");
		spriteRen.sprite = animation[num].sprite;
		spriteRen.flipX = animation[num].frameDuration < 0;
	}

	private void UpdateParticlePosition(int direction)
	{
		switch (direction)
		{
		case 2:
		case 5:
		case 7:
			sweatParticle.gameObject.transform.localPosition = Vector2.up * particlePositionRadius;
			sweatParticle.gameObject.transform.localRotation = Quaternion.identity;
			return;
		default:
			switch (direction)
			{
			case 7:
				break;
			case 3:
			case 5:
			case 9:
				sweatParticle.gameObject.transform.localPosition = new Vector2(-0.8660254f, 0.5f) * particlePositionRadius;
				sweatParticle.gameObject.transform.localRotation = Quaternion.FromToRotation(Vector2.up, new Vector2(-0.5f, 0.8660254f));
				return;
			default:
				return;
			}
			break;
		case 1:
		case 4:
			break;
		}
		sweatParticle.gameObject.transform.localPosition = new Vector2(0.8660254f, 0.5f) * particlePositionRadius;
		sweatParticle.gameObject.transform.localRotation = Quaternion.FromToRotation(Vector2.up, new Vector2(0.5f, 0.8660254f));
	}

	private int DetermineDirection(Vec2 inputVector)
	{
		Vec2 u = physics.getAttachedGround().currentNormal(body);
		Vec2 u2 = new Vec2(u.y, -u.x);
		Vec2 v = Vec2.NormalizedSafe(inputVector);
		Fix fix = Vec2.Dot(v, u2);
		Fix fix2 = Vec2.Dot(v, u);
		int result = -1;
		if (Vec2.Magnitude(inputVector) < Constants.DEADZONE)
		{
			result = 7;
		}
		else if (fix2 >= (Fix)1L - upSensitivity)
		{
			result = 5;
		}
		else if (fix2 <= downSensitivity - (Fix)1L)
		{
			result = 2;
		}
		else if (fix >= 0L && fix2 >= 0L)
		{
			result = 6;
		}
		else if (fix >= 0L && fix2 <= 0L)
		{
			result = 3;
		}
		else if (fix <= 0L && fix2 >= 0L)
		{
			result = 4;
		}
		else if (fix <= 0L && fix2 <= 0L)
		{
			result = 1;
		}
		return result;
	}
}
public class DarknessAura : MonoBehaviour
{
	public SpriteRenderer redGlow;

	public SpriteRenderer blackGlow;

	public SpriteRenderer blackStreams;

	public SpriteRenderer BlackFade;

	public SpriteRenderer OrangeFlare;

	public UnityEngine.Color TargetColor;

	public SpriteRenderer character;

	public SpriteRenderer BlackBorderPrefab;

	public SpriteRenderer BlackSpherePrefab;

	public SpriteRenderer ExitEffectPrefab;

	public AnimationCurve RedGlowAnimation;

	public AnimationCurve BlackGlowAnimation;

	public AnimationCurve BlackStreamsAnimation;

	public AnimationCurve OrangeFlareAnimation;

	public AnimationCurve UnstableScale;

	public float BlackFadeAlphaFrom;

	public float BlackFadeAlphaTo;

	public float BlackFadeAnimTime = 3f;

	private float TimeSetUnstable;

	private float localTime;

	private const string property = "_AffectRadius";

	public float maxAffectRadius = 1f;

	private void Start()
	{
		localTime = 0f;
		AnimateEffects();
		base.transform.localScale = new Vector3(1f, 1f, 1f);
	}

	private void Update()
	{
		localTime += Time.deltaTime;
		AnimateEffects();
	}

	public void RestartEffects()
	{
		localTime = 0f;
		AnimateEffects();
		TimeSetUnstable = float.MaxValue;
		base.transform.localScale = new Vector3(1f, 1f, 1f);
	}

	private void AnimateEffects()
	{
		redGlow.material.SetFloat("_AffectRadius", RedGlowAnimation.Evaluate(localTime));
		blackGlow.material.SetFloat("_AffectRadius", BlackGlowAnimation.Evaluate(localTime));
		blackStreams.material.SetFloat("_AffectRadius", BlackStreamsAnimation.Evaluate(localTime));
		float num = 1f;
		if (RedGlowAnimation != null && RedGlowAnimation.keys.Length >= 1)
		{
			num = RedGlowAnimation.keys[RedGlowAnimation.keys.Length - 1].time;
		}
		UnityEngine.Color color = OrangeFlare.color;
		color.a = OrangeFlareAnimation.Evaluate(localTime);
		OrangeFlare.color = color;
		character.color = UnityEngine.Color.Lerp(UnityEngine.Color.white, TargetColor, localTime / num);
		UnityEngine.Color color2 = BlackFade.color;
		color2.a = Mathf.Lerp(BlackFadeAlphaFrom, BlackFadeAlphaTo, localTime / BlackFadeAnimTime);
		BlackFade.color = color2;
		if (TimeSetUnstable < localTime)
		{
			float num2 = UnstableScale.Evaluate(localTime - TimeSetUnstable);
			base.transform.localScale = new Vector3(num2, num2, base.transform.localScale.z);
		}
	}

	public void StartUnstableAnimation(bool isUnstable)
	{
		if (isUnstable)
		{
			TimeSetUnstable = localTime;
		}
		else
		{
			TimeSetUnstable = float.MaxValue;
		}
	}

	public void ExitEffect()
	{
		character.color = UnityEngine.Color.white;
		Vector3 position = base.transform.position + BlackSpherePrefab.transform.position;
		UnityEngine.Object.Instantiate(BlackBorderPrefab, position, Quaternion.identity);
		UnityEngine.Object.Instantiate(BlackSpherePrefab, position, Quaternion.identity);
	}

	public void CancelEffect()
	{
		character.color = UnityEngine.Color.white;
		Vector3 position = base.transform.position + BlackSpherePrefab.transform.position;
		UnityEngine.Object.Instantiate(ExitEffectPrefab, position, Quaternion.identity);
	}
}
[RequireComponent(typeof(Ability))]
public class Dash : MonoUpdatable, IAbilityComponent
{
	public Fix pauseLength;

	public Fix dashLength;

	public Sprite dashSprite;

	public Sprite anticipationSprite;

	private Vec2 inputVector;

	private PlayerInfo playerInfo;

	private Player player;

	private Ability ability;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private PlayerPhysics physics;

	private Animator animator;

	private PlayerCollision playerCol;

	private DPhysicsBox hitbox;

	[SerializeField]
	private SpriteRenderer SmearFrame;

	[SerializeField]
	private SpriteRenderer SmearFrameEffectPrefab;

	private InterruptableAudio dashSound;

	private Fix timePassed = Fix.Zero;

	private int updatesPassedInDash;

	public LayerMask colliders;

	public int FixedUpdatesInDash = 2;

	public float smearScaling = 0.2f;

	public Fix smearBaseLength = (Fix)4.1f;

	private List<RaycastInformation> collisions = new List<RaycastInformation>();

	private StickyRoundedRectangle hitGround;

	private Fix HitGroundLocalPosition;

	public Fix leaveSpeed = (Fix)100f;

	private bool inDash;

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		animator = GetComponent<Animator>();
		spriteRen = GetComponent<SpriteRenderer>();
		physics = GetComponent<PlayerPhysics>();
		playerCol = GetComponent<PlayerCollision>();
		hitbox = GetComponent<DPhysicsBox>();
	}

	public void OnEnterAbility()
	{
		collisions.Clear();
		spriteRen.enabled = true;
		SmearFrame.enabled = false;
		updatesPassedInDash = 0;
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		physics.SyncPhysicsTo(playerInfo);
		hitbox.UpdatePhysicsPositions();
		spriteRen.material = playerInfo.playerMaterial;
		body.rotation = Fix.Zero;
		base.transform.rotation = Quaternion.identity;
		spriteRen.sprite = anticipationSprite;
		inDash = false;
		timePassed = Fix.Zero;
		body.ropeBody = playerInfo.ropeBody;
		body.topAttachment = playerInfo.topAttachment;
		readyDash();
	}

	private void readyDash()
	{
		physics.UnGround(nullRotation: true, playSoundEffect: false);
		inputVector = player.AimVector();
		body.selfImposedVelocity = Vec2.zero;
		body.externalVelocity = Vec2.zero;
		dashSound = AudioManager.Get().PlayInterruptable("dash");
	}

	private void performDash()
	{
		if (Vec2.Magnitude(inputVector) < Constants.DEADZONE)
		{
			inputVector = Vec2.up;
		}
		inputVector = Vec2.Normalized(inputVector);
		Fix rotationFromDirection = Tools.GetRotationFromDirection(inputVector, Vec2.up);
		body.rotation = rotationFromDirection;
		base.transform.rotation = Quaternion.Euler(new Vector3(0f, 0f, (float)rotationFromDirection * 57.29578f));
		updatesPassedInDash = 0;
		body.selfImposedVelocity = Vec2.zero;
		body.externalVelocity = Vec2.zero;
		SmearFrame.enabled = true;
		spriteRen.enabled = false;
		SmearFrame.material.SetColor("_ShadowColor", spriteRen.material.GetColor("_ShadowColor"));
		SmearFrame.material.SetColor("_MainColor", spriteRen.material.GetColor("_MainColor"));
		SmearFrame.material.SetColor("_ReflectionColour", spriteRen.material.GetColor("_ReflectionColour"));
		DetPhysics.Get().RaycastAll(body.position, inputVector, dashLength, colliders, collisions, hitbox.GetPhysicsParent().instanceId);
		UnityEngine.Debug.DrawLine((Vector3)body.position, (Vector3)(body.position + inputVector * dashLength), UnityEngine.Color.blue, 10f);
		Fix fix = smearBaseLength * body.fixtrans.Scale;
		Vec2 position;
		Vec2 nearPos;
		for (int i = 0; i < collisions.Count; i++)
		{
			RaycastInformation raycastInformation = collisions[i];
			if (raycastInformation.layer == LayerMask.NameToLayer("wall"))
			{
				position = body.position;
				nearPos = raycastInformation.nearPos;
				_ = nearPos - position;
				SmearFrame.transform.localScale = new Vector3(1f, (float)(raycastInformation.nearDist / fix), 1f);
				SmearFrame.material.SetVector("_Scale", new Vector4(1f, SmearFrame.transform.localScale.y * smearScaling, 1f));
				hitGround = raycastInformation.pp.fixTrans.GetComponent<StickyRoundedRectangle>();
				Vec2 closestPoint = hitGround.GetClosestPoint(nearPos);
				HitGroundLocalPosition = hitGround.LocalPlayerPosFromPos(closestPoint, physics.radius);
				return;
			}
			position = body.position;
			nearPos = raycastInformation.nearPos;
			Vec2 vec = nearPos - position;
			Vec2 normal = Vec2.NormalizedSafe(vec);
			UnityEngine.Debug.DrawLine((Vector3)body.position, (Vector3)nearPos, UnityEngine.Color.yellow, 10f);
			CollisionInformation collision = new CollisionInformation
			{
				layer = base.gameObject.layer,
				collider = hitbox.physicsBox,
				colliderPP = hitbox.pp,
				contactPoint = raycastInformation.nearPos,
				normal = normal,
				pp = raycastInformation.pp,
				penetration = Fix.One,
				colliderImpactVelocity = vec
			};
			raycastInformation.pp.collisionCallback.OnCollide(collision);
			CollisionInformation collision2 = new CollisionInformation
			{
				layer = raycastInformation.layer,
				contactPoint = raycastInformation.nearPos,
				normal = normal,
				colliderPP = raycastInformation.pp
			};
			Vec2 position2 = body.position;
			body.position = raycastInformation.nearPos;
			if (playerCol.KillPlayerOnCollision(collision2))
			{
				return;
			}
			SmearFrame.transform.localScale = new Vector3(1f, (float)(raycastInformation.nearDist / fix), 1f);
			SmearFrame.material.SetVector("_Scale", new Vector4(1f, SmearFrame.transform.localScale.y * smearScaling, 1f));
			body.position = position2;
		}
		hitGround = null;
		SmearFrame.GetComponent<DPhysicsBox>();
		position = body.position;
		nearPos = position + inputVector * dashLength;
		if (nearPos.y <= SceneBounds.WaterHeight)
		{
			nearPos.y = SceneBounds.WaterHeight;
		}
		float magnitude = ((Vector2)(nearPos - position)).magnitude;
		SmearFrame.transform.localScale = new Vector3(1f, magnitude / (float)fix, 1f);
		SmearFrame.material.SetVector("_Scale", new Vector4(1f, SmearFrame.transform.localScale.y * smearScaling, 1f));
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		if (body.ropeBody != null)
		{
			RopeBody ropeBody = body.ropeBody;
			ropeBody.SetForce(inputVector * leaveSpeed * (Fix)10L, body.topAttachment);
			if (body.topAttachment)
			{
				ropeBody.segment[0] = body.position;
			}
			else
			{
				Vec2 vec = (body.position - ropeBody.segment[0]) / (Fix)ropeBody.segmentCount;
				for (int i = 1; i < ropeBody.segmentCount; i++)
				{
					ropeBody.segment[i] = ropeBody.segment[0] + vec * (Fix)i;
				}
				for (int j = 0; j < ropeBody.segmentCount; j++)
				{
					ropeBody.segmentPrev[j] = ropeBody.segment[j];
				}
			}
		}
		SmearFrame.enabled = false;
		spriteRen.enabled = true;
		exitInfo.groundedSpeed = Fix.Zero;
		exitInfo.isFacingRight = Vec2.Dot(inputVector, Vec2.right) <= 0L;
		exitInfo.selfImposedVelocity = inputVector * leaveSpeed;
		if (Constants.isSpaceLevel)
		{
			exitInfo.selfImposedVelocity *= (Fix)0.5f;
		}
		exitInfo.externalVelocity = Vec2.zero;
		exitInfo.isGrounded = false;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.position = body.position;
		exitInfo.radius = physics.radius;
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.topAttachment = body.topAttachment;
		exitInfo.ropeAttachment = body.ropeBody;
		ability.ExitAbility(exitInfo);
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		timePassed += GameTime.FixedDeltaTime(player.Id, simDeltaTime);
		if (timePassed < pauseLength)
		{
			Vec2 v = player.AimVector();
			if (Vec2.Magnitude(v) > Constants.DEADZONE)
			{
				inputVector = v;
			}
		}
		else if (!inDash)
		{
			inDash = true;
			performDash();
		}
		else
		{
			if (!inDash)
			{
				return;
			}
			if (updatesPassedInDash > FixedUpdatesInDash)
			{
				SmearFrame.enabled = false;
				spriteRen.enabled = true;
				if (hitGround != null)
				{
					body.position = hitGround.PositionFromLocalPlayerPos(HitGroundLocalPosition, physics.radius);
					physics.AttachToGround(hitGround, body.position);
					ExitAbility(default(AbilityExitInfo));
				}
				else
				{
					Vec2 position = body.position + inputVector * dashLength;
					Vec2 position2 = body.position;
					if (position.y < SceneBounds.WaterHeight)
					{
						Fix fix = (SceneBounds.WaterHeight - position2.y) / inputVector.y;
						position.y = SceneBounds.WaterHeight;
						position.x = position2.x + inputVector.x * fix;
					}
					body.position = position;
					ExitAbility(default(AbilityExitInfo));
				}
			}
			updatesPassedInDash++;
		}
	}
}
public class GrowthFlare : MonoBehaviour
{
	public AnimationCurve opacityAnim01;

	public float flareSize = 1f;

	private SpriteRenderer target;

	private float timePassed;

	private SpriteRenderer spriteRen;

	private float startOpacity;

	private ResizablePlatform resizable;

	private void Awake()
	{
		spriteRen = GetComponent<SpriteRenderer>();
		startOpacity = spriteRen.color.a;
	}

	public void Init(SpriteRenderer tar)
	{
		target = tar;
		Vector2 pivot = target.sprite.pivot;
		pivot.x /= target.sprite.bounds.size.x * target.sprite.pixelsPerUnit;
		pivot.y /= target.sprite.bounds.size.y * target.sprite.pixelsPerUnit;
		Vector2 vector = new Vector2(0.5f, 0.5f) - pivot;
		vector.x *= target.sprite.bounds.size.x * target.transform.localScale.x;
		vector.y *= target.sprite.bounds.size.y * target.transform.localScale.y;
		base.transform.position = target.transform.position + (Vector3)vector;
		base.transform.rotation = target.transform.rotation;
		timePassed = 0f;
		base.gameObject.SetActive(value: true);
		resizable = tar.GetComponent<ResizablePlatform>();
	}

	private void Update()
	{
		if (target == null)
		{
			base.gameObject.SetActive(value: false);
			return;
		}
		Vector2 pivot = target.sprite.pivot;
		pivot.x /= target.sprite.bounds.size.x * target.sprite.pixelsPerUnit;
		pivot.y /= target.sprite.bounds.size.y * target.sprite.pixelsPerUnit;
		Vector2 vector = new Vector2(0.5f, 0.5f) - pivot;
		vector.x *= target.sprite.bounds.size.x * target.transform.localScale.x;
		vector.y *= target.sprite.bounds.size.y * target.transform.localScale.y;
		base.transform.position = target.transform.position + target.transform.rotation * vector;
		base.transform.rotation = target.transform.rotation;
		float x = target.sprite.bounds.size.x * target.transform.localScale.x * flareSize;
		float y = target.sprite.bounds.size.y * target.transform.localScale.y * flareSize;
		if ((bool)resizable)
		{
			Vec2 vec = resizable.RectangleApproximation();
			x = (float)vec.x * flareSize * 2.5f;
			y = (float)vec.y * flareSize * 2.5f;
		}
		base.transform.localScale = new Vector3(x, y, 1f);
		timePassed += Time.deltaTime * (float)GameTime.PlayerTimeScale;
		if (timePassed > opacityAnim01.Duration())
		{
			base.gameObject.SetActive(value: false);
			return;
		}
		float num = opacityAnim01.Evaluate(timePassed);
		spriteRen.color = new UnityEngine.Color(spriteRen.color.r, spriteRen.color.g, spriteRen.color.b, num * startOpacity);
	}
}
[RequireComponent(typeof(Ability))]
public class GunTransform : MonoUpdatable, IAbilityComponent
{
	public Fix airealControlBlend = (Fix)0.5f;

	public AnimationData animData;

	public Vec2 FirepointOffset;

	public Fix KnockBack = (Fix)0.2;

	private Vec2 inputVector = new Vec2((Fix)0L, (Fix)1L);

	private PlayerInfo playerInfo;

	private Player player;

	private bool hasFired;

	private IGun gun;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private DPhysicsBox hurtbox;

	public string prepareToShootSoundName = "prepareToShoot";

	public Fix maxSlowMoSpeed = (Fix)9f;

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
		FirepointOffset *= scaleMultiplier;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		gun = GetComponent<IGun>();
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		hurtbox = GetComponent<DPhysicsBox>();
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		body.rotation = Fix.Zero;
		body.externalVelocity = Vec2.zero;
		animator.beginAnimThenPlayAnim(animData.GetAnimation("gunTransform"), animData.GetAnimation("gunTransformLoop"));
		if (!playerInfo.isGrounded)
		{
			physics.gravity_modifier = (Fix)0.03f;
			body.selfImposedVelocity = playerInfo.selfImposedVelocity * (Fix)0.1f;
			body.externalVelocity = playerInfo.externalVelocity * (Fix)0.1f;
		}
		inputVector = playerInfo.forwardsVector;
		hasFired = false;
		body.rotation = Fix.Zero;
		AudioManager.Get().Play(prepareToShootSoundName);
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		body.rotation = Fix.Zero;
		physics.UnGround(nullRotation: true, playSoundEffect: false);
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.isFacingRight = inputVector.x >= 0L;
		exitInfo.position = body.position;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.lastSprite = spriteRen.sprite;
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		ability.ExitAbility(exitInfo);
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawWireSphere((Vector2)(base.transform.position + (float)FirepointOffset.y * base.transform.up + (float)FirepointOffset.x * base.transform.right), 0.3f);
	}

	private Vec2 CurrentFirePoint()
	{
		return body.position + FirepointOffset.y * body.up + FirepointOffset.x * body.right;
	}

	private void EmptyExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	private void Fire(Vec2 inputVector)
	{
		hasFired = true;
		animator.beginAnimThenDoAction(animData.GetAnimation("gunTransformFire"), EmptyExitAbility);
		Vec2 up = new Vec2(-inputVector.y, inputVector.x);
		body.up = up;
		Vec2 firepoint = CurrentFirePoint();
		inputVector = Vec2.NormalizedSafe(inputVector);
		gun.Shoot(firepoint, inputVector, ref hasFired, playerInfo.playerId, alreadyHitWater: false);
		physics.gravity_modifier = Fix.One;
		if (physics.IsGrounded())
		{
			body.selfImposedVelocity = -physics.getAttachedGround().currentNormal(body) * KnockBack;
			physics.UnGround(nullRotation: true, playSoundEffect: false);
		}
		else
		{
			body.selfImposedVelocity = -inputVector * KnockBack;
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		Vec2 vec = player.AimVector();
		Fix fix = Vec2.Magnitude(vec);
		if (fix > Constants.DEADZONE)
		{
			inputVector = vec / fix;
		}
		if (physics.IsGrounded())
		{
			physics.Move(Vec2.zero, simDeltaTime);
		}
		if (!player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012) && !hasFired)
		{
			Fire(inputVector);
		}
		if (!base.gameObject.activeInHierarchy)
		{
			return;
		}
		UnityEngine.Debug.DrawRay((Vector3)CurrentFirePoint(), ((Vector3)inputVector).normalized * 20f);
		if (physics.IsGrounded() && (Vec2.SqrMagnitude(body.selfImposedVelocity) > (Fix)1E-06f || physics.getAttachedGround() == null || !physics.getAttachedGround().isActiveAndEnabled))
		{
			physics.gravity_modifier = (Fix)0.03f;
			physics.UnGround(nullRotation: true, playSoundEffect: false);
		}
		if (!physics.IsGrounded())
		{
			physics.AddGravityFactor();
			if (physics.VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime) && hasFired)
			{
				AbilityExitInfo info = default(AbilityExitInfo);
				body.rotation = (Fix)0L;
				info.justlanded = true;
				info.groundedSpeed = physics.groundedSpeed;
				info.isGrounded = physics.IsGrounded();
				info.isFacingRight = inputVector.x >= 0L;
				info.position = body.position;
				info.externalVelocity = body.externalVelocity;
				info.selfImposedVelocity = body.selfImposedVelocity;
				info.currentlyAttachedGround = physics.getAttachedGround();
				info.lastSprite = spriteRen.sprite;
				info.groundedLocalPosition = physics.LocalPlatformPos;
				info.radius = physics.radius;
				ability.ExitAbility(info);
			}
		}
		if (!hasFired)
		{
			Vec2 up = new Vec2(-inputVector.y, inputVector.x);
			body.up = up;
			if (Vec2.Magnitude(body.selfImposedVelocity) > maxSlowMoSpeed)
			{
				body.selfImposedVelocity = Vec2.Normalized(body.selfImposedVelocity) * maxSlowMoSpeed;
			}
		}
		else
		{
			Vec2 selfImposedVelocity = body.selfImposedVelocity;
			Fix inputHorz = player.HorizontalAxis();
			physics.AirealMovement(inputHorz, simDeltaTime);
			Vec2 selfImposedVelocity2 = body.selfImposedVelocity;
			body.selfImposedVelocity = Vec2.Lerp(selfImposedVelocity, selfImposedVelocity2, airealControlBlend);
		}
		if (Vec2.Magnitude(body.selfImposedVelocity) > physics.Speed)
		{
			body.selfImposedVelocity = Vec2.Normalized(body.selfImposedVelocity) * physics.Speed;
		}
		if (physics.IsGrounded())
		{
			physics.DropPlatformTest();
		}
	}
}
public interface IGun
{
	void Shoot(Vec2 firepoint, Vec2 direction, ref bool hasFired, int playerId, bool alreadyHitWater);
}
public enum MachoState
{
	idle,
	run,
	landIdle,
	air,
	turn,
	runLand,
	transforming,
	blocking,
	punch
}
public enum PunchState
{
	nothing,
	punch1,
	punch2,
	punch3
}
public enum PunchInputBuffer
{
	nothing,
	down,
	up,
	down2
}
[Serializable]
public struct RectangleF
{
	public Vec2 pos;

	public Vec2 size;
}
public class Machoman : MonoUpdatable, IAbilityComponent
{
	public AnimationData animData;

	private PlayerInfo playerInfo;

	private Player player;

	private AbilityExitInfo exitInfo;

	private DPhysicsBox hurtbox;

	private PlayerCollision playerCol;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private MachoState state;

	private PunchState punchState;

	private bool inPunchRecover;

	private Fix[] timeSinceAbilityActivated;

	[SerializeField]
	private List<RectangleF> hitboxesPunch1;

	[SerializeField]
	private List<RectangleF> hitboxesPunch2;

	[SerializeField]
	private List<RectangleF> hitboxesPunch3;

	[SerializeField]
	private Fix[] AbilityCooldowns = new Fix[3];

	[SerializeField]
	private Fix spawnBounce = (Fix)10f;

	public Fix LandrunSpeedModifier = (Fix)0.8f;

	public Fix punch1_3speedModifier = (Fix)0.4f;

	public Fix punch2SpeedModifier = (Fix)2f;

	[SerializeField]
	private LayerMask punchableThings;

	[SerializeField]
	private Fix punchStr = (Fix)100L;

	[SerializeField]
	private Fix downPunchStr = (Fix)100L;

	private Collider2D[] punchedTargets = new Collider2D[10];

	[SerializeField]
	private float downPunchCameraTrauma = 0.3f;

	private ShakableCamera shakeyCam;

	[SerializeField]
	private Fix ConstantDownForce = (Fix)10f;

	private bool facingRight = true;

	private PunchInputBuffer InputBuffer;

	[SerializeField]
	private Fix instantJumpTeleportDistance = Fix.One;

	[SerializeField]
	private Fix forceOnLanding = (Fix)30f;

	private SpeedContainer animationSpeedContainer;

	private void Awake()
	{
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		exitInfo = default(AbilityExitInfo);
		physics.OnAttachedToGround += AirToGround;
		animationSpeedContainer = new SpeedContainer();
		timeSinceAbilityActivated = new Fix[3]
		{
			(Fix)10000L,
			(Fix)10000L,
			(Fix)10000L
		};
		hurtbox = GetComponent<DPhysicsBox>();
		shakeyCam = Camera.main.transform.parent.gameObject.GetComponent<ShakableCamera>();
		playerCol = GetComponent<PlayerCollision>();
		Updater.RegisterUpdatable(this);
	}

	public void OnEnterAbility()
	{
		state = MachoState.transforming;
		punchState = PunchState.nothing;
		inPunchRecover = false;
		animator.beginAnimThenDoAction(animData.GetAnimation("transform"), delegate
		{
			physics.enabled = true;
			OnNoLongerGrounded(spriteRen.sprite);
			animationSpeedContainer.UpdateWithBody(body);
		});
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		physics.enabled = false;
		physics.UnGround();
		body.selfImposedVelocity = Vec2.zero;
		facingRight = playerInfo.isFacingRight;
		float num = (facingRight ? 1 : (-1));
		base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * num, base.transform.localScale.y, base.transform.localScale.z);
		body.rotation = Fix.Zero;
		animationSpeedContainer.UpdateWithBody(body);
		for (int num2 = 0; num2 < timeSinceAbilityActivated.Length; num2++)
		{
			timeSinceAbilityActivated[num2] = (Fix)1000L;
		}
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		body.rotation = Fix.Zero;
		physics.UnGround(nullRotation: true, playSoundEffect: false);
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.position = body.position;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.lastSprite = spriteRen.sprite;
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		ability.ExitAbility(exitInfo);
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		OldUpdate(SimDeltaTime);
		playerCol.SetInvulnerable(state == MachoState.blocking, 2u);
		if (state == MachoState.transforming)
		{
			return;
		}
		if (state == MachoState.landIdle)
		{
			Fix speed = physics.Speed;
			physics.Speed = speed * (Fix)0.5f;
			physics.Move(player.InputVector(), SimDeltaTime);
			physics.Speed = speed;
		}
		else if (state == MachoState.runLand && animator.getNumberOfPassedSprites() <= 3)
		{
			Fix speed2 = physics.Speed;
			physics.Speed = speed2 * LandrunSpeedModifier;
			physics.Move(player.InputVector(), SimDeltaTime);
			physics.Speed = speed2;
		}
		else if (state == MachoState.blocking)
		{
			physics.Move(Vec2.zero, SimDeltaTime);
			animationSpeedContainer.UpdateWithBody(body);
			if (physics.IsGrounded())
			{
				physics.getAttachedGround().GetGroundBody().AddForceAtPosition(ConstantDownForce * Vec2.down, body.position);
			}
		}
		else if (state == MachoState.punch)
		{
			if (!inPunchRecover)
			{
				List<RectangleF> list = punchState switch
				{
					PunchState.punch1 => hitboxesPunch1, 
					PunchState.punch2 => hitboxesPunch2, 
					PunchState.punch3 => hitboxesPunch3, 
					_ => null, 
				};
				if (list != null)
				{
					BoxCastPunchHitboxes(list);
				}
			}
			if ((punchState == PunchState.punch2 || punchState == PunchState.punch3) && animator.getNumberOfPassedSprites() < 3 && !inPunchRecover)
			{
				Fix speed3 = physics.Speed;
				physics.Speed = speed3 * punch2SpeedModifier;
				physics.Move(Vec2.right * ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One), SimDeltaTime);
				physics.Speed = speed3;
			}
			else if (punchState == PunchState.punch1 && animator.getNumberOfPassedSprites() < 2 && !inPunchRecover)
			{
				Fix speed4 = physics.Speed;
				physics.Speed = speed4 * punch1_3speedModifier;
				physics.Move(Vec2.right * ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One), SimDeltaTime);
				physics.Speed = speed4;
			}
			else if (inPunchRecover)
			{
				Fix speed5 = physics.Speed;
				physics.Move(player.InputVector(), SimDeltaTime);
				physics.Speed = speed5;
			}
			else
			{
				Fix speed6 = physics.Speed;
				physics.Speed = speed6 * punch1_3speedModifier;
				physics.Move(player.InputVector(), SimDeltaTime);
				physics.Speed = speed6;
			}
			animationSpeedContainer.UpdateWithBody(body);
			if (physics.IsGrounded())
			{
				physics.getAttachedGround().GetGroundBody().AddForceAtPosition(ConstantDownForce * Vec2.down, body.position);
			}
		}
		else
		{
			if (physics.IsGrounded())
			{
				physics.getAttachedGround().GetGroundBody().AddForceAtPosition(ConstantDownForce * Vec2.down, body.position);
			}
			physics.Move(player.InputVector(), SimDeltaTime);
			animationSpeedContainer.UpdateWithBody(body);
		}
	}

	private void shakeCamera(float trauma)
	{
		shakeyCam?.AddTrauma(trauma);
	}

	private void BoxCastPunchHitboxes(List<RectangleF> hitboxes)
	{
		int num;
		Vec2 vec;
		switch (punchState)
		{
		case PunchState.punch1:
			vec = body.rotation * Vec2.up;
			num = 2;
			break;
		case PunchState.punch2:
			vec = body.rotation * Vec2.right * ((base.transform.localScale.x < 0f) ? Fix.One : (-Fix.One));
			num = 1;
			break;
		case PunchState.punch3:
			vec = body.rotation * Vec2.down;
			num = 3;
			break;
		default:
			vec = Vec2.zero;
			num = -1;
			break;
		}
		if (animator.getNumberOfPassedSprites() - 1 != num)
		{
			return;
		}
		if (punchState == PunchState.punch3 && physics.IsGrounded())
		{
			physics.getAttachedGround().GetGroundBody().AddForceAtPosition(vec * downPunchStr, body.position - body.up * physics.radius);
			shakeCamera(downPunchCameraTrauma);
		}
		for (int i = 0; i < hitboxes.Count; i++)
		{
			Vec2 pos = hitboxes[i].pos;
			pos.x *= ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One);
			int num2 = 0;
			for (int j = 0; j < num2; j++)
			{
				if (punchedTargets[j].GetInstanceID() == hurtbox.GetInstanceID())
				{
					continue;
				}
				PlayerCollision component = punchedTargets[j].GetComponent<PlayerCollision>();
				if (component != null)
				{
					component.killPlayer(playerInfo.playerId, spawnEffect: true);
					continue;
				}
				BoplBody component2 = punchedTargets[j].GetComponent<BoplBody>();
				if (component2 != null && component2.isActiveAndEnabled && (!physics.IsGrounded() || component2.gameObject.GetInstanceID() != physics.getAttachedGround().ThisGameObject().GetInstanceID()))
				{
					vec = Vec2.NormalizedSafe(component2.position - (body.position + pos));
					component2.AddForceAtPosition(vec * punchStr, body.position + pos);
				}
			}
		}
	}

	private void DebugDrawBox(Rect rect)
	{
		Vector2 vector = base.transform.position + base.transform.rotation * new Vector2(rect.xMax * base.transform.localScale.x, rect.yMax);
		Vector2 vector2 = base.transform.position + base.transform.rotation * new Vector2(rect.xMin * base.transform.localScale.x, rect.yMax);
		Vector2 vector3 = base.transform.position + base.transform.rotation * new Vector2(rect.xMin * base.transform.localScale.x, rect.yMin);
		Vector2 vector4 = base.transform.position + base.transform.rotation * new Vector2(rect.xMax * base.transform.localScale.x, rect.yMin);
		UnityEngine.Debug.DrawLine(vector, vector2, UnityEngine.Color.green);
		UnityEngine.Debug.DrawLine(vector2, vector3, UnityEngine.Color.green);
		UnityEngine.Debug.DrawLine(vector3, vector4, UnityEngine.Color.green);
		UnityEngine.Debug.DrawLine(vector4, vector, UnityEngine.Color.green);
	}

	private Fix RelativeInput()
	{
		Fix zero = Fix.Zero;
		if (physics.IsGrounded())
		{
			return Vec2.Dot(physics.getAttachedGround().forwardsDirection(body), player.InputVector());
		}
		return player.HorizontalAxis();
	}

	private bool CanUseAbility(int i)
	{
		if (timeSinceAbilityActivated[i] > AbilityCooldowns[i])
		{
			return player.CanUseAbilities;
		}
		return false;
	}

	private void OldUpdate(Fix dTime)
	{
		for (int i = 0; i < timeSinceAbilityActivated.Length; i++)
		{
			timeSinceAbilityActivated[i] += dTime;
		}
		bool flag = player.jumpButton_PressedThisFrame();
		bool flag2 = player.AbilityButtonIsDown(0);
		bool flag3 = false;
		player.AbilityButtonIsDown(2);
		Fix fix = RelativeInput();
		bool flag4 = player.InputVector().x != 0L || player.InputVector().y != 0L;
		switch (state)
		{
		case MachoState.idle:
			if (flag)
			{
				Jump();
				break;
			}
			if (flag3 && CanUseAbility(1))
			{
				EnterBlock();
			}
			else if (flag2 && CanUseAbility(0))
			{
				EnterPunch();
			}
			if (flag4)
			{
				state = MachoState.run;
				animator.beginAnimation(animData.GetAnimation("run"));
			}
			break;
		case MachoState.run:
		{
			Fix fix2 = (facingRight ? Fix.One : (-Fix.One));
			if (flag)
			{
				Jump();
			}
			else if (flag3 && CanUseAbility(1))
			{
				EnterBlock();
			}
			else if (flag2 && CanUseAbility(0))
			{
				EnterPunch();
			}
			else if (!flag4)
			{
				state = MachoState.idle;
				animator.beginAnimation(animData.GetAnimation("idle"));
			}
			else if (fix2 * fix < 0L && flag4)
			{
				state = MachoState.turn;
				animator.beginAnimThenDoAction(animData.GetAnimation("turn"), delegate
				{
					facingRight = !facingRight;
					animator.beginAnimation(animData.GetAnimation("run"));
					state = MachoState.run;
					base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * (float)(facingRight ? 1 : (-1)), base.transform.localScale.y, base.transform.localScale.z);
				});
			}
			break;
		}
		case MachoState.landIdle:
			if (flag)
			{
				Jump();
			}
			else if (flag3 && CanUseAbility(1))
			{
				EnterBlock();
			}
			else if (flag2 && CanUseAbility(0))
			{
				EnterPunch();
			}
			break;
		case MachoState.air:
			if (flag3 && CanUseAbility(1))
			{
				EnterBlock();
			}
			break;
		case MachoState.turn:
			if (flag)
			{
				Jump();
			}
			else if (flag3 && CanUseAbility(1))
			{
				EnterBlock();
				facingRight = !facingRight;
				base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * (float)(facingRight ? 1 : (-1)), base.transform.localScale.y, base.transform.localScale.z);
			}
			else if (flag2 && CanUseAbility(0))
			{
				facingRight = !facingRight;
				base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * (float)(facingRight ? 1 : (-1)), base.transform.localScale.y, base.transform.localScale.z);
				EnterPunch();
			}
			else if (!flag4)
			{
				state = MachoState.idle;
				facingRight = !facingRight;
				animator.beginAnimation(animData.GetAnimation("idle"));
			}
			else if ((facingRight ? Fix.One : (-Fix.One)) * fix > 0L && flag4)
			{
				state = MachoState.turn;
				facingRight = !facingRight;
				base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * (float)(facingRight ? 1 : (-1)), base.transform.localScale.y, base.transform.localScale.z);
				animator.beginAnimThenDoAction(animData.GetAnimation("turn"), delegate
				{
					facingRight = !facingRight;
					animator.beginAnimation(animData.GetAnimation("run"));
					state = MachoState.run;
					base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * (float)(facingRight ? 1 : (-1)), base.transform.localScale.y, base.transform.localScale.z);
				});
			}
			break;
		case MachoState.runLand:
			if (flag)
			{
				Jump();
			}
			else if (flag3 && CanUseAbility(1))
			{
				EnterBlock();
			}
			else if (flag2 && CanUseAbility(0))
			{
				EnterPunch();
			}
			else if (!flag4)
			{
				state = MachoState.idle;
				animator.beginAnimation(animData.GetAnimation("idle"));
			}
			else if ((facingRight ? Fix.One : (-Fix.One)) * fix < 0L && flag4)
			{
				facingRight = !facingRight;
			}
			break;
		case MachoState.blocking:
			if (!flag3)
			{
				if (physics.IsGrounded())
				{
					state = MachoState.idle;
					animator.beginAnimation(animData.GetAnimation("idle"));
				}
				else
				{
					OnNoLongerGrounded(spriteRen.sprite);
				}
			}
			break;
		case MachoState.punch:
			if (InputBuffer == PunchInputBuffer.nothing && flag2)
			{
				InputBuffer = PunchInputBuffer.down;
			}
			else if (InputBuffer == PunchInputBuffer.down && !flag2)
			{
				InputBuffer = PunchInputBuffer.up;
			}
			else if (InputBuffer == PunchInputBuffer.up && flag2)
			{
				InputBuffer = PunchInputBuffer.down2;
			}
			if (flag && inPunchRecover)
			{
				Jump();
				InputBuffer = PunchInputBuffer.nothing;
			}
			else if (flag3 && CanUseAbility(1) && inPunchRecover)
			{
				EnterBlock();
			}
			else if (inPunchRecover && punchState == PunchState.punch1 && (flag2 || InputBuffer == PunchInputBuffer.down2))
			{
				punchState = PunchState.punch2;
				InputBuffer = PunchInputBuffer.nothing;
				inPunchRecover = false;
				animator.beginAnimThenDoAction(animData.GetAnimation("punch2"), delegate
				{
					inPunchRecover = true;
					animator.beginAnimThenDoAction(animData.GetAnimation("recovery2"), delegate
					{
						InputBuffer = PunchInputBuffer.nothing;
						state = MachoState.idle;
						inPunchRecover = false;
						animator.beginAnimation(animData.GetAnimation("idle"));
					});
				});
			}
			else
			{
				if (!inPunchRecover || punchState != PunchState.punch2 || (!flag2 && InputBuffer != PunchInputBuffer.down2))
				{
					break;
				}
				punchState = PunchState.punch3;
				InputBuffer = PunchInputBuffer.nothing;
				inPunchRecover = false;
				animator.beginAnimThenDoAction(animData.GetAnimation("punch3"), delegate
				{
					inPunchRecover = true;
					animator.beginAnimThenDoAction(animData.GetAnimation("recovery3"), delegate
					{
						InputBuffer = PunchInputBuffer.nothing;
						state = MachoState.idle;
						inPunchRecover = false;
						animator.beginAnimation(animData.GetAnimation("idle"));
					});
				});
			}
			break;
		}
		if (!physics.IsGrounded() && flag4)
		{
			facingRight = fix >= 0L;
		}
		base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * (float)(facingRight ? 1 : (-1)), base.transform.localScale.y, base.transform.localScale.z);
	}

	private void EnterPunch()
	{
		timeSinceAbilityActivated[0] = Fix.Zero;
		state = MachoState.punch;
		punchState = PunchState.punch1;
		InputBuffer = PunchInputBuffer.nothing;
		inPunchRecover = false;
		animator.beginAnimThenDoAction(animData.GetAnimation("punch1"), delegate
		{
			inPunchRecover = true;
			animator.beginAnimThenDoAction(animData.GetAnimation("recovery1"), delegate
			{
				state = MachoState.idle;
				inPunchRecover = false;
				animator.beginAnimation(animData.GetAnimation("idle"));
			});
		});
	}

	private void EnterBlock()
	{
		state = MachoState.blocking;
		InputBuffer = PunchInputBuffer.nothing;
		animator.beginAnimation(animData.GetAnimation("block"));
	}

	private void Jump()
	{
		body.selfImposedVelocity = Vec2.zero;
		physics.Jump();
		AudioManager.Get().Play("slimeJump" + player.Id);
		OnNoLongerGrounded(animData.GetVelocityMap("air")[0].sprite);
	}

	private void AirToGround(RaycastInformation collision)
	{
		StickyRoundedRectangle component = collision.pp.fixTrans.GetComponent<StickyRoundedRectangle>();
		if (!physics.enabled)
		{
			physics.enabled = true;
		}
		if (Fix.Abs(RelativeInput()) > Constants.DEADZONE)
		{
			state = MachoState.runLand;
			animator.beginAnimThenPlayAnim(animData.GetAnimation("runLand"), animData.GetAnimation("run"), delegate
			{
				state = MachoState.run;
			});
		}
		else
		{
			state = MachoState.landIdle;
			animator.beginAnimThenPlayAnim(animData.GetAnimation("land"), animData.GetAnimation("idle"), delegate
			{
				state = MachoState.idle;
			});
		}
		component.GetGroundBody().AddForceAtPosition(Vec2.NormalizedSafe(collision.nearPos - body.position) * forceOnLanding, body.position, ForceMode2D.Impulse);
		AudioManager.Get().Play("slimeLand" + player.Id);
		_ = component.currentNormal(body).y < 0L;
	}

	private void OnNoLongerGrounded(Sprite anticipationFrame)
	{
		state = MachoState.air;
		animationSpeedContainer.UpdateWithBody(body);
		animator.beginYSpeedBasedAnimation(animData.GetVelocityMap("air"), animData.GetAnimation("airLoop"), anticipationFrame, animationSpeedContainer);
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	public override void Init()
	{
	}
}
[RequireComponent(typeof(Ability))]
public class MagnetGun : MonoUpdatable, IAbilityComponent
{
	public struct ParryHitbox
	{
		public Circle circle;

		public MagnetGun magnetGunRef;
	}

	public enum HeldItemType
	{
		nothing,
		item,
		player,
		blackhole,
		spell
	}

	public enum MagnetState
	{
		entering,
		prepulling,
		pulling,
		locked,
		paused,
		exiting
	}

	public static List<ParryHitbox> parryHitboxes = new List<ParryHitbox>();

	public Fix parryPushStr;

	private MagnetState state;

	public AnimationCurveFixed pullStrMultiplierCurve;

	public Fix airealControlBlend = (Fix)0.5f;

	public AnimationData animData;

	public Vec2 FirepointOffset;

	public Fix KnockBack = (Fix)0.2;

	public HeldMagnetParticle heldParticlePrefab;

	private Vec2 inputVector = new Vec2((Fix)0L, (Fix)1L);

	private PlayerInfo playerInfo;

	private Player player;

	private bool hasFired;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	[NonSerialized]
	public DPhysicsBox hurtbox;

	private PlayerCollision playerCol;

	private HeldMagnetParticle heldParticle;

	private ParticleSystem particle_heldObject;

	private ParticleSystem particle_heldObject_child;

	private float heldParticleShapeSize;

	private SpriteRenderer batteryRen;

	private SpriteRenderer magnetRen;

	private SpriteRenderer magnetTOPRen;

	private Vec2 extraOffset;

	public Vec2 playerRockExtraOffset;

	public Vec2 boulderExtraOffset;

	private Vec2 heldPosition;

	public Fix heldPosLerpFactor01;

	public Fix FireForceMines;

	public Fix FireForce;

	public Fix FireRagdollForce;

	public Fix FireBlackHoleForce;

	public Fix FireRockForce;

	public Fix FireMissileForce;

	public Fix FireBoulderForce;

	public Fix ropedForceMul;

	public Fix maxSlowMoSpeed = (Fix)9f;

	public LayerMask onlyPull;

	public LayerMask onlyPickup;

	public Fix pickupRadius;

	public Fix maxLockDist;

	private static PhysicsParent[] hitBuffer = new PhysicsParent[100];

	public Fix closePullStrMul;

	public Fix FastPullSqrRadius;

	public Fix pullWidth;

	public Fix pullStr;

	public Fix playerPullStr;

	public Fix projectilePullStr;

	public Fix wallPullStr;

	public Fix blackHolePullStr;

	public Fix MachoSlimePullStr;

	public Fix playerMass;

	public Fix angVelOnLockedItem;

	private int batteryTicks;

	private int magnetTicks;

	private ParticleSystem idleSpark;

	private BounceBall pickedupBounceBall;

	private BoplBody heldItem;

	private SlimeController heldItemSlimeController;

	private HeldItemType heldItemState;

	private BlackHole heldBlackHole;

	private Boulder heldBoulder;

	public Fix smallRagdollDuration;

	public Fix fireRagdollDuration;

	public LayerMask wallmask;

	public Vec2 raycastOffset;

	public Fix maxPullDuration;

	private Fix timeSpentPulling;

	private Fix multiplierLastFrame;

	public static void StaticUpdate()
	{
		for (int i = 0; i < parryHitboxes.Count; i++)
		{
			for (int j = i + 1; j < parryHitboxes.Count; j++)
			{
				Circle circle = parryHitboxes[i].circle;
				Circle circle2 = parryHitboxes[j].circle;
				MagnetGun magnetGunRef = parryHitboxes[i].magnetGunRef;
				MagnetGun magnetGunRef2 = parryHitboxes[j].magnetGunRef;
				if (PhysTools.CollisionTest(circle, circle2) && magnetGunRef != null && !magnetGunRef.IsDestroyed && magnetGunRef2 != null && !magnetGunRef2.IsDestroyed && magnetGunRef2.isActiveAndEnabled && magnetGunRef.isActiveAndEnabled)
				{
					Vec2 vec = Vec2.NormalizedSafe(magnetGunRef.body.position - magnetGunRef2.body.position);
					magnetGunRef.Parry(vec);
					magnetGunRef2.Parry(-vec);
				}
			}
		}
		parryHitboxes.Clear();
	}

	public void Parry(Vec2 direction)
	{
		if (state == MagnetState.prepulling || state == MagnetState.pulling)
		{
			enterPause();
			body.AddForce(direction * parryPushStr);
		}
	}

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
		FirepointOffset *= scaleMultiplier;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		hurtbox = GetComponent<DPhysicsBox>();
		playerCol = GetComponent<PlayerCollision>();
		batteryRen = base.transform.GetChild(0).GetComponent<SpriteRenderer>();
		magnetRen = base.transform.GetChild(1).GetComponent<SpriteRenderer>();
		magnetTOPRen = base.transform.GetChild(2).GetComponent<SpriteRenderer>();
		idleSpark = base.transform.GetChild(3).GetComponent<ParticleSystem>();
		heldParticle = UnityEngine.Object.Instantiate(heldParticlePrefab, idleSpark.transform.position, Quaternion.identity);
		particle_heldObject = heldParticle.particle;
		heldParticleShapeSize = particle_heldObject.shape.scale.x;
		particle_heldObject_child = heldParticle.particle_child;
		magnetRen.enabled = false;
		batteryRen.enabled = false;
		magnetTOPRen.enabled = false;
	}

	private void updateParticle(SpriteRenderer heldRenderer)
	{
		bool flag = GameTime.IsTimeStoppedFor(playerInfo.playerId);
		if (state == MagnetState.locked)
		{
			if (heldItemState == HeldItemType.blackhole && heldBlackHole != null && !heldBlackHole.IsDestroyed)
			{
				heldParticle.SetScale(heldParticleShapeSize / heldBlackHole.transform.localScale.x, 5f);
			}
			idleSpark.Stop();
			if (heldRenderer != null)
			{
				ParticleSystem.ShapeModule shape = particle_heldObject.shape;
				shape.spriteRenderer = heldRenderer;
				ParticleSystem.ShapeModule shape2 = particle_heldObject_child.shape;
				shape2.spriteRenderer = heldRenderer;
			}
			if (particle_heldObject.isPaused || particle_heldObject.isStopped || !particle_heldObject.isPlaying)
			{
				if (heldItemState != HeldItemType.spell && !flag)
				{
					particle_heldObject.Play();
					particle_heldObject_child.Play();
				}
			}
			else if (flag)
			{
				particle_heldObject.Play();
				particle_heldObject_child.Play();
			}
		}
		else if (state == MagnetState.exiting || state == MagnetState.paused)
		{
			heldParticle.DelayedStop();
			idleSpark.Stop();
		}
		else if (particle_heldObject.isPaused || particle_heldObject.isStopped || !particle_heldObject.isPlaying)
		{
			heldParticle.DelayedStop();
		}
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		batteryRen.material = playerInfo.playerMaterial;
		magnetRen.material = playerInfo.playerMaterial;
		magnetTOPRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		body.rotation = Fix.Zero;
		body.externalVelocity = Vec2.zero;
		batteryTicks = 0;
		magnetTicks = 0;
		timeSpentPulling = Fix.Zero;
		heldParticle.reset();
		heldParticle.SetScale(1f, 1f);
		idleSpark.Stop();
		state = MagnetState.entering;
		animator.beginAnimThenDoAction(animData.GetAnimation("enter"), enterPrePull);
		if (!playerInfo.isGrounded)
		{
			physics.gravity_modifier = (Fix)0.03f;
			body.selfImposedVelocity = playerInfo.selfImposedVelocity * (Fix)0.1f;
			body.externalVelocity = playerInfo.externalVelocity * (Fix)0.1f;
		}
		heldBoulder = null;
		heldItem = null;
		heldBlackHole = null;
		heldItem = null;
		heldItemSlimeController = null;
		inputVector = playerInfo.forwardsVector;
		magnetRen.enabled = false;
		batteryRen.enabled = false;
		magnetTOPRen.enabled = false;
		hasFired = false;
		body.rotation = Fix.Zero;
		AudioManager.Get().Play("magnetEnter");
	}

	private void enterPrePull()
	{
		state = MagnetState.prepulling;
		animator.beginAnimThenDoAction(animData.GetAnimation("prepull"), enterPull);
	}

	private void enterPull()
	{
		state = MagnetState.pulling;
		animator.beginAnimation(animData.GetAnimation("idle"));
		magnetRen.enabled = true;
		batteryRen.enabled = true;
		magnetTOPRen.enabled = true;
	}

	private void enterPause()
	{
		state = MagnetState.paused;
		heldItemState = HeldItemType.nothing;
		animator.beginAnimation(animData.GetAnimation("idle"));
		magnetRen.enabled = true;
		batteryRen.enabled = true;
		magnetTOPRen.enabled = true;
		idleSpark.Stop();
		AudioManager.Get().Play("magnetPause");
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		body.rotation = Fix.Zero;
		physics.UnGround(nullRotation: true, playSoundEffect: false);
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.isFacingRight = inputVector.x >= 0L;
		exitInfo.position = body.position;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.lastSprite = spriteRen.sprite;
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		playerCol.IgnoreCollider(null, PlayerCollision.IgnoreColliderInd.magnet);
		heldParticle.DelayedStop();
		idleSpark.Stop();
		ability.ExitAbility(exitInfo);
	}

	private void OnDrawGizmos()
	{
		Vector2 vector = base.transform.position + (float)(FirepointOffset.y + extraOffset.y) * base.transform.up + (float)(FirepointOffset.x + extraOffset.x) * base.transform.right;
		Gizmos.DrawWireSphere(vector, 0.3f);
		Gizmos.DrawWireSphere(vector, (float)pickupRadius * base.transform.localScale.x);
		Gizmos.DrawWireSphere(vector, Mathf.Sqrt((float)FastPullSqrRadius));
	}

	private Vec2 CurrentFirePoint()
	{
		return body.position + (FirepointOffset.y + extraOffset.y) * body.up + (FirepointOffset.x + extraOffset.x) * body.right;
	}

	private void EmptyExitAbility()
	{
		playerCol.IgnoreCollider(null, PlayerCollision.IgnoreColliderInd.magnet);
		ExitAbility(default(AbilityExitInfo));
	}

	private void Fire(Vec2 inputVector)
	{
		hasFired = true;
		animator.beginAnimThenDoAction(animData.GetAnimation("exit"), EmptyExitAbility);
		Vec2 up = new Vec2(-inputVector.y, inputVector.x);
		body.up = up;
		CurrentFirePoint();
		inputVector = Vec2.NormalizedSafe(inputVector);
		Shoot(inputVector);
		physics.gravity_modifier = Fix.One;
		if (physics.IsGrounded())
		{
			body.selfImposedVelocity = -physics.getAttachedGround().currentNormal(body) * KnockBack;
			physics.UnGround(nullRotation: true, playSoundEffect: false);
		}
		else
		{
			body.selfImposedVelocity = -inputVector * KnockBack;
		}
		state = MagnetState.exiting;
	}

	private void Shoot(Vec2 dir)
	{
		if (state != MagnetState.locked)
		{
			return;
		}
		state = MagnetState.exiting;
		switch (heldItemState)
		{
		case HeldItemType.item:
		case HeldItemType.spell:
		{
			Fix fix = FireForce;
			if (heldItem.gameObject.layer == LayerMask.NameToLayer("Projectile"))
			{
				fix *= (Fix)2L;
			}
			else if (heldItem.gameObject.layer == LayerMask.NameToLayer("Player"))
			{
				fix = FireRockForce;
			}
			else if (heldItem.gameObject.layer == LayerMask.NameToLayer("spell"))
			{
				fix *= heldItem.Scale;
			}
			else
			{
				if ((bool)heldItem.GetComponent<Missile>())
				{
					heldItem.up = dir;
					heldItem.velocity = FireMissileForce * dir;
					heldItem = null;
					pickedupBounceBall = null;
					break;
				}
				if ((bool)heldItem.GetComponent<Mine>())
				{
					heldItem.velocity = FireForceMines * dir;
				}
			}
			if ((bool)heldBoulder)
			{
				fix = FireBoulderForce;
			}
			heldItem.AddForce(fix * dir);
			heldItem = null;
			pickedupBounceBall = null;
			break;
		}
		case HeldItemType.player:
		{
			Vec2 speed = FireRagdollForce * dir;
			if (heldItemSlimeController.body.ropeBody != null && speed.y > Fix.Zero)
			{
				heldItemSlimeController.body.ropeBody.SetTimeInAir(Fix.One / (Fix)10L, heldItemSlimeController.body.topAttachment);
			}
			heldItemSlimeController.ApplyRagDoll(fireRagdollDuration, speed, goFast: true);
			heldItemSlimeController?.playerPhysics.VelocityBasedRaycasts(attachToGroundIfHit: true, (Fix)0.0001);
			heldItemSlimeController = null;
			break;
		}
		case HeldItemType.blackhole:
			heldBlackHole.AddForce(heldBlackHole.GetMass() * FireBlackHoleForce * dir);
			heldBlackHole = null;
			break;
		case HeldItemType.nothing:
			break;
		}
	}

	private bool TryPullItems()
	{
		Fix fix = pullStrMultiplierCurve.Evaluate(timeSpentPulling / maxPullDuration);
		Vec2 vec = CurrentFirePoint();
		DetPhysics detPhysics = DetPhysics.Get();
		Fix a = (Fix)1000L;
		Fix a2 = pullWidth;
		Vec2 vec2 = Vec2.NormalizedSafe(inputVector);
		RaycastInformation raycastInformation = detPhysics.RaycastToClosestRoundedRect(vec, vec2, (Fix)10000L);
		if ((bool)raycastInformation)
		{
			a = raycastInformation.nearDist / (Fix)2L;
		}
		Tools.Debug_DrawLine_fu(vec, raycastInformation.nearPos, UnityEngine.Color.green);
		a = Fix.Max(a, (Fix)0.01);
		a2 = Fix.Max(a2, (Fix)0.01);
		Box b = new Box
		{
			center = vec,
			right = vec2 * a,
			up = Vec2.MulByI(vec2) * a2,
			inverseExtents = new Vec2(Fix.One / a, Fix.One / a2)
		};
		b.center += b.right;
		int num = detPhysics.CollideBox(b, ref hitBuffer, onlyPull);
		bool result = false;
		for (int i = 0; i < num; i++)
		{
			Vec2 position = hitBuffer[i].fixTrans.position;
			Fix fix2 = Vec2.SqrMagnitude(position - FirepointOffset);
			Fix fix3 = fix;
			if (hitBuffer[i].fixTrans.gameObject.layer == LayerMask.NameToLayer("Projectile"))
			{
				if (fix2 < FastPullSqrRadius)
				{
					fix3 *= closePullStrMul;
				}
				BoplBody component = hitBuffer[i].fixTrans.GetComponent<BoplBody>();
				if ((bool)component)
				{
					component.AddForce(-projectilePullStr * fix3 * vec2);
				}
			}
			else if (hitBuffer[i].fixTrans.gameObject.layer == LayerMask.NameToLayer("wall"))
			{
				if (physics.IsGrounded() && physics.getAttachedGround().HierarchyNumber == hitBuffer[i].fixTrans.GetComponent<StickyRoundedRectangle>().HierarchyNumber)
				{
					continue;
				}
				Vec2 v = position - body.position;
				Vec2 pos = body.position + Vec2.Dot(v, vec2) * vec2;
				Tools.Debug_DrawPos_fu(pos, UnityEngine.Color.red);
				hitBuffer[i].fixTrans.GetComponent<BoplBody>().AddForceAtPosition(-wallPullStr * fix3 * vec2, pos);
			}
			else if (hitBuffer[i].fixTrans.gameObject.layer == LayerMask.NameToLayer("RigidBodyAffector"))
			{
				BlackHole component2 = hitBuffer[i].fixTrans.GetComponent<BlackHole>();
				if ((bool)component2)
				{
					component2.AddForce(-blackHolePullStr * vec2);
				}
			}
			else
			{
				if (fix2 < FastPullSqrRadius)
				{
					fix3 *= closePullStrMul;
				}
				BoplBody component3 = hitBuffer[i].fixTrans.GetComponent<BoplBody>();
				if ((bool)component3)
				{
					component3.AddForce(-pullStr * fix3 * vec2);
				}
				else
				{
					PlayerBody component4 = hitBuffer[i].fixTrans.GetComponent<PlayerBody>();
					MachoThrow2 component5 = hitBuffer[i].fixTrans.GetComponent<MachoThrow2>();
					if (component4 != null)
					{
						if (component5 != null)
						{
							component4.externalVelocity -= MachoSlimePullStr * fix3 * vec2;
						}
						else
						{
							component4.externalVelocity -= playerPullStr * fix3 * vec2;
						}
					}
				}
			}
			result = true;
		}
		return result;
	}

	private bool TryPickupNearbyItems()
	{
		Vec2 vec = CurrentFirePoint();
		DetPhysics detPhysics = DetPhysics.Get();
		hurtbox.enabled = false;
		int num = detPhysics.CircleCastAll(vec, pickupRadius * body.fixtrans.Scale, onlyPickup, ref hitBuffer);
		hurtbox.enabled = true;
		Fix fix = Fix.MaxValue;
		int num2 = -1;
		parryHitboxes.Add(new ParryHitbox
		{
			circle = new Circle
			{
				center = vec,
				radius = pickupRadius * body.fixtrans.Scale
			},
			magnetGunRef = this
		});
		for (int i = 0; i < num; i++)
		{
			if (hitBuffer[i].fixTrans == null || hitBuffer[i].fixTrans.IsDestroyed || !hitBuffer[i].fixTrans.gameObject.activeSelf || (hitBuffer[i].fixTrans.gameObject.layer == LayerMask.NameToLayer("wall") && !hitBuffer[i].fixTrans.CompareTag("boulder")))
			{
				continue;
			}
			if (hitBuffer[i].fixTrans.gameObject.layer == LayerMask.NameToLayer("Player"))
			{
				SlimeController component = hitBuffer[i].fixTrans.GetComponent<SlimeController>();
				if (component != null && !component.IsDestroyed && !component.HasSpawned)
				{
					continue;
				}
			}
			Fix fix2 = Vec2.SqrMagnitude(hitBuffer[i].fixTrans.position - vec);
			if (fix2 < fix)
			{
				fix = fix2;
				num2 = i;
			}
		}
		if (num2 != -1)
		{
			extraOffset = Vec2.right * (Fix)1.5 * (Fix.Max(hitBuffer[num2].fixTrans.Scale, Fix.One) - Fix.One);
			heldBoulder = null;
			if (state == MagnetState.prepulling)
			{
				enterPull();
			}
			if (hitBuffer[num2].fixTrans.gameObject.layer != LayerMask.NameToLayer("RigidBodyAffector"))
			{
				playerCol.IgnoreCollider(hitBuffer[num2].fixTrans.GetComponent<IPhysicsCollider>(), PlayerCollision.IgnoreColliderInd.magnet);
			}
			if (hitBuffer[num2].fixTrans.gameObject.layer == LayerMask.NameToLayer("Player"))
			{
				pickedupBounceBall = hitBuffer[num2].fixTrans.GetComponent<BounceBall>();
				if (pickedupBounceBall != null && !pickedupBounceBall.IsDestroyed)
				{
					extraOffset += playerRockExtraOffset;
					heldItem = hitBuffer[num2].fixTrans.GetComponent<BoplBody>();
					heldItemState = HeldItemType.item;
					if (!(heldItem != null) || heldItem.IsDestroyed)
					{
						heldItemState = HeldItemType.nothing;
						return false;
					}
					heldItem.angularVelocity = angVelOnLockedItem;
					body.AddForce(heldItem.velocity / (Fix)35L);
					if (heldItem.magnetGunHolder != null && !heldItem.magnetGunHolder.IsDestroyed)
					{
						heldItem.magnetGunHolder.OnItemWasStolen();
					}
					vec = CurrentFirePoint();
					heldPosition = heldItem.position;
				}
				else
				{
					AbilityMonoBehaviour component2 = hitBuffer[num2].fixTrans.GetComponent<AbilityMonoBehaviour>();
					heldItemSlimeController = component2?.GetSlimeController();
					if ((bool)component2)
					{
						PlayerBody component3 = component2.GetComponent<PlayerBody>();
						Vec2 vec2 = ((component3 != null) ? component3.Velocity : Vec2.zero);
						body.AddForce(vec2 / playerMass);
						AbilityExitInfo info = new AbilityExitInfo
						{
							justlanded = false,
							groundedSpeed = Fix.Zero,
							isGrounded = false,
							isFacingRight = true,
							position = CurrentFirePoint(),
							externalVelocity = Vec2.zero,
							selfImposedVelocity = Vec2.zero,
							currentlyAttachedGround = null,
							lastSprite = null,
							groundedLocalPosition = Fix.Zero
						};
						playerCol.IgnoreCollider(null, PlayerCollision.IgnoreColliderInd.magnet);
						component2.GetComponent<IAbilityComponent>().ExitAbility(info);
					}
					else
					{
						heldItemSlimeController = hitBuffer[num2].fixTrans.GetComponent<SlimeController>();
						body.AddForce(heldItemSlimeController.body.Velocity / playerMass);
					}
					heldPosition = heldItemSlimeController.body.position;
					heldItemSlimeController.MagnetSteal(this);
					heldItemSlimeController.playerPhysics.UnGround();
					heldItemSlimeController.playerPhysics.skipNextUpdate = true;
					heldItemSlimeController.ApplyRagDoll(smallRagdollDuration, Vec2.zero, goFast: false, resetAnimation: true, this);
					heldItemState = HeldItemType.player;
				}
			}
			else if (hitBuffer[num2].fixTrans.gameObject.layer == LayerMask.NameToLayer("RigidBodyAffector"))
			{
				BlackHole component4 = hitBuffer[num2].fixTrans.GetComponent<BlackHole>();
				if (!component4 || component4.IsDestroyed || !(component4.GetMass() > 0L))
				{
					heldItemState = HeldItemType.nothing;
					return false;
				}
				heldItemState = HeldItemType.blackhole;
				heldBlackHole = component4;
				heldBlackHole.magnetGunHolder?.OnItemWasStolen();
				heldBlackHole.magnetGunHolder = this;
				heldBlackHole.Hold(this, 3);
				heldPosition = component4.dCircle.position;
				body.AddForce(component4.dCircle.velocity / playerMass);
			}
			else
			{
				heldItem = hitBuffer[num2].fixTrans.GetComponent<BoplBody>();
				if (hitBuffer[num2].fixTrans.gameObject.layer == LayerMask.NameToLayer("wall") && hitBuffer[num2].fixTrans.CompareTag("boulder"))
				{
					heldBoulder = hitBuffer[num2].fixTrans.GetComponent<Boulder>();
					extraOffset = boulderExtraOffset;
					body.AddForce(heldItem.velocity / (Fix)35L);
				}
				else
				{
					body.AddForce(heldItem.velocity / playerMass);
				}
				if (hitBuffer[num2].fixTrans.gameObject.layer == LayerMask.NameToLayer("spell"))
				{
					heldItemState = HeldItemType.spell;
				}
				else
				{
					heldItemState = HeldItemType.item;
				}
				if (!(heldItem != null) || heldItem.IsDestroyed)
				{
					heldItemState = HeldItemType.nothing;
					return false;
				}
				if (heldItem.magnetGunHolder != null && !heldItem.magnetGunHolder.IsDestroyed)
				{
					heldItem.magnetGunHolder.OnItemWasStolen();
				}
				heldPosition = heldItem.position;
				heldItem.angularVelocity = angVelOnLockedItem;
				if (heldItem.gameObject.layer == LayerMask.NameToLayer("weapon"))
				{
					heldItem.Hold(3L, this, changeSortingLayer: false);
				}
				else
				{
					heldItem.Hold(3L, this);
				}
				StickyRoundedRectangle attachedGround = physics.getAttachedGround();
				if (physics.IsGrounded() && attachedGround != null && heldBoulder != null && !heldBoulder.IsDestroyed)
				{
					heldBoulder.Hold();
					if (attachedGround.HierarchyNumber == heldBoulder.GetComponent<StickyRoundedRectangle>().HierarchyNumber)
					{
						physics.UnGround();
					}
				}
			}
			idleSpark.Play();
			return true;
		}
		heldItemState = HeldItemType.nothing;
		return false;
	}

	public void OnItemWasStolen()
	{
		if (state != MagnetState.exiting)
		{
			enterPause();
		}
	}

	private void SetSpriteFromAnim(SpriteFrame[] anim, SpriteRenderer spriteRen, int ticks)
	{
		int num = 0;
		for (int i = 0; i < anim.Length; i++)
		{
			num += anim[i].frameDuration;
		}
		ticks %= num;
		if (ticks < 0)
		{
			ticks = num + ticks;
		}
		int num2 = 0;
		int num3 = anim[num2].frameDuration;
		while (ticks > 0)
		{
			if (num3 == 0)
			{
				num2++;
				num3 += anim[num2].frameDuration;
			}
			else
			{
				num3--;
				ticks--;
			}
			if (num3 == 0)
			{
				num2++;
				num3 += anim[num2].frameDuration;
			}
		}
		spriteRen.sprite = anim[num2].sprite;
	}

	private void UpdateMagnetBatteryVisual()
	{
		if (state == MagnetState.entering || state == MagnetState.exiting || state == MagnetState.prepulling || state == MagnetState.paused)
		{
			batteryRen.enabled = false;
			magnetRen.enabled = false;
			magnetTOPRen.enabled = false;
			if (idleSpark.isPlaying)
			{
				idleSpark.Stop();
			}
		}
		else if (idleSpark.isStopped || idleSpark.isPaused)
		{
			idleSpark.Play();
		}
		UnityEngine.Color color = spriteRen.color;
		batteryRen.color = color;
		magnetRen.color = color;
		magnetTOPRen.color = color;
		if (state == MagnetState.pulling)
		{
			batteryRen.enabled = true;
			magnetRen.enabled = true;
			magnetTOPRen.enabled = true;
			SpriteFrame[] animation = animData.GetAnimation("magnet");
			SpriteFrame[] animation2 = animData.GetAnimation("battery");
			SetSpriteFromAnim(animation, magnetRen, magnetTicks);
			SetSpriteFromAnim(animation2, batteryRen, batteryTicks);
			SpriteFrame[] animation3 = animData.GetAnimation("magnetTOP");
			SetSpriteFromAnim(animation3, magnetTOPRen, magnetTicks);
		}
		else if (state == MagnetState.locked)
		{
			batteryRen.enabled = true;
			magnetRen.enabled = true;
			magnetTOPRen.enabled = true;
			SpriteFrame[] animation4 = animData.GetAnimation("magnet");
			SpriteFrame[] animation5 = animData.GetAnimation("battery");
			SetSpriteFromAnim(animation4, magnetRen, magnetTicks);
			SetSpriteFromAnim(animation5, batteryRen, batteryTicks);
			SpriteFrame[] animation6 = animData.GetAnimation("magnetTOP");
			SetSpriteFromAnim(animation6, magnetTOPRen, magnetTicks);
		}
		else if (state == MagnetState.paused)
		{
			batteryRen.enabled = true;
			magnetRen.enabled = true;
			magnetTOPRen.enabled = true;
			SpriteFrame[] animation7 = animData.GetAnimation("magnet");
			SpriteFrame[] animation8 = animData.GetAnimation("battery");
			SetSpriteFromAnim(animation7, magnetRen, magnetTicks);
			SetSpriteFromAnim(animation8, batteryRen, batteryTicks);
			SpriteFrame[] animation9 = animData.GetAnimation("magnetTOP");
			SetSpriteFromAnim(animation9, magnetTOPRen, magnetTicks);
		}
	}

	public override void LateUpdateSim(Fix SimDeltaTime)
	{
		nullItemTypeIfDropped();
		if (state != MagnetState.locked)
		{
			return;
		}
		switch (heldItemState)
		{
		case HeldItemType.player:
		{
			if (heldItemSlimeController.playerPhysics.IsGrounded())
			{
				heldItemSlimeController.playerPhysics.UnGround(nullRotation: false, playSoundEffect: false);
				heldItemSlimeController.body.position = CurrentFirePoint();
			}
			RopeBody ropeBody = heldItemSlimeController.body.ropeBody;
			if (ropeBody != null && ropeBody.enabled)
			{
				int num = ((!heldItemSlimeController.body.topAttachment) ? (ropeBody.segmentCount - 1) : 0);
				ropeBody.segment[num] = heldPosition;
			}
			break;
		}
		case HeldItemType.nothing:
		case HeldItemType.item:
		case HeldItemType.blackhole:
		case HeldItemType.spell:
			break;
		}
	}

	private void nullItemTypeIfDropped()
	{
		if (state != MagnetState.locked)
		{
			return;
		}
		switch (heldItemState)
		{
		case HeldItemType.item:
		case HeldItemType.spell:
			if (heldItem == null || heldItem.IsDestroyed || !heldItem.gameObject.activeInHierarchy)
			{
				heldItem = null;
				heldBoulder = null;
				heldItemState = HeldItemType.nothing;
				heldParticle.DelayedStop();
				heldParticle.SetRenderer(null);
				heldParticle.Update();
			}
			break;
		case HeldItemType.player:
			if (heldItemSlimeController == null || heldItemSlimeController.IsDestroyed || !heldItemSlimeController.gameObject.activeInHierarchy)
			{
				heldItemSlimeController = null;
				heldItemState = HeldItemType.nothing;
				heldParticle.DelayedStop();
				heldParticle.SetRenderer(null);
				heldParticle.Update();
			}
			break;
		case HeldItemType.blackhole:
			if (heldBlackHole == null || heldBlackHole.IsDestroyed || !heldBlackHole.gameObject.activeInHierarchy)
			{
				heldBlackHole = null;
				heldItemState = HeldItemType.nothing;
				heldParticle.DelayedStop();
				heldParticle.SetRenderer(null);
				heldParticle.Update();
			}
			break;
		case HeldItemType.nothing:
			break;
		}
	}

	private Fix interpolationWallRaycast(Vec2 origin, Vec2 dir, Fix distance)
	{
		RaycastInformation raycastInformation = DetPhysics.Get().RaycastToClosestRoundedRect(origin, dir, (Fix)1000L);
		Tools.Debug_DrawLine_fu(origin, raycastInformation.nearPos, UnityEngine.Color.red);
		if ((bool)raycastInformation && raycastInformation.nearDist < distance)
		{
			return raycastInformation.nearDist;
		}
		return distance;
	}

	private Vec2 RaycastForWalls(Vec2 dir, Vec2 fp)
	{
		Fix fix = extraOffset.x + FirepointOffset.x;
		Fix fix2 = fix;
		Fix distance = fix2 + (Fix)1000L;
		Vec2 vec = fp - body.right * fix2;
		Tools.Debug_DrawPos_fu(vec, UnityEngine.Color.yellow);
		Vec2 vec2 = body.fixtrans.Scale * raycastOffset;
		Vec2 vec3 = vec + dir * vec2.x + Vec2.MulByI(dir) * vec2.y;
		Vec2 vec4 = vec + dir * vec2.x + Vec2.MulByNegI(dir) * vec2.y;
		DetPhysics detPhysics = DetPhysics.Get();
		RaycastInformation raycastInformation = detPhysics.RaycastToClosestRoundedRect(body.position, dir, distance);
		RaycastInformation raycastInformation2 = detPhysics.RaycastToClosestRoundedRect(vec3, dir, distance);
		RaycastInformation raycastInformation3 = detPhysics.RaycastToClosestRoundedRect(vec4, dir, distance);
		Tools.Debug_DrawLine_fu(vec, raycastInformation.nearPos, UnityEngine.Color.red);
		Tools.Debug_DrawLine_fu(vec3, raycastInformation2.nearPos, UnityEngine.Color.green);
		Tools.Debug_DrawLine_fu(vec4, raycastInformation3.nearPos, UnityEngine.Color.blue);
		if ((bool)raycastInformation2)
		{
			raycastInformation2.nearDist += vec2.x;
		}
		if ((bool)raycastInformation3)
		{
			raycastInformation3.nearDist += vec2.x;
		}
		if ((bool)raycastInformation)
		{
			fix2 = raycastInformation.nearDist;
		}
		if ((bool)raycastInformation2 && (bool)raycastInformation3)
		{
			fix2 = Fix.Min(Fix.Max(raycastInformation2.nearDist, raycastInformation3.nearDist), raycastInformation.nearDist);
		}
		if (fix2 < fix)
		{
			fp = vec + fix2 * inputVector;
		}
		return fp;
	}

	private void UpdateHeldPosition_old(Vec2 firepoint)
	{
		heldPosition = Vec2.Lerp(heldPosition, firepoint, heldPosLerpFactor01);
		heldItem.position = heldPosition;
	}

	private void UpdateHeldPosition(Vec2 firepoint, bool raycastWalls = true)
	{
		Vec2 v = heldPosition - body.position;
		Fix a = Vec2.Magnitude(v);
		Vec2 v2 = Vec2.NormalizedSafe(v);
		Vec2 v3 = firepoint - body.position;
		Fix b = Vec2.Magnitude(v3);
		Vec2 u = Vec2.NormalizedSafe(v3);
		Fix fix = Fix.Lerp(a, b, heldPosLerpFactor01);
		Vec2 vec = Vec2.Slerp(v2, u, heldPosLerpFactor01);
		if (raycastWalls)
		{
			if (heldItemState == HeldItemType.item)
			{
				heldItem?.gameObject.SetActive(value: false);
				fix = interpolationWallRaycast(body.position, vec, fix);
				heldItem?.gameObject.SetActive(value: true);
			}
			else if (heldItemState != HeldItemType.spell)
			{
				fix = interpolationWallRaycast(body.position, vec, fix);
			}
		}
		heldPosition = body.position + vec * fix;
	}

	private void Update()
	{
		if (multiplierLastFrame > 4L && state == MagnetState.pulling)
		{
			AudioManager.Get().PlayOrContinueLoop("drill_loop");
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		Vec2 vec = player.AimVector();
		Fix fix = Vec2.Magnitude(vec);
		if (fix > Constants.DEADZONE)
		{
			inputVector = vec / fix;
		}
		ParticleSystem.MainModule main = idleSpark.main;
		_ = main.startColor;
		UnityEngine.Color color = main.startColor.color;
		color.a = spriteRen.color.a;
		main.startColor = color;
		if (!base.gameObject.activeInHierarchy)
		{
			return;
		}
		timeSpentPulling += GameTime.FixedDeltaTime(player.Id, simDeltaTime);
		if ((state == MagnetState.pulling || state == MagnetState.prepulling || state == MagnetState.locked) && timeSpentPulling > maxPullDuration)
		{
			enterPause();
		}
		bool flag = GameTime.IsTimeStoppedFor(playerInfo.playerId);
		Vec2 vec2 = CurrentFirePoint();
		if (!flag && (state == MagnetState.pulling || state == MagnetState.prepulling))
		{
			TryPullItems();
			if (TryPickupNearbyItems())
			{
				state = MagnetState.locked;
				timeSpentPulling = Fix.Zero;
				AudioManager.Get().Play("magnetPickup");
				AudioManager.Get().Play("beamSparks1", 0.1f);
			}
		}
		vec2 = CurrentFirePoint();
		if (state == MagnetState.locked)
		{
			nullItemTypeIfDropped();
			switch (heldItemState)
			{
			case HeldItemType.nothing:
				enterPause();
				break;
			case HeldItemType.spell:
				if (Vec2.SqrMagnitude(vec2 - heldItem.position) > maxLockDist)
				{
					heldItem = null;
					state = MagnetState.pulling;
					return;
				}
				UpdateHeldPosition(vec2);
				heldItem.position = heldPosition;
				body.externalVelocity += heldItem.velocity / (Fix)10L;
				heldItem.velocity = Vec2.zero;
				heldItem.Hold(2L, this);
				heldBoulder?.Hold();
				break;
			case HeldItemType.item:
				heldItem?.gameObject.SetActive(value: false);
				vec2 = RaycastForWalls(inputVector, vec2);
				heldItem?.gameObject.SetActive(value: true);
				if (Vec2.SqrMagnitude(vec2 - heldItem.position) > maxLockDist)
				{
					heldItem = null;
					state = MagnetState.pulling;
					return;
				}
				UpdateHeldPosition(vec2);
				heldItem.position = heldPosition;
				body.externalVelocity += heldItem.velocity / (Fix)10L;
				heldItem.velocity = Vec2.zero;
				if ((bool)pickedupBounceBall && !pickedupBounceBall.IsDestroyed)
				{
					pickedupBounceBall.timeSinceActivation -= GameTime.FixedDeltaTime(playerInfo.playerId, simDeltaTime);
				}
				else
				{
					Grenade component = heldItem.GetComponent<Grenade>();
					if ((bool)component)
					{
						component.selfDestructDelay += simDeltaTime * GameTime.PlayerTimeScale;
					}
				}
				heldItem.Hold(2L, this);
				heldBoulder?.Hold();
				DetPhysics.Get().MoveObjectOutOfWalls(heldItem.GetComponent<IPhysicsCollider>());
				break;
			case HeldItemType.player:
				vec2 = RaycastForWalls(inputVector, vec2);
				UpdateHeldPosition(vec2);
				heldItemSlimeController.body.position = heldPosition;
				heldItemSlimeController.ApplyRagDoll(smallRagdollDuration, Vec2.zero, goFast: false, resetAnimation: false);
				heldItemSlimeController.playerPhysics.skipNextUpdate = true;
				break;
			case HeldItemType.blackhole:
				vec2 = CurrentFirePoint();
				if (heldBlackHole.GetMass() > 0L)
				{
					UpdateHeldPosition(vec2, raycastWalls: false);
					heldBlackHole.dCircle.position = heldPosition;
				}
				else
				{
					enterPull();
				}
				heldBlackHole?.Hold(this, 3);
				break;
			}
		}
		if (state != MagnetState.locked)
		{
			playerCol.IgnoreCollider(null, PlayerCollision.IgnoreColliderInd.magnet);
		}
		if (!flag && !player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012) && !hasFired)
		{
			if (heldItemState == HeldItemType.nothing || state != MagnetState.locked)
			{
				AudioManager.Get().Play("magnetCancel");
			}
			else
			{
				AudioManager.Get().Play("magnetShoot");
				AudioManager.Get().PlayRandomWithPrefix("beamSparks");
			}
			Fire(inputVector);
		}
		SpriteRenderer heldRenderer = null;
		if (state == MagnetState.locked || state == MagnetState.exiting)
		{
			switch (heldItemState)
			{
			case HeldItemType.item:
				heldRenderer = heldItem?.GetComponent<SpriteRenderer>();
				break;
			case HeldItemType.spell:
				heldRenderer = null;
				break;
			case HeldItemType.player:
				heldRenderer = heldItemSlimeController?.GetComponentInChildren<SpriteRenderer>();
				break;
			case HeldItemType.blackhole:
				heldRenderer = heldBlackHole?.GetComponent<SpriteRenderer>();
				break;
			}
		}
		if (flag)
		{
			return;
		}
		updateParticle(heldRenderer);
		if (state == MagnetState.pulling)
		{
			Fix fix2 = pullStrMultiplierCurve.Evaluate(timeSpentPulling / maxPullDuration);
			if (multiplierLastFrame <= 3L && fix2 > 3L)
			{
				AudioManager.Get().Play("drill_start");
			}
			multiplierLastFrame = fix2;
			if (fix2 > 3L)
			{
				fix2 *= (Fix)2L;
			}
			magnetTicks -= (int)(long)Fix.Ceiling(fix2);
			batteryTicks += (int)(long)Fix.Ceiling(fix2);
		}
		else if (state == MagnetState.locked)
		{
			batteryTicks -= 4;
		}
		else
		{
			_ = state;
			_ = 4;
		}
		UpdateMagnetBatteryVisual();
		UnityEngine.Debug.DrawRay((Vector3)CurrentFirePoint(), ((Vector3)inputVector).normalized * 20f);
		if (physics.IsGrounded() && (Vec2.SqrMagnitude(body.selfImposedVelocity) > (Fix)1E-06f || physics.getAttachedGround() == null || !physics.getAttachedGround().isActiveAndEnabled))
		{
			physics.gravity_modifier = (Fix)0.03f;
			physics.UnGround(nullRotation: true, playSoundEffect: false);
		}
		if (!physics.IsGrounded())
		{
			physics.AddGravityFactor();
			bool flag2 = state == MagnetState.locked && heldBoulder != null && !heldBoulder.IsDestroyed;
			if (flag2)
			{
				heldBoulder.hitbox.enabled = false;
			}
			bool num = physics.VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime);
			if (flag2)
			{
				heldBoulder.hitbox.enabled = true;
			}
			if (num && hasFired)
			{
				AbilityExitInfo info = default(AbilityExitInfo);
				body.rotation = (Fix)0L;
				info.justlanded = true;
				info.groundedSpeed = physics.groundedSpeed;
				info.isGrounded = physics.IsGrounded();
				info.isFacingRight = inputVector.x >= 0L;
				info.position = body.position;
				info.externalVelocity = body.externalVelocity;
				info.selfImposedVelocity = body.selfImposedVelocity;
				info.currentlyAttachedGround = physics.getAttachedGround();
				info.lastSprite = spriteRen.sprite;
				info.groundedLocalPosition = physics.LocalPlatformPos;
				info.radius = physics.radius;
				GetComponent<PlayerCollision>().IgnoreCollider(null, PlayerCollision.IgnoreColliderInd.magnet);
				ability.ExitAbility(info);
			}
		}
		if (physics.IsGrounded())
		{
			physics.Move(Vec2.zero, simDeltaTime);
		}
		if (!hasFired)
		{
			Vec2 up = new Vec2(-inputVector.y, inputVector.x);
			body.up = up;
			if (Vec2.Magnitude(body.selfImposedVelocity) > maxSlowMoSpeed)
			{
				body.selfImposedVelocity = Vec2.Normalized(body.selfImposedVelocity) * maxSlowMoSpeed;
			}
		}
		else
		{
			Vec2 selfImposedVelocity = body.selfImposedVelocity;
			Fix inputHorz = player.HorizontalAxis();
			physics.AirealMovement(inputHorz, simDeltaTime);
			Vec2 selfImposedVelocity2 = body.selfImposedVelocity;
			body.selfImposedVelocity = Vec2.Lerp(selfImposedVelocity, selfImposedVelocity2, airealControlBlend);
		}
		if (Vec2.Magnitude(body.selfImposedVelocity) > physics.Speed)
		{
			body.selfImposedVelocity = Vec2.Normalized(body.selfImposedVelocity) * physics.Speed;
		}
		if (physics.IsGrounded())
		{
			physics.DropPlatformTest();
		}
	}
}
[RequireComponent(typeof(Item))]
public class Mine : MonoUpdatable, ICollisionCallback
{
	public enum MineState
	{
		off,
		armed,
		chasing,
		anticipation
	}

	private MineState state;

	public SpriteRenderer Light;

	public Fix HoverStr = (Fix)1L;

	public Fix HoverPeriod = (Fix)1L;

	public Fix TimeBeforeArmed = (Fix)2L;

	public Fix chaseTime = Fix.Zero;

	private BoplBody body;

	private IPhysicsCollider physicsCollider;

	private Item item;

	private SpriteRenderer spriteRen;

	private Fix randomOffset;

	public LayerMask Igniters;

	public LayerMask ScansFor;

	private Fix timeSinceAnticipation = Fix.Zero;

	private Fix timeSinceSpawned;

	private Vector2 originalLightScale;

	public float lightPeriod = 1f;

	private float maxAlpha;

	[SerializeField]
	private AnimationCurve AnimateArmedFlash;

	public float chasingBlinkSpeed = 0.25f;

	public Fix chaseStrength = Fix.One;

	private Vec2 prevChaseDir;

	[SerializeField]
	private Fix scanRadius = (Fix)3f;

	private PhysicsParent[] scanHitsBuffer = new PhysicsParent[4];

	public Fix shakeForce;

	public Fix anticipationDuration = Fix.One;

	public Explosion Explosion;

	public string SoundToPlayOnDetonation;

	private Vec2 prevRandVector;

	private Vec2 prevVelocityChange;

	public override void Init()
	{
		timeSinceSpawned = (Fix)0L;
		randomOffset = (Fix)1L - Updater.RandomFix((Fix)0L, (Fix)2L) * HoverPeriod;
		prevChaseDir = Vec2.right;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		body = GetComponent<BoplBody>();
		spriteRen = GetComponent<SpriteRenderer>();
		physicsCollider = GetComponent<IPhysicsCollider>();
		physicsCollider.RegisterCollisionCallback(this);
		item = GetComponent<Item>();
		UnityEngine.Color color = Light.color;
		color.a = 0.7843137f;
		Light.color = color;
		maxAlpha = Light.color.a;
		originalLightScale = new Vector2(0.1708333f, 0.1708333f);
		state = MineState.off;
	}

	private void Update()
	{
		if (state == MineState.chasing || state == MineState.anticipation)
		{
			float num = (float)timeSinceSpawned % chasingBlinkSpeed;
			Light.transform.localScale = originalLightScale + Vector2.one * AnimateArmedFlash.Evaluate(num) * 0.25f;
			Light.color = new UnityEngine.Color(Light.color.r, Light.color.g, Light.color.b, 0.25f * (2f + num) * maxAlpha);
			return;
		}
		if (timeSinceSpawned < TimeBeforeArmed)
		{
			Light.color = new UnityEngine.Color(Light.color.r, Light.color.g, Light.color.b, 0f);
			return;
		}
		float num2 = Mathf.Sin((float)timeSinceSpawned * lightPeriod + (float)randomOffset);
		num2 = (1f + num2) * 0.25f + 0.4f;
		if (timeSinceSpawned - TimeBeforeArmed > 0L && timeSinceSpawned - TimeBeforeArmed < 1L)
		{
			num2 = Mathf.Max(Mathf.Lerp(1f, 0f, (float)timeSinceSpawned - (float)TimeBeforeArmed), num2);
			Light.transform.localScale = originalLightScale + Vector2.one * AnimateArmedFlash.Evaluate((float)timeSinceSpawned - (float)TimeBeforeArmed) * 0.25f;
		}
		Light.color = new UnityEngine.Color(Light.color.r, Light.color.g, Light.color.b, num2 * maxAlpha);
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}

	private FixTransform ScanForPlayers()
	{
		int num = 0;
		num = DetPhysics.Get().CircleCastAll(body.position, scanRadius * physicsCollider.Scale, ScansFor, ref scanHitsBuffer);
		int num2 = 0;
		while (num2 < num)
		{
			IPlayerIdHolder component = scanHitsBuffer[num2].fixTrans.GetComponent<IPlayerIdHolder>();
			if (component != null)
			{
				Player player = PlayerHandler.Get().GetPlayer(component.GetPlayerId());
				Player player2 = PlayerHandler.Get().GetPlayer(item.OwnerId);
				if (player == null || player.isInvisible || component.GetPlayerId() == player2.Id || player2.Team == player.Team)
				{
					num2++;
					continue;
				}
			}
			return scanHitsBuffer[num2].fixTrans;
		}
		return null;
	}

	public override void LateUpdateSim(Fix simDeltaTime)
	{
		Player player = PlayerHandler.Get().GetPlayer(item.OwnerId);
		if (GameTime.IsTimeStopped() && (player == null || !player.isProtectedFromTimeStop))
		{
			return;
		}
		timeSinceSpawned += simDeltaTime;
		Fix fix = Fix.Cos(timeSinceSpawned * HoverPeriod + randomOffset);
		body.AddForce(new Vec2(Fix.Zero, fix * HoverStr));
		switch (state)
		{
		case MineState.off:
			if (timeSinceSpawned >= TimeBeforeArmed)
			{
				AudioManager.Get().Play("mineArmed");
				state = MineState.armed;
			}
			break;
		case MineState.armed:
			if (!GameTime.IsTimeStopped() && !body.IsBeingHeld())
			{
				FixTransform fixTransform2 = ScanForPlayers();
				if (fixTransform2 != null)
				{
					state = MineState.chasing;
					Vec2 v2 = fixTransform2.position - body.position;
					prevChaseDir = Vec2.NormalizedSafe(v2);
					AudioManager.Get().Play("mineArmedDouble");
				}
			}
			break;
		case MineState.chasing:
		{
			if (GameTime.IsTimeStopped() || body.IsBeingHeld())
			{
				break;
			}
			timeSinceAnticipation += GameTime.FixedDeltaTime(item.OwnerId, simDeltaTime);
			if (timeSinceAnticipation > chaseTime)
			{
				timeSinceAnticipation = Fix.Zero;
				state = MineState.anticipation;
				AudioManager.Get().Play("mineAnticipation");
			}
			FixTransform fixTransform = ScanForPlayers();
			if (!(fixTransform == null) && !fixTransform.IsDestroyed)
			{
				Vec2 v = fixTransform.position - body.position;
				if (Vec2.SqrMagnitude(v) < (Fix)4L)
				{
					Detonate();
					break;
				}
				prevChaseDir = Vec2.NormalizedSafe(v);
			}
			body.AddForce(prevChaseDir * chaseStrength);
			break;
		}
		case MineState.anticipation:
			if (!GameTime.IsTimeStopped())
			{
				timeSinceAnticipation += GameTime.FixedDeltaTime(item.OwnerId, simDeltaTime);
				if (timeSinceAnticipation >= anticipationDuration)
				{
					Detonate();
				}
				else
				{
					Anticipation(timeSinceAnticipation);
				}
			}
			break;
		}
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (((1 << collision.layer) & Igniters.value) != 0 && state != MineState.anticipation && state != MineState.off && (collision.layer != LayerMask.NameToLayer("LethalTerrain") || collision.colliderPP.fixTrans.CompareTag("ChainLightning")) && (!body.IsBeingHeld() || body.magnetGunHolder.hurtbox.HierarchyNumber != collision.colliderPP.hierarchyNumber))
		{
			timeSinceAnticipation = anticipationDuration * (Fix)0.8;
			state = MineState.anticipation;
			AudioManager.Get().Play("mineAnticipation");
		}
	}

	public void SetMaterial(Material playerMaterial)
	{
		spriteRen.material = playerMaterial;
		float a = Light.color.a;
		UnityEngine.Color color = playerMaterial.GetColor("_ShadowColor");
		if (playerMaterial.name.StartsWith("blackSlime"))
		{
			color.r = 1f;
			color.g = 1f;
			color.b = 1f;
		}
		color.a = a;
		Light.color = color;
	}

	private void Anticipation(Fix timePassed)
	{
		Shake(Fix.Lerp(Fix.Zero, shakeForce, timePassed / anticipationDuration));
	}

	public void Detonate()
	{
		Explosion explosion = FixTransform.InstantiateFixed(Explosion, body.position);
		explosion.GetComponent<IPhysicsCollider>().Scale = physicsCollider.Scale;
		explosion.PlayerOwnerId = item.OwnerId;
		if (SoundToPlayOnDetonation != null)
		{
			AudioManager.Get().Play(SoundToPlayOnDetonation);
		}
		Updater.DestroyFix(base.gameObject);
	}

	private void Shake(Fix shake)
	{
		body.position -= prevVelocityChange;
		Vec2 vec = Updater.RandomInsideUnitCircle() * shake * (Fix)3L;
		Vec2 vec2 = vec - prevRandVector;
		body.position += vec2;
		prevRandVector = vec;
		prevVelocityChange = vec2;
	}
}
