public class PlaceRocketEngine : MonoBehaviour, IPlaceObject
{
	[SerializeField]
	private Vec2 plantOffset;

	[SerializeField]
	private GameObject plantablePrefab;

	[SerializeField]
	private Fix castForce = (Fix)10L;

	[SerializeField]
	private int bufferSize = 2;

	private RingBuffer<RocketEngine> plantBuffer;

	private PlayerBody body;

	private FixTransform fixTrans;

	private void Awake()
	{
		plantBuffer = new RingBuffer<RocketEngine>(bufferSize);
		body = GetComponent<PlayerBody>();
		fixTrans = GetComponent<FixTransform>();
	}

	public AbilityExitInfo ModifyExitInfo(AbilityExitInfo info)
	{
		return info;
	}

	public GameObject Place(int playerId, StickyRoundedRectangle ground)
	{
		Vec2 vec = plantOffset;
		Vec2 closestPoint = ground.GetClosestPoint(body.position + body.right * (Fix)((!(base.transform.localScale.x < 0f)) ? 1 : (-1)) * vec.x);
		Fix localPlayerPos = ground.LocalPlayerPosFromPos(closestPoint, Fix.Zero);
		closestPoint = ground.PositionFromLocalPlayerPos(localPlayerPos, Fix.Zero);
		Vec2 vec2 = ground.currentNormal(closestPoint);
		closestPoint += vec2 * vec.y;
		GameObject obj = FixTransform.InstantiateFixed(plantablePrefab, closestPoint);
		obj.transform.SetParent(ground.transform);
		obj.GetComponent<IPhysicsCollider>();
		FixTransform component = obj.GetComponent<FixTransform>();
		RocketEngine component2 = obj.GetComponent<RocketEngine>();
		obj.transform.localScale = new Vector3((float)body.fixtrans.Scale, (float)body.fixtrans.Scale, 1f);
		component.position = closestPoint;
		component.up = vec2;
		component2.RocketEngineInit(ground, vec.y, closestPoint, body.fixtrans.Scale, playerId);
		ground.GetGroundBody().AddForceAtPosition(-vec2 * castForce, body.position);
		plantBuffer.Add(component2);
		return obj.gameObject;
	}
}
public class PlaceSparkNode : MonoUpdatable, IPlaceObject
{
	[SerializeField]
	private Vec2 plantOffset;

	[SerializeField]
	private GameObject plantablePrefab;

	[SerializeField]
	private Fix castForce = (Fix)10L;

	private RingBuffer<SimpleSparkNode> plantBuffer;

	private PlayerBody body;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		plantBuffer = new RingBuffer<SimpleSparkNode>(2);
		body = GetComponent<PlayerBody>();
	}

	public AbilityExitInfo ModifyExitInfo(AbilityExitInfo info)
	{
		return info;
	}

	public GameObject Place(int playerId, StickyRoundedRectangle ground)
	{
		Vec2 vec = plantOffset;
		Vec2 closestPoint = ground.GetClosestPoint(body.position + body.right * (Fix)((!(base.transform.localScale.x < 0f)) ? 1 : (-1)) * vec.x);
		Fix fix = ground.LocalPlayerPosFromPos(closestPoint, Fix.Zero);
		closestPoint = ground.PositionFromLocalPlayerPos(fix, Fix.Zero);
		Vec2 vec2 = ground.currentNormal(closestPoint);
		closestPoint += vec2 * vec.y;
		GameObject gameObject = FixTransform.InstantiateFixed(plantablePrefab, closestPoint);
		gameObject.transform.SetParent(ground.transform);
		gameObject.GetComponent<IPhysicsCollider>();
		FixTransform component = gameObject.GetComponent<FixTransform>();
		SimpleSparkNode component2 = gameObject.GetComponent<SimpleSparkNode>();
		gameObject.transform.localScale = new Vector3((float)body.fixtrans.Scale, (float)body.fixtrans.Scale, 1f);
		component.position = closestPoint;
		component.up = vec2;
		plantBuffer.Add(component2);
		SimpleSparkNode childNode = null;
