public class PlantObjectOnPlatform : MonoUpdatable, IAbilityComponent
{
	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private DPhysicsBox hitBox;

	private Ability ability;

	private PlayerPhysics playerPhysics;

	private PlayerInfo playerInfo;

	private IPlaceObject placeObject;

	[SerializeField]
	private AnimationData animData;

	[SerializeField]
	private SpriteRenderer dummyTeslaCoil;

	[SerializeField]
	private Vector2[] DummyPositions;

	[SerializeField]
	private float[] DummyRotations;

	[SerializeField]
	private int ShowDummyAtFrame;

	[SerializeField]
	private Vector2 DummyOffset;

	[SerializeField]
	private GameObject ParticlePrefab;

	[SerializeField]
	private Vec2 ParticlePlantOffset;

	private ParticleSystem OnPlaceParticle;

	private GameObject OnPlaceParticleObject;

	private bool playDummyAnimation;

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		hitBox = GetComponent<DPhysicsBox>();
		ability = GetComponent<Ability>();
		playerPhysics = GetComponent<PlayerPhysics>();
		placeObject = GetComponent<IPlaceObject>();
		OnPlaceParticleObject = UnityEngine.Object.Instantiate(ParticlePrefab, base.transform.position, Quaternion.identity);
		OnPlaceParticle = OnPlaceParticleObject.GetComponentInChildren<ParticleSystem>();
	}

	public override void Init()
	{
	}

	public void OnEnterAbility()
	{
		spriteRen.enabled = true;
		playerInfo = ability.GetPlayerInfo();
		spriteRen.material = playerInfo.playerMaterial;
		body.rotation = playerInfo.rotation;
		animator.beginAnimThenDoAction(animData.GetAnimation("cast"), PlantObject);
		playDummyAnimation = true;
		playerPhysics.SyncPhysicsTo(playerInfo);
		hitBox.UpdatePhysicsPositions();
		body.position = playerInfo.position;
		dummyTeslaCoil.gameObject.SetActive(value: false);
		int num = ((!playerInfo.isFacingRight) ? 1 : (-1));
		base.transform.localScale = new Vector3(num, base.transform.localScale.y, base.transform.localScale.z);
	}

	private void PlantObject()
	{
		StickyRoundedRectangle attachedGround = playerPhysics.getAttachedGround();
		if (attachedGround == null || attachedGround.IsDestroyed || !attachedGround.ThisGameObject().activeInHierarchy)
		{
			ExitAbility();
			return;
		}
		GameObject gameObject = placeObject.Place(playerInfo.playerId, attachedGround);
		OnPlaceParticleObject.transform.position = gameObject.transform.position + gameObject.transform.rotation * new Vector3(0f, (float)ParticlePlantOffset.y, 0f);
		OnPlaceParticleObject.transform.rotation = gameObject.transform.rotation;
		OnPlaceParticle?.Play();
		playDummyAnimation = false;
		dummyTeslaCoil.gameObject.SetActive(value: false);
		AudioManager.Get().Play("plantObjectOnPlatform");
		animator.beginAnimThenDoAction(animData.GetAnimation("recover"), delegate
		{
			ExitAbility();
		});
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		body.rotation = Fix.Zero;
		Vec2 inputVector = Vec2.NormalizedSafe(PlayerHandler.Get().GetPlayer(playerInfo.playerId).InputVector());
		Fix value = playerPhysics.InputGroundAlignment(inputVector);
		if (Fix.Abs(value) >= Constants.GROUNDALIGNMENTDEADZONE && (float)Fix.Sign2(value) * base.transform.localScale.x >= 0f)
		{
			exitInfo.enterTurn = true;
		}
		exitInfo.groundedSpeed = Fix.Zero;
		exitInfo.isGrounded = playerPhysics.IsGrounded();
		exitInfo.isFacingRight = playerInfo.isFacingRight;
		exitInfo.radius = playerPhysics.radius;
		if (playerPhysics.IsGrounded())
		{
			playerPhysics.getAttachedGround().currentNormal(body);
			exitInfo.position = body.position;
			exitInfo.currentlyAttachedGround = playerPhysics.getAttachedGround();
			exitInfo.groundedLocalPosition = playerPhysics.LocalPlatformPos;
		}
		else
		{
			exitInfo.position = body.position;
		}
		exitInfo.selfImposedVelocity = Vec2.zero;
		exitInfo.externalVelocity = Vec2.zero;
		exitInfo.lastSprite = spriteRen.sprite;
		exitInfo = placeObject.ModifyExitInfo(exitInfo);
		ability.ExitAbility(exitInfo);
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	private void OnDrawGizmosSelected()
	{
		for (int i = 0; i < DummyPositions.Length; i++)
		{
			if (DummyRotations.Length <= i)
			{
				Gizmos.DrawRay((Vector2)body.position + DummyPositions[i], Vector2.up);
			}
			else
			{
				Gizmos.DrawRay((Vector2)base.transform.position + DummyPositions[i], new Vector2(Mathf.Cos(MathF.PI / 2f + MathF.PI / 180f * DummyRotations[i]), Mathf.Sin(MathF.PI / 2f + MathF.PI / 180f * DummyRotations[i])));
			}
		}
	}

	private void LateUpdate()
	{
		if (!playDummyAnimation)
		{
			return;
		}
		int num = animator.getNumberOfPassedSprites() - 1;
		if (num - ShowDummyAtFrame >= DummyPositions.Length)
		{
			dummyTeslaCoil.gameObject.SetActive(value: false);
			playDummyAnimation = false;
			return;
		}
		if (num >= ShowDummyAtFrame && num < DummyPositions.Length)
		{
			dummyTeslaCoil.gameObject.SetActive(value: true);
		}
		else
		{
			dummyTeslaCoil.gameObject.SetActive(value: false);
		}
		if (dummyTeslaCoil.gameObject.activeSelf)
		{
			dummyTeslaCoil.transform.localPosition = DummyPositions[num - ShowDummyAtFrame] + DummyOffset;
			dummyTeslaCoil.transform.rotation = base.transform.rotation * Quaternion.Euler(0f, 0f, Mathf.Sign(base.transform.localScale.x) * DummyRotations[num - ShowDummyAtFrame]);
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (playerPhysics.IsGrounded())
		{
			playerPhysics.Move(Vec2.zero, simDeltaTime);
		}
	}
}
[RequireComponent(typeof(Ability))]
public class PlatformTransform : MonoUpdatable, IAbilityComponent
{
	public enum State
	{
		Rotation,
		Size,
		Exit,
		Anticipation
	}

	private StickyRoundedRectangle StickyRect;

	private ResizablePlatform platform;

	private AnimateVelocity animVel;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private SpriteAnimator spriteAnim;

	private State state;

	private Vec2 inputVector = Vec2.up;

	private PlayerInfo playerInfo;

	private Player player;

	public StickyRoundedRectangle platformPrefab;

	public AnimationCurveFixed EjectionCurve01;

	public AnimationCurveFixed EnterScaleAnimation;

	public FixTransform CursorPrefab;

	private SpriteRenderer cursorRenderer;

	private FixTransform cursorTransform;

	private FixTransform fixTrans;

	private DPhysicsCircle hurtBox;

	private PlayerCollision playerCol;

	public RopeAttachment ropeAttachmentPrefab;

	private ResizablePlatform[] srrBuffer = new ResizablePlatform[1];

	private bool ButtonWasDown;

	private Fix timePassed;

	private Fix exitTime;

	public Fix TimeInExit = (Fix)0.3f;

	public Fix SizeChangeSpeed = Fix.One;

	public Fix MaxSize = (Fix)10L;

	public Fix MinSize = Fix.One;

	public Fix rotationSpeed = (Fix)10f;

	public Fix maxArea = (Fix)20L;

	public AnimationData animData;

	public Fix maxSizeTime;

	public static Fix cursorSensitivity = (Fix)25L;

	private bool hasReleased;

	private bool expandingWidth;

	private Vec2 activeCorner01;

	private Vec2[] aimVectorBuffer = new Vec2[256];

	public int bufferSize = 8;

	public Fix faceHeight = (Fix)0.3f;

	public Fix EjectionOffset = (Fix)2f;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		spriteAnim = GetComponent<SpriteAnimator>();
		hurtBox = GetComponent<DPhysicsCircle>();
		playerCol = GetComponent<PlayerCollision>();
		fixTrans = GetComponent<FixTransform>();
	}

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		body.rotation = (Fix)0L;
		ButtonWasDown = true;
		fixTrans.position = playerInfo.position;
		hurtBox.UpdatePhysicsPositions();
		state = State.Anticipation;
		timePassed = (Fix)0L;
		hasReleased = false;
		expandingWidth = true;
		hurtBox.enabled = true;
		activeCorner01 = new Vec2((Fix)1L, (Fix)1L);
		spriteAnim.beginAnimThenDoAction(animData.GetAnimation("Anticipation"), CreatePlatform);
		AudioManager.Get().Play("transform1");
		player.InPlatformTransform = true;
		player.CustomAimAbilityPosition = fixTrans.position;
	}

	private void CreatePlatform()
	{
		AudioManager.Get().Play("transform2");
		hurtBox.enabled = false;
		state = State.Rotation;
		playerCol.isSquishable = false;
		if (cursorRenderer == null)
		{
			cursorTransform = FixTransform.InstantiateFixed(CursorPrefab, fixTrans.position);
			cursorRenderer = cursorTransform.GetComponent<SpriteRenderer>();
		}
		else
		{
			cursorRenderer.enabled = true;
		}
		cursorRenderer.enabled = false;
		cursorRenderer.material = playerInfo.playerMaterial;
		StickyRect = FixTransform.InstantiateFixed(platformPrefab, fixTrans.position);
		StickyRect.rr.Scale = fixTrans.Scale;
		platform = StickyRect.GetComponent<ResizablePlatform>();
		AddPlatformToBuffer(platform);
		platform.GetComponent<DPhysicsRoundedRect>().ManualInit();
		StickyRect.GetComponent<SpriteRenderer>().color = playerInfo.playerMaterial.GetColor("_ShadowColor");
		animVel = StickyRect.GetComponent<AnimateVelocity>();
		spriteAnim.beginAnimThenDoAction(animData.GetAnimation("Enter"), EnterSize);
		fixTrans.position = StickyRect.GetGroundBody().position;
		Vec2 vec = StickyRect.rr.CalcExtents();
		ResizePlatform(vec.x, vec.y, StickyRect.rr.radius);
		if (GameSessionHandler.SuddenDeathInProgress)
		{
			animVel.ActivateSuddenDeath(activate: true, GameSessionHandler.SuddenDeathTimeStamp);
		}
		cursorTransform.position = fixTrans.position + Vec2.up * StickyRect.rr.radius;
		if (body.ropeBody != null && body.ropeBody.enabled)
		{
			Vec2 closestPoint = StickyRect.GetClosestPoint(StickyRect.GetGroundBody().position - StickyRect.GetGroundBody().up * (Fix)10L);
			RopeAttachment ropeAttachment = FixTransform.InstantiateFixed(ropeAttachmentPrefab, closestPoint);
			if (Constants.leveltype == LevelType.grass)
			{
				ropeAttachment.GetComponent<SpriteRenderer>().color = UnityEngine.Color.black;
			}
			else
			{
				ropeAttachment.GetComponent<SpriteRenderer>().color = UnityEngine.Color.white;
			}
			ropeAttachment.AttachToPlatform(closestPoint, StickyRect, body.ropeBody, body.topAttachment);
			body.EnterAbilityClearRope();
		}
	}

	private void ResizePlatform(Fix newWidth, Fix newHeight, Fix newRadius)
	{
		platform.ResizePlatform(newHeight, newWidth, newRadius);
	}

	private void AddPlatformToBuffer(ResizablePlatform platform)
	{
		for (int i = 0; i < srrBuffer.Length; i++)
		{
			if (srrBuffer[i] == null)
			{
				srrBuffer[i] = platform;
				return;
			}
		}
		_ = srrBuffer[0];
		srrBuffer[0].RemovePlatform();
		for (int j = 0; j < srrBuffer.Length - 1; j++)
		{
			srrBuffer[j] = srrBuffer[j + 1];
		}
		srrBuffer[srrBuffer.Length - 1] = platform;
	}

	private void EnterSize()
	{
		cursorRenderer.enabled = true;
		state = State.Size;
		spriteAnim.beginAnimation(animData.GetAnimation("WidthLoop"));
	}

	public static Vec2 EstimateCursorPosition(Vec2 currentPos, Vec2 aimVector)
	{
		return currentPos + aimVector * cursorSensitivity * GameTime.FixedTimeStep;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		Fix fix = GameTime.FixedDeltaTime(player.Id, simDeltaTime);
		inputVector = player.AimVector();
		if (cursorTransform != null)
		{
			player.CustomAimAbilityPosition = cursorTransform.position;
		}
		else
		{
			player.CustomAimAbilityPosition = fixTrans.position;
		}
		if (state == State.Anticipation)
		{
			inputVector = player.AimVector();
			if (!(ButtonWasDown = player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012)) && !hasReleased)
			{
				hasReleased = true;
			}
			return;
		}
		if (StickyRect == null)
		{
			playerCol.killPlayer(Constants.ENVIRONMENTAL_PLAYER_ID, spawnEffect: true, ignoreInvulnerability: true, CauseOfDeath.Accident);
			return;
		}
		if (!StickyRect.isActiveAndEnabled)
		{
			spriteRen.enabled = false;
			return;
		}
		if (!spriteRen.enabled)
		{
			spriteRen.enabled = true;
		}
		timePassed += GameTime.FixedDeltaTime(player.Id, simDeltaTime);
		bool flag = player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012);
		if (!flag && !hasReleased)
		{
			hasReleased = true;
		}
		_ = ButtonWasDown;
		Vec2 vec = StickyRect.rr.CalcExtents();
		Fix x = vec.x;
		Fix y = vec.y;
		Fix radius = StickyRect.rr.radius;
		Fix fix2 = maxArea * StickyRect.rr.Scale;
		switch (state)
		{
		case State.Rotation:
		{
			Vec2 vec2 = player.AimVector();
			Fix fix5 = EnterScaleAnimation.Evaluate(timePassed);
			ResizePlatform(vec.x, vec.y, StickyRect.rr.Scale * fix5);
			if (Vec2.Magnitude(vec2) >= Constants.DEADZONE)
			{
				Vec2 up = Vec2.Slerp(StickyRect.rr.up, vec2, simDeltaTime * rotationSpeed);
				body.up = up;
				animVel.homeRotation = body.rotation;
				if (StickyRect != null)
				{
					StickyRect.GetGroundBody().up = up;
				}
			}
			body.position = StickyRect.rr.position;
			break;
		}
		case State.Size:
		{
			cursorTransform.position += inputVector * cursorSensitivity * simDeltaTime;
			Vec2 vec3 = Vec2.ComplexMul(new Vec2(-body.rotation), cursorTransform.position - fixTrans.position);
			Fix x2 = vec3.x;
			Fix y2 = vec3.y;
			x2 = Fix.Min(Fix.Max(x2, -x - radius), x + radius);
			y2 = Fix.Min(Fix.Max(y2, -y - radius), y + radius);
			vec3 = new Vec2(x2, y2);
			cursorTransform.position = fixTrans.position + Vec2.ComplexMul(body.right, vec3);
			Fix b = MinSize + radius * (Fix)2L;
			Vec2 vec4 = new Vec2(x, y);
			if (vec3.x >= x && x <= MinSize)
			{
				activeCorner01.x = Fix.One;
			}
			else if (vec3.x < -x && x <= MinSize)
			{
				activeCorner01.x = -Fix.One;
			}
			if (vec3.y >= y && y <= MinSize)
			{
				activeCorner01.y = Fix.One;
			}
			else if (vec3.y < -y && y <= MinSize)
			{
				activeCorner01.y = -Fix.One;
			}
			vec4 = new Vec2(activeCorner01.x * vec4.x, activeCorner01.y * vec4.y);
			Vec2 vec5 = vec3 - vec4;
			Vec2 vec6 = new Vec2(Fix.Min(vec5.x, b), Fix.Min(vec5.y, b));
			Fix fix6 = Vec2.Magnitude(vec6);
			Vec2 vec7 = ((fix6 == 0L) ? Vec2.zero : vec6);
			if (fix6 < 1L)
			{
				vec7 = vec6;
			}
			vec7 = new Vec2(vec7.x * (Fix)Fix.Sign(vec4.x), vec7.y * (Fix)Fix.Sign(vec4.y));
			Fix a = x + vec7.x * fix * SizeChangeSpeed;
			Fix a2 = y + vec7.y * fix * SizeChangeSpeed;
			a = Fix.Max(a, MinSize);
			a2 = Fix.Max(a2, MinSize);
			if (vec7.x >= 0L && vec7.y >= 0L)
			{
				Vec2 vec8 = vec7;
				vec8.x *= fix * SizeChangeSpeed;
				vec8.y *= fix * SizeChangeSpeed;
				Fix fix7 = Fix.Min(vec8.x, vec8.y);
				Fix fix8 = vec8.x - vec8.y;
				if (fix8 > 0L)
				{
					Vec2 newSize = GetNewSize(x + fix8, y);
					a = newSize.x;
					a2 = newSize.y;
				}
				else if (fix8 < 0L)
				{
					fix8 *= -Fix.One;
					Vec2 newSize2 = GetNewSize(y + fix8, x);
					a2 = newSize2.x;
					a = newSize2.y;
				}
				else
				{
					a2 = y;
					a = x;
				}
				if (StickyRect.rr.PlatformArea(a + fix7, a2 + fix7, radius) > fix2)
				{
					Fix fix9 = (Fix)4L * a2 * radius + (Fix)4L * a * radius + (Fix)4L * a2 * a + Fix.Pi * radius * radius - fix2;
					Fix fix10 = (Fix)8L * radius + (Fix)4L * a2 + (Fix)4L * a;
					fix9 *= (Fix)0.25f;
					Fix fix11 = fix10 * (Fix)0.25f;
					Fix fix12 = Fix.Sqrt(fix11 * fix11 * (Fix)0.25f - fix9);
					Fix fix13 = -fix11 * (Fix)0.5f + fix12;
					a2 += fix13;
					a += fix13;
				}
				else
				{
					a2 += fix7;
					a += fix7;
				}
			}
			else if (vec7.x > 0L)
			{
				Vec2 newSize3 = GetNewSize(a, a2);
				a = newSize3.x;
				a2 = newSize3.y;
			}
			else if (vec7.y > 0L)
			{
				Vec2 newSize4 = GetNewSize(a2, a);
				a2 = newSize4.x;
				a = newSize4.y;
			}
			_ = radius * (Fix)2L;
			Vec2 vec9 = new Vec2(a - x, a2 - y);
			vec9 = Vec2.ComplexMul(u: new Vec2(vec9.x * activeCorner01.x, vec9.y * activeCorner01.y), v: body.right);
			StickyRect.GetGroundBody().position += vec9;
			animVel.HomePosition += vec9;
			fixTrans.position += vec9;
			ResizePlatform(a, a2, radius);
			if (!(Vec2.Magnitude(vec7) <= Constants.DEADZONE))
			{
				if (!expandingWidth && Fix.Abs(vec7.x) > Fix.Abs(vec7.y))
				{
					spriteAnim.beginAnimation(animData.GetAnimation("WidthLoop"));
					expandingWidth = true;
				}
				else if (expandingWidth && Fix.Abs(vec7.x) <= Fix.Abs(vec7.y))
				{
					spriteAnim.beginAnimation(animData.GetAnimation("HeightLoop"));
					expandingWidth = false;
				}
			}
			if (hasReleased || timePassed > maxSizeTime)
			{
				cursorRenderer.enabled = false;
				state = State.Exit;
				AudioManager.Get().Play("transform3");
				spriteAnim.beginAnimThenDoAction(animData.GetAnimation("ToExit"), beginEjection);
				exitTime = timePassed;
			}
			body.position = StickyRect.GetGroundBody().position;
			break;
		}
		case State.Exit:
		{
			Fix fix3 = radius + y;
			Fix fix4 = EjectionCurve01.Evaluate((timePassed - exitTime) / TimeInExit) * fix3;
			body.position = StickyRect.GetGroundBody().position + StickyRect.GetGroundBody().up * fix4;
			if (fix4 + faceHeight >= radius + y)
			{
				body.position += StickyRect.GetGroundBody().up * EjectionOffset;
				ExitAbility();
			}
			break;
		}
		}
		ButtonWasDown = flag;
	}

	private void beginEjection()
	{
		spriteAnim.beginAnimation(animData.GetAnimation("Exit"));
	}

	private Vec2 GetNewSize(Fix newWidth, Fix newHeight)
	{
		Fix radius = StickyRect.rr.radius;
		Fix fix = StickyRect.rr.PlatformArea(newWidth, newHeight, radius);
		Fix fix2 = maxArea * StickyRect.rr.Scale;
		if (fix > fix2)
		{
			newHeight = (fix2 - (Fix)4L * radius * newWidth - Fix.Pi * radius * radius) / ((Fix)4L * radius + (Fix)4L * newWidth);
			if (newHeight < MinSize)
			{
				newHeight = MinSize;
				newWidth = (fix2 - (Fix)4L * newHeight * radius - Fix.Pi * radius * radius) / ((Fix)4L * newHeight + (Fix)4L * radius);
			}
		}
		return new Vec2(newWidth, newHeight);
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		if (cursorRenderer != null)
		{
			cursorRenderer.enabled = false;
		}
		body.rotation = Fix.Zero;
		exitInfo.groundedSpeed = Fix.Zero;
		exitInfo.isGrounded = false;
		exitInfo.isFacingRight = inputVector.x >= 0L;
		exitInfo.position = body.position;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.currentlyAttachedGround = null;
		exitInfo.lastSprite = spriteRen.sprite;
		player.InPlatformTransform = false;
		ability.ExitAbility(exitInfo);
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}
}
public class QuantumTunnel : MonoUpdatable
{
	[HideInInspector]
	public GameObject Victim;

	private Fix LifeSpan;

	private bool IsInitialized;

	private Fix age;

	private Sprite sprite;

	private SpriteRenderer spriteRen;

	private FixTransform fixTrans;

	public AnimationCurve ScaleAnim;

	public AnimationCurve OpacityAnim;

	private float originalAlpha = 1f;

	private Vector3 originalScale;

	private Fix victimRotation;

	private BoplBody victimBoplBody;

	private PlayerBody victimPlayerBody;

	private FixTransform victimFixTrans;

	private Fix delay = -Fix.One;

	private Fix DelayTimePassed = Fix.Zero;

	private Fix delayedParameter2;

	private Material delayedParameter3;

	private bool isPlayer;

	private bool hasPlayedTeleport2;

	public ParticleSystem onPlayerHitParticlePrefab;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		spriteRen = GetComponent<SpriteRenderer>();
		fixTrans = GetComponent<FixTransform>();
	}

	public void DelayedInit(GameObject victim, Fix lifeSpan, Fix delay, Material onDissapearResizableWallMaterail = null)
	{
		this.delay = delay;
		DelayTimePassed = Fix.Zero;
		IsInitialized = false;
		Victim = victim;
		delayedParameter2 = lifeSpan;
		delayedParameter3 = onDissapearResizableWallMaterail;
	}

	public void Init(GameObject victim, Fix lifeSpan, Material onDisappearResizableWallMaterial = null, bool isPlayer = false)
	{
		this.isPlayer = isPlayer;
		victimBoplBody = victim.GetComponent<BoplBody>();
		victimPlayerBody = victim.GetComponent<PlayerBody>();
		victimFixTrans = victim.GetComponent<FixTransform>();
		if (victimFixTrans.IsDestroyed)
		{
			Updater.DestroyFix(this);
			return;
		}
		if (victimBoplBody != null)
		{
			victimRotation = victimBoplBody.rotation;
			if (isPlayer)
			{
				BounceBall component = victimBoplBody.GetComponent<BounceBall>();
				component?.AttachRope(null, component.topAttachment);
			}
		}
		else if (victimPlayerBody != null)
		{
			victimRotation = victimPlayerBody.rotation;
			if (victimPlayerBody.ropeBody != null && victimPlayerBody.ropeBody.enabled)
			{
				victimPlayerBody.AttachRope(null, victimPlayerBody.topAttachment);
			}
			MagnetGun component2 = victimPlayerBody.GetComponent<MagnetGun>();
			if (component2 != null && !component2.IsDestroyed)
			{
				component2.OnItemWasStolen();
			}
		}
		victim.GetComponent<IPlayerIdHolder>();
		LifeSpan = lifeSpan;
		Victim = victim;
		IsInitialized = true;
		age = Fix.Zero;
		hasPlayedTeleport2 = false;
		SpriteRenderer componentInChildren = victim.GetComponentInChildren<SpriteRenderer>();
		if (componentInChildren != null)
		{
			spriteRen.sprite = componentInChildren.sprite;
			spriteRen.sortingLayerID = componentInChildren.sortingLayerID;
			spriteRen.sortingOrder = componentInChildren.sortingOrder;
			spriteRen.flipX = componentInChildren.flipX;
			spriteRen.flipY = componentInChildren.flipY;
			originalAlpha = componentInChildren.color.a;
			spriteRen.material.SetVector("_UVCenter", new Vector4(0.5f, 0.5f, 1f, 1f));
		}
		if (onDisappearResizableWallMaterial != null)
		{
			spriteRen.material = onDisappearResizableWallMaterial;
			DPhysicsRoundedRect component3 = victim.GetComponent<DPhysicsRoundedRect>();
			if (component3 != null)
			{
				Vec2 vec = component3.CalcExtents();
				spriteRen.material.SetFloat("_Scale", victim.transform.localScale.x);
				spriteRen.material.SetFloat("_BevelRadius", (float)component3.radius);
				spriteRen.material.SetFloat("_RWidth", (float)vec.x);
				spriteRen.material.SetFloat("_RHeight", (float)vec.y);
			}
		}
		base.transform.localScale = victim.transform.localScale;
		victimFixTrans.rotation = victimFixTrans.rotation;
		fixTrans.SyncTransform();
		originalScale = victim.transform.lossyScale;
		victim.SetActive(value: false);
		AudioManager.Get().Play("teleport");
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (Victim == null)
		{
			Updater.DestroyFix(base.gameObject);
			return;
		}
		if (!IsInitialized && delay > 0L)
		{
			DelayTimePassed += SimDeltaTime * GameTime.PlayerTimeScale;
			if (DelayTimePassed > delay)
			{
				Init(Victim, delayedParameter2, delayedParameter3);
			}
		}
		if (!IsInitialized)
		{
			return;
		}
		if (age > LifeSpan)
		{
			Victim.SetActive(value: true);
			Updater.DestroyFix(base.gameObject);
		}
		age += GameTime.PlayerTimeScale * SimDeltaTime;
		fixTrans.position = victimFixTrans.position;
		fixTrans.rotation = victimFixTrans.rotation;
		float time = ScaleAnim.keys[ScaleAnim.keys.Length - 1].time;
		if (age < LifeSpan - (Fix)time)
		{
			float num = ScaleAnim.Evaluate((float)age);
			base.transform.localScale = new Vector3(num * originalScale.x, num * originalScale.y, originalScale.z);
			spriteRen.color = new UnityEngine.Color(spriteRen.color.r, spriteRen.color.g, spriteRen.color.b, originalAlpha * OpacityAnim.Evaluate((float)age));
			return;
		}
		if (isPlayer)
		{
			Vec2 position = victimFixTrans.position;
			determinePlayerReleasePosition();
			Vec2 position2 = victimFixTrans.position;
			spawnPlayerMoveEffect(position, position2);
			isPlayer = false;
		}
		if (!hasPlayedTeleport2)
		{
			AudioManager.Get().Play("teleport2");
			hasPlayedTeleport2 = true;
		}
		float time2 = Mathf.Clamp01((float)LifeSpan - (float)age);
		float num2 = ScaleAnim.Evaluate(time2);
		base.transform.localScale = new Vector3(num2 * originalScale.x, num2 * originalScale.y, originalScale.z);
		spriteRen.color = new UnityEngine.Color(spriteRen.color.r, spriteRen.color.g, spriteRen.color.b, originalAlpha * OpacityAnim.Evaluate(time2));
	}

	private void spawnPlayerMoveEffect(Vec2 from, Vec2 to)
	{
		float num = 5f;
		Vector3 vector = (Vector3)to - (Vector3)from;
		if (vector.sqrMagnitude > num)
		{
			ParticleSystem particleSystem = UnityEngine.Object.Instantiate(onPlayerHitParticlePrefab, (Vector3)from, Quaternion.identity);
			ParticleSystem.VelocityOverLifetimeModule velocityOverLifetime = particleSystem.velocityOverLifetime;
			velocityOverLifetime.orbitalOffsetX = new ParticleSystem.MinMaxCurve
			{
				constantMin = vector.x,
				constantMax = vector.x,
				mode = ParticleSystemCurveMode.TwoConstants
			};
			velocityOverLifetime.orbitalOffsetY = new ParticleSystem.MinMaxCurve
			{
				constantMin = vector.y - 0.5f,
				constantMax = vector.y + 0.5f,
				mode = ParticleSystemCurveMode.TwoConstants
			};
			float num2 = 0.25f;
			float num3 = vector.magnitude / num2;
			if (num3 > 100f)
			{
				velocityOverLifetime.radial = 0f - num3;
				return;
			}
			num3 = -100f;
			velocityOverLifetime.radial = num3;
			num2 = (0f - Mathf.Abs(vector.magnitude)) / num3;
			ParticleSystem.MainModule main = particleSystem.main;
			main.startLifetime = num2;
		}
	}

	private void determinePlayerReleasePosition()
	{
		PlayerPhysics component = victimFixTrans.GetComponent<PlayerPhysics>();
		PhysicsBodyList<RoundedRect> roundedRects = DetPhysics.Get().roundedRects;
		DetPhysics detPhysics = DetPhysics.Get();
		if (component != null && component.IsGrounded())
		{
			_ = victimFixTrans.position;
			List<int> list = new List<int>(detPhysics.roundedRects.Length);
			Fix fix = SceneBounds.WaterHeight + (Fix)0.5;
			Vec2 p = new Vec2(Fix.Zero, (Fix)1000L);
			for (int i = 0; i < detPhysics.roundedRects.Length; i++)
			{
				if (DetPhysics.IsActive(detPhysics.roundedRects.physicsParents[i]) && SceneBounds.IsInSceneBounds(detPhysics.roundedRects.colliders[i].Pos()) && detPhysics.roundedRects.colliders[i].GetClosestPoint(p).y > fix)
				{
					Vec2 vec = detPhysics.roundedRects.colliders[i].Pos();
					if (Fix.Abs(vec.x - victimFixTrans.position.x) > SceneBounds.BlastZone_YMax)
					{
						Tools.Debug_DrawLine(vec, new Vec2((Fix)0L, (Fix)1000L), UnityEngine.Color.red, 10f);
					}
					else
					{
						list.Add(i);
					}
				}
			}
			if (list.Count == 0)
			{
				return;
			}
			int index = Updater.RandomInt(0, list.Count);
			int num = list[index];
			PhysicsParent physicsParent = detPhysics.roundedRects.physicsParents[num];
			StickyRoundedRectangle component2 = physicsParent.fixTrans.GetComponent<StickyRoundedRectangle>();
			if (component2 == null)
			{
				return;
			}
			for (int j = 0; j < 20; j++)
			{
				Fix localPlayerPos = Updater.RandomFix(Fix.Zero, Fix.One);
				Vec2 vec2 = component2.PositionFromLocalPlayerPos(localPlayerPos, Fix.Zero);
				Vec2 vec3 = vec2 + component2.currentNormal(vec2) * component.radius;
				bool flag = false;
				for (int k = 0; k < detPhysics.roundedRects.Length; k++)
				{
					Tools.Debug_DrawPos(vec2, UnityEngine.Color.blue, 2f);
					Tools.Debug_DrawLine(vec2, vec3, UnityEngine.Color.black, 2f);
					if (detPhysics.roundedRects.physicsParents[k].hierarchyNumber != physicsParent.hierarchyNumber && detPhysics.roundedRects.colliders[k].OverlapPoint(vec3))
					{
						flag = true;
						break;
					}
				}
				if (vec2.y > fix && SceneBounds.IsInSceneBounds(vec2) && !flag)
				{
					component.AttachToGround(component2, vec2);
					victimFixTrans.position = component.GetPlayerBody().position;
					return;
				}
			}
			victimFixTrans.position = detPhysics.roundedRects.colliders[num].GetClosestPoint(p);
			component.AttachToGround(component2, victimFixTrans.position);
			return;
		}
		Vec2 zero = Vec2.zero;
		for (int l = 0; l < roundedRects.Length; l++)
		{
			zero += roundedRects.colliders[l].Pos();
		}
		zero /= (Fix)roundedRects.Length;
		Tools.Debug_DrawPos(zero, UnityEngine.Color.red, 10f);
		Fix a = zero.y - (Fix)4L;
		Fix fix2 = SceneBounds.BlastZone_XMin;
		Fix fix3 = SceneBounds.BlastZone_XMax;
		int num2 = 0;
		for (int m = 0; m < detPhysics.roundedRects.Length; m++)
		{
			if (DetPhysics.IsActive(detPhysics.roundedRects.physicsParents[m]))
			{
				Vec2 pos = detPhysics.roundedRects.colliders[m].Pos();
				if (Fix.Abs(pos.x - victimFixTrans.position.x) > SceneBounds.BlastZone_YMax)
				{
					Tools.Debug_DrawPos(pos, UnityEngine.Color.red, 10f);
					continue;
				}
				num2++;
				AABB bb = PhysTools.ComputeBoundingBox(detPhysics.roundedRects.colliders[m], m);
				Tools.Debug_DrawAABB(bb, UnityEngine.Color.green, 10f);
				fix2 = Fix.Max(fix2, bb.max.x);
				fix3 = Fix.Min(fix3, bb.min.x);
			}
		}
		if (num2 == 0 || fix2 < fix3)
		{
			fix2 = victimFixTrans.position.x + (Fix)30L;
			fix3 = victimFixTrans.position.x - (Fix)30L;
		}
		Vec2 min = new Vec2(fix3, Fix.Max(a, SceneBounds.WaterHeight + Fix.One));
		Vec2 max = new Vec2(fix2, SceneBounds.Camera_YMax - (Fix)1.7);
		Tools.Debug_DrawAABB(new AABB
		{
			min = min,
			max = max
		}, UnityEngine.Color.red, 10f);
		Vec2 vec4 = victimFixTrans.position;
		if (min.x > max.x)
		{
			min.x = max.x;
		}
		if (min.y > max.y)
		{
			min.y = max.y;
		}
		for (int n = 0; n < 20; n++)
		{
			Fix x = Updater.RandomFix(min.x, max.x);
			Fix y = Updater.RandomFix(min.y, max.y);
			vec4 = new Vec2(x, y);
			if (!detPhysics.PointCheckAllRoundedRects(vec4))
			{
				break;
			}
		}
		victimFixTrans.position = vec4;
		PlayerBody component3 = victimFixTrans.GetComponent<PlayerBody>();
		if (component3 != null)
		{
			component3.selfImposedVelocity = Vec2.zero;
		}
	}

	private void determinePlayerReleasePosition_old()
	{
		PlayerPhysics component = victimFixTrans.GetComponent<PlayerPhysics>();
		Vec2 vec = victimFixTrans.position + Updater.RandomInsideUnitCircle() * (Fix)6L;
		if (component != null)
		{
			component.UnGround();
		}
		RaycastInformation raycastInformation = DetPhysics.Get().PointCheckAllRoundedRects(vec);
		if ((bool)raycastInformation)
		{
			StickyRoundedRectangle component2 = raycastInformation.pp.fixTrans.GetComponent<StickyRoundedRectangle>();
			if (component2 != null)
			{
				vec = component2.GetClosestPoint(vec);
			}
		}
		victimFixTrans.position = vec;
	}
}
public class QuickSpell : MonoUpdatable, IAbilityComponent
{
	[SerializeField]
	private AnimationData animData;

	[SerializeField]
	private GameObject spell;

	[SerializeField]
	private UnityEvent spellFunc;

	[SerializeField]
	private Vec2 ExitAbilityOffset;

	[SerializeField]
	private Vec2 EnterAbilityOffset;

	[SerializeField]
	private Vec2 shockwaveOffset;

	[SerializeField]
	private bool offsetParticle;

	[SerializeField]
	private ParticleSystem ParticleCastPrefab;

	private ParticleSystem ParticleOnCast;

	[SerializeField]
	private string AudioToPlayOnCast;

	[SerializeField]
	private string AudioToPlayOnEnter;

	private PlayerInfo playerInfo;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private DPhysicsCircle smallCollider;

	private Player player;

	public bool scaleParticleSize = true;

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		smallCollider = GetComponent<DPhysicsCircle>();
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		smallCollider.UpdatePhysicsPositions();
		body.position = playerInfo.position + EnterAbilityOffset;
		base.transform.position = (Vector3)body.position;
		physics.UnGround();
		body.selfImposedVelocity = Vec2.zero;
		body.externalVelocity = Vec2.zero;
		animator.beginAnimThenDoAction(animData.GetAnimation("castAir"), Cast);
		if (!string.IsNullOrEmpty(AudioToPlayOnEnter))
		{
			AudioManager.Get().Play(AudioToPlayOnEnter);
		}
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		body.rotation = Fix.Zero;
		physics.UnGround(nullRotation: true, playSoundEffect: false);
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.position = body.position + ExitAbilityOffset;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		exitInfo.lastSprite = null;
		ability.ExitAbility(exitInfo);
	}

	private void Cast()
	{
		GameObject gameObject = null;
		Revive component = GetComponent<Revive>();
		if (spell != null)
		{
			Vec2 pos = body.position + shockwaveOffset * player.Scale;
			if (component != null)
			{
				Vec2 offset = new Vec2((Fix)2L, (Fix)2L);
				pos = SceneBounds.ClampInsideCameraMaxBounds(pos, offset);
			}
			gameObject = FixTransform.InstantiateFixed(spell, pos);
			gameObject.GetComponent<IPlayerIdHolder>()?.SetPlayerId(playerInfo.playerId);
			IPhysicsCollider component2 = gameObject.GetComponent<IPhysicsCollider>();
			if (component2 != null && !GetComponent<Revive>())
			{
				component2.Scale = player.Scale;
			}
			gameObject.GetComponent<Shockwave>()?.SetScale(player.Scale);
		}
		spellFunc?.Invoke();
		if (component != null)
		{
			component.SetReviveFlag(gameObject);
		}
		ParticleOnCast = UnityEngine.Object.Instantiate(ParticleCastPrefab, base.transform.position + (Vector3)(player.Scale * shockwaveOffset), Quaternion.identity);
		if (ParticleOnCast != null && scaleParticleSize)
		{
			ParticleOnCast.transform.localScale = ParticleCastPrefab.transform.localScale * (float)player.Scale;
		}
		if (!string.IsNullOrEmpty(AudioToPlayOnCast))
		{
			AudioManager.Get().Play(AudioToPlayOnCast);
		}
		animator.beginAnimThenDoAction(animData.GetAnimation("exit"), EmptyExitInfo);
	}

	private void EmptyExitInfo()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}
}
public class Revive : MonoUpdatable
{
	private Player player;

	[SerializeField]
	private Vec2 positionOffset;

	private RevivePositionIndicator reviveIndicator;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
	}

	public override void Init()
	{
	}

	public void SetReviveFlag(GameObject indicator)
	{
		if (reviveIndicator != null && !reviveIndicator.IsDestroyed)
		{
			reviveIndicator.End();
			int num = player.RespawnPositions.Count - 1;
			while (num >= 0 && num < player.RespawnPositions.Count)
			{
				if (player.RespawnPositions[num] == null || (player.RespawnPositions[num] != null && player.RespawnPositions[num].IsDestroyed))
				{
					player.RespawnPositions.RemoveAt(num);
				}
				else
				{
					num--;
				}
			}
		}
		reviveIndicator = indicator.GetComponent<RevivePositionIndicator>();
		player = PlayerHandler.Get().GetPlayer(GetComponent<IPlayerIdHolder>().GetPlayerId());
		player.ExtraLife = ReviveStatus.willReviveOnDeath;
		player.ReviveInstance = this;
		player.RespawnPositions.Add(reviveIndicator);
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}
}
public class RevivePositionIndicator : MonoUpdatable, IPlayerIdHolder, ISpell
{
	private ParticleSystem particle;

	private FixTransform fixTrans;

	private BoplBody body;

	private DPhysicsCircle hurtbox;

	private int id;

	public Vec2 GetPos()
	{
		return fixTrans.position;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		particle = GetComponent<ParticleSystem>();
		fixTrans = GetComponent<FixTransform>();
		body = GetComponent<BoplBody>();
		hurtbox = GetComponent<DPhysicsCircle>();
	}

	public int GetPlayerId()
	{
		return id;
	}

	public Material GetPlayerMaterial()
	{
		return null;
	}

	public void SetPlayerId(int id)
	{
		this.id = id;
		Player player = PlayerHandler.Get().GetPlayer(id);
		if (player != null && particle != null)
		{
			ParticleSystem.MainModule main = particle.main;
			main.startColor = player.Color.GetColor("_ShadowColor");
		}
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		Vec2 position = body.position;
		Vec2 offset = new Vec2((Fix)2L, (Fix)2L);
		position = SceneBounds.ClampInsideCameraMaxBounds(position, offset);
		if (position.y < SceneBounds.WaterHeight && !Constants.isSpaceLevel)
		{
			position.y = SceneBounds.WaterHeight;
		}
		body.position = position;
	}

	public void End()
	{
		if (!(this == null) && !(base.gameObject == null))
		{
			if (particle == null)
			{
				Updater.DestroyFix(base.gameObject);
				return;
			}
			UnityEngine.Object.Destroy(base.gameObject, particle.main.duration);
			particle.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
			Updater.DestroyFix(this);
			Updater.DestroyFix(body);
			Updater.DestroyFix(hurtbox);
			Updater.DestroyFix(fixTrans);
		}
	}

	public void AddScale(Fix scaleDiff)
	{
		_ = body.Scale;
		body.Scale += scaleDiff;
		base.transform.GetChild(0).transform.localScale = base.transform.localScale;
		base.transform.GetChild(1).transform.localScale = base.transform.localScale;
	}
}
public class RocketEngine : MonoUpdatable, IPlatformAttachable
{
	private AnimateVelocity groundVel;

	private BoplBody groundBody;

	private SpriteAnimator childAnimation;

	private ParticleSystem particleSmoke;

	private bool isEngineOn;

	private StickyRoundedRectangle srr;

	private DPhysicsBox hitbox;

	private FixTransform fixTrans;

	public AnimationData FireData;

	public AnimationCurveFixed ForceAnim;

	public Vec2 offset;

	public Fix radius;

	public LayerMask smokeOnlyLayerMask;

	private static PhysicsParent[] scanForSmokeBuffer = new PhysicsParent[1];

	[HideInInspector]
	public int ownerId;

	private Fix timeSinceEngineStarted;

	private bool inStoppingAnimation;

	private Fix prevScale = Fix.One;

	public Fix SurfaceOffset { get; private set; }

	public Fix LocalPlatformPosition { get; private set; }

	public override void Init()
	{
	}

	public bool IsEngineOn()
	{
		return isEngineOn;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawWireSphere(base.transform.position + base.transform.up * (float)offset.y + base.transform.right * (float)offset.x, (float)radius);
	}

	private void BlowUpSmokeTouchingTheFire()
	{
		Vec2 pos = fixTrans.position + fixTrans.up * (offset.y * fixTrans.Scale) + fixTrans.right * (offset.x * fixTrans.Scale);
		if (DetPhysics.Get().circleCastCircles(pos, radius * fixTrans.Scale, smokeOnlyLayerMask, ref scanForSmokeBuffer) > 0 && scanForSmokeBuffer[0].fixTrans != null && !scanForSmokeBuffer[0].fixTrans.IsDestroyed)
		{
			scanForSmokeBuffer[0].fixTrans.GetComponent<FlammableSmoke>()?.Ignite();
		}
	}

	public void RocketEngineInit(StickyRoundedRectangle srr, Fix surfaceOffset, Vec2 position, Fix scale, int playerId, bool updateStartScale = true, bool skipInit = false)
	{
		this.srr = srr;
		groundVel = srr?.GetComponent<AnimateVelocity>();
		groundBody = srr?.GetComponent<BoplBody>();
		hitbox = GetComponent<DPhysicsBox>();
		fixTrans = GetComponent<FixTransform>();
		if (!skipInit)
		{
			hitbox.ManualInit();
		}
		hitbox.Scale = scale;
		srr.UpdateBounds();
		LocalPlatformPosition = srr.LocalPlayerPosFromPos(position, Fix.Zero);
		SurfaceOffset = surfaceOffset;
		childAnimation = base.transform.GetChild(0).GetComponent<SpriteAnimator>();
		particleSmoke = base.transform.GetChild(1).GetComponent<ParticleSystem>();
		particleSmoke.transform.localScale = (float)scale * new Vector3(1f, 1f, 1f);
		ownerId = playerId;
		isEngineOn = false;
		inStoppingAnimation = false;
		childAnimation.enabled = true;
		timeSinceEngineStarted = Fix.Zero;
		childAnimation.beginAnimThenDoAction(FireData.GetAnimation("start"), StartEngine);
		AudioManager.Get().Play("startEngine");
		Fix fix = Fix.Clamp(scale, hitbox.MinScale, hitbox.MaxScale);
		LocalPlatformPosition = srr.LocalPlayerPosFromPos(position, Fix.Zero);
		SurfaceOffset = surfaceOffset;
		SurfaceOffset *= fix;
		hitbox.Scale = fix;
		prevScale = fix;
		if (updateStartScale)
		{
			fixTrans.startScale = new Vector3(fixTrans.startScale.x / srr.transform.localScale.x, fixTrans.startScale.y / srr.transform.localScale.y, 1f);
		}
		base.transform.localScale = new Vector3((float)fix / srr.transform.localScale.x, (float)fix / srr.transform.localScale.y, 1f);
		DetPhysics.Get().AddBoxToRR(base.gameObject.GetInstanceID(), srr.gameObject.GetInstanceID());
		RepositionOnParent();
	}

	private void StartEngine()
	{
		childAnimation.beginAnimation(FireData.GetAnimation("loop"));
		inStoppingAnimation = false;
		isEngineOn = true;
		particleSmoke.Play();
		timeSinceEngineStarted = Fix.Zero;
	}

	private void TurnOff()
	{
		isEngineOn = false;
		childAnimation.beginAnimation(new SpriteFrame[1]);
		childAnimation.enabled = false;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (fixTrans.Scale != prevScale)
		{
			Fix fix = fixTrans.Scale / prevScale;
			SurfaceOffset *= fix;
			prevScale = fixTrans.Scale;
		}
		if (!isEngineOn)
		{
			return;
		}
		BlowUpSmokeTouchingTheFire();
		if (GameTime.IsTimeStopped())
		{
			if (!particleSmoke.isPaused)
			{
				particleSmoke.Pause();
			}
			return;
		}
		if (particleSmoke.isPaused)
		{
			particleSmoke.Play();
		}
		Vec2 vec = srr.PositionFromLocalPlayerPos(LocalPlatformPosition, Fix.Zero);
		Vec2 vec2 = srr.currentNormal(vec);
		if (!inStoppingAnimation && (timeSinceEngineStarted > ForceAnim.keys[ForceAnim.keys.Length - 1].time || vec.y < SceneBounds.WaterHeight))
		{
			inStoppingAnimation = true;
			AudioManager.Get().Play("endEngine");
			childAnimation.beginAnimThenDoAction(FireData.GetAnimation("end"), TurnOff);
			particleSmoke.Stop();
			return;
		}
		timeSinceEngineStarted += GameTime.FixedDeltaTime(Constants.ENVIRONMENTAL_PLAYER_ID, simDeltaTime);
		Vec2 vec3 = ForceAnim.Evaluate(timeSinceEngineStarted) * -vec2 * hitbox.Scale;
		Tools.Debug_DrawLine_fu(vec, vec + vec3, UnityEngine.Color.red);
		groundBody.AddForceAtPosition(vec3, vec);
		if (groundVel != null && groundVel.HomeIsMovable)
		{
			groundVel.HomePosition = groundBody.position;
			if (!groundVel.isInRotationMode())
			{
				groundVel.homeRotation = groundBody.rotation;
			}
		}
	}

	public void RepositionOnParent()
	{
		if (!(groundBody == null) && !groundBody.IsDestroyed)
		{
			Vec2 vec = srr.PositionFromLocalPlayerPos(LocalPlatformPosition, Fix.Zero);
			if (hitbox != null && !hitbox.IsDestroyed)
			{
				vec += hitbox.up * SurfaceOffset;
				Vec2 vec2 = new Vec2(Fix.PiTimes2 - srr.rr.rotation);
				Vec2 relativePos = Vec2.ComplexMul(vec2, vec - srr.rr.position);
				Vec2 relativeRightVector = Vec2.ComplexMul(hitbox.right, vec2);
				hitbox.SetRelativePositionOfChildBody(relativePos, relativeRightVector);
			}
		}
	}

	private void Update()
	{
		if (isEngineOn && !GameTime.IsTimeStopped())
		{
			AudioManager.Get().PlayOrContinueLoop("loopEngine");
		}
	}
}
public class Roll : MonoUpdatable, IAbilityComponent
{
	private PlayerInfo playerInfo;

	private Player player;

	private bool movingRight;

	private bool isCharging;

	private Fix secondsCharged = Fix.Zero;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private DPhysicsCircle hurtBox;

	private PlayerPhysics playerPhysics;

	private DestroyIfOutsideSceneBounds destroyOutsideScene;

	private PlayerCollision playerCol;

	public Fix maxDuration = (Fix)10L;

	public Fix MaxSpeed;

	public Fix MinSpeed;

	public AnimationCurveFixed speedCurve;

	public AnimationCurveFixed trailWidthCurve;

	public Fix trailWidthMultiplier = (Fix)0.005f;

	public GameObject rollWave;

	private SpriteAnimator rollAnimator;

	public AnimationData animData;

	public Fix chargeTime = (Fix)1L;

	public Fix dashTime = (Fix)2L;

	private ParticleSystem particle;

	public ParticleSystem DashTrailPrefab;

	public Fix ParticleLifeTimeAfterExit;

	public SpriteRenderer slimeTrail;

	private const string col = "_ShadowColor";

	private AnimateVelocity groundAV;

	public AnimationCurveFixed chargingMovement;

	[SerializeField]
	private Fix MoveCollisionDensity = (Fix)1L;

	private int[] platformHopBuffer = new int[5];

	public LayerMask collidesWith;

	private PhysicsParent[] collidersBuffer = new PhysicsParent[10];

	private Vec2[] extraHurtBoxesPos = new Vec2[30];

	private bool[] extraHurtBoxesEnabled = new bool[30];

	[SerializeField]
	private Fix platformTurnSpeed = (Fix)5L;

	private bool jumpButtonHasBeenUp;

	private bool waitingToRelease;

	private bool hasCharged;

	private Fix topSpeed = Fix.Zero;

	private Fix groundedSpeed = Fix.Zero;

	private Fix timeSinceRelease = Fix.Zero;

	private bool isShortJumping;

	public Fix EarlyReleaseJumpStr;

	[SerializeField]
	private Fix shortJumpStr = (Fix)10f;

	public void OnScaleChanged(Fix scaleMultiplier)
	{
		if (particle != null)
		{
			particle.transform.localScale = new Vector3(base.transform.localScale.x, base.transform.localScale.y, 1f);
		}
	}

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		hurtBox = GetComponent<DPhysicsCircle>();
		ability = GetComponent<Ability>();
		playerPhysics = GetComponent<PlayerPhysics>();
		rollAnimator = rollWave.GetComponent<SpriteAnimator>();
		destroyOutsideScene = GetComponent<DestroyIfOutsideSceneBounds>();
		playerCol = GetComponent<PlayerCollision>();
	}

	private void SpawnParticleTrails()
	{
		particle = UnityEngine.Object.Instantiate(DashTrailPrefab);
		particle.transform.localScale = new Vector3(base.transform.localScale.x, base.transform.localScale.y, 1f);
		UnityEngine.Color color = spriteRen.material.GetColor("_ShadowColor");
		UnityEngine.Color color2 = (UnityEngine.Color.white * 0.5f - color * 0.5f) * 2f;
		UnityEngine.Color.RGBToHSV(color, out var H, out var S, out var V);
		color2 = UnityEngine.Color.HSVToRGB((H + 0.5f) % 1f, S, V);
		ParticleSystem.ColorOverLifetimeModule colorOverLifetime = particle.colorOverLifetime;
		Gradient gradient = new Gradient();
		GradientColorKey gradientColorKey = new GradientColorKey(UnityEngine.Color.Lerp(color, color2, 0.65f), 0f);
		GradientColorKey gradientColorKey2 = new GradientColorKey(color, 0.167f);
		GradientColorKey gradientColorKey3 = new GradientColorKey(UnityEngine.Color.black, 1f);
		gradient.SetKeys(new GradientColorKey[3] { gradientColorKey, gradientColorKey2, gradientColorKey3 }, new GradientAlphaKey[0]);
		colorOverLifetime.color = gradient;
		FollowTransform component = particle.gameObject.GetComponent<FollowTransform>();
		if ((bool)component)
		{
			component.Leader = base.transform;
		}
		component.Init();
	}

	public void OnEnterAbility()
	{
		playerCol.isSquishable = true;
		spriteRen.enabled = true;
		secondsCharged = (Fix)0L;
		waitingToRelease = false;
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		slimeTrail.material = playerInfo.playerMaterial;
		movingRight = playerInfo.isFacingRight;
		body.rotation = playerInfo.rotation;
		isCharging = true;
		isShortJumping = false;
		hasCharged = false;
		jumpButtonHasBeenUp = false;
		topSpeed = (Fix)0L;
		groundedSpeed = (Fix)0L;
		timeSinceRelease = (Fix)0L;
		animator.beginAnimThenPlayAnim(animData.GetAnimation("startup"), animData.GetAnimation("loop"));
		rollAnimator.beginAnimation(animData.GetAnimation("wave"));
		AudioManager.Get().Play("rollCharge");
		player.Rumble(Rumble.BuildTension);
		playerPhysics.SyncPhysicsTo(playerInfo);
		hurtBox.UpdatePhysicsPositions();
		body.externalVelocity = playerInfo.externalVelocity * (Fix)0.2;
		if (playerInfo.isGrounded)
		{
			groundAV = playerPhysics.getAttachedGround().GetComponent<AnimateVelocity>();
			body.selfImposedVelocity = Vec2.zero;
		}
		else
		{
			body.selfImposedVelocity = new Vec2(Fix.Zero, body.selfImposedVelocity.y);
		}
		ability.KillPlayersOnContact = false;
		int num = ((!movingRight) ? 1 : (-1));
		base.transform.localScale = new Vector3(base.transform.localScale.y * (float)num, base.transform.localScale.y, base.transform.localScale.z);
	}

	private void syncTrailMaterials(Material playerMat, Material trailMat)
	{
		trailMat.SetColor("_ShadowColor", playerMat.GetColor("_ShadowColor"));
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		if (player.RumbleState == Rumble.BuildTension)
		{
			player.Rumble(Rumble.None);
		}
		groundAV = null;
		secondsCharged = (Fix)0L;
		waitingToRelease = true;
		body.rotation = (Fix)0L;
		exitInfo.groundedSpeed = Vec2.Magnitude(body.Velocity);
		exitInfo.isGrounded = playerPhysics.IsGrounded();
		exitInfo.isFacingRight = playerInfo.isFacingRight;
		exitInfo.radius = playerPhysics.radius;
		if (playerPhysics.IsGrounded())
		{
			Vec2 vec = playerPhysics.getAttachedGround().currentNormal(body);
			exitInfo.position = body.position - vec * PlayerAbilityRadiusDiff();
			exitInfo.currentlyAttachedGround = playerPhysics.getAttachedGround();
			exitInfo.groundedLocalPosition = playerPhysics.LocalPlatformPos;
		}
		else
		{
			exitInfo.position = body.position;
		}
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.lastSprite = spriteRen.sprite;
		if (particle != null)
		{
			particle.Play();
			particle.Stop();
		}
		ability.ExitAbility(exitInfo);
	}

	private Fix PlayerAbilityRadiusDiff()
	{
		return playerPhysics.radius - playerInfo.radius;
	}

	private void Move(Fix speed, Fix simDeltaTime)
	{
		for (int i = 0; i < extraHurtBoxesPos.Length; i++)
		{
			extraHurtBoxesEnabled[i] = false;
		}
		for (int j = 0; j < platformHopBuffer.Length; j++)
		{
			platformHopBuffer[j] = -1;
		}
		if (isCharging)
		{
			playerPhysics.Move(Vec2.zero, simDeltaTime);
			return;
		}
		int num = (int)(long)(Fix.Abs(speed) * GameTime.FixedDeltaTime(player.Id, GameTime.FixedTimeStep) * MoveCollisionDensity / hurtBox.radius) + 1;
		Fix fix = (Fix)num + (Fix)1L;
		Fix fix2 = (Fix)1L / fix * speed;
		_ = body.position;
		float t = (float)GameTime.FixedDeltaTime(player.Id, GameTime.FixedTimeStep) / (float)num;
		if (playerPhysics.getAttachedGround() == null || playerPhysics.getAttachedGround().IsDestroyed)
		{
			playerPhysics.DropPlatformTest();
			return;
		}
		for (int k = 1; k < num; k++)
		{
			playerPhysics.MoveAlongCurrentPlatFormSwapIfBlocked(body, playerPhysics.radius, fix2, GameTime.FixedDeltaTime(player.Id, GameTime.FixedTimeStep), ref platformHopBuffer);
			Vec2 vec = playerPhysics.getAttachedGround().PositionFromLocalPlayerPos(playerPhysics.LocalPlatformPos, playerPhysics.radius);
			if (k <= extraHurtBoxesPos.Length)
			{
				extraHurtBoxesPos[k - 1] = vec;
				extraHurtBoxesEnabled[k - 1] = true;
			}
			if (particle != null)
			{
				particle.transform.position = (Vector3)vec;
				particle.Simulate(t, withChildren: false, restart: false, fixedTimeStep: false);
			}
		}
		playerPhysics.MoveAlongCurrentPlatFormSwapIfBlocked(body, playerPhysics.radius, fix2, GameTime.FixedDeltaTime(player.Id, GameTime.FixedTimeStep), ref platformHopBuffer);
		if (particle != null)
		{
			particle.transform.position = (Vector3)playerPhysics.getAttachedGround().PositionFromLocalPlayerPos(playerPhysics.LocalPlatformPos, playerPhysics.radius);
			particle.Simulate(t, withChildren: false, restart: false, fixedTimeStep: false);
		}
		playerPhysics.AlignToGround();
		for (int l = 0; l < extraHurtBoxesPos.Length; l++)
		{
			Vec2 vec2 = extraHurtBoxesPos[l];
			UnityEngine.Debug.DrawRay((Vector3)vec2, Vector2.up * (float)hurtBox.radius, UnityEngine.Color.red);
			UnityEngine.Debug.DrawRay((Vector3)vec2, Vector2.down * (float)hurtBox.radius, UnityEngine.Color.red);
			UnityEngine.Debug.DrawRay((Vector3)vec2, Vector2.right * (float)hurtBox.radius, UnityEngine.Color.red);
			UnityEngine.Debug.DrawRay((Vector3)vec2, Vector2.left * (float)hurtBox.radius, UnityEngine.Color.red);
		}
		CollideExtraHurtBoxes();
		playerPhysics.DropPlatformTest();
	}

	private void CollideExtraHurtBoxes()
	{
		Fix radius = hurtBox.radius;
		Circle circle = new Circle
		{
			center = hurtBox.position,
			radius = radius,
			layer = base.gameObject.layer
		};
		for (int i = 0; i < extraHurtBoxesPos.Length && extraHurtBoxesEnabled[i]; i++)
		{
			Vec2 vec = extraHurtBoxesPos[i];
			int num = DetPhysics.Get().CircleCastAll(vec, radius, collidesWith, ref collidersBuffer);
			circle.center = extraHurtBoxesPos[i];
			Vec2 center = circle.center;
			UnityEngine.Debug.DrawRay((Vector3)center, Vector2.up * (float)radius, UnityEngine.Color.red);
			UnityEngine.Debug.DrawRay((Vector3)center, Vector2.down * (float)radius, UnityEngine.Color.red);
			UnityEngine.Debug.DrawRay((Vector3)center, Vector2.right * (float)radius, UnityEngine.Color.red);
			UnityEngine.Debug.DrawRay((Vector3)center, Vector2.left * (float)radius, UnityEngine.Color.red);
			for (int j = 0; j < num; j++)
			{
				CollisionInformation collision = new CollisionInformation
				{
					collider = circle,
					colliderImpactVelocity = body.Velocity,
					colliderPP = hurtBox.GetPhysicsParent(),
					contactPoint = center,
					layer = base.gameObject.layer,
					pp = collidersBuffer[j]
				};
				collidersBuffer[j].collisionCallback.OnCollide(collision);
			}
			if (hurtBox == null || hurtBox.IsDestroyed)
			{
				break;
			}
			Vec2 position = hurtBox.position;
			for (int k = 0; k < num; k++)
			{
				circle.center = collidersBuffer[k].fixTrans.position;
				circle.layer = collidersBuffer[k].fixTrans.gameObject.layer;
				CollisionInformation colInfo = new CollisionInformation
				{
					collider = circle,
					colliderImpactVelocity = -body.Velocity,
					colliderPP = collidersBuffer[k],
					contactPoint = center,
					layer = circle.layer,
					pp = hurtBox.GetPhysicsParent()
				};
				hurtBox.position = vec;
				hurtBox.OnCollide(colInfo);
			}
			hurtBox.position = position;
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (!player.JumpButton_isDown())
		{
			jumpButtonHasBeenUp = true;
		}
		OldUpdate(simDeltaTime);
		if (!IsEnabled())
		{
			return;
		}
		if (playerPhysics.IsGrounded())
		{
			Vec2 vec = playerPhysics.getAttachedGround().forwardsDirection(body);
			vec *= (Fix)(movingRight ? 1 : (-1));
			if (isCharging)
			{
				groundedSpeed = Fix.Zero;
				vec *= (Fix)(-1L);
			}
			else
			{
				groundedSpeed = Fix.Clamp01(speedCurve.Evaluate(timeSinceRelease / dashTime)) * topSpeed;
			}
			groundedSpeed *= (Fix)(movingRight ? 1 : (-1));
			return;
		}
		if (!isCharging && !isShortJumping)
		{
			playerPhysics.AirealMovement((Fix)(movingRight ? 1 : (-1)), simDeltaTime);
		}
		playerPhysics.AddGravityFactor();
		if (playerPhysics.VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime) && isShortJumping)
		{
			ExitAbility(new AbilityExitInfo
			{
				justlanded = true
			});
		}
		else if (isShortJumping && body.selfImposedVelocity.y < 0L)
		{
			ExitAbility();
		}
	}

	private void OldUpdate(Fix simDeltaTime)
	{
		if (playerPhysics.IsGrounded() && (playerPhysics.getAttachedGround() == null || !playerPhysics.getAttachedGround().ThisGameObject().activeInHierarchy))
		{
			playerPhysics.UnGround();
			ExitAbility();
			return;
		}
		if (isCharging)
		{
			secondsCharged += GameTime.FixedDeltaTime(playerInfo.playerId, simDeltaTime);
			if (jumpButtonHasBeenUp && player.JumpButton_isDown())
			{
				playerPhysics.Jump();
				AudioManager.Get().Play("slimeJump" + player.Id);
				ExitAbility();
				return;
			}
		}
		else
		{
			timeSinceRelease += GameTime.FixedDeltaTime(playerInfo.playerId, simDeltaTime);
			if (jumpButtonHasBeenUp && player.JumpButton_isDown())
			{
				Vec2 vec = groundedSpeed * body.right;
				playerPhysics.UnGround();
				body.selfImposedVelocity = vec * (Fix)0.75f;
				ExitAbility();
				return;
			}
		}
		if (isCharging && !player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012))
		{
			if (secondsCharged >= chargeTime)
			{
				waitingToRelease = true;
				body.AttachRope(null, body.topAttachment);
			}
			else
			{
				if (playerPhysics.IsGrounded())
				{
					ExitAbility(new AbilityExitInfo
					{
						justlanded = true
					});
					return;
				}
				ShortJump();
			}
		}
		if (timeSinceRelease > dashTime)
		{
			ExitAbility();
			return;
		}
		if (!hasCharged && secondsCharged >= chargeTime && !isShortJumping)
		{
			hasCharged = true;
			if (player.RumbleState == Rumble.BuildTension)
			{
				player.Rumble(Rumble.None);
			}
			rollAnimator.beginAnimation(animData.GetAnimation("bigWave"));
			animator.beginAnimation(animData.GetAnimation("rollFast"));
			AudioManager.Get().Play("rollReady");
		}
		if (waitingToRelease && playerPhysics.IsGrounded())
		{
			ReleaseDash();
		}
		if (playerPhysics.IsGrounded())
		{
			Move(groundedSpeed, simDeltaTime);
		}
		rollWave.SetActive(playerPhysics.IsGrounded() && !ability.KillPlayersOnContact);
	}

	private void OnEnable()
	{
		if (!waitingToRelease && particle != null)
		{
			particle.GetComponent<FollowTransform>()?.AlignPositionInstantly();
			particle.gameObject.SetActive(value: true);
		}
	}

	private void OnDestroy()
	{
		if (particle != null)
		{
			particle.Play();
			particle.Stop();
		}
	}

	private void OnDisable()
	{
		if (particle != null)
		{
			particle.Play();
			particle.Stop();
		}
	}

	private void ReleaseDash()
	{
		playerCol.IgnoreCollider(hurtBox, PlayerCollision.IgnoreColliderInd.roll);
		playerCol.isSquishable = false;
		if (player.RumbleState == Rumble.BuildTension)
		{
			player.Rumble(Rumble.None);
		}
		waitingToRelease = false;
		if (particle == null)
		{
			SpawnParticleTrails();
		}
		else
		{
			particle.GetComponent<FollowTransform>().AlignPositionInstantly();
			particle.gameObject.SetActive(value: true);
		}
		ability.KillPlayersOnContact = true;
		isCharging = false;
		topSpeed = MaxSpeed;
		animator.beginAnimation(animData.GetAnimation("ball"));
		AudioManager.Get().Play("rollRelease");
	}

	private void ShortJump()
	{
		rollWave.SetActive(value: false);
		isCharging = false;
		isShortJumping = true;
		Fix jumpStrength = playerPhysics.jumpStrength;
		playerPhysics.jumpStrength = shortJumpStr;
		playerPhysics.Jump();
		playerPhysics.jumpStrength = jumpStrength;
	}
}
public class ScaleChanger : MonoUpdatable
{
	public AnimationCurveFixed scaleAnimation;

	public Fix multiplier;

	public Fix PlayerMultiplier;

	public Fix smallNonPlayersMultiplier;

	public Fix inverseMassBeforeConsideredBig;

	public IPhysicsCollider victim;

	public Player player;

	private Fix timePassed;

	[NonSerialized]
	public ISpell spell;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (timePassed > scaleAnimation.Duration() || victim == null || victim.IsDestroyed)
		{
			Updater.DestroyFix(base.gameObject);
		}
		else if (player == null)
		{
			if (GameTime.IsTimeStopped())
			{
				return;
			}
			timePassed += SimDeltaTime;
			if (victim.GetPhysicsParent().fixTrans != null)
			{
				Fix zero = Fix.Zero;
				zero = ((!(victim.GetBody().inverseMass > 0L) || !(victim.GetBody().inverseMass * victim.Scale > inverseMassBeforeConsideredBig)) ? (scaleAnimation.Evaluate(timePassed) * multiplier) : (scaleAnimation.Evaluate(timePassed) * smallNonPlayersMultiplier));
				if (spell != null)
				{
					spell.AddScale(zero);
				}
				else
				{
					victim.Scale += zero;
				}
			}
		}
		else if (!GameTime.IsTimeStopped() || player.isProtectedFromTimeStop)
		{
			player.Scale += scaleAnimation.Evaluate(timePassed) * PlayerMultiplier;
			timePassed += SimDeltaTime;
		}
	}

	private void fun(Fix SimDeltaTime)
	{
		if (victim.GetPhysicsParent().fixTrans != null && victim.GetPhysicsParent().fixTrans.gameObject.activeSelf)
		{
			timePassed += SimDeltaTime;
			victim.Scale += scaleAnimation.Evaluate(timePassed) * multiplier;
		}
	}
}
public class ShootDuplicator : MonoBehaviour, IGun
{
	private Fix maxDistance = (Fix)100L;

