	public BoplBody bounceBallPrefab;

	private float spawnInParticleScaleX;

	private float spawnInParticleScaleY;

	private float spawnInParticleRadius;

	private FixTransform fixTrans;

	public Fix f005 = (Fix)0.05;

	public Fix f032 = (Fix)0.32;

	public Fix f001 = (Fix)0.01;

	public Fix f03 = (Fix)0.3;

	public Fix f022 = (Fix)0.22;

	public bool useOldPlatformBehaviour;

	public Boulder boulderPrefab;

	public NamedSpriteList boulderSprites;

	public Fix boulderSpeed;

