	public static Vec2 PlatformSpawnPos(Vec2 dir, Vec2 r, Vec2 u, Vec2 startPos, StickyRoundedRectangle srr)
	{
		DPhysicsRoundedRect rr = srr.rr;
		Vec2 vec = rr.CalcExtents();
		Fix fix = Fix.One / (Fix)20L;
		if (vec.x < fix && vec.y < fix)
		{
			r = Vec2.right;
			u = Vec2.up;
		}
		Fix value = Vec2.Dot(u, dir);
		Fix value2 = Vec2.Dot(r, dir);
		if (Fix.Abs(value) > Fix.Abs(value2))
		{
			Fix fix2 = (Fix)Fix.Sign(value);
			return startPos + fix2 * (Fix)2L * u * (rr.radius + vec.y + rr.Scale);
		}
		Fix fix3 = (Fix)Fix.Sign(value2);
		return startPos + fix3 * (Fix)2L * r * (rr.radius + vec.x + rr.Scale);
	}

	public void Shoot(Vec2 firepointFIX, Vec2 directionFIX, ref bool hasFired, int playerId, bool alreadyHitWater = false)
	{
		Vec2 vec = firepointFIX;
		Vec2 vec2 = directionFIX;
		AudioManager.Get().PlayWithRandomPitchVariation("fireRaygun");
		AudioManager.Get().PlayRandomWithPrefix("beamSparks");
		UnityEngine.Debug.DrawRay((Vector2)vec, (float)maxDistance * (Vector2)vec2, new UnityEngine.Color(255f, 255f, 0f));
		LayerMask mask = collisionMask;
		if (alreadyHitWater)
		{
			mask = collisionMaskNoWater;
		}
		RaycastInformation raycastInformation = DetPhysics.Get().PointCheckAllRoundedRects(vec);
		if (!alreadyHitWater)
		{
			base.gameObject.SetActive(value: false);
		}
		if (!raycastInformation)
		{
			raycastInformation = DetPhysics.Get().RaycastToClosestTriple(vec, vec2, maxDistance, mask, tripleRaycastRadius);
		}
		if (!alreadyHitWater)
		{
			base.gameObject.SetActive(value: true);
		}
		if ((!alreadyHitWater && firepointFIX.y <= SceneBounds.WaterHeight) || (alreadyHitWater && raycastInformation.layer == LayerMask.NameToLayer("Water")))
		{
			rayParticle.Stop();
			GameObject obj = UnityEngine.Object.Instantiate(WaterRing);
			AudioManager.Get().Play("waterExplosion");
			obj.transform.position = new Vector3(WaterRing.transform.position.x + (float)raycastInformation.nearPos.x, WaterRing.transform.position.y, WaterRing.transform.position.z);
			raycastInformation.layer = LayerMask.NameToLayer("Player");
			raycastInformation.pp = GetComponent<DPhysicsBox>().GetPhysicsParent();
			raycastInformation.nearDist = f001;
			raycastInformation.farDist = f001;
			raycastInformation.nearPos = raycastInformation.pp.fixTrans.position;
			raycastInformation.farPos = raycastInformation.pp.fixTrans.position;
			if (!alreadyHitWater)
			{
				vec2 = Vec2.up;
				directionFIX = Vec2.up;
				vec = raycastInformation.nearPos;
				firepointFIX = raycastInformation.nearPos;
			}
		}
		if ((bool)raycastInformation)
		{
			PlayerHandler.Get().GetPlayer(playerId);
			if (raycastInformation.layer == LayerMask.NameToLayer("Water"))
			{
				spawnRayCastEffect((Vector3)vec, (Vector3)vec2, (float)raycastInformation.nearDist, didHit: false, reflected: true);
				rayParticle.Stop();
				vec2 = new Vec2(vec2.x, -vec2.y);
				Shoot(raycastInformation.nearPos, vec2, ref hasFired, playerId, alreadyHitWater: true);
				UnityEngine.Debug.DrawRay((Vector2)raycastInformation.nearPos, (Vector2)(vec2 * maxDistance), UnityEngine.Color.magenta);
				GameObject obj2 = UnityEngine.Object.Instantiate(WaterRing);
				AudioManager.Get().Play("waterExplosion");
				obj2.transform.position = new Vector3(WaterRing.transform.position.x + (float)raycastInformation.nearPos.x, WaterRing.transform.position.y, WaterRing.transform.position.z);
				return;
			}
			spawnRayCastEffect((Vector3)vec, (Vector3)vec2, (float)raycastInformation.nearDist, didHit: true);
			hasFired = true;
			Vec2 position = raycastInformation.pp.fixTrans.position;
			Vec2 nearPos = raycastInformation.nearPos;
			GameObject obj3 = raycastInformation.pp.fixTrans.gameObject;
			Vec2 dir = vec2;
			int layer = raycastInformation.layer;
			ApplyDuplicationEffect(raycastInformation, position, nearPos, obj3, dir, firepointFIX, layer, playerId, ref hasFired);
		}
		else
		{
			spawnRayCastEffect((Vector2)vec, (Vector2)vec2, (float)maxDistance, didHit: false);
		}
		hasFired = true;
	}

	public void ApplyDuplicationEffect(RaycastInformation hit, Vec2 objPos, Vec2 hitPos, GameObject obj, Vec2 dir, Vec2 firepointFIX, int layer, int playerId, ref bool hasFired, bool forceSingleClone = false)
	{
		if (layer == LayerMask.NameToLayer("Projectile"))
		{
			BoplBody component = obj.GetComponent<BoplBody>();
			if (!(component != null))
			{
				Vec2.MulByI(dir);
			}
			else
			{
				Vec2.MulByI(Vec2.NormalizedSafe(component.velocity));
			}
			Fix offset = (Fix)7L * component.Scale;
			Vec2 vec = hitPos;
			ForceArrow forceArrowPrefab = component.ForceArrowPrefab;
			component.ForceArrowPrefab = null;
			int num = 4;
			if (forceSingleClone)
			{
				num = 1;
			}
			for (int i = 0; i < num; i++)
			{
				vec = FanOut(num, dir, objPos, offset, f032, i);
				Vec2 velocity = component.velocity;
				velocity = Vec2.NormalizedSafe(vec - objPos) * (Vec2.Magnitude(velocity) + (Fix)10L);
				BoplBody boplBody = duplicateBoplBody(vec, obj, velocity, i, component.Scale);
				if (forceSingleClone)
				{
					boplBody.velocity = Vec2.MulByNegI(boplBody.StartVelocity) * (Fix)1L;
				}
			}
			component.ForceArrowPrefab = forceArrowPrefab;
		}
		else if (layer == LayerMask.NameToLayer("item") || layer == LayerMask.NameToLayer("Smoke"))
		{
			BoplBody component2 = obj.GetComponent<BoplBody>();
			Item component3 = obj.GetComponent<Item>();
			Vec2 vec2 = Vec2.MulByI(Vec2.NormalizedSafe(component2.velocity));
			Fix fix = component3.duplicate_spacing * component2.Scale;
			Vec2 vec3 = hitPos;
			ForceArrow forceArrowPrefab2 = component2.ForceArrowPrefab;
			component2.ForceArrowPrefab = null;
			int num2 = component3.nrOfClonesWhenDuplicated;
			if (forceSingleClone)
			{
				num2 = 1;
			}
			for (int j = 0; j < num2; j++)
			{
				Vec2 vec4 = component2.velocity;
				if (component3.duplicatePattern == DuplicatePattern.line)
				{
					Fix fix2 = fix * ((Fix)j + Fix.One);
					if (j % 2 == 0)
					{
						vec3 += vec2 * fix2;
					}
					else
					{
						vec3 -= vec2 * fix2;
					}
				}
				else if (component3.duplicatePattern == DuplicatePattern.circle)
				{
					Fix fix3 = (Fix)(j + 1) / (Fix)num2;
					Fix angleRadians = Fix.PiTimes2 * fix3;
					vec3 = hit.pp.fixTrans.position + new Vec2(angleRadians) * fix;
				}
				else if (component3.duplicatePattern == DuplicatePattern.randomCircle)
				{
					Vec2 vec5 = Updater.RandomUnitVector();
					vec3 = hit.pp.fixTrans.position + vec5 * fix;
				}
				else if (component3.duplicatePattern == DuplicatePattern.fan)
				{
					vec3 = FanOut(num2, dir, objPos, fix, component3.duplicate_angle, j);
					vec4 = Vec2.NormalizedSafe(vec3 - objPos) * (Vec2.Magnitude(vec4) + (Fix)10L);
				}
				BoplBody boplBody2 = duplicateBoplBody(vec3, obj, vec4, j, component2.Scale);
				boplBody2.up = component2.up;
				Item component4 = boplBody2.GetComponent<Item>();
				Grenade component5 = boplBody2.GetComponent<Grenade>();
				if (component5 != null)
				{
					component5.Initialize(null);
					component5.DelayedEnableHurtOwner(Fix.Zero);
					component5.hasBeenThrown = false;
					component5.DetonatesOnOwner = true;
					component5.timedExplosion = false;
					component5.selfDestructDelay = component5.detonationTime - (Fix)(j + 1) * (Fix)0.1;
				}
				else if (boplBody2.GetComponent<Missile>() != null)
				{
					boplBody2.up = Vec2.NormalizedSafe(vec4);
				}
				if (component4 != null)
				{
					component4.OwnerId = component3.OwnerId;
				}
				if (forceSingleClone)
				{
					boplBody2.velocity = Vec2.MulByNegI(boplBody2.StartVelocity) * (Fix)1L;
				}
			}
			component2.ForceArrowPrefab = forceArrowPrefab2;
		}
		else if (layer == LayerMask.NameToLayer("RigidBodyAffector"))
		{
			BlackHole component6 = obj.GetComponent<BlackHole>();
			if (!(component6 == null) && !component6.IsDestroyed)
			{
				AudioManager.Get().Play("blackholeNoClap");
				Vec2 pos = objPos + dir * component6.dCircle.radius * (Fix)2L;
				BlackHole component7 = duplicateObjectWithEffect(pos, obj, 0, component6.dCircle.radius * (Fix)0.75, 480).GetComponent<BlackHole>();
				component7.SetMass(component6.GetMass());
				component7.AddForce(component6.GetMass() * dir * (Fix)6L);
			}
		}
		else if (layer == LayerMask.NameToLayer("weapon"))
		{
			int num3 = 3;
			if (forceSingleClone)
			{
				num3 = 1;
			}
			for (int k = 0; k < num3; k++)
			{
				BoplBody component8 = obj.GetComponent<BoplBody>();
				Fix offset2 = (Fix)2L * component8.Scale;
				Fix angle = (Fix)1L;
				Vec2 vec6 = FanOut(num3, dir, objPos, offset2, angle, k);
				Vec2 velocity2 = Vec2.NormalizedSafe(vec6 - objPos) * (Vec2.Magnitude(component8.velocity) + (Fix)15L);
				BoplBody boplBody3 = duplicateBoplBody(vec6, obj, velocity2, k, hit.pp.fixTrans.Scale);
				DynamicAbilityPickup component9 = boplBody3.GetComponent<DynamicAbilityPickup>();
				if (component9 != null && !component9.IsDestroyed && !component9.initSelf)
				{
					component9.initSelf = true;
				}
				if (forceSingleClone)
				{
					boplBody3.velocity = Vec2.MulByNegI(boplBody3.StartVelocity) * (Fix)1L;
				}
			}
		}
		else if (layer == LayerMask.NameToLayer("wall"))
		{
			AudioManager.Get().PlayWithRandomPitchVariation("fireDuplicatorOnPlatform");
			StickyRoundedRectangle component10 = obj.GetComponent<StickyRoundedRectangle>();
			SpawnWallEffect((Vector3)hitPos, component10);
			if (component10.currentDuplicatePlatformEffect != null && !component10.currentDuplicatePlatformEffect.IsDestroyed)
			{
				component10.currentDuplicatePlatformEffect.SelfDestruct();
			}
			if (useOldPlatformBehaviour)
			{
				component10.GetComponent<ShakablePlatform>().AddShake(PlatformShakeDuration, platformShake, 30);
				Vec2 vec7 = hitPos;
				DPhysicsRoundedRect rr = component10.rr;
				Vec2 vec8 = rr.CalcExtents();
				Vec2 right = rr.right;
				Vec2 up = rr.up;
				if (vec8.x < f005 && vec8.y < f005)
				{
					right = Vec2.right;
					up = Vec2.up;
				}
				Fix value = Vec2.Dot(up, dir);
				Fix value2 = Vec2.Dot(right, dir);
				if (Fix.Abs(value) > Fix.Abs(value2))
				{
					Fix fix4 = (Fix)Fix.Sign(value);
					vec7 = rr.position + fix4 * (Fix)2L * up * (rr.radius + vec8.y + rr.Scale);
				}
				else
				{
					Fix fix5 = (Fix)Fix.Sign(value2);
					vec7 = rr.position + fix5 * (Fix)2L * right * (rr.radius + vec8.x + rr.Scale);
				}
				Tools.Debug_DrawPos(vec7, UnityEngine.Color.red, 10f);
				DuplicatePlatformEffect duplicatePlatformEffect = FixTransform.InstantiateFixed(platformEffect, vec7);
				int num4 = -1;
				GunTransform component11 = GetComponent<GunTransform>();
				duplicatePlatformEffect.Initialize(hierarchyNumberOfGunTransform: (!(component11 != null)) ? GetComponent<Orb>().HierarchyNumber : component11.HierarchyNumber, srr: component10, cloneDir: dir, duration: PlatformShakeDuration);
				return;
			}
			Sprite sprite = boulderSprites.GetSprite((int)component10.platformType % boulderSprites.sprites.Count);
			UnityEngine.Color color = component10.GetComponent<SpriteRenderer>().color;
			Vec2 vec9 = hitPos;
			Vec2 vec10 = component10.currentNormal(vec9);
			RoundedRect r = DetPhysics.Get().roundedRects.colliders[DetPhysics.Get().roundedRects.ColliderIndex(component10.rr.pp.instanceId)];
			Fix distNear = (Fix)1000000L;
			Fix distFar = (Fix)2000000L;
