	private Vec2 FanOut(int cloneCount, Vec2 direction, Vec2 pos, Fix offset, Fix angle, int i)
	{
		Vec2 vec = direction;
		switch (cloneCount)
		{
		case 1:
			_ = pos + direction * offset;
			break;
		case 2:
			switch (i)
			{
			case 0:
				vec = Vec2.ComplexMul(direction, new Vec2(angle));
				break;
			case 1:
				vec = Vec2.ComplexMul(direction, new Vec2(-angle));
				break;
			}
			break;
		case 3:
			switch (i)
			{
			case 1:
				vec = Vec2.ComplexMul(direction, new Vec2(angle));
				break;
			case 2:
				vec = Vec2.ComplexMul(direction, new Vec2(-angle));
				break;
			}
			break;
		case 4:
			switch (i)
			{
			case 0:
				vec = Vec2.ComplexMul(direction, new Vec2(angle));
				break;
			case 1:
				vec = Vec2.ComplexMul(direction, new Vec2(-angle));
				break;
			case 2:
				vec = Vec2.ComplexMul(direction, new Vec2(angle * (Fix)3L));
				break;
			case 3:
				vec = Vec2.ComplexMul(direction, new Vec2(-angle * (Fix)3L));
				break;
			}
			break;
		}
		return pos + vec * offset;
	}

	private void SpawnWallEffect(Vector3 pos, StickyRoundedRectangle srr)
	{
		SpriteRenderer spriteRenderer = srr.GetSpriteRenderer();
		ParticleSystem particleSystem = UnityEngine.Object.Instantiate(wallSparkParticlePrefab, pos, Quaternion.identity);
		Vector2 vector = Vector2.one;
		bool flag = srr.CompareTag("ResizablePlatform");
		float num = 1f;
		if (flag)
		{
			vector = new Vector2(1f / srr.transform.localScale.x, 1f / srr.transform.localScale.y);
			Vec2 vec = srr.rr.CalcExtents();
			vec += new Vec2(srr.rr.radius, srr.rr.radius);
			num = (float)vec.x / (float)vec.y;
		}
		ParticleSystem.ShapeModule shape = particleSystem.shape;
		shape.spriteRenderer = spriteRenderer;
		shape.shapeType = ParticleSystemShapeType.SpriteRenderer;
		ParticleSystem.MainModule main = particleSystem.main;
		main.duration = (float)PlatformShakeDuration;
		main.loop = false;
		main.startSizeX = main.startSizeX.constant * vector.x;
		main.startSizeY = main.startSizeY.constant * vector.y;
		if (flag)
		{
			Vector3 scale = shape.scale;
			if (num > 1f)
			{
				scale.y /= num;
			}
			else
			{
				scale.x *= num;
			}
			shape.scale = scale;
		}
		ParticleSystem component = particleSystem.transform.GetChild(0).GetComponent<ParticleSystem>();
		ParticleSystem.ShapeModule shape2 = component.shape;
		shape2.spriteRenderer = spriteRenderer;
		shape2.shapeType = ParticleSystemShapeType.SpriteRenderer;
		ParticleSystem.MainModule main2 = component.main;
		main2.duration = (float)PlatformShakeDuration;
		main2.loop = false;
		main2.startSizeX = main2.startSizeX.constant * vector.x;
		main2.startSizeY = main2.startSizeY.constant * vector.y;
		if (flag)
		{
			Vector3 scale2 = shape2.scale;
			if (num > 1f)
			{
				scale2.y /= num;
			}
			else
			{
				scale2.x *= num;
			}
			shape2.scale = scale2;
		}
		particleSystem.Play();
	}

	private BoplBody duplicateBoplBody(Vec2 pos, GameObject original, Vec2 velocity, int index, Fix scale)
	{
		if (index >= 0)
		{
			onSpawnParticle[index].transform.localScale = onSpawnParticlePrefab.transform.localScale * (float)scale;
			onSpawnParticle[index].transform.position = (Vector3)pos;
			onSpawnParticle[index].Play();
		}
		GameObject obj = DuplicateObject(pos, original);
		BoplBody component = obj.GetComponent<BoplBody>();
		DPhysicsCircle component2 = obj.GetComponent<DPhysicsCircle>();
		DPhysicsBox component3 = obj.GetComponent<DPhysicsBox>();
		if (component2 != null)
		{
			DPhysicsCircle component4 = original.GetComponent<DPhysicsCircle>();
			component2.radius = component4.radius / component4.Scale;
		}
		else if (component3 != null)
		{
			DPhysicsBox component5 = original.GetComponent<DPhysicsBox>();
			Vec2 vec = component5.CalcExtents();
			component3.SetExtents(vec / component5.Scale);
		}
		component.velocity = velocity;
		component.Scale = scale;
		component.rotation = original.GetComponent<BoplBody>().rotation;
		return component;
	}

	private GameObject duplicateObjectWithEffect(Vec2 pos, GameObject obj, int index, Fix scale, int lifespan = 1800)
	{
		onSpawnParticle[index].transform.localScale = onSpawnParticlePrefab.transform.localScale * (float)scale;
		onSpawnParticle[index].transform.position = (Vector3)pos;
		onSpawnParticle[index].Play();
		return DuplicateObject(pos, obj, lifespan);
	}

	public static GameObject DuplicateObject(Vec2 pos, GameObject obj, int lifespan = 1800, bool allowOnlyASingleCopyWithInifinteLifespan = false, int spawnerHierarchyNumber = -1)
	{
		MonoUpdatable[] componentsInChildren = obj.GetComponentsInChildren<MonoUpdatable>();
		Array.Sort(componentsInChildren, Updater.updateComparer);
		int num = 1;
		MonoUpdatable[] array = componentsInChildren;
		foreach (MonoUpdatable monoUpdatable in array)
		{
			updatableIdBuffer.Add(monoUpdatable.HierarchyNumber);
			monoUpdatable.HierarchyNumber = num;
			num++;
		}
		ForceArrow forceArrowPrefab = null;
		BoplBody component = obj.GetComponent<BoplBody>();
		if (component != null)
		{
			forceArrowPrefab = component.ForceArrowPrefab;
			component.ForceArrowPrefab = null;
		}
		GameObject gameObject = FixTransform.InstantiateFixed(obj, pos);
		if (component != null)
		{
			component.ForceArrowPrefab = forceArrowPrefab;
			gameObject.GetComponent<BoplBody>().ForceArrowPrefab = forceArrowPrefab;
		}
		Vector3 startScale = obj.GetComponent<FixTransform>().startScale;
		FixTransform component2 = gameObject.GetComponent<FixTransform>();
		component2.startScale = startScale;
		if (component2 != null)
		{
			if (allowOnlyASingleCopyWithInifinteLifespan)
			{
				DetPhysics.Get().AddObjectToDeleteList_lifespanUntilCalledAgain(component2, spawnerHierarchyNumber);
			}
			else
			{
				DetPhysics.Get().AddObjectToDeleteList(component2, lifespan);
			}
		}
		num = 0;
		array = componentsInChildren;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].HierarchyNumber = updatableIdBuffer[num];
			num++;
		}
		updatableIdBuffer.Clear();
		return gameObject;
	}

	public void spawnRayCastEffect(Vector2 start, Vector2 dir, float dist, bool didHit, bool reflected = false)
	{
		ParticleSystem.ShapeModule shape = rayParticle.shape;
		ParticleSystem.EmissionModule emission = rayParticle.emission;
		ParticleSystem.Burst burst = emission.GetBurst(0);
		shape.radius = (dist + trailEffectOffset) * 0.5f;
		rayParticle.transform.position = start + dir * dist * 0.5f;
		rayParticle.transform.right = dir;
		burst.count = Mathf.Max(dist * 0.5f, 2f);
		emission.SetBurst(0, burst);
		onHitParticle.transform.position = start + dir * dist;
		if (reflected)
		{
			rayParticle.Simulate(0.11f);
		}
		rayParticle.Play();
		onHitParticle.Play();
	}
}
