}
public class ShootQuantum : MonoBehaviour, IGun
{
	private Fix maxDistance = (Fix)100L;

	public LayerMask collisionMask;

	public float raycastEffectSpacing;

	public GameObject WaterExplosion;

	public GameObject WaterRing;

	public GameObject RayCastEffect;

	public QuantumTunnel QuantumTunnelPrefab;

	public ParticleSystem RaycastParticlePrefab;

	public ParticleSystem RaycastParticleHitPrefab;

	public Fix minPlayerDuration;

	public Fix WallDuration = (Fix)3L;

	public Fix WallDelay = (Fix)1f;

	public Fix WallShake = (Fix)1f;

	public Material onHitWallMaterail;

	public Material onHitResizableWallMaterail;

	public Material onDissapearResizableWallMaterail;

	public Material onHitBlackHoleMaterial;

	private static List<QuantumTunnel> spawnedQuantumTunnels = new List<QuantumTunnel>();

	private ParticleSystem rayParticle;

	private ParticleSystem hitParticle;

	private ParticleSystem rayParticle2;

	private float rayDensity;

	private Ability ability;

	private Fix baseCD;

	public Fix onPlayerHitCD;

	private void Awake()
	{
		ability = GetComponent<Ability>();
		if (ability != null)
		{
			baseCD = ability.Cooldown;
		}
		rayParticle = UnityEngine.Object.Instantiate(RaycastParticlePrefab);
		hitParticle = UnityEngine.Object.Instantiate(RaycastParticleHitPrefab);
		rayParticle2 = UnityEngine.Object.Instantiate(RaycastParticlePrefab);
		rayDensity = rayParticle.emission.GetBurst(0).count.constant / rayParticle.shape.scale.x;
	}

	public void Shoot(Vec2 firepointFIX, Vec2 directionFIX, ref bool hasFired, int playerId, bool alreadyHitWater = false)
	{
		Vec2 vec = firepointFIX;
		Vec2 vec2 = directionFIX;
		AudioManager.Get().Play("laserShoot");
		UnityEngine.Debug.DrawRay((Vector2)vec, (float)maxDistance * (Vector2)vec2, new UnityEngine.Color(255f, 255f, 0f));
		if (!alreadyHitWater)
		{
			base.gameObject.SetActive(value: false);
		}
		RaycastInformation raycastInformation = DetPhysics.Get().PointCheckAllRoundedRects(vec);
		if (!raycastInformation)
		{
			raycastInformation = DetPhysics.Get().RaycastToClosest(vec, vec2, maxDistance, collisionMask);
		}
		if (!alreadyHitWater)
		{
			base.gameObject.SetActive(value: true);
		}
		if ((!alreadyHitWater && firepointFIX.y <= SceneBounds.WaterHeight) || (alreadyHitWater && raycastInformation.layer == LayerMask.NameToLayer("Water")))
		{
			spawnRayCastEffect((Vector3)vec, (Vector3)vec2, (float)raycastInformation.nearDist, didHit: false, Vec2.up, reflected: true);
			rayParticle.Stop();
			GameObject obj = UnityEngine.Object.Instantiate(WaterRing);
			AudioManager.Get().Play("waterExplosion");
			obj.transform.position = new Vector3(WaterRing.transform.position.x + (float)raycastInformation.nearPos.x, WaterRing.transform.position.y, WaterRing.transform.position.z);
			raycastInformation.layer = LayerMask.NameToLayer("Player");
			raycastInformation.pp = GetComponent<DPhysicsBox>().GetPhysicsParent();
			raycastInformation.nearDist = (Fix)0.1;
			raycastInformation.farDist = (Fix)0.1;
			raycastInformation.nearPos = raycastInformation.pp.fixTrans.position;
			raycastInformation.farPos = raycastInformation.pp.fixTrans.position;
			if (!alreadyHitWater)
			{
				vec2 = Vec2.up;
				directionFIX = Vec2.up;
				vec = raycastInformation.nearPos;
				firepointFIX = raycastInformation.nearPos;
			}
		}
		if ((bool)raycastInformation)
		{
			Vec2 normal = Vec2.NormalizedSafe(raycastInformation.pp.monobehaviourCollider.NormalAtPoint(raycastInformation.nearPos));
			BlinkObject(raycastInformation, vec, vec2, normal, ref hasFired, playerId, alreadyHitWater = false);
		}
		else
		{
			spawnRayCastEffect((Vector2)vec, (Vector2)vec2, (float)maxDistance, didHit: false, Vec2.up);
		}
		hasFired = true;
	}

	public void BlinkObject(RaycastInformation hit, Vec2 firepoint, Vec2 direction, Vec2 normal, ref bool hasFired, int playerId, bool alreadyHitWater = false)
	{
		if (hit.layer == LayerMask.NameToLayer("Water") && !alreadyHitWater)
		{
			spawnRayCastEffect((Vector3)firepoint, (Vector3)direction, (float)hit.nearDist, didHit: false, normal, reflected: true);
			rayParticle.Stop();
			direction = new Vec2(direction.x, direction.y * -Fix.One);
			Shoot(hit.nearPos, direction, ref hasFired, playerId, alreadyHitWater: true);
			UnityEngine.Debug.DrawRay((Vector2)hit.nearPos, (Vector2)(direction * maxDistance), UnityEngine.Color.magenta);
			GameObject obj = UnityEngine.Object.Instantiate(WaterRing);
			AudioManager.Get().Play("waterExplosion");
			obj.transform.position = new Vector3(WaterRing.transform.position.x + (float)hit.nearPos.x, WaterRing.transform.position.y, WaterRing.transform.position.z);
			return;
		}
		if (hit.layer == LayerMask.NameToLayer("EffectorZone") || hit.layer == LayerMask.NameToLayer("weapon"))
		{
			spawnRayCastEffect((Vector2)firepoint, (Vector2)direction, (float)hit.nearDist, didHit: true, normal);
			GameObject victim = hit.pp.fixTrans.gameObject;
			QuantumTunnel quantumTunnel = FixTransform.InstantiateFixed(QuantumTunnelPrefab, hit.pp.fixTrans.position);
			if (!hit.pp.fixTrans.gameObject.CompareTag("InvincibilityZone"))
			{
				quantumTunnel.Init(victim, WallDuration);
			}
			return;
		}
		spawnRayCastEffect((Vector2)firepoint, (Vector2)direction, (float)hit.nearDist, didHit: true, normal);
		if (hit.layer == LayerMask.NameToLayer("orb"))
		{
			Orb component = hit.pp.fixTrans.GetComponent<Orb>();
			if (component.orbType != Orb.OrbType.blink)
			{
				component.SetOrbType(Orb.OrbType.blink);
				spawnRayCastEffect((Vector2)firepoint, (Vector2)direction, (float)hit.nearDist, didHit: true, normal);
				return;
			}
		}
		GameObject gameObject = hit.pp.fixTrans.gameObject;
		QuantumTunnel quantumTunnel2 = null;
		for (int i = 0; i < spawnedQuantumTunnels.Count; i++)
		{
			if (spawnedQuantumTunnels[i].Victim.GetInstanceID() == gameObject.GetInstanceID())
			{
				quantumTunnel2 = spawnedQuantumTunnels[i];
			}
		}
		if (quantumTunnel2 == null)
		{
			quantumTunnel2 = FixTransform.InstantiateFixed(QuantumTunnelPrefab, hit.pp.fixTrans.position);
			spawnedQuantumTunnels.Add(quantumTunnel2);
		}
		if (ability != null)
		{
			ability.Cooldown = baseCD;
		}
		if (gameObject.layer == LayerMask.NameToLayer("wall"))
		{
			ShakablePlatform component2 = gameObject.GetComponent<ShakablePlatform>();
			if (gameObject.CompareTag("ResizablePlatform"))
			{
				Material material = onHitResizableWallMaterail;
				gameObject.GetComponent<SpriteRenderer>();
				DPhysicsRoundedRect component3 = gameObject.GetComponent<DPhysicsRoundedRect>();
				material.SetFloat("_Scale", gameObject.transform.localScale.x);
				material.SetFloat("_BevelRadius", (float)component3.radius);
				Vec2 vec = component3.CalcExtents();
				material.SetFloat("_RHeight", (float)vec.y);
				material.SetFloat("_RWidth", (float)vec.x);
				component2.AddShake(WallDelay, WallShake, 10, material);
				quantumTunnel2.DelayedInit(gameObject, WallDuration, WallDelay, onDissapearResizableWallMaterail);
			}
			else
			{
				component2.AddShake(WallDelay, WallShake, 10, onHitWallMaterail);
				quantumTunnel2.DelayedInit(gameObject, WallDuration, WallDelay);
			}
		}
		else if (gameObject.layer == LayerMask.NameToLayer("RigidBodyAffector"))
		{
			if (gameObject.GetComponent<BlackHole>() != null)
			{
				quantumTunnel2.Init(gameObject, WallDuration, onHitBlackHoleMaterial);
			}
			else
			{
				quantumTunnel2.Init(gameObject, WallDuration);
			}
		}
		else if (gameObject.layer == LayerMask.NameToLayer("Player"))
		{
			if (ability != null)
			{
				ability.Cooldown = onPlayerHitCD;
			}
			IPlayerIdHolder component4 = gameObject.GetComponent<IPlayerIdHolder>();
			Player player = PlayerHandler.Get().GetPlayer(component4.GetPlayerId());
			if (player != null)
			{
				_ = player.timesHitByBlinkgunThisRound;
				player.timesHitByBlinkgunThisRound++;
			}
			Fix lifeSpan = Fix.Max(minPlayerDuration, (Fix)0.3 * WallDuration);
			quantumTunnel2.Init(gameObject, lifeSpan, null, isPlayer: true);
		}
		else
		{
			quantumTunnel2.Init(gameObject, WallDuration);
		}
	}

	public void spawnRayCastEffect(Vector2 start, Vector2 dir, float dist, bool didHit, Vec2 normal, bool reflected = false)
	{
		ParticleSystem obj = (reflected ? rayParticle2 : rayParticle);
		ParticleSystem.ShapeModule shape = obj.shape;
		ParticleSystem.EmissionModule emission = obj.emission;
		ParticleSystem.Burst burst = emission.GetBurst(0);
		shape.scale = new Vector3(dist, shape.scale.y, shape.scale.z);
		obj.transform.right = dir;
		obj.transform.position = start + dir * dist * 0.5f;
		burst.count = dist * rayDensity;
		emission.SetBurst(0, burst);
		obj.Play();
		if (reflected)
		{
			hitParticle.transform.position = start + dir * dist;
			hitParticle.transform.up = (Vector3)normal;
			hitParticle.Simulate(0.16f);
			hitParticle.Play();
		}
		if (didHit)
		{
			hitParticle.Stop();
			hitParticle.transform.position = start + dir * dist;
			hitParticle.transform.up = (Vector3)normal;
			hitParticle.Play();
		}
	}
}
public class ShootScaleChange : MonoBehaviour, IGun
{
	private Fix maxDistance = (Fix)100L;

	public LayerMask collisionMask;

	public LayerMask collisionMaskNoWater;

	public float raycastEffectSpacing;

	public GameObject WaterExplosion;

	public GameObject WaterRing;

	public GameObject RayCastEffect;

	public ScaleChanger ScaleChangerPrefab;

	public GrowthFlare flarePrefab;

	public Fix blackHoleGrowthInverse01 = Fix.One;

	public ParticleSystem RaycastParticlePrefab;

	public ParticleSystem RaycastParticleHitPrefab;

	private ParticleSystem rayParticle;

	private ParticleSystem rayParticleChild;

	private ParticleSystem hitParticle;

	private GrowthFlare growthFlare;

	private float rayDensity;

	private float rayDensityChild;

	private void Awake()
	{
		rayParticle = UnityEngine.Object.Instantiate(RaycastParticlePrefab);
		rayParticleChild = rayParticle.transform.GetChild(0).GetComponent<ParticleSystem>();
		hitParticle = UnityEngine.Object.Instantiate(RaycastParticleHitPrefab);
		growthFlare = UnityEngine.Object.Instantiate(flarePrefab);
		growthFlare.gameObject.SetActive(value: false);
		rayDensity = rayParticle.emission.GetBurst(0).count.constant / rayParticle.shape.scale.x;
		rayDensityChild = rayParticleChild.emission.GetBurst(0).count.constant / rayParticleChild.shape.scale.x;
	}

	private void OnDestroy()
	{
		if (rayParticle != null)
		{
			UnityEngine.Object.Destroy(rayParticle.gameObject);
		}
		if (hitParticle != null)
		{
			UnityEngine.Object.Destroy(hitParticle.gameObject);
		}
		if (growthFlare != null)
		{
			UnityEngine.Object.Destroy(growthFlare.gameObject);
		}
	}

	public void Shoot(Vec2 firepointFIX, Vec2 directionFIX, ref bool hasFired, int playerId, bool alreadyHitWater = false)
	{
		Vec2 vec = firepointFIX;
		Vec2 vec2 = directionFIX;
		AudioManager.Get().Play("fireRaygun");
		UnityEngine.Debug.DrawRay((Vector2)vec, (float)maxDistance * (Vector2)vec2, new UnityEngine.Color(255f, 255f, 0f));
		LayerMask mask = collisionMask;
		if (alreadyHitWater)
		{
			mask = collisionMaskNoWater;
		}
		RaycastInformation raycastInformation = DetPhysics.Get().PointCheckAllRoundedRects(vec);
		if (!raycastInformation)
		{
			raycastInformation = DetPhysics.Get().RaycastToClosest(vec, vec2, maxDistance, mask);
		}
		if ((!alreadyHitWater && firepointFIX.y <= SceneBounds.WaterHeight) || (alreadyHitWater && raycastInformation.layer == LayerMask.NameToLayer("Water")))
		{
			rayParticle.Stop();
			GameObject obj = UnityEngine.Object.Instantiate(WaterRing);
			AudioManager.Get().Play("waterExplosion");
			obj.transform.position = new Vector3(WaterRing.transform.position.x + (float)raycastInformation.nearPos.x, WaterRing.transform.position.y, WaterRing.transform.position.z);
			raycastInformation.layer = LayerMask.NameToLayer("Player");
			raycastInformation.pp = GetComponent<DPhysicsBox>().GetPhysicsParent();
			raycastInformation.nearDist = (Fix)0.1;
			raycastInformation.farDist = (Fix)0.1;
			raycastInformation.nearPos = raycastInformation.pp.fixTrans.position;
			raycastInformation.farPos = raycastInformation.pp.fixTrans.position;
			if (!alreadyHitWater)
			{
				vec2 = Vec2.up;
				directionFIX = Vec2.up;
				vec = raycastInformation.nearPos;
				firepointFIX = raycastInformation.nearPos;
			}
		}
		if ((bool)raycastInformation)
		{
			Player player = PlayerHandler.Get().GetPlayer(playerId);
			if (!AchievementHandler.IsAchieved(AchievementHandler.AchievementEnum.GrowthRayYourself) && blackHoleGrowthInverse01 > 0L && raycastInformation.layer == LayerMask.NameToLayer("Player") && raycastInformation.pp.fixTrans.GetComponent<IPlayerIdHolder>().GetPlayerId() == playerId && player != null && player.IsLocalPlayer)
			{
				AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.GrowthRayYourself);
			}
			ApplyScaleChange(raycastInformation, vec, vec2, ref hasFired, playerId);
		}
		else
		{
			spawnRayCastEffect((Vector2)vec, (Vector2)vec2, (float)maxDistance, didHit: false);
		}
		hasFired = true;
	}

	public void ApplyScaleChange(RaycastInformation hit, Vec2 firepoint, Vec2 direction, ref bool hasFired, int playerId)
	{
		if (hit.layer == LayerMask.NameToLayer("Water"))
		{
			spawnRayCastEffect((Vector3)firepoint, (Vector3)direction, (float)hit.nearDist, didHit: false, reflected: true);
			rayParticle.Stop();
			direction = new Vec2(direction.x, direction.y * -Fix.One);
			Shoot(hit.nearPos, direction, ref hasFired, playerId, alreadyHitWater: true);
			UnityEngine.Debug.DrawRay((Vector2)hit.nearPos, (Vector2)(direction * maxDistance), UnityEngine.Color.magenta);
			GameObject obj = UnityEngine.Object.Instantiate(WaterRing);
			AudioManager.Get().Play("waterExplosion");
			obj.transform.position = new Vector3(WaterRing.transform.position.x + (float)hit.nearPos.x, WaterRing.transform.position.y, WaterRing.transform.position.z);
			return;
		}
		if (hit.layer == LayerMask.NameToLayer("RigidBodyAffector"))
		{
			spawnRayCastEffect((Vector3)firepoint, (Vector3)direction, (float)hit.nearDist, didHit: true);
			hit.pp.fixTrans.gameObject.GetComponent<BlackHole>()?.Grow(blackHoleGrowthInverse01, Fix.Zero);
		}
		else
		{
			spawnRayCastEffect((Vector3)firepoint, (Vector3)direction, (float)hit.nearDist, didHit: true);
			if (hit.layer == LayerMask.NameToLayer("orb"))
			{
				Orb component = hit.pp.fixTrans.GetComponent<Orb>();
				bool flag = ScaleChangerPrefab.multiplier > Fix.Zero;
				if ((component.orbType != Orb.OrbType.shrink || flag) && !(component.orbType == Orb.OrbType.grow && flag))
				{
					component.SetOrbType(flag ? Orb.OrbType.grow : Orb.OrbType.shrink);
					return;
				}
			}
			GameObject obj2 = hit.pp.fixTrans.gameObject;
			ScaleChanger scaleChanger = FixTransform.InstantiateFixed(ScaleChangerPrefab, Vec2.zero);
			scaleChanger.victim = hit.pp.monobehaviourCollider;
			if (hit.pp.fixTrans.gameObject.layer == LayerMask.NameToLayer("spell"))
			{
				scaleChanger.spell = hit.pp.fixTrans.GetComponent<ISpell>();
			}
			Ability component2 = obj2.GetComponent<Ability>();
			if (component2 != null)
			{
				scaleChanger.player = PlayerHandler.Get().GetPlayer(component2.GetPlayerId());
			}
			SlimeController component3 = obj2.GetComponent<SlimeController>();
			if (component3 != null)
			{
				scaleChanger.player = PlayerHandler.Get().GetPlayer(component3.GetPlayerId());
			}
			SpriteRenderer spriteRenderer = hit.pp.fixTrans?.GetComponent<SpriteRenderer>();
			if (spriteRenderer != null)
			{
				growthFlare.Init(spriteRenderer);
			}
		}
		if (blackHoleGrowthInverse01 > 0L)
		{
			AudioManager.Get().Play("grow");
		}
		else
		{
			AudioManager.Get().Play("shrink");
		}
	}

	public void spawnRayCastEffect(Vector2 start, Vector2 dir, float dist, bool didHit, bool reflected = false)
	{
		ParticleSystem.ShapeModule shape = rayParticle.shape;
		ParticleSystem.EmissionModule emission = rayParticle.emission;
		ParticleSystem.Burst burst = emission.GetBurst(0);
		shape.scale = new Vector3(dist, shape.scale.y, shape.scale.z);
		rayParticle.transform.right = dir;
		rayParticle.transform.position = start + dir * dist * 0.5f;
		burst.count = dist * rayDensity;
		emission.SetBurst(0, burst);
		ParticleSystem.ShapeModule shape2 = rayParticleChild.shape;
		ParticleSystem.EmissionModule emission2 = rayParticleChild.emission;
		ParticleSystem.Burst burst2 = emission2.GetBurst(0);
		shape2.scale = new Vector3(dist, shape2.scale.y, shape2.scale.z);
		burst2.count = dist * rayDensityChild;
		emission2.SetBurst(0, burst2);
		if (reflected)
		{
			rayParticle.Simulate(0.16f);
		}
		rayParticle.Play();
		if (didHit)
		{
			hitParticle.transform.position = start + dir * dist;
			hitParticle.Play();
		}
	}
}
public class SimpleSparkNode : MonoUpdatable, IPlayerIdHolder, IPlatformAttachable
{
	[SerializeField]
	private GameObject lightningPrefab;

	[SerializeField]
	private Fix lightningLineLength;

	[SerializeField]
	private AnimationCurve ScaleAnim;

	private DPhysicsCircle hitbox;

	public SpriteRenderer[] LitOrbs;

	public SpriteAnimator OrbAnimation;

	public AnimationData OrbAnimationData;

	private int id;

	[NonSerialized]
	public SimpleSparkNode childNode;

	private SimpleSparkNode parentNode;

	private UnityEngine.Color origColor;

	private DPhysicsBox lightningLine;

	private FixTransform lightningLineFixTrans;

	private bool isConnected;

	private FixTransform fixTrans;

	private float originalFlareScale = 1f;

	public bool InitializedWithAParent;

	[NonSerialized]
	public Fix startScale;

	private StickyRoundedRectangle attachedGround;

	private float timeSinceActivated;

	private Fix prevScale = Fix.One;

	public Fix hitBoxOffsetY = Fix.One;

	private Fix _hitBoxOffsetY;

	public Fix SurfaceOffset { get; private set; }

	public Fix LocalPlatformPosition { get; private set; }

	public bool CanConnect()
	{
		if (childNode != null)
		{
			return childNode.gameObject.activeInHierarchy;
		}
		return false;
	}

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		hitbox = GetComponent<DPhysicsCircle>();
		origColor = LitOrbs[0].color;
		LitOrbs[0].enabled = false;
		LitOrbs[1].enabled = false;
		isConnected = false;
		originalFlareScale = LitOrbs[1].transform.localScale.x;
		fixTrans = GetComponent<FixTransform>();
	}

	public void Initialize(int ownerId, SimpleSparkNode childNode, Fix surfaceOffset, Fix localPlatformPosition, StickyRoundedRectangle attachedGround, Fix startScale, bool skipInit = false)
	{
		this.startScale = Fix.Clamp(startScale, hitbox.MinScale, hitbox.MaxScale);
		id = ownerId;
		this.childNode = childNode;
		if (childNode != null)
		{
			childNode.parentNode = this;
			childNode.InitializedWithAParent = true;
		}
		isConnected = false;
		LocalPlatformPosition = localPlatformPosition;
		SurfaceOffset = surfaceOffset;
		if (!skipInit)
		{
			hitbox.ManualInit();
		}
		this.attachedGround = attachedGround;
		SurfaceOffset *= startScale;
		_hitBoxOffsetY = hitBoxOffsetY * startScale;
		hitbox.Scale = startScale;
		prevScale = startScale;
		fixTrans.startScale = new Vector3(fixTrans.startScale.x / attachedGround.transform.localScale.x, fixTrans.startScale.y / attachedGround.transform.localScale.y, 1f);
		base.transform.localScale = new Vector3((float)startScale / attachedGround.transform.localScale.x, (float)startScale / attachedGround.transform.localScale.y, 1f);
		DetPhysics.Get().AddCircleToRR(base.gameObject.GetInstanceID(), attachedGround.gameObject.GetInstanceID());
		RepositionOnParent();
	}

	public void ActivateLightning()
	{
		if (lightningLine != null)
		{
			lightningLine.gameObject.SetActive(value: true);
		}
		AudioManager.Get().Play("lightning");
		base.gameObject.layer = LayerMask.NameToLayer("LethalTerrain");
		hitbox.UpdateLayer();
		OrbAnimation.beginAnimThenDoAction(OrbAnimationData.GetAnimation("TransitionOrb"), LoopOrb);
	}

	private void LoopOrb()
	{
		LitOrbs[0].color = UnityEngine.Color.white;
		OrbAnimation.beginAnimation(OrbAnimationData.GetAnimation("LoopOrb"));
	}

	private void ActivatePartnerLightning()
	{
		childNode.gameObject.layer = LayerMask.NameToLayer("LethalTerrain");
		childNode.hitbox.UpdateLayer();
		childNode.OrbAnimation.beginAnimThenDoAction(OrbAnimationData.GetAnimation("TransitionOrb"), childNode.LoopOrb);
	}

	public override void OnDestroyUpdatable()
	{
		if (isConnected)
		{
			Deactivate();
		}
		if (parentNode != null && parentNode.isConnected)
		{
			parentNode.Deactivate();
		}
	}

	private void Deactivate()
	{
		isConnected = false;
		if (lightningLine != null)
		{
			Updater.DestroyFix(lightningLine.gameObject);
		}
		if (!base.IsDestroyed)
		{
			for (int i = 0; i < LitOrbs.Length; i++)
			{
				LitOrbs[i].enabled = false;
			}
			base.gameObject.layer = LayerMask.NameToLayer("NonLethalTerrain");
			hitbox.UpdateLayer();
		}
		if (!(childNode != null))
		{
			return;
		}
		childNode.isConnected = false;
		if (childNode.lightningLine != null)
		{
			Updater.DestroyFix(childNode.lightningLine.gameObject);
		}
		if (!childNode.IsDestroyed)
		{
			for (int j = 0; j < childNode.LitOrbs.Length; j++)
			{
				childNode.LitOrbs[j].enabled = false;
			}
			childNode.gameObject.layer = LayerMask.NameToLayer("NonLethalTerrain");
			childNode.hitbox.UpdateLayer();
		}
	}

	private void ConnectToPartner()
	{
		isConnected = true;
		childNode.isConnected = true;
		LitOrbs[0].color = origColor;
		childNode.LitOrbs[0].color = origColor;
		timeSinceActivated = 0f;
		childNode.timeSinceActivated = 0f;
		OrbAnimation.beginAnimThenDoAction(OrbAnimationData.GetAnimation("EnterOrb"), ActivateLightning);
		childNode.OrbAnimation.beginAnimThenDoAction(OrbAnimationData.GetAnimation("EnterOrb"), ActivatePartnerLightning);
		for (int i = 0; i < LitOrbs.Length; i++)
		{
			LitOrbs[i].enabled = true;
		}
		for (int j = 0; j < childNode.LitOrbs.Length; j++)
		{
			childNode.LitOrbs[j].enabled = true;
		}
		Vec2.Distance(childNode.hitbox.position, hitbox.position);
		Vec2 up = Vec2.NormalizedSafe(childNode.hitbox.position - hitbox.position);
		GameObject gameObject = FixTransform.InstantiateFixed(lightningPrefab, hitbox.position);
		gameObject.SetActive(value: false);
		lightningLine = gameObject.GetComponent<DPhysicsBox>();
		lightningLineFixTrans = gameObject.GetComponent<FixTransform>();
		lightningLineFixTrans.up = up;
		UpdateLightningLine();
		lightningLineFixTrans.SyncTransform();
		AudioManager.Get().Play("loadLightning");
		lightningLine.GetComponent<StretchableLightning>().InitLightning(id);
	}

	public override bool IsEnabled()
	{
		return true;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (fixTrans.Scale != prevScale)
		{
			Fix fix = fixTrans.Scale / prevScale;
			SurfaceOffset *= fix;
			_hitBoxOffsetY *= fix;
			prevScale = fixTrans.Scale;
		}
		if (childNode != null && isConnected && !CanConnect())
		{
			Deactivate();
		}
		if (isConnected && parentNode != null && !parentNode.gameObject.activeInHierarchy)
		{
			parentNode.Deactivate();
		}
		if (!isConnected && CanConnect() && base.gameObject.activeInHierarchy)
		{
			ConnectToPartner();
		}
		if (isConnected && lightningLine != null)
		{
			if (childNode == null)
			{
				Updater.DestroyFix(lightningLine.gameObject);
			}
			else
			{
				UpdateLightningLine();
			}
		}
		if (!isConnected && base.gameObject.layer == LayerMask.NameToLayer("LethalTerrain"))
		{
			base.gameObject.layer = LayerMask.NameToLayer("NonLethalTerrain");
			hitbox.UpdateLayer();
		}
	}

	private void Update()
	{
		timeSinceActivated += Time.deltaTime * (float)GameTime.PlayerTimeScale;
		float num = ScaleAnim.Evaluate(timeSinceActivated) * originalFlareScale;
		LitOrbs[1].transform.localScale = new Vector3(num, num, 1f);
	}

	private void UpdateLightningLine()
	{
		Vec2 vec = hitbox.position + hitbox.up * _hitBoxOffsetY;
		Vec2 vec2 = childNode.hitbox.position + childNode.hitbox.up * childNode._hitBoxOffsetY - vec;
		Fix fix = Vec2.Magnitude(vec2);
		Vec2 vec3 = ((fix != 0L) ? (vec2 / fix) : Vec2.up);
		Vec2 up = new Vec2(-vec3.y, vec3.x);
		lightningLineFixTrans.position = vec + vec2 * (Fix)0.5f;
		lightningLineFixTrans.up = up;
		Fix fix2 = Fix.Max(fix / lightningLineLength, (Fix)0.01f);
		Vec2 vec4 = lightningLine.CalcExtents();
		lightningLine.SetExtents(new Vec2(fix * (Fix)0.5f, vec4.y));
		lightningLine.transform.localScale = new Vector3((float)fix2, lightningLine.transform.localScale.y, lightningLine.transform.localScale.z);
	}

	public void SetPlayerId(int id)
	{
		this.id = id;
	}

	public int GetPlayerId()
	{
		return id;
	}

	public Material GetPlayerMaterial()
	{
		return null;
	}

	public void SetLocalPlatformPos(Fix localPlatformPos)
	{
		LocalPlatformPosition = localPlatformPos;
		RepositionOnParent();
	}

	public void RepositionOnParent()
	{
		if (!(attachedGround == null) && !attachedGround.IsDestroyed)
		{
			Vec2 vec = attachedGround.PositionFromLocalPlayerPos(LocalPlatformPosition, Fix.Zero);
			if (hitbox != null && !hitbox.IsDestroyed)
			{
				vec += hitbox.up * SurfaceOffset;
				Vec2 vec2 = new Vec2(Fix.PiTimes2 - attachedGround.rr.rotation);
				Vec2 relativePos = Vec2.ComplexMul(vec2, vec - attachedGround.rr.position);
				Vec2 relativeRightVector = Vec2.ComplexMul(hitbox.right, vec2);
				hitbox.SetRelativePositionOfChildBody(relativePos, relativeRightVector);
			}
		}
	}
}
public class SparkShot : MonoUpdatable, IAbilityComponent
{
	public enum State
	{
		Enter,
		Idle,
		Right,
		Left,
		InTransition,
		Exit
	}

	[SerializeField]
	private AnimationData animData;

	[SerializeField]
	private BoplBody SparkPrefab;

	[SerializeField]
	private Explosion ExplosionPrefab;

	[SerializeField]
	private Vec2 projectileOffset;

	private BoplBody sparkBody;

	private Missile missile;

	private PlayerInfo playerInfo;

	private Player player;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private DPhysicsBox hurtbox;

	private SpriteRenderer prefabSpriteRen;

	private State state;

	private Fix chargeTime;

	private bool enterGrounded;

	public Fix ProjectileScaling = Fix.One;

	public Fix ChannelCamShake;

	public Fix AuraMinAlpha = (Fix)0.1f;

	public Fix AuraMaxAlpha = (Fix)0.8f;

	public Fix SparkRotationSpeed = (Fix)100L;

	public Fix projectileStartSpeed = (Fix)15L;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		chargeTime = Fix.Zero;
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		hurtbox = GetComponent<DPhysicsBox>();
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		body.rotation = playerInfo.rotation;
		Fix fix = (Fix)(playerInfo.isFacingRight ? 1 : (-1));
		base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * (float)fix, base.transform.localScale.y, base.transform.localScale.z);
		player.InSparkShot = true;
		player.CustomAimAbilityPosition = body.position;
		if (!playerInfo.isGrounded)
		{
			body.externalVelocity = playerInfo.externalVelocity;
			body.selfImposedVelocity = playerInfo.selfImposedVelocity;
		}
		animator.beginAnimThenDoAction(animData.GetAnimation("enter"), Fire);
		state = State.Enter;
		sparkBody = null;
		chargeTime = Fix.Zero;
		enterGrounded = playerInfo.isGrounded;
	}

	private void Fire()
	{
		Vec2 position = body.position;
		position += Vec2.ComplexMul(new Vec2(body.rotation), body.fixtrans.Scale * projectileOffset);
		sparkBody = FixTransform.InstantiateFixed(SparkPrefab, position, body.rotation);
		sparkBody.Scale = body.fixtrans.Scale;
		player.CustomAimAbilityPosition = position;
		sparkBody.StartVelocity = projectileStartSpeed * body.up;
		animator.beginAnimThenDoAction(animData.GetAnimation("enterToIdle"), Idle);
		sparkBody.GetComponent<SpriteRenderer>().material = playerInfo.playerMaterial;
		sparkBody.GetComponent<Item>().OwnerId = playerInfo.playerId;
		missile = sparkBody.GetComponent<Missile>();
		AudioManager.Get().Play("transform1");
	}

	private void Idle()
	{
		animator.beginAnimation(animData.GetAnimation("idle"));
		state = State.Idle;
	}

	private void OldUpdate()
	{
		if ((!GameTime.IsTimeStopped() || player.isProtectedFromTimeStop) && !player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012) && state != State.Enter && state != State.Exit)
		{
			state = State.Exit;
			animator.beginAnimThenDoAction(animData.GetAnimation("idle"), Finish);
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		chargeTime += GameTime.FixedDeltaTime(playerInfo.playerId, simDeltaTime);
		OldUpdate();
		if (!physics.IsGrounded())
		{
			if (physics.VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime))
			{
				AbilityExitInfo info = default(AbilityExitInfo);
				body.rotation = Fix.Zero;
				info.justlanded = true;
				info.groundedSpeed = physics.groundedSpeed;
				info.isGrounded = physics.IsGrounded();
				info.isFacingRight = true;
				info.position = body.position;
				info.selfImposedVelocity = body.selfImposedVelocity;
				info.externalVelocity = body.externalVelocity;
				info.currentlyAttachedGround = physics.getAttachedGround();
				info.lastSprite = spriteRen.sprite;
				info.groundedLocalPosition = physics.LocalPlatformPos;
				info.radius = physics.radius;
				player.InSparkShot = false;
				ability.ExitAbility(info);
				return;
			}
		}
		else if (physics.getAttachedGround() == null || !physics.getAttachedGround().gameObject.activeSelf)
		{
			AbilityExitInfo info2 = default(AbilityExitInfo);
			body.rotation = Fix.Zero;
			info2.isGrounded = false;
			info2.isFacingRight = true;
			info2.position = body.position;
			info2.selfImposedVelocity = body.selfImposedVelocity;
			info2.externalVelocity = body.externalVelocity;
			info2.currentlyAttachedGround = null;
			info2.lastSprite = spriteRen.sprite;
			info2.radius = physics.radius;
			player.InSparkShot = false;
			ability.ExitAbility(info2);
			return;
		}
		physics.Move(Vec2.zero, simDeltaTime);
		if (!(sparkBody != null) || sparkBody.IsDestroyed || !sparkBody.HasBeenInitialized || state == State.Exit)
		{
			return;
		}
		player.CustomAimAbilityPosition = sparkBody.position;
		Vec2 vec = player.AimVector();
		Vec2 vec2 = Vec2.NormalizedSafe(sparkBody.velocity);
		Tools.Angle2(vec2, vec);
		missile.Stabilize();
		Vec2 vec3 = Vec2.ComplexMul(u: new Vec2((!(Vec2.Cross(vec2, vec) > 0L)) ? (-GameTime.FixedDeltaTime(player.Id, simDeltaTime) * SparkRotationSpeed) : (GameTime.FixedDeltaTime(player.Id, simDeltaTime) * SparkRotationSpeed)), v: sparkBody.up);
		if (Vec2.SqrMagnitude(vec) < Constants.DEADZONE * Constants.DEADZONE)
		{
			vec = sparkBody.up;
			vec3 = sparkBody.up;
		}
		if (Fix.Abs(Vec2.Dot(vec, sparkBody.up)) < (Fix)0.8f)
		{
			bool right = Vec2.Cross(vec, sparkBody.up) < 0L;
			missile.SteerAnimation(right);
		}
		if (Fix.Abs(Vec2.Dot(vec, body.up)) > (Fix)0.8f)
		{
			UnityEngine.Debug.DrawRay((Vector3)body.position, (Vector3)body.up, UnityEngine.Color.red);
			if (state == State.Left)
			{
				animator.beginAnimThenDoAction(animData.GetAnimation("leftToIdle"), delegate
				{
					animator.beginAnimation(animData.GetAnimation("idle"));
					state = State.Idle;
				});
				state = State.InTransition;
			}
			else if (state == State.Right)
			{
				animator.beginAnimThenDoAction(animData.GetAnimation("rightToIdle"), delegate
				{
					animator.beginAnimation(animData.GetAnimation("idle"));
					state = State.Idle;
				});
				state = State.InTransition;
			}
		}
		else if (Vec2.Dot(vec, body.right) * (Fix)Mathf.Sign(base.transform.localScale.x) > 0L)
		{
			UnityEngine.Debug.DrawRay((Vector3)body.position, (Vector3)body.right, UnityEngine.Color.red);
			if (state == State.Idle)
			{
				animator.beginAnimThenDoAction(animData.GetAnimation("idleToRight"), delegate
				{
					animator.beginAnimation(animData.GetAnimation("right"));
					state = State.Right;
				});
				state = State.InTransition;
			}
			else if (state == State.Left)
			{
				animator.beginAnimThenDoAction(animData.GetAnimation("leftToIdle"), delegate
				{
					animator.beginAnimation(animData.GetAnimation("idle"));
					state = State.Idle;
				});
				state = State.InTransition;
			}
		}
		else
		{
			UnityEngine.Debug.DrawRay((Vector3)body.position, -sparkBody.transform.right, UnityEngine.Color.red);
			if (state == State.Idle)
			{
				animator.beginAnimThenDoAction(animData.GetAnimation("idleToLeft"), delegate
				{
					animator.beginAnimation(animData.GetAnimation("left"));
					state = State.Left;
				});
				state = State.InTransition;
			}
			else if (state == State.Right)
			{
				animator.beginAnimThenDoAction(animData.GetAnimation("rightToIdle"), delegate
				{
					animator.beginAnimation(animData.GetAnimation("idle"));
					state = State.Idle;
				});
				state = State.InTransition;
			}
		}
		sparkBody.velocity = vec3 * Vec2.Magnitude(sparkBody.velocity);
		sparkBody.up = vec3;
	}

	private void Finish()
	{
		AbilityExitInfo info = default(AbilityExitInfo);
		player.InSparkShot = false;
		ExitAbility(info);
	}

	public void ExitAbility(AbilityExitInfo info)
	{
		info.selfImposedVelocity = body.selfImposedVelocity;
		info.externalVelocity = body.externalVelocity;
		info.isFacingRight = base.transform.localScale.x >= 0f;
		info.position = body.position;
		info.groundedSpeed = physics.groundedSpeed;
		info.isGrounded = physics.IsGrounded();
		info.currentlyAttachedGround = physics.getAttachedGround();
		info.lastSprite = spriteRen.sprite;
		info.groundedLocalPosition = physics.LocalPlatformPos;
		info.radius = physics.radius;
		player.InSparkShot = false;
		ability.ExitAbility(info);
	}

	public override void Init()
	{
	}
}
public class Spike : MonoUpdatable, IAbilityComponent
{
	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private DPhysicsBox hitBox;

	private Ability ability;

	private PlayerPhysics playerPhysics;

	private PlayerInfo playerInfo;

	private SpikeAttack currentSpike;

	private DPhysicsRoundedRect groundRect;

	private ParticleSystem dustParticle;

	private ParticleSystem dustParticleFar;

	[SerializeField]
	private GameObject dustParticlePrefab;

	[SerializeField]
	private GameObject dustParticle2Prefab;

	[SerializeField]
	private AnimationData animData;

	private ShakableCamera shakeCam;

	[SerializeField]
	private SpikeAttack spikePrefab;

	[SerializeField]
	private Fix surfaceOffset = (Fix)0.5f;

	[SerializeField]
	private float trauma = 0.3f;

	[SerializeField]
	private Fix castForce = (Fix)10L;

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		hitBox = GetComponent<DPhysicsBox>();
		ability = GetComponent<Ability>();
		playerPhysics = GetComponent<PlayerPhysics>();
		dustParticle = UnityEngine.Object.Instantiate(dustParticlePrefab, base.transform.position, Quaternion.identity).GetComponentInChildren<ParticleSystem>();
		dustParticleFar = UnityEngine.Object.Instantiate(dustParticle2Prefab, base.transform.position, Quaternion.identity).GetComponentInChildren<ParticleSystem>();
		shakeCam = GameObject.FindGameObjectWithTag("ShakableCamera").GetComponent<ShakableCamera>();
	}

	public void OnEnterAbility()
	{
		spriteRen.enabled = true;
		playerInfo = ability.GetPlayerInfo();
		spriteRen.material = playerInfo.playerMaterial;
		body.rotation = playerInfo.rotation;
		animator.beginAnimThenDoAction(animData.GetAnimation("cast"), CastSpike);
		playerPhysics.SyncPhysicsTo(playerInfo);
		hitBox.UpdatePhysicsPositions();
		body.position = playerInfo.position;
		float x = (playerInfo.isFacingRight ? 1 : (-1));
		base.transform.localScale = new Vector3(x, base.transform.localScale.y, base.transform.localScale.z);
	}

	private void CastSpike()
	{
		StickyRoundedRectangle attachedGround = playerPhysics.getAttachedGround();
		if (attachedGround == null || attachedGround.IsDestroyed || !attachedGround.ThisGameObject().activeInHierarchy)
		{
			ExitAbility();
			return;
		}
		groundRect = attachedGround.GetComponent<DPhysicsRoundedRect>();
		if (currentSpike != null)
		{
			Updater.DestroyFix(currentSpike.gameObject);
		}
		Vec2 vec = attachedGround.currentNormal(body.position);
		Fix distNear = Fix.Zero;
		Fix distFar = Fix.Zero;
		if (!Raycast.RayCastRoundedRect(body.position, -vec, groundRect.GetRoundedRect(), out distNear, out distFar))
		{
			MonoBehaviour.print("Spike raycast inexplicibly missed");
			ExitAbility();
			return;
		}
		Vec2 vec2 = body.position - vec * distFar;
		AudioManager.Get().Play("spikeRock");
		dustParticle.transform.parent.position = base.transform.position;
		dustParticle.transform.parent.up = base.transform.up;
		dustParticle.Play();
		dustParticleFar.transform.parent.position = (Vector3)vec2;
		dustParticleFar.transform.parent.up = base.transform.up;
		dustParticleFar.Play();
		shakeCam.AddTrauma(trauma);
		Vec2 pos = vec2;
		currentSpike = FixTransform.InstantiateFixed(spikePrefab, pos);
		FixTransform component = currentSpike.GetComponent<FixTransform>();
		component.up = vec;
		component.transform.SetParent(groundRect.transform);
		currentSpike.transform.localScale = new Vector3(1f / attachedGround.transform.localScale.x, 1f / attachedGround.transform.localScale.x, 1f);
		currentSpike.Initialize(vec2, surfaceOffset, attachedGround, hitBox.Scale);
		attachedGround.GetGroundBody().AddForceAtPosition(vec * castForce, body.position);
		animator.beginAnimThenDoAction(animData.GetAnimation("recover"), delegate
		{
			ExitAbility();
		});
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		body.rotation = Fix.Zero;
		exitInfo.groundedSpeed = Vec2.Magnitude(body.selfImposedVelocity);
		exitInfo.isGrounded = playerPhysics.IsGrounded();
		exitInfo.isFacingRight = playerInfo.isFacingRight;
		exitInfo.radius = playerPhysics.radius;
		if (playerPhysics.IsGrounded())
		{
			playerPhysics.getAttachedGround().currentNormal(body.position);
			exitInfo.position = body.position;
			exitInfo.currentlyAttachedGround = playerPhysics.getAttachedGround();
			exitInfo.groundedLocalPosition = playerPhysics.LocalPlatformPos;
		}
		else
		{
			exitInfo.position = body.position;
		}
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.lastSprite = spriteRen.sprite;
		ability.ExitAbility(exitInfo);
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (playerPhysics.IsGrounded())
		{
			playerPhysics.Move(Vec2.zero, simDeltaTime);
		}
	}
}
public class SpikeAttack : MonoUpdatable, IPlatformAttachable, ICollisionCallback
{
	private DPhysicsBox hitbox;

	private FixTransform fixTrans;

	[SerializeField]
	private LayerMask layermask;

	[SerializeField]
	private AnimationCurveFixed DownThrustAnimation;

	private Fix timePassed;

	private Fix groundOrientationAtCastTime;

	private Fix fixedOffset = (Fix)0L;

	[SerializeField]
	private Fix knockAwayStr = (Fix)50f;

	[SerializeField]
	private Fix knockAwayWallStr = (Fix)1000f;

	[SerializeField]
	private Fix selfPushMultiplier = (Fix)0.5f;

	private StickyRoundedRectangle attachedGround;

	private Vec2 relativeOrientationRight;

	[SerializeField]
	private Fix pushTime = (Fix)0.4f;

	private bool pushedThisFrame;

	public Fix SurfaceOffset { get; private set; }

	public Fix LocalPlatformPosition { get; private set; }

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		hitbox = GetComponent<DPhysicsBox>();
		fixTrans = GetComponent<FixTransform>();
		timePassed = Fix.Zero;
		hitbox.RegisterCollisionCallback(this);
	}

	public DPhysicsBox GetHitbox()
	{
		return hitbox;
	}

	public void Initialize(Vec2 surfacePosition, Fix offset, StickyRoundedRectangle attachedGround, Fix scale, bool updateStartScale = true, bool skipInit = false)
	{
		if (!skipInit)
		{
			hitbox.ManualInit();
		}
		attachedGround.UpdateBounds();
		LocalPlatformPosition = attachedGround.LocalPlayerPosFromPos(surfacePosition, Fix.Zero);
		groundOrientationAtCastTime = attachedGround.GetGroundBody().rotation;
		fixedOffset = offset;
		SurfaceOffset = offset;
		this.attachedGround = attachedGround;
		if (updateStartScale)
		{
			fixTrans.startScale = new Vector3(fixTrans.startScale.x / attachedGround.transform.localScale.x, fixTrans.startScale.y / attachedGround.transform.localScale.y, 1f);
		}
		DetPhysics.Get().AddBoxToRR(base.gameObject.GetInstanceID(), attachedGround.gameObject.GetInstanceID());
		UpdateRelativeOrientation();
		UpdatePosition();
		hitbox.Scale = scale;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		pushedThisFrame = false;
		timePassed += simDeltaTime * GameTime.PlayerTimeScale;
		if (timePassed <= DownThrustAnimation.keys[DownThrustAnimation.keys.Length - 1].time && attachedGround != null && !attachedGround.IsDestroyed && attachedGround.gameObject.activeSelf)
		{
			UpdatePosition();
		}
	}

	public void UpdatePosition()
	{
		Vec2 up = fixTrans.up;
		Vec2 vec = attachedGround.PositionFromLocalPlayerPos(LocalPlatformPosition, Fix.Zero);
		Fix fix = DownThrustAnimation.Evaluate(timePassed);
		SurfaceOffset = fix + fixedOffset;
		Vec2 vec2 = vec + up * SurfaceOffset;
		Fix rotation = attachedGround.GetGroundBody().rotation;
		Vec2 vec3 = new Vec2(Fix.PiTimes2 - rotation);
		Vec2 relativePos = Vec2.ComplexMul(vec3, vec2 - attachedGround.GetGroundBody().position);
		Vec2 relativeRightVector = Vec2.ComplexMul(fixTrans.right, vec3);
		hitbox.SetRelativePositionOfChildBody(relativePos, relativeRightVector);
		UnityEngine.Debug.DrawLine(Vector3.zero, (Vector3)vec2, UnityEngine.Color.black);
	}

	public void UpdateRelativeOrientation()
	{
		Fix fix = fixTrans.rotation - groundOrientationAtCastTime;
		relativeOrientationRight = new Vec2(fix);
		hitbox.SetRelativeOrientationOfChildBody(fix);
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (!(timePassed < pushTime) || GameTime.IsTimeStopped() || collision.colliderPP.monobehaviourCollider == null || collision.colliderPP.monobehaviourCollider.IsDestroyed || !collision.colliderPP.monobehaviourCollider.initHasBeenCalled || collision.colliderPP.instanceId == attachedGround.gameObject.GetInstanceID())
		{
			return;
		}
		if (collision.layer == LayerMask.NameToLayer("wall"))
		{
			Vec2 vec = Vec2.NormalizedSafe(collision.contactPoint - fixTrans.position);
			collision.colliderPP.monobehaviourCollider.AddForceAtPosition(vec * knockAwayWallStr, collision.contactPoint);
			if (!pushedThisFrame)
			{
				hitbox.AddForceAtPosition(-vec * knockAwayWallStr * selfPushMultiplier, collision.contactPoint, ForceMode2D.Force);
				pushedThisFrame = true;
			}
		}
		else
		{
			Vec2 vec2 = Vec2.NormalizedSafe(collision.contactPoint - fixTrans.position);
			collision.colliderPP.monobehaviourCollider.AddForceAtPosition(vec2 * knockAwayStr, collision.contactPoint);
			if (!pushedThisFrame)
			{
				hitbox.AddForceAtPosition(-vec2 * knockAwayStr * selfPushMultiplier, collision.contactPoint, ForceMode2D.Force);
				pushedThisFrame = true;
			}
		}
	}

	public void RepositionOnParent()
	{
		if (!(attachedGround == null) && !attachedGround.IsDestroyed)
		{
			Vec2 vec = attachedGround.PositionFromLocalPlayerPos(LocalPlatformPosition, Fix.Zero);
			if (hitbox != null && !hitbox.IsDestroyed)
			{
				vec += hitbox.up * SurfaceOffset;
				Vec2 vec2 = new Vec2(Fix.PiTimes2 - attachedGround.rr.rotation);
				Vec2 relativePos = Vec2.ComplexMul(vec2, vec - attachedGround.rr.position);
				Vec2 relativeRightVector = Vec2.ComplexMul(hitbox.right, vec2);
				hitbox.SetRelativePositionOfChildBody(relativePos, relativeRightVector);
			}
		}
	}
}
public class StretchableLightning : MonoUpdatable, IPlayerIdHolder
{
	private SpriteRenderer spriteRen;

	private SpriteRenderer childSpriteRen;

	private StretchableLightning childLightning;

	private DPhysicsBox hitbox;

	private SpriteAnimator spriteAnim;

	private SpriteAnimator childSpriteAnime;

	public string AnimationToPlay;

	public AnimationData animData;

	public Fix flickerPeriod;

	private Fix timePassed;

	private int id;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
	}

	public override void Init()
	{
	}

	public void InitLightning(int id)
	{
		this.id = id;
		spriteRen = GetComponent<SpriteRenderer>();
		timePassed = Fix.Zero;
		if (base.transform.childCount > 0)
		{
			childSpriteRen = base.transform.GetChild(0).GetComponent<SpriteRenderer>();
			childLightning = base.transform.GetChild(0).GetComponent<StretchableLightning>();
			hitbox = GetComponent<DPhysicsBox>();
			if (childLightning != null)
			{
				childLightning.InitLightning(id);
				childSpriteAnime = base.transform.GetChild(0).GetComponent<SpriteAnimator>();
			}
		}
		spriteAnim = GetComponent<SpriteAnimator>();
		spriteAnim.beginAnimation(animData.GetAnimation(AnimationToPlay));
		Update();
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (spriteRen != null && childSpriteRen != null && hitbox != null && hitbox.enabled)
		{
			timePassed += GameTime.FixedDeltaTime(id, simDeltaTime);
			if (timePassed > flickerPeriod)
			{
				spriteAnim.beginAnimThenDoAction(animData.GetAnimation("flicker"), UnFlicker);
				hitbox.enabled = false;
				childSpriteRen.enabled = false;
			}
		}
	}

	private void UnFlicker()
	{
		timePassed = Fix.Zero;
		spriteAnim.beginAnimation(animData.GetAnimation(AnimationToPlay));
		childSpriteAnime.beginAnimation(animData.GetAnimation(childLightning.AnimationToPlay));
		hitbox.enabled = true;
		childSpriteRen.enabled = true;
	}

	public void Update()
	{
		if (!(spriteRen.sprite == null))
		{
			float value = spriteRen.sprite.textureRect.min.y / (float)spriteRen.sprite.texture.height;
			float value2 = spriteRen.sprite.textureRect.max.y / (float)spriteRen.sprite.texture.height;
			spriteRen.material.SetFloat("_Scale", base.transform.lossyScale.x);
			spriteRen.material.SetFloat("_UVYMin", value);
			spriteRen.material.SetFloat("_UVYMax", value2);
		}
	}

	public void SetPlayerId(int id)
	{
		this.id = id;
	}

	public int GetPlayerId()
	{
		return id;
	}

	public Material GetPlayerMaterial()
	{
		return null;
	}
}
[RequireComponent(typeof(Ability))]
public class ThrowItem : MonoUpdatable, IAbilityComponent
{
	private enum Direction
	{
		UP,
		DOWN,
		RIGHT,
		LEFT
	}

	public Fix airealControlBlend = (Fix)0.5f;

	public AnimationData animData;

	public Fix KnockBack;

	public Fix angularVelocity;

	public BoplBody GrenadePrefab;

	public GameObject GrenadeDummy;

	public Fix throwStrength;

	public Fix airealThrowStrength;

	public GameObject AimIndicator;

	public Vector2[] ItemPositionPickup;

	public Vector2[] ItemPositionAnticipation;

	public Vec2 throwPosition;

	[SerializeField]
	private bool onlyThrowUp;

	private Vec2 inputVector = new Vec2((Fix)0L, (Fix)1L);

	private PlayerInfo playerInfo;

	private Player player;

	private bool hasFired;

	private Fix OnExitKnockBack;

	private Direction direction;

	private bool firedFromTheGround;

	private GameObject dummy;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private DPhysicsBox hurtbox;

	public int ThrowLoopItemPositionIndex;

	private bool isInAnticipation;

	private Vec2 exitVelocity;

	public float DisableGrenadeHitBoxTime = 0.1f;

	public Fix AirealKnockBack = (Fix)0L;

	public Fix throwingRange01;

	[SerializeField]
	private Fix minThrowStrength = (Fix)2.1f;

	private bool abilityButtonUp = true;

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		hurtbox = GetComponent<DPhysicsBox>();
	}

	public void OnEnterAbility()
	{
		isInAnticipation = false;
		firedFromTheGround = false;
		abilityButtonUp = false;
		exitVelocity = Vec2.zero;
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		body.rotation = playerInfo.rotation;
		dummy = UnityEngine.Object.Instantiate(GrenadeDummy, base.transform);
		if (ItemPositionPickup.Length >= 1)
		{
			dummy.transform.localPosition = ItemPositionPickup[0];
		}
		if (!playerInfo.isGrounded)
		{
			physics.gravity_modifier = (Fix)1f;
		}
		else
		{
			physics.gravity_modifier = (Fix)0L;
		}
		UpdateInputVector(player.InputVector());
		float num = ((!playerInfo.isFacingRight) ? 1 : (-1));
		base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * num, base.transform.localScale.y, base.transform.localScale.z);
		direction = Direction.UP;
		hasFired = false;
		if (playerInfo.isGrounded)
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("gEnter"), OnGroundedPickupDone);
		}
		else
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("aEnter"), Fire);
		}
	}

	private void OnGroundedPickupDone()
	{
		isInAnticipation = true;
		animator.beginAnimThenDoAction(animData.GetAnimation("gLoop"), Fire);
	}

	private void OnAirealPickupDone()
	{
		Fire();
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		if (dummy != null)
		{
			Updater.DestroyFix(dummy.gameObject);
		}
		exitInfo.isFacingRight = base.transform.localScale.x < 0f;
		exitInfo.position = body.position;
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.justlanded = exitInfo.isGrounded;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.lastSprite = spriteRen.sprite;
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		ability.ExitAbility(exitInfo);
	}

	private void enableColliders(Collider2D[] colliders, int nrCols, bool toEnabled)
	{
		for (int i = 0; i < nrCols; i++)
		{
			colliders[i].enabled = toEnabled;
		}
	}

	private IEnumerator delayedColliderEnable(GameObject grenade)
	{
		yield return new WaitForSeconds(DisableGrenadeHitBoxTime);
		grenade.gameObject.layer = Constants.effectLayer;
	}

	private void ExitAbility()
	{
		ExitAbility(new AbilityExitInfo
		{
			selfImposedVelocity = (firedFromTheGround ? exitVelocity : body.selfImposedVelocity),
			externalVelocity = body.externalVelocity
		});
	}

	private void Fire()
	{
		isInAnticipation = false;
		dummy.gameObject.SetActive(value: false);
		Updater.DestroyFix(dummy.gameObject);
		hasFired = true;
		if (physics.IsGrounded())
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("gExit"), ExitAbility);
		}
		else
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("aExit"), ExitAbility);
		}
		Vec2 vec = throwPosition * body.fixtrans.Scale;
		Vec2 vec2 = LocalUp();
		Vec2 vec3 = new Vec2(vec2.y, -vec2.x) * (Fix)((!(base.transform.localScale.x < 0f)) ? 1 : (-1));
		Vec2 pos = body.position + vec.y * vec2 + vec.x * vec3;
		if (physics.IsGrounded())
		{
			exitVelocity = -physics.getAttachedGround().currentNormal(body) * KnockBack;
			body.selfImposedVelocity = Vec2.zero;
			Quaternion rotation = base.transform.rotation;
			base.transform.rotation = rotation;
			firedFromTheGround = true;
		}
		else
		{
			physics.gravity_modifier = (Fix)1L;
			firedFromTheGround = false;
		}
		BoplBody boplBody = FixTransform.InstantiateFixed(GrenadePrefab, pos);
		Item component = boplBody.gameObject.GetComponent<Item>();
		if (component != null)
		{
			component.GetComponent<Mine>()?.SetMaterial(playerInfo.playerMaterial);
		}
		boplBody.Scale = body.fixtrans.Scale;
		if (!firedFromTheGround)
		{
			boplBody.StartVelocity = Vec2.up * airealThrowStrength;
		}
		else
		{
			Fix fix = ((direction == Direction.DOWN) ? minThrowStrength : throwStrength);
			Vec2 vec4 = ThrowingVector();
			if (Vec2.Magnitude(player.InputVector()) <= Constants.DEADZONE || onlyThrowUp)
			{
				boplBody.StartVelocity = vec2 * fix;
			}
			else
			{
				boplBody.StartVelocity = vec4 * fix;
			}
		}
		component.OwnerId = playerInfo.playerId;
		Grenade component2 = component.GetComponent<Grenade>();
		if (component2 != null)
		{
			component2.DetonatesOnOwner = false;
		}
		AudioManager.Get().Play("throwSmallItem");
	}

	private Vec2 ThrowingVector()
	{
		Vec2 vec = LocalUp();
		Vec2 vec2 = player.InputVector();
		Vec2 result;
		if (Vec2.Dot(Vec2.NormalizedSafe(vec2), vec) <= throwingRange01)
		{
			Vec2 vec3 = new Vec2(-vec.y, vec.x);
			result = ((!(Vec2.Dot(vec3, vec2) >= 0L)) ? Vec2.Normalized(throwingRange01 * -vec3 + (Fix.One - throwingRange01) * vec) : Vec2.Normalized(throwingRange01 * vec3 + (Fix.One - throwingRange01) * vec));
		}
		else
		{
			result = Vec2.Normalized(vec2);
		}
		if (!(Vec2.Magnitude(vec2) > Constants.DEADZONE))
		{
			return vec;
		}
		return result;
	}

	private Vec2 LocalUp()
	{
		if (!physics.IsGrounded())
		{
			return Vec2.up;
		}
		return physics.getAttachedGround().currentNormal(body);
	}

	private void UpdateInputVector(Vec2 newInputVector)
	{
		Vec2 v = LocalUp();
		if (Vec2.Magnitude(newInputVector) > Constants.DEADZONE)
		{
			new Vec2(v.y, -v.x);
			Fix fix = Vec2.Dot(v, Vec2.Normalized(newInputVector));
			if (fix > (Fix)0.8)
			{
				direction = Direction.UP;
				inputVector = v;
			}
			else if (fix > (Fix)(-0.3))
			{
				direction = Direction.UP;
				inputVector = v;
			}
			else
			{
				direction = Direction.DOWN;
				inputVector = v;
			}
		}
		else
		{
			direction = Direction.UP;
			inputVector = v;
		}
	}

	private void UpdateLocalScale()
	{
		Vec2 vec = LocalUp();
		Vec2 u = new Vec2(vec.y, -vec.x);
		Vec2 v = player.InputVector();
		if (Vec2.Magnitude(v) < Constants.DEADZONE)
		{
			return;
		}
		Fix fix = Vec2.Dot(v, u);
		if (physics.IsGrounded())
		{
			if (fix < 0L)
			{
				base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x), base.transform.localScale.y, base.transform.localScale.z);
			}
			else
			{
				base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * -1f, base.transform.localScale.y, base.transform.localScale.z);
			}
		}
	}

	private void OldUpdate()
	{
		if (hasFired)
		{
			return;
		}
		if (!abilityButtonUp)
		{
			UpdateInputVector(player.InputVector());
		}
		if (AimIndicator != null)
		{
			if (physics.IsGrounded())
			{
				AimIndicator.SetActive(value: true);
				AimIndicator.GetComponent<FixTransform>().up = ThrowingVector();
			}
			else
			{
				AimIndicator.SetActive(value: false);
			}
		}
		if (!player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012))
		{
			abilityButtonUp = true;
			Vec2 vec = LocalUp();
			if (abilityButtonUp)
			{
				UpdateInputVector(-vec);
			}
			else
			{
				UpdateInputVector(vec);
			}
		}
		if (isInAnticipation && abilityButtonUp)
		{
			Fire();
		}
		Vector2[] array = (isInAnticipation ? ItemPositionAnticipation : ItemPositionPickup);
		int num = animator.getNumberOfPassedSprites() - 1;
		if (dummy.gameObject != null && num < array.Length)
		{
			dummy.transform.localPosition = array[num];
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		OldUpdate();
		if (!physics.IsGrounded())
		{
			physics.AddGravityFactor();
			if (!firedFromTheGround)
			{
				Fix inputHorz = player.HorizontalAxis();
				physics.AirealMovement(inputHorz, simDeltaTime);
			}
			if (physics.VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime))
			{
				if (hasFired)
				{
					ExitAbility();
					return;
				}
				direction = Direction.DOWN;
				Fire();
			}
		}
		else
		{
			physics.Move(Vec2.zero, simDeltaTime);
		}
	}

	private void OnDrawGizmosSelected()
	{
		for (int i = 0; i < ItemPositionPickup.Length; i++)
		{
			Gizmos.DrawWireSphere(ItemPositionPickup[i], 1.5f);
		}
		for (int j = 0; j < ItemPositionAnticipation.Length; j++)
		{
			Gizmos.DrawWireSphere(ItemPositionAnticipation[j], 1f);
		}
		Gizmos.DrawWireSphere((Vector3)throwPosition, 0.5f);
	}
}
[RequireComponent(typeof(Ability))]
public class ThrowItem2 : MonoUpdatable, IAbilityComponent
{
	public AnimationData animData;

	public BoplBody ItemPrefab;

	public Vec2 aThrowPosition;

	public Vec2 gThrowPosition;

	private PlayerInfo playerInfo;

	private Player player;

	private GameObject dummy;

	private GameObject aimIndicator;

	private bool hasFired;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private DPhysicsBox hurtbox;

	public Vec2[] groundedDummyPositions;

	public Vec2[] airealDummyPositions;

	public int maxEffectsSpawnedFromGrenades;

	public RingBuffer<MonoUpdatable> effectBuffer;

	private bool isGroundedThrow;

	private bool isInLoop;

	private Grenade grenade;

	private BoplBody grenadeBody;

	private RingBuffer<Grenade> grenadeBuffer;

	private Vec2 exitVelocity;

	public Fix DisableGrenadeHitBoxTime = (Fix)0.1f;

	public Fix maxThrowForce = (Fix)30L;

	public Fix minThrowForce = (Fix)5L;

	public Fix ThrowForceGainSpeed = (Fix)1L;

	public Fix minIndicatorSize = (Fix)0.3f;

	public Fix maxIndicatorSize = (Fix)0.9f;

	private Fix timePassed;

	private Vec2 dir;

	public Fix maxSlowMoSpeed = (Fix)9L;

	public Fix knockback = (Fix)10L;

	public Fix adjustRotationTime = (Fix)1L;

	private Fix timeSinceFired;

	private Fix FireInputTimeStamp;

	private bool hasInputtedFire;

	public bool isExplosiveGrenade;

	public bool showAirealGizmoPositions = true;

	public void OnScaleChanged(Fix scaleMultiplier)
	{
		if (grenadeBody != null)
		{
			grenadeBody.Scale *= scaleMultiplier;
		}
	}

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		hurtbox = GetComponent<DPhysicsBox>();
		aimIndicator = base.transform.GetChild(0).gameObject;
		dummy = base.transform.GetChild(1).gameObject;
		effectBuffer = new RingBuffer<MonoUpdatable>(maxEffectsSpawnedFromGrenades);
	}

	public void OnEnterAbility()
	{
		dir = Vec2.up;
		exitVelocity = Vec2.zero;
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		isInLoop = false;
		hasInputtedFire = false;
		int num = ((!playerInfo.isFacingRight) ? 1 : (-1));
		base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * (float)num, base.transform.localScale.y, base.transform.localScale.z);
		timePassed = (Fix)0L;
		timeSinceFired = (Fix)0L;
		dummy.SetActive(value: true);
		aimIndicator.SetActive(value: true);
		base.transform.rotation = Quaternion.identity;
		if (physics.IsGrounded())
		{
			body.selfImposedVelocity = Vec2.zero;
			dummy.transform.localPosition = (Vector3)groundedDummyPositions[0];
			animator.beginAnimThenDoAction(animData.GetAnimation("gEnter"), OnGroundedEnter);
			isGroundedThrow = true;
		}
		else
		{
			physics.gravity_modifier = (Fix)0.03f;
			body.selfImposedVelocity = playerInfo.selfImposedVelocity * (Fix)0.1f;
			dummy.transform.localPosition = (Vector3)airealDummyPositions[0];
			animator.beginAnimThenDoAction(animData.GetAnimation("aEnter"), OnAirealEnter);
			isGroundedThrow = false;
		}
		hasFired = false;
	}

	private void OnAirealEnter()
	{
		animator.beginAnimation(animData.GetAnimation("aLoop"));
		SpawnGrenade(dummyPos());
		isInLoop = true;
	}

	private void OnGroundedEnter()
	{
		animator.beginAnimation(animData.GetAnimation("gLoop"));
		SpawnGrenade(dummyPos());
		isInLoop = true;
	}

	private void SpawnGrenade(Vec2 pos)
	{
		grenadeBody = FixTransform.InstantiateFixed(ItemPrefab, pos, body.rotation);
		grenadeBody.Scale = player.Scale;
		Item component = grenadeBody.GetComponent<Item>();
		component.OwnerId = playerInfo.playerId;
		grenade = component.GetComponent<Grenade>();
		grenade.Initialize(this);
		grenade.DetonatesOnOwner = false;
		dummy.SetActive(value: false);
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		if (grenade != null && !hasFired)
		{
			grenade.DelayedEnableHurtOwner(DisableGrenadeHitBoxTime * body.fixtrans.Scale);
			grenade.hasBeenThrown = true;
			Fix fix = minThrowForce;
			DPhysicsCircle dPhysicsCircle = grenadeBody?.GetComponent<DPhysicsCircle>();
			if (dPhysicsCircle != null && !dPhysicsCircle.IsDestroyed)
			{
				if (!dPhysicsCircle.initHasBeenCalled)
				{
					dPhysicsCircle.ManualInit();
				}
				grenadeBody?.AddForce(body.fixtrans.Scale * fix * Vec2.up, ForceMode2D.Impulse);
			}
		}
		grenade = null;
		grenadeBody = null;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.isFacingRight = base.transform.localScale.x < 0f;
		exitInfo.position = body.position;
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.justlanded = exitInfo.isGrounded;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.lastSprite = spriteRen.sprite;
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		ability.ExitAbility(exitInfo);
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	private void Fire()
	{
		dummy.SetActive(value: false);
		aimIndicator.SetActive(value: false);
		Vec2 vec = dir;
		Vec2 position = body.position + Vec2.ComplexMul(new Vec2(body.rotation), player.Scale * (isGroundedThrow ? gThrowPosition : aThrowPosition) * (Fix)((!(base.transform.localScale.x < 0f)) ? 1 : (-1)));
		if (grenade != null && !grenade.hasBeenThrown)
		{
			grenade.DelayedEnableHurtOwner(DisableGrenadeHitBoxTime * Fix.Max(body.fixtrans.Scale, Fix.One));
			grenadeBody.GetComponent<DPhysicsCircle>().ManualInit();
			grenadeBody.position = position;
			grenade.hasBeenThrown = true;
			grenadeBody.UpdateSim(Fix.Zero);
			Fix fix = Fix.Lerp(minThrowForce, maxThrowForce, Fix.Clamp01(FireInputTimeStamp * ThrowForceGainSpeed));
			grenadeBody.AddForce(body.fixtrans.Scale * fix * vec, ForceMode2D.Impulse);
			timeSinceFired = (Fix)0L;
			body.selfImposedVelocity -= knockback * vec;
			physics.gravity_modifier = (Fix)1L;
			hasFired = true;
			AudioManager.Get().Play("throwSmallItem");
		}
		else
		{
			physics.gravity_modifier = (Fix)1L;
			hasFired = true;
			timeSinceFired = (Fix)0L;
			body.selfImposedVelocity -= knockback * vec;
		}
	}

	private void OldUpdate(Fix simDeltaTime)
	{
		if (!hasInputtedFire)
		{
			Vec2 vec = player.AimVector();
			if (Vec2.Magnitude(vec) > Constants.DEADZONE)
			{
				if (physics.IsGrounded())
				{
					Fix value = Vec2.Cross(physics.getAttachedGround().currentNormal(body), Vec2.NormalizedSafe(vec));
					base.transform.localScale = new Vector3((float)Fix.Sign2(value) * Mathf.Abs(base.transform.localScale.x), base.transform.localScale.y, base.transform.localScale.z);
				}
				else
				{
					base.transform.localScale = new Vector3((float)Fix.Sign2(-vec.x) * Mathf.Abs(base.transform.localScale.x), base.transform.localScale.y, base.transform.localScale.z);
				}
			}
			if (Vec2.Magnitude(vec) > Constants.DEADZONE)
			{
				dir = vec;
				aimIndicator.transform.rotation = Quaternion.FromToRotation((Vector2)Vec2.up, (Vector2)vec);
			}
		}
		if (grenade == null)
		{
			Vec2[] array = (physics.IsGrounded() ? groundedDummyPositions : airealDummyPositions);
			int num = animator.getNumberOfPassedSprites() - 1;
			if (isInLoop)
			{
				num = array.Length - 1;
			}
			if (num < array.Length)
			{
				dummy.transform.localPosition = (Vector3)array[num];
			}
			dummy.transform.localScale = new Vector3(Mathf.Sign(base.transform.localScale.x), 1f, 1f);
		}
		else if (!hasFired && !grenade.hasBeenThrown)
		{
			grenadeBody.position = dummyPos();
		}
	}

	private Vec2 dummyPos()
	{
		Vec2 u = (physics.IsGrounded() ? (player.Scale * groundedDummyPositions[groundedDummyPositions.Length - 1]) : (player.Scale * airealDummyPositions[airealDummyPositions.Length - 1]));
		u.x *= ((base.transform.localScale.x < 0f) ? (-Fix.One) : Fix.One);
		return Vec2.ComplexMul(new Vec2(body.rotation), u) + body.position;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		OldUpdate(simDeltaTime);
		if (isGroundedThrow && !physics.IsGrounded())
		{
			ExitAbility();
			return;
		}
		if (!hasInputtedFire && !player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012))
		{
			hasInputtedFire = true;
			FireInputTimeStamp = timePassed;
		}
		if (isInLoop && hasInputtedFire)
		{
			isInLoop = false;
			Fire();
			if (isGroundedThrow)
			{
				animator.beginAnimThenDoAction(animData.GetAnimation("gExit"), ExitAbility);
			}
			else
			{
				animator.beginAnimThenDoAction(animData.GetAnimation("aExit"), ExitAbility);
			}
		}
		if (hasFired)
		{
			timeSinceFired += GameTime.FixedDeltaTime(player.Id, simDeltaTime);
		}
		if (!hasFired && grenade != null && !grenade.IsDestroyed && grenade.selfDestructDelay <= (Fix)0.02 && grenade.selfDestructDelay >= 0L && player.IsLocalPlayer && isExplosiveGrenade)
		{
			AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.HoldAGrenadeUntilItExplodes);
		}
		timePassed += GameTime.FixedDeltaTime(player.Id, simDeltaTime);
		Fix t = Fix.Clamp01((hasInputtedFire ? FireInputTimeStamp : timePassed) * ThrowForceGainSpeed);
		Fix fix = Fix.Lerp(minIndicatorSize, maxIndicatorSize, t);
		aimIndicator.transform.localScale = new Vector3((float)fix, (float)fix, 1f);
		if (!physics.IsGrounded())
		{
			physics.AddGravityFactor();
			if (!hasFired)
			{
				if (Vec2.Magnitude(body.selfImposedVelocity) > maxSlowMoSpeed)
				{
					body.selfImposedVelocity = Vec2.Normalized(body.selfImposedVelocity) * maxSlowMoSpeed;
				}
			}
			else
			{
				Vec2 selfImposedVelocity = body.selfImposedVelocity;
				Fix inputHorz = player.HorizontalAxis();
				physics.AirealMovement(inputHorz, simDeltaTime);
				Vec2 selfImposedVelocity2 = body.selfImposedVelocity;
				body.selfImposedVelocity = Vec2.Lerp(selfImposedVelocity, selfImposedVelocity2, (Fix)0.6f);
			}
			if (physics.VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime))
			{
				ExitAbility();
			}
		}
		else
		{
			physics.Move(Vec2.zero, simDeltaTime);
		}
	}

	private void OnDrawGizmosSelected()
	{
		if (showAirealGizmoPositions)
		{
			Gizmos.DrawWireSphere(base.transform.position + base.transform.rotation * (Vector3)aThrowPosition, 0.2f);
			for (int i = 0; i < airealDummyPositions.Length; i++)
			{
				Gizmos.DrawWireSphere(base.transform.position + base.transform.rotation * (Vector3)airealDummyPositions[i], 0.5f);
			}
		}
		else
		{
			Gizmos.DrawWireSphere(base.transform.position + base.transform.rotation * (Vector3)gThrowPosition, 0.2f);
			for (int j = 0; j < groundedDummyPositions.Length; j++)
			{
				Gizmos.DrawWireSphere(base.transform.position + base.transform.rotation * (Vector3)groundedDummyPositions[j], 0.5f);
			}
		}
	}
}
public class TimeStop : MonoUpdatable, IPlayerIdHolder
{
	[SerializeField]
	private AnimationCurve InversionSphereScale;

	[SerializeField]
	private AnimationCurve TimeScale;

	[SerializeField]
	private AnimationCurve ExitAlpha;

	[SerializeField]
	private float duration = 5f;

	[SerializeField]
	private float musicFadeOutStrength = 0.2f;

	private SpriteRenderer inversionSphere;

	private int casterId = -1;

	private float secondsElapsed;

	public override void Init()
	{
		secondsElapsed = 0f;
		UpdateTimeScaleProtection();
		Shader.SetGlobalFloat("_Timestop01", 0f);
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		inversionSphere = GetComponent<SpriteRenderer>();
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		secondsElapsed += (float)simDeltaTime;
		GameTime.PlayerTimeScale = (Fix)0L;
		float num = Mathf.Max(InversionSphereScale.Evaluate(secondsElapsed), 0f);
		base.transform.localScale = new Vector3(num, num, base.transform.localScale.z);
		UnityEngine.Color color = new UnityEngine.Color(inversionSphere.color.r, inversionSphere.color.g, inversionSphere.color.b, ExitAlpha.Evaluate(secondsElapsed - duration));
		inversionSphere.color = color;
		AudioManager.Get().FadeOutMusicTick(musicFadeOutStrength);
		if (secondsElapsed > duration + ExitAlpha.keys[ExitAlpha.keys.Length - 1].time)
		{
			End();
			Updater.DestroyFix(base.gameObject);
		}
		else
		{
			UpdateTimeScaleProtection();
		}
	}

	private void UpdateTimeScaleProtection()
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		Player player = PlayerHandler.Get().GetPlayer(casterId);
		for (int i = 0; i < list.Count; i++)
		{
			int team = list[i].Team;
			list[i].isProtectedFromTimeStop = team == player.Team;
		}
	}

	public void End()
	{
		if (!GameSessionHandler.HasGameEnded())
		{
			List<Player> list = PlayerHandler.Get().PlayerList();
			for (int i = 0; i < list.Count; i++)
			{
				_ = list[i].Id;
				list[i].isProtectedFromTimeStop = false;
			}
			GameTime.PlayerTimeScale = (Fix)1L;
			Shader.SetGlobalFloat("_Timestop01", 1f);
			AchievementHandler.RegisterTimeStopEnded(casterId);
		}
	}

	public void SetPlayerId(int id)
	{
		casterId = id;
	}

	public int GetPlayerId()
	{
		return casterId;
	}

	public Material GetPlayerMaterial()
	{
		return PlayerHandler.Get().GetPlayer(GetPlayerId()).Color;
	}
}
public class Ability : AbilityMonoBehaviour, IPlayerIdHolder
{
	public Fix Cooldown;

	public bool KillPlayersOnContact;

	private PlayerInfo playerInfo;

	private Action<AbilityExitInfo> onExitAbility;

	public bool isPushable;

	public bool cooldownStoppedDuringTimeStop;

	private IAbilityComponent[] abilityComponents;

	private IPhysicsCollider potentialCollider;

	private SpriteRenderer spriteRen;

	private PlayerBody playerBody;

	private PlayerCollision playerCol;

	private SlimeController slimeController;

	private Fix prevScale = Fix.One;

	public bool isCastable = true;

	public override bool IsRope => false;

	public override bool IgnoreNextCooldown => false;

	public override bool CooldownStoppedDuringTimeStop => cooldownStoppedDuringTimeStop;

	public override void UpdateCooldowns(PlayerBody playerbody)
	{
	}

	public PlayerInfo GetPlayerInfo()
	{
		return playerInfo;
	}

	public override Fix GetCooldown()
	{
		return Cooldown;
	}

	public Material GetPlayerMaterial()
	{
		return playerInfo.playerMaterial;
	}

	public int GetPlayerId()
	{
		return playerInfo.playerId;
	}

	public override void Init()
	{
	}

	public void Awake()
	{
		Updater.RegisterUpdatable(this);
		abilityComponents = GetComponents<IAbilityComponent>();
		potentialCollider = GetComponent<IPhysicsCollider>();
		spriteRen = GetComponent<SpriteRenderer>();
		playerBody = GetComponent<PlayerBody>();
		playerCol = GetComponent<PlayerCollision>();
	}

	public override PlayerCollision GetPlayerCollision()
	{
		return playerCol;
	}

	public override SlimeController GetSlimeController()
	{
		return slimeController;
	}

	public override void EnterAbility(PlayerInfo playerInfo, Action<AbilityExitInfo> onExitAbility)
	{
		this.playerInfo = playerInfo;
		this.onExitAbility = onExitAbility;
		base.gameObject.SetActive(value: true);
		slimeController = playerInfo.slimeController;
		if (playerCol != null && !playerCol.IsDestroyed && slimeController != null && !slimeController.IsDestroyed && slimeController.GetPlayerCollision() != null && !slimeController.GetPlayerCollision().IsDestroyed)
		{
			playerCol.CopyIgnoredColliderFrom(slimeController.GetPlayerCollision());
		}
		if (playerBody != null && playerInfo.ropeBody != null)
		{
			playerBody.AttachRope(playerInfo.ropeBody, playerInfo.topAttachment);
		}
		if (potentialCollider != null)
		{
			potentialCollider.Scale = PlayerHandler.Get().GetPlayer(playerInfo.playerId).Scale;
		}
		PlayerHandler.Get().GetPlayer(playerInfo.playerId)?.SetPosition(potentialCollider.position, slimeController);
		for (int i = 0; i < abilityComponents.Length; i++)
		{
			abilityComponents[i].OnEnterAbility();
		}
	}

	private void LateUpdate()
	{
		Invisibility.SetAlphaBasedOnPlayerInvisibiltyTime(PlayerHandler.Get().GetPlayer(playerInfo.playerId), spriteRen);
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		Player player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		if (potentialCollider == null)
		{
			return;
		}
		if (player.Scale != prevScale)
		{
			Fix scaleMultiplier = player.Scale / prevScale;
			prevScale = player.Scale;
			for (int i = 0; i < abilityComponents.Length; i++)
			{
				abilityComponents[i].OnScaleChanged(scaleMultiplier);
			}
		}
		potentialCollider.Scale = player.Scale;
		player?.SetPosition(potentialCollider.position, slimeController);
	}

	public override void ExitAbility(AbilityExitInfo exitInfo)
	{
		if (playerBody != null && playerBody.ropeBody != null)
		{
			exitInfo.topAttachment = playerBody.topAttachment;
			exitInfo.ropeAttachment = playerBody.ropeBody;
			playerBody.EnterAbilityClearRope();
		}
		if (playerCol != null && !playerCol.IsDestroyed && slimeController != null && !slimeController.IsDestroyed && slimeController.GetPlayerCollision() != null && !slimeController.GetPlayerCollision().IsDestroyed)
		{
			slimeController.GetPlayerCollision().CopyIgnoredColliderFrom(playerCol);
		}
		PlayerHandler.Get().GetPlayer(playerInfo.playerId)?.SetPosition(potentialCollider.position, slimeController);
		base.gameObject.SetActive(value: false);
		onExitAbility(exitInfo);
	}

	public void SetPlayerId(int id)
	{
		playerInfo.playerId = id;
	}

	public override bool IsInstant()
	{
		return false;
	}

	public override bool IsCastable(Player player)
	{
		return isCastable;
	}
}
public class AbilityReadyIndicator : MonoBehaviour
{
	public AnimationCurve ResetColorAnimation;

	public UnityEngine.Color ResetColor;

	public AnimationCurve ResetSizeAnimation;

	private float SecondsSinceReset = 10000f;

	private Sprite overiddenSprite;

	private bool overidden;

	public float extraScale = 0.2f;

	private SpriteRenderer spriteRen;

	private FollowTransform followTrans;

	public void SetCooldownProgress(float pDone)
	{
		if (spriteRen != null)
		{
			spriteRen.material.SetFloat("_PercentDone", Mathf.Clamp01(pDone));
		}
	}

	public void SetSprite(Sprite sprite, bool isPrimarySprite = true)
	{
		if (isPrimarySprite)
		{
			overiddenSprite = sprite;
		}
		if (isPrimarySprite && !overidden)
		{
			spriteRen.sprite = sprite;
		}
		else if (!isPrimarySprite)
		{
			spriteRen.sprite = sprite;
		}
		Vector2 center = sprite.textureRect.center;
		center.x /= sprite.texture.width;
		center.y /= sprite.texture.height;
		spriteRen.material.SetVector("_SpriteCenter", center);
	}

	public void UpdateOverriden(Sprite overrideSprite, bool shouldOverride)
	{
		if (shouldOverride && overidden && spriteRen.sprite != overrideSprite)
		{
			OverrideSprite(overrideSprite);
		}
		else if (shouldOverride && !overidden)
		{
			OverrideSprite(overrideSprite);
		}
		else if (!shouldOverride && overidden)
		{
			CancelOverridenSprite();
		}
		else if (!shouldOverride)
		{
			_ = overidden;
		}
	}

	public void OverrideSprite(Sprite sprite)
	{
		if (!overidden)
		{
			ResetAnimation();
			overidden = true;
			overiddenSprite = spriteRen.sprite;
		}
		SetSprite(sprite, isPrimarySprite: false);
	}

	public void CancelOverridenSprite()
	{
		overidden = false;
		if (overiddenSprite != null)
		{
			SetSprite(overiddenSprite, isPrimarySprite: false);
		}
	}

	public void ResetAnimation()
	{
		SecondsSinceReset = 0f;
	}

	private void Awake()
	{
		if (spriteRen == null)
		{
			spriteRen = GetComponent<SpriteRenderer>();
		}
		base.transform.localScale = new Vector3(0.7f + extraScale, 0.7f + extraScale, 1f);
	}

	public void Init()
	{
		spriteRen = GetComponent<SpriteRenderer>();
		followTrans = GetComponent<FollowTransform>();
		followTrans.Init();
		if (spriteRen != null && spriteRen.sprite != null)
		{
			SetSprite(spriteRen.sprite);
		}
	}

	public void SetColor(UnityEngine.Color c)
	{
		spriteRen.material.SetColor("_CircleColor", c);
	}

	public void Update()
	{
		UnityEngine.Color color = spriteRen.color;
		if (SecondsSinceReset < 10f)
		{
			float num = ResetSizeAnimation.Evaluate(SecondsSinceReset) + extraScale;
			base.transform.localScale = new Vector3(num, num, 1f);
			UnityEngine.Color color2 = UnityEngine.Color.Lerp(UnityEngine.Color.white, ResetColor, ResetColorAnimation.Evaluate(SecondsSinceReset));
			color.r = color2.r;
			color.g = color2.g;
			color.b = color2.b;
			spriteRen.color = color;
		}
		else
		{
			base.transform.localScale = new Vector3(0.7f + extraScale, 0.7f + extraScale, 1f);
			color.r = 1f;
			color.g = 1f;
			color.b = 1f;
			spriteRen.color = color;
		}
		SecondsSinceReset += Time.deltaTime;
	}

	public void InstantlySyncTransform()
	{
		followTrans.AlignPositionInstantly();
	}

	public SpriteRenderer GetSpriteRen()
	{
		return spriteRen;
	}

	public Sprite GetPrimarySprite()
	{
		if ((bool)overiddenSprite)
		{
			return overiddenSprite;
		}
		return spriteRen.sprite;
	}

	private void OnEnable()
	{
		if (followTrans != null)
		{
			followTrans.AlignPositionInstantly();
		}
		if (SecondsSinceReset > 0f)
		{
			SecondsSinceReset = 11f;
		}
	}
}
public class AbilitySpawner : MonoUpdatable
{
	public DynamicAbilityPickup pickupPrefab;

	private Fix SpawnDelay = (Fix)40L;

	private int MaxSpawns = 3;

	private Fix time = Fix.Zero;

	private int spawns;

	private FixTransform fixTrans;

	public override void Init()
	{
	}

	public void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		time += (GameTime.IsTimeStopped() ? Fix.Zero : simDeltaTime);
		if (time > SpawnDelay)
		{
			time = Fix.Zero;
			Spawn();
			spawns++;
			if (spawns >= MaxSpawns)
			{
				base.enabled = false;
			}
		}
	}

	private void Spawn()
	{
		DynamicAbilityPickup dynamicAbilityPickup = FixTransform.InstantiateFixed(pickupPrefab, fixTrans.position);
		dynamicAbilityPickup.InitPickup(null, null, Updater.RandomUnitVector());
		dynamicAbilityPickup.SwapToRandomAbility();
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawCube(base.transform.position, 5f * Vector3.one);
	}
}
[RequireComponent(typeof(AnimateVelocity))]
public class AnimateGround : MonoUpdatable
{
	public Vec2[] PathKeys;

	public AnimationCurveFixed PositionCurve;

	public Fix DelaySeconds;

	private AnimateVelocity animateVelocity;

	private int framesSinceActivation;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animateVelocity = GetComponent<AnimateVelocity>();
	}

	public override void Init()
	{
		framesSinceActivation = 0;
	}

	public void Reverse()
	{
		framesSinceActivation = 0;
		for (int i = 0; i < PathKeys.Length / 2; i++)
		{
			Vec2 vec = PathKeys[i];
			PathKeys[i] = PathKeys[PathKeys.Length - i - 1];
			PathKeys[PathKeys.Length - i - 1] = vec;
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (PathKeys == null || PositionCurve == null)
		{
			return;
		}
		Vec2 homePosition = animateVelocity.HomePosition;
		Fix fix = PositionCurve.Evaluate((Fix)framesSinceActivation * simDeltaTime * GameTime.PlayerTimeScale - DelaySeconds);
		framesSinceActivation++;
		Fix zero = Fix.Zero;
		if (PathKeys.Length < 2)
		{
			zero = Fix.Zero;
		}
		else
		{
			Vec2 vec = PathKeys[0];
			for (int i = 1; i < PathKeys.Length; i++)
			{
				Vec2 vec2 = PathKeys[i];
				zero += Vec2.Magnitude(vec2 - vec);
				vec = vec2;
			}
		}
		Fix fix2 = fix * zero;
		int num = 0;
		Fix fix3 = Fix.Zero;
		Fix zero2 = Fix.Zero;
		if (PathKeys.Length < 2)
		{
			num = 0;
			fix3 = fix;
		}
		else
		{
			Vec2 vec3 = PathKeys[0];
			for (int j = 1; j < PathKeys.Length; j++)
			{
				Vec2 vec4 = PathKeys[j];
				Fix fix4 = Vec2.Magnitude(vec4 - vec3);
				Fix fix5 = zero2;
				zero2 += fix4;
				if (zero2 >= fix2)
				{
					num = j - 1;
					if (fix4 == 0L)
					{
						fix4 = (Fix)0.0001f;
					}
					fix3 = (fix2 - fix5) / fix4;
					break;
				}
				vec3 = vec4;
			}
		}
		Vec2 vec5 = PathKeys[num];
		Vec2 vec6 = PathKeys[Mathf.Clamp(num + 1, 0, PathKeys.Length)];
		homePosition = vec5 + (vec6 - vec5) * fix3;
		animateVelocity.HomePosition = homePosition;
	}

	private void OnDrawGizmosSelected()
	{
		if (PathKeys == null)
		{
			return;
		}
		float radius = 0.5f;
		if (PathKeys.Length < 2)
		{
			for (int i = 0; i < PathKeys.Length; i++)
			{
				Gizmos.DrawSphere((Vector2)PathKeys[i], radius);
			}
		}
		else
		{
			Vector2 vector = (Vector2)PathKeys[0];
			Gizmos.DrawSphere(vector, radius);
			for (int j = 1; j < PathKeys.Length; j++)
			{
				Vector2 vector2 = (Vector2)PathKeys[j];
				Gizmos.DrawLine(vector, vector2);
				Gizmos.DrawSphere(vector2, radius);
				vector = vector2;
			}
		}
		if (animateVelocity != null)
		{
			Gizmos.DrawSphere((Vector2)animateVelocity.HomePosition, radius);
		}
	}
}
public class AnimateIn : MonoBehaviour
{
	public AnimationCurve Animation01;

	public Vector2 StartPosition;

	public float delay;

	public AnimationCurve LoopAnimation01;

	public Vector2 LoopPosition;

	private Vector2 origPos;

	private void Awake()
	{
		origPos = base.transform.position;
		base.transform.position = StartPosition;
	}

	private void Update()
	{
		float num = Mathf.Max(Time.timeSinceLevelLoad - delay, 0f);
		if (num < Animation01.keys[Animation01.keys.Length - 1].time)
		{
			float t = Animation01.Evaluate(num);
			base.transform.position = Vector2.LerpUnclamped(StartPosition, origPos, t);
		}
		else if (LoopAnimation01.keys.Length != 0)
		{
			float t2 = LoopAnimation01.Evaluate(num - Animation01.keys[Animation01.keys.Length - 1].time);
			base.transform.position = Vector2.LerpUnclamped(origPos, LoopPosition, t2);
		}
		else
		{
			base.enabled = false;
		}
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawLine(StartPosition, base.transform.position);
		if (LoopAnimation01.keys.Length != 0)
		{
			Gizmos.DrawLine(LoopPosition, base.transform.position);
		}
	}
}
[RequireComponent(typeof(ResizablePlatform))]
public class AnimatePlatformSize : MonoUpdatable
{
	public AnimationCurveFixed heightCurve;

	public AnimationCurveFixed widthCurve;

	public AnimationCurveFixed radiusCurve;

	private ResizablePlatform resizablePlatform;

	private StickyRoundedRectangle srr;

	private SpriteRenderer spriteRen;

	private Fix timePassed;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		spriteRen = GetComponent<SpriteRenderer>();
		srr = GetComponent<StickyRoundedRectangle>();
		resizablePlatform = GetComponent<ResizablePlatform>();
	}

	public override void Init()
	{
		UpdateSize();
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		timePassed += simDeltaTime * GameTime.PlayerTimeScale;
		UpdateSize();
	}

	private void UpdateSize()
	{
		Fix scale = srr.GetGroundBody().Scale;
		Fix rHeight = scale * Fix.Max(heightCurve.Evaluate(timePassed), (Fix)2.5f);
		Fix rWidth = scale * Fix.Max(widthCurve.Evaluate(timePassed), (Fix)2.5f);
		Fix bevelRadius = scale * Fix.Max(radiusCurve.Evaluate(timePassed), (Fix)2.5f);
		resizablePlatform.ResizePlatform(rHeight, rWidth, bevelRadius);
	}
