public class AntiLockPlatform : MonoUpdatable
{
	private AnimateVelocity animVel;

	private BoplBody body;

	private StickyRoundedRectangle srr;

	public Fix OrbitForce = (Fix)100L;

	public Vec2[] OrbitPath;

	public Fix DelaySeconds = (Fix)30L;

	private int currentTarget;

	public override void Init()
	{
		currentTarget = 0;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animVel = GetComponent<AnimateVelocity>();
		body = GetComponent<BoplBody>();
		srr = GetComponent<StickyRoundedRectangle>();
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (!GameTime.IsTimeStopped() && !(Updater.SimTimeSinceLevelLoaded < DelaySeconds) && !GameSessionHandler.SuddenDeathInProgress && currentTarget < OrbitPath.Length)
		{
			Vec2 v = OrbitPath[currentTarget] - body.position;
			body.AddForce(Vec2.NormalizedSafe(v) * OrbitForce);
			animVel.HomePosition = body.position;
			if (HasPassedCurrentTarget())
			{
				currentTarget = (currentTarget + 1) % OrbitPath.Length;
			}
		}
	}

	private bool HasPassedCurrentTarget()
	{
		Vec2 vec = OrbitPath[currentTarget];
		Vec2 vec2 = OrbitPath[(currentTarget - 1 + OrbitPath.Length) % OrbitPath.Length];
		Vec2 v = vec - vec2;
		Vec2 u = body.position - vec;
		return Vec2.Dot(v, u) > 0L;
	}

	private void OnDrawGizmos()
	{
		if (OrbitPath.Length >= 0)
		{
			Gizmos.DrawSphere((Vector3)OrbitPath[0], 1f);
			for (int i = 1; i < OrbitPath.Length; i++)
			{
				Gizmos.DrawLine((Vector3)OrbitPath[i], (Vector3)OrbitPath[i - 1]);
				Gizmos.DrawSphere((Vector3)OrbitPath[i], 0.5f);
			}
			Gizmos.DrawLine((Vector3)OrbitPath[OrbitPath.Length - 1], (Vector3)OrbitPath[0]);
			Vector3 vector = (Vector3)new Vec2(SceneBounds.BlastZone_XMin, SceneBounds.BlastZone_YMax);
			Vector3 vector2 = (Vector3)new Vec2(SceneBounds.BlastZone_XMax, SceneBounds.BlastZone_YMax);
			Vector3 vector3 = (Vector3)new Vec2(SceneBounds.BlastZone_XMin, SceneBounds.WaterHeight);
			Vector3 vector4 = (Vector3)new Vec2(SceneBounds.BlastZone_XMax, SceneBounds.WaterHeight);
			Gizmos.DrawLine(vector, vector3);
			Gizmos.DrawLine(vector3, vector4);
			Gizmos.DrawLine(vector4, vector2);
			Gizmos.DrawLine(vector2, vector);
		}
	}
}
