public struct InterruptableAudio
{
	public AudioSource source;

	public int timesPlayed;

	public int index;

	public InterruptableAudio(AudioSource source, int numberOfTimesPlayed, int index)
	{
		this.source = source;
		timesPlayed = numberOfTimesPlayed;
		this.index = index;
	}

	public void TryPause(bool pause)
	{
		if (source != null && timesPlayed == AudioManager.Get().TimesSoundsPlayed(this))
		{
			if (pause)
			{
				source.Pause();
			}
			else
			{
				source.UnPause();
			}
		}
	}
}
public class AudioManager : MonoBehaviour
{
	public Settings settings;

	public float originalMasterVolume = 1f;

	public float musicVolumeMultiplier = 0.3f;

	private float currentMasterVolume;

	private float currentMusicVolume;

	private int[] timesSoundPlayed;

	private bool[] isSoundLooping;

	public Sound[] sounds;

	public Song[] songs;

	public Song menuSong;

	public Song[] test_songs;

	private static AudioManager instance;

	public float MusicRecoveryPerSecond01 = 0.3f;

	public bool realTimeUpdateVolumes_testOnly;

	private float musicFadeThisFrame;

	private System.Random seed;

	private AudioSource musicPlayer;

	private AudioSource introMusicPlayer;

	private bool inMenus;

	private int currentSongIndex;

	private float timeSpentOnThisSong;

	private float currentClipPitch;

	public float suddenDeathSpeedUp = 0.2f;

	public float originalMusicVolume => (float)settings.MusicVolume * 0.1f;

	public float sfxVolume => (float)settings.SfxVolume * 0.1f;

	public int TimesSoundsPlayed(InterruptableAudio interruptableAudio)
	{
		return timesSoundPlayed[interruptableAudio.index];
	}

	private void Update()
	{
		if (musicFadeThisFrame == 0f)
		{
			currentMusicVolume = Mathf.Lerp(currentMusicVolume, originalMusicVolume, MusicRecoveryPerSecond01 * Time.deltaTime);
		}
		else
		{
			currentMusicVolume = Mathf.Clamp(currentMusicVolume - musicFadeThisFrame * Time.deltaTime, 0f, originalMusicVolume);
			musicFadeThisFrame = 0f;
		}
		musicPlayer.volume = currentMusicVolume * currentMasterVolume * musicVolumeMultiplier;
		introMusicPlayer.volume = currentMusicVolume * currentMasterVolume * musicVolumeMultiplier;
		timeSpentOnThisSong += Time.deltaTime;
		if (realTimeUpdateVolumes_testOnly)
		{
			for (int i = 0; i < sounds.Length; i++)
			{
				sounds[i].source.volume = sounds[i].volume * currentMasterVolume * sfxVolume;
			}
		}
	}

	private void LateUpdate()
	{
		for (int i = 0; i < isSoundLooping.Length; i++)
		{
			float num = sounds[i].volume * currentMasterVolume * sfxVolume;
			if (!sounds[i].loop)
			{
				continue;
			}
			if (isSoundLooping[i] && !sounds[i].source.isPlaying)
			{
				sounds[i].source.Play();
			}
			else if (isSoundLooping[i] && sounds[i].source.isPlaying)
			{
				if (sounds[i].fadeLoop)
				{
					sounds[i].source.volume = Mathf.Min(sounds[i].source.volume + Time.deltaTime * num, num);
				}
				else
				{
					sounds[i].source.volume = num;
				}
			}
			else if (!isSoundLooping[i] && sounds[i].source.isPlaying)
			{
				if (sounds[i].source.volume <= 0f)
				{
					sounds[i].source.Stop();
				}
				else if (sounds[i].fadeLoop)
				{
					sounds[i].source.volume = Mathf.Max(sounds[i].source.volume - Time.deltaTime * num, 0f);
				}
				else
				{
					sounds[i].source.Stop();
				}
			}
			isSoundLooping[i] = false;
		}
	}

	public void FadeOutMusicTick(float str01)
	{
		musicFadeThisFrame = Mathf.Max(str01, musicFadeThisFrame);
	}

	public static AudioManager Get()
	{
		if (instance == null)
		{
			UnityEngine.Debug.LogError("Attempted to access AudioManager before it has been initialized. Do not call Get() in awake");
		}
		return instance;
	}

	public void UpdateMusicMasterVolume()
	{
		currentMasterVolume = originalMasterVolume;
		currentMusicVolume = originalMusicVolume;
	}

	private void Awake()
	{
		UpdateMusicMasterVolume();
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		if (instance == null)
		{
			instance = this;
			seed = new System.Random();
			instance = this;
			timesSoundPlayed = new int[sounds.Length];
			isSoundLooping = new bool[sounds.Length];
			for (int i = 0; i < sounds.Length; i++)
			{
				sounds[i].source = base.gameObject.AddComponent<AudioSource>();
			}
			ReInitializeSfx();
			introMusicPlayer = base.gameObject.AddComponent<AudioSource>();
			musicPlayer = base.gameObject.AddComponent<AudioSource>();
		}
		else
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	public void ReInitializeSfx()
	{
		for (int i = 0; i < sounds.Length; i++)
		{
			sounds[i].source.clip = sounds[i].clip;
			sounds[i].source.volume = sounds[i].volume * currentMasterVolume * sfxVolume;
			sounds[i].source.pitch = sounds[i].pitch;
			sounds[i].source.loop = sounds[i].loop;
		}
	}

	public AudioSource Play(string name, float delay)
	{
		for (int i = 0; i < sounds.Length; i++)
		{
			if (sounds[i].name != null && sounds[i].name.Equals(name))
			{
				sounds[i].source.pitch = sounds[i].pitch;
				sounds[i].source.PlayDelayed(delay);
				timesSoundPlayed[i]++;
				return sounds[i].source;
			}
		}
		UnityEngine.Debug.LogWarning("Could not play non-existent sound " + name);
		return null;
	}

	public AudioSource Play(string name, float delay, float pitchVariation)
	{
		for (int i = 0; i < sounds.Length; i++)
		{
			if (sounds[i].name != null && sounds[i].name.Equals(name))
			{
				sounds[i].source.pitch = sounds[i].pitch + ((float)seed.NextDouble() - 0.5f) * 2f * pitchVariation;
				sounds[i].source.PlayDelayed(delay);
				timesSoundPlayed[i]++;
				return sounds[i].source;
			}
		}
		UnityEngine.Debug.LogWarning("Could not play non-existent sound " + name);
		return null;
	}

	public void PlayOrContinueLoop(string name)
	{
		for (int i = 0; i < sounds.Length; i++)
		{
			if (sounds[i].name != null && sounds[i].name.Equals(name))
			{
				isSoundLooping[i] = true;
				return;
			}
		}
		UnityEngine.Debug.LogWarning("Could not play non-existent sound " + name);
	}

	public InterruptableAudio PlayInterruptable(string name)
	{
		for (int i = 0; i < sounds.Length; i++)
		{
			if (sounds[i].name != null && sounds[i].name.Equals(name))
			{
				sounds[i].source.Play();
				timesSoundPlayed[i]++;
				return new InterruptableAudio(sounds[i].source, timesSoundPlayed[i], i);
			}
		}
		UnityEngine.Debug.LogWarning("Could not play non-existent sound " + name);
		return new InterruptableAudio(null, -1, -1);
	}

	public void Play(string name)
	{
		Play(name, 0f);
	}

	public void PlayWithRandomPitchVariation(string name, float variation = 0.2f)
	{
		Play(name, 0f, variation);
	}

	public void OnEnteredMenus()
	{
		if (!inMenus)
		{
			StartMenuMusic();
			inMenus = true;
		}
	}

	public void OnMatchStarted()
	{
		if (inMenus)
		{
			currentSongIndex = 0;
			timeSpentOnThisSong = 0f;
			inMenus = false;
			StartMusic(currentSongIndex);
			return;
		}
		Song[] array = ((test_songs != null && test_songs.Length != 0) ? test_songs : songs);
		if (timeSpentOnThisSong > array[currentSongIndex].intro.length + array[currentSongIndex].songLoop.length)
		{
			currentSongIndex = (currentSongIndex + 1) % array.Length;
			timeSpentOnThisSong = 0f;
			StartMusic(currentSongIndex);
		}
	}

	public void OnMatchEnded(bool isDraw)
	{
		if (isDraw)
		{
			musicPlayer.Stop();
			timeSpentOnThisSong = 10000000f;
		}
		stopSuddenDeathShift();
	}

	private void StartMenuMusic()
	{
		musicPlayer.Stop();
		introMusicPlayer.Stop();
		Song song = menuSong;
		currentClipPitch = song.pitch;
		musicPlayer.clip = song.songLoop;
		musicPlayer.volume = currentMusicVolume * currentMasterVolume * musicVolumeMultiplier;
		musicPlayer.pitch = song.pitch;
		musicPlayer.loop = true;
		musicPlayer.PlayDelayed((song.introLength > 0f) ? song.introLength : song.intro.length);
		introMusicPlayer.clip = song.intro;
		introMusicPlayer.volume = currentMusicVolume * currentMasterVolume * musicVolumeMultiplier;
		introMusicPlayer.pitch = song.pitch;
		introMusicPlayer.loop = false;
		introMusicPlayer.Play();
	}

	private void StartMusic(int songIndex)
	{
		musicPlayer.Stop();
		introMusicPlayer.Stop();
		Song song = ((test_songs != null && test_songs.Length != 0) ? test_songs : songs)[songIndex];
		currentClipPitch = song.pitch;
		musicPlayer.clip = song.songLoop;
		musicPlayer.volume = currentMusicVolume * currentMasterVolume * musicVolumeMultiplier;
		musicPlayer.pitch = song.pitch;
		musicPlayer.loop = true;
		musicPlayer.PlayDelayed((song.introLength > 0f) ? song.introLength : song.intro.length);
		introMusicPlayer.clip = song.intro;
		introMusicPlayer.volume = currentMusicVolume * currentMasterVolume * musicVolumeMultiplier;
		introMusicPlayer.pitch = song.pitch;
		introMusicPlayer.loop = false;
		introMusicPlayer.Play();
	}

	public void suddenDeathMusicShift()
	{
		musicPlayer.pitch = currentClipPitch + suddenDeathSpeedUp;
		introMusicPlayer.pitch = currentClipPitch + suddenDeathSpeedUp;
	}

	public void stopSuddenDeathShift()
	{
		musicPlayer.pitch = currentClipPitch;
		introMusicPlayer.pitch = currentClipPitch;
	}

	public void StopMusic()
	{
		musicPlayer.Stop();
		introMusicPlayer.Stop();
	}

	public void PauseMusic()
	{
		musicPlayer.Pause();
		introMusicPlayer.Pause();
	}

	public void UnPauseMusic()
	{
		musicPlayer.UnPause();
		introMusicPlayer.UnPause();
	}

	public void PlayRandomWithPrefix(string prefix, float delay = 0f)
	{
		List<int> list = new List<int>();
		for (int i = 0; i < sounds.Length; i++)
		{
			if (sounds[i].name.StartsWith(prefix) && !sounds[i].source.isPlaying && !sounds[i].loop)
			{
				list.Add(i);
			}
		}
		if (list.Count != 0)
		{
			int index = seed.Next(0, list.Count - 1);
			sounds[list[index]].source.PlayDelayed(delay);
			timesSoundPlayed[list[index]]++;
		}
	}

	public void PlayPrefixWithInterrupts(string prefix)
	{
		int num = 0;
		int num2 = -1;
		float num3 = 10000f;
		for (int i = 0; i < sounds.Length; i++)
		{
			if (sounds[i].name.StartsWith(prefix) && !sounds[i].loop)
			{
				num++;
				if (sounds[i].source.time / sounds[i].source.clip.length < num3)
				{
					num3 = sounds[i].source.time;
					num2 = i;
				}
			}
		}
		if (num == 0)
		{
			UnityEngine.Debug.LogWarning("Could not find sound with prefix: " + prefix);
			return;
		}
		timesSoundPlayed[num2]++;
		sounds[num2].source.Play();
	}
}
