public class CSBox_online : MonoBehaviour
{
	public TextMeshProUGUI[] textsToColor;

	public UnityEngine.UI.Image[] borderImages;

	public UnityEngine.UI.Image[] fillImages;

	public UnityEngine.UI.Image[] characters;

	[SerializeField]
	private TeamColors teamColors;

	[SerializeField]
	private PlayerColors playerColors;

	public SteamConnection connectedPlayer;

	public AnimateInOutUI choosingText;

	public AnimateInOutUI readyText;

	public TextMeshProUGUI pingText;

	public TextMeshProUGUI playerNameText;

	private bool choosingTextIsVisible = true;

	private AnimateInOutUI animateInOut;

	[HideInInspector]
	public bool isVisible;

	private int currentlyDisplayedPing;

	private float timeSinceLastPing;

	public float TimeSecondsBetweenPings = 0.33f;

	private static byte[] ackPingBuffer = new byte[6];

	public void AnimateOut()
	{
		animateInOut.AnimateOut();
		isVisible = false;
	}

	public void Init(SteamConnection targetPlayer)
	{
		if (!choosingTextIsVisible)
		{
			readyText.AnimateOut();
		}
		connectedPlayer = targetPlayer;
		choosingTextIsVisible = true;
		if (SteamManager.instance.currentLobby.IsOwnedBy(targetPlayer.id))
		{
			targetPlayer.lobby_team = 0;
		}
		else
		{
			for (byte b = 1; b < 4; b++)
			{
				bool flag = false;
				for (int i = 0; i < SteamManager.instance.connectedPlayers.Count; i++)
				{
					SteamConnection steamConnection = SteamManager.instance.connectedPlayers[i];
					flag |= steamConnection.lobby_team == b;
				}
				if (!flag)
				{
					targetPlayer.lobby_team = b;
					break;
				}
			}
		}
		if (Settings.Get().Hide == 0)
		{
			playerNameText.text = targetPlayer.steamName;
		}
		else
		{
			playerNameText.text = string.Empty;
		}
		isVisible = true;
		choosingText.AnimateIn();
		animateInOut.AnimateIn();
	}

	private void updatePing()
	{
		int num = (int)(connectedPlayer.Ping * 1000f);
		if (currentlyDisplayedPing != num)
		{
			currentlyDisplayedPing = num;
			pingText.text = num + "ms";
		}
		timeSinceLastPing += Time.deltaTime;
		if (!(timeSinceLastPing < TimeSecondsBetweenPings))
		{
			timeSinceLastPing = 0f;
			connectedPlayer.SendPing(Time.timeSinceLevelLoad, ackPingBuffer);
		}
	}

	private void Awake()
	{
		animateInOut = GetComponent<AnimateInOutUI>();
	}

	private void Update()
	{
		if (connectedPlayer == null || !connectedPlayer.Connected)
		{
			if (isVisible)
			{
				animateInOut.AnimateOut();
				isVisible = false;
			}
			connectedPlayer = null;
		}
		else
		{
			if (connectedPlayer.lobby_team < 0 || connectedPlayer.lobby_color < 0)
			{
				return;
			}
			updatePing();
			TeamColor teamColor = teamColors.teamColors[connectedPlayer.lobby_team];
			Material material = characters[0].material;
			if (connectedPlayer.lobby_isReady && choosingTextIsVisible)
			{
				choosingText.AnimateOut();
				readyText.AnimateIn();
				choosingTextIsVisible = false;
			}
			else if (!connectedPlayer.lobby_isReady && !choosingTextIsVisible)
			{
				choosingText.AnimateOut_reverse();
				readyText.AnimateIn_reverse();
				choosingTextIsVisible = true;
			}
			for (int i = 0; i < playerColors.Length; i++)
			{
				if (playerColors[i].colorIndex == connectedPlayer.lobby_color)
				{
					material = playerColors[i].uiMaterial;
					break;
				}
			}
			for (int j = 0; j < textsToColor.Length; j++)
			{
				textsToColor[j].color = teamColor.border;
			}
			for (int k = 0; k < borderImages.Length; k++)
			{
				borderImages[k].color = teamColor.border;
			}
			for (int l = 0; l < fillImages.Length; l++)
			{
				fillImages[l].color = teamColor.fill;
			}
			for (int m = 0; m < characters.Length; m++)
			{
				characters[m].material = material;
			}
		}
	}
}
public class CursorUpdater : MonoBehaviour
{
	public Texture2D originalTexture;

	public Texture2D CursorBufferTexture;

	public bool alwaysHideCursorInstead;

	public UnityEngine.Color defaultCursorColor;

	public static CursorUpdater selfRef;

	private Texture2D tempTexture;

	private Texture texNative;

	private void Awake()
	{
		selfRef = this;
	}

	private void Start()
	{
		initialize();
	}

	private void initialize()
	{
		if (alwaysHideCursorInstead)
		{
			Cursor.SetCursor(null, Vector2.one / 2f, CursorMode.Auto);
			Cursor.visible = false;
			return;
		}
		if (!Cursor.visible)
		{
			Cursor.visible = true;
		}
		PlayerInput[] array = UnityEngine.Object.FindObjectsOfType<PlayerInput>();
		if (array.Length == 0)
		{
			SetCursor(defaultCursorColor);
			return;
		}
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].currentControlScheme.Equals("KeyboardAndMouse"))
			{
				int claimerId = array[i].GetComponent<InputUpdater>().GetClaimerId();
				Player player = PlayerHandler.Get().GetPlayer(claimerId);
				if (player != null)
				{
					UnityEngine.Color color = player.Color.GetColor("_ShadowColor");
					SetCursor(color);
				}
				break;
			}
		}
	}

	public void SetCursor(UnityEngine.Color CursorColor)
	{
		Cursor.SetCursor(null, Vector2.zero, CursorMode.Auto);
		UnityEngine.Color[] pixels = originalTexture.GetPixels(0, 0, originalTexture.width, originalTexture.height);
		for (int i = 0; i < pixels.Length; i++)
		{
			float a = pixels[i].a;
			pixels[i] = UnityEngine.Color.Lerp(UnityEngine.Color.black, CursorColor, pixels[i].g);
			pixels[i].a = a;
		}
		CursorBufferTexture.SetPixels(0, 0, originalTexture.width, originalTexture.height, pixels);
		CursorBufferTexture.Apply(updateMipmaps: false, makeNoLongerReadable: false);
		Cursor.SetCursor(CursorBufferTexture, Vector2.zero, CursorMode.Auto);
	}
}
public class DeathEffect2 : MonoUpdatable
{
	private SpriteRenderer spriteRen;

	private FixTransform fixTrans;

	private SpriteAnimator spriteAnim;

	public Fix gibbMaxDistance;

	public GameObject groundSplashEffect;

	public int numberGibbs;

	public AnimationData animData;

	private bool vibrate;

	public int hitStopFrames = 5;

	private Vector3 prevDisp;

	public float shakeStr;

	public void SpawnRandomSplash(Vector3 pos, Material mat)
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(groundSplashEffect, pos, Quaternion.Euler(0f, 0f, 360f * UnityEngine.Random.value));
		gameObject.transform.localScale = new Vector3(UnityEngine.Random.value / 2f + 0.5f, UnityEngine.Random.value / 2f + 0.5f, 1f) * base.transform.localScale.x;
		gameObject.GetComponent<SpriteRenderer>().material = mat;
		AudioManager.Get().PlayRandomWithPrefix("slimeSplash", gameObject.transform.localScale.x * 0.2f);
	}

	private void SelfDestruct()
	{
		Updater.DestroyFix(base.gameObject);
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		spriteRen = GetComponent<SpriteRenderer>();
		fixTrans = GetComponent<FixTransform>();
		spriteAnim = GetComponent<SpriteAnimator>();
	}

	public override void Init()
	{
		AudioManager.Get().Play("slimeDeath");
		spriteAnim.beginAnimThenDoAction(animData.GetAnimation("anticipation"), startExplode);
		vibrate = true;
		Updater.HitStop(hitStopFrames);
	}

	private void startExplode()
	{
		spriteAnim.beginAnimThenDoAction(animData.GetAnimation("start"), OnExplode);
		vibrate = false;
	}

	private void LateUpdate()
	{
		if (Updater.InHitstop() || (vibrate && !GameTime.IsTimeStopped()))
		{
			base.transform.position -= prevDisp;
			prevDisp = (Vector3)UnityEngine.Random.insideUnitCircle * shakeStr;
			base.transform.position += prevDisp;
		}
	}

	public void OnExplode()
	{
		for (int i = 0; i < numberGibbs; i++)
		{
			Fix x = (Fix)i * Fix.One / (Fix)numberGibbs * Fix.PiTimes2;
			Vec2 dir = new Vec2(Fix.Cos(x), Fix.Sin(x));
			RaycastInformation raycastInformation = DetPhysics.Get().RaycastToClosestRoundedRect(fixTrans.position, dir, gibbMaxDistance);
			if ((bool)raycastInformation)
			{
				SpawnRandomSplash((Vector3)raycastInformation.nearPos, spriteRen.material);
			}
		}
		spriteAnim.beginAnimThenDoAction(animData.GetAnimation("end"), SelfDestruct);
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}
}
public class DestroyIfOutsideSceneBounds : MonoUpdatable
{
	public bool DestroyIfTooFarX;

	public bool DestroyIfTooFarY = true;

	public bool DoNotDestroyUp;

	public GameObject XEffect;

	public GameObject UpEffect;

	public GameObject DownEffect;

	public bool UsePlayerMaterialForXEffect;

	public bool UsePlayerMaterialForUpEffect;

	public bool UsePlayerMaterialForDownEffect;

	private FixTransform fixTrans;

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
	}

	private void ColorIfPlayerObject(bool UsePlayerMaterialForXEffect, ref GameObject inst)
	{
		if (!UsePlayerMaterialForXEffect)
		{
			return;
		}
		IPlayerIdHolder component = GetComponent<IPlayerIdHolder>();
		if (component != null)
		{
			SpriteRenderer component2 = inst.GetComponent<SpriteRenderer>();
			if (component2 != null)
			{
				component2.material = component.GetPlayerMaterial();
			}
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (!Constants.isSpaceLevel && DestroyIfTooFarY && fixTrans.position.y < SceneBounds.WaterHeight)
		{
			if (DownEffect != null)
			{
				Vec2 pos = fixTrans.position + DownEffect.GetComponent<FixTransform>().position;
				pos.y = SceneBounds.WaterHeight - (Fix)1.47f * fixTrans.Scale;
				GameObject inst = FixTransform.InstantiateFixed(DownEffect, pos);
				inst.transform.localScale *= (float)fixTrans.Scale;
				ColorIfPlayerObject(UsePlayerMaterialForDownEffect, ref inst);
			}
			selfDestruct();
		}
		else if (Constants.isSpaceLevel && DestroyIfTooFarY && fixTrans.position.y < SceneBounds.Camera_YMin)
		{
			if (UpEffect != null)
			{
				Vec2 pos2 = fixTrans.position + UpEffect.GetComponent<FixTransform>().position;
				pos2.y = SceneBounds.Camera_YMin;
				GameObject inst2 = FixTransform.InstantiateFixed(UpEffect, pos2);
				ColorIfPlayerObject(UsePlayerMaterialForUpEffect, ref inst2);
			}
			selfDestruct();
		}
		else if (!DoNotDestroyUp && DestroyIfTooFarY && fixTrans.position.y > SceneBounds.BlastZone_YMax)
		{
			if (UpEffect != null)
			{
				Vec2 pos3 = fixTrans.position + UpEffect.GetComponent<FixTransform>().position;
				pos3.y = SceneBounds.BlastZone_YMax;
				GameObject inst3 = FixTransform.InstantiateFixed(UpEffect, pos3);
				ColorIfPlayerObject(UsePlayerMaterialForUpEffect, ref inst3);
			}
			selfDestruct();
		}
		else
		{
			if (!DestroyIfTooFarX || (!(fixTrans.position.x < SceneBounds.BlastZone_XMin) && !(fixTrans.position.x > SceneBounds.BlastZone_XMax)))
			{
				return;
			}
			if (XEffect != null)
			{
				Vec2 position = fixTrans.position;
				if (fixTrans.position.x < SceneBounds.BlastZone_XMin)
				{
					position.x = SceneBounds.BlastZone_XMin;
				}
				else
				{
					position.x = SceneBounds.BlastZone_XMax;
				}
				position += XEffect.GetComponent<FixTransform>().position;
				GameObject inst4 = FixTransform.InstantiateFixed(XEffect, position);
				ColorIfPlayerObject(UsePlayerMaterialForXEffect, ref inst4);
			}
			selfDestruct();
		}
	}

	private void selfDestruct()
	{
		if (LayerMask.NameToLayer("Projectile") == base.gameObject.layer || LayerMask.NameToLayer("item") == base.gameObject.layer)
		{
			Updater.DestroyFix(base.gameObject);
			return;
		}
		IPlayerIdHolder component = GetComponent<IPlayerIdHolder>();
		if (component != null)
		{
			IAbilityComponent component2 = GetComponent<IAbilityComponent>();
			if (component2 != null)
			{
				component2.ExitAbility(new AbilityExitInfo
				{
					position = fixTrans.position,
					isDead = true,
					killerId = Constants.ENVIRONMENTAL_PLAYER_ID
				});
				return;
			}
			int playerId = component.GetPlayerId();
			Player player = PlayerHandler.Get().GetPlayer(playerId);
			PlayerCollision component3 = GetComponent<PlayerCollision>();
			if (component3 != null)
			{
				component3.killPlayer(Constants.ENVIRONMENTAL_PLAYER_ID, spawnEffect: false, ignoreInvulnerability: true, CauseOfDeath.Accident);
				return;
			}
			player?.Kill(Constants.ENVIRONMENTAL_PLAYER_ID, Updater.SimulationTicks, CauseOfDeath.Accident);
		}
		Updater.DestroyFix(base.gameObject);
	}

