	public void OnPlayerJoined(PlayerInput playerInput)
	{
		InputDevices.Add(playerInput.GetComponent<InputUpdater>());
	}

	public void InitClaimedInputDevices()
	{
		for (int i = 0; i < InputDevices.Count; i++)
		{
			if (InputDevices[i].HasBeenClaimed())
			{
				InputDevices[i].Init(InputDevices[i].GetClaimerId());
