public class DummyGameHandler : MonoBehaviour
{
	public SlimeController[] playerObjects;

	public InputUpdater[] inputUpdaters;

	public bool useListOfInputUpdaters;

	private int localPlayerId;

	public LevelType levelType;

	private void Start()
	{
		Shader.SetGlobalFloat("_Timestop01", 1f);
		AudioManager.Get().OnMatchEnded(isDraw: true);
		AudioManager.Get().OnMatchStarted();
	}

	private void Awake()
	{
		GameSession.Init();
		TutorialGameHandler.isInTutorial = true;
		string[] commandLineArgs = Environment.GetCommandLineArgs();
		localPlayerId = 1;
		Constants.leveltype = levelType;
		for (int i = 0; i < commandLineArgs.Length; i++)
		{
			if (commandLineArgs[i].StartsWith("PLAYERID="))
			{
				localPlayerId = int.Parse(commandLineArgs[i].Substring("PLAYERID=".Length));
			}
		}
		List<Player> list = new List<Player>();
		for (int j = 0; j < playerObjects.Length; j++)
		{
			Player player = new Player(playerObjects[j].GetPlayerId(), j);
			player.Color = playerObjects[j].GetComponentInChildren<SpriteRenderer>().material;
			player.playersAndClonesStillAlive = 1;
			if (j == 0)
			{
				player.UsesKeyboardAndMouse = true;
			}
			else
			{
				player.UsesKeyboardAndMouse = false;
			}
			player.CurrentAbilities = new List<GameObject>();
			for (int k = 0; k < playerObjects[j].abilities.Count; k++)
			{
				player.CurrentAbilities.Add(playerObjects[j].abilities[k].gameObject);
				playerObjects[j].AbilityReadyIndicators[k].GetComponent<SpriteRenderer>().sprite = playerObjects[j].abilityIconsFull.FindSprite(playerObjects[j].abilities[k].gameObject.name);
			}
			list.Add(player);
		}
		PlayerHandler.Get().SetPlayerList(list);
		if (!useListOfInputUpdaters)
		{
			UnityEngine.Object.FindObjectOfType<InputUpdater>().Init(localPlayerId);
			return;
		}
		for (int l = 0; l < inputUpdaters.Length && l < playerObjects.Length; l++)
		{
			int playerId = playerObjects[l].GetPlayerId();
			if (inputUpdaters[l].GetComponent<PlayerInput>().devices.Count > 0)
			{
				PlayerHandler.Get().GetPlayer(playerId).inputDevice = inputUpdaters[l].GetComponent<PlayerInput>().devices[0];
			}
			inputUpdaters[l].Init(playerId);
		}
	}
}
public class DynamicAbilityPickup : MonoUpdatable, ICollisionCallback
{
	public Fix UpForce = Fix.One;

	private SpriteRenderer spriteRen;

	private DPhysicsCircle hitbox;

	private BoplBody body;

	private GameObject abilityPrefab;

	public NamedSpriteList abilityIcons;

	public NamedSpriteList abilityIcons_demo;

	public Fix wobbleSpeed = (Fix)10L;

	public Fix hoverHeight = (Fix)0.1f;

	public Fix wobbleAmount = (Fix)3L;

	public Fix launchForce = (Fix)1000f;

	public Fix disabledSeconds = (Fix)1f;

	private Fix timePassed;

	public Fix SwapAbilityPeriod = (Fix)10L;

	private Fix timeSinceAbilitySwap;

	public bool initSelf;

	public AnimationCurveFixed scaleAnimOnAbilitySwap;

	public Fix vibrationStr;

	public Fix vibrationDuration;

	public Fix animTimingOffset;

	public Fix vibrateTimingOffset;

	private Vec2 prevVibrationPos;

	public Fix gravity = (Fix)40L;

	public Fix pushAwayFromOtherWeaponsStr;

	public override void Init()
	{
		if (initSelf)
		{
			for (int i = 0; i < abilityIcons.sprites.Count; i++)
			{
				if (abilityIcons.sprites[i].sprite == spriteRen.sprite)
				{
					InitPickup(abilityIcons.sprites[i].associatedGameObject, abilityIcons.sprites[i].sprite, Vec2.up);
					break;
				}
			}
		}
		timeSinceAbilitySwap = Fix.Zero;
		prevVibrationPos = Vec2.zero;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		spriteRen = GetComponent<SpriteRenderer>();
		hitbox = GetComponent<DPhysicsCircle>();
		hitbox.RegisterCollisionCallback(this);
		body = GetComponent<BoplBody>();
	}

	private void Update()
	{
		Fix fix = (timeSinceAbilitySwap + SwapAbilityPeriod - animTimingOffset) % SwapAbilityPeriod;
		UnityEngine.Debug.DrawLine(Vector3.zero, Vector3.right * (float)timeSinceAbilitySwap, UnityEngine.Color.red);
		UnityEngine.Debug.DrawLine(Vector3.up, Vector3.up + Vector3.right * (float)fix, UnityEngine.Color.magenta);
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (GameTime.IsTimeStopped())
		{
			body.velocity = Vec2.zero;
		}
		else
		{
			timePassed += simDeltaTime;
			timeSinceAbilitySwap += simDeltaTime;
		}
		if (timePassed >= disabledSeconds && !hitbox.enabled)
		{
			hitbox.enabled = true;
			UnityEngine.Color color = spriteRen.color;
			color.a = 1f;
			spriteRen.color = color;
		}
		if (timeSinceAbilitySwap > SwapAbilityPeriod)
		{
			timeSinceAbilitySwap = Fix.Zero;
			SwapToRandomAbility();
		}
		Fix t = (timeSinceAbilitySwap + SwapAbilityPeriod - animTimingOffset) % SwapAbilityPeriod;
		Fix fix = scaleAnimOnAbilitySwap.Evaluate(t);
		float num = (float)body.Scale + (float)fix;
		base.transform.localScale = new Vector3(num, num, 1f);
		if ((timeSinceAbilitySwap + SwapAbilityPeriod - vibrateTimingOffset) % SwapAbilityPeriod > SwapAbilityPeriod - vibrationDuration)
		{
			body.position -= prevVibrationPos;
			prevVibrationPos = Updater.RandomInsideUnitCircle() * vibrationStr;
			body.position += prevVibrationPos;
		}
		Fix fix2 = body.position.y - (Constants.isSpaceLevel ? ((Fix)(-1000L)) : Constants.WATER_HEIGHT);
		RaycastInformation raycastInformation = DetPhysics.Get().RaycastToClosestRoundedRect(hitbox.position, Vec2.down, (Fix)10000000L);
		if ((bool)raycastInformation)
		{
			fix2 = raycastInformation.nearDist;
		}
		if (fix2 < (Fix)0.5)
		{
			body.velocity *= (Fix)0.95;
		}
		Fix fix3 = Fix.Max(fix2, Fix.One);
		Fix fix4 = Fix.Sin(Updater.SimTimeSinceLevelLoaded * wobbleSpeed) * wobbleAmount;
		body.velocity += Vec2.down * gravity * simDeltaTime;
		body.AddForce(fix4 * Vec2.up + Vec2.up * (UpForce / fix3));
	}

	public void SwapToRandomAbility()
	{
		NamedSprite randomAbilityPrefab = RandomAbility.GetRandomAbilityPrefab(abilityIcons, abilityIcons_demo, spriteRen.sprite);
		spriteRen.sprite = randomAbilityPrefab.sprite;
		abilityPrefab = randomAbilityPrefab.associatedGameObject;
	}

	public void InitPickup(GameObject abilityPrefab, Sprite playerIcon, Vec2 launchDirection)
	{
		this.abilityPrefab = abilityPrefab;
		spriteRen.sprite = playerIcon;
		if (hitbox.manuallyCallInit)
		{
			hitbox.ManualInit();
		}
		hitbox.enabled = false;
		UnityEngine.Color color = spriteRen.color;
		color.a = 0.75f;
		spriteRen.color = color;
		body.AddForce(launchDirection * launchForce, ForceMode2D.Impulse);
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (collision.layer != LayerMask.NameToLayer("weapon"))
		{
			SlimeController component = collision.colliderPP.fixTrans.GetComponent<SlimeController>();
			if ((bool)component)
			{
				AbilityMonoBehaviour component2 = FixTransform.InstantiateFixed(abilityPrefab, Vec2.zero, Fix.Zero).GetComponent<AbilityMonoBehaviour>();
				component.AddAdditionalAbility(component2, spriteRen.sprite, abilityPrefab);
				Updater.DestroyFix(base.gameObject);
			}
		}
	}
}
