public class Explosion : MonoUpdatable
{
	public float cameraShakeTrauma;

	public bool canHurtOwner = true;

	public bool hitBoxActiveOnlyFirstFrame = true;

	public bool igniteFlammables = true;

	public AnimationData explosionAnimation;

	private IPhysicsCollider hitbox;

	private ShakableCamera cam;

	private SpriteAnimator spriteAnim;

	private bool isOnFirstFrame = true;

	public int PlayerOwnerId { get; set; }

	private void ActivateHitBox()
	{
		hitbox.enabled = true;
		cam.AddTrauma(cameraShakeTrauma);
	}

	private void DeactivateHitBox()
	{
		hitbox.enabled = false;
	}

	public override void Init()
	{
		isOnFirstFrame = true;
		if (hitbox == null)
		{
			hitbox = GetComponent<IPhysicsCollider>();
		}
		if (cam == null)
		{
			cam = Camera.main.transform.parent.GetComponent<ShakableCamera>();
		}
		if (hitBoxActiveOnlyFirstFrame)
		{
			ActivateHitBox();
		}
		if (explosionAnimation != null)
		{
			spriteAnim.beginAnimThenDoAction(explosionAnimation.animations[0].animation, SelfDestruct);
		}
	}

	private void SelfDestruct()
	{
		Updater.DestroyFix(base.gameObject);
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (hitBoxActiveOnlyFirstFrame && !isOnFirstFrame)
		{
			DeactivateHitBox();
		}
		isOnFirstFrame = false;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		hitbox = GetComponent<IPhysicsCollider>();
		cam = Camera.main.transform.parent.GetComponent<ShakableCamera>();
		spriteAnim = GetComponent<SpriteAnimator>();
	}
}
public class FlammableSmoke : MonoUpdatable, ICollisionCallback
{
	public Explosion ExplosionPrefab;

	public AnimationData animData;

	public Fix[] SmokeRadius;

	private Item item;

	private SpriteAnimator spriteAnimator;

	private SpriteRenderer childSpriteRen;

	private DPhysicsCircle circleCollider;

	private FixTransform fixTrans;

	private bool enter;

	public Fix maxDetonationDelay = (Fix)0.5f;

	public Fix minDetonationDelay = (Fix)0.5f;

	private Fix timeSinceDetonated = (Fix)(-1L);

	private Fix detonationDelay;

	public void SetPlayerOwnerId(int id)
	{
		item.OwnerId = id;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		item = GetComponent<Item>();
		spriteAnimator = GetComponent<SpriteAnimator>();
		circleCollider = GetComponent<DPhysicsCircle>();
		circleCollider.RegisterCollisionCallback(this);
		fixTrans = GetComponent<FixTransform>();
		circleCollider.radius = SmokeRadius[0] * circleCollider.Scale;
		childSpriteRen = base.transform.GetChild(0).GetComponent<SpriteRenderer>();
		childSpriteRen.sprite = animData.GetAnimation("enter")[0].sprite;
		GetComponent<SpriteRenderer>().sprite = childSpriteRen.sprite;
	}

	public override void Init()
	{
		enter = true;
		spriteAnimator.beginAnimThenDoAction(animData.GetAnimation("enter"), Loop);
		childSpriteRen.sprite = spriteAnimator.getCurrentSprite();
		detonationDelay = Updater.RandomFix(minDetonationDelay, maxDetonationDelay);
		timeSinceDetonated = (Fix)(-1L);
	}

	private void Loop()
	{
		enter = false;
		spriteAnimator.beginAnimation(animData.GetAnimation("loop"));
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		int num = (enter ? (spriteAnimator.getNumberOfPassedSprites() - 1) : (SmokeRadius.Length - 1));
		circleCollider.radius = SmokeRadius[num] * circleCollider.Scale;
		childSpriteRen.sprite = spriteAnimator.getCurrentSprite();
		if (timeSinceDetonated >= 0L)
		{
			timeSinceDetonated += simDeltaTime * GameTime.PlayerTimeScale;
			if (timeSinceDetonated > detonationDelay)
			{
				Explosion explosion = FixTransform.InstantiateFixed(ExplosionPrefab, fixTrans.position);
				explosion.GetComponent<IPhysicsCollider>().Scale = circleCollider.Scale;
				AchievementHandler.RegisterSmokeExplosion(item.OwnerId);
				explosion.PlayerOwnerId = item.OwnerId;
				Updater.DestroyFix(base.gameObject);
			}
		}
	}

	public void Ignite()
	{
		timeSinceDetonated = Fix.Zero;
		circleCollider.enabled = false;
	}

	public void OnCollide(CollisionInformation collision)
	{
		Explosion component = collision.colliderPP.fixTrans.GetComponent<Explosion>();
		if (component != null && !component.IsDestroyed && component.igniteFlammables)
		{
			Ignite();
		}
	}
}
public class ForceArrow : MonoBehaviour
{
	public SpriteRenderer rectangle;

	public SpriteRenderer Triangle;

	public float forceMultiplier = 0.1f;

	private Vector3 triangleStartPos;

	private Vector3 RectangleStartPos;

	public float minLength = 1f;

	private Vector3 oScaleTriangle;

	private Vector3 oScaleRectangle;

	private void Awake()
	{
		triangleStartPos = Triangle.transform.position;
		RectangleStartPos = rectangle.transform.position;
		oScaleTriangle = Triangle.transform.localScale;
		oScaleRectangle = rectangle.transform.localScale;
	}

	public void SetForce(Vector2 force)
	{
		force *= forceMultiplier;
		float magnitude = force.magnitude;
		if (magnitude < minLength)
		{
			rectangle.enabled = false;
			Triangle.enabled = false;
		}
		else if (!rectangle.enabled)
		{
			rectangle.enabled = true;
			Triangle.enabled = true;
		}
		float x = 1f / base.transform.parent.localScale.x;
		float y = 1f / base.transform.parent.localScale.y;
		base.transform.localScale = new Vector3(x, y, 1f);
		Triangle.transform.localPosition = new Vector3(Triangle.transform.localPosition.x, magnitude - 0.2f, 0f);
		rectangle.transform.localScale = new Vector3(oScaleRectangle.x, magnitude, 1f);
		if (magnitude != 0f)
		{
			base.transform.rotation = Quaternion.FromToRotation(Vector3.up, force / magnitude);
		}
	}
}
