public class GameSession
{
	private static byte currentLevel;

	private static bool isInitialized;

	public static bool inMenus = true;

	private static bool[] playedLevelsBag;

	public static bool IsInitialized()
	{
		return isInitialized;
	}

	public static bool IsInAbilitySelect()
	{
		return currentLevel != 0;
	}

	public static void Init()
	{
		currentLevel = 0;
		isInitialized = true;
		int num = SceneManager.sceneCountInBuildSettings - 6;
		GameSessionHandler.GameIsPaused = false;
		playedLevelsBag = new bool[num];
	}

	public static byte CurrentLevel()
	{
		return currentLevel;
	}

	public static int NextLevel()
	{
		int num = (byte)(SceneManager.sceneCountInBuildSettings - 6);
		currentLevel = (byte)((currentLevel + 1) % num);
		return currentLevel;
	}

	public static void SetCurrentLevel(byte nextLevel)
	{
		playedLevelsBag[currentLevel] = true;
		currentLevel = nextLevel;
	}

	public static int RandomBagLevel()
	{
		playedLevelsBag[currentLevel] = true;
		int num = 0;
		for (int i = 0; i < playedLevelsBag.Length; i++)
		{
			if (!playedLevelsBag[i])
			{
				num++;
			}
		}
		if (num == 0)
		{
			for (int j = 0; j < playedLevelsBag.Length; j++)
			{
				playedLevelsBag[j] = false;
			}
		}
		byte b = (byte)UnityEngine.Random.Range(0, num);
		for (byte b2 = 0; b2 < playedLevelsBag.Length; b2++)
		{
			if (!playedLevelsBag[b2])
			{
				if (b == 0)
				{
					b = b2;
					break;
				}
				b--;
			}
		}
		currentLevel = b;
		return currentLevel;
	}
}
