public class GameSessionHandler : MonoUpdatable
{
	public TeamColors teamColors;

	public SlimeController PlayerPrefab;

	public InputUpdater InputUpdaterPrefab;

	private SlimeController[] slimeControllers;

	public Vec2[] teamSpawns = new Vec2[4];

	public Fix teammateSpawnSpacing = Fix.One;

	public List<GameObject> AbilityReadyIndicators;

	public GameObject playerSpawnsRoot;

	private StickyRoundedRectangle[] grounds;

	private Vec2[] targetPositions;

	private Vec2[] startPositions;

	public LevelType levelType;

	private Fix[] randomDelay;

	private Fix[] startRotations;

	public Fix levelAnimationRadius;

	public Fix MaxRandomDelay;

	public GameObject Level;

	public static Vec2[] playerSpawns_readonly;

	private static GameSessionHandler selfRef;

	private RoutineQueue playerInitRoutine = new RoutineQueue();

	private RoutineQueue levelAnimationRoutine = new RoutineQueue();

	public Fix timeBeforeGO = (Fix)2.5f;

	public Fix timeBeforeTwo = (Fix)1f;

	public string musicTrack;

	private GameObject winnerTriangle;

	private GameObject winnerTriangleCanvas;

	private Fix timeSinceGameOver;

	public Fix DelayBeforeNextLevelInput = (Fix)4L;

	public static bool GameIsPaused;

	public Fix TimeBeforeSuddenDeath = (Fix)120f;

	public static Fix SuddenDeathTimeStamp;

	private bool gameOver;

	private bool gameInProgress;

	private UnityEngine.AsyncOperation SceneLoad;

	public AlphaFade transitionFade;

	public AnimationCurveFixed AnimateInOut;

	public AnimationCurveFixed AnimateOut;

	public Fix LevelAnimationTime;

	private bool[] _playedArrivalSound;

	private Fix _t;

	public Fix blockAnimateInDelay_constantDelayFactor = Fix.Zero;

	public Fix blockAnimateOutDelay_constantDelayFactor = (Fix)0.3f;

	public Fix startProgressOfAnimateInGrounds = (Fix)0.5f;

	public static bool SuddenDeathInProgress { get; private set; }

	public static void LeaveGame(bool abandonLobbyEntirely, bool sendOthersBackToAbilitySelect = false)
	{
		SteamManager.instance?.networkClient?.SaveReplay();
		if (!abandonLobbyEntirely && SteamManager.LocalPlayerIsLobbyOwner)
		{
			SteamManager.instance.currentLobby.SetData("LFM", "0");
		}
		if (abandonLobbyEntirely)
		{
			SteamManager.instance.BroadcastCloseCurrentGame();
		}
		else if (sendOthersBackToAbilitySelect)
		{
			SteamManager.instance.BroadcastBacktoAbilityCommand_instant();
		}
		if (GameLobby.isOnlineGame && SteamManager.LocalPlayerIsLobbyOwner)
		{
			SteamManager.instance.currentLobby.SetJoinable(b: true);
		}
		SteamManager.instance.LeaveLobby();
		SteamManager.networkClientHandle?.ClearClients();
		SteamManager.networkClientHandle?.DeInit();
		AudioManager.Get().Play("return");
		if (SceneManager.GetActiveScene().buildIndex < 6)
		{
			return;
		}
		if (selfRef != null)
		{
			selfRef.gameOver = false;
			selfRef.transitionFade.gameObject.SetActive(value: true);
			CircleBG.TimeSpentInMenus = 0f;
			selfRef.winnerTriangle?.SetActive(value: false);
			selfRef.winnerTriangleCanvas?.SetActive(value: false);
			for (int i = 0; i < PlayerHandler.Get().PlayerList().Count; i++)
			{
				PlayerHandler.Get().PlayerList()[i].Position = Vec2.zero;
				PlayerHandler.Get().PlayerList()[i].Scale = Fix.One;
			}
			if (selfRef.SceneLoad != null)
			{
				selfRef.SceneLoad.allowSceneActivation = false;
			}
		}
		InputUpdater.PauseAllRumble();
		if (GameLobby.isOnlineGame)
		{
			PlayerHandler.Get().PlayerList().Clear();
		}
		Updater.PreLevelLoad();
		SceneManager.LoadScene("MainMenu", LoadSceneMode.Single);
		Updater.PostLevelLoad();
	}

	private void Awake()
	{
		Shader.SetGlobalFloat("_Timestop01", 1f);
		Constants.leveltype = levelType;
		Updater.RegisterUpdatable(this);
		SuddenDeathInProgress = false;
		grounds = Level.transform.root.GetComponentsInChildren<StickyRoundedRectangle>();
		startPositions = new Vec2[grounds.Length];
		targetPositions = new Vec2[grounds.Length];
		startRotations = new Fix[grounds.Length];
		randomDelay = new Fix[grounds.Length];
		playerSpawns_readonly = teamSpawns;
		for (int i = 0; i < grounds.Length; i++)
		{
			if (!(grounds[i] == null) && !grounds[i].IsDestroyed)
			{
				FixTransform component = grounds[i].GetComponent<FixTransform>();
				targetPositions[i] = component.serializedPosition;
				startRotations[i] = component.serializedRotation;
				startPositions[i] = targetPositions[i] + Vec2.NormalizedSafe(targetPositions[i] + Vec2.up * (Fix)20f) * levelAnimationRadius;
				component.position = startPositions[i];
				component.rotation = startRotations[i];
			}
		}
	}

	public override void Init()
	{
		selfRef = this;
		for (int i = 0; i < grounds.Length; i++)
		{
			if (!(grounds[i] == null) && !grounds[i].IsDestroyed)
			{
				grounds[i].GetComponent<BoplBody>().GetComponent<DPhysicsRoundedRect>().enabled = false;
				FixTransform component = grounds[i].GetComponent<FixTransform>();
				AnimateVelocity component2 = grounds[i].ThisGameObject().GetComponent<AnimateVelocity>();
				component2.Initialize(startPositions[i], startRotations[i]);
				component2.enabled = false;
				component.rotation = startRotations[i];
				component.position = startPositions[i];
				randomDelay[i] = Updater.RandomFix(Fix.Zero, Fix.One) * MaxRandomDelay;
			}
		}
		PlayerHandler.Get().ResetForNextStage();
		gameInProgress = false;
		for (int j = 0; j < PlayerHandler.Get().PlayerList().Count; j++)
		{
			PlayerHandler.Get().PlayerList()[j].isProtectedFromTimeStop = false;
		}
		GameTime.PlayerTimeScale = Fix.One;
		GameIsPaused = false;
		AchievementHandler.OnStartedAGame();
		StartSpawnPlayersRoutine();
		StartAnimateInLevelRoutine();
	}

	public static bool HasGameEnded()
	{
		if (selfRef == null)
		{
			return false;
		}
		return !selfRef.gameInProgress;
	}

	public static void EndGameImmediately()
	{
		if (selfRef != null && selfRef.gameInProgress)
		{
			selfRef?.DeclareGameUndecided(PlayerHandler.Get().PlayerList());
		}
	}

	private int[] DifferentTeams()
	{
		int num = PlayerHandler.Get().NumberOfTeams();
		List<Player> list = PlayerHandler.Get().PlayerList();
		int[] array = new int[num];
		for (int i = 0; i < array.Length; i++)
		{
			array[i] = -1;
		}
		int num2 = 0;
		for (int j = 0; j < list.Count; j++)
		{
			bool flag = false;
			for (int k = 0; k < array.Length; k++)
			{
				flag |= list[j].Team == array[k];
			}
			if (!flag)
			{
				array[num2] = list[j].Team;
				num2++;
			}
		}
		Array.Sort(array);
		return array;
	}

	private void SpawnPlayers()
	{
		gameInProgress = true;
		List<Player> list = PlayerHandler.Get().PlayerList();
		slimeControllers = new SlimeController[list.Count];
		int[] array = new int[4];
		int[] array2 = DifferentTeams();
		List<InputUpdater> list2 = new List<InputUpdater>();
		for (int i = 0; i < list.Count; i++)
		{
			int num = Array.IndexOf(array2, list[i].Team);
			list[i].playersAndClonesStillAlive = 1;
			Vec2 pos = ((array[num] == 0) ? teamSpawns[num] : ((array[list[i].Team] != 1) ? (teamSpawns[num] + new Vec2(teammateSpawnSpacing, -teammateSpawnSpacing * (Fix)0.5)) : (teamSpawns[num] - new Vec2(teammateSpawnSpacing, teammateSpawnSpacing * (Fix)0.5))));
			array[num]++;
			slimeControllers[i] = FixTransform.InstantiateFixed(PlayerPrefab, pos);
			slimeControllers[i].playerNumber = list[i].Id;
			slimeControllers[i].transform.SetParent(playerSpawnsRoot.transform);
			slimeControllers[i].GetPlayerSprite().sprite = null;
			slimeControllers[i].GetPlayerSprite().material = list[i].Color;
			List<AbilityMonoBehaviour> list3 = new List<AbilityMonoBehaviour>();
			list[i].CurrentAbilities = new List<GameObject>();
			bool flag = false;
			bool flag2 = true;
			for (int j = 0; j < list[i].Abilities.Count; j++)
			{
				if (list[i].Abilities[j].GetComponent<RandomAbility>() == null)
				{
					flag2 = false;
				}
			}
			for (int k = 0; k < list[i].Abilities.Count; k++)
			{
				RandomAbility component = list[i].Abilities[k].GetComponent<RandomAbility>();
				if (component != null)
				{
					NamedSprite randomAbilityPrefab = RandomAbility.GetRandomAbilityPrefab(component.abilityIcons, component.abilityIcons_demo);
					flag |= randomAbilityPrefab.isOffensiveAbility;
					if (flag2 && !flag && k == list[i].Abilities.Count - 1)
					{
						randomAbilityPrefab = RandomAbility.GetRandomAbilityPrefab(component.abilityIcons, component.abilityIcons_demo);
					}
					list[i].AbilityIcons[k] = randomAbilityPrefab.sprite;
					GameObject gameObject = FixTransform.InstantiateFixed(randomAbilityPrefab.associatedGameObject, Vec2.zero);
					gameObject.SetActive(value: false);
					list[i].CurrentAbilities.Add(gameObject);
					list3.Add(gameObject.GetComponent<AbilityMonoBehaviour>());
				}
				else
				{
					GameObject gameObject2 = FixTransform.InstantiateFixed(list[i].Abilities[k], Vec2.zero);
					gameObject2.SetActive(value: false);
					list[i].CurrentAbilities.Add(gameObject2);
					list3.Add(gameObject2.GetComponent<AbilityMonoBehaviour>());
				}
			}
			slimeControllers[i].abilities = list3;
			AbilityReadyIndicator[] array3 = new AbilityReadyIndicator[3];
			for (int l = 0; l < 3; l++)
			{
				array3[l] = UnityEngine.Object.Instantiate(AbilityReadyIndicators[l], playerSpawnsRoot.transform).GetComponent<AbilityReadyIndicator>();
				array3[l].Init();
				array3[l].SetColor(teamColors.teamColors[list[i].Team].fill);
				array3[l].GetComponent<FollowTransform>().Leader = slimeControllers[i].transform;
				array3[l].gameObject.SetActive(value: false);
				if (l < list[i].AbilityIcons.Count)
				{
					array3[l].SetSprite(list[i].AbilityIcons[l]);
				}
			}
			slimeControllers[i].AbilityReadyIndicators = array3;
			gameOver = false;
			if (list[i].IsLocalPlayer)
			{
				InputUpdater inputUpdater = UnityEngine.Object.Instantiate(InputUpdaterPrefab);
				PlayerInput component2 = inputUpdater.GetComponent<PlayerInput>();
				inputUpdater.Claim(list[i].Id);
				inputUpdater.Init(list[i].Id);
				component2.neverAutoSwitchControlSchemes = true;
				component2.ActivateInput();
				list2.Add(inputUpdater);
			}
		}
	}

	private void StartSpawnPlayersRoutine()
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int i = 0; i < list.Count; i++)
		{
			list[i].WonThisRound = false;
			list[i].KillsAtStartOfRound = list[i].Kills;
			list[i].CauseOfDeath = CauseOfDeath.NotDeadYet;
		}
		AudioManager.Get()?.Play("go");
		AudioManager.Get()?.OnMatchStarted();
		GameSession.inMenus = false;
		playerInitRoutine.Delay(timeBeforeTwo);
		playerInitRoutine.Function(SpawnPlayers);
		playerInitRoutine.Delay(timeBeforeGO);
		playerInitRoutine.Function(prepareWinnerTriangle);
	}

	private void prepareWinnerTriangle()
	{
		if (!winnerTriangle)
		{
			winnerTriangleCanvas = WinnerTriangleCanvas.instance.gameObject;
			winnerTriangle = WinnerTriangleCanvas.instance.charStatsList.transform.parent.gameObject;
			winnerTriangleCanvas.SetActive(value: false);
		}
	}

	public static void LoadNextLevelScene()
	{
		if (GameLobby.isPlayingAReplay)
		{
			Host.goToNextReplay = true;
			return;
		}
		Updater.PreLevelLoad();
		InputUpdater.PauseAllRumble();
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int i = 0; i < list.Count; i++)
		{
			list[i].Position = Vec2.zero;
			list[i].stillAliveThisRound = true;
			list[i].ignoreAllInputs = false;
			list[i].timesHitByBlinkgunThisRound = 0;
			list[i].InSparkShot = false;
			list[i].isInvisible = false;
			list[i].playersEatenCountThisRound = 0;
			list[i].RumbleState = Rumble.None;
			list[i].timeSpentInvisible = Fix.Zero;
			list[i].Scale = Fix.One;
			list[i].RespawnPositions.Clear();
		}
		if (GameLobby.isOnlineGame)
		{
			Updater.InitSeed(SteamManager.startParameters.seed);
		}
		BlackHole.OnNewLevel();
		Rope.ropeNumber = 0u;
		SceneManager.LoadScene(6 + GameSession.CurrentLevel(), LoadSceneMode.Single);
		if (GameLobby.isOnlineGame)
		{
			SteamManager.instance?.networkClient.ReInit();
		}
		Updater.PostLevelLoad();
	}

