	private void Update()
	{
		if (SceneLoad != null && transitionFade.IsDone && !SceneLoad.allowSceneActivation)
		{
			winnerTriangle?.SetActive(value: false);
			winnerTriangleCanvas?.SetActive(value: false);
			Updater.PreLevelLoad();
			SceneLoad.allowSceneActivation = true;
			Updater.PostLevelLoad();
			for (int i = 0; i < PlayerHandler.Get().PlayerList().Count; i++)
			{
				PlayerHandler.Get().PlayerList()[i].Position = Vec2.zero;
				PlayerHandler.Get().PlayerList()[i].Scale = Fix.One;
			}
		}
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		levelAnimationRoutine.Update(SimDeltaTime);
		playerInitRoutine.Update(SimDeltaTime);
		if (gameOver)
		{
			timeSinceGameOver += SimDeltaTime;
		}
		else
		{
			timeSinceGameOver = Fix.Zero;
		}
		List<Player> list = PlayerHandler.Get().PlayerList();
		if (!SuddenDeathInProgress && gameInProgress && Updater.SimTimeSinceLevelLoaded > TimeBeforeSuddenDeath)
		{
			ActivateSuddenDeath(activate: true);
		}
		int num = 0;
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].IsAlive)
			{
				num++;
			}
		}
		if (!gameInProgress)
		{
			return;
		}
		int num2 = PlayerHandler.Get().TeamsLeft();
		if (PlayerHandler.Get().NumberOfPlayers() == 1 && num == 0)
		{
			gameInProgress = false;
			WinGame(PlayerHandler.Get().PlayerList()[0].Team);
		}
		else if (PlayerHandler.Get().NumberOfPlayers() > 1 && num2 == 1)
		{
			gameInProgress = false;
			for (int j = 0; j < list.Count; j++)
			{
				if (list[j].IsAlive)
				{
					WinGame(list[j].Team);
					break;
				}
			}
		}
		else if (PlayerHandler.Get().NumberOfPlayers() > 1 && num2 == 0)
		{
			gameInProgress = false;
			DeclareGameUndecided(list);
		}
	}

	private void DeclareGameUndecided(List<Player> playerList)
	{
		AudioManager.Get()?.OnMatchEnded(isDraw: true);
		gameInProgress = false;
		AchievementHandler.OnRoundEnded();
		ActivateSuddenDeath(activate: false);
		long num = 0L;
		for (int i = 0; i < playerList.Count; i++)
		{
			if (num < playerList[i].TimestampWhenKilled)
			{
				num = playerList[i].TimestampWhenKilled;
			}
		}
		for (int j = 0; j < playerList.Count; j++)
		{
			if (num == playerList[j].TimestampWhenKilled)
			{
				playerList[j].IsMostRecentWinner = true;
			}
			else
			{
				playerList[j].IsMostRecentWinner = false;
			}
		}
		for (int k = 0; k < playerList.Count; k++)
		{
			if (!playerList[k].IsMostRecentWinner)
			{
				continue;
			}
			for (int l = 0; l < playerList.Count; l++)
			{
				if (playerList[k].Team == playerList[l].Team)
				{
					playerList[l].IsMostRecentWinner = true;
				}
			}
		}
		bool flag = true;
		for (int m = 0; m < playerList.Count; m++)
		{
			if (!playerList[m].IsMostRecentWinner)
			{
				flag = false;
			}
		}
		if (flag && PlayerHandler.Get().NumberOfPlayers() == 4)
		{
			AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.HaveAGameEndInA4personDraw);
		}
		for (int n = 0; n < playerList.Count; n++)
		{
			if (playerList[n].IsMostRecentWinner)
			{
				playerList[n].WinAGame();
			}
		}
		AchievementHandler.CheckAchievementsOnWinRound();
		prepareNextlevel();
		if (!winnerTriangle)
		{
			winnerTriangleCanvas = WinnerTriangleCanvas.instance.gameObject;
			winnerTriangle = WinnerTriangleCanvas.instance.charStatsList.transform.parent.gameObject;
		}
		playerInitRoutine.Delay(DelayBeforeNextLevelInput - (Fix)2L);
		playerInitRoutine.Function(ActivateWinnerTriangle);
	}

	private void ActivateSuddenDeath(bool activate)
	{
		SuddenDeathInProgress = activate;
		if (activate)
		{
			AudioManager.Get()?.suddenDeathMusicShift();
			SuddenDeathTimeStamp = Updater.SimTimeSinceLevelLoaded;
		}
	}

	private void prepareNextlevel()
	{
		gameInProgress = false;
		gameOver = true;
		if (!GameLobby.isOnlineGame || SteamManager.LocalPlayerIsLobbyOwner)
		{
			GameSession.RandomBagLevel();
		}
	}

	private void ActivateWinnerTriangle()
	{
		for (int i = 0; i < PlayerHandler.Get().PlayerList().Count; i++)
		{
			PlayerHandler.Get().PlayerList()[i].isProtectedFromTimeStop = false;
		}
		GameTime.PlayerTimeScale = Fix.Zero;
		GameIsPaused = true;
		levelAnimationRoutine.Function(AnimateOutLevel);
		winnerTriangle.SetActive(value: false);
		winnerTriangleCanvas.SetActive(value: false);
		winnerTriangle.SetActive(value: true);
		winnerTriangleCanvas.SetActive(value: true);
	}

	public void DisableWinnerTriangleIfActive()
	{
		winnerTriangle.SetActive(value: false);
		winnerTriangleCanvas.SetActive(value: false);
	}

	private void WinGame(int team)
	{
		AudioManager.Get()?.OnMatchEnded(isDraw: false);
		ActivateSuddenDeath(activate: false);
		for (int i = 0; i < PlayerHandler.Get().PlayerList().Count; i++)
		{
			PlayerHandler.Get().PlayerList()[i].IsMostRecentWinner = false;
		}
		for (int j = 0; j < PlayerHandler.Get().PlayerList().Count; j++)
		{
			Player player = PlayerHandler.Get().PlayerList()[j];
			if (player.Team == team)
			{
				player.WinAGame();
			}
		}
		AchievementHandler.CheckAchievementsOnWinRound();
		AchievementHandler.OnRoundEnded();
		prepareNextlevel();
		if (!winnerTriangle)
		{
			winnerTriangleCanvas = WinnerTriangleCanvas.instance.gameObject;
			winnerTriangle = WinnerTriangleCanvas.instance.charStatsList.transform.parent.gameObject;
		}
		playerInitRoutine.Delay(DelayBeforeNextLevelInput - (Fix)2L);
		playerInitRoutine.Function(ActivateWinnerTriangle);
	}

	private Fix animateIn(Fix start, Fix end, Fix value)
	{
		Fix fix = AnimateInOut.Evaluate(value);
		return end * fix + start * (Fix.One - fix);
	}

	private Fix animateOut(Fix start, Fix end, Fix value)
	{
		Fix fix = AnimateOut.Evaluate(value);
		return end * fix + start * (Fix.One - fix);
	}

	private bool AnimateInLoop(Fix dTime)
	{
		bool flag = true;
		_t += dTime / LevelAnimationTime;
		for (int i = 0; i < grounds.Length; i++)
		{
			if (grounds[i] == null || grounds[i].IsDestroyed)
			{
				_playedArrivalSound[i] = true;
				continue;
			}
			FixTransform component = grounds[i].GetComponent<FixTransform>();
			if (_t < Fix.One + randomDelay[i])
			{
				flag = false;
			}
			if (_t > blockAnimateInDelay_constantDelayFactor + randomDelay[i] && !_playedArrivalSound[i])
			{
				AudioManager.Get()?.PlayPrefixWithInterrupts("easeInBlock");
				_playedArrivalSound[i] = true;
			}
			component.position = new Vec2
			{
				x = animateIn(startPositions[i].x, targetPositions[i].x, _t - randomDelay[i]),
				y = animateIn(startPositions[i].y, targetPositions[i].y, _t - randomDelay[i])
			};
		}
		return !flag;
	}

	private bool AnimateOutLoop(Fix dTime)
	{
		bool flag = true;
		_t += dTime / LevelAnimationTime;
		for (int i = 0; i < grounds.Length; i++)
		{
			if (!(grounds[i] == null) && !grounds[i].IsDestroyed)
			{
				FixTransform component = grounds[i].GetComponent<FixTransform>();
				if (_t < Fix.One + randomDelay[i])
				{
					flag = false;
				}
				if (_t > blockAnimateOutDelay_constantDelayFactor + randomDelay[i] && !_playedArrivalSound[i])
				{
					AudioManager.Get()?.PlayPrefixWithInterrupts("easeInBlock");
					_playedArrivalSound[i] = true;
				}
				component.position = new Vec2
				{
					x = animateOut(targetPositions[i].x, startPositions[i].x, _t - randomDelay[i]),
					y = animateOut(targetPositions[i].y, startPositions[i].y, _t - randomDelay[i])
				};
			}
		}
		return !flag;
	}

	private void StartAnimateInLevelRoutine()
	{
		levelAnimationRoutine.Delay((Fix)0.1f);
		_playedArrivalSound = new bool[grounds.Length];
		_t = startProgressOfAnimateInGrounds;
		levelAnimationRoutine.WhileLoop(AnimateInLoop);
		levelAnimationRoutine.Function(delegate
		{
			for (int i = 0; i < grounds.Length; i++)
			{
				if (!(grounds[i] == null) && !grounds[i].IsDestroyed)
				{
					AnimateVelocity component = grounds[i].ThisGameObject().GetComponent<AnimateVelocity>();
					bool homeIsMovable = component.HomeIsMovable;
					component.HomeIsMovable = true;
					component.HomePosition = targetPositions[i];
					component.HomeIsMovable = homeIsMovable;
					component.enabled = true;
					grounds[i].GetComponent<DPhysicsRoundedRect>().enabled = true;
					grounds[i].UpdateBounds();
				}
			}
		});
	}

	private void AnimateOutLevel()
	{
		UnityEngine.Object.FindObjectOfType<PlayerAverageCamera>().enabled = false;
		for (int i = 0; i < grounds.Length; i++)
		{
			if (!(grounds[i] == null) && !grounds[i].IsDestroyed)
			{
				AnimateVelocity component = grounds[i].ThisGameObject().GetComponent<AnimateVelocity>();
				if (component != null)
				{
					component.enabled = false;
				}
			}
		}
		for (int j = 0; j < startPositions.Length; j++)
		{
			if (!(grounds[j] == null) && !grounds[j].IsDestroyed)
			{
				targetPositions[j] = grounds[j].GetComponent<FixTransform>().position;
			}
		}
		for (int k = 0; k < _playedArrivalSound.Length; k++)
		{
			_playedArrivalSound[k] = false;
		}
		_t = startProgressOfAnimateInGrounds;
		levelAnimationRoutine.WhileLoop(AnimateOutLoop);
	}

	private void OnDrawGizmos()
	{
		Vec2 vec = new Vec2(teammateSpawnSpacing, teammateSpawnSpacing * (Fix)0.5);
		DrawCross(teamSpawns[0] - vec, UnityEngine.Color.blue);
		DrawCross(teamSpawns[1] - vec, UnityEngine.Color.red);
		DrawCross(teamSpawns[2] - vec, UnityEngine.Color.green);
		DrawCross(teamSpawns[3] - vec, UnityEngine.Color.magenta);
		vec.y = -vec.y;
		DrawCross(teamSpawns[0] + vec, UnityEngine.Color.blue);
		DrawCross(teamSpawns[1] + vec, UnityEngine.Color.red);
		DrawCross(teamSpawns[2] + vec, UnityEngine.Color.green);
		DrawCross(teamSpawns[3] + vec, UnityEngine.Color.magenta);
		DrawCross(teamSpawns[0], UnityEngine.Color.blue);
		DrawCross(teamSpawns[1], UnityEngine.Color.red);
		DrawCross(teamSpawns[2], UnityEngine.Color.green);
		DrawCross(teamSpawns[3], UnityEngine.Color.magenta);
	}

	private void DrawCross(Vec2 fpos, UnityEngine.Color col)
	{
		float num = 1f;
		Vector2 vector = (Vector2)fpos;
		Vector2 vector2 = new Vector2(vector.x - num, vector.y);
		UnityEngine.Debug.DrawLine(end: new Vector2(vector.x + num, vector.y), start: vector2, color: col);
		Vector2 vector3 = new Vector2(vector.x, vector.y - num);
		UnityEngine.Debug.DrawLine(end: new Vector2(vector.x, vector.y + num), start: vector3, color: col);
	}
}
public class GameTime
{
	public static readonly Fix FixedTimeStep = Fix.One / (Fix)60L;

	public static Fix PlayerTimeScale { get; set; } = (Fix)1f;

	public static bool IsTimeStopped()
	{
		return PlayerTimeScale < (Fix)0.01f;
	}

	public static bool IsTimeStoppedFor(int playerId)
	{
		if (playerId == Constants.ENVIRONMENTAL_PLAYER_ID)
		{
			return false;
		}
		if (IsTimeStopped())
		{
			return !PlayerHandler.Get().GetPlayer(playerId).isProtectedFromTimeStop;
		}
		return false;
	}

	public static float DeltaTime(int id)
	{
		if (PlayerHandler.Get().GetPlayer(id) == null)
		{
			return Time.deltaTime;
		}
		if (!PlayerHandler.Get().GetPlayer(id).isProtectedFromTimeStop)
		{
			return Time.deltaTime * (float)PlayerTimeScale;
		}
		return Time.deltaTime;
	}

	public static Fix FixedDeltaTime(int id, Fix simDeltaTime)
	{
		if (PlayerHandler.Get().GetPlayer(id) == null)
		{
			return simDeltaTime;
		}
		if (!PlayerHandler.Get().GetPlayer(id).isProtectedFromTimeStop)
		{
			return simDeltaTime * PlayerTimeScale;
		}
		return simDeltaTime;
	}

	public static Fix FixedDeltaTime(IPlayerIdHolder idHolder, Fix simDeltaTime)
	{
		if (idHolder == null)
		{
			return simDeltaTime;
		}
		return FixedDeltaTime(idHolder.GetPlayerId(), simDeltaTime);
	}

	public static float DeltaTime(IPlayerIdHolder idHolder)
	{
		if (idHolder == null)
		{
			return Time.deltaTime;
		}
		return DeltaTime(idHolder.GetPlayerId());
	}
}
