[RequireComponent(typeof(Item))]
public class Grenade : MonoUpdatable
{
	[NonSerialized]
	public BoplBody body;

	private Item item;

	public bool timedExplosion;

	public Fix detonationTime;

	private IGrenadeDetonation detonation;

	[HideInInspector]
	public ThrowItem2 thrower;

	public bool hasBeenThrown = true;

	private Fix hurtOwnerDelay = -Fix.One;

	[HideInInspector]
	public Fix selfDestructDelay = -Fix.One;

	public bool DetonatesOnOwner { get; set; }

	public void Initialize(ThrowItem2 mu)
	{
		thrower = mu;
	}

	public override void Init()
	{
		if (timedExplosion)
		{
			selfDestructDelay = detonationTime;
		}
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		body = GetComponent<BoplBody>();
		item = GetComponent<Item>();
		detonation = GetComponent<IGrenadeDetonation>();
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (!hasBeenThrown && (thrower == null || !thrower.gameObject.activeSelf))
		{
			hasBeenThrown = true;
			hurtOwnerDelay = Fix.One;
			GetComponent<DPhysicsCircle>().ManualInit();
		}
		if (hasBeenThrown && hurtOwnerDelay > 0L)
		{
			hurtOwnerDelay -= simDeltaTime * GameTime.PlayerTimeScale;
			if (hurtOwnerDelay <= 0L)
			{
				DetonatesOnOwner = true;
			}
		}
		if (selfDestructDelay > 0L)
		{
			selfDestructDelay -= simDeltaTime * GameTime.PlayerTimeScale;
			if (selfDestructDelay <= 0L)
			{
				Detonate();
			}
		}
	}

	public void DelayedEnableHurtOwner(Fix secondsDelay)
	{
		hurtOwnerDelay = secondsDelay;
	}

	private void OnDrawGizmos()
	{
		if (DetonatesOnOwner)
		{
			DPhysicsCircle component = GetComponent<DPhysicsCircle>();
			if ((bool)component)
			{
				Gizmos.DrawWireSphere(base.transform.position, (float)component.radius * 5f);
			}
		}
	}

	public void Detonate()
	{
		detonation.Detonate();
	}
}
public class GrenadeExplode : MonoUpdatable, IGrenadeDetonation, ICollisionCallback
{
	public Explosion explosion;

	private Item item;

	private Grenade grenade;

	private IPhysicsCollider hitbox;

	private FixTransform fixTrans;

	[HideInInspector]
	public int hasBeenGustedBy = -1;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
		item = GetComponent<Item>();
		grenade = GetComponent<Grenade>();
		hitbox = GetComponent<IPhysicsCollider>();
		hitbox.RegisterCollisionCallback(this);
	}

	public void Detonate()
	{
		Explosion obj = FixTransform.InstantiateFixed(explosion, fixTrans.position);
		obj.GetComponent<IPhysicsCollider>().Scale = hitbox.Scale;
		obj.PlayerOwnerId = item.OwnerId;
		Updater.DestroyFix(base.gameObject);
	}

	public void SetThrower(ThrowItem2 thrower)
	{
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (collision.layer == LayerMask.NameToLayer("Player"))
		{
			IPlayerIdHolder component = collision.colliderPP.fixTrans.GetComponent<IPlayerIdHolder>();
			if (component == null)
			{
				return;
			}
			if (hasBeenGustedBy != -1 && item.OwnerId != component.GetPlayerId())
			{
				if (GameLobby.isOnlineGame)
				{
					Player player = PlayerHandler.Get().GetPlayer(hasBeenGustedBy);
					if (player != null && player.IsLocalPlayer)
					{
						AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.GustAGrenadeIntoAPlayer);
					}
				}
				else
				{
					AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.GustAGrenadeIntoAPlayer);
				}
			}
			if ((item.OwnerId != component.GetPlayerId() || grenade.DetonatesOnOwner) && (!grenade.body.IsBeingHeld() || grenade.body.magnetGunHolder.hurtbox.HierarchyNumber != collision.colliderPP.hierarchyNumber))
			{
				Detonate();
			}
		}
		else if (collision.layer == LayerMask.NameToLayer("Projectile"))
		{
			Projectile component2 = collision.colliderPP.fixTrans.GetComponent<Projectile>();
			if (component2 != null && component2.IgnitesExplosives)
			{
				Detonate();
			}
		}
		else if (collision.layer == LayerMask.NameToLayer("Explosion"))
		{
			Detonate();
		}
	}

	public override void Init()
	{
	}

	public override bool IsEnabled()
	{
		return false;
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}
}
