public class InstantAbility : AbilityMonoBehaviour, IPlayerIdHolder
{
	public GameObject EffectOnEnter;

	public UnityEvent funcOnEnter;

	public string AudioOnCast;

	[NonSerialized]
	public PlayerInfo playerInfo;

	private FixTransform fixTrans;

	[SerializeField]
	private Fix cooldown = Fix.One;

	public bool isHookshot;

	public bool cooldownStoppedDuringTimeStop;

	[NonSerialized]
	public bool ignoreNextCooldown;

	private SlimeController slimeController;

	private HookshotInstant hookshotInstant;

	public bool isInvisibilty;

	public override bool IsRope => isHookshot;

	public override bool CooldownStoppedDuringTimeStop => cooldownStoppedDuringTimeStop;

	public override bool IgnoreNextCooldown => ignoreNextCooldown;

	public override PlayerCollision GetPlayerCollision()
	{
		return null;
	}

	public override SlimeController GetSlimeController()
	{
		return slimeController;
	}

	public override void UpdateCooldowns(PlayerBody playerBody)
	{
		if (IsRope)
		{
			hookshotInstant?.UpdateCooldowns(playerBody);
		}
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		ignoreNextCooldown = false;
		if (isHookshot)
		{
			hookshotInstant = GetComponent<HookshotInstant>();
		}
		fixTrans = GetComponent<FixTransform>();
	}

	public override void EnterAbility(PlayerInfo playerInfo, Action<AbilityExitInfo> onExitAbility)
	{
		this.playerInfo = playerInfo;
		base.gameObject.SetActive(value: true);
		slimeController = playerInfo.slimeController;
		fixTrans.position = playerInfo.position;
		funcOnEnter?.Invoke();
		if (EffectOnEnter != null)
		{
			FixTransform.InstantiateFixed(EffectOnEnter, playerInfo.position);
		}
		if (!string.IsNullOrEmpty(AudioOnCast))
		{
			AudioManager.Get().Play(AudioOnCast);
		}
		base.gameObject.SetActive(value: false);
	}

	public override void ExitAbility(AbilityExitInfo info)
	{
		base.gameObject.SetActive(value: false);
	}

	public override Fix GetCooldown()
	{
		return cooldown;
	}

	public void SetCoolDown(Fix newCooldown)
	{
		cooldown = newCooldown;
	}

	public Material GetPlayerMaterial()
	{
		return playerInfo.playerMaterial;
	}

	public int GetPlayerId()
	{
		return playerInfo.playerId;
	}

	public override bool IsInstant()
	{
		return true;
	}

	public void SetPlayerId(int id)
	{
		playerInfo.playerId = id;
	}

	public override bool IsCastable(Player player)
	{
		if (isInvisibilty && player != null && player.isInvisible)
		{
			return false;
		}
		return true;
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}
}
