public class ManualPlayerController : MonoBehaviour
{
	public int PlayerId = 1;

	public bool jump;

	public bool Ability1;

	public bool Ability2;

	public bool Ability3;

	[Range(-1f, 1f)]
	public float xInput;

	[Range(-1f, 1f)]
	public float yInput;

	public bool Start;

	public bool Select;

	public bool w;

	public bool a;

	public bool s;

	public bool d;

	public bool RESET_EVERY_FRAME;

	public bool runBackAndForth;

	public float oscillationSpeed = 2f;

	private Player player;

	private void Awake()
	{
		if (player == null)
		{
			player = PlayerHandler.Get().GetPlayer(PlayerId);
		}
	}

	private void Update()
	{
		if (player == null)
		{
			player = PlayerHandler.Get().GetPlayer(PlayerId);
		}
		if (player != null)
		{
			Vec2 v = new Vec2((Fix)xInput, (Fix)yInput);
			if (runBackAndForth)
			{
				if (Time.timeSinceLevelLoad % oscillationSpeed < oscillationSpeed / 2f)
				{
					v.x = Fix.One;
				}
				else
				{
					v.x = -Fix.One;
				}
			}
			player.ForceSetInputProfile(Start, Select, jump, Ability1, Ability2, Ability3, Player.InputProfile.JoyStickAngleByteFromVector(v), w, a, s, d);
		}
		if (RESET_EVERY_FRAME)
		{
			ResetProperties();
		}
	}

	private void ResetProperties()
	{
		jump = false;
		Ability1 = false;
		Ability2 = false;
		Ability3 = false;
		xInput = 0f;
		yInput = 0f;
		Select = false;
		Start = false;
	}
}
public enum State
{
	Anticipation,
	Jump,
	Vibrate,
	Dash
}
[RequireComponent(typeof(Ability))]
public class MeteorSmash : MonoUpdatable, IAbilityComponent, IPlayerIdHolder
{
	public Fix timeBeforeDrop = (Fix)1L;

	public Fix jumpSpeed;

	public Fix holdSpeed;

	public Fix maxHoldTime = (Fix)2L;

	public Fix minHoldTime = (Fix)0.5f;

	public AnimationCurveFixed speedCurve;

	public AnimationData animData;

	public GameObject SmokePrefab;

	public GameObject SmearFramePrefab;

	public Shockwave ShockwavePrefab;

	private PlayerInfo playerInfo;

	private Player player;

	private State state;

	private Ability ability;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private PlayerPhysics physics;

	private SpriteAnimator animator;

	private FixTransform fixTrans;

	private DPhysicsBox hitbox;

	private Fix trueMinHoldTime;

	private Fix timePassed = (Fix)0L;

	private bool hasEnteredAbility;

	private Vec2 prevOffset;

	public Fix vibrationStr = (Fix)1L;

	private int updatesPassedInDash;

	public int FixedUpdatesInDash = 5;

	public Fix smearScaling = (Fix)0.5f;

	public Fix groundForce = (Fix)30f;

	public Fix spinSpeed = (Fix)100L;

	public AnimationCurveFixed spinCurve;

	public Fix playerPushForce = (Fix)30L;

	private StickyRoundedRectangle hitGround;

	private Fix HitGroundLocalPosition;

	public LayerMask raycastMask;

	private List<RaycastInformation> raycastHits = new List<RaycastInformation>();

	public Fix shakeStr = (Fix)30L;

	public Fix shakeDuration = Fix.One;

	public Fix rotationStr = Fix.One;

	private RaycastHit2D[] rayCastHits = new RaycastHit2D[1];

	private ParticleSystem smokeParticle;

	public override void Init()
	{
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		spriteRen = GetComponent<SpriteRenderer>();
		physics = GetComponent<PlayerPhysics>();
		animator = GetComponent<SpriteAnimator>();
		fixTrans = GetComponent<FixTransform>();
		hitbox = GetComponent<DPhysicsBox>();
		smokeParticle = UnityEngine.Object.Instantiate(SmokePrefab, base.transform.position, Quaternion.FromToRotation(Vector3.down, Vector3.up)).GetComponentInChildren<ParticleSystem>();
	}

	private void OnDestroy()
	{
		if (smokeParticle != null)
		{
			UnityEngine.Object.Destroy(smokeParticle.transform.parent.gameObject);
		}
	}

	public void OnEnterAbility()
	{
		ability.KillPlayersOnContact = false;
		hasEnteredAbility = true;
		hitGround = null;
		spriteRen.enabled = true;
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		physics.SyncPhysicsTo(playerInfo);
		hitbox.UpdatePhysicsPositions();
		spriteRen.material = playerInfo.playerMaterial;
		body.rotation = (Fix)0L;
		base.transform.rotation = Quaternion.identity;
		timePassed = (Fix)0L;
		state = State.Anticipation;
		prevOffset = Vec2.zero;
		body.selfImposedVelocity = Vec2.zero;
		body.externalVelocity = Vec2.zero;
		if (playerInfo.isGrounded)
		{
			animator.beginAnimThenDoAction(animData.GetAnimation("gEnter"), Jump);
		}
		else
		{
			Jump();
		}
	}

	public void Jump()
	{
		if (!playerInfo.isGrounded)
		{
			trueMinHoldTime = minHoldTime;
			Vibrate_fromAirStart();
			return;
		}
		trueMinHoldTime = Fix.Zero;
		AudioManager.Get().Play("meteor_jump");
		bool num = physics.IsGrounded();
		physics.UnGround(nullRotation: true, playSoundEffect: false);
		if (num)
		{
			body.position += Vec2.up * physics.extraJumpTeleportMultiplier;
		}
		else
		{
			body.position += Vec2.up * (Fix)1.75;
		}
		base.transform.position = (Vector3)body.position;
		if (physics.VelocityBasedRaycasts(attachToGroundIfHit: true, Updater.standardFixedDeltaTime))
		{
			body.selfImposedVelocity = Vec2.zero;
			ExitAbilityGrounded();
			return;
		}
		fixTrans.position += Vec2.up * physics.extraJumpTeleportMultiplier;
		body.selfImposedVelocity = Vec2.up * speedCurve.Evaluate(timePassed) * jumpSpeed;
		animator.beginAnimThenDoAction(animData.GetAnimation("air"), Vibrate);
		state = State.Jump;
	}

	public void Vibrate()
	{
		timePassed = (Fix)0L;
		animator.beginAnimation(animData.GetAnimation("hold"));
		state = State.Vibrate;
		player.Rumble(Rumble.BuildTension);
	}

	public void Vibrate_fromAirStart()
	{
		timePassed = (Fix)0L;
		animator.beginAnimThenPlayAnim(animData.GetAnimation("aStartHold"), animData.GetAnimation("hold"));
		state = State.Vibrate;
		player.Rumble(Rumble.BuildTension);
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		if (player.RumbleState == Rumble.BuildTension)
		{
			player.RumbleState = Rumble.None;
		}
		ability.KillPlayersOnContact = false;
		hasEnteredAbility = false;
		ability.ExitAbility(exitInfo);
	}

	private void ExitAbilityGrounded()
	{
		ExitAbility(new AbilityExitInfo
		{
			groundedSpeed = (Fix)0L,
			isFacingRight = true,
			selfImposedVelocity = body.selfImposedVelocity,
			externalVelocity = body.externalVelocity,
			isGrounded = true,
			justlanded = true,
			currentlyAttachedGround = physics.getAttachedGround(),
			position = body.position,
			radius = physics.radius,
			groundedLocalPosition = physics.LocalPlatformPos
		});
	}

	private void ExitAbilityNoGround()
	{
		AbilityExitInfo exitInfo = default(AbilityExitInfo);
		ability.KillPlayersOnContact = false;
		exitInfo.groundedSpeed = (Fix)0L;
		exitInfo.isFacingRight = true;
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.isGrounded = false;
		exitInfo.justlanded = false;
		exitInfo.currentlyAttachedGround = null;
		exitInfo.position = body.position;
		exitInfo.radius = physics.radius;
		ExitAbility(exitInfo);
	}

	private void Update()
	{
		if (state == State.Vibrate && !GameSessionHandler.GameIsPaused)
		{
			AudioManager.Get().PlayOrContinueLoop("meteor_vibrate");
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		timePassed += GameTime.FixedDeltaTime(player.Id, simDeltaTime);
		switch (state)
		{
		case State.Anticipation:
			physics.Move(Vec2.zero, simDeltaTime);
			break;
		case State.Jump:
			body.selfImposedVelocity = Vec2.up * speedCurve.Evaluate(timePassed) * jumpSpeed;
			break;
		case State.Vibrate:
		{
			if (timePassed > maxHoldTime || (timePassed > trueMinHoldTime && !player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012)))
			{
				Dash();
				animator.beginAnimation(animData.GetAnimation("release"));
				return;
			}
			Vec2 vec = Vec2.NormalizedSafe(Updater.RandomInsideUnitCircle()) * vibrationStr * Fix.Max(timePassed, (Fix)0.5f);
			fixTrans.position -= prevOffset;
			fixTrans.position += vec;
			prevOffset = vec;
			body.selfImposedVelocity = Vec2.up * holdSpeed;
			body.externalVelocity *= (Fix)0.8;
			break;
		}
		case State.Dash:
			updatesPassedInDash++;
			if (updatesPassedInDash > FixedUpdatesInDash)
			{
				if (hitGround != null)
				{
					fixTrans.position = hitGround.PositionFromLocalPlayerPos(HitGroundLocalPosition, physics.radius);
					physics.AttachToGround(hitGround, fixTrans.position);
					ExitAbilityGrounded();
				}
				else
				{
					fixTrans.position = new Vec2(fixTrans.position.x, SceneBounds.WaterHeight - (Fix)20L);
				}
			}
			return;
		}
		if (physics.VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime))
		{
			ExitAbilityGrounded();
		}
	}

	private void SpawnSmearEffect(Vec2 from, Vec2 to)
	{
		GameObject gameObject = FixTransform.InstantiateFixed(SmearFramePrefab, to);
		SpriteRenderer component = gameObject.GetComponent<SpriteRenderer>();
		DPhysicsBox component2 = gameObject.GetComponent<DPhysicsBox>();
		FixTransform component3 = gameObject.GetComponent<FixTransform>();
		component2.ManualInit();
		ability.GetSlimeController().GetPlayerCollision().IgnoreCollider(component2, PlayerCollision.IgnoreColliderInd.meteor);
		ability.GetPlayerCollision().IgnoreCollider(component2, PlayerCollision.IgnoreColliderInd.meteor);
		Vec2 vec = to - from;
		Vec2 extents = component2.CalcExtents();
		Fix y = extents.y;
		extents.y = Vec2.Magnitude(vec) * (Fix)0.5f;
		extents.x *= fixTrans.Scale;
		component2.SetExtents(extents);
		Vec2 offset = component3.offset;
		offset.y *= extents.y / y;
		component3.offset = offset;
		float y2 = ((Vector2)vec).magnitude / (float)y;
		gameObject.transform.localScale = new Vector3((float)fixTrans.Scale, y2, 1f);
		component.material.SetVector("_Scale", new Vector4(1f, gameObject.transform.localScale.y * (float)smearScaling, 1f));
		component.material.SetColor("_ShadowColor", spriteRen.material.GetColor("_ShadowColor"));
		component.material.SetColor("_MainColor", spriteRen.material.GetColor("_MainColor"));
		component.material.SetColor("_ReflectionColour", spriteRen.material.GetColor("_ReflectionColour"));
		gameObject.GetComponent<Explosion>().PlayerOwnerId = playerInfo.playerId;
	}

	private void Dash()
	{
		ability.KillPlayersOnContact = true;
		Fix fix = Fix.Min(timePassed / maxHoldTime, Fix.One);
		state = State.Dash;
		updatesPassedInDash = 0;
		body.selfImposedVelocity = Vec2.zero;
		body.externalVelocity = Vec2.zero;
		spriteRen.enabled = false;
		raycastHits.Clear();
		bool num = DetPhysics.Get().RaycastAll(fixTrans.position + Vec2.down * physics.radius, Vec2.down, (Fix)1000000L, raycastMask, raycastHits, hitbox.GetPhysicsParent().instanceId);
		Vec2 position = body.position;
		if (num)
		{
			for (int i = 0; i < raycastHits.Count; i++)
			{
				Vec2 nearPos = raycastHits[i].nearPos;
				if (raycastHits[i].layer == LayerMask.NameToLayer("wall"))
				{
					StickyRoundedRectangle component = raycastHits[i].pp.fixTrans.GetComponent<StickyRoundedRectangle>();
					Vec2 closestPoint = component.GetClosestPoint(nearPos);
					smokeParticle.transform.parent.transform.position = (Vector3)closestPoint;
					smokeParticle.Play();
					body.position = nearPos;
					HitGroundLocalPosition = component.LocalPlayerPosFromPos(closestPoint, physics.radius);
					Fix fix2 = (fix + Fix.One) * (Fix)0.5f;
					if (!(closestPoint.x < component.GetGroundBody().position.x))
					{
						_ = -Fix.One;
					}
					else
					{
						_ = Fix.One;
					}
					component.GetGroundBody().AddForceAtPosition(Vec2.down * groundForce * fix2, nearPos);
					StickyRoundedRectangle component2 = component.GetComponent<StickyRoundedRectangle>();
					float num2 = (1f + (float)fix * 0.4f) * Mathf.Min((float)fixTrans.Scale, 1.5f);
					smokeParticle.transform.localScale = new Vector3(num2, num2, 1f);
					smokeParticle.transform.GetChild(0).localScale = new Vector3(num2, num2, 1f);
					if (timePassed > timeBeforeDrop)
					{
						component2.DropAllAttachedPlayers(playerInfo.playerId, playerPushForce * timePassed);
						component.GetComponent<ShakablePlatform>()?.AddShake(shakeDuration, shakeStr, 100, null, spinCurve);
					}
					else
					{
						component.GetComponent<ShakablePlatform>()?.AddShake(shakeDuration, shakeStr / (Fix)3L, 0, null, spinCurve);
					}
					Shockwave shockwave = FixTransform.InstantiateFixed(ShockwavePrefab, nearPos);
					shockwave.SetPlayerId(playerInfo.playerId);
					shockwave.AddObjectToIgnore(component.gameObject.GetInstanceID());
					shockwave.platformForce *= fix2;
					shockwave.defaultForce *= fix2;
					SpawnSmearEffect(position, nearPos);
					body.position = component.PositionFromLocalPlayerPos(HitGroundLocalPosition, physics.radius);
					physics.AttachToGround(component, fixTrans.position);
					AudioManager.Get().Play("meteor_dash");
					ExitAbilityGrounded();
					break;
				}
				if (raycastHits[i].layer == LayerMask.NameToLayer("Water"))
				{
					body.position = new Vec2(body.position.x, SceneBounds.WaterHeight - (Fix)20f);
					base.transform.position = (Vector3)body.position;
					SpawnSmearEffect(position, nearPos);
					AudioManager.Get().Play("dash");
					ExitAbilityNoGround();
					break;
				}
				body.position = nearPos;
				Box physicsBox = hitbox.physicsBox;
				physicsBox.center = nearPos;
				CollisionInformation collision = new CollisionInformation
				{
					collider = physicsBox,
					colliderImpactVelocity = Vec2.down * (Fix)50L,
					colliderPP = hitbox.pp,
					contactPoint = nearPos,
					layer = base.gameObject.layer,
					normal = Vec2.up,
					penetration = (Fix)0.1f,
					pp = raycastHits[i].pp
				};
				raycastHits[i].pp.collisionCallback.OnCollide(collision);
				Circle circle = new Circle
				{
					center = raycastHits[i].nearPos,
					layer = raycastHits[i].layer,
					radius = Fix.One
				};
				collision = new CollisionInformation
				{
					collider = circle,
					colliderImpactVelocity = Vec2.zero,
					colliderPP = raycastHits[i].pp,
					contactPoint = nearPos,
					layer = raycastHits[i].layer,
					normal = Vec2.up,
					penetration = (Fix)0.1f,
					pp = hitbox.pp
				};
				hitbox.OnCollide(collision);
				if (!hasEnteredAbility)
				{
					AudioManager.Get().Play("dash");
					SpawnSmearEffect(position, nearPos);
					break;
				}
			}
		}
		else
		{
			body.position = new Vec2(body.position.x, SceneBounds.WaterHeight - (Fix)10L);
			SpawnSmearEffect(position, new Vec2(body.position.x, SceneBounds.WaterHeight));
			body.selfImposedVelocity = Vec2.zero;
			body.externalVelocity = Vec2.zero;
			AudioManager.Get().Play("dash");
			ExitAbilityNoGround();
		}
	}

	public void SetPlayerId(int id)
	{
	}

	public int GetPlayerId()
	{
		return playerInfo.playerId;
	}

	public Material GetPlayerMaterial()
	{
		return playerInfo.playerMaterial;
	}
}
