public class Missile : MonoUpdatable, ICollisionCallback
{
	public Fix minimumForwardsSpeed = (Fix)5L;

	public Fix accel = (Fix)3L;

	public AnimationData animData;

	public ParticleSystem particleSmokePrefab;

	public Vector2 particleSmokeOffset;

	private ParticleSystem particleSmoke;

	private BoplBody body;

	private SpriteAnimator spriteAnimator;

	private FixTransform fixTrans;

	private bool isSteeringRight;

	private IPhysicsCollider hitbox;

	private Item item;

	public PlayAnimation flameAnimator;

	private int instabilityTicks;

	public Fix instabilityAccel = (Fix)10L;

	public float flameSizeIncrease = 1.4f;

	private bool instable;

	private float spawnTime;

	public float startEngineTime = 1f;

	public Explosion onHitExplosionPrefab;

	public string soundEffectOnCol;

	public override void Init()
	{
		spawnTime = Time.time;
		AudioManager.Get().Play("startEngine");
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		hitbox = GetComponent<IPhysicsCollider>();
		hitbox.RegisterCollisionCallback(this);
		body = GetComponent<BoplBody>();
		item = GetComponent<Item>();
		fixTrans = GetComponent<FixTransform>();
		spriteAnimator = GetComponent<SpriteAnimator>();
		particleSmoke = UnityEngine.Object.Instantiate(particleSmokePrefab);
		UpdateParticlePosition();
	}

	private void OnDestroy()
	{
		if (particleSmoke != null && this != null)
		{
			ParticleSystem.MainModule main = particleSmoke.main;
			main.stopAction = ParticleSystemStopAction.Destroy;
			particleSmoke.Play();
			particleSmoke.Stop();
		}
		AudioManager.Get().Play("endEngine");
	}

	public void SteerAnimation(bool right)
	{
		if (isSteeringRight != right)
		{
			isSteeringRight = right;
			if (right)
			{
				int num = spriteAnimator.getNumberOfPassedSprites() - 1;
				int num2 = animData.GetAnimation("rocketR").Length;
				spriteAnimator.beginAnimation(animData.GetAnimation("rocketR"));
				spriteAnimator.SkipToSpriteOfIndex(num2 - num - 1);
			}
			else
			{
				int num3 = spriteAnimator.getNumberOfPassedSprites() - 1;
				int num4 = animData.GetAnimation("rocketL").Length;
				spriteAnimator.beginAnimation(animData.GetAnimation("rocketL"));
				spriteAnimator.SkipToSpriteOfIndex(num4 - num3 - 1);
			}
		}
	}

	public void Stabilize()
	{
		instabilityTicks = 0;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		instabilityTicks++;
		if (instabilityTicks >= 3)
		{
			if (!instable)
			{
				flameAnimator.transform.localScale *= flameSizeIncrease;
				flameAnimator.Init();
				instable = true;
			}
			if (!GameTime.IsTimeStopped() && !body.IsBeingHeld())
			{
				body.AddForce(fixTrans.up * instabilityAccel);
			}
			ParticleSystem.EmissionModule emission = particleSmoke.emission;
			emission.rateOverTime = 150f;
		}
		else if (Vec2.Dot(fixTrans.up, body.velocity) < minimumForwardsSpeed && !GameTime.IsTimeStopped() && !body.IsBeingHeld())
		{
			body.AddForce(fixTrans.up * accel);
		}
		if (GameTime.IsTimeStopped() && particleSmoke != null)
		{
			if (!particleSmoke.isPaused)
			{
				particleSmoke.Pause();
			}
		}
		else if (particleSmoke.isPaused)
		{
			particleSmoke.Play();
		}
	}

	private void OnDisable()
	{
		if (particleSmoke != null && this != null)
		{
			particleSmoke.Stop();
		}
	}

	private void OnEnable()
	{
		if (!GameTime.IsTimeStopped() && particleSmoke != null)
		{
			particleSmoke?.Play();
		}
		if (particleSmoke == null)
		{
			particleSmoke = UnityEngine.Object.Instantiate(particleSmokePrefab);
			UpdateParticlePosition();
		}
	}

	private void UpdateParticlePosition()
	{
		if (!(particleSmoke == null))
		{
			particleSmoke.transform.up = base.transform.up;
			particleSmoke.transform.localScale = Vector3.one * (float)fixTrans.Scale;
			particleSmoke.gameObject.transform.position = base.transform.position + base.transform.rotation * particleSmokeOffset * (float)fixTrans.Scale;
		}
	}

	private void Update()
	{
		if (Time.time > startEngineTime + spawnTime && !GameTime.IsTimeStopped())
		{
			AudioManager.Get().PlayOrContinueLoop("loopEngine");
		}
		UpdateParticlePosition();
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (!(this == null) && collision.layer != LayerMask.NameToLayer("RigidBodyAffector") && collision.layer != LayerMask.NameToLayer("Rope") && !body.IsBeingHeld())
		{
			FixTransform.InstantiateFixed(onHitExplosionPrefab, body.position).GetComponent<IPhysicsCollider>().Scale = fixTrans.Scale;
			if (!string.IsNullOrEmpty(soundEffectOnCol))
			{
				AudioManager.Get().Play(soundEffectOnCol);
			}
			Updater.DestroyFix(base.gameObject);
		}
	}
}
public class Client
{
	private int playerId;

	public ConcurrentQueue<TimedAck> receivedAckQueue;

	public ConcurrentQueue<InputPacketUpdate> receivedPackets;

	public ConcurrentQueue<ChecksumPacket> checksumPacketQueue;

	public bool HasReceivedSyncAck;

	public bool HasSentSyncAck;

	public float inputReceivedTimeStamp;

	public double ping;

	public double HighestPing;

	private Connection connection;

	public SteamConnection steamConnection;

	private byte[] ackBuffer = new byte[6];

	private byte[] checksumBuffer = new byte[14];

	private byte[] uintConversionArray = new byte[4];

	public uint AcksReceived;

	public uint InputPacketsReceived;

	public Queue<InputPacket> inputHistory;

	public uint InputUpdatesReceived;

	private uint inputHistoryHeadSeqNum;

	public float latestTimePassedReceived;

	public bool newTimePassed;

	public uint AckPacketsReceived;

	public double lagEstimateMillis;

	public double lagstandardDeviation;

	private const double rollingAverageWeight = 0.05000000074505806;

	private List<InputPacketUpdate> OutOfOrderUpdates = new List<InputPacketUpdate>(32);

	private List<ChecksumPacket> receivedCheckSumPackets = new List<ChecksumPacket>(256);

	public List<ChecksumPacket> localChecksums = new List<ChecksumPacket>(256);

	public Dictionary<uint, string> serializedStates = new Dictionary<uint, string>();

	public int PlayerId => playerId;

	public SteamId Id { get; }

	public Client(Client oldClient)
	{
		playerId = oldClient.playerId;
		steamConnection = oldClient.steamConnection;
		connection = oldClient.steamConnection.Connection;
		Id = oldClient.Id;
		receivedPackets = new ConcurrentQueue<InputPacketUpdate>();
		receivedAckQueue = new ConcurrentQueue<TimedAck>();
		checksumPacketQueue = new ConcurrentQueue<ChecksumPacket>();
		inputHistory = new Queue<InputPacket>(128);
		HasReceivedSyncAck = false;
		HasSentSyncAck = false;
		AcksReceived = 0u;
		inputReceivedTimeStamp = 0f;
		ping = oldClient.ping;
		HighestPing = oldClient.HighestPing;
		lagstandardDeviation = oldClient.lagstandardDeviation;
		lagEstimateMillis = oldClient.lagEstimateMillis;
	}

	public Client(int playerId, SteamConnection connection)
	{
		this.playerId = playerId;
		steamConnection = connection;
		this.connection = connection.Connection;
		Id = connection.id;
		receivedPackets = new ConcurrentQueue<InputPacketUpdate>();
		receivedAckQueue = new ConcurrentQueue<TimedAck>();
		checksumPacketQueue = new ConcurrentQueue<ChecksumPacket>();
		inputHistory = new Queue<InputPacket>(128);
		HasReceivedSyncAck = false;
		HasSentSyncAck = false;
		AcksReceived = 0u;
		inputReceivedTimeStamp = 0f;
		ping = -1.0;
		HighestPing = -1.0;
	}

	public void SendPacket(byte[] data, int ExtraInputDelayMillis, int ExtraRandomInputDelay, SendType sendType)
	{
		_ = "Sending packet to " + Id.ToString() + ":" + connection.ConnectionName + " playerId: " + playerId;
		if (ExtraInputDelayMillis > 0 || ExtraRandomInputDelay > 0)
		{
			int randomBonus = (int)(UnityEngine.Random.value * (float)ExtraRandomInputDelay);
			byte[] dataCopy = new byte[data.Length];
			for (int i = 0; i < data.Length; i++)
			{
				dataCopy[i] = data[i];
			}
			Task.Run(async delegate
			{
				await Task.Delay(ExtraInputDelayMillis + randomBonus);
				connection.SendMessage(dataCopy, sendType);
			});
		}
		else
		{
			connection.SendMessage(data, sendType);
		}
	}

	private void SendAck(uint seqNum, byte localPlayerId)
	{
		NetworkTools.EncodeAckForNetwork(ref ackBuffer, new Ack
		{
			seqNumber = seqNum,
			playerId = localPlayerId,
			level = Host.level
		});
		connection.SendMessage(ackBuffer, SendType.NoNagle);
	}

	public void SendChecksum(uint seqNum, byte level, ulong checksum, byte localPlayerId)
	{
		NetworkTools.EncodeCheckSum(ref checksumBuffer, seqNum, level, checksum, localPlayerId);
		connection.SendMessage(checksumBuffer, SendType.Unreliable);
	}

	public void ProcessNetworkPackets(float unscaledCurrentTime, TimedInputPacket[] inputHistory, bool adaptiveInputDelayBuffer, byte localPlayerId)
	{
		bool flag = false;
		while (!receivedPackets.IsEmpty)
		{
			if (receivedPackets.TryDequeue(out var result))
			{
				inputReceivedTimeStamp = unscaledCurrentTime;
				if (result.seqNumber != 0)
				{
					InputUpdatesReceived++;
				}
				if (result.seqNumber == 0)
				{
					if (!flag)
					{
						SendAck(0u, localPlayerId);
						flag = true;
						HasSentSyncAck = true;
					}
				}
				else if (result.seqNumber > InputPacketsReceived)
				{
					bool num = UpdateInputHistory(result);
					latestTimePassedReceived = result.timePassed;
					newTimePassed = true;
					if (num)
					{
						OutOfOrderUpdates.Add(result);
						continue;
					}
					InputPacketsReceived = result.seqNumber;
					FillHistoryWithOutOfOrderUpdates();
				}
			}
			else
			{
				UnityEngine.Debug.LogError("couldnt dequeue a network packet for some reason");
			}
		}
		while (!checksumPacketQueue.IsEmpty)
		{
			if (checksumPacketQueue.TryDequeue(out var result2) && result2.level == Host.level)
			{
				receivedCheckSumPackets.Add(result2);
			}
		}
		while (!receivedAckQueue.IsEmpty)
		{
			if (receivedAckQueue.TryDequeue(out var result3))
			{
				if (result3.level != Host.level)
				{
					continue;
				}
				if (result3.seqNumber != 0)
				{
					AckPacketsReceived++;
				}
				if (result3.seqNumber == 0)
				{
					HasReceivedSyncAck = true;
					if (AcksReceived == 0)
					{
						AcksReceived = 1u;
					}
				}
				else
				{
					if (result3.seqNumber <= AcksReceived)
					{
						continue;
					}
					AcksReceived = result3.seqNumber;
					for (int i = 0; i < inputHistory.Length; i++)
					{
						if (result3.seqNumber == inputHistory[i].input.seqNumber)
						{
							double num2 = TicksToMillis(result3.TimeOfArrivalTicks - inputHistory[i].TimeSentTicks);
							double val = 1024.0;
							double val2 = 256.0;
							double val3 = lagstandardDeviation * 8.0;
							val3 = Math.Min(val3, val);
							val3 = Math.Max(val3, val2);
							if (num2 > val3)
							{
								num2 = lagEstimateMillis * 2.0 + Math.Max(8.0 * lagstandardDeviation, 1.0);
							}
							ping = num2;
							double num3 = num2 * 0.5;
							if (lagEstimateMillis == 0.0)
							{
								lagEstimateMillis = num3;
								break;
							}
							lagEstimateMillis = 0.9499999992549419 * lagEstimateMillis + 0.05000000074505806 * num3;
							lagstandardDeviation = 0.9499999992549419 * lagstandardDeviation + 0.05000000074505806 * Math.Abs(num3 - lagEstimateMillis);
							break;
						}
					}
				}
			}
			else
			{
				UnityEngine.Debug.LogError("couldnt dequeue an ack for some reason");
			}
		}
	}

	private static double TicksToMillis(long ticks)
	{
		return (double)ticks / 10000.0;
	}

	private void FillHistoryWithOutOfOrderUpdates()
	{
		for (int i = 0; i < OutOfOrderUpdates.Count; i++)
		{
			if (!UpdateInputHistory(OutOfOrderUpdates[i]))
			{
				OutOfOrderUpdates.RemoveAt(i);
				FillHistoryWithOutOfOrderUpdates();
				break;
			}
		}
	}

	public void CheckForDesyncs()
	{
		for (int num = localChecksums.Count - 1; num >= 0; num--)
		{
			for (int num2 = receivedCheckSumPackets.Count - 1; num2 >= 0; num2--)
			{
				if (localChecksums[num].seqNumber == receivedCheckSumPackets[num2].seqNumber)
				{
					if (localChecksums[num].checkSum == receivedCheckSumPackets[num2].checkSum)
					{
						if (serializedStates.ContainsKey(localChecksums[num].seqNumber))
						{
							serializedStates.Remove(localChecksums[num].seqNumber);
						}
						localChecksums.RemoveAt(num);
						receivedCheckSumPackets.RemoveAt(num2);
						break;
					}
					UnityEngine.Debug.Log(serializedStates[localChecksums[num].seqNumber]);
					throw new Exception("desync detected on frame " + localChecksums[num].seqNumber + ", checkSums: p1= " + localChecksums[num].checkSum + ", p" + playerId + "= " + receivedCheckSumPackets[num2].checkSum);
				}
			}
		}
	}

	private bool UpdateInputHistory(InputPacketUpdate update)
	{
		uint num = inputHistoryHeadSeqNum;
		int num2 = (int)(update.seqNumber - num);
		if (num2 > 32)
		{
			return true;
		}
		for (int num3 = num2 - 1; num3 >= 0; num3--)
		{
			uint num4 = (uint)(1 << num3);
			InputPacket item = new InputPacket
			{
				jump = ((update.jump & num4) != 0),
				ab1 = ((update.ab1 & num4) != 0),
				ab2 = ((update.ab2 & num4) != 0),
				ab3 = ((update.ab3 & num4) != 0),
				select = ((update.select & num4) != 0),
				start = ((update.start & num4) != 0),
				w = ((update.w & num4) != 0),
				a = ((update.a & num4) != 0),
				s = ((update.s & num4) != 0),
				d = ((update.d & num4) != 0),
				joystickAngle = update.joystickAngle[num3],
				targetDelayBufferSize = update.targetDelayBufferSize,
				seqNumber = num + 1
			};
			num++;
			inputHistory.Enqueue(item);
			inputHistoryHeadSeqNum = item.seqNumber;
		}
		return false;
	}
}
