	}

	private static ReplayFile[] FindReplayFiles(FileInfo[] files)
	{
		ReplayFile[] array = new ReplayFile[files.Length];
		for (int i = 0; i < array.Length; i++)
		{
			int length = files[i].Name.LastIndexOf('.');
			string s = files[i].Name.Substring(0, length);
			int result = 0;
			if (int.TryParse(s, out result))
			{
				array[i].info = files[i];
				array[i].number = result;
				continue;
			}
			throw new Exception("replay of strange name in replays folder \"" + files[i].Name + "\" all replays need to be named a NUMBER.rep. ");
		}
		Array.Sort(array, delegate(ReplayFile x, ReplayFile y)
		{
			if (x.number < y.number)
			{
				return -1;
			}
			return (x.number > y.number) ? 1 : 0;
		});
		return array;
	}

	public static void PrepareReplaySaving()
	{
		try
		{
			replaysSaved = 0;
			FileInfo[] files = Directory.CreateDirectory(Application.persistentDataPath + "/replays").GetFiles();
			ReplayFile[] array = FindReplayFiles(files);
			if (array.Length != 0)
			{
				replaysSaved = array[^1].number;
			}
			else
			{
				replaysSaved = 0;
			}
			if (files.Length > 1000)
			{
				int num = files.Length - 1000;
				for (int i = 0; i < num; i++)
				{
					array[i].info?.Delete();
				}
			}
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("Failed to initialize replays. turning off replay function " + ex.Message);
			recordReplay = false;
		}
	}

	public void RecordReplayFrame(InputPacketQuad quadToSave)
	{
		inputRecording.Add(quadToSave);
	}

	public void SaveReplay()
	{
		Updater.gameHasStopped = true;
		if (recordReplay && inputRecording.Count != 0 && !(SteamManager.instance == null))
		{
			string text = Application.persistentDataPath + "/replays/";
			byte[] bytes = NetworkTools.SerializeReplay_compressed(inputRecording, EncodedStartRequest);
			replaysSaved++;
			string text2 = text + replaysSaved + ".rep";
			File.WriteAllBytes(text + replaysSaved + ".rep", bytes);
			UnityEngine.Debug.Log("saved replay " + text2);
		}
		inputRecording.Clear();
	}

	private void Start()
	{
		if (PlayReplayInEditor)
		{
			Settings.Get().NumberOfAbilities = SteamManager.startParameters.nrOfAbilites;
		}
	}

	private void OnLevelWasLoaded(int level)
	{
		if (PlayReplayInEditor && level != 0 && level != 1)
		{
			if (replayLevelsLoaded > 0)
			{
				Application.Quit();
				return;
			}
			MonoBehaviour.print("loaded level " + level);
			replayLevelsLoaded++;
		}
	}

	private void Awake()
	{
		if (!PlayReplayInEditor)
		{
			string[] commandLineArgs = Environment.GetCommandLineArgs();
			bool flag = false;
			for (int i = 0; i < commandLineArgs.Length; i++)
			{
				if (!commandLineArgs[i].EndsWith(".rep"))
				{
					continue;
				}
				if (File.Exists(commandLineArgs[i]))
				{
					flag = true;
					replayPath = commandLineArgs[i];
					UnityEngine.Debug.Log("found a valid .rep argument: " + commandLineArgs[i]);
					if (flag)
					{
						SceneManager.LoadScene("Replay");
					}
					return;
				}
				UnityEngine.Debug.Log("found .rep argument, but can't find the file: " + commandLineArgs[i]);
			}
		}
		if (PlayReplayInEditor)
		{
			recordReplay = false;
			string text = replayPath;
			if (text != null)
			{
				replay = NetworkTools.ReadCompressedReplay(File.ReadAllBytes(text), out var startRequest);
				SteamManager.startParameters = startRequest;
				GameLobby.isPlayingAReplay = true;
				clients = new List<Client>();
				for (int j = 0; j < startRequest.nrOfPlayers - 1; j++)
				{
					clients.Add(new Client(1, new SteamConnection()));
				}
			}
		}
		if (!isLoaded)
		{
			UnityEngine.Object.DontDestroyOnLoad(this);
			UnityEngine.Object.DontDestroyOnLoad(DebugTextRenderer);
			isLoaded = true;
		}
	}

	public static InputPacket CurrentInputAsPacket(int hostPlayerId, uint inputPacketsSent, TimedInputPacket[] inputHistory)
	{
		Player player = PlayerHandler.Get().GetPlayer(hostPlayerId);
		Player.InputProfile rawInputProfile = player.GetRawInputProfile();
		InputPacket result = new InputPacket
		{
			seqNumber = inputPacketsSent,
			joystickAngle = rawInputProfile.joystickAngleByte,
			jump = rawInputProfile.jumpButton_IS_DOWN,
			ab1 = rawInputProfile.firstAbilityButton_IS_DOWN,
			ab2 = rawInputProfile.secondAbilityButton_IS_DOWN,
			ab3 = rawInputProfile.thirdAbilityButton_IS_DOWN,
			select = rawInputProfile.selectButton_IS_DOWN,
			start = rawInputProfile.startButton_IS_DOWN,
			w = rawInputProfile.w_IS_DOWN,
			a = rawInputProfile.a_IS_DOWN,
			s = rawInputProfile.s_IS_DOWN,
			d = rawInputProfile.d_IS_DOWN
		};
		int currentDelayBufferSize = CurrentDelayBufferSize;
		if (player.InPlatformTransform && player.UsesKeyboardAndMouse && currentDelayBufferSize != 0)
		{
			Vec2 vec = player.CustomAimAbilityPosition;
			for (int num = currentDelayBufferSize; num >= 0; num--)
			{
				Vec2 aimVector = Player.InputProfile.inputVectorFromByte(inputHistory[num].input.joystickAngle);
				vec = PlatformTransform.EstimateCursorPosition(vec, aimVector);
			}
			Vector2 vector = (Vector2)vec;
			Vector2 vector2 = player.mouseWorldPos - vector;
			vector2 = ((!(vector2.SqrMagnitude() < 0.2f)) ? vector2.normalized : Vector2.zero);
			result.joystickAngle = Player.InputProfile.JoyStickAngleByteFromVector((Vec2)vector2);
		}
		return result;
	}

	private byte TargetPlayoutDelay(uint seqNum)
	{
		double num = -1.0;
		for (int i = 0; i < clients.Count; i++)
		{
			if (clients[i].ping < 0.0)
			{
				return 0;
			}
			double num2 = clients[i].lagEstimateMillis + clients[i].lagstandardDeviation * StandardDeviationMultiple;
			if (num2 > num)
			{
				num = num2;
			}
		}
		byte b = (byte)Math.Min(Math.Max(1.0, extraDelayBuffer + num / 16.667), 32.0);
		if ((byte)delayBufferSize > b)
		{
			b = (byte)Math.Min(Math.Max(1.0, delayBufferDecreaseResistence + extraDelayBuffer + num / 16.667), 32.0);
		}
		return b;
	}

	public void ReadPacket(byte[] bytes, int size)
	{
		int num = 0;
		if (bytes != null && size >= 1)
		{
			byte b = bytes[0];
			for (int i = 0; i < clients.Count; i++)
			{
				if ((byte)clients[i].PlayerId == b)
				{
					num = i;
					break;
				}
			}
			if (num < 0 || num >= clients.Count)
			{
				return;
			}
		}
		switch (size)
		{
		case 6:
		{
			Ack ack = NetworkTools.ReadAck(bytes, ref uintConversionArray);
			long ticks = DateTime.UtcNow.Ticks;
			clients[num].receivedAckQueue.Enqueue(new TimedAck
			{
				seqNumber = ack.seqNumber,
				TimeOfArrivalTicks = ticks,
				level = ack.level
			});
			break;
		}
		case 67:
		case 83:
			if (NetworkTools.ReadInputPacketUpdateLevel(bytes) == level)
			{
				uint num2 = NetworkTools.ReadInputPacketUpdateSeqNum(bytes, ref uintConversionArray);
				if (num2 % PingMeasurmentsRate == 1 && num2 > clients[num].InputPacketsReceived)
				{
					NetworkTools.EncodeAckForNetwork(ref dataBufferAck, new Ack
					{
						seqNumber = num2,
						playerId = (byte)localPlayerId,
						level = level
					});
					clients[num].SendPacket(dataBufferAck, ExtraInputDelayMillis, ExtraInputDelayVariation, SendType.NoNagle);
				}
				bool usesKeyboardAndMouse = size == 83;
				InputPacketUpdate item2 = NetworkTools.ReadInputPacketUpdate(bytes, size, ref uintConversionArray);
				if (PlayerHandler.Get() != null)
				{
					PlayerHandler.Get().GetPlayer(clients[num].PlayerId).UsesKeyboardAndMouse = usesKeyboardAndMouse;
				}
				clients[num].receivedPackets.Enqueue(item2);
			}
			break;
		case 14:
		{
			ChecksumPacket item = NetworkTools.ReadChecksum(ref bytes, ref ulongConversionArray, ref uintConversionArray);
			clients[num].checksumPacketQueue.Enqueue(item);
			break;
		}
		}
	}

	public void DeInit()
	{
		hasBeenInitialized = false;
	}

	public void ClearClients()
	{
		clients.Clear();
	}

	public void ReInit()
	{
		List<Client> list = new List<Client>();
		for (int i = 0; i < clients.Count; i++)
		{
			list.Add(new Client(clients[i]));
		}
		Init(list, localPlayerId, GameSession.CurrentLevel(), SteamManager.startParameters.frameBufferSize, SteamManager.instance.checkForDesyncs);
	}

	public void Init(List<Client> clients, int localPlayerId, byte currentLevel, int sizeOfDelayBuffer = 4, bool checkForDesyncs = false)
	{
		level = currentLevel;
		hasBeenInitialized = true;
		Application.targetFrameRate = 60;
		QualitySettings.vSyncCount = 0;
		InputBuffer.Clear();
		inputHistory = new TimedInputPacket[32];
		sentPacketHistory.Clear();
		lastRebroadcastTime = Time.unscaledTime;
		previousInputQuad = default(InputPacketQuad);
		simulationTicksPassed = 0u;
		timePassed = 0f;
		timeSpentHalted = 0f;
		UpdatesPlacedInDelayBuffer = 0;
		allClientsSynced = false;
		inputPacketsSent = 0u;
		Updater.ReInit();
		Environment.GetCommandLineArgs();
		_ = clients.Count;
		this.clients = clients;
		this.localPlayerId = localPlayerId;
		delayBufferSize = sizeOfDelayBuffer;
		broadcastChecksums = checkForDesyncs;
		if (recordReplay)
		{
			inputRecording.Clear();
		}
		if (!PlayReplayInEditor)
		{
			for (int i = 0; i < clients.Count; i++)
			{
				clients[i].inputReceivedTimeStamp = Time.unscaledTime;
			}
			targetDelayBufferSize = delayBufferSize;
			dataBufferWASD = new byte[83];
			dataBufferNoWASD = new byte[67];
			dataBufferAck = new byte[6];
		}
	}

	private void UpdateLocalInputHistory()
	{
		InputPacket inputPacket = CurrentInputAsPacket(localPlayerId, inputPacketsSent, inputHistory);
		for (int num = inputHistory.Length - 1; num > 0; num--)
		{
			inputHistory[num] = inputHistory[num - 1];
		}
		if (AdaptiveInputDelayBuffer)
		{
			if (inputPacketsSent % 32 == 0)
			{
				inputPacket.targetDelayBufferSize = TargetPlayoutDelay(inputPacketsSent);
			}
			else
			{
				inputPacket.targetDelayBufferSize = inputHistory[0].input.targetDelayBufferSize;
			}
		}
		inputHistory[0] = new TimedInputPacket
		{
			input = inputPacket,
			TimeSentTicks = DateTime.UtcNow.Ticks
		};
		sentPacketHistory.Enqueue(inputPacket);
	}

	private void BroadcastInputPacket()
	{
		bool usesKeyboardAndMouse = PlayerHandler.Get().GetPlayer(localPlayerId).UsesKeyboardAndMouse;
		if (allClientsSynced)
		{
			inputPacketsSent++;
			UpdateLocalInputHistory();
		}
		byte[] data = (usesKeyboardAndMouse ? dataBufferWASD : dataBufferNoWASD);
		NetworkTools.EncodeInputForNetwork(ref data, level, inputHistory, usesKeyboardAndMouse, (byte)localPlayerId, timePassed);
		for (int i = 0; i < clients.Count; i++)
		{
			if (packetLoss == 0f || UnityEngine.Random.value > packetLoss)
			{
				clients[i].SendPacket(data, ExtraInputDelayMillis, ExtraInputDelayVariation, SendType.NoNagle);
			}
		}
		lastSentPacketData = data;
	}

	private void SendChecksumToPlayer1(uint seqNum)
	{
		if (localPlayerId == 1)
		{
			string value = Updater.SerializeState();
			ulong checkSum = Updater.ComputeChecksum();
			for (int i = 0; i < clients.Count; i++)
			{
				clients[i].serializedStates.Add(seqNum, value);
				clients[i].localChecksums.Add(new ChecksumPacket
				{
					seqNumber = seqNum,
					checkSum = checkSum,
					level = level
				});
			}
			return;
		}
		ulong checksum = Updater.ComputeChecksum();
		for (int j = 0; j < clients.Count; j++)
		{
			if (clients[j].PlayerId == 1)
			{
				clients[j].SendChecksum(seqNum, level, checksum, (byte)localPlayerId);
				break;
			}
		}
	}

	private void RebroadcastLastInputPacket()
	{
		for (int i = 0; i < clients.Count; i++)
		{
			if (UnityEngine.Random.value > packetLoss)
			{
				clients[i].SendPacket(lastSentPacketData, ExtraInputDelayMillis, ExtraInputDelayVariation, SendType.NoNagle);
			}
		}
	}

	private void ProcessNetworkPackets()
	{
		if (clients.Count == 0)
		{
			MonoBehaviour.print("There are no clients");
		}
		for (int i = 0; i < clients.Count; i++)
		{
			if (!clients[i].steamConnection.Connected && !clients[i].steamConnection.Connecting)
			{
				MonoBehaviour.print(" a client is not connected nor connecting");
			}
		}
		bool flag = true;
		for (int j = 0; j < clients.Count; j++)
		{
			clients[j].ProcessNetworkPackets(Time.unscaledTime, inputHistory, AdaptiveInputDelayBuffer, (byte)localPlayerId);
			flag &= clients[j].HasReceivedSyncAck;
			flag &= clients[j].HasSentSyncAck;
		}
		if (flag && !allClientsSynced)
		{
			allClientsSynced = true;
			for (int k = 0; k < delayBufferSize; k++)
			{
				InputBuffer.Enqueue(default(InputPacketQuad));
			}
		}
		if (!allClientsSynced)
		{
			return;
		}
		uint num = uint.MaxValue;
		for (int l = 0; l < clients.Count; l++)
		{
			if (clients[l].InputPacketsReceived < num)
			{
				num = clients[l].InputPacketsReceived;
			}
		}
		if (inputPacketsSent < num)
		{
			num = inputPacketsSent;
		}
		int num2 = (int)num - UpdatesPlacedInDelayBuffer;
		for (int m = 0; m < num2; m++)
		{
			InputPacketQuad item = default(InputPacketQuad);
			for (int n = 0; n < clients.Count; n++)
			{
				InputPacket inputPacket = clients[n].inputHistory.Dequeue();
				switch (clients[n].PlayerId)
				{
				case 1:
					item.p1 = inputPacket;
					break;
				case 2:
					item.p2 = inputPacket;
					break;
				case 3:
					item.p3 = inputPacket;
					break;
				case 4:
					item.p4 = inputPacket;
					break;
				}
			}
			InputPacket inputPacket2 = sentPacketHistory.Dequeue();
			switch (localPlayerId)
			{
			case 1:
				item.p1 = inputPacket2;
				break;
			case 2:
				item.p2 = inputPacket2;
				break;
			case 3:
				item.p3 = inputPacket2;
				break;
			case 4:
				item.p4 = inputPacket2;
				break;
			}
			InputBuffer.Enqueue(item);
			UpdatesPlacedInDelayBuffer++;
		}
		try
		{
			if (localPlayerId == 1)
			{
				for (int num3 = 0; num3 < clients.Count; num3++)
				{
					clients[num3].CheckForDesyncs();
				}
			}
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("Desync occured, ending game " + ex);
			GameSessionHandler.EndGameImmediately();
		}
	}

	public float EstimateTimePassedDelta()
	{
		float num = 0f;
		for (int i = 0; i < timePassedDeltas.array.Length; i++)
		{
			num += timePassedDeltas.array[i];
		}
		return num / (float)timePassedDeltas.Length;
	}

	private void UpdateTimePassed(float delta)
	{
		timePassed += delta;
		for (int i = 0; i < timePassedDeltas.array.Length; i++)
		{
			timePassedDeltas.array[i] -= delta;
		}
	}

	private void GoToNextReplay()
	{
		replayLevelsLoaded = 0;
		FileInfo[] files = Directory.CreateDirectory(Application.persistentDataPath + "/replays").GetFiles();
		Array.Sort(files, (FileInfo x, FileInfo y) => x.CreationTime.CompareTo(y.CreationTime));
		int num = -1;
		string text = replayPath.Replace("/", "\\");
		for (int num2 = 0; num2 < files.Length; num2++)
		{
			if (files[num2].FullName == text)
			{
				num = num2;
			}
		}
		int num3 = (num + 1) % Math.Max(files.Length, 1);
		if (num3 >= files.Length)
		{
			Application.Quit();
			return;
		}
		replayPath = files[num3].FullName;
		recordReplay = false;
		string text2 = replayPath;
		if (text2 != null)
		{
			StartRequestPacket startRequest;
			try
			{
				replay = NetworkTools.ReadCompressedReplay(File.ReadAllBytes(text2), out startRequest);
				MonoBehaviour.print("Loaded replay: " + files[num3].Name);
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("could not load next replay: " + files[num3].Name + "file possibly corrupted " + ex.Message);
				Application.Quit();
				return;
			}
			SteamManager.startParameters = startRequest;
			GameLobby.isPlayingAReplay = true;
			clients = new List<Client>();
			for (int num4 = 0; num4 < startRequest.nrOfPlayers - 1; num4++)
			{
				clients.Add(new Client(1, new SteamConnection()));
			}
		}
		Updater.PreLevelLoad();
		Init(clients, 1, SteamManager.startParameters.currentLevel);
		CharacterSelectHandler_online.ForceStartGame(playerColors);
		Updater.PostLevelLoad();
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int num5 = 0; num5 < list.Count; num5++)
		{
			if (list[num5].Id == 1)
			{
				list[num5].UsesKeyboardAndMouse = SteamManager.startParameters.p1_id != 0;
			}
			else if (list[num5].Id == 2)
			{
				list[num5].UsesKeyboardAndMouse = SteamManager.startParameters.p2_id != 0;
			}
			else if (list[num5].Id == 3)
			{
				list[num5].UsesKeyboardAndMouse = SteamManager.startParameters.p3_id != 0;
			}
			else if (list[num5].Id == 4)
			{
				list[num5].UsesKeyboardAndMouse = SteamManager.startParameters.p4_id != 0;
			}
		}
	}

	private void Update()
	{
		if (!PlayReplayInEditor && clients != null && clients.Count > 0)
		{
			for (int num = clients.Count - 1; num >= 0; num--)
			{
				bool flag = false;
				for (int i = 0; i < SteamManager.instance.connectedPlayers.Count; i++)
				{
					if ((ulong)SteamManager.instance.connectedPlayers[i].id == (ulong)clients[num].Id)
					{
						flag = true;
					}
				}
				if (!flag)
				{
					disconnectedPlayerName = clients[num].steamConnection.steamName;
					disconnectedPlayerId = clients[num].PlayerId;
					if (SceneManager.GetActiveScene().buildIndex < 6 && GameLobby.isOnlineGame)
					{
						clients.Clear();
						UnityEngine.Debug.Log("A client was disconnected, abandoning lobby");
						GameSessionHandler.LeaveGame(abandonLobbyEntirely: true);
						return;
					}
					clients.RemoveAt(num);
				}
			}
			if (clients.Count == 0)
			{
				GameSessionHandler.LeaveGame(abandonLobbyEntirely: false);
				return;
			}
		}
		if (PlayReplayInEditor && SceneManager.GetActiveScene().name == "Replay")
		{
			Init(clients, 1, SteamManager.startParameters.currentLevel);
			CharacterSelectHandler_online.ForceStartGame(playerColors);
			List<Player> list = PlayerHandler.Get().PlayerList();
			for (int j = 0; j < list.Count; j++)
			{
				if (list[j].Id == 1)
				{
					list[j].UsesKeyboardAndMouse = SteamManager.startParameters.p1_id != 0;
				}
				else if (list[j].Id == 2)
				{
					list[j].UsesKeyboardAndMouse = SteamManager.startParameters.p2_id != 0;
				}
				else if (list[j].Id == 3)
				{
					list[j].UsesKeyboardAndMouse = SteamManager.startParameters.p3_id != 0;
				}
				else if (list[j].Id == 4)
				{
					list[j].UsesKeyboardAndMouse = SteamManager.startParameters.p4_id != 0;
				}
			}
		}
		else if (GameLobby.isPlayingAReplay && ((Keyboard.current != null && Keyboard.current.f10Key.wasPressedThisFrame) || goToNextReplay))
		{
			goToNextReplay = false;
			GoToNextReplay();
		}
		else
		{
			if (!hasBeenInitialized)
			{
				return;
			}
			if (replay != null && GameLobby.isPlayingAReplay)
			{
				PlayReplayUpdate();
				return;
			}
			ProcessNetworkPackets();
			if (!allClientsSynced)
			{
				if (timeSinceLastBroadcast > 1f / 60f)
				{
					BroadcastInputPacket();
					timeSinceLastBroadcast = 0f;
				}
				timeSinceLastBroadcast += Time.deltaTime;
				return;
			}
			float b = 8f * (float)GameTime.FixedTimeStep;
			timePassed += Mathf.Min(Time.deltaTime, b);
			bool isCatchingUp = false;
			bool flag2 = false;
			int team = PlayerHandler.Get().GetPlayer(localPlayerId).Team;
			for (int k = 0; k < clients.Count; k++)
			{
				if (PlayerHandler.Get().GetPlayer(clients[k].PlayerId).Team != team)
				{
					flag2 = true;
				}
			}
			if (!flag2)
			{
				SteamManager.ForceBacktoAbilitySelect();
			}
			if (localPlayerId != 1 && clients.Count != 0)
			{
				Client client = clients[0];
				for (int l = 0; l < clients.Count; l++)
				{
					if (clients[l].PlayerId == 1)
					{
						client = clients[l];
						break;
					}
				}
				if (client.newTimePassed)
				{
					float num2 = client.latestTimePassedReceived + (float)client.lagEstimateMillis * 0.001f;
					client.newTimePassed = false;
					float newObj = num2 - timePassed;
					timePassedDeltas.Add(newObj);
					newObj = EstimateTimePassedDelta();
					if (newObj > catchupWindow)
					{
						UpdateTimePassed(newObj);
						isCatchingUp = true;
						MonoBehaviour.print("catching up on frame:" + Updater.SimulationTicks + ", timeDiff: " + newObj);
					}
					else if (newObj < 0f - catchupWindow)
					{
						UpdateTimePassed(newObj);
						isCatchingUp = true;
						MonoBehaviour.print("slowing down on frame:" + Updater.SimulationTicks + ", timeDiff: " + newObj);
					}
				}
			}
			while (true)
			{
				double num3 = (double)Updater.SimulationTicks * (double)GameTime.FixedTimeStep;
				if ((double)timePassed - num3 < (double)GameTime.FixedTimeStep)
				{
					break;
				}
				if (InputBuffer.Count == 0)
				{
					if (allClientsSynced && clients.Count > 0)
					{
						timeSpentHalted += Time.deltaTime;
						float num4 = Time.unscaledTime - lastRebroadcastTime;
						int index = 0;
						for (int m = 0; m < clients.Count; m++)
						{
							if (clients[m].inputReceivedTimeStamp < clients[index].inputReceivedTimeStamp)
							{
								index = m;
							}
						}
						float num5 = Time.unscaledTime - clients[index].inputReceivedTimeStamp;
						float num6 = 10f;
						if (num5 > num6)
						{
							MonoBehaviour.print("Disconnecting player " + clients[index].PlayerId);
							UnityEngine.Debug.LogError("Disconnecting player " + clients[index].PlayerId);
							disconnectedPlayerName = clients[index].steamConnection.steamName;
							disconnectedPlayerId = clients[index].PlayerId;
							GameSessionHandler.LeaveGame(abandonLobbyEntirely: true);
							return;
						}
						if (num5 > 0.53333f)
						{
							if (num4 >= 0.25f)
							{
								RebroadcastLastInputPacket();
								lastRebroadcastTime = Time.unscaledTime;
							}
						}
						else if (num4 >= 1f / 62f)
						{
							RebroadcastLastInputPacket();
							lastRebroadcastTime = Time.unscaledTime;
						}
					}
					if (clients.Count > 0)
					{
						renderDebugText(isCatchingUp);
					}
					timePassed -= Time.deltaTime;
					return;
				}
				timeSpentHalted = 0f;
				InputPacketQuad item = InputBuffer.Dequeue();
				if (recordReplay)
				{
					inputRecording.Add(item);
				}
				if (AdaptiveInputDelayBuffer)
				{
					uint num7 = ((item.p1.seqNumber > item.p2.seqNumber) ? item.p1.seqNumber : item.p2.seqNumber);
					num7 = ((num7 > item.p3.seqNumber) ? num7 : item.p3.seqNumber);
					num7 = ((num7 > item.p4.seqNumber) ? num7 : item.p4.seqNumber);
					if (num7 % 32 == 0)
					{
						int num8 = Mathf.Max(Mathf.Max(Mathf.Max(previousInputQuad.p1.targetDelayBufferSize, previousInputQuad.p2.targetDelayBufferSize), previousInputQuad.p3.targetDelayBufferSize), previousInputQuad.p4.targetDelayBufferSize);
						if (num8 > 0)
						{
							targetDelayBufferSize = num8;
						}
					}
					if (targetDelayBufferSize > delayBufferSize)
					{
						delayBufferSize++;
						BroadcastInputPacket();
						BroadcastInputPacket();
					}
					else if (targetDelayBufferSize < delayBufferSize)
					{
						delayBufferSize--;
					}
					else
					{
						BroadcastInputPacket();
					}
				}
				else
				{
					BroadcastInputPacket();
				}
				lastRebroadcastTime = Time.unscaledTime;
				Player player = PlayerHandler.Get().GetPlayer(1);
				Player player2 = PlayerHandler.Get().GetPlayer(2);
				Player player3 = PlayerHandler.Get().GetPlayer(3);
				Player player4 = PlayerHandler.Get().GetPlayer(4);
				player?.OverrideInputWithNetworkInput(item.p1);
				player2?.OverrideInputWithNetworkInput(item.p2);
				player3?.OverrideInputWithNetworkInput(item.p3);
				player4?.OverrideInputWithNetworkInput(item.p4);
				previousInputQuad = item;
				try
				{
					Updater.TickSimulation(GameTime.FixedTimeStep);
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogError("Exception caught in simulation. loading next level as recovery: e = " + ex);
					simulationTicksPassed++;
					GameSessionHandler.EndGameImmediately();
					return;
				}
				simulationTicksPassed++;
				if (broadcastChecksums && !GameSessionHandler.GameIsPaused)
				{
					SendChecksumToPlayer1(simulationTicksPassed);
				}
				if (Updater.LoadedALevelThisUpdate)
				{
					Updater.LoadedALevelThisUpdate = false;
					break;
				}
			}
			if (clients.Count > 0)
			{
				renderDebugText(isCatchingUp);
			}
		}
	}

	private void renderDebugText(bool isCatchingUp)
	{
		double num = clients[0].lagEstimateMillis + clients[0].lagstandardDeviation * StandardDeviationMultiple;
		float num2 = Mathf.Clamp01(1f - (float)clients[0].AckPacketsReceived * (float)PingMeasurmentsRate / (float)inputPacketsSent);
		string text = "\nCurrentFrame = " + Updater.SimulationTicks + "\nTimePassed= " + timePassed + "\nPing = " + clients[0].ping + "ms\nDelayBufferSize= " + delayBufferSize + "\nTargetDelayBuffer= " + targetDelayBufferSize + "\nLagEstimate= " + clients[0].lagEstimateMillis + "\nStd = " + clients[0].lagstandardDeviation + "\nPlayoutDelay = " + num + "\nPacketLoss= " + num2;
		for (int i = 0; i < clients.Count; i++)
		{
			text = text + "\nTimePassed" + clients[i].PlayerId + "= " + clients[i].latestTimePassedReceived;
		}
		if (isCatchingUp)
		{
			text += "\nCatching up!";
		}
		DebugTextRenderer.SetText(text);
	}

	private void PlayReplayUpdate()
	{
		timePassed += Time.deltaTime;
		double num = (double)Updater.SimulationTicks * (double)GameTime.FixedTimeStep;
		int num2 = (int)Mathf.Max((float)((double)timePassed - num) / (float)GameTime.FixedTimeStep, 0f);
		num2 = ((num2 > 4) ? 4 : num2);
		if (Keyboard.current.f9Key.IsActuated())
		{
			num2 = 8;
			timePassed = (float)(num + (double)GameTime.FixedTimeStep * (double)num2);
		}
		for (int i = 0; i < num2; i++)
		{
			InputPacketQuad inputPacketQuad = ((replay.Count <= 0) ? default(InputPacketQuad) : replay.Dequeue());
			Player player = PlayerHandler.Get().GetPlayer(1);
			Player player2 = PlayerHandler.Get().GetPlayer(2);
			Player player3 = PlayerHandler.Get().GetPlayer(3);
			Player player4 = PlayerHandler.Get().GetPlayer(4);
			if (GameTime.IsTimeStopped())
			{
				if (player != null && player.isProtectedFromTimeStop)
				{
					player.OverrideInputWithNetworkInput(inputPacketQuad.p1);
				}
				if (player2 != null && player2.isProtectedFromTimeStop)
				{
					player2.OverrideInputWithNetworkInput(inputPacketQuad.p2);
				}
				if (player3 != null && player3.isProtectedFromTimeStop)
				{
					player3.OverrideInputWithNetworkInput(inputPacketQuad.p3);
				}
				if (player4 != null && player4.isProtectedFromTimeStop)
				{
					player4.OverrideInputWithNetworkInput(inputPacketQuad.p4);
				}
			}
			else
			{
				player?.OverrideInputWithNetworkInput(inputPacketQuad.p1);
				player2?.OverrideInputWithNetworkInput(inputPacketQuad.p2);
				player3?.OverrideInputWithNetworkInput(inputPacketQuad.p3);
				player4?.OverrideInputWithNetworkInput(inputPacketQuad.p4);
			}
			Updater.TickSimulation(GameTime.FixedTimeStep);
			if (Updater.LoadedALevelThisUpdate)
			{
				Updater.LoadedALevelThisUpdate = false;
				break;
			}
		}
		if (clients.Count > 0)
		{
			renderDebugText(isCatchingUp: false);
		}
	}
}
