	public static uint SwapBytesIfLittleEndian(uint x)
	{
		if (BitConverter.IsLittleEndian)
		{
			return SwapBytes(x);
		}
		return x;
	}

	public static ushort SwapBytesIfLittleEndian(ushort x)
	{
		if (BitConverter.IsLittleEndian)
		{
