	public static ulong SwapBytesIfLittleEndian(ulong x)
	{
		if (BitConverter.IsLittleEndian)
		{
			return SwapBytes(x);
		}
		return x;
	}

	public static ushort SwapBytes(ushort x)
	{
		return (ushort)((ushort)((x & 0xFF) << 8) | ((x >> 8) & 0xFF));
	}

	public static uint SwapBytes(uint x)
	{
		return ((x & 0xFF) << 24) + ((x & 0xFF00) << 8) + ((x & 0xFF0000) >> 8) + ((x & 0xFF000000u) >> 24);
	}

	public static ulong SwapBytes(ulong x)
	{
		return ((x & 0xFF) << 56) + ((x & 0xFF00) << 40) + ((x & 0xFF0000) << 24) + ((x & 0xFF000000u) << 8) + ((x & 0xFF00000000L) >> 8) + ((x & 0xFF0000000000L) >> 24) + ((x & 0xFF000000000000L) >> 40) + ((x & 0xFF00000000000000uL) >> 56);
	}

