	public static void EncodeAckForNetwork(ref byte[] data, Ack ack)
	{
		int num = 0;
		data[num++] = ack.playerId;
		data[num++] = ack.level;
		byte[] bytes = BitConverter.GetBytes(SwapBytesIfLittleEndian(ack.seqNumber));
		data[num++] = bytes[0];
		data[num++] = bytes[1];
		data[num++] = bytes[2];
		data[num++] = bytes[3];
	}

	public static Ack ReadAck(byte[] data, ref byte[] uintConversionHelperArray)
	{
		Ack result = new Ack
		{
			playerId = data[0],
			level = data[1]
		};
		int num = 2;
		uintConversionHelperArray[0] = data[num++];
		uintConversionHelperArray[1] = data[num++];
		uintConversionHelperArray[2] = data[num++];
		uintConversionHelperArray[3] = data[num++];
		result.seqNumber = BitConverter.ToUInt32(uintConversionHelperArray, 0);
		result.seqNumber = SwapBytesIfLittleEndian(result.seqNumber);
		return result;
	}

	public static void EncodeCheckSum(ref byte[] data, uint seqNum, byte level, ulong cs, byte localPlayerId)
	{
		int num = 0;
		data[num] = localPlayerId;
		num++;
		data[num] = level;
		num++;
