		InputPacket[] inputPackets4 = new InputPacket[32];
		int num = 105;
		while (num < serializedReplay.Length)
		{
			Array.Copy(serializedReplay, num, array, 0, array.Length);
			InputPacketUpdate update = ReadInputPacketUpdate(array, array.Length, ref uintConversionHelperArray);
			num += array.Length;
			Array.Copy(serializedReplay, num, array, 0, array.Length);
			InputPacketUpdate update2 = ReadInputPacketUpdate(array, array.Length, ref uintConversionHelperArray);
			num += array.Length;
			Array.Copy(serializedReplay, num, array, 0, array.Length);
			InputPacketUpdate update3 = ReadInputPacketUpdate(array, array.Length, ref uintConversionHelperArray);
			num += array.Length;
			Array.Copy(serializedReplay, num, array, 0, array.Length);
			InputPacketUpdate update4 = ReadInputPacketUpdate(array, array.Length, ref uintConversionHelperArray);
			num += array.Length;
			ReadInputPackets(update, ref inputPackets);
			ReadInputPackets(update2, ref inputPackets2);
			ReadInputPackets(update3, ref inputPackets3);
			ReadInputPackets(update4, ref inputPackets4);
			for (int i = 0; i < 32; i++)
