	public static byte[] SerializeReplay_compressed(List<InputPacketQuad> replay, byte[] startRequestEncoded)
	{
		List<byte> list = new List<byte>();
		int num = 32 - replay.Count % 32;
		uint seqNumber = replay[replay.Count - 1].p1.seqNumber;
		for (int i = 0; i < num; i++)
		{
			replay.Add(new InputPacketQuad
			{
				p1 = new InputPacket
				{
					seqNumber = seqNumber
				},
				p2 = new InputPacket
				{
					seqNumber = seqNumber
				},
				p3 = new InputPacket
				{
					seqNumber = seqNumber
				},
				p4 = new InputPacket
				{
					seqNumber = seqNumber
				}
			});
		}
		InputPacketQuad current = new InputPacketQuad
		{
			p1 = default(InputPacket),
			p2 = default(InputPacket),
			p3 = default(InputPacket),
			p4 = default(InputPacket)
		};
		for (int j = 0; j < startRequestEncoded.Length; j++)
		{
			list.Add(startRequestEncoded[j]);
		}
		int num2 = 0;
		while (num2 < replay.Count)
		{
			serialize32InputPacketsForPlayer1(replay, current, list, num2);
			serialize32InputPacketsForPlayer2(replay, current, list, num2);
			serialize32InputPacketsForPlayer3(replay, current, list, num2);
			serialize32InputPacketsForPlayer4(replay, current, list, num2);
			num2 += 32;
			current = replay[num2 - 1];
		}
		return list.ToArray();
	}

	public static Queue<InputPacketQuad> ReadCompressedReplay(byte[] compressedReplay, out StartRequestPacket startRequest)
	{
		byte[] ushortConversionHelperArray = new byte[2];
		byte[] uintConversionHelperArray = new byte[4];
		byte[] ulongConversionHelperArray = new byte[8];
		List<InputPacketQuad> list = new List<InputPacketQuad>();
		startRequest = ReadStartRequest(compressedReplay, ref uintConversionHelperArray, ref ulongConversionHelperArray, ref ushortConversionHelperArray);
		int num = 105;
		InputPacketQuad inputPacketQuad = default(InputPacketQuad);
		int num2 = 0;
		while (num < compressedReplay.Length)
		{
			for (int i = 0; i < 32; i++)
			{
				InputPacketQuad item = inputPacketQuad;
				list.Add(item);
			}
			num = read32InputPacketsForPlayer1(list, inputPacketQuad, compressedReplay, num, ref uintConversionHelperArray);
			num = read32InputPacketsForPlayer2(list, inputPacketQuad, compressedReplay, num, ref uintConversionHelperArray);
			num = read32InputPacketsForPlayer3(list, inputPacketQuad, compressedReplay, num, ref uintConversionHelperArray);
			num = read32InputPacketsForPlayer4(list, inputPacketQuad, compressedReplay, num, ref uintConversionHelperArray);
			num2 += 32;
			inputPacketQuad = list[num2 - 1];
		}
		for (int j = 0; j < list.Count; j++)
		{
			InputPacketQuad value = list[j];
			value.p1.seqNumber = (uint)(j + 1);
			value.p2.seqNumber = (uint)(j + 1);
			value.p3.seqNumber = (uint)(j + 1);
			value.p4.seqNumber = (uint)(j + 1);
			list[j] = value;
		}
		Queue<InputPacketQuad> queue = new Queue<InputPacketQuad>();
		for (int k = 0; k < list.Count; k++)
		{
			queue.Enqueue(list[k]);
		}
		return queue;
	}

	private static void ReadInputPackets(InputPacketUpdate update, ref InputPacket[] inputPackets)
	{
		for (int i = 0; i < inputPackets.Length; i++)
		{
			uint num = (uint)(1 << i);
			InputPacket inputPacket = new InputPacket
			{
				jump = ((update.jump & num) != 0),
				ab1 = ((update.ab1 & num) != 0),
				ab2 = ((update.ab2 & num) != 0),
				ab3 = ((update.ab3 & num) != 0),
				select = ((update.select & num) != 0),
				start = ((update.start & num) != 0),
				w = ((update.w & num) != 0),
				a = ((update.a & num) != 0),
				s = ((update.s & num) != 0),
				d = ((update.d & num) != 0),
				joystickAngle = update.joystickAngle[i],
				targetDelayBufferSize = update.targetDelayBufferSize
			};
			inputPackets[i] = inputPacket;
		}
	}
}
