public class Updater : MonoBehaviour
{
	public class UpdatableComparer : IComparer<MonoUpdatable>
	{
		public int Compare(MonoUpdatable x, MonoUpdatable y)
		{
			if (x.GetHashCode() != y.GetHashCode())
			{
				_ = x.HierarchyNumber;
				_ = y.HierarchyNumber;
			}
			return x.HierarchyNumber - y.HierarchyNumber;
		}
	}

	public static bool LoadedALevelThisUpdate = false;

	private static List<MonoUpdatable> toDestroyBuffer = new List<MonoUpdatable>();

	private static Queue<MonoBehaviour> destroyedMonos = new Queue<MonoBehaviour>();

	private static Queue<GameObject> destroyedObjects = new Queue<GameObject>();

	public static List<MonoUpdatable> updatables = new List<MonoUpdatable>();

	private static List<MonoUpdatable> toBeAddedUpdatables = new List<MonoUpdatable>();

	private static int addedUpdatables = 0;

	public static UpdatableComparer updateComparer = new UpdatableComparer();

	private static List<MonoUpdatable> toBeAddedPrefab = new List<MonoUpdatable>();

	private static int prefabsAdded = 0;

	private static bool registeringAPrefab = false;

	private static Unity.Mathematics.Random random = new Unity.Mathematics.Random(37u);

	private static int hitStopFrames;

	public static Fix standardFixedDeltaTime = (Fix)(1f / 60f);

	public static Fix SimTimePassed = Fix.Zero;

	public static Fix SimTimeSinceLevelLoaded = Fix.Zero;

	public static int SimulationTicks = 0;

	public static bool gameHasStopped = false;

	public bool autoUpdate;

	private float autoUpdateAccum;

	public static int AddedUpdatables => addedUpdatables;

	public static void PreLevelLoad()
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int i = 0; i < list.Count; i++)
		{
			_ = list[i].Id;
			list[i].isProtectedFromTimeStop = false;
			list[i].isInvisible = false;
			list[i].timeSpentInvisible = Fix.Zero;
			list[i].timeSinceEnteredAbility = Fix.Zero;
		}
		GameTime.PlayerTimeScale = (Fix)1L;
		toDestroyBuffer.Clear();
		updatables.Clear();
		toBeAddedUpdatables.Clear();
		toBeAddedPrefab.Clear();
		SimTimeSinceLevelLoaded = Fix.Zero;
	}

	public static void PostLevelLoad()
	{
		LoadedALevelThisUpdate = true;
	}

	public static void DestroyFix(GameObject go)
	{
		go.GetComponentsInChildren(includeInactive: true, toDestroyBuffer);
		FixTransform component = go.GetComponent<FixTransform>();
		for (int i = 0; i < toDestroyBuffer.Count; i++)
		{
			toDestroyBuffer[i].IsDestroyed = true;
		}
		if (component != null)
		{
			component.IsDestroyed = true;
		}
		for (int j = 0; j < go.transform.childCount; j++)
		{
			FixTransform component2 = go.transform.GetChild(j).GetComponent<FixTransform>();
			if (component2 != null)
			{
				component2.IsDestroyed = true;
			}
		}
		destroyedObjects.Enqueue(go);
	}

	public static void DestroyFix(MonoBehaviour mb)
	{
		if (mb is MonoUpdatable)
		{
			((MonoUpdatable)mb).IsDestroyed = true;
		}
		if (mb is FixTransform)
		{
			((FixTransform)mb).IsDestroyed = true;
		}
		destroyedMonos.Enqueue(mb);
	}

	public static void ReInit()
	{
		SimTimePassed = Fix.Zero;
		SimTimeSinceLevelLoaded = Fix.Zero;
		SimulationTicks = 0;
		updatables.Clear();
		toBeAddedPrefab.Clear();
		toBeAddedUpdatables.Clear();
		addedUpdatables = 0;
		prefabsAdded = 0;
		registeringAPrefab = false;
	}

	public static void BeginRegisterPrefab()
	{
		registeringAPrefab = true;
	}

	public static void EndRegisterPrefab()
	{
		registeringAPrefab = false;
		for (int i = 0; i < toBeAddedPrefab.Count; i++)
		{
			toBeAddedPrefab[i].HierarchyNumber += prefabsAdded + 100000000;
			toBeAddedUpdatables.Add(toBeAddedPrefab[i]);
		}
		prefabsAdded += toBeAddedPrefab.Count;
		toBeAddedPrefab.Clear();
	}

	public static void RegisterUpdatable(MonoUpdatable updatable)
	{
		if (registeringAPrefab)
		{
			addedUpdatables++;
			toBeAddedPrefab.Add(updatable);
		}
		else
		{
			addedUpdatables++;
			toBeAddedUpdatables.Add(updatable);
		}
	}

	public static void HitStop(int frames)
	{
		hitStopFrames = frames;
	}

	public static bool InHitstop()
	{
		return hitStopFrames > 0;
	}

	public static void InitSeed(uint seed)
	{
		random.InitState(seed);
	}

	public static int RandomInt(int from, int to)
	{
		return random.NextInt(from, to);
	}

	public static Vec2 RandomInsideUnitCircle()
	{
		return new Vec2(RandomFix(Fix.Zero, Fix.PiTimes2)) * RandomFix(Fix.Zero, Fix.One);
	}

	public static Vec2 RandomUnitVector()
	{
		return new Vec2(RandomFix(Fix.Zero, Fix.PiTimes2));
	}

	public static Fix RandomFix(Fix from, Fix to)
	{
		if (Fix.Floor(from) == Fix.Floor(to))
		{
			uint min = (uint)(from.m_rawValue & 0xFFFFFFFFu);
			uint max = (uint)(to.m_rawValue & 0xFFFFFFFFu);
			uint num = random.NextUInt(min, max);
			return Fix.FromRaw(Fix.Floor(from).m_rawValue + num);
		}
		int min2 = (int)(long)Fix.Floor(from);
		int max2 = (int)(long)Fix.Floor(to);
		long num2 = random.NextInt(min2, max2);
		uint min3 = (uint)(from.m_rawValue & 0xFFFFFFFFu);
		uint max3 = uint.MaxValue;
		uint num3 = random.NextUInt(min3, max3);
		return Fix.FromRaw((num2 << 32) + num3);
	}

	public static void TickSimulation(Fix deltaTime)
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		if (LoadedALevelThisUpdate)
		{
			gameHasStopped = false;
		}
		if (!TutorialGameHandler.isInTutorial && !GameLobby.isOnlineGame && !gameHasStopped && Host.recordReplay && !GameLobby.isPlayingAReplay)
		{
			if (LoadedALevelThisUpdate || SimulationTicks == 0)
			{
				uint tickCount = (uint)Environment.TickCount;
				InitSeed(tickCount);
				StartRequestPacket p = new StartRequestPacket
				{
					seed = tickCount,
					seqNum = 1,
					frameBufferSize = 0,
					isDemoMask = byte.MaxValue,
					nrOfAbilites = (byte)Settings.Get().NumberOfAbilities,
					currentLevel = GameSession.CurrentLevel(),
					nrOfPlayers = (byte)list.Count
				};
				NamedSpriteList abilityIcons = SteamManager.instance.abilityIcons;
				for (int i = 0; i < list.Count; i++)
				{
					byte b = (byte)abilityIcons.IndexOf(list[i].Abilities[0].name);
					switch (list[i].Id)
					{
					case 1:
						p.p1_color = 1;
						p.p1_id = 1uL;
						p.p1_team = (byte)list[i].Team;
						p.p1_ability1 = b;
						break;
					case 2:
						p.p2_color = 2;
						p.p2_id = 2uL;
						p.p2_team = (byte)list[i].Team;
						p.p2_ability1 = b;
						break;
					case 3:
						p.p3_color = 3;
						p.p3_id = 3uL;
						p.p3_team = (byte)list[i].Team;
						p.p3_ability1 = b;
						break;
					case 4:
						p.p4_color = 4;
						p.p4_id = 4uL;
						p.p4_team = (byte)list[i].Team;
						p.p4_ability1 = b;
						break;
					}
					if (p.nrOfAbilites > 1)
					{
						b = (byte)abilityIcons.IndexOf(list[i].Abilities[1].name);
						switch (list[i].Id)
						{
						case 1:
							p.p1_ability2 = b;
							break;
						case 2:
							p.p2_ability2 = b;
							break;
						case 3:
							p.p3_ability2 = b;
							break;
						case 4:
							p.p4_ability2 = b;
							break;
						}
					}
					if (p.nrOfAbilites > 2)
					{
						b = (byte)abilityIcons.IndexOf(list[i].Abilities[2].name);
						switch (list[i].Id)
						{
						case 1:
							p.p1_ability3 = b;
							break;
						case 2:
							p.p2_ability3 = b;
							break;
						case 3:
							p.p3_ability3 = b;
							break;
						case 4:
							p.p4_ability3 = b;
							break;
						}
					}
				}
				SteamManager.instance.EncodeCurrentStartParameters_forReplay(ref SteamManager.instance.networkClient.EncodedStartRequest, p, isLocalGame: true);
			}
			InputPacketQuad quadToSave = default(InputPacketQuad);
			for (int j = 0; j < list.Count; j++)
			{
				InputPacket inputPacket = Host.CurrentInputAsPacket(list[j].Id, (uint)(SimulationTicks + 1), null);
				switch (list[j].Id)
				{
				case 1:
					quadToSave.p1 = inputPacket;
					break;
				case 2:
					quadToSave.p2 = inputPacket;
					break;
				case 3:
					quadToSave.p3 = inputPacket;
					break;
				case 4:
					quadToSave.p4 = inputPacket;
					break;
				}
			}
			SteamManager.instance?.networkClient?.RecordReplayFrame(quadToSave);
		}
		for (int k = 0; k < list.Count; k++)
		{
			list[k].UpdateFRAMEDependentInputs();
			list[k].UpdatePlayer(deltaTime);
		}
		for (int num = toBeAddedUpdatables.Count - 1; num >= 0; num--)
		{
			if (toBeAddedUpdatables[num] == null || toBeAddedUpdatables[num].IsDestroyed)
			{
				toBeAddedUpdatables.RemoveAt(num);
			}
		}
		for (int l = 0; l < toBeAddedUpdatables.Count; l++)
		{
			MonoUpdatable value = toBeAddedUpdatables[l];
			toBeAddedUpdatables[l] = value;
		}
		toBeAddedUpdatables.Sort(updateComparer);
		for (int m = 0; m < toBeAddedUpdatables.Count; m++)
		{
			if (toBeAddedUpdatables[m] != null && !toBeAddedUpdatables[m].IsDestroyed)
			{
				toBeAddedUpdatables[m].Init();
			}
		}
		for (int n = 0; n < toBeAddedUpdatables.Count; n++)
		{
			updatables.Add(toBeAddedUpdatables[n]);
		}
		toBeAddedUpdatables.Clear();
		if (!GameTime.IsTimeStopped())
		{
			DetPhysics.Get().UpdateDuplicatedObjects();
		}
		for (int num2 = updatables.Count - 1; num2 >= 0; num2--)
		{
			if (updatables[num2] == null || updatables[num2].IsDestroyed)
			{
				updatables[num2]?.OnDestroyUpdatable();
				updatables.RemoveAt(num2);
			}
		}
		for (int num3 = 0; num3 < updatables.Count; num3++)
		{
			if (updatables[num3] != null && !updatables[num3].IsDestroyed && updatables[num3].IsEnabled())
			{
				updatables[num3].UpdateSim(deltaTime);
			}
		}
		MagnetGun.StaticUpdate();
		if (LoadedALevelThisUpdate)
		{
			SimTimePassed += deltaTime;
			SimTimeSinceLevelLoaded += deltaTime;
			SimulationTicks++;
			LoadedALevelThisUpdate = false;
			return;
		}
		DetPhysics.Get().Simulate(deltaTime);
		for (int num4 = 0; num4 < updatables.Count; num4++)
		{
			if (updatables[num4] != null && !updatables[num4].IsDestroyed && updatables[num4].IsEnabled())
			{
				updatables[num4].LateUpdateSim(deltaTime);
			}
		}
		DetPhysics.Get().VeryLateRopeUpdate();
		DetPhysics.Get().UpdateRopeMesh_parallell();
		for (int num5 = updatables.Count - 1; num5 >= 0; num5--)
		{
			if (updatables[num5] == null || updatables[num5].IsDestroyed)
			{
				updatables[num5]?.OnDestroyUpdatable();
				updatables.RemoveAt(num5);
			}
		}
		while (destroyedObjects.Count > 0)
		{
			UnityEngine.Object.DestroyImmediate(destroyedObjects.Dequeue(), allowDestroyingAssets: false);
		}
		while (destroyedMonos.Count > 0)
		{
			UnityEngine.Object.DestroyImmediate(destroyedMonos.Dequeue(), allowDestroyingAssets: false);
		}
		SimTimePassed += deltaTime;
		SimTimeSinceLevelLoaded += deltaTime;
		SimulationTicks++;
	}

	public static ulong ComputeChecksum()
	{
		FixTransform[] array = UnityEngine.Object.FindObjectsOfType<FixTransform>();
		Fix x = Fix.Zero;
		for (int i = 0; i < array.Length; i++)
		{
			if (!array[i].IsDestroyed)
			{
				x = Fix.SlowAdd(x, array[i].ComputeCheckSum());
			}
		}
		return (ulong)x.m_rawValue;
	}

	public static string SerializeState()
	{
		FixTransform[] array = UnityEngine.Object.FindObjectsOfType<FixTransform>();
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine("----------------");
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].IsDestroyed)
			{
				continue;
			}
			MonoUpdatable[] components = array[i].GetComponents<MonoUpdatable>();
			if (components != null)
			{
				stringBuilder.Append(array[i].gameObject.name + " hierarchyNumbers = ");
				for (int j = 0; j < components.Length; j++)
				{
					if (components[j].IsDestroyed)
					{
						stringBuilder.Append("[DESTROYED]");
					}
					stringBuilder.Append(components[j].HierarchyNumber);
					stringBuilder.Append(", ");
				}
			}
			else
			{
				stringBuilder.Append(array[i].gameObject.name);
			}
			stringBuilder.Append("\n");
			stringBuilder.Append("posX = ");
			stringBuilder.Append(array[i].position.x);
			stringBuilder.Append(", posY = ");
			stringBuilder.Append(array[i].position.y);
			stringBuilder.Append(", rotation = ");
			stringBuilder.Append(array[i].rotation);
			stringBuilder.AppendLine("----------------");
		}
		return stringBuilder.ToString();
	}

	private void Update()
	{
		if (!autoUpdate || GameLobby.isOnlineGame || GameLobby.isPlayingAReplay)
		{
			return;
		}
		autoUpdateAccum += Time.deltaTime;
		while (autoUpdateAccum > 0f)
		{
			autoUpdateAccum -= (float)GameTime.FixedTimeStep;
			if (hitStopFrames > 0)
			{
				hitStopFrames--;
				SimTimePassed += GameTime.FixedTimeStep;
				SimTimeSinceLevelLoaded += GameTime.FixedTimeStep;
				SimulationTicks++;
			}
			else
			{
				TickSimulation(GameTime.FixedTimeStep);
			}
		}
	}
}
public class ParticleCamera : MonoBehaviour
{
	[SerializeField]
	[HideInInspector]
	private Camera particleCamera;

	public string globalTextureName = "_FireParticleRT";

	public bool force18by9;

	private void Start()
	{
	}

	private void Awake()
	{
		particleCamera = GetComponent<Camera>();
		if (force18by9)
		{
			particleCamera.aspect = 2f;
		}
		GenerateRenderTarget();
	}

	private void GenerateRenderTarget()
	{
		if (particleCamera.targetTexture != null)
		{
			RenderTexture targetTexture = particleCamera.targetTexture;
			particleCamera.targetTexture = null;
			UnityEngine.Object.DestroyImmediate(targetTexture);
		}
		particleCamera.targetTexture = new RenderTexture(particleCamera.pixelWidth, particleCamera.pixelHeight, 24);
		particleCamera.targetTexture.filterMode = FilterMode.Bilinear;
		particleCamera.targetTexture.wrapMode = TextureWrapMode.Mirror;
		Shader.SetGlobalTexture(globalTextureName, particleCamera.targetTexture);
	}
}
public class PSVInvisible : MonoUpdatable, IAbilityComponent
{
	public AnimationCurve alphaAnim = AnimationCurve.EaseInOut(0f, 1f, 1f, 0f);

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private PlayerPhysics physics;

	private PlayerInfo playerInfo;

	private Player player;

	private Ability ability;

	private Fix timePassed;

	private bool isVisible;

	public override void Init()
	{
		physics.OnNoLongerGrounded += ExitAbility;
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		physics.Move(Vec2.zero, simDeltaTime);
		physics.AlignToGround();
		Player player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		timePassed += GameTime.FixedDeltaTime(player.Id, simDeltaTime);
		InvisibleAnimation(isVisible);
		Vec2 vec = player.InputVector();
		if (player.jumpButton_PressedThisFrame())
		{
			ExitAbility(new AbilityExitInfo
			{
				enterJump = player.jumpButton_PressedThisFrame()
			});
		}
		else if (player.AbilityButtonIsDown((playerInfo.AbilityButtonUsedIndex012 + 1) % 3) || player.AbilityButtonIsDown((playerInfo.AbilityButtonUsedIndex012 + 2) % 3))
		{
			ExitAbility(default(AbilityExitInfo));
		}
		else if (timePassed >= 1L && (vec.x != 0L || vec.y != 0L))
		{
			ExitAbility(default(AbilityExitInfo));
		}
	}

	public void InvisibleAnimation(bool visible)
	{
		UnityEngine.Color color = spriteRen.color;
		color.a = alphaAnim.Evaluate((float)timePassed);
		spriteRen.color = color;
	}

	public void OnEnterAbility()
	{
		AudioManager.Get().Play("invisibility");
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		spriteRen.sprite = playerInfo.EntrySprite;
		physics.SyncPhysicsTo(playerInfo);
		if (!playerInfo.isGrounded)
		{
			Vec2 selfImposedVelocity = body.selfImposedVelocity;
			selfImposedVelocity.x = Fix.Zero;
			body.selfImposedVelocity = selfImposedVelocity;
		}
		body.externalVelocity = playerInfo.externalVelocity;
		body.rotation = playerInfo.rotation;
		isVisible = true;
		timePassed = Fix.Zero;
		float x = (playerInfo.isFacingRight ? 1 : (-1));
		base.transform.localScale = new Vector3(x, base.transform.localScale.y, base.transform.localScale.z);
	}

	private void ExitAbility(Fix prevRot)
	{
		ExitAbility(default(AbilityExitInfo));
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		UnityEngine.Color color = spriteRen.color;
		color.a = 1f;
		spriteRen.color = color;
		isVisible = true;
		body.rotation = Fix.Zero;
		exitInfo.groundedSpeed = Vec2.Magnitude(body.selfImposedVelocity);
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.isFacingRight = playerInfo.isFacingRight;
		exitInfo.radius = physics.radius;
		if (physics.IsGrounded())
		{
			physics.getAttachedGround().currentNormal(body);
			exitInfo.position = body.position;
			exitInfo.currentlyAttachedGround = physics.getAttachedGround();
			exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		}
		else
		{
			exitInfo.position = body.position;
		}
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.lastSprite = spriteRen.sprite;
		ability.ExitAbility(exitInfo);
	}
}
public class PlatformSlimeTrailCamera : MonoBehaviour
{
	[SerializeField]
	[HideInInspector]
	private Camera slimeCamera;

	private Camera mainCamera;

	private SpriteRenderer groundRenderer;

	[SerializeField]
	private float ScaleTexture = 1f;

	private const string TrailTextureName = "_SlimeRT";

	private const string CameraPosName = "_SlimeCamera_WorldPosition";

	private const string slimeCameraSizeName = "_SlimeCamera_Size";

	private const string mainCameraSizeName = "_MainCamera_Size";

	private const string spriteRendererFlippedName = "_Flip01";

	private float scale = 1f;

	private void Awake()
	{
		slimeCamera = GetComponent<Camera>();
		groundRenderer = GetComponentInParent<SpriteRenderer>();
		Bounds bounds = groundRenderer.sprite.bounds;
		slimeCamera.aspect = bounds.size.x / bounds.size.y;
		slimeCamera.orthographicSize = bounds.extents.y;
		mainCamera = Camera.main;
		GenerateRenderTarget();
	}

	private void Update()
	{
		if (groundRenderer != null && groundRenderer.transform.localScale.x != scale)
		{
			scale = groundRenderer.transform.localScale.x;
			slimeCamera.orthographicSize = groundRenderer.sprite.bounds.extents.y * scale;
		}
	}

	private void GenerateRenderTarget()
	{
		if (slimeCamera.targetTexture != null)
		{
			RenderTexture targetTexture = slimeCamera.targetTexture;
			slimeCamera.targetTexture = null;
			UnityEngine.Object.DestroyImmediate(targetTexture);
		}
		slimeCamera.targetTexture = new RenderTexture((int)((float)groundRenderer.sprite.texture.width * ScaleTexture), (int)((float)groundRenderer.sprite.texture.height * ScaleTexture), 0, RenderTextureFormat.ARGB32)
		{
			filterMode = FilterMode.Bilinear
		};
		Vector4 value = new Vector4
		{
			x = (groundRenderer.flipX ? 1 : 0),
			y = (groundRenderer.flipY ? 1 : 0)
		};
		groundRenderer.material.SetVector("_Flip01", value);
		groundRenderer.material.SetTexture("_SlimeRT", slimeCamera.targetTexture);
	}
}
