public class Player
{
	public class InputProfile
	{
		public bool startButton_IS_DOWN;

		public bool selectButton_IS_DOWN;

		public bool jumpButton_IS_DOWN;

		public bool firstAbilityButton_IS_DOWN;

		public bool secondAbilityButton_IS_DOWN;

		public bool thirdAbilityButton_IS_DOWN;

		public bool jumpButton_DOWN_THIS_FRAME;

		public bool jumpButton_DOWN_LAST_FRAME;

		public bool w_IS_DOWN;

		public bool a_IS_DOWN;

		public bool s_IS_DOWN;

		public bool d_IS_DOWN;

		public byte joystickAngleByte;

		public bool UsesMouse;

		private static Vec2[] inputVectors;

		public Vec2 InputVector
		{
			get
			{
				if (UsesMouse)
				{
					Vec2 zero = Vec2.zero;
					if (w_IS_DOWN)
					{
						zero.y += Fix.One;
					}
					if (s_IS_DOWN)
					{
						zero.y -= Fix.One;
					}
					if (d_IS_DOWN)
					{
						zero.x += Fix.One;
					}
					if (a_IS_DOWN)
					{
						zero.x -= Fix.One;
					}
					if (zero.x == 0L && zero.y == 0L)
					{
						return Vec2.zero;
					}
					return zero;
				}
				return inputVectors[joystickAngleByte];
			}
		}

		public Vec2 AimVector => inputVectors[joystickAngleByte];

		public InputProfile()
		{
			if (inputVectors == null)
			{
				GenerateInputVectorTable();
			}
		}

		public bool Equals_ignoringMousePos(InputProfile that)
		{
			if (that == null)
			{
				return false;
			}
			if (UsesMouse)
			{
				if (startButton_IS_DOWN == that.startButton_IS_DOWN && selectButton_IS_DOWN == that.selectButton_IS_DOWN && jumpButton_IS_DOWN == that.jumpButton_IS_DOWN && firstAbilityButton_IS_DOWN == that.firstAbilityButton_IS_DOWN && secondAbilityButton_IS_DOWN == that.secondAbilityButton_IS_DOWN && thirdAbilityButton_IS_DOWN == that.thirdAbilityButton_IS_DOWN && jumpButton_DOWN_THIS_FRAME == that.jumpButton_DOWN_THIS_FRAME && jumpButton_DOWN_LAST_FRAME == that.jumpButton_DOWN_LAST_FRAME && w_IS_DOWN == that.w_IS_DOWN && a_IS_DOWN == that.a_IS_DOWN && s_IS_DOWN == that.s_IS_DOWN)
				{
					return d_IS_DOWN == that.d_IS_DOWN;
				}
				return false;
			}
			if (startButton_IS_DOWN == that.startButton_IS_DOWN && selectButton_IS_DOWN == that.selectButton_IS_DOWN && jumpButton_IS_DOWN == that.jumpButton_IS_DOWN && firstAbilityButton_IS_DOWN == that.firstAbilityButton_IS_DOWN && secondAbilityButton_IS_DOWN == that.secondAbilityButton_IS_DOWN && thirdAbilityButton_IS_DOWN == that.thirdAbilityButton_IS_DOWN && jumpButton_DOWN_THIS_FRAME == that.jumpButton_DOWN_THIS_FRAME && jumpButton_DOWN_LAST_FRAME == that.jumpButton_DOWN_LAST_FRAME)
			{
				return joystickAngleByte == that.joystickAngleByte;
			}
			return false;
		}

		public void Clone(InputProfile buffer)
		{
			buffer.startButton_IS_DOWN = startButton_IS_DOWN;
			buffer.selectButton_IS_DOWN = selectButton_IS_DOWN;
			buffer.jumpButton_IS_DOWN = jumpButton_IS_DOWN;
			buffer.firstAbilityButton_IS_DOWN = firstAbilityButton_IS_DOWN;
			buffer.secondAbilityButton_IS_DOWN = secondAbilityButton_IS_DOWN;
			buffer.thirdAbilityButton_IS_DOWN = thirdAbilityButton_IS_DOWN;
			buffer.jumpButton_DOWN_THIS_FRAME = jumpButton_DOWN_THIS_FRAME;
			buffer.jumpButton_DOWN_LAST_FRAME = jumpButton_DOWN_LAST_FRAME;
			buffer.w_IS_DOWN = w_IS_DOWN;
			buffer.a_IS_DOWN = a_IS_DOWN;
			buffer.s_IS_DOWN = s_IS_DOWN;
			buffer.d_IS_DOWN = d_IS_DOWN;
			buffer.joystickAngleByte = joystickAngleByte;
			buffer.UsesMouse = UsesMouse;
		}

		public static Vec2 inputVectorFromByte(byte angle)
		{
			return inputVectors[angle];
		}

		private static void GenerateInputVectorTable()
		{
			inputVectors = new Vec2[256];
			inputVectors[0] = Vec2.zero;
			for (int i = 1; i < inputVectors.Length; i++)
			{
				int num = i - 1;
				Fix x = Fix.PiTimes2 * ((Fix)num / (Fix)255f);
				inputVectors[i] = new Vec2(Fix.Cos(x), Fix.Sin(x));
			}
		}

		public static byte JoyStickAngleByteFromVector(Vec2 v)
		{
			if (Vec2.SqrMagnitude(v) < Constants.DEADZONE * Constants.DEADZONE)
			{
				return 0;
			}
			return (byte)((int)(long)(Vec2.NormalizedVectorAngle(v) / Fix.PiTimes2 * (Fix)255L) % 255 + 1);
		}

		public void Reset()
		{
			joystickAngleByte = 0;
			startButton_IS_DOWN = false;
			selectButton_IS_DOWN = false;
			jumpButton_IS_DOWN = false;
			firstAbilityButton_IS_DOWN = false;
			secondAbilityButton_IS_DOWN = false;
			thirdAbilityButton_IS_DOWN = false;
			jumpButton_DOWN_THIS_FRAME = false;
			UsesMouse = false;
			w_IS_DOWN = false;
			a_IS_DOWN = false;
			s_IS_DOWN = false;
			d_IS_DOWN = false;
		}

		public bool GetButtonDown(Constants.Button button)
		{
			return button switch
			{
				Constants.Button.jump => jumpButton_IS_DOWN, 
				Constants.Button.ab1 => firstAbilityButton_IS_DOWN, 
				Constants.Button.ab2 => secondAbilityButton_IS_DOWN, 
				Constants.Button.ab3 => thirdAbilityButton_IS_DOWN, 
				Constants.Button.start => startButton_IS_DOWN, 
				Constants.Button.select => selectButton_IS_DOWN, 
				_ => false, 
			};
		}

		internal void UpdateFrameDependentInputs()
		{
			jumpButton_DOWN_THIS_FRAME = !jumpButton_DOWN_LAST_FRAME && jumpButton_IS_DOWN;
			jumpButton_DOWN_LAST_FRAME = jumpButton_IS_DOWN;
		}
	}

