	public void SetPosition(Vec2 pos, SlimeController controller)
	{
		if (!(controller == null) && !controller.IsDestroyed)
		{
			int num = comparePriority(controller, positionSetterThisFrame);
			if (num > 0 || (num == 0 && positionSetterLastFrame == controller))
			{
				positionSetterThisFrame = controller;
				Position = pos;
			}
		}
	}

	private int comparePriority(SlimeController a, SlimeController b)
	{
		bool flag = a != null && !a.IsDestroyed;
		bool flag2 = b != null && !b.IsDestroyed;
		if (!flag)
		{
			return -1;
		}
		if (!flag2 && flag)
		{
			return 1;
		}
		int count = a.abilities.Count;
		int count2 = b.abilities.Count;
		return count - count2;
	}

	public void UpdatePlayer(Fix deltaTime)
	{
		if (isInvisible)
		{
			timeSpentInvisible += GameTime.FixedDeltaTime(Id, deltaTime);
			timeSinceEnteredAbility += GameTime.FixedDeltaTime(Id, deltaTime);
			if (timeSpentInvisible > 5L)
			{
				isInvisible = false;
				timeSpentInvisible = Fix.Zero;
				timeSinceEnteredAbility = Fix.Zero;
			}
		}
		else
		{
			timeSpentInvisible = Fix.Zero;
			timeSinceEnteredAbility = Fix.Zero;
		}
		if (positionSetterLastFrame != null && !positionSetterLastFrame.IsDestroyed)
		{
			_ = !positionSetterLastFrame.IsEnabled();
		}
		else
			_ = 0;
		positionSetterLastFrame = positionSetterThisFrame;
		positionSetterThisFrame = null;
	}

