	public bool PlayerHasValidGamepad()
	{
		if (UsesKeyboardAndMouse)
		{
			return true;
		}
		foreach (Gamepad item in Gamepad.all)
		{
			if (item.deviceId == inputDevice.deviceId)
			{
				return true;
			}
		}
		return false;
	}

	public void Kill(int idOfKiller, long timestamp, CauseOfDeath causeOfDeath)
	{
		if (WonThisRound)
		{
			return;
		}
		Rumble(global::Rumble.Big);
		Player player = PlayerHandler.Get().GetPlayer(idOfKiller);
		if (playersAndClonesStillAlive == 1)
		{
			Deaths++;
			playersAndClonesStillAlive--;
			if (player != null)
			{
				player.Kills++;
				player.Rumble(global::Rumble.Small);
			}
			if (idOfKiller != Id)
			{
				AchievementHandler.RegisterKill(idOfKiller);
			}
			stillAliveThisRound = false;
			TimestampWhenKilled = timestamp;
			CauseOfDeath = causeOfDeath;
			this.playerDied?.Invoke(Id, causeOfDeath);
		}
		else
		{
			Deaths++;
			playersAndClonesStillAlive--;
			if (player != null)
			{
				player.Kills++;
				player.Rumble(global::Rumble.Small);
			}
		}
	}

	public void WinAGame()
	{
		GamesWon++;
		IsMostRecentWinner = true;
		WonThisRound = true;
		this.playerWon?.Invoke(Id);
	}

