[RequireComponent(typeof(FixTransform))]
public class PlayerBody : MonoUpdatable
{
	public bool simulated = true;

	public Vec2 selfImposedVelocity;

	public Vec2 externalVelocity;

	[HideInInspector]
	public Vec2 prevPosition;

	private FixTransform fixTransform;

	private IPlayerIdHolder idHolder;

	private PlayerPhysics physics;

	private Vec2 prevPlayerVel;

	private Vec2 prevImposedVel;

	private Vec2 prevExternalVel;

	[NonSerialized]
	public Vec2 extraSwingForce;

	public RopeBody ropeBody;

	public bool topAttachment;

	public bool ignoreGravityWhenRoped;

	public Fix RopePlayerMass01 = (Fix)0.5;

	public Vec2 Velocity => externalVelocity + selfImposedVelocity;

	public Vec2 position
	{
		get
		{
			return fixTransform.position;
		}
		set
		{
			fixTransform.position = value;
		}
	}

	public Fix rotation
	{
		get
		{
			return fixTransform.rotation;
		}
		set
		{
			fixTransform.rotation = value;
		}
	}

	public Vec2 up
	{
		get
		{
			return fixTransform.up;
		}
		set
		{
			fixTransform.up = value;
		}
	}

	public Vec2 right
	{
		get
		{
			return fixTransform.right;
		}
		set
		{
			fixTransform.right = value;
		}
	}

	public FixTransform fixtrans => fixTransform;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTransform = GetComponent<FixTransform>();
		idHolder = GetComponent<IPlayerIdHolder>();
		physics = GetComponent<PlayerPhysics>();
	}

	public override void Init()
	{
		prevPlayerVel = Velocity;
		prevImposedVel = selfImposedVelocity;
		prevExternalVel = externalVelocity;
	}

	public override bool IsEnabled()
	{
		if (base.IsEnabled())
		{
			return simulated;
		}
		return false;
	}

	public void AddForce(Vec2 force)
	{
		externalVelocity += force * (Fix)35L;
	}

	public override void LateUpdateSim(Fix SimDeltaTime)
	{
		if (ropeBody != null && !ropeBody.enabled)
		{
			ropeBody = null;
		}
		else if (ropeBody != null && ropeBody.enabled)
		{
			for (int i = 0; i < ropeBody.segmentCount - 2; i++)
			{
				if (Vec2.SqrMagnitude(ropeBody.segment[i] - ropeBody.segment[i + 1]) > DetPhysics.Get().maxStretchLength)
				{
					AttachRope(null, topAttachment);
					break;
				}
			}
		}
		if (ropeBody != null && ropeBody.enabled)
		{
			Vec2 vec = selfImposedVelocity - prevImposedVel;
			vec += Vec2.down * DetPhysics.Get().playerGravity;
			Vec2 vec2 = externalVelocity - prevExternalVel;
			if (ignoreGravityWhenRoped)
			{
				vec.y = Fix.Zero;
			}
			ropeBody.SetForce(vec + vec2 + extraSwingForce, topAttachment);
			extraSwingForce = Vec2.zero;
		}
		prevPosition = fixtrans.position;
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (ropeBody != null && ropeBody.enabled)
		{
			Player player = PlayerHandler.Get().GetPlayer(idHolder.GetPlayerId());
			if (player.Id == ropeBody.ownerId && ((physics != null && !physics.IsGrounded() && !physics.jumpedThisFrame) || physics == null) && player.jumpButton_PressedThisFrame())
			{
				int num = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
				selfImposedVelocity = (ropeBody.segment[num] - ropeBody.segmentPrev[num]) / GameTime.FixedTimeStep;
				AttachRope(null, topAttachment);
				AudioManager.Get().Play("hookshotLetGo");
			}
		}
		if (ropeBody != null && !ropeBody.enabled)
		{
			ropeBody = null;
		}
		else if (ropeBody != null)
		{
			_ = ropeBody.enabled;
		}
		if (ropeBody != null && ropeBody.enabled)
		{
			position += Velocity * GameTime.FixedDeltaTime(idHolder, SimDeltaTime);
			if (ropeBody.hasBeenDettached)
			{
				int num2 = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
				ropeBody.segment[num2] = position;
				AttachRope(null, topAttachment);
			}
			else if (!ropeBody.hookHasArrived)
			{
				int num3 = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
				ropeBody.segment[num3] = position;
				ropeBody.SetTimeInAir(Fix.Zero, topAttachment);
				ropeBody.SetMass01(Fix.One, topAttachment, Fix.One);
				ropeBody.SetForce(Vec2.zero, topAttachment);
			}
			else if (physics != null && physics.IsGrounded())
			{
				Fix mass = Fix.Lerp(Fix.One, (Fix)0.9, Fix.Clamp01(ropeBody.timeSinceHookArrived));
				ropeBody.SetTimeInAir(Fix.Zero, topAttachment);
				ropeBody.SetMass01(mass, topAttachment, Fix.One);
				ropeBody.SetForce(Vec2.zero, topAttachment);
			}
			else
			{
				int num4 = ((!topAttachment) ? (ropeBody.segmentCount - 1) : 0);
				Fix fix;
				if (topAttachment)
				{
					ropeBody.timeInAir_start += SimDeltaTime;
					fix = ropeBody.timeInAir_start;
				}
				else
				{
					ropeBody.timeInAir_end += SimDeltaTime;
					fix = ropeBody.timeInAir_end;
				}
				ropeBody.SetMass01((RopePlayerMass01 == Fix.Zero) ? ((Fix)0.5) : RopePlayerMass01, topAttachment, Fix.One);
				Fix fix2 = Fix.Clamp01(fix * (Fix)2L);
				if (ignoreGravityWhenRoped)
				{
					fix2 = Fix.One - RopePlayerMass01;
				}
				_ = (Fix)0.5;
				Vec2 vec = ropeBody.segment[num4] - position;
				Fix fix3 = Vec2.Magnitude(vec);
				if (fix3 != Fix.Zero)
				{
					Fix fix4 = ropeBody.segmentSeparation - fix3;
					Vec2 vec2 = vec / fix3;
					ropeBody.segment[num4] += fix4 * vec2 * (Fix.One - fix2);
					position -= fix4 * vec2 * fix2;
				}
			}
			prevPlayerVel = Velocity;
			prevImposedVel = selfImposedVelocity;
			prevExternalVel = externalVelocity;
		}
		else
		{
			position += Velocity * GameTime.FixedDeltaTime(idHolder, SimDeltaTime);
		}
		externalVelocity *= (Fix)0.95;
	}

	public void AttachRope(RopeBody rope, bool topAttachment)
	{
		if (ropeBody != null)
		{
			ropeBody.SetForce(ignoreGravityWhenRoped ? Vec2.zero : (Vec2.down * DetPhysics.Get().ropeGravity), topAttachment);
			ropeBody.SetTimeInAir((Fix)100L, topAttachment);
			if (rope == null)
			{
				ropeBody.Dettach(topAttachment);
			}
			else
			{
				ropeBody.SetMass01((RopePlayerMass01 == Fix.Zero) ? ((Fix)0.5) : RopePlayerMass01, topAttachment, Fix.One);
			}
		}
		prevPlayerVel = Velocity;
		prevImposedVel = selfImposedVelocity;
		prevExternalVel = externalVelocity;
		ropeBody = rope;
		this.topAttachment = topAttachment;
	}

	public void EnterAbilityClearRope()
	{
		prevPlayerVel = Velocity;
		prevImposedVel = selfImposedVelocity;
		prevExternalVel = externalVelocity;
		ropeBody = null;
	}
}
[RequireComponent(typeof(IPhysicsCollider), typeof(PlayerBody))]
public class PlayerCollision : MonoUpdatable, ICollisionCallback
{
	public enum IgnoreColliderInd
	{
		meteor,
		magnet,
		roll,
		combo0,
		combo1,
		combo2
	}

	public GameObject deathEffect;

	private uint isInvulnerableMask;

	public const uint Mask_InInvincibilityZone = 1u;

	public const uint Mask_IsBlocking = 2u;

	public const uint Mask_OnSpawnBuff = 4u;

	private bool wasKilledThisFrame;

	public float deathTrauma = 0.8f;

	public Vec2 platformSquishPointOffset;

	public bool isSquishable = true;

	private IPlayerIdHolder playerIdHolder;

	private PlayerBody body;

	private IAbilityComponent ability;

	private PlayerPhysics physics;

	private IPhysicsCollider hurtBox;

	public ReviveEffect reviveEffectPrefab;

	private int layerMask;

	private RaycastHit2D[] temp = new RaycastHit2D[1];

	private IPhysicsCollider[] ignoredCollider = new IPhysicsCollider[6];

	private int ignoredBeamId = -1;

	public bool IsInvulnerable => isInvulnerableMask != 0;

	public void SetInvulnerable(bool toInvulnerable, uint effectedVulnerabilityMask)
	{
		if (toInvulnerable)
		{
			isInvulnerableMask |= effectedVulnerabilityMask;
		}
		else
		{
			isInvulnerableMask &= ~effectedVulnerabilityMask;
		}
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		wasKilledThisFrame = false;
	}

	public override void LateUpdateSim(Fix SimDeltaTime)
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		playerIdHolder = GetComponent<IPlayerIdHolder>();
		body = GetComponent<PlayerBody>();
		hurtBox = GetComponent<IPhysicsCollider>();
		hurtBox.RegisterCollisionCallback(this);
		ability = GetComponent<IAbilityComponent>();
		physics = GetComponent<PlayerPhysics>();
		layerMask = 1 << LayerMask.NameToLayer("Projectile");
		layerMask += 1 << LayerMask.NameToLayer("Explosion");
		layerMask += 1 << LayerMask.NameToLayer("LethalTerrain");
	}

	public int GetPlayerId()
	{
		return playerIdHolder.GetPlayerId();
	}

	public bool killPlayer(int killerId, bool spawnEffect, bool ignoreInvulnerability = false, CauseOfDeath causeOfDeath = CauseOfDeath.Other)
	{
		if (body.ropeBody != null)
		{
			body.AttachRope(null, body.topAttachment);
		}
		Player player = PlayerHandler.Get().GetPlayer(playerIdHolder.GetPlayerId());
		if ((IsInvulnerable && !ignoreInvulnerability) || !base.gameObject.activeSelf)
		{
			return false;
		}
		if ((player == null && spawnEffect) || (spawnEffect && player.ExtraLife != ReviveStatus.isbeingRevived))
		{
			GameObject obj = FixTransform.InstantiateFixed(deathEffect, body.position);
			obj.transform.localScale *= (float)body.fixtrans.Scale;
			obj.GetComponent<SpriteRenderer>().material = playerIdHolder.GetPlayerMaterial();
		}
		if (ability != null)
		{
			AbilityExitInfo info = new AbilityExitInfo
			{
				position = body.position,
				isDead = true,
				killerId = killerId,
				causeOfDeath = causeOfDeath
			};
			ability.ExitAbility(info);
			return true;
		}
		GameObject.FindGameObjectWithTag("ShakableCamera").GetComponent<ShakableCamera>().AddTrauma(deathTrauma);
		if (player == null)
		{
			Updater.DestroyFix(base.gameObject);
			return true;
		}
		if (player.RespawnPositions.Count > 0)
		{
			physics.UnGround();
			player.ExtraLife = ReviveStatus.isbeingRevived;
			SlimeController component = GetComponent<SlimeController>();
			List<ReviveEffect.SlimeControllerRevival> list = new List<ReviveEffect.SlimeControllerRevival>(player.RespawnPositions.Count);
			for (int i = 0; i < player.RespawnPositions.Count; i++)
			{
				list.Add(new ReviveEffect.SlimeControllerRevival
				{
					sm = SpawnClone(player, component, player.RespawnPositions[i].GetPos()),
					reviveIndicator = player.RespawnPositions[i]
				});
			}
			player.Kill(killerId, Updater.SimulationTicks, causeOfDeath);
			player.RespawnPositions.Clear();
			FixTransform.InstantiateFixed(reviveEffectPrefab, body.position).Init(player, list);
			for (int j = 0; j < component.abilities.Count; j++)
			{
				if (component.abilities[j] != null)
				{
					Updater.DestroyFix(component.abilities[j].gameObject);
				}
			}
			component.abilities.Clear();
			Updater.DestroyFix(component.gameObject);
			AudioManager.Get().Play("reviveOnDeath");
		}
		else if (player.ExtraLife == ReviveStatus.NoRevive || player.ExtraLife == ReviveStatus.isbeingRevived)
		{
			SlimeController component2 = GetComponent<SlimeController>();
			if (player.playersAndClonesStillAlive == 1)
			{
				component2.DropAbilities();
			}
			player.Kill(killerId, Updater.SimulationTicks, causeOfDeath);
			for (int k = 0; k < component2.abilities.Count; k++)
			{
				if (component2.abilities[k] != null && !component2.abilities[k].IsDestroyed)
				{
					Updater.DestroyFix(component2.abilities[k].gameObject);
				}
			}
			component2.abilities.Clear();
			Updater.DestroyFix(base.gameObject);
		}
		else if (player.ExtraLife == ReviveStatus.permanentRevive)
		{
			physics.UnGround();
			player.ExtraLife = ReviveStatus.isbeingRevived;
			SlimeController component3 = GetComponent<SlimeController>();
			component3.PrepareToRevive(player.SpawnPosition);
			component3.ReSpawn(player.SpawnPosition);
		}
		return true;
	}

	public SlimeController SpawnAbilityLessClone(Player player, SlimeController slimeContToRevive, Vec2 targetPosition)
	{
		if (player.playersAndClonesStillAlive < Constants.MaxClones + 1)
		{
			player.playersAndClonesStillAlive++;
			SlimeController slimeController = FixTransform.InstantiateFixed(reviveEffectPrefab.emptyPlayerPrefab, targetPosition);
			slimeController.playerNumber = player.Id;
			slimeController.GetPlayerSprite().sprite = null;
			slimeController.GetPlayerSprite().material = player.Color;
			List<AbilityMonoBehaviour> abilities = new List<AbilityMonoBehaviour>();
			slimeController.abilities = abilities;
			AbilityReadyIndicator[] abilityReadyIndicators = new AbilityReadyIndicator[0];
			slimeController.AbilityReadyIndicators = abilityReadyIndicators;
			slimeController.PrepareToRevive(targetPosition);
			return slimeController;
		}
		return null;
	}

	public SlimeController SpawnClone(Player player, SlimeController slimeContToRevive, Vec2 targetPosition)
	{
		if (player.playersAndClonesStillAlive < Constants.MaxClones + 1)
		{
			player.playersAndClonesStillAlive++;
			SlimeController slimeController = FixTransform.InstantiateFixed(reviveEffectPrefab.emptyPlayerPrefab, targetPosition);
			slimeController.playerNumber = player.Id;
			slimeController.GetPlayerSprite().sprite = null;
			slimeController.GetPlayerSprite().material = player.Color;
			List<AbilityMonoBehaviour> list = new List<AbilityMonoBehaviour>();
			for (int i = 0; i < slimeContToRevive.abilities.Count; i++)
			{
				int index = slimeContToRevive.abilityIcons.IndexOf(slimeContToRevive.AbilityReadyIndicators[i].GetPrimarySprite());
				GameObject gameObject = FixTransform.InstantiateFixed(slimeContToRevive.abilityIcons.sprites[index].associatedGameObject, Vec2.zero);
				gameObject.gameObject.SetActive(value: false);
				list.Add(gameObject.GetComponent<AbilityMonoBehaviour>());
			}
			slimeController.abilities = list;
			AbilityReadyIndicator[] array = new AbilityReadyIndicator[3];
			for (int j = 0; j < slimeContToRevive.AbilityReadyIndicators.Length; j++)
			{
				if (!(slimeContToRevive.AbilityReadyIndicators[j] == null))
				{
					array[j] = UnityEngine.Object.Instantiate(reviveEffectPrefab.AbilityReadyIndicators[j]).GetComponent<AbilityReadyIndicator>();
					array[j].SetSprite(slimeContToRevive.AbilityReadyIndicators[j].GetPrimarySprite());
					array[j].Init();
					array[j].SetColor(reviveEffectPrefab.teamColors.teamColors[player.Team].fill);
					array[j].GetComponent<FollowTransform>().Leader = slimeController.transform;
					array[j].gameObject.SetActive(value: false);
				}
			}
			slimeController.AbilityReadyIndicators = array;
			slimeController.PrepareToRevive(targetPosition);
			return slimeController;
		}
		return null;
	}

	public void IgnoreCollider(IPhysicsCollider collider, IgnoreColliderInd ignoreType)
	{
		ignoredCollider[(int)ignoreType] = collider;
	}

	public void CopyIgnoredColliderFrom(PlayerCollision copyFromMe)
	{
		for (int i = 0; i < ignoredCollider.Length; i++)
		{
			ignoredCollider[i] = copyFromMe.ignoredCollider[i];
		}
	}

	public void IgnoreBeamId(int beamIdToIgnore)
	{
		ignoredBeamId = beamIdToIgnore;
	}

	public bool KillPlayerOnCollision(CollisionInformation collision)
	{
		if (IsInvulnerable)
		{
			return false;
		}
		int playerId = playerIdHolder.GetPlayerId();
		Player player = PlayerHandler.Get().GetPlayer(playerId);
		if ((player != null && !player.IsAlive) || collision.colliderPP.fixTrans == null || collision.colliderPP.fixTrans.IsDestroyed)
		{
			return false;
		}
		bool flag = false;
		for (int i = 0; i < ignoredCollider.Length; i++)
		{
			if (ignoredCollider[i] != null && !ignoredCollider[i].IsDestroyed && ignoredCollider[i].GetPhysicsParent().hierarchyNumber == collision.colliderPP.hierarchyNumber && collision.colliderPP.hierarchyNumber != 0)
			{
				return false;
			}
		}
		if (collision.layer == LayerMask.NameToLayer("wall"))
		{
			StickyRoundedRectangle component = collision.colliderPP.fixTrans.GetComponent<StickyRoundedRectangle>();
			if (isSquishable && component != null && physics != null && physics.IsGrounded() && physics.getAttachedGround() != null && !physics.getAttachedGround().IsDestroyed && !physics.getAttachedGround().GetGroundBody().GetInstanceID()
				.Equals(component.GetGroundBody().GetInstanceID()))
			{
				if (component.pickUpPlayersInsteadOfSquish)
				{
					GetComponent<PlayerPhysics>()?.AttachToGround(component, body.position);
				}
				else if (collision.collider.OverlapPoint(body.position + Vec2.ComplexMul(body.right, platformSquishPointOffset)))
				{
					if (!AchievementHandler.IsAchieved(AchievementHandler.AchievementEnum.GetAKillWithTheEngineAbility))
					{
						RocketEngine componentInChildren = component.transform.GetComponentInChildren<RocketEngine>();
						if (componentInChildren != null && !componentInChildren.IsDestroyed && componentInChildren.IsEngineOn() && componentInChildren.ownerId != player.Id && PlayerHandler.Get().GetPlayer(componentInChildren.ownerId).IsLocalPlayer)
						{
							AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.GetAKillWithTheEngineAbility);
						}
					}
					flag = true;
				}
			}
		}
		bool flag2 = false;
		GameObject gameObject = collision.colliderPP.fixTrans.gameObject;
		if (gameObject.layer == LayerMask.NameToLayer("Projectile") || gameObject.layer == LayerMask.NameToLayer("Explosion") || gameObject.layer == LayerMask.NameToLayer("Player") || gameObject.layer == LayerMask.NameToLayer("LethalTerrain") || gameObject.layer == LayerMask.NameToLayer("orb") || flag)
		{
			if (gameObject.layer == LayerMask.NameToLayer("orb") && !gameObject.GetComponent<Orb>().killsOnContact())
			{
				return false;
			}
			bool flag3 = false;
			int num;
			if (gameObject.layer == LayerMask.NameToLayer("Explosion") || gameObject.layer == LayerMask.NameToLayer("LethalTerrain"))
			{
				Explosion component2 = gameObject.GetComponent<Explosion>();
				if (component2 == null)
				{
					num = gameObject.GetComponent<Hitbox>().GetPlayerId();
					flag3 = true;
				}
				else
				{
					flag2 = component2.CompareTag("beam");
					num = component2.PlayerOwnerId;
					flag3 = component2.canHurtOwner;
					if (ignoredBeamId >= 0 && flag2)
					{
						BeamObject component3 = component2.GetComponent<BeamObject>();
						if (component3 != null && Mathf.Abs(component3.beamId) == ignoredBeamId)
						{
							return false;
						}
					}
				}
				if (player != null && collision.colliderPP.fixTrans.CompareTag("ChainLightning") && ((num == playerId && flag3) || num != playerId))
				{
					AudioManager.Get().Play("lightning");
				}
			}
			else if (gameObject.layer == LayerMask.NameToLayer("Projectile") || gameObject.layer == LayerMask.NameToLayer("orb"))
			{
				Projectile component4 = gameObject.GetComponent<Projectile>();
				if (component4 != null)
				{
					num = component4.GetPlayerId();
					flag3 = component4.canHurtOwner;
					Fix fix = (Fix)2.5;
					bool flag4 = PlayerHandler.Get().GetPlayer(num)?.IsLocalPlayer ?? false;
					if (!AchievementHandler.IsAchieved(AchievementHandler.AchievementEnum.LandALongRangeArrow) && num != playerId && component4.timePassed >= fix && flag4)
					{
						Arrow component5 = component4.GetComponent<Arrow>();
						if (component5 != null && !component5.IsDestroyed)
						{
							AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.LandALongRangeArrow);
						}
					}
				}
				else
				{
					num = gameObject.GetComponent<IPlayerIdHolder>().GetPlayerId();
				}
			}
			else if (gameObject.layer == LayerMask.NameToLayer("Player"))
			{
				Ability component6 = gameObject.GetComponent<Ability>();
				if (component6 == null)
				{
					component6 = gameObject.GetComponentInParent<Ability>();
					if (!(component6 != null) || !component6.KillPlayersOnContact)
					{
						return false;
					}
					num = gameObject.GetComponentInParent<IPlayerIdHolder>().GetPlayerId();
					flag3 = true;
				}
				else
				{
					if (!AchievementHandler.IsAchieved(AchievementHandler.AchievementEnum.Get2KillsWith1UseOfRock))
					{
						BounceBall component7 = gameObject.GetComponent<BounceBall>();
						if (component7 != null && component6.KillPlayersOnContact)
						{
							component7.playersKilledThisUse++;
							if (component7.playersKilledThisUse >= 2 && component7.getPlayer() != null && component7.getPlayer().IsLocalPlayer)
							{
								AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.Get2KillsWith1UseOfRock);
							}
						}
					}
					if (!(component6 != null) || !component6.KillPlayersOnContact)
					{
						return false;
					}
					num = gameObject.GetComponent<IPlayerIdHolder>().GetPlayerId();
					flag3 = true;
				}
			}
			else
			{
				num = Constants.ENVIRONMENTAL_PLAYER_ID;
			}
			if ((num == playerId && flag3) || num != playerId)
			{
				wasKilledThisFrame = true;
				if (flag)
				{
					return killPlayer(num, spawnEffect: true, ignoreInvulnerability: false, CauseOfDeath.Squished);
				}
				if (num == playerId && flag3)
				{
					return killPlayer(num, spawnEffect: true, ignoreInvulnerability: false, CauseOfDeath.Accident);
				}
				if (flag2)
				{
					return killPlayer(num, spawnEffect: true, ignoreInvulnerability: false, CauseOfDeath.Beamed);
				}
				return killPlayer(num, spawnEffect: true);
			}
		}
		return false;
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (!wasKilledThisFrame)
		{
			KillPlayerOnCollision(collision);
		}
	}

	private void OnDrawGizmosSelected()
	{
		if (isSquishable)
		{
			Gizmos.DrawWireSphere(base.transform.position + base.transform.rotation * (Vector3)platformSquishPointOffset, 0.1f);
		}
	}
}
[CreateAssetMenu(fileName = "PlayerColors", menuName = "Dynaslimes/PlayerColors", order = 1)]
public class PlayerColors : ScriptableObject
{
	public PlayerColor[] playerColors;

	public PlayerColor this[int key]
	{
		get
		{
			return playerColors[key];
		}
		set
		{
			playerColors[key] = value;
		}
	}

