}
public class PlayerHandler
{
	private static PlayerHandler instance;

	private List<Player> playerList;

	public void ResetForNextStage()
	{
	}

	public Player GetPlayer(int playerId)
	{
		for (int i = 0; i < playerList.Count; i++)
		{
			if (playerId == playerList[i].Id)
			{
				return playerList[i];
			}
		}
		return null;
	}

	private PlayerHandler()
	{
		playerList = new List<Player>();
	}

	public int NumberOfPlayers()
	{
		if (playerList != null)
		{
			return playerList.Count;
		}
		return 0;
	}

	public void SetPlayerList(List<Player> playerlist)
	{
		playerList = playerlist;
	}

	public static PlayerHandler Get()
	{
		if (instance == null)
		{
			instance = new PlayerHandler();
		}
		return instance;
	}

	public List<Player> PlayerList()
	{
		return playerList;
	}

	public int TeamsLeft()
	{
		int num = 0;
		for (int i = 0; i < playerList.Count; i++)
		{
			if (playerList[i].IsAlive)
			{
				bool flag = false;
				for (int j = i + 1; j < playerList.Count; j++)
				{
					flag |= playerList[j].IsAlive && playerList[j].Team == playerList[i].Team;
				}
				if (!flag)
				{
					num++;
				}
			}
		}
		return num;
	}

	public bool HasAliveTeammate(int playerId)
	{
		bool flag = false;
		Player player = GetPlayer(playerId);
		for (int i = 0; i < playerList.Count; i++)
		{
			flag |= playerList[i].IsAlive && playerList[i].Team == player.Team;
		}
		return flag;
	}

	public int NumberOfTeams()
	{
		int num = 0;
		for (int i = 0; i < playerList.Count; i++)
		{
			bool flag = false;
			for (int j = i + 1; j < playerList.Count; j++)
			{
				flag |= playerList[j].Team == playerList[i].Team;
			}
			if (!flag)
			{
				num++;
			}
		}
		return num;
	}
}
public struct PlayerInfo
{
