public enum Interpolation
{
	None,
	Interpolate,
	Extrapolate
}
[RequireComponent(typeof(IPlayerIdHolder))]
public class PlayerPhysics : MonoUpdatable
{
	private PlayerBody body;

	[SerializeField]
	private Fix maxSpeed = (Fix)19L;

	public Fix jumpStrength = (Fix)30L;

	public Fix accel = (Fix)180L;

	public Fix radius = (Fix)0.76f;

	private bool isGrounded;

	public LayerMask collisionMask = 2048;

	public Fix gravity_accel = (Fix)1.6f;

	public Fix gravity_maxFallSpeed = (Fix)27f;

	public Fix gravity_modifier = (Fix)1f;

	private StickyRoundedRectangle attachedGround;

	private IPlayerIdHolder playerIdHolder;

	[SerializeField]
	private bool ApplyGravity = true;

	[SerializeField]
	private bool SyncRotationToPlatform = true;

	private Fix prevScal = Fix.One;

	[NonSerialized]
	public bool skipNextUpdate;

	public bool cannotBeUngroundedByRopes;

	private Fix IcePlatformSlipperyness01 = (Fix)0.87f;

	private Fix PlatformSlipperyness01 = (Fix)0.5f;

	private int[] phb = new int[10];

	private RaycastHit2D[] blockableTerrainHitBuffer = new RaycastHit2D[20];

	public Fix jumpExtraXStrength = (Fix)0.6f;

	public Fix jumpKeptMomentum = (Fix)0.65f;

	public Fix jumpNormalScaleFactor = Fix.One;

	public Fix extraJumpTeleportMultiplier = (Fix)0.02f;

	[HideInInspector]
	public bool jumpedThisFrame;

	public Fix airAccel = (Fix)10L;

	public Fix inverseMass01 = (Fix)35L;

	public Fix Speed
	{
		get
		{
			return maxSpeed;
		}
		set
		{
			maxSpeed = value;
		}
	}

	public Fix groundedSpeed { get; set; }

	public Fix LocalPlatformPos { get; private set; }

	public event Action<Fix> OnNoLongerGrounded;

	public event Action<RaycastInformation> OnAttachedToGround;

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		groundedSpeed = Fix.Zero;
		body = GetComponent<PlayerBody>();
		playerIdHolder = GetComponent<IPlayerIdHolder>();
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.DrawWireSphere(base.transform.position, (float)radius);
	}

	public void UpdateScale()
	{
		if (prevScal != body.fixtrans.Scale)
		{
			Fix fix = body.fixtrans.Scale / prevScal;
			radius *= fix;
			prevScal = body.fixtrans.Scale;
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (skipNextUpdate)
		{
			skipNextUpdate = false;
			return;
		}
		UpdateScale();
		if (!isGrounded && ApplyGravity)
		{
			AddGravityFactor();
			VelocityBasedRaycasts(attachToGroundIfHit: true, simDeltaTime);
		}
	}

	public PlayerBody GetPlayerBody()
	{
		return body;
	}

	public override void LateUpdateSim(Fix SimDeltaTime)
	{
		if (isGrounded && attachedGround != null && !attachedGround.IsDestroyed)
		{
			body.position = attachedGround.PositionFromLocalPlayerPos(LocalPlatformPos, radius);
			if (SyncRotationToPlatform)
			{
				attachedGround.alignRotation(body);
			}
			if (body.ropeBody != null && body.ropeBody.enabled && body.ropeBody.hookHasArrived)
			{
				RopeBody ropeBody = body.ropeBody;
				int num = ((!body.topAttachment) ? (ropeBody.segmentCount - 1) : 0);
				Vec2 vec = ropeBody.segment[num] - body.position;
				if (!(Vec2.SqrMagnitude(vec) < (Fix)0.07))
				{
					body.externalVelocity += vec * DetPhysics.Get().groundedPlayerRopeStr;
				}
				if (Vec2.Dot(attachedGround.currentNormal(body), body.externalVelocity) > (Fix)30L && !cannotBeUngroundedByRopes)
				{
					UnGround(nullRotation: true, playSoundEffect: false);
				}
				ropeBody.segment[num] = body.position;
			}
		}
		jumpedThisFrame = false;
	}

	public void AlignToGround()
	{
		if (!(attachedGround == null))
		{
			Vec2 position = attachedGround.PositionFromLocalPlayerPos(LocalPlatformPos, radius);
			body.position = position;
			attachedGround.alignRotation(body);
		}
	}

	public void AddGravityFactor()
	{
		Fix fix = (Constants.isSpaceLevel ? (gravity_modifier * (Fix)0.5f) : gravity_modifier);
		body.selfImposedVelocity += Vec2.down * gravity_accel * fix;
		Fix fix2 = gravity_accel * fix / gravity_maxFallSpeed;
		body.selfImposedVelocity += Vec2.down * fix2 * body.selfImposedVelocity.y;
	}

	public bool IsGrounded()
	{
		return isGrounded;
	}

	public void MachoMove(Vec2 inputVector, Fix simDeltaTime, Fix roundedness)
	{
		if (!isGrounded)
		{
			AirealMovement(inputVector.x, GameTime.FixedDeltaTime(playerIdHolder, simDeltaTime));
			VelocityBasedRaycasts(attachToGroundIfHit: true, GameTime.FixedDeltaTime(playerIdHolder, simDeltaTime));
			return;
		}
		Fix fix = maxSpeed;
		Fix value = InputGroundAlignment(Vec2.NormalizedSafe(inputVector));
		Fix fix2 = Vec2.Dot(getAttachedGround().currentNormal(body), inputVector);
		Fix fix3 = ((Fix.Abs(value) >= Constants.GROUNDALIGNMENTDEADZONE || (fix2 <= 0L && Fix.Abs(value) >= (Fix)0.01f)) ? ((Fix)Fix.Sign(value)) : Fix.Zero);
		if (attachedGround != null && fix3 == Fix.Zero)
		{
			if (attachedGround.isIcePlatform)
			{
				groundedSpeed *= IcePlatformSlipperyness01;
			}
			else
			{
				groundedSpeed *= PlatformSlipperyness01;
			}
		}
		else
		{
			groundedSpeed = incrementTowards(groundedSpeed, fix3 * fix, accel, GameTime.FixedDeltaTime(playerIdHolder, simDeltaTime));
		}
		if (attachedGround == null || attachedGround.IsDestroyed || !attachedGround.ThisGameObject().activeSelf)
		{
			UnGround();
			return;
		}
		if (SyncRotationToPlatform)
		{
			attachedGround.alignRotation(body);
		}
		Fix fix4 = attachedGround.externalForceAlongSurface(body);
		LocalPlatformPos = attachedGround.moveAlongSurface(body, radius, (groundedSpeed + fix4) * roundedness, GameTime.FixedDeltaTime(playerIdHolder.GetPlayerId(), simDeltaTime), LocalPlatformPos, ref blockableTerrainHitBuffer);
		DropPlatformTest();
	}

	public void Move(Vec2 inputVector, Fix simDeltaTime, bool moveAlongSurface = true)
	{
		if (!isGrounded)
		{
			AirealMovement(inputVector.x, GameTime.FixedDeltaTime(playerIdHolder, simDeltaTime));
			VelocityBasedRaycasts(attachToGroundIfHit: true, GameTime.FixedDeltaTime(playerIdHolder, simDeltaTime));
			return;
		}
		Fix fix = maxSpeed;
		Fix value = InputGroundAlignment(Vec2.NormalizedSafe(inputVector));
		Fix fix2 = Vec2.Dot(getAttachedGround().currentNormal(body), inputVector);
		Fix fix3 = ((Fix.Abs(value) >= Constants.GROUNDALIGNMENTDEADZONE || (fix2 <= 0L && Fix.Abs(value) >= (Fix)0.01f)) ? ((Fix)Fix.Sign(value)) : Fix.Zero);
		if (attachedGround != null && fix3 == Fix.Zero)
		{
			if (attachedGround.isIcePlatform)
			{
				groundedSpeed *= IcePlatformSlipperyness01;
			}
			else
			{
				groundedSpeed *= PlatformSlipperyness01;
			}
		}
		else
		{
			groundedSpeed = incrementTowards(groundedSpeed, fix3 * fix, accel, GameTime.FixedDeltaTime(playerIdHolder, simDeltaTime));
		}
		if (attachedGround == null || attachedGround.IsDestroyed || !attachedGround.ThisGameObject().activeSelf)
		{
			UnGround();
			return;
		}
		if (SyncRotationToPlatform)
		{
			attachedGround.alignRotation(body);
		}
		Fix fix4 = attachedGround.externalForceAlongSurface(body);
		if (moveAlongSurface)
		{
			LocalPlatformPos = attachedGround.moveAlongSurface(body, radius, groundedSpeed + fix4, GameTime.FixedDeltaTime(playerIdHolder.GetPlayerId(), simDeltaTime), LocalPlatformPos, ref blockableTerrainHitBuffer);
		}
		DropPlatformTest();
	}

	public void DropPlatformTest()
	{
		if (!(attachedGround == null) && !attachedGround.IsDestroyed && attachedGround.ThisGameObject().activeSelf && attachedGround.AmIdropped(playerIdHolder.GetPlayerId(), out var dropForce))
		{
			IAbilityComponent component = GetComponent<IAbilityComponent>();
			Vec2 vec = attachedGround.currentNormal(body);
			UnGround(nullRotation: true, playSoundEffect: false);
			body.selfImposedVelocity += vec * dropForce;
			body.position += body.selfImposedVelocity / (Fix)100L;
			component?.ExitAbility(new AbilityExitInfo
			{
				groundedSpeed = Fix.Zero,
				isGrounded = false,
				selfImposedVelocity = body.selfImposedVelocity,
				position = body.position
			});
		}
	}

	public void MoveAlongCurrentPlatFormSwapIfBlocked(PlayerBody body, Fix radius, Fix groundedSpeed, Fix deltaTime, ref int[] platformHopBuffer)
	{
		Fix remainingMovement = Fix.Zero;
		for (int i = 0; i < platformHopBuffer.Length; i++)
		{
			if (platformHopBuffer[i] == -1)
			{
				platformHopBuffer[i] = attachedGround.gameObject.GetInstanceID();
				break;
			}
		}
		LocalPlatformPos = attachedGround.PlatformHopMove(body, radius, groundedSpeed, deltaTime, LocalPlatformPos, ref blockableTerrainHitBuffer, ref platformHopBuffer, out var blockingPlatform, out remainingMovement);
		if (blockingPlatform != null)
		{
			AttachToGround(blockingPlatform, attachedGround.PositionFromLocalPlayerPos(LocalPlatformPos, radius));
			MoveAlongCurrentPlatFormSwapIfBlocked(body, radius, remainingMovement, deltaTime, ref platformHopBuffer);
		}
	}

	public void MoveAlongCurrentPlatForm(Fix simDeltaTime)
	{
		Fix fix = attachedGround.externalForceAlongSurface(body);
		body.externalVelocity = Vec2.zero;
		LocalPlatformPos = attachedGround.moveAlongSurface(body, radius, Fix.Zero + fix, GameTime.FixedDeltaTime(playerIdHolder.GetPlayerId(), simDeltaTime), LocalPlatformPos, ref blockableTerrainHitBuffer);
	}

	public void Jump()
	{
		jumpedThisFrame = true;
		Vec2 vec = ((!isGrounded) ? Vec2.up : attachedGround.currentNormal(body));
		Vec2 vec2 = new Vec2(vec.x, Fix.Zero);
		Vec2 up = Vec2.up;
		Fix b = (vec.y + Fix.One) / jumpNormalScaleFactor;
		b = Fix.Min(Fix.One, b);
		b = Fix.Max(Fix.Zero, b);
		up *= b;
		up += vec2 * jumpExtraXStrength;
		Vec2 vec3 = new Vec2(vec.y, -vec.x) * groundedSpeed;
		body.selfImposedVelocity = vec3 * jumpKeptMomentum + up * jumpStrength;
		body.position += body.selfImposedVelocity * extraJumpTeleportMultiplier;
		base.transform.position = (Vector3)body.position;
		UnGround();
	}

	public Fix incrementTowards(Fix currentSpeedx, Fix targetSpeed, Fix acc, Fix fixedDeltaTime)
	{
		if (currentSpeedx * targetSpeed < 0L)
		{
			currentSpeedx = Fix.Zero;
		}
		Fix fix = currentSpeedx + fixedDeltaTime * (Fix)Fix.Sign(targetSpeed) * acc;
		if (Fix.Abs(fix) > Fix.Abs(targetSpeed))
		{
			fix = targetSpeed;
		}
		return fix;
	}

	public void UnGround(bool nullRotation = true, bool playSoundEffect = true)
	{
		groundedSpeed = Fix.Zero;
		isGrounded = false;
		if (attachedGround != null)
		{
			Fix fix = (Fix)0.05f;
			body.position += attachedGround.currentNormal(body) * fix;
		}
		Fix rotation = body.rotation;
		if (nullRotation)
		{
			body.rotation = Fix.Zero;
			base.transform.rotation = Quaternion.identity;
		}
		if (this.OnNoLongerGrounded != null)
		{
			this.OnNoLongerGrounded(rotation);
		}
		if (playSoundEffect)
		{
			AudioManager.Get().Play("slimeJump" + playerIdHolder.GetPlayerId());
		}
	}

	public StickyRoundedRectangle getAttachedGround()
	{
		return attachedGround;
	}

	public Fix InputGroundAlignment(Vec2 inputVector)
	{
		Vec2 u = ((attachedGround != null) ? attachedGround.forwardsDirection(body) : Vec2.right);
		return Vec2.Dot(inputVector, u);
	}

	public void AirealMovement(Fix inputHorz, Fix simDeltaTime)
	{
		body.selfImposedVelocity += new Vec2(inputHorz * airAccel, Fix.Zero);
		Fix fix = airAccel / (maxSpeed + airAccel);
		body.selfImposedVelocity += Vec2.left * fix * body.selfImposedVelocity.x;
	}

	public void AddForce(Vec2 force)
	{
		body.externalVelocity += force * inverseMass01;
	}

	public bool CollisionRaycasts(bool attachToGroundIfHit, Vec2 velocity, Fix simDeltaTime)
	{
		Fix fix = Vec2.Magnitude(velocity);
		Fix speed = fix * GameTime.FixedDeltaTime(playerIdHolder, simDeltaTime);
		_ = body.up;
		Vec2 position = body.position;
		Vec2 vec = ((fix == 0L) ? Vec2.zero : (velocity / fix));
		Vec2 vec2 = new Vec2(-vec.y, vec.x);
		Vec2 pos = position + vec * radius;
		Vec2 pos2 = position - vec2 * radius;
		Vec2 pos3 = position + vec2 * radius;
		RaycastInformation raycastInformation = checkForWall(pos, vec, speed);
		if ((bool)raycastInformation)
		{
			if (attachToGroundIfHit)
			{
				CollideWithGround(raycastInformation, raycastInformation.nearPos);
			}
			return true;
		}
		RaycastInformation raycastInformation2 = checkForWall(pos2, vec, speed);
		if ((bool)raycastInformation2)
		{
			if (attachToGroundIfHit)
			{
				CollideWithGround(raycastInformation2, raycastInformation2.nearPos + vec2 * radius);
			}
			return true;
		}
		RaycastInformation raycastInformation3 = checkForWall(pos3, vec, speed);
		if ((bool)raycastInformation3)
		{
			if (attachToGroundIfHit)
			{
				CollideWithGround(raycastInformation3, raycastInformation3.nearPos - vec2 * radius);
			}
			return true;
		}
		return false;
	}

	public Fix accelerateTowards(Fix currentSpeedx, Fix targetSpeed, Fix acc, Fix simDeltaTime)
	{
		Fix fix = GameTime.FixedDeltaTime(playerIdHolder, simDeltaTime);
		Fix fix2 = (Fix)Fix.Sign(targetSpeed - currentSpeedx);
		Fix fix3 = currentSpeedx + fix2 * fix * acc;
		if (targetSpeed == 0L && currentSpeedx * fix3 <= 0L)
		{
			return targetSpeed;
		}
		if (fix2 >= 0L && currentSpeedx <= targetSpeed && fix3 > targetSpeed)
		{
			fix3 = targetSpeed;
		}
		else if (fix2 < 0L && currentSpeedx >= targetSpeed && fix3 < targetSpeed)
		{
			fix3 = targetSpeed;
		}
		return fix3;
	}

	private void CollideWithGround(RaycastInformation collision, Vec2 location)
	{
		AttachToGround(collision.pp.fixTrans.GetComponent<StickyRoundedRectangle>(), location);
		if (this.OnAttachedToGround != null)
		{
			this.OnAttachedToGround(collision);
		}
	}

	public void ApplyOffset(Vec2 offset)
	{
		if (!(offset == Vec2.zero))
		{
			if (attachedGround != null)
			{
				body.position = attachedGround.PositionFromLocalPlayerPos(LocalPlatformPos, radius);
				LocalPlatformPos = attachedGround.LocalPlayerPosFromPos(body.position + offset, radius);
			}
			else
			{
				body.position += offset;
			}
		}
	}

	public void AttachToGround(StickyRoundedRectangle wall, Vec2 location)
	{
		attachedGround = wall;
		isGrounded = true;
		groundedSpeed = Vec2.Cross(body.selfImposedVelocity, attachedGround.currentNormal(body));
		LocalPlatformPos = attachedGround.LocalPlayerPosFromPos(location, radius);
		Vec2 vec = attachedGround.PositionFromLocalPlayerPos(LocalPlatformPos, radius);
		body.position = vec;
		body.selfImposedVelocity = Vec2.zero;
		body.externalVelocity = Vec2.zero;
		body.transform.position = (Vector3)vec;
		attachedGround.alignRotation(body);
	}

	private RaycastInformation checkForWall(Vec2 pos, Vec2 dir, Fix speed)
	{
		RaycastInformation result = DetPhysics.Get().RaycastToClosestRoundedRect(pos, dir, speed);
		_ = (Fix)10L;
		UnityEngine.Debug.DrawLine((Vector3)pos, (Vector3)(pos + speed * dir), UnityEngine.Color.cyan);
		UnityEngine.Debug.DrawLine((Vector3)pos, (Vector3)result.nearPos, UnityEngine.Color.green);
		return result;
	}

	public bool VelocityBasedRaycasts(bool attachToGroundIfHit, Fix simDeltaTime)
	{
		return CollisionRaycasts(attachToGroundIfHit, body.Velocity, simDeltaTime);
	}

	public void SyncPhysicsTo(PlayerInfo playerInfo)
	{
		isGrounded = playerInfo.isGrounded;
		UpdateScale();
		if (isGrounded)
		{
			attachedGround = playerInfo.currentlyAttachedGround;
			isGrounded = true;
			LocalPlatformPos = playerInfo.groundedLocalPosition;
			body.position = attachedGround.PositionFromLocalPlayerPos(LocalPlatformPos, radius);
			base.transform.position = (Vector3)body.position;
			body.selfImposedVelocity = Vec2.zero;
			body.externalVelocity = playerInfo.externalVelocity;
			groundedSpeed = playerInfo.groundedSpeed;
			attachedGround.alignRotation(body);
		}
		else
		{
			body.externalVelocity = playerInfo.externalVelocity;
			body.selfImposedVelocity = playerInfo.selfImposedVelocity;
			body.position = playerInfo.position;
			base.transform.position = (Vector3)playerInfo.position;
			body.rotation = Fix.Zero;
			base.transform.rotation = Quaternion.identity;
			attachedGround = null;
			groundedSpeed = Fix.Zero;
		}
	}

	public void SyncPhysicsTo(AbilityExitInfo exitInfo)
	{
		isGrounded = exitInfo.isGrounded;
		UpdateScale();
		if (isGrounded && exitInfo.currentlyAttachedGround != null && exitInfo.currentlyAttachedGround.rr != null && !exitInfo.currentlyAttachedGround.IsDestroyed)
		{
			groundedSpeed = exitInfo.groundedSpeed;
			attachedGround = exitInfo.currentlyAttachedGround;
			isGrounded = true;
			Vec2 vec = attachedGround.PositionFromLocalPlayerPos(exitInfo.groundedLocalPosition, exitInfo.radius);
			LocalPlatformPos = attachedGround.LocalPlayerPosFromPos(vec, radius);
			body.position = vec;
			body.externalVelocity = exitInfo.externalVelocity;
			body.selfImposedVelocity = Vec2.zero;
			body.transform.position = (Vector3)exitInfo.position;
			attachedGround.alignRotation(body);
		}
		else
		{
			body.externalVelocity = exitInfo.externalVelocity;
			body.selfImposedVelocity = exitInfo.selfImposedVelocity;
			body.position = exitInfo.position;
			body.transform.position = (Vector3)exitInfo.position;
			attachedGround = null;
			groundedSpeed = Fix.Zero;
			body.rotation = Fix.Zero;
			base.transform.rotation = Quaternion.identity;
		}
	}
}
public class PlayerStateMeter : MonoBehaviour
{
	private Text text;

	private SlimeController playerController;

	private void Start()
	{
		text = GetComponent<Text>();
		playerController = (SlimeController)UnityEngine.Object.FindObjectOfType(typeof(SlimeController));
	}

	private void Update()
	{
		if (playerController != null)
		{
			text.text = playerController.getCurrentState().ToString().ToUpper();
		}
	}
}
public class POCHandler : MonoUpdatable
{
	public class TeamSorter : IComparer<Player>
	{
		public int Compare(Player x, Player y)
		{
			if (x.Team == y.Team)
			{
				return x.Id - y.Id;
			}
			return x.Team - y.Team;
		}
	}

	private int localPlayerId;

	private SlimeController[] playerObjects;

	public Material[] colors = new Material[4];

	public List<GameObject> AbilityReadyIndicators;

	public GameObject playerPrefab;

	public NamedSpriteList AbilityIcons;

	public GameObject Level;

	public GameObject abilityRootObject;

	public GameObject RandomAbilityPrefab;

	private Fix delayBeforeLevelSwap = (Fix)3L;

	private Fix timeSinceAllDead = Fix.Zero;

	public static int levelToLoad = 1;

	private bool gameHasStarted;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		Shader.SetGlobalFloat("_Timestop01", 1f);
		string[] commandLineArgs = Environment.GetCommandLineArgs();
		localPlayerId = 1;
		int num = 0;
		for (int i = 0; i < commandLineArgs.Length; i++)
		{
			if (commandLineArgs[i].StartsWith("IP1="))
			{
				commandLineArgs[i].Substring("IP1=".Length);
				num++;
			}
			else if (commandLineArgs[i].StartsWith("IP2="))
			{
				commandLineArgs[i].Substring("IP2=".Length);
				num++;
			}
			else if (commandLineArgs[i].StartsWith("IP3="))
			{
				commandLineArgs[i].Substring("IP3=".Length);
				num++;
			}
			else if (commandLineArgs[i].StartsWith("IP4="))
			{
				commandLineArgs[i].Substring("IP4=".Length);
				num++;
			}
			else if (commandLineArgs[i].StartsWith("PLAYERID="))
			{
				localPlayerId = int.Parse(commandLineArgs[i].Substring("PLAYERID=".Length));
			}
		}
		if (num == 0)
		{
			num = 4;
			localPlayerId = 1;
		}
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int j = 0; j < list.Count; j++)
		{
			list[j].Color = colors[j];
			list[j].playersAndClonesStillAlive = 1;
		}
		PlayerHandler.Get().SetPlayerList(list);
	}

	public override void Init()
	{
		int num = 3;
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int i = 0; i < list.Count; i++)
		{
			list[i].Abilities.Clear();
			for (int j = 0; j < num; j++)
			{
				list[i].Abilities.Add(RandomAbilityPrefab);
			}
		}
		startGame();
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (!gameHasStarted)
		{
			return;
		}
		List<Player> list = PlayerHandler.Get().PlayerList();
		int num = 0;
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].IsAlive)
			{
				num++;
			}
		}
		if (num <= 1)
		{
			timeSinceAllDead += SimDeltaTime;
			if (timeSinceAllDead > delayBeforeLevelSwap)
			{
				Updater.PreLevelLoad();
				SceneManager.LoadScene(levelToLoad + 1, LoadSceneMode.Single);
				Updater.PostLevelLoad();
				int num2 = SceneManager.sceneCountInBuildSettings - 1;
				levelToLoad = (levelToLoad + 1) % num2;
			}
		}
	}

	private void startGame()
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int i = 0; i < list.Count; i++)
		{
			list[i].WonThisRound = false;
			list[i].KillsAtStartOfRound = list[i].Kills;
			list[i].CauseOfDeath = CauseOfDeath.NotDeadYet;
		}
		Spawnplayers(base.gameObject, playerPrefab, abilityRootObject, AbilityReadyIndicators);
		gameHasStarted = true;
	}

	public static List<FixTransform> FindPlayerSpawns(GameObject playerSpawnRoot)
	{
		List<FixTransform> list = new List<FixTransform>();
		FixTransform[] componentsInChildren = playerSpawnRoot.GetComponentsInChildren<FixTransform>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (componentsInChildren[i].CompareTag("PlayerSpawn"))
			{
				list.Add(componentsInChildren[i]);
			}
		}
		return list;
	}

	public static List<SlimeController> Spawnplayers(GameObject playerSpawnsRoot, GameObject playerPrefab, GameObject abilityRootObject, List<GameObject> AbilityReadyIndicators)
	{
		List<FixTransform> list = FindPlayerSpawns(playerSpawnsRoot);
		List<Player> list2 = new List<Player>();
		for (int i = 0; i < PlayerHandler.Get().PlayerList().Count; i++)
		{
			list2.Add(PlayerHandler.Get().PlayerList()[i]);
		}
		list2.Sort(new TeamSorter());
		List<SlimeController> list3 = new List<SlimeController>();
		for (int j = 0; j < list2.Count && j < list.Count; j++)
		{
			GameObject gameObject = FixTransform.InstantiateFixed(playerPrefab, list[j].position);
			gameObject.transform.parent = playerSpawnsRoot.transform;
			list2[j].SpawnPosition = list[j].position;
			SlimeController component = gameObject.GetComponent<SlimeController>();
			int playerId = (component.playerNumber = list2[j].Id);
			component.GetPlayerSprite().material = list2[j].Color;
			List<AbilityMonoBehaviour> list4 = new List<AbilityMonoBehaviour>(3);
			AbilityReadyIndicator[] array = new AbilityReadyIndicator[3];
			List<AbilityMonoBehaviour> list5 = new List<AbilityMonoBehaviour>();
			list2[j].AbilityIcons = new List<Sprite>(3);
			list2[j].AbilityIcons.Add(null);
			list2[j].AbilityIcons.Add(null);
			list2[j].AbilityIcons.Add(null);
			list2[j].CurrentAbilities = new List<GameObject>();
			for (int k = 0; k < list2[j].Abilities.Count; k++)
			{
				RandomAbility component2 = list2[j].Abilities[k].GetComponent<RandomAbility>();
				if (component2 != null)
				{
					NamedSprite randomAbilityPrefab = RandomAbility.GetRandomAbilityPrefab(component2.abilityIcons, component2.abilityIcons_demo);
					list2[j].AbilityIcons[k] = randomAbilityPrefab.sprite;
					GameObject gameObject2 = FixTransform.InstantiateFixed(randomAbilityPrefab.associatedGameObject, Vec2.zero);
					gameObject2.transform.parent = abilityRootObject.transform;
					gameObject2.SetActive(value: false);
					list2[j].CurrentAbilities.Add(gameObject2);
					list5.Add(gameObject2.GetComponent<AbilityMonoBehaviour>());
				}
				else
				{
					GameObject gameObject3 = FixTransform.InstantiateFixed(list2[j].Abilities[k], Vec2.zero);
					gameObject3.transform.parent = abilityRootObject.transform;
					gameObject3.SetActive(value: false);
					list4.Add(gameObject3.GetComponent<AbilityMonoBehaviour>());
					list2[j].CurrentAbilities.Add(list2[j].Abilities[k]);
					list5.Add(list4[k]);
				}
			}
			for (int l = 0; l < array.Length; l++)
			{
				array[l] = UnityEngine.Object.Instantiate(AbilityReadyIndicators[l].GetComponent<AbilityReadyIndicator>(), playerSpawnsRoot.transform);
				array[l].Init();
				array[l].GetComponent<FollowTransform>().Leader = gameObject.transform;
				array[l].gameObject.SetActive(value: false);
				if (l < list2[j].AbilityIcons.Count)
				{
					array[l].SetSprite(list2[j].AbilityIcons[l]);
				}
			}
			component.abilities = list5;
			component.AbilityReadyIndicators = array;
			list3.Add(component);
			PlayerHandler.Get().GetPlayer(playerId).playersAndClonesStillAlive = 1;
		}
		return list3;
	}
}
