	public static NamedSprite GetRandomAbilityPrefab(NamedSpriteList abilityIcons, NamedSpriteList abilityIcons_demo)
	{
		NamedSpriteList obj = (SteamManager.instance.dlc.HasDLC() ? abilityIcons : abilityIcons_demo);
		int count = obj.sprites.Count;
		count -= 2;
		int index = Updater.RandomInt(0, count) + 2;
		return obj.sprites[index];
	}

	public static NamedSprite GetRandomAbilityPrefab(NamedSpriteList abilityIcons, NamedSpriteList abilityIcons_demo, Sprite notAllowedSprite)
	{
		NamedSpriteList obj = ((SteamManager.instance != null && SteamManager.instance.dlc.HasDLC()) ? abilityIcons : abilityIcons_demo);
		int num = obj.IndexOf(notAllowedSprite) - 2;
		if (num <= 0)
		{
			num = 100000;
		}
		int count = obj.sprites.Count;
		count -= 2;
		int num2 = Updater.RandomInt(0, count - 1);
		if (num2 >= num)
		{
			num2 = (num2 + 1) % count;
		}
		num2 += 2;
		return obj.sprites[num2];
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		ability = GetComponent<Ability>();
		fixTrans = GetComponent<FixTransform>();
