[RequireComponent(typeof(StickyRoundedRectangle))]
public class ResizablePlatform : MonoUpdatable
{
	private StickyRoundedRectangle StickyRect;

	private DPhysicsRoundedRect rr;

	private BoplBody body;

	private FixTransform fixTrans;

	private SpriteRenderer spriteRen;

	private AnimateVelocity animVel;

	public AnimationCurveFixed RemoveAnimation;

	public Fix MassPerArea = (Fix)0.05f;

	private ShakablePlatform shakablePlatform;

	private Fix oBevelRadius;

	private Fix oRHeight;

	private Fix oRWidth;

	private bool isBeingRemoved;

	private Fix timePassed;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		StickyRect = GetComponent<StickyRoundedRectangle>();
		rr = GetComponent<DPhysicsRoundedRect>();
		spriteRen = GetComponent<SpriteRenderer>();
		animVel = GetComponent<AnimateVelocity>();
		body = GetComponent<BoplBody>();
		shakablePlatform = GetComponent<ShakablePlatform>();
		fixTrans = GetComponent<FixTransform>();
	}

	public override void Init()
	{
	}

	public void ResizePlatform(Fix rHeight, Fix rWidth, Fix bevelRadius, bool resizeChildren = true)
	{
		body.InverseMass = Fix.One / ((Fix)10L + MassPerArea * StickyRect.rr.PlatformArea(rHeight, rWidth, bevelRadius));
		body.InverseMomentOfInertia = Fix.One / rr.ApproximateMOI(rWidth, rHeight, bevelRadius);
		StickyRect.rr.CalcExtents();
		_ = StickyRect.rr.radius;
		StickyRect.rr.radius = bevelRadius;
		StickyRect.rr.SetExtents(new Vec2(rWidth, rHeight));
		float num = (float)spriteRen.sprite.texture.width / spriteRen.sprite.pixelsPerUnit;
		float num2 = (float)spriteRen.sprite.texture.height / spriteRen.sprite.pixelsPerUnit;
		float a = ((float)bevelRadius * 2f + (float)rWidth * 2f) * num;
		float b = ((float)bevelRadius * 2f + (float)rHeight * 2f) * num2;
		float num3 = Mathf.Max(a, b);
		Vector2 vector = base.transform.localScale;
		base.transform.localScale = new Vector3(num3, num3, 1f);
		fixTrans.startScale = new Vector3(num3 / (float)fixTrans.Scale, num3 / (float)fixTrans.Scale, 1f);
		Fix fix = (rWidth + bevelRadius) / (rHeight + bevelRadius);
		animVel.rotationResistence = Fix.Max(Fix.Max(fix, Fix.One / fix) * (Fix)4.5f - (Fix)4L, Fix.One);
		if (resizeChildren)
		{
			int childCount = base.transform.childCount;
			for (int i = 0; i < childCount; i++)
			{
				GameObject gameObject = base.transform.GetChild(i).gameObject;
				IPlatformAttachable component = gameObject.GetComponent<IPlatformAttachable>();
				if (component != null)
				{
					float num4 = gameObject.transform.localScale.x * vector.x / num3;
					float num5 = gameObject.transform.localScale.y * vector.y / num3;
					gameObject.transform.localScale = new Vector3(num4, num5, 1f);
					IPhysicsCollider component2 = gameObject.GetComponent<IPhysicsCollider>();
					if (component2 != null && !component2.IsDestroyed)
					{
						FixTransform fixTransform = component2.GetPhysicsParent().fixTrans;
						fixTransform.startScale = new Vector3(num4 / (float)fixTransform.Scale, num5 / (float)fixTransform.Scale, 1f);
					}
					component.RepositionOnParent();
				}
			}
		}
		spriteRen.material.SetFloat("_Scale", base.transform.localScale.x);
		spriteRen.material.SetFloat("_BevelRadius", (float)bevelRadius);
		spriteRen.material.SetFloat("_RHeight", (float)rHeight);
		spriteRen.material.SetFloat("_RWidth", (float)rWidth);
		if (shakablePlatform != null && shakablePlatform.Original() != null)
		{
			shakablePlatform.Original().SetFloat("_Scale", base.transform.localScale.x);
			shakablePlatform.Original().SetFloat("_BevelRadius", (float)bevelRadius);
			shakablePlatform.Original().SetFloat("_RHeight", (float)rHeight);
			shakablePlatform.Original().SetFloat("_RWidth", (float)rWidth);
		}
		StickyRect.UpdateBounds();
	}

	public void RemovePlatform()
	{
		isBeingRemoved = true;
		Vec2 vec = StickyRect.rr.CalcExtents();
		oBevelRadius = StickyRect.rr.radius;
		oRHeight = vec.y;
		oRWidth = vec.x;
	}

	public Vec2 RectangleApproximation()
	{
		Vec2 vec = rr.CalcExtents();
		return new Vec2(vec.x + rr.radius, vec.y + rr.radius);
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (isBeingRemoved)
		{
			Fix t = RemoveAnimation.Evaluate(timePassed);
			if (timePassed >= RemoveAnimation.keys[RemoveAnimation.keys.Length - 1].time)
			{
				Updater.DestroyFix(base.gameObject);
				return;
			}
			timePassed += GameTime.FixedTimeStep * GameTime.PlayerTimeScale;
			ResizePlatform(Fix.Lerp((Fix)0.1f, oRHeight, t), Fix.Lerp((Fix)0.1f, oRWidth, t), Fix.Lerp((Fix)0.1f, oBevelRadius, t));
		}
		else
		{
			Vec2 vec = rr.CalcExtents();
			ResizePlatform(vec.y, vec.x, rr.radius);
		}
	}
}
public class ReviveEffect : MonoUpdatable, IPlayerIdHolder
{
	public struct SlimeControllerRevival
	{
		public SlimeController sm;

		public RevivePositionIndicator reviveIndicator;
	}

	[SerializeField]
	private AnimationData animData;

	[SerializeField]
	private ReviveParticle Particle;

	private SpriteAnimator spriteAnim;

	private List<SlimeControllerRevival> playersToRevive;

	private FixTransform fixTrans;

	private Player player;

	public SlimeController emptyPlayerPrefab;

	public GameObject[] AbilityReadyIndicators;

	public TeamColors teamColors;

	public void Init(Player player, List<SlimeControllerRevival> playersToRevive)
	{
		spriteAnim = GetComponent<SpriteAnimator>();
		fixTrans = GetComponent<FixTransform>();
		this.player = player;
		this.playersToRevive = playersToRevive;
		spriteAnim.beginAnimThenDoAction(animData.GetAnimation("wisp"), Shoot);
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
	}

	private void Shoot()
	{
		if (playersToRevive == null || playersToRevive.Count == 0)
		{
			SelfDestruct();
			return;
		}
		for (int i = 0; i < playersToRevive.Count; i++)
		{
			Vec2 vec = Vec2.NormalizedSafe(playersToRevive[i].reviveIndicator.GetPos() - fixTrans.position);
			ReviveParticle reviveParticle = FixTransform.InstantiateFixed(Particle, fixTrans.position);
			if (vec != Vec2.zero)
			{
				reviveParticle.GetComponent<FixTransform>().right = vec;
				fixTrans.right = vec;
			}
			reviveParticle.InitRevive(playersToRevive[i].reviveIndicator, playersToRevive[i].sm, i);
		}
		spriteAnim.beginAnimThenDoAction(animData.GetAnimation("shoot"), SelfDestruct);
	}

	private void SelfDestruct()
	{
		Updater.DestroyFix(base.gameObject);
	}

