	{
	}
}
public class ReviveParticle : MonoUpdatable, IPlayerIdHolder
{
	private RevivePositionIndicator targetIndicator;

	private SlimeController slimeContToRevive;

	private Fix distanceToTravel;

	private Fix distanceTravelled;

	private SpriteAnimator spriteAnim;

	private FixTransform fixTrans;

	[SerializeField]
	private AnimationData spawnEffect;

	[SerializeField]
	private Fix speed;

	private bool hasArrived;

	private int playerCloneId;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
	}

	public int GetPlayerId()
	{
		if (slimeContToRevive == null)
		{
			return 1;
		}
		return slimeContToRevive.GetPlayerId();
	}

	public Material GetPlayerMaterial()
	{
		if (slimeContToRevive == null)
		{
			return null;
		}
		return slimeContToRevive.GetPlayerMaterial();
	}

	public override void Init()
	{
	}

	public void InitRevive(RevivePositionIndicator targetIndicator, SlimeController playerToRevive, int playerCloneId)
	{
		spriteAnim = GetComponent<SpriteAnimator>();
		fixTrans = GetComponent<FixTransform>();
		this.targetIndicator = targetIndicator;
		slimeContToRevive = playerToRevive;
		this.playerCloneId = playerCloneId;
		distanceTravelled = Fix.Zero;
		hasArrived = false;
		distanceToTravel = Vec2.Magnitude(targetIndicator.GetPos() - fixTrans.position);
		Updater.RegisterUpdatable(this);
	}

	public void SetPlayerId(int id)
	{
		throw new NotImplementedException();
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (!(distanceTravelled <= distanceToTravel))
		{
			return;
		}
		Fix fix = SimDeltaTime;
		if (slimeContToRevive != null)
		{
			fix = GameTime.FixedDeltaTime(slimeContToRevive.playerNumber, SimDeltaTime);
		}
		Vec2 pos = targetIndicator.GetPos();
		Vec2 vec = Vec2.NormalizedSafe(pos - fixTrans.position);
		vec *= speed * fix;
		distanceTravelled += Fix.Abs(speed * fix);
		if (distanceTravelled >= distanceToTravel && !hasArrived)
		{
			targetIndicator.End();
			fixTrans.position = pos;
			hasArrived = true;
			speed = Fix.Zero;
			AudioManager.Get().Play("reviveDing");
			spriteAnim.beginAnimThenDoAction(spawnEffect.GetAnimation("spawn"), delegate
			{
				Updater.DestroyFix(base.gameObject);
			});
			if (slimeContToRevive != null)
			{
				slimeContToRevive.ReSpawn(pos);
			}
		}
		else
		{
			fixTrans.position += vec;
		}
	}
}
public class SettingsInitializer : MonoBehaviour
{
