	public static void UpdateQualityLevelBasedOnResolution(float screenHeight)
	{
		if (screenHeight >= 1550f)
		{
			QualitySettings.SetQualityLevel(2);
		}
		else if (screenHeight >= 1000f)
		{
			QualitySettings.SetQualityLevel(1);
		}
		else
		{
			QualitySettings.SetQualityLevel(0);
		}
	}
