[RequireComponent(typeof(StickyRoundedRectangle))]
public class ShakablePlatform : MonoUpdatable
{
	private StickyRoundedRectangle surface;

	private Material originalMaterial;

	private SpriteRenderer spriteRen;

	private SpriteMask spriteMask;

	private DPhysicsRoundedRect rr;

	private Fix overshootMagnitude;

	public Fix basicShakeStr = (Fix)1f;

	private Vec2 originalPosition;

	private Vec2 homePosition;

	private BoplBody body;

	private Fix extraShake = (Fix)1f;

	private int currentShakePriority;

	private Fix t = Fix.Zero;

	private Fix duration = Fix.Zero;

	private Fix shakeAmount = Fix.Zero;

	private AnimationCurveFixed shakeCurve;

	private bool IsInitialized;

	private Vec2 prevRandVector = Vec2.zero;

	public Fix CurrentShakePriority => (Fix)currentShakePriority;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		rr = GetComponent<DPhysicsRoundedRect>();
		surface = GetComponent<StickyRoundedRectangle>();
		spriteRen = GetComponent<SpriteRenderer>();
		originalMaterial = GetComponent<SpriteRenderer>().material;
		spriteMask = GetComponent<SpriteMask>();
		body = GetComponent<BoplBody>();
	}

	public Material Original()
	{
		return originalMaterial;
	}

	public void AddShake(Fix duration, Fix shakeAmount, int shakePriority = 1, Material newMaterialDuringShake = null, AnimationCurveFixed shakeCurve = null)
	{
		this.duration = duration;
		t = Fix.Zero;
		currentShakePriority = shakePriority;
		this.shakeCurve = shakeCurve;
		this.shakeAmount = shakeAmount;
		if (newMaterialDuringShake != null)
		{
			spriteRen.material = newMaterialDuringShake;
		}
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (t < duration)
		{
			t += simDeltaTime * GameTime.PlayerTimeScale;
			if (shakeCurve == null)
			{
				shake(shakeAmount);
			}
			else
			{
				shake(shakeCurve.Evaluate(t) * shakeAmount);
			}
			if (t >= duration)
			{
				currentShakePriority = 0;
				spriteRen.material = originalMaterial;
				t = Fix.Zero;
				duration = Fix.Zero;
				shakeAmount = Fix.Zero;
				shakeCurve = null;
			}
		}
	}

	public void SetHomePosition(Vec2 newHomePosition)
	{
		homePosition = newHomePosition;
	}

	public override void Init()
	{
		if (!IsInitialized)
		{
			originalPosition = body.position;
			homePosition = originalPosition;
			surface = GetComponent<StickyRoundedRectangle>();
			surface?.UpdateBounds();
			currentShakePriority = 0;
			IsInitialized = true;
		}
	}

	private void shake(Fix burningShake)
	{
		Vec2 vec = Updater.RandomInsideUnitCircle() * burningShake;
		body.position = body.position - prevRandVector + vec;
		prevRandVector = vec;
	}
}
