	public void ActivateShockWave(Fix simDeltaTime)
	{
		gameObjectIdsHit.Clear();
		hitCount = DetPhysics.Get().CircleCastAll(fixTrans.position, radius * scale, collisionMask, ref hits);
		for (int i = 0; i < hitCount; i++)
		{
			int instanceId = hits[i].instanceId;
			if (gameObjectIdsHit.Contains(instanceId) || hits[i].fixTrans == null || hits[i].fixTrans.IsDestroyed || hits[i].monobehaviourCollider == null)
			{
				continue;
			}
			if (hits[i].fixTrans.gameObject.layer == LayerMask.NameToLayer("Player"))
			{
				Ability component = hits[i].fixTrans.gameObject.GetComponent<Ability>();
				if (component != null && !component.isPushable)
				{
					continue;
				}
				PlayerPhysics component2 = hits[i].fixTrans.GetComponent<PlayerPhysics>();
				if (component2 == null)
				{
					PlayerBody component3 = hits[i].fixTrans.GetComponent<PlayerBody>();
					Fix fix = Fix.One;
					if (!CallEveryFrame)
					{
						fix = (Fix)7L;
					}
					Fix fix2 = (scale + Fix.One) / (Fix)2L;
					Vec2 vec = hits[i].fixTrans.position - fixTrans.position;
					Fix fix3 = Fix.Max(Vec2.SqrMagnitude(vec) / (Fix)10L, (Fix)3L);
					Fix fix4 = fix2 * defaultForce / (fix3 * fix);
					if (component3 != null)
					{
						component3.AddForce(vec * fix4);
					}
					else
					{
						hits[i].fixTrans.GetComponent<BoplBody>()?.AddForce(vec * fix4 * (Fix)9000L);
					}
				}
				else
				{
					Fix fix5 = Fix.One;
					if (!CallEveryFrame)
					{
						fix5 = (Fix)7L;
					}
					Fix fix6 = (scale + Fix.One) / (Fix)2L;
					Vec2 vec2 = hits[i].fixTrans.position - fixTrans.position;
					Fix fix7 = Fix.Max(Vec2.SqrMagnitude(vec2) / (Fix)10L, (Fix)3L);
					Fix fix8 = fix6 * defaultForce / (fix7 * fix5);
					if (component2.IsGrounded())
					{
						component2.AddForce(groundedPlayerForceMultiplier * vec2 * fix8);
					}
					else
					{
						component2.AddForce(vec2 * fix8);
					}
				}
				continue;
			}
			if (hits[i].fixTrans.gameObject.layer == LayerMask.NameToLayer("LethalTerrain"))
			{
				if (hits[i].fixTrans.GetComponent<IPlatformAttachable>() == null)
				{
					Fix fix9 = Fix.One;
					if (!CallEveryFrame)
					{
						fix9 = (Fix)7L;
					}
					Fix fix10 = (scale + Fix.One) / (Fix)2L;
					Vec2 vec3 = hits[i].fixTrans.position - fixTrans.position;
					Fix fix11 = Fix.Max(Vec2.SqrMagnitude(vec3) / (Fix)10L, (Fix)3L);
					Fix fix12 = fix10 * defaultForce / (fix11 * fix9);
					hits[i].fixTrans.GetComponent<BoplBody>()?.AddForce(vec3 * fix12 * (Fix)9000L);
				}
				continue;
			}
			gameObjectIdsHit.Add(instanceId);
			if (isGustAbility && !AchievementHandler.IsAchieved(AchievementHandler.AchievementEnum.GustAGrenadeIntoAPlayer) && hits[i].fixTrans.gameObject.layer == LayerMask.NameToLayer("item"))
			{
				GrenadeExplode component4 = hits[i].fixTrans.GetComponent<GrenadeExplode>();
				if (component4 != null && !component4.IsDestroyed)
				{
					component4.hasBeenGustedBy = ownerId;
				}
			}
		}
		UpdateHitObjects(simDeltaTime);
	}

	private void UpdateHitObjects(Fix simDeltaTime)
	{
		Fix fix = forceCurve01.Evaluate(timeAlive);
		timeAlive += simDeltaTime;
		if (timeAlive > forceCurve01.Duration())
		{
			Updater.DestroyFix(base.gameObject);
			return;
		}
		for (int i = 0; i < hitCount; i++)
		{
			if (!(hits[i].fixTrans == null) && !hits[i].fixTrans.IsDestroyed && hits[i].monobehaviourCollider != null && gameObjectIdsHit.Contains(hits[i].instanceId) && !extraObjectsToIgnore.Contains(hits[i].instanceId))
			{
				StickyRoundedRectangle component = hits[i].fixTrans.GetComponent<StickyRoundedRectangle>();
				Vec2 vec;
				Vec2 v;
				Fix fix3;
				if (component != null)
				{
					vec = component.GetClosestPoint(fixTrans.position);
					v = -component.currentNormal(vec);
					Fix fix2 = Fix.Max(Vec2.SqrMagnitude(fixTrans.position - vec) / (Fix)10L, (Fix)1.5);
					fix3 = ((!component.CompareTag("boulder")) ? (platformForce / fix2) : (defaultForce / fix2));
				}
				else
				{
					vec = hits[i].fixTrans.position;
					v = vec - fixTrans.position;
					Fix fix2 = Fix.Max(Vec2.SqrMagnitude(v) / (Fix)10L, (Fix)1.5);
					fix3 = defaultForce / fix2;
				}
				fix3 *= scale;
				UnityEngine.Debug.DrawRay((Vector3)vec, Vector3.left, UnityEngine.Color.red);
				UnityEngine.Debug.DrawRay((Vector3)vec, Vector3.up, UnityEngine.Color.red);
				UnityEngine.Debug.DrawRay((Vector3)vec, Vector3.right, UnityEngine.Color.red);
				UnityEngine.Debug.DrawRay((Vector3)vec, Vector3.down, UnityEngine.Color.red);
				if (hits[i].fixTrans.gameObject.layer == LayerMask.NameToLayer("RigidBodyAffector"))
				{
					hits[i].fixTrans.GetComponent<BlackHole>()?.AddForce(Vec2.NormalizedSafe(v) * fix3 * fix);
				}
				else
				{
					hits[i].monobehaviourCollider.AddForceAtPosition(Vec2.NormalizedSafe(v) * fix3 * fix, vec, ForceMode2D.Impulse);
				}
			}
		}
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.DrawWireSphere(base.transform.position, (float)(radius * scale));
	}

	public void SetPlayerId(int id)
	{
		ownerId = id;
	}

	public int GetPlayerId()
	{
		return ownerId;
	}

	public Material GetPlayerMaterial()
	{
		return null;
	}
}
