	private void onEnterAbility()
	{
		isInAbility = true;
		PlayerHandler.Get().GetPlayer(playerNumber).timeSinceEnteredAbility = Fix.Zero;
		wasInvisibileWhenEnteredAbility = PlayerHandler.Get().GetPlayer(playerNumber).isInvisible;
		base.gameObject.SetActive(value: false);
	}

	private void onExitAbility(AbilityExitInfo exitInfo)
	{
		if (base.gameObject == null)
		{
			return;
		}
		base.gameObject.SetActive(value: true);
		PlayerHandler.Get().GetPlayer(playerNumber).timeSinceEnteredAbility = Fix.Zero;
		if (wasInvisibileWhenEnteredAbility && !PlayerHandler.Get().GetPlayer(playerNumber).isInvisible)
		{
			invisibiltyEnded();
		}
		Player player = PlayerHandler.Get().GetPlayer(playerNumber);
		hurtBox.Scale = player.Scale;
		player.InSparkShot = false;
		player.InMachoThrow = false;
		player.InPlatformTransform = false;
		if (exitInfo.ropeAttachment != null)
		{
			body.ropeBody = exitInfo.ropeAttachment;
			body.topAttachment = exitInfo.topAttachment;
		}
		if (exitInfo.isDead)
		{
			body.position = exitInfo.position;
			base.transform.position = (Vector3)exitInfo.position;
			playerCollision.killPlayer(exitInfo.killerId, spawnEffect: false, ignoreInvulnerability: false, exitInfo.causeOfDeath);
			isInAbility = false;
			return;
		}
		if (exitInfo.isFacingRight != flipTrans.facingRight())
		{
			flipTrans.flipFacing();
		}
		playerPhysics.SyncPhysicsTo(exitInfo);
		if (playerPhysics.IsGrounded())
		{
			if (exitInfo.enterTurn)
			{
				EnterStop();
			}
			else
			{
				EnterIdle();
			}
			if (exitInfo.justlanded)
			{
				attachToGround(exitInfo.currentlyAttachedGround);
			}
			if (exitInfo.enterJump)
			{
				Jump();
			}
		}
		else
		{
			EnterFall(exitInfo.lastSprite);
		}
		hurtBox.UpdatePhysicsPositions();
		for (int i = 0; i < abilities.Count; i++)
		{
			if (!(abilities[i] == null) && !abilities[i].IsDestroyed)
			{
				AbilityReadyIndicators[i].gameObject.SetActive(value: true);
				AbilityReadyIndicators[i].InstantlySyncTransform();
			}
		}
		isInAbility = false;
	}

	private void EnterFall(Sprite lastSprite)
	{
		AlignTransformAir();
		body.rotation = Fix.Zero;
		base.transform.rotation = Quaternion.identity;
		currentState = State.fall;
		animationSpeedContainer.UpdateWithBody(body);
		bodyAnimator.beginYSpeedBasedAnimation(animData.GetVelocityMap("fallLeft"), animData.GetAnimation("fallLeftLoop"), lastSprite, animationSpeedContainer);
		playerPhysics.VelocityBasedRaycasts(attachToGroundIfHit: true, Updater.standardFixedDeltaTime);
	}

	public void DropAbilities()
	{
		if (!GameSession.IsInitialized() || GameSessionHandler.HasGameEnded() || abilities.Count <= 0)
		{
			return;
		}
		PlayerHandler.Get().GetPlayer(playerNumber);
		for (int i = 0; i < AbilityReadyIndicators.Length; i++)
		{
			if (AbilityReadyIndicators[i] != null)
			{
				AbilityReadyIndicators[i].InstantlySyncTransform();
			}
		}
		int num = Settings.Get().NumberOfAbilities - 1;
		while (num >= 0 && (num >= AbilityReadyIndicators.Length || AbilityReadyIndicators[num] == null))
		{
			num--;
		}
		if (num < 0)
		{
			return;
		}
		Vec2 launchDirection = Vec2.NormalizedSafe(Vec2.up + new Vec2(Updater.RandomFix((Fix)(-0.3f), (Fix)0.3f), (Fix)0L));
		Sprite primarySprite = AbilityReadyIndicators[num].GetPrimarySprite();
		int num2 = abilityIconsFull.IndexOf(primarySprite);
		if (num2 != -1)
		{
			DynamicAbilityPickup dynamicAbilityPickup = FixTransform.InstantiateFixed(abilityPickupPrefab, body.position);
			NamedSprite namedSprite = abilityIconsFull.sprites[num2];
			if (namedSprite.associatedGameObject == null)
			{
				namedSprite = abilityIconsDemo.sprites[abilityIconsDemo.IndexOf(primarySprite)];
			}
			dynamicAbilityPickup.InitPickup(namedSprite.associatedGameObject, primarySprite, launchDirection);
		}
	}

	public Vec2 GetPos()
	{
		return body.position;
	}

	public void AddAbility(AbilityMonoBehaviour ability, Sprite indicatorSprite, GameObject abilityPrefab = null)
	{
		abilities[nextAbiltityToChangeOnPickup] = ability;
		AbilityReadyIndicators[nextAbiltityToChangeOnPickup].SetSprite(indicatorSprite);
		AbilityReadyIndicators[nextAbiltityToChangeOnPickup].ResetAnimation();
		abilityCooldownTimers[nextAbiltityToChangeOnPickup] = (Fix)100000L;
		if (abilityPrefab != null && (bool)abilityPrefab)
		{
			PlayerHandler.Get().GetPlayer(playerNumber).Abilities[nextAbiltityToChangeOnPickup] = abilityPrefab;
			PlayerHandler.Get().GetPlayer(playerNumber).AbilityIcons[nextAbiltityToChangeOnPickup] = indicatorSprite;
		}
		nextAbiltityToChangeOnPickup = (nextAbiltityToChangeOnPickup + 1) % abilities.Count;
		AudioManager.Get().Play("abilityPickup");
	}

	public void AddAdditionalAbility(AbilityMonoBehaviour ability, Sprite indicatorSprite, GameObject abilityPrefab)
	{
		if (abilities.Count == 3)
		{
			abilities[2] = ability;
			PlayerHandler.Get().GetPlayer(playerNumber).CurrentAbilities[2] = abilityPrefab;
			AbilityReadyIndicators[2].SetSprite(indicatorSprite);
			AbilityReadyIndicators[2].ResetAnimation();
			abilityCooldownTimers[2] = (Fix)100000L;
		}
		else if (abilities.Count > 0 && AbilityReadyIndicators[0] != null)
		{
			abilities.Add(ability);
			PlayerHandler.Get().GetPlayer(playerNumber).CurrentAbilities.Add(abilityPrefab);
			int num = abilities.Count - 1;
			if (num >= AbilityReadyIndicators.Length || AbilityReadyIndicators[num] == null)
			{
				GameObject original = playerCollision.reviveEffectPrefab.AbilityReadyIndicators[num];
				Player player = PlayerHandler.Get().GetPlayer(playerNumber);
				AbilityReadyIndicator[] array = new AbilityReadyIndicator[abilities.Count];
				for (int i = 0; i < num; i++)
				{
					array[i] = AbilityReadyIndicators[i];
				}
				AbilityReadyIndicators = array;
				AbilityReadyIndicators[num] = UnityEngine.Object.Instantiate(original).GetComponent<AbilityReadyIndicator>();
				AbilityReadyIndicators[num].SetSprite(indicatorSprite);
				AbilityReadyIndicators[num].Init();
				AbilityReadyIndicators[num].SetColor(playerCollision.reviveEffectPrefab.teamColors.teamColors[player.Team].fill);
				AbilityReadyIndicators[num].GetComponent<FollowTransform>().Leader = base.transform;
			}
			AbilityReadyIndicators[num].SetSprite(indicatorSprite);
			AbilityReadyIndicators[num].ResetAnimation();
			abilityCooldownTimers[num] = (Fix)100000L;
			for (int j = 0; j < abilities.Count; j++)
			{
				if (abilities[j] == null || abilities[j].IsDestroyed)
				{
					return;
				}
				AbilityReadyIndicators[j].gameObject.SetActive(value: true);
				AbilityReadyIndicators[j].InstantlySyncTransform();
			}
		}
		else
		{
			GameObject gameObject = FixTransform.InstantiateFixed(abilityPrefab, Vec2.zero);
			gameObject.gameObject.SetActive(value: false);
			abilities = new List<AbilityMonoBehaviour>();
			abilities.Add(gameObject.GetComponent<AbilityMonoBehaviour>());
			AbilityReadyIndicator[] array2 = new AbilityReadyIndicator[1];
			GameObject original2 = playerCollision.reviveEffectPrefab.AbilityReadyIndicators[0];
			Player player2 = PlayerHandler.Get().GetPlayer(playerNumber);
			array2[0] = UnityEngine.Object.Instantiate(original2).GetComponent<AbilityReadyIndicator>();
			array2[0].SetSprite(indicatorSprite);
			array2[0].Init();
			array2[0].SetColor(playerCollision.reviveEffectPrefab.teamColors.teamColors[player2.Team].fill);
			array2[0].GetComponent<FollowTransform>().Leader = base.transform;
			array2[0].gameObject.SetActive(value: true);
			array2[0].InstantlySyncTransform();
			abilityCooldownTimers[0] = (Fix)100L;
			AbilityReadyIndicators = array2;
		}
		AudioManager.Get().Play("abilityPickup");
	}

	public PlayerCollision GetPlayerCollision()
	{
		return playerCollision;
	}

	public PlayerCollision GetActivePlayerCollision()
	{
		if (!base.IsDestroyed && base.gameObject.activeInHierarchy)
		{
			return this.playerCollision;
		}
		for (int i = 0; i < abilities.Count; i++)
		{
			if (abilities[i] != null && !abilities[i].IsDestroyed && abilities[i].gameObject.activeInHierarchy)
			{
				PlayerCollision playerCollision = abilities[i].GetPlayerCollision();
				if (playerCollision != null && !playerCollision.IsDestroyed)
				{
					return playerCollision;
				}
			}
		}
		return null;
	}

	private void StartFallLoop()
	{
		bodyAnimator.beginAnimation(animData.GetAnimation("fallLeftLoop"));
	}

	private void LateUpdate()
	{
		Player player = PlayerHandler.Get().GetPlayer(playerNumber);
		if (player == null)
		{
			return;
		}
		Invisibility.SetAlphaBasedOnPlayerInvisibiltyTime(player, spriteRen);
		for (int i = 0; i < AbilityReadyIndicators.Length && i < abilities.Count; i++)
		{
			Invisibility.SetAlphaBasedOnPlayerInvisibiltyTime(player, AbilityReadyIndicators[i].GetSpriteRen());
			UnityEngine.Color color = AbilityReadyIndicators[i].GetSpriteRen().color;
			float num = (float)uncastableAbilityIndicatorAlpha;
			if (color.a > num && !isAbilityCastable(i))
			{
				color.a = num;
				AbilityReadyIndicators[i].GetSpriteRen().color = color;
			}
		}
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		body = GetComponent<PlayerBody>();
		animationSpeedContainer = new SpeedContainer();
		animationSpeedContainer.UpdateWithBody(body);
		playerPhysics = GetComponent<PlayerPhysics>();
		hurtBox = GetComponent<IPhysicsCollider>();
		hurtBox.RegisterCollisionCallback(this);
		playerPhysics.OnAttachedToGround += attachToGround;
		playerPhysics.OnNoLongerGrounded += OnNoLongerGrounded;
		SpriteRenderer[] componentsInChildren = GetComponentsInChildren<SpriteRenderer>();
		foreach (SpriteRenderer spriteRenderer in componentsInChildren)
		{
			if (spriteRenderer.CompareTag("PlayerSprite"))
			{
				spriteRen = spriteRenderer;
				break;
			}
		}
		bodyAnimator = GetComponentInChildren<SpriteAnimator>();
		playerCollision = GetComponent<PlayerCollision>();
		flipTrans = GetComponentInChildren<FlippingTransform>();
		currentState = State.fall;
		suppressInput = true;
		if (abilities == null)
		{
			abilities = new List<AbilityMonoBehaviour>(0);
		}
		for (int j = 0; j < AbilityReadyIndicators.Length; j++)
		{
			if (AbilityReadyIndicators[j].GetSpriteRen() == null)
			{
				AbilityReadyIndicators[j].Init();
			}
		}
		body.simulated = false;
	}

	public override void Init()
	{
		nextAbiltityToChangeOnPickup = 0;
		abilityCooldownTimers = new Fix[3];
		for (int i = 0; i < abilityCooldownTimers.Length; i++)
		{
			abilityCooldownTimers[i] = (Fix)(-1.5f);
		}
		if (!isAbilitylessClone)
		{
			BeforeSpawnInit();
		}
	}

	private void BeforeSpawnInit()
	{
		playerPhysics.enabled = false;
		suppressInput = true;
		body.simulated = false;
		body.selfImposedVelocity = Vec2.zero;
		body.externalVelocity = Vec2.zero;
		_ = playerPhysics.Speed;
		if (currentState != State.nothing)
		{
			hurtBox.enabled = true;
			bodyAnimator.beginAnimThenDoAction(animData.GetAnimation("spawn"), Spawn);
		}
		if (TutorialGameHandler.isInTutorial)
		{
			hurtBox.enabled = false;
		}
	}

	public void PopIntoAir(Vec2 dir)
	{
		body.selfImposedVelocity = dir * (Fix)1.3 * playerPhysics.jumpStrength;
	}

	public Vec2 CurrentNormal()
	{
		if (playerPhysics.IsGrounded())
		{
			return playerPhysics.getAttachedGround().currentNormal(body);
		}
		return Vec2.up;
	}

	public void Spawn()
	{
		playerPhysics.enabled = true;
		body.simulated = true;
		hurtBox.enabled = true;
		playerPhysics.UnGround();
		body.selfImposedVelocity = Vec2.up * playerPhysics.jumpStrength * (Fix)0.25f;
		suppressInput = false;
		hasSpawned = true;
		playerCollision.SetInvulnerable(toInvulnerable: false, 4u);
		Player player = PlayerHandler.Get().GetPlayer(playerNumber);
		player.ExtraLife = ReviveStatus.NoRevive;
		player.InSparkShot = false;
		player.InMachoThrow = false;
		player.InPlatformTransform = false;
		for (int i = 0; i < abilities.Count; i++)
		{
			AbilityReadyIndicators[i].gameObject.SetActive(value: true);
		}
	}

	public void ReSpawn(Vec2 respawnLocation)
	{
		hurtBox.enabled = false;
		body.simulated = true;
		spriteRen.enabled = true;
		body.externalVelocity = Vec2.zero;
		body.selfImposedVelocity = Vec2.zero;
		body.position = respawnLocation;
		currentState = State.fall;
		PlayerHandler.Get().GetPlayer(playerNumber).ExtraLife = ReviveStatus.NoRevive;
		playerCollision.SetInvulnerable(toInvulnerable: false, 4u);
		BeforeSpawnInit();
	}

	public void PrepareToRevive(Vec2 respawnLocation)
	{
		Player player = PlayerHandler.Get().GetPlayer(playerNumber);
		player.ExtraLife = ReviveStatus.isbeingRevived;
		hurtBox.enabled = false;
		playerCollision.SetInvulnerable(toInvulnerable: true, 4u);
		playerPhysics.UnGround();
		currentState = State.nothing;
		body.rotation = Fix.Zero;
		body.externalVelocity = Vec2.zero;
		body.selfImposedVelocity = Vec2.zero;
		body.position = respawnLocation;
		hasSpawned = false;
		playerPhysics.enabled = false;
		body.simulated = false;
		suppressInput = true;
		spriteRen.enabled = false;
		for (int i = 0; i < abilities.Count; i++)
		{
			Revive component = abilities[i].GetComponent<Revive>();
			if (component != null && player.ReviveInstance != null && component.GetInstanceID() == player.ReviveInstance.GetInstanceID())
			{
				abilityCooldownTimers[i] = Fix.Zero;
				break;
			}
		}
		for (int j = 0; j < abilities.Count; j++)
		{
			AbilityReadyIndicators[j].gameObject.SetActive(value: false);
		}
	}

	private void EnterAbility(int abilityIndex, bool useRopeOnOtherPlayer)
	{
		playerAbilityInfoPackage = default(PlayerInfo);
		playerAbilityInfoPackage.playerToUseRopeOn = ropeCastBuffer;
		playerAbilityInfoPackage.useRopeOnOtherPlayer = useRopeOnOtherPlayer;
		playerAbilityInfoPackage.AbilityButtonUsedIndex012 = abilityIndex;
		playerAbilityInfoPackage.groundedSpeed = playerPhysics.groundedSpeed;
		playerAbilityInfoPackage.isGrounded = playerPhysics.IsGrounded();
		playerAbilityInfoPackage.playerId = playerNumber;
		playerAbilityInfoPackage.playerMaterial = GetPlayerMaterial();
		playerAbilityInfoPackage.position = body.position;
		playerAbilityInfoPackage.EntrySprite = spriteRen.sprite;
		playerAbilityInfoPackage.radius = playerPhysics.radius;
		playerAbilityInfoPackage.forwardsVector = (playerPhysics.IsGrounded() ? playerPhysics.getAttachedGround().forwardsDirection(body) : (Vec2.right * (isFacingRight() ? ((Fix)1L) : ((Fix)(-1L)))));
		playerAbilityInfoPackage.slimeController = this;
		playerAbilityInfoPackage.externalVelocity = body.externalVelocity;
		playerAbilityInfoPackage.selfImposedVelocity = (playerPhysics.IsGrounded() ? (playerPhysics.groundedSpeed * playerAbilityInfoPackage.forwardsVector) : body.selfImposedVelocity);
		playerAbilityInfoPackage.ropeBody = body.ropeBody;
		playerAbilityInfoPackage.topAttachment = body.topAttachment;
		if (!abilities[abilityIndex].IsInstant())
		{
			body.EnterAbilityClearRope();
		}
		playerAbilityInfoPackage.upVector = (playerPhysics.IsGrounded() ? Vec2.Normalized(playerPhysics.getAttachedGround().currentNormal(body)) : Vec2.up);
		if (!isFacingRight())
		{
			playerAbilityInfoPackage.forwardsVector *= -Fix.One;
		}
		playerAbilityInfoPackage.rotation = body.rotation;
		playerAbilityInfoPackage.isFacingRight = isFacingRight();
		playerAbilityInfoPackage.currentlyAttachedGround = playerPhysics.getAttachedGround();
		if (playerPhysics.IsGrounded())
		{
			playerAbilityInfoPackage.groundedLocalPosition = playerPhysics.LocalPlatformPos;
		}
		if (abilities[abilityIndex] == null || abilities[abilityIndex].IsDestroyed)
		{
			abilityCooldownTimers[abilityIndex] = Fix.Zero;
			return;
		}
		Player player = PlayerHandler.Get().GetPlayer(playerNumber);
		player.InSparkShot = false;
		player.InMachoThrow = false;
		player.InPlatformTransform = false;
		if (!abilities[abilityIndex].IsInstant())
		{
			onEnterAbility();
		}
		abilities[abilityIndex].EnterAbility(playerAbilityInfoPackage, onExitAbility);
		abilityCooldownTimers[abilityIndex] = Fix.Zero;
	}

	private void Update()
	{
		if (Updater.SimulationTicks > 2 && playReelInSoundOnFrame + 1 == Updater.SimulationTicks)
		{
			AudioManager.Get().PlayOrContinueLoop("reelInLoop");
		}
	}

	private void OldUpdate(Fix simDeltaTime)
	{
		Player player = PlayerHandler.Get().GetPlayer(playerNumber);
		if (player == null)
		{
			return;
		}
		player?.SetPosition(body.position, this);
		if (currentState == State.nothing)
		{
			return;
		}
		bool flag = false;
		if (!isInAbility)
		{
			for (int i = 0; i < abilities.Count; i++)
			{
				if (abilities[i] == null || abilities[i].IsDestroyed)
				{
					continue;
				}
				bool num = abilityCooldownTimers[i] >= abilities[i].GetCooldown();
				if (!GameTime.IsTimeStopped() || !abilities[i].CooldownStoppedDuringTimeStop)
				{
					abilityCooldownTimers[i] += GameTime.FixedDeltaTime(playerNumber, simDeltaTime);
				}
				bool flag2 = abilityCooldownTimers[i] >= abilities[i].GetCooldown();
				if (!num && flag2 && i < AbilityReadyIndicators.Length)
				{
					AbilityReadyIndicators[i].ResetAnimation();
				}
				if (abilities[i].IsRope)
				{
					if (DetPhysics.Get().CircleCastClosestPlayers(body.position, RopeCircleCastRadius, (Fix)1.5, base.gameObject.GetInstanceID(), ref ropeCastBuffer))
					{
						flag = true;
					}
					abilities[i].UpdateCooldowns(body);
				}
				if (i >= AbilityReadyIndicators.Length)
				{
					continue;
				}
				bool flag3 = abilities[i].GetCooldown() == Fix.Zero;
				if (flag3)
				{
					abilityCooldownTimers[i] = (Fix)0.01;
				}
				if (abilities[i].IsRope)
				{
					if (flag3)
					{
						AbilityReadyIndicators[i].UpdateOverriden(ReelinRopeIcon, shouldOverride: true);
						if (player.AbilityButtonIsDown(i) && isAbilityReady(i) && isAbilityCastable(i) && !suppressInput)
						{
							playReelInSoundOnFrame = Updater.SimulationTicks;
						}
						else
						{
							playReelInSoundOnFrame = -1;
						}
					}
					else
					{
						AbilityReadyIndicators[i].UpdateOverriden(CloseToPlayerRopeIcon, flag);
					}
				}
				else
				{
					AbilityReadyIndicators[i].UpdateOverriden(CloseToPlayerRopeIcon, shouldOverride: false);
				}
			}
			for (int j = 0; j < abilities.Count && j < AbilityReadyIndicators.Length; j++)
			{
				if (!(abilities[j] == null) && !abilities[j].IsDestroyed)
				{
					AbilityReadyIndicators[j].SetCooldownProgress((float)abilityCooldownTimers[j] / (float)abilities[j].GetCooldown());
				}
			}
		}
		if (currentState == State.biting || currentState == State.ragdoll)
		{
			return;
		}
		inputVector = player.InputVector();
		_ = inputVector;
		_ = inputVector;
		Fix fix = playerPhysics.InputGroundAlignment(Vec2.NormalizedSafe(inputVector));
		bool flag4 = player.jumpButton_PressedThisFrame();
		Fix fix2 = Vec2.Dot(playerPhysics.IsGrounded() ? playerPhysics.getAttachedGround().currentNormal(body) : Vec2.up, inputVector);
		bool flag5 = Vec2.Magnitude(inputVector) >= Constants.DEADZONE && (Fix.Abs(fix) >= Constants.GROUNDALIGNMENTDEADZONE || (fix2 < 0L && Fix.Abs(fix) >= (Fix)0.01f));
		if (flag5)
		{
			UnityEngine.Debug.DrawRay(base.transform.position, (Vector3)player.InputVector() * 10f, UnityEngine.Color.white);
		}
		else
		{
			UnityEngine.Debug.DrawRay(base.transform.position, (Vector3)player.InputVector() * 10f, UnityEngine.Color.black);
		}
		if (suppressInput)
		{
			flag5 = false;
			flag4 = false;
			_ = Fix.Zero;
			_ = Fix.Zero;
			inputVector = Vec2.zero;
			fix = Fix.Zero;
		}
		for (int k = 0; k < abilities.Count; k++)
		{
			if (abilities[k].IgnoreNextCooldown && !player.AbilityButtonIsDown(k))
			{
				abilityCooldownTimers[k] = abilities[k].GetCooldown();
			}
			if (player.AbilityButtonIsDown(k) && isAbilityReady(k) && isAbilityCastable(k) && !suppressInput)
			{
				EnterAbility(k, flag);
				return;
			}
		}
		switch (currentState)
		{
		case State.land:
			if (Fix.Abs(fix) >= Constants.GROUNDALIGNMENTDEADZONE || fix2 < 0L)
			{
				flipTrans.alignTransform(fix >= 0L);
			}
			break;
		case State.stop:
			if (flag5 && flipTrans.facingRight() != fix >= 0L)
			{
				EnterTurn(fix);
			}
			break;
		case State.turn:
			if (!flag5)
			{
				EnterStop();
			}
			break;
		case State.idle:
			if (flag5)
			{
				EnterRun(fix);
			}
			break;
		case State.run:
			if (!flag5 || Fix.Sign(fix * prevInput) < 0)
			{
				EnterStop();
			}
			break;
		}
		if (playerPhysics.IsGrounded() && flag4)
		{
			Jump();
			bodyAnimator.UpdateAnimations();
		}
		for (int l = 0; l < AbilityReadyIndicators.Length && l < abilities.Count; l++)
		{
			if (!(AbilityReadyIndicators[l].GetSpriteRen() == null))
			{
				UnityEngine.Color color = AbilityReadyIndicators[l].GetSpriteRen().color;
				if (isAbilityCastable(l))
				{
					color.a = 1f;
				}
				else
				{
					color.a = (float)uncastableAbilityIndicatorAlpha;
				}
				AbilityReadyIndicators[l].GetSpriteRen().color = color;
			}
		}
		prevInput = fix;
		if (!playerPhysics.IsGrounded())
		{
			AlignTransformAir();
		}
	}

	private void Jump()
	{
		bool flag = playerPhysics.getAttachedGround().currentNormal(body).y < 0L;
		wasUpsideDown = flag;
		playerPhysics.Jump();
	}

	private void EnterStop()
	{
		currentState = State.stop;
		bodyAnimator.beginAnimThenDoAction(animData.GetAnimation("stop"), delegate
		{
			EnterIdle();
		});
	}

	private void EnterTurn(Fix relativeInput)
	{
		currentState = State.turn;
		flipTrans.alignTransform(relativeInput >= 0L);
		bodyAnimator.beginAnimThenDoAction(animData.GetAnimation("runTurnAround"), delegate
		{
			EnterRun(relativeInput);
		});
	}

	private void EnterRun(Fix relativeInput)
	{
		currentState = State.run;
		flipTrans.alignTransform(relativeInput >= 0L);
		bodyAnimator.beginAnimation(animData.GetAnimation("run"));
		AudioManager.Get().Play("slimeWalk" + playerNumber);
	}

	private void EnterIdle()
	{
		currentState = State.idle;
		bodyAnimator.beginAnimation(animData.GetAnimation("idle"));
	}

	private bool isAbilityReady(int abilityIndex)
	{
		return abilityCooldownTimers[abilityIndex] > abilities[abilityIndex].GetCooldown();
	}

	private bool isAbilityCastable(int abilityIndex)
	{
		if ((!abilities[abilityIndex].OnlyCastableOnGround || (abilities[abilityIndex].OnlyCastableOnGround && playerPhysics.IsGrounded())) && PlayerHandler.Get().GetPlayer(playerNumber).CanUseAbilities)
		{
			return abilities[abilityIndex].IsCastable(PlayerHandler.Get().GetPlayer(playerNumber));
		}
		return false;
	}

	public bool isFacingRight()
	{
		return flipTrans.facingRight();
	}

	private void OnNoLongerGrounded(Fix prevRotation)
	{
		currentState = State.fall;
		spriteRen.flipX = true;
		animationSpeedContainer.UpdateWithBody(body);
		if (body.simulated)
		{
			bodyAnimator.beginYSpeedBasedAnimation(animData.GetVelocityMap("fallLeft"), animData.GetAnimation("fallLeftLoop"), spriteRen.sprite, animationSpeedContainer);
		}
	}

	private void AlignTransformAir()
	{
		if (wasUpsideDown)
		{
			flipTrans.flipFacing();
			wasUpsideDown = false;
		}
		if (inputVector.x < -Constants.MIN_TURNSPEED)
		{
			flipTrans.alignTransform(facingRight: false);
		}
		else if (inputVector.x > Constants.MIN_TURNSPEED)
		{
			flipTrans.alignTransform(facingRight: true);
		}
	}

	private void invisibiltyEnded()
	{
		Fix fix = Fix.MaxValue;
		Invisibility invisibility = null;
		int num = -1;
		for (int i = 0; i < abilities.Count; i++)
		{
			if (abilities[i].IsInstant())
			{
				Invisibility component = abilities[i].GetComponent<Invisibility>();
				if (component != null && abilityCooldownTimers[i] < fix)
				{
					fix = abilityCooldownTimers[i];
					invisibility = component;
					num = i;
				}
				if (component != null && abilities[i].GetCooldown() == (Fix)10000L)
				{
					component.OnInvisibiltyEnded();
				}
			}
		}
		if (invisibility != null)
		{
			abilityCooldownTimers[num] = Fix.Zero;
		}
	}

	public void ApplyRagDoll(Fix ragdollDuration, Vec2 speed, bool goFast, bool resetAnimation = true, MagnetGun magnet = null)
	{
		if (resetAnimation)
		{
			if (goFast)
			{
				bodyAnimator.beginAnimation(animData.GetAnimation("ragdollFast"));
			}
			else
			{
				bodyAnimator.beginAnimation(animData.GetAnimation("ragdollSlow"));
			}
		}
		currentState = State.ragdoll;
		ragDollSpeed = speed;
		ragDollSpeed.x /= (Fix)3L / (Fix)2L;
		this.ragdollDuration = ragdollDuration;
		timeInRagdoll = Fix.Zero;
		body.selfImposedVelocity = ragDollSpeed;
		Vec2 vec = Vec2.NormalizedSafe(speed);
		if (vec != Vec2.zero)
		{
			body.fixtrans.right = vec;
		}
	}

	public void MagnetSteal(MagnetGun magnet)
	{
		if (magnetHolder != null && !magnetHolder.IsDestroyed)
		{
			magnetHolder.OnItemWasStolen();
		}
		magnetHolder = magnet;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		Player player = PlayerHandler.Get().GetPlayer(playerNumber);
		if (currentState == State.ragdoll)
		{
			timeInRagdoll += GameTime.FixedDeltaTime(GetPlayerId(), simDeltaTime);
		}
		if (currentState == State.ragdoll && timeInRagdoll > ragdollDuration)
		{
			magnetHolder = null;
			body.externalVelocity += body.selfImposedVelocity;
			body.selfImposedVelocity = Vec2.zero;
			EnterFall(spriteRen.sprite);
		}
		if (playerPhysics.IsGrounded() && (playerPhysics.getAttachedGround() == null || playerPhysics.getAttachedGround().IsDestroyed))
		{
			body.rotation = Fix.Zero;
			playerPhysics.UnGround(nullRotation: false);
		}
		OldUpdate(simDeltaTime);
		if (swallowing && !GameTime.IsTimeStoppedFor(playerNumber))
		{
			PlayerHandler.Get().GetPlayer(playerNumber).Scale += scaleIncreaseOnNom;
		}
		if (!player.isInvisible && wasInvisible)
		{
			invisibiltyEnded();
		}
		wasInvisible = player.isInvisible;
		hurtBox.Scale = player.Scale;
		if (currentState == State.nothing || currentState == State.biting || currentState == State.ragdoll || !hasSpawned)
		{
			return;
		}
		playerPhysics.Move(inputVector, simDeltaTime);
		if (!playerPhysics.IsGrounded() && body.ropeBody != null && body.ropeBody.enabled)
		{
			body.extraSwingForce = new Vec2(inputVector.x * extraSwingForce, Fix.Zero);
		}
		if (!AchievementHandler.IsAchieved(AchievementHandler.AchievementEnum.MoonwalkLikeABoss) && currentState == State.run)
		{
			bool flag = playerPhysics.groundedSpeed > 0L;
			bool flag2 = isFacingRight();
			if ((!flag && flag2) || (flag && !flag2))
			{
				timeSpentMoonwalking += simDeltaTime;
				if (timeSpentMoonwalking > (Fix)3L && player.IsLocalPlayer)
				{
					AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.MoonwalkLikeABoss);
				}
			}
			else
			{
				timeSpentMoonwalking = Fix.Zero;
			}
		}
		animationSpeedContainer.UpdateWithBody(body);
	}

	private void setStateToIdle()
	{
		currentState = State.idle;
	}

	private void attachToGround(RaycastInformation collision)
	{
		if (hurtBox.enabled && body.simulated)
		{
			StickyRoundedRectangle component = collision.pp.fixTrans.GetComponent<StickyRoundedRectangle>();
			attachToGround(component);
		}
	}

	private void attachToGround(StickyRoundedRectangle attachedGround)
	{
		currentState = State.land;
		bodyAnimator.beginAnimThenPlayAnim(animData.GetAnimation("land"), animData.GetAnimation("idle"), setStateToIdle);
		AudioManager.Get().Play("slimeLand" + playerNumber);
		if (attachedGround.currentNormal(body).y < 0L)
		{
			flipTrans.flipFacing();
		}
	}

	public void SetPlayerId(int id)
	{
		playerNumber = id;
	}

	public void Bite(PlayerCollision victim)
	{
		SlimeController component = victim.GetComponent<SlimeController>();
		AbilityMonoBehaviour component2 = victim.GetComponent<AbilityMonoBehaviour>();
		if (component != null && !component.IsDestroyed)
		{
			playerToEat = component;
		}
		else if (component2 != null && !component2.IsDestroyed)
		{
			playerToEat = component2.GetSlimeController();
		}
		if (playerToEat == null || playerToEat.IsDestroyed)
		{
			return;
		}
		PlayerCollision activePlayerCollision = playerToEat.GetActivePlayerCollision();
		if (activePlayerCollision != null && !activePlayerCollision.IsDestroyed)
		{
			PlayerCollision activePlayerCollision2 = playerToEat.GetActivePlayerCollision();
			if (activePlayerCollision2 != null && !activePlayerCollision2.IsDestroyed && activePlayerCollision2.IsInvulnerable)
			{
				return;
			}
		}
		AudioManager.Get().Play("bite");
		currentState = State.biting;
		bodyAnimator.beginAnimThenDoAction(animData.GetAnimation("bite"), Chew);
	}

	public void Chew()
	{
		PlayerCollision playerCollision = playerToEat?.GetActivePlayerCollision();
		if (playerCollision != null && !playerCollision.IsDestroyed)
		{
			playerToEat.GetActivePlayerCollision()?.killPlayer(playerNumber, spawnEffect: false, ignoreInvulnerability: false, CauseOfDeath.Eaten);
			Player player = PlayerHandler.Get().GetPlayer(playerNumber);
			player.playersEatenCountThisRound++;
			if (!AchievementHandler.IsAchieved(AchievementHandler.AchievementEnum.EatAPlayer) && player.IsLocalPlayer)
			{
				AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.EatAPlayer);
			}
			if (!AchievementHandler.IsAchieved(AchievementHandler.AchievementEnum.Eat3Players) && player.IsLocalPlayer && player.playersEatenCountThisRound == 3)
			{
				AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.Eat3Players);
			}
		}
		bodyAnimator.beginAnimThenDoAction(animData.GetAnimation("chew"), Swallow);
	}

	public void Swallow()
	{
		AudioManager.Get().Play("swallow");
		bodyAnimator.beginAnimThenDoAction(animData.GetAnimation("swallow"), FinishEating);
		swallowing = true;
	}

	public void FinishEating()
	{
		currentState = State.idle;
		swallowing = false;
		bodyAnimator.beginAnim(animData.GetAnimation("idle"), null);
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (collision.layer != LayerMask.NameToLayer("Player"))
		{
			return;
		}
		FixTransform fixTrans = collision.colliderPP.fixTrans;
		if (currentState != State.biting && playerPhysics.IsGrounded() && fixTrans != null && !GameTime.IsTimeStoppedFor(playerNumber) && body.fixtrans.Scale - fixTrans.Scale >= scaleDiffBeforeNomNom)
		{
			PlayerCollision component = fixTrans.GetComponent<PlayerCollision>();
			if (component != null && PlayerHandler.Get().GetPlayer(component.GetPlayerId()).Team != PlayerHandler.Get().GetPlayer(playerNumber).Team)
			{
				Bite(component);
			}
		}
		Vec2 vec = body.position - fixTrans.position;
		Fix fix = Vec2.Magnitude(vec);
		UnityEngine.Debug.DrawLine((Vector2)body.position, (Vector2)fixTrans.position, UnityEngine.Color.red);
		if (fix != Fix.Zero && fix < playerPhysics.radius)
		{
			vec /= fix;
			playerPhysics.AddForce(vec * pushOverlappingPlayersStr);
		}
		else if (fix == Fix.Zero)
		{
			collision.colliderPP.fixTrans.GetComponent<PlayerBody>();
			vec = Vec2.MulByI(body.up) / (Fix)10L;
			if (collision.pp.hierarchyNumber - collision.colliderPP.hierarchyNumber < 0)
			{
				playerPhysics.AddForce(vec * pushOverlappingPlayersStr);
			}
			else
			{
				playerPhysics.AddForce(-vec * pushOverlappingPlayersStr);
			}
		}
	}
}
public class SlimeTrailCamera : MonoBehaviour
{
	[SerializeField]
	[HideInInspector]
	private Camera trailCamera;

	private const string globalTextureName = "_SlimeTrailRT";

	private const string globalCameraPosName = "_SlimeCameraWorldPosition";

	private const string slimeCameraSizeName = "_SlimeCameraSize";

	private const string mainCameraSizeName = "_MainCameraSize";

	private void Start()
	{
		GenerateRenderTarget();
	}

	private void GenerateRenderTarget()
	{
		trailCamera = GetComponent<Camera>();
		if (trailCamera.targetTexture != null)
		{
			RenderTexture targetTexture = trailCamera.targetTexture;
			trailCamera.targetTexture = null;
			UnityEngine.Object.DestroyImmediate(targetTexture);
		}
		trailCamera.targetTexture = new RenderTexture(4096, 2048, 24, RenderTextureFormat.ARGB32);
		trailCamera.targetTexture.filterMode = FilterMode.Trilinear;
		Shader.SetGlobalTexture("_SlimeTrailRT", trailCamera.targetTexture);
		UpdateVolatileShaderGlobals();
	}

	private void UpdateVolatileShaderGlobals()
	{
		Shader.SetGlobalVector("_SlimeCameraWorldPosition", trailCamera.transform.position);
		Shader.SetGlobalFloat("_SlimeCameraSize", trailCamera.orthographicSize);
		Shader.SetGlobalFloat("_MainCameraSize", Camera.main.orthographicSize);
	}

	private void Update()
	{
		UpdateVolatileShaderGlobals();
	}
}
public class SlimeTrailHandler : MonoBehaviour
{
	private List<GameObject> slimeTrailBlobs;

	private IPlayerIdHolder playerIdHolder;

	private PlayerPhysics playerPhysics;

	private SlimeController slimeController;

	private void Awake()
	{
		playerIdHolder = GetComponent<IPlayerIdHolder>();
		playerPhysics = GetComponent<PlayerPhysics>();
		slimeController = GetComponent<SlimeController>();
	}

	private void Start()
	{
		slimeTrailBlobs = new List<GameObject>();
		Transform[] componentsInChildren = GetComponentsInChildren<Transform>();
		foreach (Transform transform in componentsInChildren)
		{
			if (transform.gameObject.CompareTag("SlimeTrailBlob"))
			{
				slimeTrailBlobs.Add(transform.gameObject);
				transform.gameObject.GetComponent<SpriteRenderer>().material = playerIdHolder.GetPlayerMaterial();
			}
		}
		Update();
	}

	private void Update()
	{
		if (playerPhysics.IsGrounded() && slimeController.HasSpawned)
		{
			foreach (GameObject slimeTrailBlob in slimeTrailBlobs)
			{
				slimeTrailBlob.SetActive(value: true);
			}
			return;
		}
		foreach (GameObject slimeTrailBlob2 in slimeTrailBlobs)
		{
			slimeTrailBlob2.SetActive(value: false);
		}
	}
}
[Serializable]
public struct Sound
{
	public string name;

	public AudioClip clip;

	[Range(0f, 1f)]
	public float volume;

	[Range(0.1f, 3f)]
	public float pitch;

	public bool loop;

