[RequireComponent(typeof(DPhysicsRoundedRect))]
[SelectionBase]
public class StickyRoundedRectangle : MonoUpdatable
{
	private enum Zone
	{
		UP,
		TOP_RIGHT,
		RIGHT,
		BOT_RIGHT,
		DOWN,
		BOT_LEFT,
		LEFT,
		TOP_LEFT
	}

	private struct ZoneNormal
	{
		public Vec2 normal;

		public Zone zone;

		public ZoneNormal(Vec2 n, Zone z)
		{
			normal = n;
			zone = z;
		}
	}

	public struct Corners
	{
		public Vec2 tl;

		public Vec2 tr;

		public Vec2 bl;

		public Vec2 br;

		public Corners(Vec2 tl, Vec2 tr, Vec2 bl, Vec2 br)
		{
			this.tl = tl;
			this.tr = tr;
			this.bl = bl;
			this.br = br;
		}
	}

	public PlatformType platformType;

	private BoplBody groundBody;

	[HideInInspector]
	public DPhysicsRoundedRect rr;

	[HideInInspector]
	public int pickupPlayerFrames;

	[HideInInspector]
	public DuplicatePlatformEffect currentDuplicatePlatformEffect;

	private SpriteRenderer spriteRen;

	private Fix totalCircum;

	private Fix[] circumferences = new Fix[8];

	private Vec2 extents;

	private static Fix epsilon = (Fix)1E-05f;

	private Fix dropForce;

	private int dropPlayersForFrames;

	private int dontDropPlayerId = -1;

	[NonSerialized]
	public Fix baseScaleForPlatform = Fix.One;

	public bool isIcePlatform => platformType == PlatformType.ice;

	public bool pickUpPlayersInsteadOfSquish => pickupPlayerFrames > 0;

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		groundBody = GetComponent<BoplBody>();
		rr = GetComponent<DPhysicsRoundedRect>();
		spriteRen = GetComponent<SpriteRenderer>();
		UpdateBounds();
	}

	public void UpdateBounds()
	{
		extents = rr.CalcExtents();
		circumferences[0] = (circumferences[4] = extents.x * (Fix)2L);
		circumferences[1] = (circumferences[3] = (circumferences[5] = (circumferences[7] = rr.radius * Fix.PiOver2)));
		circumferences[2] = (circumferences[6] = extents.y * (Fix)2L);
		totalCircum = circumferences[0] * (Fix)2L + circumferences[1] * (Fix)4L + circumferences[2] * (Fix)2L;
	}

	public Fix Circumference()
	{
		return totalCircum;
	}

	private Fix totalWidth()
	{
		return extents.x * (Fix)2L + rr.radius * (Fix)2L;
	}

	private Fix totalHeight()
	{
		return extents.y * (Fix)2L + rr.radius * (Fix)2L;
	}

	public DPhysicsRoundedRect DPhysicsShape()
	{
		return rr;
	}

	public SpriteRenderer GetSpriteRenderer()
	{
		return spriteRen;
	}

	private ZoneNormal currentNormalZoned(Vec2 p)
	{
		Fix y = extents.y;
		Fix x = extents.x;
		Vec2 position = groundBody.position;
		Vec2 up = groundBody.up;
		Vec2 right = groundBody.right;
		Vec2 vec = up * y;
		Vec2 vec2 = right * x;
		Fix fix = Vec2.Dot(p - position, right);
		Fix fix2 = Vec2.Dot(p - position, up);
		if (fix <= -x)
		{
			if (fix2 >= y)
			{
				Vec2 vec3 = position - vec2 + vec;
				return new ZoneNormal(Vec2.NormalizedSafe(p - vec3), Zone.TOP_LEFT);
			}
			if (fix2 <= -y)
			{
				Vec2 vec4 = position - vec2 - vec;
				return new ZoneNormal(Vec2.NormalizedSafe(p - vec4), Zone.BOT_LEFT);
			}
			return new ZoneNormal(-right, Zone.LEFT);
		}
		if (fix >= x)
		{
			if (fix2 >= y)
			{
				Vec2 vec5 = position + vec2 + vec;
				return new ZoneNormal(Vec2.NormalizedSafe(p - vec5), Zone.TOP_RIGHT);
			}
			if (fix2 <= -y)
			{
				Vec2 vec6 = position + vec2 - vec;
				return new ZoneNormal(Vec2.NormalizedSafe(p - vec6), Zone.BOT_RIGHT);
			}
			return new ZoneNormal(right, Zone.RIGHT);
		}
		if (fix2 >= 0L)
		{
			return new ZoneNormal(up, Zone.UP);
		}
		return new ZoneNormal(-up, Zone.DOWN);
	}

	public Vec2 currentNormal(PlayerBody body)
	{
		return currentNormalZoned(body.position).normal;
	}

	public bool inCorner(Vec2 pos)
	{
		ZoneNormal zoneNormal = currentNormalZoned(pos);
		if (zoneNormal.zone != Zone.TOP_LEFT && zoneNormal.zone != Zone.TOP_RIGHT && zoneNormal.zone != Zone.BOT_LEFT)
		{
			return zoneNormal.zone == Zone.BOT_RIGHT;
		}
		return true;
	}

	public Vec2 currentNormal(Vec2 v)
	{
		return currentNormalZoned(v).normal;
	}

	public Vec2 forwardsDirection(PlayerBody body)
	{
		return Vec2.MulByNegI(currentNormal(body));
	}

	public Vec2 VelocityAtPos(Vec2 pos)
	{
		Vec2 v = pos - groundBody.position;
		Fix fix = Vec2.Magnitude(v) * groundBody.angularVelocity;
		Vec2 vec = Vec2.MulByI(Vec2.NormalizedSafe(v));
		return fix * vec + groundBody.velocity;
	}

	public Vec2 PositionFromLocalPlayerPos(Fix localPlayerPos, Fix playerRadius)
	{
		localPlayerPos *= totalCircum + playerRadius * Fix.PiTimes2;
		Fix zero = Fix.Zero;
		for (int i = 0; i < circumferences.Length; i++)
		{
			Fix fix = localPlayerPos - zero;
			zero += circumferences[i];
			Zone zone = (Zone)i;
			if (zone == Zone.TOP_RIGHT || zone == Zone.BOT_RIGHT || zone == Zone.BOT_LEFT || zone == Zone.TOP_LEFT)
			{
				zero += playerRadius * Fix.PiOver2;
			}
			if (localPlayerPos < zero)
			{
				Vec2 position = groundBody.position;
				Vec2 up = groundBody.up;
				Vec2 right = groundBody.right;
				Fix fix2 = rr.radius + playerRadius;
				Fix zero2 = Fix.Zero;
				Fix y = extents.y;
				Fix x = extents.x;
				switch (zone)
				{
				case Zone.UP:
					return position - right * x + up * (y + fix2) + right * fix;
				case Zone.TOP_RIGHT:
					zero2 = Fix.PiOver2 - fix / fix2;
					return position + right * x + up * y + (right * Fix.Cos(zero2) + up * Fix.Sin(zero2)) * fix2;
				case Zone.RIGHT:
					return position + right * (x + fix2) + up * (y - fix);
				case Zone.BOT_RIGHT:
					zero2 = -fix / fix2;
					return position + right * x - up * y + (right * Fix.Cos(zero2) + up * Fix.Sin(zero2)) * fix2;
				case Zone.DOWN:
					return position + right * x - up * (y + fix2) - right * fix;
				case Zone.BOT_LEFT:
					zero2 = Fix.PiOver2 - fix / fix2 + Fix.Pi;
					return position - right * x - up * y + (right * Fix.Cos(zero2) + up * Fix.Sin(zero2)) * fix2;
				case Zone.LEFT:
					return position - right * (x + fix2) + up * (fix - y);
				case Zone.TOP_LEFT:
					zero2 = Fix.Pi - fix / fix2;
					return position - right * x + up * y + (right * Fix.Cos(zero2) + up * Fix.Sin(zero2)) * fix2;
				default:
					return Vec2.zero;
				}
			}
		}
		return Vec2.zero;
	}

	public Fix LocalPlayerPosFromPos(Vec2 pos, Fix playerRadius)
	{
		ZoneNormal zoneNormal = currentNormalZoned(pos);
		Fix zero = Fix.Zero;
		for (int i = 0; i < (int)zoneNormal.zone; i++)
		{
			zero += circumferences[i];
			Zone zone = (Zone)i;
			if (zone != Zone.UP && zone != Zone.DOWN && zone != Zone.RIGHT && zone != Zone.LEFT)
			{
				zero += playerRadius * Fix.PiOver2;
			}
		}
		Vec2 position = groundBody.position;
		Vec2 up = groundBody.up;
		Vec2 right = groundBody.right;
		Fix fix = rr.radius + playerRadius;
		Fix y = extents.y;
		Fix x = extents.x;
		Vec2 closestPoint = GetClosestPoint(pos);
		Fix fix2;
		switch (zoneNormal.zone)
		{
		case Zone.UP:
			fix2 = zero + Vec2.Distance(position + up * (y + rr.radius) - right * x, closestPoint);
			break;
		case Zone.TOP_RIGHT:
		{
			Vec2 vec4 = position + up * y + right * x;
			fix2 = zero + Fix.Abs(Tools.Angle2(up, closestPoint - vec4) * fix);
			break;
		}
		case Zone.RIGHT:
			fix2 = zero + Vec2.Distance(position + up * y + right * (x + rr.radius), closestPoint);
			break;
		case Zone.BOT_RIGHT:
		{
			Vec2 vec3 = position - up * y + right * x;
			fix2 = zero + Fix.Abs(Tools.Angle2(right, closestPoint - vec3) * fix);
			break;
		}
		case Zone.DOWN:
			fix2 = zero + Vec2.Distance(position - up * (y + rr.radius) + right * x, closestPoint);
			break;
		case Zone.BOT_LEFT:
		{
			Vec2 vec2 = position - up * y - right * x;
			fix2 = zero + Fix.Abs(Tools.Angle2(-up, closestPoint - vec2) * fix);
			break;
		}
		case Zone.LEFT:
			fix2 = zero + Vec2.Distance(position - up * y - right * (x + rr.radius), closestPoint);
			break;
		case Zone.TOP_LEFT:
		{
			Vec2 vec = position + up * y - right * x;
			fix2 = zero + Fix.Abs(Tools.Angle2(-right, closestPoint - vec) * fix);
			break;
		}
		default:
			return Fix.Zero;
		}
		return fix2 / (totalCircum + playerRadius * Fix.PiTimes2);
	}

	public Fix moveAlongSurface(PlayerBody body, Fix playerRadius, Fix speed, Fix deltaTime, Fix localPlatFormPos, ref RaycastHit2D[] hitsBuffer)
	{
		Fix fix = speed;
		if (hitsBuffer != null)
		{
			Vec2 vec = forwardsDirection(body);
			fix = Fix.Min(maxMovementAllowed(playerRadius, body.position, speed * vec, deltaTime, ref hitsBuffer, out var _), Fix.Abs(speed));
			fix *= (Fix)Fix.Sign(speed);
		}
		fix *= deltaTime;
		Fix fix2 = totalCircum + playerRadius * Fix.PiTimes2;
		return Fix.SlowMod(Fix.One + localPlatFormPos + fix / fix2, Fix.One);
	}

	public Fix moveAlongSurfaceMultiple(PlayerBody body, Fix playerRadius, Fix speed, Fix deltaTime, Fix localPlatFormPos, Vec2 pos2, Fix radius2, ref RaycastHit2D[] hitsBuffer)
	{
		Fix fix = speed;
		if (hitsBuffer != null)
		{
			Vec2 vec = forwardsDirection(body);
			fix = Fix.Min(maxMovementAllowed(playerRadius, body.position, speed * vec, deltaTime, ref hitsBuffer, out var blockingPlatform), Fix.Abs(speed));
			fix = Fix.Min(maxMovementAllowed(radius2, pos2, speed * vec, deltaTime, ref hitsBuffer, out blockingPlatform), Fix.Abs(speed));
			fix *= (Fix)Fix.Sign(speed);
		}
		fix *= deltaTime;
		Fix fix2 = totalCircum + playerRadius * Fix.PiTimes2;
		return Fix.SlowMod(Fix.One + localPlatFormPos + fix / fix2, Fix.One);
	}

	public Fix externalForceAlongSurface(PlayerBody body)
	{
		return Vec2.Dot(body.externalVelocity, forwardsDirection(body));
	}

	public Fix PlatformHopMove(PlayerBody body, Fix playerRadius, Fix speed, Fix deltaTime, Fix localPlatFormPos, ref RaycastHit2D[] hitsBuffer, ref int[] disAllowedPlatformIds, out StickyRoundedRectangle blockingPlatform, out Fix remainingMovement)
	{
		speed *= deltaTime;
		Fix fix = speed;
		remainingMovement = Fix.Zero;
		blockingPlatform = null;
		if (hitsBuffer != null)
		{
			Vec2 vec = forwardsDirection(body);
			Vec2 pos = PositionFromLocalPlayerPos(localPlatFormPos, playerRadius);
			Fix fix2 = MaxPlatformHoppingMovemementAllowed(playerRadius, pos, speed * vec, deltaTime, ref disAllowedPlatformIds, out blockingPlatform);
			if (Fix.Abs(fix) < fix2)
			{
				blockingPlatform = null;
			}
			fix = Fix.Min(Fix.Abs(speed), fix2);
			remainingMovement = Fix.Abs(fix - Fix.Abs(speed)) * (Fix)Fix.Sign(speed);
			fix *= (Fix)Fix.Sign(speed);
		}
		Fix fix3 = totalCircum + playerRadius * Fix.PiTimes2;
		return Fix.SlowMod(localPlatFormPos + fix / fix3 + Fix.One, Fix.One);
	}

	public void DropAllAttachedPlayers(int dontDropPlayerId, Fix dropForce)
	{
		dropPlayersForFrames = 2;
		this.dontDropPlayerId = dontDropPlayerId;
		this.dropForce = dropForce;
	}

	public bool AmIdropped(int playerId, out Fix dropForce)
	{
		dropForce = this.dropForce;
		if (dropPlayersForFrames > 0)
		{
			return playerId != dontDropPlayerId;
		}
		return false;
	}

	public Fix moveAlongSurface(PlayerBody body, Fix playerRadius, Fix speed, Fix deltaTime, Fix localPlatFormPos)
	{
		Fix fix = speed;
		fix *= deltaTime;
		Fix fix2 = totalCircum + playerRadius * Fix.PiTimes2;
		return Fix.SlowMod(Fix.One + localPlatFormPos + fix / fix2, Fix.One);
	}

	private Fix MaxPlatformHoppingMovemementAllowed(Fix playerRadius, Vec2 pos, Vec2 velocity, Fix deltaTime, ref int[] disAllowedPlatformIds, out StickyRoundedRectangle blockingPlatform)
	{
		Fix fix = (Fix)1000000000L;
		blockingPlatform = null;
		Vec2 dir = Vec2.NormalizedSafe(velocity);
		for (int i = 0; i < DetPhysics.Get().roundedRects.Length; i++)
		{
			Fix distNear = Fix.Zero;
			Fix distFar = Fix.Zero;
			if (Raycast.RayCastRoundedRect(pos, dir, DetPhysics.Get().roundedRects.colliders[i], out distNear, out distFar))
			{
				bool flag = true;
				for (int j = 0; j < disAllowedPlatformIds.Length; j++)
				{
					FixTransform fixTrans = DetPhysics.Get().roundedRects.physicsParents[i].fixTrans;
					flag &= DetPhysics.Get().roundedRects.physicsParents[i].instanceId != disAllowedPlatformIds[j] && fixTrans != null && !fixTrans.IsDestroyed && fixTrans.gameObject.activeSelf;
				}
				if (flag && distNear < fix)
				{
					fix = distNear;
					blockingPlatform = DetPhysics.Get().roundedRects.physicsParents[i].fixTrans.GetComponent<StickyRoundedRectangle>();
				}
			}
		}
		return fix;
	}

	private Fix maxMovementAllowed(Fix playerRadius, Vec2 pos, Vec2 velocity, Fix deltaTime, ref RaycastHit2D[] hitsBuffer, out StickyRoundedRectangle blockingPlatform)
	{
		Fix fix = (Fix)10000000000L;
		rr.enabled = false;
		Vec2 vec = Vec2.NormalizedSafe(velocity);
		Fix distance = Vec2.Magnitude(velocity) * deltaTime;
		Vec2 vec2 = playerRadius * vec;
		RaycastInformation raycastInformation = DetPhysics.Get().RaycastToClosestRoundedRect(pos + vec2, vec, distance);
		RaycastInformation raycastInformation2 = DetPhysics.Get().RaycastToClosestRoundedRect(pos + vec2 + Vec2.MulByI(vec2), vec, distance);
		RaycastInformation raycastInformation3 = DetPhysics.Get().RaycastToClosestRoundedRect(pos + vec2 + Vec2.MulByNegI(vec2), vec, distance);
		blockingPlatform = null;
		if ((bool)raycastInformation)
		{
			fix = raycastInformation.nearDist;
			blockingPlatform = raycastInformation.pp.fixTrans.GetComponent<StickyRoundedRectangle>();
		}
		if ((bool)raycastInformation2 && raycastInformation2.nearDist < fix)
		{
			fix = raycastInformation2.nearDist;
			blockingPlatform = raycastInformation2.pp.fixTrans.GetComponent<StickyRoundedRectangle>();
		}
		if ((bool)raycastInformation3 && raycastInformation3.nearDist < fix)
		{
			fix = raycastInformation3.nearDist;
			blockingPlatform = raycastInformation3.pp.fixTrans.GetComponent<StickyRoundedRectangle>();
		}
		rr.enabled = true;
		return fix;
	}

	private Fix VectorAngle(Vec2 normal)
	{
		return Fix.Atan2(normal.y, normal.x);
	}

	public GameObject ThisGameObject()
	{
		return base.gameObject;
	}

	public Vec2 GetClosestPoint(Vec2 p)
	{
		Vec2 position = groundBody.position;
		Vec2 up = groundBody.up;
		Vec2 right = groundBody.right;
		Fix x = extents.x;
		Fix y = extents.y;
		Vec2 vec = up * y;
		Vec2 vec2 = right * x;
		Fix fix = Vec2.Dot(p - position, right);
		Fix fix2 = Vec2.Dot(p - position, up);
		if (fix <= -x)
		{
			if (fix2 >= y)
			{
				Vec2 vec3 = position - vec2 + vec;
				return vec3 + Vec2.Normalized(p - vec3) * rr.radius;
			}
			if (fix2 <= -y)
			{
				Vec2 vec4 = position - vec2 - vec;
				return vec4 + Vec2.Normalized(p - vec4) * rr.radius;
			}
			Vec2 vec5 = -right * (x + rr.radius);
			Vec2 vec6 = up * fix2;
			return position + vec5 + vec6;
		}
		if (fix >= x)
		{
			if (fix2 >= y)
			{
				Vec2 vec7 = position + vec2 + vec;
				return vec7 + Vec2.Normalized(p - vec7) * rr.radius;
			}
			if (fix2 <= -y)
			{
				Vec2 vec8 = position + vec2 - vec;
				return vec8 + Vec2.Normalized(p - vec8) * rr.radius;
			}
			Vec2 vec9 = right * (x + rr.radius);
			Vec2 vec10 = up * fix2;
			return position + vec9 + vec10;
		}
		if (fix2 >= 0L)
		{
			Vec2 vec11 = right * fix;
			Vec2 vec12 = up * (y + rr.radius);
			return position + vec11 + vec12;
		}
		Vec2 vec13 = right * fix;
		Vec2 vec14 = -up * (y + rr.radius);
		return position + vec13 + vec14;
	}

	public bool ContainsPoint(Vec2 point)
	{
		Fix x = extents.x;
		Fix y = extents.y;
		Vec2 position = groundBody.position;
		Vec2 vec = groundBody.up * y;
		Vec2 vec2 = groundBody.right * x;
		Vec2 u = position + vec2 + vec;
		Vec2 u2 = position + vec2 - vec;
		Vec2 u3 = position - vec2 - vec;
		Vec2 u4 = position - vec2 + vec;
		if (Vec2.Distance(point, u) <= rr.radius || Vec2.Distance(point, u2) <= rr.radius || Vec2.Distance(point, u3) <= rr.radius || Vec2.Distance(point, u4) <= rr.radius)
		{
			return true;
		}
		return innerRectanglesContain(point);
	}

	private bool innerRectanglesContain(Vec2 point)
	{
		Vec2 position = groundBody.position;
		Vec2 up = groundBody.up;
		Vec2 right = groundBody.right;
		Fix x = extents.x;
		Fix y = extents.y;
		Fix value = Vec2.Dot(position - point, right);
		Fix value2 = Vec2.Dot(position - point, up);
		if (Fix.Abs(value) <= totalWidth() * (Fix)0.5f && Fix.Abs(value2) <= totalHeight() * (Fix)0.5f)
		{
			if (Fix.Abs(value) <= x)
			{
				return true;
			}
			if (Fix.Abs(value2) <= y)
			{
				return true;
			}
		}
		return false;
	}

	public Corners GetBoundingRect()
	{
		Fix x = extents.x;
		Fix y = extents.y;
		Vec2 position = groundBody.position;
		Vec2 vec = groundBody.up * (y + rr.radius);
		Vec2 vec2 = groundBody.right * (x + rr.radius);
		return new Corners(tr: position + vec2 + vec, br: position + vec2 - vec, bl: position - vec2 - vec, tl: position - vec2 + vec);
	}

	public BoplBody GetGroundBody()
	{
		return groundBody;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (dropPlayersForFrames >= 0)
		{
			dropPlayersForFrames--;
		}
		if (pickupPlayerFrames >= 0)
		{
			pickupPlayerFrames--;
		}
		rr.timeSinceLastScaledUp += simDeltaTime * GameTime.PlayerTimeScale;
		if ((rr.timeSinceLastScaledUp > Constants.timeUntilPlatformsReturnToOriginalSize || GameSessionHandler.SuddenDeathInProgress) && rr.Scale > baseScaleForPlatform && !GameTime.IsTimeStopped())
		{
			rr.Scale = Fix.Lerp(rr.Scale, baseScaleForPlatform, simDeltaTime);
		}
		UpdateBounds();
	}

	public void alignRotation(PlayerBody body)
	{
		Vec2 up = currentNormal(body);
		body.up = up;
		body.transform.rotation = Quaternion.AngleAxis((float)body.rotation * 57.29578f, Vector3.forward);
	}

	public void alignRotation(BoplBody body)
	{
		Vec2 up = currentNormal(body.position);
		body.up = up;
		body.transform.rotation = Quaternion.AngleAxis((float)body.rotation * 57.29578f, Vector3.forward);
	}
}
