public class AbilityGrid : MonoBehaviour
{
	public AbilityGridEntry entryPrefab;

	public NamedSpriteList abilityIcons;

	public NamedSpriteList abilityIcons_demo;

	private NamedSpriteList selectedList;

	private RectTransform recTrans;

	public int columns = 4;

	private AbilityGridEntry[] grid;

	[HideInInspector]
	public AnimateInOutUI animateUI;

	private bool usesKeyboardAndMouse;

	private Gamepad gamepad;

	public RectTransform selectionCircle;

	public CharacterSelectBox csb;

	public TextMeshProUGUI text;

	public UnityEngine.UI.Image borderImage;

	public Sprite LockSprite;

	public TextMeshProUGUI notAvailableInDemo;

	private bool isActive;

	private int x;

	private int y;

	public float nonSelectedScale = 1f;

	public float selectedScale = 1.3f;

	private int rows;

	private float entrySize;

	public int SelectedIcon
	{
		get
		{
			return x + y * columns;
		}
		set
		{
			y = value / columns;
			x = value % columns;
		}
	}

	public void Init(bool usesKeyboardAndMouse, Gamepad gamepad, int startSelection)
	{
		base.enabled = true;
		this.usesKeyboardAndMouse = usesKeyboardAndMouse;
		this.gamepad = gamepad;
		notAvailableInDemo.enabled = false;
		animateUI.AnimateIn();
		SelectedIcon = startSelection - 1;
		text.text = LocalizedText.localizationTable.GetText(abilityIcons.sprites[SelectedIcon + 1].name, Settings.Get().Language);
		AudioManager.Get().Play("accept");
		borderImage.transform.SetAsLastSibling();
	}

	public void CloseGrid()
	{
		csb.CloseAbilityGrid(SelectedIcon + 1);
	}

	private int columnsAtRow(int row)
	{
		int num = grid.Length - columns * row;
		if (num > columns)
		{
			return columns;
		}
		return num % (columns + 1);
	}

	private int rowsAtColumn(int column)
	{
		if (columnsAtRow(rows - 1) > column)
		{
			return rows;
		}
		return rows - 1;
	}

	public void DeInit()
	{
		base.enabled = false;
		animateUI.AnimateOut();
	}

	private void Awake()
	{
		base.enabled = false;
		recTrans = GetComponent<RectTransform>();
		animateUI = GetComponent<AnimateInOutUI>();
		int num = abilityIcons.sprites.Count - 1;
		grid = new AbilityGridEntry[num];
		rows = Mathf.CeilToInt((float)num / (float)columns);
		float num2 = recTrans.rect.height * 0.9f;
		Vector2 vector = new Vector2(126f, -122f);
		float num3 = recTrans.rect.width * num2;
		entrySize = Mathf.Sqrt(num3 / (float)(columns * rows));
		int num4 = 0;
		for (int i = 0; i <= rows; i++)
		{
			for (int j = 0; j < columns; j++)
			{
				if (num4 >= grid.Length)
				{
					break;
				}
				AbilityGridEntry abilityGridEntry = UnityEngine.Object.Instantiate(entryPrefab, base.transform);
				abilityGridEntry.SetSprite(abilityIcons.sprites[num4 + 1].sprite);
				abilityGridEntry.rectTrans.anchoredPosition = vector + new Vector2((float)j * entrySize - recTrans.rect.width / 2f, (float)(-i) * entrySize + recTrans.rect.height / 2f);
				abilityGridEntry.rectTrans.localScale = nonSelectedScale * new Vector3(entrySize / abilityGridEntry.rectTrans.rect.width, entrySize / abilityGridEntry.rectTrans.rect.height, 1f);
				grid[num4] = abilityGridEntry;
				num4++;
			}
		}
		NamedSpriteList namedSpriteList = (SteamManager.instance.dlc.HasDLC() ? abilityIcons : abilityIcons_demo);
		for (int k = 0; k < grid.Length; k++)
		{
			bool isLocked = k >= namedSpriteList.sprites.Count - 1;
			grid[k].SetSprite(abilityIcons.sprites[k + 1].sprite);
			grid[k].Init(this, k, isLocked);
		}
		text.font = LocalizedText.localizationTable.GetFont(Settings.Get().Language, useFontWithStroke: false);
	}

	private void Update()
	{
		int num = columnsAtRow(y);
		int num2 = rowsAtColumn(x);
		int num3 = x;
		int num4 = y;
		if (usesKeyboardAndMouse)
		{
			Keyboard current = Keyboard.current;
			if (current.dKey.wasPressedThisFrame || current.rightArrowKey.wasPressedThisFrame)
			{
				x = (x + 1) % num;
			}
			else if (current.aKey.wasPressedThisFrame || current.leftArrowKey.wasPressedThisFrame)
			{
				x = (x - 1 + num) % num;
			}
			else if (current.wKey.wasPressedThisFrame || current.upArrowKey.wasPressedThisFrame)
			{
				y = (y - 1 + num2) % num2;
			}
			else if (current.sKey.wasPressedThisFrame || current.downArrowKey.wasPressedThisFrame)
			{
				y = (y + 1) % num2;
			}
		}
		else if (gamepad != null)
		{
			if (gamepad.dpad.right.wasPressedThisFrame || gamepad.leftStick.right.wasPressedThisFrame)
			{
				x = (x + 1) % num;
			}
			else if (gamepad.dpad.left.wasPressedThisFrame || gamepad.leftStick.left.wasPressedThisFrame)
			{
				x = (x - 1 + num) % num;
			}
			else if (gamepad.dpad.up.wasPressedThisFrame || gamepad.leftStick.up.wasPressedThisFrame)
			{
				y = (y - 1 + num2) % num2;
			}
			else if (gamepad.dpad.down.wasPressedThisFrame || gamepad.leftStick.down.wasPressedThisFrame)
			{
				y = (y + 1) % num2;
			}
		}
		if (x != num3 || y != num4)
		{
			AudioManager.Get().Play("navigateMenu");
		}
		text.text = LocalizedText.localizationTable.GetText(abilityIcons.sprites[SelectedIcon + 1].name.ToLower(), Settings.Get().Language);
		if (grid[0].GetColor() != borderImage.color)
		{
			for (int i = 0; i < grid.Length; i++)
			{
				grid[i].SetColor(borderImage.color);
			}
		}
		for (int j = 0; j < grid.Length; j++)
		{
			grid[j].rectTrans.localScale = nonSelectedScale * new Vector3(entrySize / grid[j].rectTrans.rect.width, entrySize / grid[j].rectTrans.rect.height, 1f);
		}
		grid[SelectedIcon].rectTrans.localScale = selectedScale * new Vector3(entrySize / grid[SelectedIcon].rectTrans.rect.width, entrySize / grid[SelectedIcon].rectTrans.rect.height, 1f);
		selectionCircle.anchoredPosition = grid[SelectedIcon].rectTrans.anchoredPosition;
		notAvailableInDemo.enabled = SelectedIcon > abilityIcons_demo.sprites.Count - 2 && !SteamManager.instance.dlc.HasDLC();
	}
}
