public class AbilityListFrame : MonoBehaviour
{
	public UnityEngine.UI.Image ArrowUp;

	public UnityEngine.UI.Image ArrowDown;

	public AnimationCurve animation;

	private Vector2 originalPosUp;

	private Vector2 originalPosDown;

	private double timeSinceAnimateUp = 1.7014117331926443E+38;

	private double timeSinceAnimateDown = 1.7014117331926443E+38;

	public void AnimateUpArrow()
	{
		timeSinceAnimateUp = 0.0;
	}

	public void AnimateDownArrow()
	{
		timeSinceAnimateDown = 0.0;
	}

	private void Awake()
	{
		originalPosUp = ArrowUp.rectTransform.anchoredPosition;
		originalPosDown = ArrowDown.rectTransform.anchoredPosition;
	}

	private void Update()
	{
		timeSinceAnimateUp += Time.deltaTime;
		timeSinceAnimateDown += Time.deltaTime;
		ArrowUp.rectTransform.anchoredPosition = originalPosUp + Vector2.left * animation.Evaluate((float)timeSinceAnimateUp);
		ArrowDown.rectTransform.anchoredPosition = originalPosDown + Vector2.right * animation.Evaluate((float)timeSinceAnimateDown);
	}
}
public class AbilitySelectCharacter : MonoBehaviour
{
	public enum AbilityIndicator
	{
		X,
		Y,
		Z
	}

	public UnityEngine.UI.Image IconX;

	public UnityEngine.UI.Image IconY;

	public UnityEngine.UI.Image IconZ;

	public GameObject UnSelectedX;

	public GameObject UnSelectedY;

	public GameObject UnSelectedZ;

	public void Start()
	{
		if (Settings.Get().NumberOfAbilities < 1)
		{
			UnSelectedX.SetActive(value: false);
		}
		if (Settings.Get().NumberOfAbilities < 2)
		{
			UnSelectedY.SetActive(value: false);
		}
		if (Settings.Get().NumberOfAbilities < 3)
		{
			UnSelectedZ.SetActive(value: false);
		}
	}

	public void SetAbility(AbilityIndicator CircleIndex, Sprite iconSprite)
	{
		UnityEngine.UI.Image image;
		GameObject gameObject;
		switch (CircleIndex)
		{
		case AbilityIndicator.X:
			if (Settings.Get().NumberOfAbilities < 1)
			{
				return;
			}
			image = IconX;
			gameObject = UnSelectedX;
			break;
		case AbilityIndicator.Y:
			if (Settings.Get().NumberOfAbilities < 2)
			{
				return;
			}
			image = IconY;
			gameObject = UnSelectedY;
			break;
		case AbilityIndicator.Z:
			if (Settings.Get().NumberOfAbilities < 3)
			{
				return;
			}
			image = IconZ;
			gameObject = UnSelectedZ;
			break;
		default:
			image = IconZ;
			gameObject = UnSelectedZ;
			break;
		}
		image.sprite = iconSprite;
		image.gameObject.SetActive(value: true);
		gameObject.SetActive(value: false);
	}

	public void ResetAbility(AbilityIndicator CircleIndex)
	{
		UnityEngine.UI.Image image;
		GameObject gameObject;
		switch (CircleIndex)
		{
		case AbilityIndicator.X:
			if (Settings.Get().NumberOfAbilities < 1)
			{
				return;
			}
			image = IconX;
			gameObject = UnSelectedX;
			break;
		case AbilityIndicator.Y:
			if (Settings.Get().NumberOfAbilities < 2)
			{
				return;
			}
			image = IconY;
			gameObject = UnSelectedY;
			break;
		case AbilityIndicator.Z:
			if (Settings.Get().NumberOfAbilities < 3)
			{
				return;
			}
			image = IconZ;
			gameObject = UnSelectedZ;
			break;
		default:
			image = IconZ;
			gameObject = UnSelectedZ;
			break;
		}
		image.gameObject.SetActive(value: false);
		gameObject.SetActive(value: true);
	}

	public void ResetAbilites()
	{
		if (Settings.Get().NumberOfAbilities >= 1)
		{
			IconX.gameObject.SetActive(value: false);
			UnSelectedX.SetActive(value: true);
		}
		if (Settings.Get().NumberOfAbilities >= 2)
		{
			IconY.gameObject.SetActive(value: false);
			UnSelectedY.SetActive(value: true);
		}
		if (Settings.Get().NumberOfAbilities >= 3)
		{
			IconZ.gameObject.SetActive(value: false);
			UnSelectedZ.SetActive(value: true);
		}
	}
}
public class AbilitySelectCircle : MonoBehaviour
{
	public AbilitySelectController loser;

	public AbilitySelectWinner winner;

	[SerializeField]
	private AnimationCurve moveUpAnim;

	[SerializeField]
	private Vector2 startPosition;

	[SerializeField]
	private Vector2 targetPosition;

	private float timeSinceActivated;

	[SerializeField]
	private AnimationCurve WiggleAnimation;

	[SerializeField]
	private UnityEngine.UI.Image[] FILL_Images;

	[SerializeField]
	private UnityEngine.UI.Image[] BORDER_Images;

	[SerializeField]
	private TextMeshProUGUI[] BORDER_Texts;

	[SerializeField]
	private Button[] BORDER_Buttons;

	[SerializeField]
	private TeamColors teamColors;

	private float timeSinceWiggleEvent = 100000f;

	private Vector2 originalPosition;

	public float DelayDifferenceDenominator = 10f;

	public float ShowUpDelay = 1f;

	public bool isWinner = true;

	[SerializeField]
	private RectTransform rectTrans;

	public RectTransform trans => rectTrans;

	public void SetCharacterSprite(Sprite sprite)
	{
		loser.SetCharacterSprite(sprite);
		winner.SetCharacterSprite(sprite);
	}

	public void Wiggle()
	{
		if (timeSinceWiggleEvent > WiggleAnimation.keys[WiggleAnimation.length - 1].time)
		{
			timeSinceWiggleEvent = 0f;
		}
	}

	public void SetPlayer(int id, bool isWinner)
	{
		loser.SetPlayer(id);
		winner.SetPlayer(id);
		int team = PlayerHandler.Get().GetPlayer(id).Team;
		for (int i = 0; i < FILL_Images.Length; i++)
		{
			FILL_Images[i].color = teamColors.teamColors[team].fill;
		}
		for (int j = 0; j < BORDER_Images.Length; j++)
		{
			BORDER_Images[j].color = teamColors.teamColors[team].border;
		}
		for (int k = 0; k < BORDER_Buttons.Length; k++)
		{
			ColorBlock colors = BORDER_Buttons[k].colors;
			colors.normalColor = teamColors.teamColors[team].border;
			BORDER_Buttons[k].colors = colors;
		}
		for (int l = 0; l < BORDER_Texts.Length; l++)
		{
			BORDER_Texts[l].color = teamColors.teamColors[team].border;
		}
		if (isWinner)
		{
			winner.enabled = true;
			loser.enabled = false;
			winner.gameObject.SetActive(value: true);
			loser.gameObject.SetActive(value: false);
		}
		else
		{
			loser.enabled = true;
			winner.enabled = false;
			loser.gameObject.SetActive(value: true);
			winner.gameObject.SetActive(value: false);
		}
		timeSinceActivated = trans.anchoredPosition.x / DelayDifferenceDenominator - ShowUpDelay;
	}

	public void Disable()
	{
		loser.FinishAnimation();
		loser.enabled = false;
		winner.enabled = false;
		trans.anchoredPosition = new Vector2(trans.anchoredPosition.x, startPosition.y);
		timeSinceActivated = 1f - trans.anchoredPosition.x / DelayDifferenceDenominator;
	}

	public bool IsDisabled()
	{
		if (!winner.enabled)
		{
			return !loser.enabled;
		}
		return false;
	}

	public int GetPlayerId()
	{
		return loser.GetPlayerId();
	}

	public void Init(int playerId, bool isWinner)
	{
		winner.Init(playerId);
		loser.Init(playerId);
		loser.enabled = false;
		winner.enabled = false;
		this.isWinner = isWinner;
		winner.gameObject.SetActive(value: false);
		loser.gameObject.SetActive(value: false);
		timeSinceActivated = 0f;
		originalPosition = rectTrans.anchoredPosition;
		_ = PlayerHandler.Get().GetPlayer(playerId).Team;
	}

	private void Start()
	{
	}

	private void Update()
	{
		if (IsDisabled())
		{
			Vector2 vector = Vector2.Lerp(startPosition, targetPosition, moveUpAnim.Evaluate(timeSinceActivated));
			trans.anchoredPosition = new Vector2(trans.anchoredPosition.x, vector.y);
			timeSinceActivated -= Time.deltaTime;
		}
		else
		{
			float x = originalPosition.x + WiggleAnimation.Evaluate(timeSinceWiggleEvent);
			Vector2 vector2 = Vector2.Lerp(startPosition, targetPosition, moveUpAnim.Evaluate(timeSinceActivated));
			trans.anchoredPosition = new Vector2(x, vector2.y);
			timeSinceActivated += Time.deltaTime;
			timeSinceWiggleEvent += Time.deltaTime;
		}
	}
}
public interface IAbilitySelectList
{
	RectTransform trans { get; }

	void SetPlayer(int id);

	int GetPlayerId();

	void Init(int playerId);
}
public class AbilitySelectController : MonoBehaviour, IAbilitySelectList
{
	[SerializeField]
	private RectTransform character;

	[SerializeField]
	private RectTransform arrow;

	[SerializeField]
	private MidGameAbilitySelect abilityCirclesParent;

	[SerializeField]
	private float arrowUpSensitivity = 2f;

	private UnityEngine.UI.Image[] characterImages;

	[SerializeField]
	private float inactiveAlpha = 0.7f;

	private Vector2[] abilityListOriginalPositions;

	private Player player;

	[SerializeField]
	private RectTransform rectTrans;

	[SerializeField]
	private float YArrowOffset = 2f;

	[SerializeField]
	private float YArrowOffsetPerCircle = 80f;

	private float YArrowOriginalHeight;

	[SerializeField]
	private AnimationCurve OpenAnimation01;

	[SerializeField]
	private AnimationCurve ScaleAnimation;

	[SerializeField]
	private TextMeshProUGUI ScoreText;

	private RectTransform[] Selectors;

	[SerializeField]
	private RectTransform busyDotsParent;

	[SerializeField]
	private RectTransform[] dots;

	private float[] originalDotHeights = new float[3];

	public AnimationCurve busyDotsAnimation;

	public float height = 10f;

	public float animationDuration = 1f;

	public TeamColors teamColors;

	private bool ClickedUp;

	private bool isOpen;

	private float timeSinceOpenOrClose;

	private float timeSinceAbilitySelect;

	private bool openCloseMenuNextFrame;

	[SerializeField]
	private float DelayBeforeInputIsTaken = 5f;

	private float timeSinceEnabled;

	public RectTransform trans => rectTrans;

	private void Awake()
	{
		originalDotHeights[0] = dots[0].anchoredPosition.y;
		originalDotHeights[1] = dots[1].anchoredPosition.y;
		originalDotHeights[2] = dots[2].anchoredPosition.y;
	}

	public void SetPlayer(int id)
	{
		player = PlayerHandler.Get().GetPlayer(id);
		if (!player.IsLocalPlayer)
		{
			List<SteamConnection> connectedPlayers = SteamManager.instance.connectedPlayers;
			for (int i = 0; i < connectedPlayers.Count; i++)
			{
				if ((ulong)connectedPlayers[i].id == (ulong)player.steamId)
				{
					for (int j = 0; j < dots.Length; j++)
					{
						dots[j].GetComponent<UnityEngine.UI.Image>().color = teamColors.teamColors[connectedPlayers[i].lobby_team].fill;
					}
					break;
				}
			}
		}
		characterImages[2].material = player.Color;
		abilityCirclesParent.SetPlayer(player.Id);
		ScoreText.text = player.GamesWon.ToString();
		player.HasAbilitySelectOpenend = false;
		abilityCirclesParent.ArrowL.anchoredPosition = new Vector2(abilityCirclesParent.ArrowL.anchoredPosition.x, abilityCirclesParent.TotalYOffset());
		abilityCirclesParent.ArrowR.anchoredPosition = new Vector2(abilityCirclesParent.ArrowL.anchoredPosition.x, abilityCirclesParent.TotalYOffset());
		abilityCirclesParent.gameObject.SetActive(value: false);
		busyDotsParent.gameObject.SetActive(value: false);
		if (GameLobby.isOnlineGame && !player.IsLocalPlayer)
		{
			arrow.gameObject.SetActive(value: false);
		}
		else
		{
			arrow.gameObject.SetActive(value: true);
		}
	}

	public void FinishAnimation()
	{
		timeSinceAbilitySelect = 1000000f;
		timeSinceOpenOrClose = 0f;
		UpdateAnimation();
	}

	public void SetCharacterSprite(Sprite sprite)
	{
		characterImages[2].sprite = sprite;
	}

	public void Init(int playerId)
	{
		player = PlayerHandler.Get().GetPlayer(playerId);
		player.HasAbilitySelectOpenend = false;
		RectTransform[] circles = abilityCirclesParent.Circles;
		abilityListOriginalPositions = new Vector2[circles.Length];
		characterImages = character.GetComponentsInChildren<UnityEngine.UI.Image>(includeInactive: true);
		characterImages[2].material = player.Color;
		for (int i = 0; i < characterImages.Length; i++)
		{
			characterImages[i].color = new UnityEngine.Color(characterImages[i].color.r, characterImages[i].color.g, characterImages[i].color.b, inactiveAlpha);
		}
		YArrowOriginalHeight = arrow.anchoredPosition.y;
		for (int j = 0; j < circles.Length; j++)
		{
			abilityListOriginalPositions[j] = circles[j].anchoredPosition;
			circles[j].anchoredPosition = Vector2.up * abilityCirclesParent.TotalYOffset();
		}
		abilityCirclesParent.SetPlayer(player.Id);
		Material material = UnityEngine.Object.Instantiate(abilityCirclesParent.CircleImages[0].material);
		for (int k = 0; k < abilityCirclesParent.CircleImages.Length; k++)
		{
			abilityCirclesParent.CircleImages[k].material = material;
		}
		for (int l = 0; l < abilityCirclesParent.ArrowImages.Length; l++)
		{
			abilityCirclesParent.ArrowImages[l].material = material;
		}
		abilityCirclesParent.ArrowL.anchoredPosition = new Vector2(abilityCirclesParent.ArrowL.anchoredPosition.x, abilityCirclesParent.TotalYOffset());
		abilityCirclesParent.ArrowR.anchoredPosition = new Vector2(abilityCirclesParent.ArrowL.anchoredPosition.x, abilityCirclesParent.TotalYOffset());
		abilityCirclesParent.gameObject.SetActive(value: false);
		busyDotsParent.gameObject.SetActive(value: false);
		if (GameLobby.isOnlineGame && !player.IsLocalPlayer)
		{
			arrow.gameObject.SetActive(value: false);
		}
		else
		{
			arrow.gameObject.SetActive(value: true);
		}
	}

	private void Start()
	{
		abilityCirclesParent.enabled = false;
		isOpen = false;
		timeSinceOpenOrClose = 0f;
		timeSinceAbilitySelect = 100000f;
		openCloseMenuNextFrame = false;
	}

	public void ClickArrow()
	{
		if (player.UsesKeyboardAndMouse)
		{
			openCloseMenuNextFrame = true;
		}
	}

	private void openCloseMenu()
	{
		if (isOpen)
		{
			float time = OpenAnimation01.keys[OpenAnimation01.keys.Length - 1].time;
			float time2 = OpenAnimation01.keys[OpenAnimation01.keys.Length - 2].time;
			isOpen = false;
			timeSinceAbilitySelect = 0f;
			if (timeSinceOpenOrClose >= time2)
			{
				timeSinceOpenOrClose = time;
			}
			AudioManager.Get().Play("selectAbilities");
			abilityCirclesParent.enabled = false;
		}
		else
		{
			ClickedUp = true;
			for (int i = 0; i < characterImages.Length; i++)
			{
				characterImages[i].color = new UnityEngine.Color(characterImages[i].color.r, characterImages[i].color.g, characterImages[i].color.b, 1f);
			}
			abilityCirclesParent.gameObject.SetActive(value: true);
			arrow.anchoredPosition += Vector2.up * (YArrowOffset + (float)Settings.Get().NumberOfAbilities * YArrowOffsetPerCircle);
			isOpen = true;
			player.HasAbilitySelectOpenend = true;
			abilityCirclesParent.enabled = true;
		}
		UpdateReadyAndAbilityChoices();
	}

	private void UpdateReadyAndAbilityChoices()
	{
		if (!GameLobby.isOnlineGame || player == null || !player.IsLocalPlayer)
		{
			return;
		}
		if (isOpen)
		{
			SteamManager.instance.BroadcastNoLongerReady();
			return;
		}
		int ability = 0;
		int ability2 = 0;
		int ability3 = 0;
		if (player.Abilities.Count > 0)
		{
			ability = abilityCirclesParent.AbilityIcons.IndexOf(player.Abilities[0].name);
		}
		if (player.Abilities.Count > 1)
		{
			ability2 = abilityCirclesParent.AbilityIcons.IndexOf(player.Abilities[1].name);
		}
		if (player.Abilities.Count > 2)
		{
			ability3 = abilityCirclesParent.AbilityIcons.IndexOf(player.Abilities[2].name);
		}
		SteamManager.instance.BroadcastAbilityChoiceUpdate(ability, ability2, ability3);
	}

	private void Update()
	{
		if (int.Parse(ScoreText.text) != player.GamesWon)
		{
			ScoreText.text = player.GamesWon.ToString();
		}
		if (!player.IsLocalPlayer && GameLobby.isOnlineGame)
		{
			List<SteamConnection> connectedPlayers = SteamManager.instance.connectedPlayers;
			for (int i = 0; i < connectedPlayers.Count; i++)
			{
				if ((ulong)connectedPlayers[i].id == (ulong)player.steamId)
				{
					if (connectedPlayers[i].lobby_isReady && busyDotsParent.gameObject.activeSelf)
					{
						busyDotsParent.gameObject.SetActive(value: false);
					}
					else if (!connectedPlayers[i].lobby_isReady && !busyDotsParent.gameObject.activeSelf)
					{
						busyDotsParent.gameObject.SetActive(value: true);
					}
				}
			}
			for (int j = 0; j < dots.Length; j++)
			{
				float num = busyDotsAnimation.Evaluate(Time.unscaledTime + (float)j * animationDuration) * height;
				dots[j].anchoredPosition = new Vector2(dots[j].anchoredPosition.x, originalDotHeights[j] + num);
			}
			return;
		}
		if (openCloseMenuNextFrame)
		{
			openCloseMenu();
		}
		openCloseMenuNextFrame = false;
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		bool flag4 = false;
		bool flag5 = false;
		bool flag6 = false;
		if (player.UsesKeyboardAndMouse)
		{
			Keyboard current = Keyboard.current;
			flag4 = current.enterKey.wasPressedThisFrame || current.spaceKey.wasPressedThisFrame;
			flag = current.escapeKey.wasPressedThisFrame;
			flag5 = current.upArrowKey.wasPressedThisFrame || current.wKey.wasPressedThisFrame;
			flag6 = current.downArrowKey.wasPressedThisFrame || current.sKey.wasPressedThisFrame;
			ClickedUp = false;
		}
		else
		{
			Gamepad gamepad = (Gamepad)player.inputDevice;
			if (gamepad.IsUsable_())
			{
				flag4 = gamepad.startButton.wasPressedThisFrame;
				flag3 = gamepad.buttonSouth.wasPressedThisFrame;
				flag2 = gamepad.buttonEast.wasPressedThisFrame;
				flag = gamepad.selectButton.wasPressedThisFrame;
				Vector2 vector = gamepad.leftStick.ReadValue();
				Vector2 vector2 = gamepad.leftStick.ReadValue();
				Vector2 vector3 = gamepad.dpad.ReadValue();
				flag5 = vector.y * arrowUpSensitivity > (float)Constants.DEADZONE;
				flag5 |= vector2.y * arrowUpSensitivity > (float)Constants.DEADZONE;
				flag5 |= vector3.y * arrowUpSensitivity > (float)Constants.DEADZONE;
				flag6 = vector.y < (float)Constants.DEADZONE;
			}
			else
			{
				flag4 = false;
				flag3 = false;
				flag2 = false;
				flag = false;
				flag5 = false;
				flag6 = false;
			}
		}
		if (timeSinceEnabled > DelayBeforeInputIsTaken)
		{
			if (!isOpen && flag5 && !ClickedUp)
			{
				openCloseMenuNextFrame = true;
			}
			else if (ClickedUp && flag6)
			{
				ClickedUp = false;
			}
			else if (isOpen && (flag || flag2 || flag3 || flag4))
			{
				openCloseMenuNextFrame = true;
			}
		}
		UpdateAnimation();
		timeSinceAbilitySelect += Time.deltaTime;
		timeSinceEnabled += Time.deltaTime;
	}

	private void UpdateAnimation()
	{
		float time = OpenAnimation01.keys[OpenAnimation01.keys.Length - 1].time;
		float num = OpenAnimation01.Evaluate(timeSinceOpenOrClose);
		float num2 = YArrowOriginalHeight + (YArrowOffset + (float)Settings.Get().NumberOfAbilities * YArrowOffsetPerCircle);
		arrow.anchoredPosition = new Vector2(arrow.anchoredPosition.x, YArrowOriginalHeight * (1f - num) + num2 * num);
		Vector2 vector = Vector2.up * abilityCirclesParent.TotalYOffset();
		for (int i = 0; i < abilityCirclesParent.Circles.Length; i++)
		{
			float num3 = 0f;
			num = OpenAnimation01.Evaluate(timeSinceOpenOrClose - num3);
			abilityCirclesParent.Circles[i].anchoredPosition = (1f - num) * vector + num * abilityListOriginalPositions[i];
		}
		abilityCirclesParent.SyncArrowPositionToCurrentYPos();
		if (isOpen)
		{
			timeSinceOpenOrClose = Mathf.Min(time, timeSinceOpenOrClose + Time.deltaTime);
		}
		else
		{
			timeSinceOpenOrClose = Mathf.Max(0f, timeSinceOpenOrClose - Time.deltaTime);
		}
		float num4 = ScaleAnimation.Evaluate(timeSinceAbilitySelect);
		for (int j = 0; j < abilityCirclesParent.Circles.Length; j++)
		{
			abilityCirclesParent.Circles[j].localScale = Vector3.one * num4;
		}
		abilityCirclesParent.CircleImages[0].material.SetFloat("_FlashBlend", Mathf.Clamp01(num4 - 1f));
		if (!abilityCirclesParent.enabled)
		{
			abilityCirclesParent.SyncArrowPositionToCurrentYPos();
			abilityCirclesParent.ArrowR.anchoredPosition += Vector2.right * abilityCirclesParent.ArrowMovementX.Evaluate(timeSinceAbilitySelect * 3f) * 1.5f;
			abilityCirclesParent.ArrowL.anchoredPosition += Vector2.left * abilityCirclesParent.ArrowMovementX.Evaluate(timeSinceAbilitySelect * 3f) * 1.5f;
			arrow.anchoredPosition += Vector2.up * abilityCirclesParent.ArrowMovementX.Evaluate(timeSinceAbilitySelect * 2f);
		}
		if (!isOpen && timeSinceAbilitySelect > ScaleAnimation.keys[ScaleAnimation.keys.Length - 1].time)
		{
			player.HasAbilitySelectOpenend = false;
		}
	}

	public void OnEnable()
	{
		timeSinceEnabled = 0f;
		if (GameLobby.isOnlineGame)
		{
			if (isOpen || openCloseMenuNextFrame)
			{
				openCloseMenu();
				isOpen = false;
				openCloseMenuNextFrame = false;
			}
			else
			{
				UpdateReadyAndAbilityChoices();
			}
		}
	}

	public int GetPlayerId()
	{
		return player.Id;
	}
}
