public class AlphaFade : MonoBehaviour
{
	public AnimationCurve fadeAnimation;

	public bool destroyWhenDone;

	private SpriteRenderer spriteRen;

	private float timePassed;

	private bool isDone;

	public bool IsDone => isDone;

	private void Awake()
	{
		spriteRen = GetComponent<SpriteRenderer>();
	}

	private void Start()
	{
		timePassed = 0f;
	}

	public void RestartAnimation()
	{
		timePassed = 0f;
		spriteRen.color = new UnityEngine.Color(spriteRen.color.r, spriteRen.color.g, spriteRen.color.b, fadeAnimation.Evaluate(timePassed));
		isDone = false;
		base.enabled = true;
	}

	private void Update()
	{
		timePassed += Time.deltaTime;
		spriteRen.color = new UnityEngine.Color(spriteRen.color.r, spriteRen.color.g, spriteRen.color.b, fadeAnimation.Evaluate(timePassed));
		if (timePassed >= fadeAnimation.keys[fadeAnimation.keys.Length - 1].time)
		{
			isDone = true;
			base.enabled = false;
			if (destroyWhenDone)
			{
				UnityEngine.Object.Destroy(base.gameObject);
			}
		}
	}
}
public class AnimateInOutUI : MonoBehaviour
{
	public RectTransform[] animatedTransforms;

	public float startHeight = 1000f;

	public float endHeight = -1000f;

	public AnimationCurve animate01 = AnimationCurve.Linear(0f, 0f, 1f, 1f);

	public bool horizontalInstead;

	public float delay;

	private float[] originalHeights;

	public bool autoCallAnimateInOnStart;

	private bool animatingIn = true;

	private bool reverse;

	private float timeSinceAnimateIn;

	private float timeSinceAnimateOut;

	private void Awake()
	{
		originalHeights = new float[animatedTransforms.Length];
		for (int i = 0; i < animatedTransforms.Length; i++)
		{
			originalHeights[i] = (horizontalInstead ? animatedTransforms[i].anchoredPosition.x : animatedTransforms[i].anchoredPosition.y);
			if (horizontalInstead)
			{
				animatedTransforms[i].anchoredPosition = new Vector2(startHeight, animatedTransforms[i].anchoredPosition.y);
			}
			else
			{
				animatedTransforms[i].anchoredPosition = new Vector2(animatedTransforms[i].anchoredPosition.x, startHeight);
			}
		}
		reverse = true;
		animatingIn = true;
		timeSinceAnimateOut = 0f - delay;
	}

	private void Start()
	{
		if (autoCallAnimateInOnStart)
		{
			AnimateIn();
		}
	}

	public void AnimateIn()
	{
		reverse = false;
		animatingIn = true;
		timeSinceAnimateIn = 0f - delay;
		for (int i = 0; i < animatedTransforms.Length; i++)
		{
			if (horizontalInstead)
			{
				animatedTransforms[i].anchoredPosition = new Vector2(startHeight, animatedTransforms[i].anchoredPosition.y);
			}
			else
			{
				animatedTransforms[i].anchoredPosition = new Vector2(animatedTransforms[i].anchoredPosition.x, startHeight);
			}
		}
	}

	public void AnimateOut()
	{
		animatingIn = false;
		reverse = false;
		timeSinceAnimateOut = 0f - delay;
		for (int i = 0; i < animatedTransforms.Length; i++)
		{
			if (horizontalInstead)
			{
				animatedTransforms[i].anchoredPosition = new Vector2(originalHeights[i], animatedTransforms[i].anchoredPosition.y);
			}
			else
			{
				animatedTransforms[i].anchoredPosition = new Vector2(animatedTransforms[i].anchoredPosition.x, originalHeights[i]);
			}
		}
	}

	public void AnimateIn_reverse()
	{
		reverse = true;
		animatingIn = true;
		timeSinceAnimateIn = animate01.Duration();
		for (int i = 0; i < animatedTransforms.Length; i++)
		{
			if (horizontalInstead)
			{
				animatedTransforms[i].anchoredPosition = new Vector2(originalHeights[i], animatedTransforms[i].anchoredPosition.y);
			}
			else
			{
				animatedTransforms[i].anchoredPosition = new Vector2(animatedTransforms[i].anchoredPosition.x, originalHeights[i]);
			}
		}
	}

	public void AnimateOut_reverse()
	{
		reverse = true;
		animatingIn = false;
		timeSinceAnimateOut = animate01.Duration();
		for (int i = 0; i < animatedTransforms.Length; i++)
		{
			if (horizontalInstead)
			{
				animatedTransforms[i].anchoredPosition = new Vector2(endHeight, animatedTransforms[i].anchoredPosition.y);
			}
			else
			{
				animatedTransforms[i].anchoredPosition = new Vector2(animatedTransforms[i].anchoredPosition.x, endHeight);
			}
		}
	}

	private void UpdatePos(RectTransform rt, float newHeight)
	{
		if (horizontalInstead)
		{
			rt.anchoredPosition = new Vector2(newHeight, rt.anchoredPosition.y);
		}
		else
		{
			rt.anchoredPosition = new Vector2(rt.anchoredPosition.x, newHeight);
		}
	}

	private void Update()
	{
		float num = (horizontalInstead ? animatedTransforms[0].anchoredPosition.x : animatedTransforms[0].anchoredPosition.y);
		if (reverse)
		{
			if (animatingIn && (num <= originalHeights[0] || timeSinceAnimateIn > 0f))
			{
				timeSinceAnimateIn -= Time.deltaTime;
				float t = animate01.Evaluate(timeSinceAnimateIn);
				for (int i = 0; i < animatedTransforms.Length; i++)
				{
					float newHeight = Mathf.LerpUnclamped(startHeight, originalHeights[i], t);
					UpdatePos(animatedTransforms[i], newHeight);
				}
			}
			else if (!animatingIn && (num <= endHeight || timeSinceAnimateOut > 0f))
			{
				timeSinceAnimateOut -= Time.deltaTime;
				float t2 = animate01.Evaluate(timeSinceAnimateOut);
				for (int j = 0; j < animatedTransforms.Length; j++)
				{
					float newHeight2 = Mathf.LerpUnclamped(originalHeights[j], endHeight, t2);
					UpdatePos(animatedTransforms[j], newHeight2);
				}
			}
		}
		else if (animatingIn && (num > originalHeights[0] || timeSinceAnimateIn < animate01.Duration()))
		{
			timeSinceAnimateIn += Time.deltaTime;
			float t3 = animate01.Evaluate(timeSinceAnimateIn);
			for (int k = 0; k < animatedTransforms.Length; k++)
			{
				float newHeight3 = Mathf.LerpUnclamped(startHeight, originalHeights[k], t3);
				UpdatePos(animatedTransforms[k], newHeight3);
			}
		}
		else if (!animatingIn && (num > endHeight || timeSinceAnimateOut < animate01.Duration()))
		{
			timeSinceAnimateOut += Time.deltaTime;
			float t4 = animate01.Evaluate(timeSinceAnimateOut);
			for (int l = 0; l < animatedTransforms.Length; l++)
			{
				float newHeight4 = Mathf.LerpUnclamped(originalHeights[l], endHeight, t4);
				UpdatePos(animatedTransforms[l], newHeight4);
			}
		}
	}
}
public class AnimateInUI : MonoBehaviour
{
	private RectTransform trans;

	private Vector2 OriginalPos;

	public AnimationCurve animateIn;

	public Vector2 direction;

	public RectTransform RecTrans => trans;

	private void Awake()
	{
		trans = GetComponent<RectTransform>();
		if (trans == null)
		{
			OriginalPos = base.transform.position;
		}
		else
		{
			OriginalPos = trans.anchoredPosition;
		}
	}

	private void Update()
	{
		if (trans == null)
		{
			base.transform.position = OriginalPos + direction.normalized * animateIn.Evaluate(Time.timeSinceLevelLoad);
			if (Time.timeSinceLevelLoad >= animateIn.keys[animateIn.length - 1].time)
			{
				base.enabled = false;
			}
			base.transform.position = OriginalPos + direction.normalized * animateIn.Evaluate(Time.timeSinceLevelLoad);
			if (Time.timeSinceLevelLoad >= animateIn.keys[animateIn.length - 1].time)
			{
				base.enabled = false;
			}
		}
		else
		{
			trans.anchoredPosition = OriginalPos + direction.normalized * animateIn.Evaluate(Time.timeSinceLevelLoad);
			if (Time.timeSinceLevelLoad >= animateIn.keys[animateIn.length - 1].time)
			{
				base.enabled = false;
			}
			trans.anchoredPosition = OriginalPos + direction.normalized * animateIn.Evaluate(Time.timeSinceLevelLoad);
			if (Time.timeSinceLevelLoad >= animateIn.keys[animateIn.length - 1].time)
			{
				base.enabled = false;
			}
		}
	}

	public void AnimateOut(float progress, AnimationCurve animateOut)
	{
		if (trans == null)
		{
			base.transform.position = OriginalPos + direction.normalized * animateOut.Evaluate(progress);
		}
		else
		{
			trans.anchoredPosition = OriginalPos + direction.normalized * animateOut.Evaluate(progress);
		}
	}

	private void OnDrawGizmosSelected()
	{
		if (trans == null)
		{
			Gizmos.DrawRay(base.transform.position, direction.normalized * 10f);
		}
		else
		{
			Gizmos.DrawRay(GetComponent<RectTransform>().position, direction.normalized * 10f);
		}
	}
}
public class AnimateScale : MonoBehaviour
{
	public AnimationCurve ScaleX;

	public AnimationCurve ScaleY;

	public float timeScale = 1f;

	private Vector3 origScale;

	private float time;

	private void Start()
	{
	}

	private void Awake()
	{
		origScale = base.transform.localScale;
		time = 0f;
	}

	public void SetOrigScale(Vector3 origScale)
	{
		this.origScale = origScale;
	}

	private void Update()
	{
		time += Time.deltaTime;
		base.transform.localScale = new Vector3(origScale.x * ScaleX.Evaluate(time * timeScale), origScale.y * ScaleY.Evaluate(time * timeScale), origScale.z);
	}
}
public class AnimateTransformUI : MonoBehaviour
{
	public float speed = 1f;

	public AnimationCurve scaleAnim;

	public AnimationCurve rotationAnimDEGREES;

	private float progress;

	public RectTransform[] targets;

	public bool callOnStart;

	private void Start()
	{
		if (callOnStart)
		{
			Animate();
		}
	}

	private void Awake()
	{
		if (targets == null)
		{
			targets = new RectTransform[1] { GetComponent<RectTransform>() };
		}
	}

	public void Animate()
	{
		progress = 0f;
		base.enabled = true;
	}

	public void SetToFinalState()
	{
		progress = scaleAnim.Duration();
		Update();
	}

	private void Update()
	{
		progress += Time.deltaTime;
		float num = scaleAnim.Evaluate(progress * speed);
		float z = rotationAnimDEGREES.Evaluate(progress * speed);
		for (int i = 0; i < targets.Length; i++)
		{
			Vector3 localScale = targets[i].localScale;
			localScale.x = num;
			localScale.y = num;
			targets[i].localScale = localScale;
			Vector3 localEulerAngles = targets[i].localEulerAngles;
			localEulerAngles.z = z;
			targets[i].localEulerAngles = localEulerAngles;
		}
		if (progress > scaleAnim.Duration() && progress > rotationAnimDEGREES.Duration())
		{
			base.enabled = false;
		}
	}
}
