	public void SetInputsEnabled(bool enabled)
	{
		base.enabled = enabled;
		selectables[1].text.enabled = enabled;
		for (int i = 1; i < selectables.Count; i++)
		{
			selectables[i].gameObject.SetActive(enabled);
		}
	}

	private void AdaptToNrOfAbilites(bool animate = false)
	{
		int num = (currentNumberOfAbilites = ((Settings.Get() == null) ? 3 : Settings.Get().NumberOfAbilities));
		int index = 4;
		int index2 = 3;
		int index3 = 2;
		if (num == 1)
		{
			selectables[index2].Skip = true;
			((SelectAbility)selectables[index2]).DisableAbility();
			selectables[index2].gameObject.SetActive(value: false);
		}
		if (num <= 2)
		{
			selectables[index].Skip = true;
			((SelectAbility)selectables[index]).DisableAbility();
			selectables[index].gameObject.SetActive(value: false);
		}
		if (num >= 2)
		{
			selectables[index2].Skip = false;
			((SelectAbility)selectables[index2]).EnableAbility();
			selectables[index2].gameObject.SetActive(value: true);
		}
		if (num == 3)
		{
			selectables[index].Skip = false;
			((SelectAbility)selectables[index]).EnableAbility();
			selectables[index].gameObject.SetActive(value: true);
		}
		switch (num)
		{
		case 1:
		{
			RectTransform component6 = selectables[index3].GetComponent<RectTransform>();
			component6.anchoredPosition = new Vector2(component6.anchoredPosition.x, AbilitySelectYPos1);
			break;
		}
		case 2:
		{
			RectTransform component4 = selectables[index3].GetComponent<RectTransform>();
			component4.anchoredPosition = new Vector2(component4.anchoredPosition.x, AbilitySelectYPos2[0]);
			RectTransform component5 = selectables[index2].GetComponent<RectTransform>();
			component5.anchoredPosition = new Vector2(component5.anchoredPosition.x, AbilitySelectYPos2[1]);
			break;
		}
		case 3:
		{
			RectTransform component = selectables[index3].GetComponent<RectTransform>();
			component.anchoredPosition = new Vector2(component.anchoredPosition.x, originalAbilitySelectPos[0]);
			RectTransform component2 = selectables[index2].GetComponent<RectTransform>();
			component2.anchoredPosition = new Vector2(component2.anchoredPosition.x, originalAbilitySelectPos[1]);
			RectTransform component3 = selectables[index].GetComponent<RectTransform>();
			component3.anchoredPosition = new Vector2(component3.anchoredPosition.x, originalAbilitySelectPos[2]);
			break;
		}
		}
		if (animate)
		{
			for (int i = 0; i < animateSelectables.Length - 1; i++)
			{
				animateSelectables[i].AnimateIn();
			}
		}
		Move(0);
	}

	private void Awake()
	{
		originalAbilitySelectPos = new float[3];
		originalAbilitySelectPos[0] = selectables[2].GetComponent<RectTransform>().anchoredPosition.y;
		originalAbilitySelectPos[1] = selectables[3].GetComponent<RectTransform>().anchoredPosition.y;
		originalAbilitySelectPos[2] = selectables[4].GetComponent<RectTransform>().anchoredPosition.y;
		AdaptToNrOfAbilites();
	}

	public void OnEnterReady()
	{
		if (menuState == CharSelectMenu.select)
		{
			animateSelect.AnimateOut();
			animateReady.AnimateIn();
			for (int i = 0; i < animateReadyBox.Length; i++)
			{
				animateReadyBox[i].AnimateIn();
			}
		}
		menuState = CharSelectMenu.ready;
		Deselect();
		UpdatePlayerInit();
	}

	internal void SetToPlayerChoices(Player player)
	{
		UseskeyboardMouse = player.UsesKeyboardAndMouse;
		joinColor.GetComponent<CharSelectClickToJoin>().LoadPlayerChoice(player);
		occupiedRectangles[RectangleIndex] = true;
		for (int i = 0; i < animateSelectables.Length; i++)
		{
			animateSelectables[i].AnimateIn();
		}
		animateSelect.AnimateIn();
		animateJoin.AnimateOut();
		menuState = CharSelectMenu.select;
		SetSelected(1);
		UpdatePlayerInit();
		for (int j = 0; j < selectables.Count; j++)
		{
			selectables[j].SetToPlayerChoices(player, j - 2);
		}
	}

	public void UpdatePlayerInit()
	{
		if (menuState == CharSelectMenu.join)
		{
			playerInit = default(PlayerInit);
			return;
		}
		playerInit.usesKeyboardMouse = UseskeyboardMouse;
		playerInit.inputDevice = currentGamePad;
		for (int i = 0; i < selectables.Count; i++)
		{
			selectables[i].UpdatePlayerInit(ref playerInit, i - 2);
		}
	}

	public void OnEnterJoin()
	{
		if (UseskeyboardMouse)
		{
			keyboardMouseIsOccupied = false;
		}
		UseskeyboardMouse = false;
		deviceIds[RectangleIndex] = 0;
		occupiedRectangles[RectangleIndex] = false;
		if (menuState == CharSelectMenu.select)
		{
			animateSelect.AnimateIn_reverse();
			animateJoin.AnimateOut_reverse();
			AudioManager.Get().Play("decline");
		}
		menuState = CharSelectMenu.join;
		Deselect();
		UpdatePlayerInit();
	}

	public void OnEnterSelect()
	{
		occupiedRectangles[RectangleIndex] = true;
		if (UseskeyboardMouse)
		{
			rebindImageControllerImage.sprite = keyboardMouseSprite;
		}
		else
		{
			rebindImageControllerImage.sprite = controllerSprite;
		}
		if (menuState == CharSelectMenu.join)
		{
			for (int i = 0; i < animateSelectables.Length; i++)
			{
				animateSelectables[i].AnimateIn();
			}
			animateSelect.AnimateIn();
			animateJoin.AnimateOut();
		}
		else
		{
			for (int j = 0; j < animateSelectables.Length - 1; j++)
			{
				animateSelectables[j].AnimateIn();
			}
			animateSelect.AnimateOut_reverse();
			animateReady.AnimateIn_reverse();
			AudioManager.Get().Play("decline");
		}
		menuState = CharSelectMenu.select;
		SetSelected(1);
		UpdatePlayerInit();
	}

	public void ClickLeft()
	{
		if (menuState == CharSelectMenu.select && UseskeyboardMouse)
		{
			selectables[selectedIndex].Move(goRight: false);
		}
	}

	public void ClickRight()
	{
		if (menuState == CharSelectMenu.select && UseskeyboardMouse)
		{
			selectables[selectedIndex].Move(goRight: true);
		}
	}

	public void SetSelectedHover(int index)
	{
		if (menuState == CharSelectMenu.select && UseskeyboardMouse)
		{
			SetSelected(index);
		}
	}

	public void SetSelected(int index)
	{
		if (!selectables[index].Skip)
		{
			selectables[selectedIndex]?.DeActivate();
			selectables[index]?.Activate();
			selectables[index].Select(-1);
			if (imagesToDisable[selectedIndex] != null)
			{
				imagesToDisable[selectedIndex].enabled = true;
			}
			if (imagesToDisable[index] != null)
			{
				imagesToDisable[index].enabled = false;
			}
			selectedIndex = index;
			float y = selectables[index].GetComponent<RectTransform>().anchoredPosition.y;
			if (index == 0 || index == 6)
			{
				y = -1024f;
			}
			arrows.anchoredPosition = new Vector2(0f, y);
			arrowL.anchoredPosition = new Vector2(0f - arrow_Separation_YPos[index].x, 0f);
			arrowR.anchoredPosition = new Vector2(arrow_Separation_YPos[index].x, 0f);
		}
	}

	public void Deselect()
	{
		selectables[selectedIndex]?.DeActivate();
	}

	private void Move(int movement)
	{
		int num = (selectedIndex + movement + selectables.Count) % selectables.Count;
		if (movement > 0)
		{
			while (selectables[num].Skip)
			{
				num = (num + 1 + selectables.Count) % selectables.Count;
			}
		}
		else
		{
			while (selectables[num].Skip)
			{
				num = (num - 1 + selectables.Count) % selectables.Count;
			}
		}
		SetSelected(num);
	}

	private void Update()
	{
		if (((Settings.Get() == null) ? 3 : Settings.Get().NumberOfAbilities) != currentNumberOfAbilites)
		{
			AdaptToNrOfAbilites(animate: true);
		}
	}

	private void LateUpdate()
	{
		Keyboard current = Keyboard.current;
		UpdatePlayerInit();
		if (!UseskeyboardMouse && currentGamePad == null)
		{
			return;
		}
		if (menuState == CharSelectMenu.select)
		{
			if ((UseskeyboardMouse && (current.wKey.wasPressedThisFrame || current.upArrowKey.wasPressedThisFrame)) || (currentGamePad != null && (currentGamePad.leftStick.up.wasPressedThisFrame || currentGamePad.dpad.up.wasPressedThisFrame)))
			{
				Move(-1);
			}
			else if ((UseskeyboardMouse && (current.sKey.wasPressedThisFrame || current.downArrowKey.wasPressedThisFrame)) || (currentGamePad != null && (currentGamePad.leftStick.down.wasPressedThisFrame || currentGamePad.dpad.down.wasPressedThisFrame)))
			{
				Move(1);
			}
			else if ((UseskeyboardMouse && current.enterKey.wasPressedThisFrame) || (currentGamePad != null && currentGamePad.aButton.wasPressedThisFrame))
			{
				if (selectedIndex == 2 || selectedIndex == 3 || selectedIndex == 4)
				{
					SelectAbility selectAbility = (SelectAbility)selectables[selectedIndex];
					selectAbility.PlayScaleAnimation();
					abilityGrid.Init(UseskeyboardMouse, currentGamePad, selectAbility.SelectedIndex);
					menuState = CharSelectMenu.abilityGrid;
					return;
				}
				if (selectedIndex != 0)
				{
					Move(1);
				}
			}
		}
		if ((UseskeyboardMouse && (current.escapeKey.wasPressedThisFrame || current.backspaceKey.wasPressedThisFrame)) || (currentGamePad != null && (currentGamePad.bButton.wasPressedThisFrame || currentGamePad.selectButton.wasPressedThisFrame)))
		{
			switch (menuState)
			{
			case CharSelectMenu.select:
				OnEnterJoin();
				break;
			case CharSelectMenu.ready:
				OnEnterSelect();
				break;
			case CharSelectMenu.trueReady:
				CharacterSelectHandler_online.CancelLocalReady();
				OnEnterSelect();
				break;
			case CharSelectMenu.abilityGrid:
				menuState = CharSelectMenu.select;
				abilityGrid.DeInit();
				AudioManager.Get().Play("decline");
				break;
			}
		}
		else if (menuState == CharSelectMenu.ready && CharacterSelectHandler.startButtonAvailable)
		{
			if ((UseskeyboardMouse && current.enterKey.wasPressedThisFrame) || (currentGamePad != null && (currentGamePad.aButton.wasPressedThisFrame || currentGamePad.startButton.wasPressedThisFrame)))
			{
				CharacterSelectHandler.TryStartGame();
			}
		}
		else if (menuState == CharSelectMenu.trueReady && CharacterSelectHandler_online.startButtonAvailable)
		{
			if ((UseskeyboardMouse && current.enterKey.wasPressedThisFrame) || (currentGamePad != null && (currentGamePad.aButton.wasPressedThisFrame || currentGamePad.startButton.wasPressedThisFrame)))
			{
				CharacterSelectHandler_online.TryStartGame();
			}
		}
		else if (menuState == CharSelectMenu.abilityGrid && ((UseskeyboardMouse && current.enterKey.wasPressedThisFrame) || (currentGamePad != null && (currentGamePad.startButton.wasPressedThisFrame || currentGamePad.aButton.wasPressedThisFrame))))
		{
			CloseAbilityGrid(abilityGrid.SelectedIcon + 1);
		}
	}

	public void CloseAbilityGrid(int abilityChoice)
	{
		if (SteamManager.instance.dlc.HasDLC() || abilityChoice < abilityGrid.abilityIcons_demo.sprites.Count)
		{
			selectables[selectedIndex].Select(abilityChoice);
			((SelectAbility)selectables[selectedIndex]).PlayDelayedScaleAnimation(0.1f);
			abilityGrid.DeInit();
			menuState = CharSelectMenu.select;
			AudioManager.Get().Play("accept");
		}
	}

	public void ClickEnterAbilityGrid()
	{
		if (UseskeyboardMouse)
		{
			EnterAbilityGrid();
		}
	}

	public void EnterAbilityGrid()
	{
		if (menuState == CharSelectMenu.select)
		{
			SelectAbility selectAbility = (SelectAbility)selectables[selectedIndex];
			selectAbility.PlayScaleAnimation();
			abilityGrid.Init(UseskeyboardMouse, currentGamePad, selectAbility.SelectedIndex);
			menuState = CharSelectMenu.abilityGrid;
		}
	}
}
public class CharacterSelectHandler : MonoBehaviour
{
	public CharacterSelectBox[] characterSelectBoxes;

	public TextMeshProUGUI startText;

	public UnityEngine.UI.Image startBorder;

	public AnimateInOutUI startButton;

	public UnityEngine.Color blue;

	public UnityEngine.Color darkBlue;

	public UnityEngine.Color orange;

	public static bool startButtonAvailable;

	[SerializeField]
	private PlayerColors playerColors;

	private static CharacterSelectHandler selfRef;

	private static bool allReadyForMoreThanOneFrame;

	public float AnimateOutSpeed = 1f;

	public float BackDelay = 0.4f;

	public Vector2 center;

	private UnityEngine.AsyncOperation goingBackOperation;

	private float timeSinceBacking;

	private RectTransform rectTransform;

	[SerializeField]
	private float[] animateOutDelays;

	private float timeSinceHover;

	public float fadeSpeed = 10f;

	private bool isHovering;

	public void HoverStartButton()
	{
		isHovering = true;
		timeSinceHover = 0f;
	}

	public void DeHoverStartButton()
	{
		isHovering = false;
		timeSinceHover = Mathf.Min(timeSinceHover, 1f / fadeSpeed);
	}

	public void ClickStartButton()
	{
		TryStartGame();
	}

	public static void TryStartGame()
	{
		selfRef.TryStartGame_inner();
	}

	private void TryStartGame_inner()
	{
		if (!startButtonAvailable || !allReadyForMoreThanOneFrame)
		{
			return;
		}
		AudioManager.Get()?.Play("startGame");
		startButtonAvailable = false;
		List<Player> list = PlayerHandler.Get().PlayerList();
		list.Clear();
		int num = 1;
		NamedSpriteList abilityIcons = SteamManager.instance.abilityIcons;
		for (int i = 0; i < characterSelectBoxes.Length; i++)
		{
			if (characterSelectBoxes[i].menuState == CharSelectMenu.ready)
			{
				PlayerInit playerInit = characterSelectBoxes[i].playerInit;
				Player player = new Player(num, playerInit.team);
				player.Color = playerColors[playerInit.color].playerMaterial;
				player.UsesKeyboardAndMouse = playerInit.usesKeyboardMouse;
				player.CanUseAbilities = true;
				player.inputDevice = playerInit.inputDevice;
				player.Abilities = new List<GameObject>(3);
				player.AbilityIcons = new List<Sprite>(3);
				player.Abilities.Add(abilityIcons.sprites[playerInit.ability0].associatedGameObject);
				player.AbilityIcons.Add(abilityIcons.sprites[playerInit.ability0].sprite);
				Settings settings = Settings.Get();
				if ((object)settings != null && settings.NumberOfAbilities > 1)
				{
					player.Abilities.Add(abilityIcons.sprites[playerInit.ability1].associatedGameObject);
					player.AbilityIcons.Add(abilityIcons.sprites[playerInit.ability1].sprite);
				}
				Settings settings2 = Settings.Get();
				if ((object)settings2 != null && settings2.NumberOfAbilities > 2)
				{
					player.Abilities.Add(abilityIcons.sprites[playerInit.ability2].associatedGameObject);
					player.AbilityIcons.Add(abilityIcons.sprites[playerInit.ability2].sprite);
				}
				player.CustomKeyBinding = playerInit.keybindOverride;
				num++;
				list.Add(player);
			}
		}
		GameSession.Init();
		SceneManager.LoadScene("Level1");
		if (!WinnerTriangleCanvas.HasBeenSpawned)
		{
			SceneManager.LoadScene("winnerTriangle", LoadSceneMode.Additive);
		}
	}

	public static bool IsColorTaken(int playerColor, CharacterSelectBox IgnoredCSB)
	{
		for (int i = 0; i < selfRef.characterSelectBoxes.Length; i++)
		{
			if (!(selfRef.characterSelectBoxes[i] == IgnoredCSB) && selfRef.characterSelectBoxes[i].menuState == CharSelectMenu.ready && selfRef.characterSelectBoxes[i].playerInit.color == playerColor)
			{
				return true;
			}
		}
		return false;
	}

	private void Awake()
	{
		Application.targetFrameRate = 300;
		GameLobby.isOnlineGame = false;
		startButtonAvailable = false;
		selfRef = this;
		for (int i = 0; i < CharacterSelectBox.occupiedRectangles.Length; i++)
		{
			CharacterSelectBox.occupiedRectangles[i] = false;
		}
		for (int j = 0; j < CharacterSelectBox.deviceIds.Length; j++)
		{
			CharacterSelectBox.deviceIds[j] = 0;
		}
		for (int k = 0; k < characterSelectBoxes.Length; k++)
		{
			characterSelectBoxes[k].UseskeyboardMouse = false;
			characterSelectBoxes[k].currentGamePad = null;
		}
		CharacterSelectBox.keyboardMouseIsOccupied = false;
		SteamFrame.SetHidden(!SteamManager.currentlyLookingForPlayers);
	}

	private void Start()
	{
		GameLobby.isOnlineGame = false;
		LoadPreviousChoices();
		AudioManager.Get()?.OnEnteredMenus();
		GameSession.inMenus = true;
		if (GameLobby.isOnlineGame && SteamManager.LocalPlayerIsLobbyOwner)
		{
			SteamManager.instance.currentLobby.SetJoinable(b: true);
		}
	}

	private void LoadPreviousChoices()
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		if (list.Count != 0)
		{
			for (int i = 0; i < list.Count; i++)
			{
				Player toPlayerChoices = list[i];
				characterSelectBoxes[i].SetToPlayerChoices(toPlayerChoices);
			}
		}
	}

	private void Update()
	{
		if (goingBackOperation != null)
		{
			timeSinceBacking += Time.deltaTime;
			if (timeSinceBacking >= BackDelay)
			{
				goingBackOperation.allowSceneActivation = true;
				return;
			}
			_ = AnimateOutSpeed;
			_ = Time.deltaTime;
			for (int i = 0; i < characterSelectBoxes.Length; i++)
			{
				if (timeSinceBacking > animateOutDelays[i])
				{
					RectTransform component = characterSelectBoxes[i].GetComponent<RectTransform>();
					component.anchoredPosition += (component.anchoredPosition - center).normalized * AnimateOutSpeed * timeSinceBacking;
				}
			}
			return;
		}
		Keyboard current = Keyboard.current;
		bool flag = false;
		foreach (Gamepad item in Gamepad.all)
		{
			bool flag2 = true;
			for (int j = 0; j < CharacterSelectBox.deviceIds.Length; j++)
			{
				flag2 &= CharacterSelectBox.deviceIds[j] != item.deviceId;
			}
			if (flag2 && item.selectButton.wasPressedThisFrame)
			{
				flag = true;
			}
		}
		bool flag3 = !CharacterSelectBox.keyboardMouseIsOccupied && (current.escapeKey.wasPressedThisFrame || current.backspaceKey.wasPressedThisFrame);
		if (flag || flag3)
		{
			PlayerHandler.Get().SetPlayerList(new List<Player>());
			goingBackOperation = SceneManager.LoadSceneAsync("MainMenu");
			AudioManager.Get()?.Play("return");
			AudioManager.Get()?.Play("menuWhoosh2");
			goingBackOperation.allowSceneActivation = false;
			if (startButtonAvailable)
			{
				startButton.AnimateOut();
			}
			for (int k = 0; k < characterSelectBoxes.Length; k++)
			{
				characterSelectBoxes[k].enabled = false;
			}
			return;
		}
		bool flag4 = startButtonAvailable;
		bool flag5 = false;
		bool flag6 = true;
		bool flag7 = false;
		int num = 0;
		for (int l = 0; l < characterSelectBoxes.Length; l++)
		{
			if (characterSelectBoxes[l].menuState == CharSelectMenu.ready)
			{
				flag7 = true;
				num++;
			}
			else if (characterSelectBoxes[l].menuState == CharSelectMenu.select || characterSelectBoxes[l].menuState == CharSelectMenu.abilityGrid)
			{
				flag6 = false;
			}
			for (int m = 0; m < characterSelectBoxes.Length; m++)
			{
				if (characterSelectBoxes[l].playerInit.team != characterSelectBoxes[m].playerInit.team && l != m && characterSelectBoxes[m].menuState == CharSelectMenu.ready && characterSelectBoxes[l].menuState == CharSelectMenu.ready)
				{
					flag5 = true;
				}
			}
		}
		if ((flag6 && flag7 && flag5) || (num == 1 && flag6 && flag7))
		{
			if (!startButtonAvailable)
			{
				startButton.AnimateIn();
				startButtonAvailable = true;
			}
		}
		else
		{
			if (startButtonAvailable)
			{
				startButton.AnimateIn_reverse();
				startButtonAvailable = false;
			}
			allReadyForMoreThanOneFrame = false;
		}
		if (startButtonAvailable && flag4)
		{
			allReadyForMoreThanOneFrame = true;
		}
		float t = timeSinceHover * fadeSpeed;
		if (isHovering)
		{
			timeSinceHover += Time.deltaTime;
		}
		else
		{
			timeSinceHover -= Time.deltaTime;
		}
		startText.color = UnityEngine.Color.Lerp(darkBlue, UnityEngine.Color.white, t);
		startBorder.color = UnityEngine.Color.Lerp(blue, orange, t);
	}
}
