	private bool CanClickFindPlayers()
	{
		if (SteamClient.IsValid && SteamClient.IsLoggedOn && (ulong)SteamManager.instance.currentLobby.Id != 0L && SteamManager.instance.currentLobby.Owner.IsMe)
		{
			return !hasMods;
		}
		return false;
	}

	public static void TryFindPlayers()
	{
		if (!SteamManager.currentlyLookingForPlayers)
		{
			SteamManager.instance.currentLobby.SetData("LFM", "1");
			MonoBehaviour.print("finding players..");
		}
		else
		{
			SteamManager.instance.currentLobby.SetData("LFM", "0");
			MonoBehaviour.print("stopped looking for players");
		}
		if (selfRef != null)
		{
			selfRef.findPlayersText.enabled = !SteamManager.currentlyLookingForPlayers;
			selfRef.findPlayersStopText.enabled = SteamManager.currentlyLookingForPlayers;
		}
	}

	public static void TryStartGame(bool errorSoundIfFail = true)
	{
		if (startButtonAvailable && allReadyForMoreThanOneFrame && !selfRef.isStartingAGame)
		{
			if (SteamManager.instance.currentLobby.IsOwnedBy(SteamClient.SteamId))
			{
				selfRef.isStartingAGame = true;
				SteamManager.instance.HostGame(selfRef.characterSelectBox.playerInit);
				ForceStartGame();
			}
			else
			{
				SteamManager.instance.SendStartSuggest();
			}
		}
		else if (errorSoundIfFail)
		{
			_ = startButtonAvailable;
		}
	}

	private static Player InitPlayer(int id, byte color, byte team, byte ability1, byte ability2, byte ability3, int nrOfAbilities, PlayerColors playerColors)
	{
		NamedSpriteList abilityIcons = SteamManager.instance.abilityIcons;
		Player player = new Player();
		player.Id = id;
		player.Color = playerColors.playerColors[color].playerMaterial;
		player.Team = team;
		if (nrOfAbilities > 0)
		{
			player.Abilities.Add(abilityIcons.sprites[ability1].associatedGameObject);
			player.AbilityIcons.Add(abilityIcons.sprites[ability1].sprite);
		}
		if (nrOfAbilities > 1)
		{
			player.Abilities.Add(abilityIcons.sprites[ability2].associatedGameObject);
			player.AbilityIcons.Add(abilityIcons.sprites[ability2].sprite);
		}
		if (nrOfAbilities > 2)
		{
			player.Abilities.Add(abilityIcons.sprites[ability3].associatedGameObject);
			player.AbilityIcons.Add(abilityIcons.sprites[ability3].sprite);
		}
		player.IsLocalPlayer = false;
		return player;
	}

