		else if (startParameters.p2_id == (ulong)SteamClient.SteamId)
		{
			for (int j = 0; j < list.Count; j++)
			{
				if (list[j].Id == 2)
				{
					player = list[j];
					break;
				}
			}
		}
		else if (startParameters.p3_id == (ulong)SteamClient.SteamId)
		{
			for (int k = 0; k < list.Count; k++)
			{
				if (list[k].Id == 3)
				{
					player = list[k];
					break;
				}
			}
		}
		else if (startParameters.p4_id == (ulong)SteamClient.SteamId)
		{
			for (int l = 0; l < list.Count; l++)
			{
				if (list[l].Id == 4)
				{
					player = list[l];
					break;
				}
			}
		}
		for (int m = 0; m < list.Count; m++)
		{
			switch (list[m].Id)
			{
			case 1:
				list[m].steamId = startParameters.p1_id;
				break;
			case 2:
				list[m].steamId = startParameters.p2_id;
				break;
			case 3:
				list[m].steamId = startParameters.p3_id;
				break;
			case 4:
				list[m].steamId = startParameters.p4_id;
				break;
			}
		}
		player.IsLocalPlayer = true;
		player.inputDevice = localPlayerInit.inputDevice;
		player.UsesKeyboardAndMouse = localPlayerInit.usesKeyboardMouse;
		player.CustomKeyBinding = localPlayerInit.keybindOverride;
		startButtonAvailable = false;
		PlayerHandler.Get().SetPlayerList(list);
		SteamManager.instance.StartHostedGame();
		AudioManager.Get()?.Play("startGame");
		GameSession.Init();
		if (GameLobby.isPlayingAReplay)
		{
			SceneManager.LoadScene(startParameters.currentLevel + 6);
		}
		else
		{
			SceneManager.LoadScene("Level1");
		}
		if (!WinnerTriangleCanvas.HasBeenSpawned)
		{
			SceneManager.LoadScene("winnerTriangle", LoadSceneMode.Additive);
		}
	}

