	public static bool IsColorTaken(int playerColor, bool includeLocalChoice = false)
	{
		List<SteamConnection> connectedPlayers = SteamManager.instance.connectedPlayers;
		for (int i = 0; i < connectedPlayers.Count; i++)
		{
			if (connectedPlayers[i].lobby_isReady && connectedPlayers[i].lobby_color == playerColor)
			{
				return true;
			}
		}
		if (includeLocalChoice)
		{
			if (selfRef != null && selfRef.characterSelectBox != null && selfRef.characterSelectBox.menuState == CharSelectMenu.trueReady)
			{
				return selfRef.characterSelectBox.playerInit.color == playerColor;
			}
			return false;
		}
		return false;
	}

