	public static void CheckForMods()
	{
		GameObject gameObject = GameObject.Find("BepInEx_Manager");
		if (gameObject != null)
		{
			if (gameObject.GetComponents(typeof(UnityEngine.Component)).Length > clientSideMods_you_can_increment_this_to_enable_matchmaking_for_your_mods__please_dont_use_it_to_cheat_thats_really_cringe_especially_if_its_desyncing_others___you_didnt_even_win_on_your_opponents_screen___I_cannot_imagine_a_sadder_existence + 1)
			{
				hasMods = true;
			}
			else
			{
				hasMods = false;
			}
		}
		else
		{
			hasMods = false;
		}
	}

	private void Start()
	{
		CheckForMods();
		GameLobby.isOnlineGame = true;
		isStartingAGame = false;
		if (SteamManager.instance.currentLobby.IsOwnedBy(SteamClient.SteamId))
		{
			characterSelectBox.selectables[1].Select(0);
		}
		else
		{
			for (byte b = 1; b < 4; b++)
			{
				bool flag = false;
				for (int i = 0; i < SteamManager.instance.connectedPlayers.Count; i++)
				{
					SteamConnection steamConnection = SteamManager.instance.connectedPlayers[i];
					flag |= steamConnection.lobby_team == b;
				}
				if (!flag)
				{
					characterSelectBox.selectables[1].Select(b);
					break;
				}
			}
		}
		LoadPreviousChoices();
		AudioManager.Get()?.OnEnteredMenus();
		Updater.PreLevelLoad();
		GameSession.inMenus = true;
		if (GameLobby.isOnlineGame && SteamManager.LocalPlayerIsLobbyOwner)
		{
			SteamManager.instance.currentLobby.SetJoinable(b: true);
		}
		startButton.AnimateIn();
		findPlayersButton.AnimateIn();
	}

	private void LoadPreviousChoices()
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		if (list.Count == 0)
		{
			return;
		}
		for (int i = 0; i < list.Count; i++)
		{
			Player player = list[i];
			if (player.IsLocalPlayer)
			{
				characterSelectBox.SetToPlayerChoices(player);
				break;
			}
		}
	}

