	private void Update()
	{
		List<SteamConnection> connectedPlayers = SteamManager.instance.connectedPlayers;
		for (int i = 0; i < connectedPlayers.Count; i++)
		{
			bool flag = false;
			if (connectedPlayers[i].Connected)
			{
				for (int j = 0; j < networkPlayerBoxes.Length; j++)
				{
					if (connectedPlayers[i] == networkPlayerBoxes[j].connectedPlayer && networkPlayerBoxes[j].connectedPlayer.Connected)
					{
						flag = true;
					}
				}
			}
			else
			{
				flag = true;
			}
			if (flag)
			{
				continue;
			}
			for (int k = 0; k < networkPlayerBoxes.Length; k++)
			{
				if (!networkPlayerBoxes[k].isVisible)
				{
					networkPlayerBoxes[k].Init(connectedPlayers[i]);
					break;
				}
			}
		}
		timeSinceLastBroadcast += Time.deltaTime;
		if (characterSelectBox.menuState == CharSelectMenu.select && timeSinceLastBroadcast > 1f / maxBroadcastsPerSecond)
		{
			SteamManager.instance.BroadcastLobbyStateUpdate(new LobbyStateUpdate
			{
				color = (byte)characterSelectBox.playerInit.color,
				team = (byte)characterSelectBox.playerInit.team,
				isReady = 0
			});
			timeSinceLastBroadcast = 0f;
		}
		else if (characterSelectBox.menuState == CharSelectMenu.trueReady && timeSinceLastBroadcast > 2f / maxBroadcastsPerSecond)
		{
			SteamManager.instance.BroadcastLobbyStateUpdate(new LobbyStateUpdate
			{
				color = (byte)characterSelectBox.playerInit.color,
				team = (byte)characterSelectBox.playerInit.team,
				isReady = 1
			});
			timeSinceLastBroadcast = 0f;
		}
		if (characterSelectBox.menuState == CharSelectMenu.ready && !awaitingReadyResponse)
		{
			PlayerInit playerInit = characterSelectBox.playerInit;
			LobbyReadyPacket packet = new LobbyReadyPacket
			{
				ability1 = (byte)playerInit.ability0,
				ability2 = (byte)playerInit.ability1,
				ability3 = (byte)playerInit.ability2,
				color = (byte)playerInit.color,
				team = (byte)playerInit.team,
				usesKeyboardAndMouse = (byte)(characterSelectBox.UseskeyboardMouse ? 1 : 0),
				ownsFullGame = (byte)(SteamManager.instance.dlc.HasDLC() ? 1u : 0u),
				steamId = SteamClient.SteamId
			};
			if (SteamManager.instance.currentLobby.IsOwnedBy(SteamClient.SteamId))
			{
				localPlayerInit = selfRef.characterSelectBox.playerInit;
				SteamManager.instance.BroadcastLobbyReadyPacket(packet);
				selfRef.characterSelectBox.menuState = CharSelectMenu.trueReady;
				awaitingReadyResponse = false;
			}
			else
			{
				SteamManager.instance.SendLobbyReadyRequest(packet);
				awaitingReadyResponse = true;
			}
		}
		if (!SteamManager.currentlyLookingForPlayers || goingBackOperation != null)
		{
			for (int l = 0; l < loadingCircles.Length; l++)
			{
				loadingCircles[l].enabled = false;
			}
		}
		else
		{
			for (int m = 0; m < loadingCircles.Length; m++)
			{
				loadingCircles[m].enabled = !networkPlayerBoxes[m].isVisible;
				if (loadingCircles[m].enabled)
				{
					loadingCircles[m].rectTransform.eulerAngles += new Vector3(0f, 0f, loadingCircleRotationSpeed * 200f * Time.deltaTime);
				}
			}
		}
		if (selfRef != null)
		{
			selfRef.findPlayersText.enabled = !SteamManager.currentlyLookingForPlayers;
			selfRef.findPlayersStopText.enabled = SteamManager.currentlyLookingForPlayers;
		}
		if (goingBackOperation != null)
		{
			timeSinceBacking += Time.deltaTime;
			if (timeSinceBacking >= BackDelay)
			{
				goingBackOperation.allowSceneActivation = true;
				return;
			}
			_ = AnimateOutSpeed;
			_ = Time.deltaTime;
			if (timeSinceBacking > animateOutDelays[0])
			{
				RectTransform component = characterSelectBox.GetComponent<RectTransform>();
				component.anchoredPosition += (component.anchoredPosition - center).normalized * AnimateOutSpeed * timeSinceBacking;
			}
			return;
		}
		Keyboard current = Keyboard.current;
		bool flag2 = false;
		foreach (Gamepad item in Gamepad.all)
		{
			bool flag3 = true;
			for (int n = 0; n < CharacterSelectBox.deviceIds.Length; n++)
			{
				flag3 &= CharacterSelectBox.deviceIds[n] != item.deviceId;
			}
			if (flag3 && item.selectButton.wasPressedThisFrame)
			{
				flag2 = true;
			}
		}
		if (characterSelectBox.currentGamePad != null && (characterSelectBox.menuState == CharSelectMenu.ready || characterSelectBox.menuState == CharSelectMenu.trueReady) && (prevMenuState == CharSelectMenu.ready || prevMenuState == CharSelectMenu.trueReady))
		{
			Gamepad currentGamePad = characterSelectBox.currentGamePad;
			if (!isHoveringFind && !isHoveringStart)
			{
				HoverFindButton();
				selectedStartButton = false;
			}
			if (currentGamePad.startButton.wasPressedThisFrame || currentGamePad.aButton.wasPressedThisFrame)
			{
				if (selectedStartButton)
				{
					ClickStartButton();
				}
				else
				{
					ClickFindButton();
				}
			}
			if (currentGamePad.leftStick.right.wasPressedThisFrame || currentGamePad.dpad.right.wasPressedThisFrame || currentGamePad.leftStick.left.wasPressedThisFrame || currentGamePad.dpad.left.wasPressedThisFrame)
			{
				selectedStartButton = !selectedStartButton;
				if (selectedStartButton)
				{
					HoverStartButton();
					DeHoverFindButton();
				}
				else
				{
					HoverFindButton();
					DeHoverStartButton();
				}
			}
		}
		bool flag4 = !CharacterSelectBox.keyboardMouseIsOccupied && (current.escapeKey.wasPressedThisFrame || current.backspaceKey.wasPressedThisFrame);
		if (flag2 || flag4)
		{
			PlayerHandler.Get().SetPlayerList(new List<Player>());
			goingBackOperation = SceneManager.LoadSceneAsync("MainMenu");
			AudioManager.Get()?.Play("return");
			AudioManager.Get()?.Play("menuWhoosh2");
			goingBackOperation.allowSceneActivation = false;
			startButton.AnimateOut();
			findPlayersButton.AnimateOut();
			for (int num = 0; num < networkPlayerBoxes.Length; num++)
			{
				if (networkPlayerBoxes[num].isVisible)
				{
					networkPlayerBoxes[num].AnimateOut();
				}
			}
			characterSelectBox.enabled = false;
			return;
		}
		bool flag5 = startButtonAvailable;
		bool flag6 = false;
		bool flag7 = true;
		bool flag8 = false;
		if (characterSelectBox.menuState == CharSelectMenu.trueReady)
		{
			flag8 = true;
		}
		else if (characterSelectBox.menuState == CharSelectMenu.select || characterSelectBox.menuState == CharSelectMenu.abilityGrid)
		{
			flag7 = false;
		}
		for (int num2 = 0; num2 < connectedPlayers.Count; num2++)
		{
			SteamConnection steamConnection = connectedPlayers[num2];
			if (steamConnection.lobby_isReady)
			{
				flag8 = true;
			}
			else
			{
				flag7 = false;
			}
			for (int num3 = 0; num3 < connectedPlayers.Count; num3++)
			{
				SteamConnection steamConnection2 = connectedPlayers[num3];
				if (num2 != num3 && steamConnection.lobby_isReady && steamConnection2.lobby_isReady && steamConnection.lobby_team != steamConnection2.lobby_team)
				{
					flag6 = true;
				}
			}
			if (steamConnection.lobby_isReady && characterSelectBox.menuState == CharSelectMenu.trueReady && steamConnection.lobby_team != characterSelectBox.playerInit.team)
			{
				flag6 = true;
			}
		}
		bool flag9 = characterSelectBox.menuState == CharSelectMenu.ready || characterSelectBox.menuState == CharSelectMenu.trueReady;
		if (flag7 && flag8 && flag6 && flag9)
		{
			if (!startButtonAvailable)
			{
				startButtonAvailable = true;
			}
		}
		else
		{
			if (startButtonAvailable)
			{
				startButtonAvailable = false;
			}
			allReadyForMoreThanOneFrame = false;
		}
		if (startButtonAvailable && flag5)
		{
			allReadyForMoreThanOneFrame = true;
		}
		float t = timeSinceHoverStart * fadeSpeed;
		if (isHoveringStart)
		{
			timeSinceHoverStart += Time.deltaTime;
		}
		else
		{
			timeSinceHoverStart -= Time.deltaTime;
		}
		if (startButtonAvailable)
		{
			startText.color = UnityEngine.Color.Lerp(darkBlue, UnityEngine.Color.white, t);
			startBorder.color = UnityEngine.Color.Lerp(blue, orange, t);
		}
		else
		{
			startText.color = UnityEngine.Color.Lerp(disabledDarkBlue, disabledWhite, t);
			startBorder.color = UnityEngine.Color.Lerp(disabledBlue, disabledOrange, t);
		}
		float t2 = timeSinceHoverFind * fadeSpeed;
		if (isHoveringFind)
		{
			timeSinceHoverFind += Time.deltaTime;
		}
		else
		{
			timeSinceHoverFind -= Time.deltaTime;
		}
		if (CanClickFindPlayers())
		{
			findPlayersText.color = UnityEngine.Color.Lerp(darkBlue, UnityEngine.Color.white, t2);
			findPlayersStopText.color = UnityEngine.Color.Lerp(darkBlue, UnityEngine.Color.white, t2);
			findPlayersBorder.color = UnityEngine.Color.Lerp(blue, orange, t2);
		}
		else
		{
			findPlayersText.color = UnityEngine.Color.Lerp(disabledDarkBlue, disabledWhite, t2);
			findPlayersStopText.color = UnityEngine.Color.Lerp(disabledDarkBlue, UnityEngine.Color.white, t2);
			findPlayersBorder.color = UnityEngine.Color.Lerp(disabledBlue, disabledOrange, t2);
		}
		prevMenuState = characterSelectBox.menuState;
	}
}
public class PlayerSorter : IComparer<Player>
{
	public int Compare(Player x, Player y)
	{
		if (x.IsMostRecentWinner && y.IsMostRecentWinner)
		{
			return 0;
		}
		if (x.IsMostRecentWinner)
		{
			return -1000000;
		}
		if (y.IsMostRecentWinner)
		{
			return 1000000;
		}
		return y.GamesWon - x.GamesWon;
	}
}
