	private IEnumerator DelayedActivate(GameObject obj, float StartDelay)
	{
		yield return new WaitForSeconds(StartDelay);
		obj.SetActive(value: true);
		obj.GetComponent<Animator>().SetBool("visible", value: true);
	}

	private IEnumerator DelayedRemove(GameObject obj, float StartDelay, float DestructionDelay)
	{
		yield return new WaitForSeconds(StartDelay);
		obj.GetComponent<Animator>().SetBool("visible", value: false);
		yield return new WaitForSeconds(DestructionDelay);
		Updater.DestroyFix(obj);
	}

	private IEnumerator DelayedDeactivate(GameObject obj, float StartDelay, float DeactivationDelay)
	{
		yield return new WaitForSeconds(StartDelay);
		obj.GetComponent<Animator>().SetBool("visible", value: false);
		yield return new WaitForSeconds(DeactivationDelay);
		obj.SetActive(value: false);
	}

