	{
	}

	public void OnExitHover_AbilitySelect()
	{
	}

	public void OnClick_NextLevel()
	{
		if (isLoading || timeSinceDisabled <= TimeBeforeInputsAreAllowed)
		{
			return;
		}
		List<Player> list = PlayerHandler.Get().PlayerList();
		bool flag = true;
		int blockedPlayerId = -1;
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].UsesKeyboardAndMouse)
			{
				blockedPlayerId = list[i].Id;
			}
		}
		if (GameLobby.isOnlineGame)
		{
			for (int j = 0; j < list.Count; j++)
			{
				if (list[j].IsLocalPlayer)
				{
					flag &= !list[j].HasAbilitySelectOpenend;
				}
			}
			List<SteamConnection> connectedPlayers = SteamManager.instance.connectedPlayers;
			for (int k = 0; k < connectedPlayers.Count; k++)
			{
				bool flag2 = false;
				for (int l = 0; l < list.Count; l++)
				{
					if ((ulong)list[l].steamId == (ulong)connectedPlayers[k].id)
					{
						flag2 = list[l].WonThisRound;
					}
				}
				flag &= flag2 || connectedPlayers[k].lobby_isReady;
			}
			Player player = null;
			for (int m = 0; m < list.Count; m++)
			{
				if (list[m].IsLocalPlayer)
				{
					player = list[m];
				}
			}
			if (GameSession.IsInitialized())
			{
				TryStartNextLevel_online(flag, player.Id);
			}
		}
		else
		{
			for (int n = 0; n < list.Count; n++)
			{
				flag &= !list[n].HasAbilitySelectOpenend;
			}
			if (flag)
			{
				AudioManager.Get().Play("startGame");
				isLoading = true;
				Transition();
				GameSessionHandler.LoadNextLevelScene();
			}
			else
			{
				abilitySelectUi.NotifySomeoneIsBlockedByOpenAbilityList(blockedPlayerId);
			}
		}
	}

	public void OnClick_AbilitySelect()
	{
		if (isLoading || timeSinceDisabled <= TimeBeforeInputsAreAllowed)
		{
			return;
		}
		List<Player> list = PlayerHandler.Get().PlayerList();
		bool flag = true;
		int blockedPlayerId = -1;
		for (int i = 0; i < list.Count; i++)
		{
			flag &= !list[i].HasAbilitySelectOpenend;
			if (list[i].UsesKeyboardAndMouse)
			{
				blockedPlayerId = list[i].Id;
			}
		}
		if (GameLobby.isOnlineGame)
		{
			Player player = null;
			for (int j = 0; j < list.Count; j++)
			{
				if (list[j].IsLocalPlayer)
				{
					player = list[j];
				}
			}
			if (GameSession.IsInitialized())
			{
				TryReturnToAbilitySelect_online(flag, player.Id);
			}
		}
		else if (flag)
		{
			isLoading = true;
			Transition();
			GameSessionHandler.LoadAbilitySelectScene();
		}
		else
		{
			abilitySelectUi.NotifySomeoneIsBlockedByOpenAbilityList(blockedPlayerId);
		}
	}

	public static void ForceBackToAbilitySelect()
	{
		if (!hostRequestsNextLevelLoad)
		{
			hostRequestsBackToAbilitySelect = true;
		}
	}

	public static void ForceNextLevelLoad()
	{
		if (!hostRequestsBackToAbilitySelect)
		{
			hostRequestsNextLevelLoad = true;
		}
	}

	public static void OnNextLevelWasSuggested(int hostPlayerId, NamedSpriteList AbilityIcons)
	{
		if (GameSessionHandler.GameIsPaused)
		{
			someoneSuggestedNextLevel = true;
			return;
		}
		SteamManager.instance.HostNextLevel(PlayerHandler.Get().GetPlayer(hostPlayerId), AbilityIcons);
		ForceNextLevelImmediately();
	}

	public static void SuggestBacktoAbilitySelect()
	{
		someoneSuggestedBacktoAbilitySelect = true;
	}

	private void TryStartNextLevel_online(bool allReady, int startedId)
	{
		if (allReady)
		{
			if (SteamManager.LocalPlayerIsLobbyOwner)
			{
				SteamManager.instance.HostNextLevel(PlayerHandler.Get().GetPlayer(startedId), abilityIcons);
				SteamManager.ForceLoadNextLevel();
			}
			else if (timeSinceLastStartSuggest > 0.1f)
			{
				SteamManager.instance.SendStartSuggest();
				AudioManager.Get().Play("startGame");
				timeSinceLastStartSuggest = 0f;
			}
		}
		else
		{
			abilitySelectUi.NotifySomeoneIsBlockedByOpenAbilityList(startedId);
		}
	}

	private void TryReturnToAbilitySelect_online(bool allReady, int startedId)
	{
		if (allReady)
		{
			if (SteamManager.LocalPlayerIsLobbyOwner)
			{
				SteamManager.instance.currentLobby.SetJoinable(b: true);
				SteamManager.instance.BroadcastBacktoAbilityCommand();
				SteamManager.ForceBacktoAbilitySelect();
				AudioManager.Get().Play("return");
				isLoading = true;
				Transition();
			}
			else if (timeSinceLastStartSuggest > 0.1f)
			{
				SteamManager.instance.SendReturnToAbilitySelectSuggest();
				AudioManager.Get().Play("return");
				timeSinceLastStartSuggest = 0f;
			}
		}
		else
		{
			abilitySelectUi.NotifySomeoneIsBlockedByOpenAbilityList(startedId);
		}
	}

	private void LateUpdate()
	{
		timeSinceDisabled += Time.deltaTime;
		timeSinceLastStartSuggest += Time.deltaTime;
		if (GameLobby.isOnlineGame)
		{
			OnlineUpdate();
		}
		else
		{
			OfflineUpdate();
		}
	}

	public static void ForceBackToAbilitySelectImmediately()
	{
		if (WinnerTriangleCanvas.instance != null)
		{
			GameObject gameObject = WinnerTriangleCanvas.instance.gameObject;
			GameObject obj = WinnerTriangleCanvas.instance.charStatsList.transform.parent.gameObject;
			gameObject.SetActive(value: false);
			obj.SetActive(value: false);
		}
		hostRequestsBackToAbilitySelect = false;
		hostRequestsNextLevelLoad = false;
		GameSessionHandler.InstantlyLoadAbilitySelectScene();
	}

	public static void ForceBackToAbilitySelectTransitionFade()
	{
		hostRequestsBackToAbilitySelect = false;
		hostRequestsNextLevelLoad = false;
		isLoading = true;
		GameSessionHandler.LoadAbilitySelectScene();
	}

	public static void ForceNextLevelImmediately()
	{
		hostRequestsNextLevelLoad = false;
		hostRequestsBackToAbilitySelect = false;
		AudioManager.Get().Play("startGame");
		isLoading = true;
		GameSessionHandler.LoadNextLevelScene();
	}

	private void OnlineUpdate()
	{
		if (hostRequestsNextLevelLoad)
		{
			Transition();
			ForceNextLevelImmediately();
			return;
		}
		if (hostRequestsBackToAbilitySelect)
		{
			Transition();
			ForceBackToAbilitySelectTransitionFade();
			return;
		}
		hostRequestsBackToAbilitySelect = false;
		hostRequestsNextLevelLoad = false;
		bool flag = true;
		bool flag2 = false;
		bool flag3 = false;
		if (SteamManager.LocalPlayerIsLobbyOwner)
		{
			if (someoneSuggestedNextLevel)
			{
				flag2 = true;
			}
			else if (someoneSuggestedBacktoAbilitySelect)
			{
				flag3 = true;
			}
			someoneSuggestedNextLevel = false;
			someoneSuggestedBacktoAbilitySelect = false;
		}
		List<Player> list = PlayerHandler.Get().PlayerList();
		Player player = null;
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].IsLocalPlayer)
			{
				player = list[i];
			}
		}
		for (int j = 0; j < list.Count; j++)
		{
			if (list[j].IsLocalPlayer)
			{
				flag &= !list[j].HasAbilitySelectOpenend;
			}
		}
		List<SteamConnection> connectedPlayers = SteamManager.instance.connectedPlayers;
		for (int k = 0; k < connectedPlayers.Count; k++)
		{
			bool flag4 = false;
			for (int l = 0; l < list.Count; l++)
			{
				if ((ulong)list[l].steamId == (ulong)connectedPlayers[k].id)
				{
					flag4 = list[l].WonThisRound;
				}
			}
			flag &= flag4 || connectedPlayers[k].lobby_isReady;
		}
		if (!isLoading && timeSinceDisabled > TimeBeforeInputsAreAllowed)
		{
			if (player.StartButton_isDown_RAW() || player.JumpButton_isDown_RAW())
			{
				flag2 = true;
			}
			if ((player.AbilityButton_2_IsDown_RAW() && !player.UsesKeyboardAndMouse) || player.SelectButton_isDown_RAW())
			{
				flag3 = true;
			}
			if (flag3 && GameSession.IsInitialized())
			{
				TryReturnToAbilitySelect_online(flag, player.Id);
			}
			else if (flag2)
			{
				TryStartNextLevel_online(flag, player.Id);
			}
		}
	}

	private void OfflineUpdate()
	{
		bool flag = false;
		bool flag2 = false;
		int blockedPlayerId = -1;
		int blockedPlayerId2 = -1;
		List<Player> list = PlayerHandler.Get().PlayerList();
		bool flag3 = true;
		for (int i = 0; i < list.Count; i++)
		{
			flag3 &= !list[i].HasAbilitySelectOpenend;
		}
		if (isLoading || !(timeSinceDisabled > TimeBeforeInputsAreAllowed))
		{
			return;
		}
		for (int j = 0; j < PlayerHandler.Get().NumberOfPlayers(); j++)
		{
			Player player = PlayerHandler.Get().PlayerList()[j];
			int id = player.Id;
			if (player.StartButton_isDown_RAW() || player.JumpButton_isDown_RAW())
			{
				flag = true;
				blockedPlayerId = id;
			}
		}
		for (int k = 0; k < PlayerHandler.Get().NumberOfPlayers(); k++)
		{
			Player player2 = PlayerHandler.Get().PlayerList()[k];
			int id2 = player2.Id;
			if ((player2.AbilityButton_2_IsDown_RAW() && !player2.UsesKeyboardAndMouse) || player2.SelectButton_isDown_RAW())
			{
				flag2 = true;
				blockedPlayerId2 = id2;
			}
		}
		if (flag2 && GameSession.IsInitialized())
		{
			if (flag3)
			{
				isLoading = true;
				Transition();
				GameSessionHandler.LoadAbilitySelectScene();
			}
			else
			{
				abilitySelectUi.NotifySomeoneIsBlockedByOpenAbilityList(blockedPlayerId2);
			}
		}
		else if (flag)
		{
			if (flag3)
			{
				AudioManager.Get().Play("startGame");
				isLoading = true;
				Transition();
				GameSessionHandler.LoadNextLevelScene();
			}
			else
			{
				abilitySelectUi.NotifySomeoneIsBlockedByOpenAbilityList(blockedPlayerId);
			}
		}
	}

	private void Transition()
	{
		StopAllCoroutines();
		for (int i = 0; i < playerRows.Count; i++)
		{
			StartCoroutine(DelayedRemove(playerRows[i], (float)i * DelaySpacing / transitionSpeed, deleteDelay));
		}
		PlayerHandler.Get().PlayerList();
		StartCoroutine(DelayedDeactivate(changeAbilitiesRef, 1f * DelaySpacing / transitionSpeed, deleteDelay));
		StartCoroutine(DelayedDeactivate(nextLevelRef, 2f * DelaySpacing / transitionSpeed, deleteDelay));
		if (WinnerTriangleRef.isActiveAndEnabled)
		{
			WinnerTriangleRef.SetBool("visible", value: false);
		}
		if (DrawTriangleRef.isActiveAndEnabled)
		{
			DrawTriangleRef.SetBool("visible", value: false);
		}
		if (teams2v2TriangleRef.isActiveAndEnabled)
		{
			teams2v2TriangleRef.SetBool("visible", value: false);
		}
		if (teams3v1TriangleRef.isActiveAndEnabled)
		{
			teams3v1TriangleRef.SetBool("visible", value: false);
		}
	}

	private void OnDisable()
	{
		for (int i = 0; i < playerRows.Count; i++)
		{
			Updater.DestroyFix(playerRows[i]);
		}
		playerRows.Clear();
		changeAbilitiesRef.SetActive(value: false);
		nextLevelRef.SetActive(value: false);
		timeSinceDisabled = 0f;
	}

	private void OnEnable()
	{
		isLoading = false;
		playerRows = new List<GameObject>();
		List<Player> list = PlayerHandler.Get().PlayerList();
		List<Player> list2 = new List<Player>();
		for (int i = 0; i < list.Count; i++)
		{
			list2.Add(list[i]);
		}
		int num = 0;
		for (int j = 0; j < list2.Count; j++)
		{
			if (list2[j].IsMostRecentWinner)
			{
				num++;
			}
		}
		bool flag = false;
		if (num > 1)
		{
			for (int k = 0; k < list2.Count; k++)
			{
				if (!list2[k].IsMostRecentWinner)
				{
					continue;
				}
				for (int l = k + 1; l < list2.Count; l++)
				{
					if (list2[l].IsMostRecentWinner)
					{
						flag |= list2[l].Team != list2[k].Team;
					}
				}
			}
		}
		list2.Sort(new PlayerSorter());
		if (num == 1)
		{
			DrawTriangleRef.gameObject.SetActive(value: false);
			teams2v2TriangleRef.gameObject.SetActive(value: false);
			teams3v1TriangleRef.gameObject.SetActive(value: false);
			WinnerTriangleRef.gameObject.SetActive(value: true);
			WinnerRef.material = list2[0].Color;
			WinnerTriangleRef.SetBool("visible", value: true);
		}
		else if (flag)
		{
			WinnerTriangleRef.gameObject.SetActive(value: false);
			teams2v2TriangleRef.gameObject.SetActive(value: false);
			teams3v1TriangleRef.gameObject.SetActive(value: false);
			DrawTriangleRef.gameObject.SetActive(value: true);
			DrawTriangleRef.SetBool("visible", value: true);
			int m = 0;
			for (int n = 0; n < list2.Count; n++)
			{
				if (list2[n].IsMostRecentWinner)
				{
					winnersOfDraw[m].gameObject.SetActive(value: true);
					winnersOfDraw[m].material = list2[n].Color;
					m++;
				}
			}
			for (; m < winnersOfDraw.Length; m++)
			{
				winnersOfDraw[m].gameObject.SetActive(value: false);
			}
		}
		else if (num == 2)
		{
			WinnerTriangleRef.gameObject.SetActive(value: false);
			DrawTriangleRef.gameObject.SetActive(value: false);
			teams3v1TriangleRef.gameObject.SetActive(value: false);
			teams2v2TriangleRef.gameObject.SetActive(value: true);
			teams2v2WinnersRef[0].material = list2[0].Color;
			teams2v2WinnersRef[1].material = list2[1].Color;
			teams2v2TriangleRef.SetBool("visible", value: true);
		}
		else
		{
			WinnerTriangleRef.gameObject.SetActive(value: false);
			DrawTriangleRef.gameObject.SetActive(value: false);
			teams2v2TriangleRef.gameObject.SetActive(value: false);
			teams3v1TriangleRef.gameObject.SetActive(value: true);
			teams3v1WinnersRef[0].material = list2[0].Color;
			teams3v1WinnersRef[1].material = list2[1].Color;
			teams3v1WinnersRef[2].material = list2[2].Color;
			teams3v1TriangleRef.SetBool("visible", value: true);
		}
		StartCoroutine(DelayedActivate(changeAbilitiesRef, Delay + (float)list2.Count * DelaySpacing + buttonsTextsDelay));
		StartCoroutine(DelayedActivate(nextLevelRef, Delay + (float)(list2.Count + 1) * DelaySpacing + buttonsTextsDelay));
	}
}
public class CharSelectClickToJoin : MonoBehaviour, IPointerClickHandler, IEventSystemHandler, IPointerEnterHandler, IPointerExitHandler
{
	public CharacterSelectBox csb;

	public UnityEngine.Color hoverColor;

	public UnityEngine.Color baseColor;

	public UnityEngine.Color borderHoverColor;

	public UnityEngine.Color borderBaseColor;

	public UnityEngine.Color textBaseColor;

	public UnityEngine.Color textHoverColor;

	public float fadeSpeed = 10f;

	private bool isHovering;

	private float timeSinceHover;

	public UnityEngine.UI.Image borderImage;

	public UnityEngine.UI.Image fillImage;

	public TextMeshProUGUI textComponent;

	private bool respondsToNonMouseInput => CurrentlyActiveIndex() == csb.RectangleIndex;

	private void Ready()
	{
		csb.OnEnterSelect();
		AudioManager.Get().Play("accept");
	}

	private int CurrentlyActiveIndex()
	{
		for (int i = 0; i < CharacterSelectBox.occupiedRectangles.Length; i++)
		{
			if (!CharacterSelectBox.occupiedRectangles[i])
			{
				return i;
			}
		}
		return 4;
	}

	public void OnPointerClick(PointerEventData eventData)
	{
		if (!CharacterSelectBox.occupiedRectangles[csb.RectangleIndex] && !CharacterSelectBox.keyboardMouseIsOccupied)
		{
			csb.UseskeyboardMouse = true;
			CharacterSelectBox.keyboardMouseIsOccupied = true;
			Ready();
		}
	}

	public void LoadPlayerChoice(Player player)
	{
		if (player.UsesKeyboardAndMouse)
		{
			CharacterSelectBox.deviceIds[csb.RectangleIndex] = 0;
			csb.UseskeyboardMouse = true;
			CharacterSelectBox.keyboardMouseIsOccupied = true;
		}
		else
		{
			CharacterSelectBox.deviceIds[csb.RectangleIndex] = player.inputDevice.deviceId;
			csb.UseskeyboardMouse = false;
			csb.currentGamePad = (Gamepad)player.inputDevice;
		}
		Ready();
	}

	private void LateUpdate()
	{
		Keyboard current = Keyboard.current;
		Gamepad gamepad = null;
		for (int i = 0; i < CharacterSelectBox.deviceIds.Length; i++)
		{
			bool flag = true;
			foreach (Gamepad item in Gamepad.all)
			{
				if (CharacterSelectBox.deviceIds[i] == item.deviceId)
				{
					flag = false;
				}
			}
			if (flag && CharacterSelectBox.deviceIds[i] != 0)
			{
				CharacterSelectBox.deviceIds[i] = 0;
				CharacterSelectBox.occupiedRectangles[i] = false;
			}
		}
		foreach (Gamepad item2 in Gamepad.all)
		{
			bool flag2 = false;
			for (int j = 0; j < CharacterSelectBox.deviceIds.Length; j++)
			{
				if (CharacterSelectBox.deviceIds[j] == item2.deviceId)
				{
					flag2 = true;
				}
			}
			if (flag2)
			{
				continue;
			}
			gamepad = item2;
			if (csb.menuState == CharSelectMenu.join && respondsToNonMouseInput)
			{
				if (!CharacterSelectBox.keyboardMouseIsOccupied && current.anyKey.wasPressedThisFrame && !current.escapeKey.wasPressedThisFrame)
				{
					CharacterSelectBox.deviceIds[csb.RectangleIndex] = 0;
					csb.UseskeyboardMouse = true;
					CharacterSelectBox.keyboardMouseIsOccupied = true;
					Ready();
					break;
				}
				if (gamepad != null && (gamepad.startButton.wasPressedThisFrame || gamepad.aButton.wasPressedThisFrame))
				{
					CharacterSelectBox.deviceIds[csb.RectangleIndex] = gamepad.deviceId;
					csb.UseskeyboardMouse = false;
					csb.currentGamePad = gamepad;
					Ready();
					break;
				}
			}
		}
		float t = timeSinceHover * fadeSpeed;
		if (isHovering)
		{
			timeSinceHover += Time.deltaTime;
		}
		else
		{
			timeSinceHover -= Time.deltaTime;
		}
		fillImage.color = UnityEngine.Color.Lerp(baseColor, hoverColor, t);
		borderImage.color = UnityEngine.Color.Lerp(borderBaseColor, borderHoverColor, t);
		textComponent.color = UnityEngine.Color.Lerp(textBaseColor, textHoverColor, t);
	}

	private void OnEnable()
	{
		isHovering = false;
		timeSinceHover = 0f;
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		if (!CharacterSelectBox.keyboardMouseIsOccupied)
		{
			timeSinceHover = Mathf.Max(timeSinceHover, 0f);
			isHovering = true;
		}
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		timeSinceHover = Mathf.Min(timeSinceHover, 1f / fadeSpeed);
		isHovering = false;
	}
}
public class CircleBG : MonoBehaviour
