public class ColorPool : MonoBehaviour
{
	public List<Material> colors;

	private int[] playerPos;

	private bool[] colorTaken;

	public Material GetMaterial(int playerId)
	{
		return colors[playerPos[playerId]];
	}

	public void SelectColor(int playerId)
	{
		colorTaken[playerPos[playerId]] = true;
		int num = 0;
		for (int i = 0; i < colorTaken.Length; i++)
		{
			if (colorTaken[i])
			{
				num++;
			}
		}
		if (num >= colors.Count)
		{
			return;
		}
		for (int j = 1; j < playerPos.Length; j++)
		{
			if (playerPos[j] == playerPos[playerId] && j != playerId)
			{
				NextPos(j);
			}
		}
	}

	public void DeselectColor(int playerId)
	{
		colorTaken[playerPos[playerId]] = false;
	}

	public void NextPos(int playerId)
	{
		int num = (playerPos[playerId] + 1) % colors.Count;
		while (colorTaken[num])
		{
			num = (num + 1) % colors.Count;
		}
		playerPos[playerId] = num;
	}

	public int PlayerPos(int id)
	{
		return playerPos[id];
	}

	public void SetPlayerPos(int id, int pos)
	{
		while (playerPos[id] != pos)
		{
			NextPos(id);
		}
	}

	public void PrevPos(int playerId)
	{
		int num = (playerPos[playerId] + colors.Count - 1) % colors.Count;
		while (colorTaken[num])
		{
			num = (num + colors.Count - 1) % colors.Count;
		}
		playerPos[playerId] = num;
	}

	private void Start()
	{
		colorTaken = new bool[colors.Count];
		playerPos = new int[Constants.MAX_PLAYERS + 1];
		for (int i = 1; i < Constants.MAX_PLAYERS + 1; i++)
		{
			playerPos[i] = (i - 1) % colors.Count;
		}
		for (int j = 0; j < colorTaken.Length; j++)
		{
			colorTaken[j] = false;
		}
	}
}
public class WinnerDecider : IComparer<Player>
{
	public int Compare(Player x, Player y)
	{
		if (x.GamesWon == y.GamesWon)
		{
			return y.Kills.CompareTo(x.Kills);
		}
		return y.GamesWon.CompareTo(x.GamesWon);
	}
}
