public class ExitGameMenu : MonoBehaviour
{
	public GameObject canvas;

	public AnimationCurve scaleAnim;

	public RectTransform leaveGameButton;

	public RectTransform exitButton;

	public UnityEngine.Color yesSelectedColor;

	public UnityEngine.Color noSelectedColor;

	private UnityEngine.Color yesColor;

	private UnityEngine.Color noColor;

	[SerializeField]
	private UnityEngine.UI.Image vImage;

	[SerializeField]
	private UnityEngine.UI.Image vCircleImage;

	[SerializeField]
	private UnityEngine.UI.Image xImage;

	[SerializeField]
	private UnityEngine.UI.Image xCircleImage;

	private bool isOpen;

	private Player controllingPlayer;

	private bool leaveGameSelected;

	private bool padClickedLeft;

	private bool padClickedRight;

	private bool padClickedLeft2;

	private bool padClickedRight2;

	private float timeSinceFlip;

	private void Awake()
	{
		canvas.SetActive(value: false);
		isOpen = false;
		yesColor = vImage.color;
		noColor = xImage.color;
	}

	private void Open(Player player)
	{
		isOpen = true;
		controllingPlayer = player;
		canvas.SetActive(value: true);
		player.ignoreAllInputs = true;
		AudioManager.Get().Play("return");
	}

	public void Close()
	{
		isOpen = false;
		controllingPlayer.ignoreAllInputs = false;
		controllingPlayer = null;
		canvas.SetActive(value: false);
		AudioManager.Get().Play("return");
	}

	public void HoverLeaveGame()
	{
		leaveGameSelected = true;
	}

	public void HoverCancel()
	{
		leaveGameSelected = false;
	}

	public void LeaveGame()
	{
		GameSessionHandler.LeaveGame(abandonLobbyEntirely: false, sendOthersBackToAbilitySelect: true);
	}

	private void clickSelectedButton()
	{
		if (leaveGameSelected)
		{
			LeaveGame();
		}
		else
		{
			Close();
		}
	}

	private void flipSelected()
	{
		AudioManager.Get().Play("navigateMenu");
		timeSinceFlip = 0f;
		if (leaveGameSelected)
		{
			leaveGameButton.localScale = new Vector3(1f, 1f, 1f);
		}
		else
		{
			exitButton.localScale = new Vector3(1f, 1f, 1f);
		}
		leaveGameSelected = !leaveGameSelected;
	}

	private void UpdatePlayer(Player player)
	{
		_ = player.Id;
		if (player.UsesKeyboardAndMouse)
		{
			Keyboard current = Keyboard.current;
			if (current.enterKey.wasPressedThisFrame)
			{
				clickSelectedButton();
			}
			else if (current.escapeKey.wasPressedThisFrame)
			{
				Close();
			}
			else if (current.rightArrowKey.wasPressedThisFrame || current.leftArrowKey.wasPressedThisFrame || current.dKey.wasPressedThisFrame || current.aKey.wasPressedThisFrame)
			{
				flipSelected();
			}
			return;
		}
		Gamepad gamepad = (Gamepad)player.inputDevice;
		if (gamepad.IsUsable_())
		{
			if (gamepad.aButton.wasPressedThisFrame)
			{
				clickSelectedButton();
			}
			else if (gamepad.bButton.wasPressedThisFrame || gamepad.selectButton.wasPressedThisFrame)
			{
				Close();
			}
			if (gamepad.rightStick.ReadValue().x > (float)Constants.DEADZONE && !padClickedRight)
			{
				padClickedRight = true;
				padClickedLeft = false;
				flipSelected();
			}
			else if (gamepad.rightStick.ReadValue().x < 0f - (float)Constants.DEADZONE && !padClickedLeft)
			{
				padClickedRight = false;
				padClickedLeft = true;
				flipSelected();
			}
			else if (Mathf.Abs(gamepad.rightStick.ReadValue().x) < (float)Constants.DEADZONE)
			{
				padClickedRight = false;
				padClickedLeft = false;
			}
			if (gamepad.leftStick.ReadValue().x > (float)Constants.DEADZONE && !padClickedRight2)
			{
				padClickedRight2 = true;
				padClickedLeft2 = false;
				flipSelected();
			}
			else if (gamepad.leftStick.ReadValue().x < 0f - (float)Constants.DEADZONE && !padClickedLeft2)
			{
				padClickedRight2 = false;
				padClickedLeft2 = true;
				flipSelected();
			}
			else if (Mathf.Abs(gamepad.leftStick.ReadValue().x) < (float)Constants.DEADZONE)
			{
				padClickedRight2 = false;
				padClickedLeft2 = false;
			}
			if (gamepad.dpad.right.wasPressedThisFrame || gamepad.dpad.left.wasPressedThisFrame)
			{
				flipSelected();
			}
		}
		else
		{
			padClickedRight2 = false;
			padClickedLeft2 = false;
			padClickedRight = false;
			padClickedLeft = false;
		}
	}

	private void updateUnOpenend(Player player)
	{
		if (player.UsesKeyboardAndMouse)
		{
			if (Keyboard.current.escapeKey.wasPressedThisFrame)
			{
				Open(player);
			}
			return;
		}
		Gamepad gamepad = (Gamepad)player.inputDevice;
		if (gamepad.IsUsable_() && gamepad.startButton.wasPressedThisFrame)
		{
			Open(player);
		}
	}

	private void Update()
	{
		timeSinceFlip += Time.deltaTime;
		if (GameSessionHandler.GameIsPaused)
		{
			if (isOpen)
			{
				Close();
			}
			return;
		}
		if (isOpen)
		{
			float num = scaleAnim.Evaluate(Time.timeSinceLevelLoad);
			if (leaveGameSelected)
			{
				leaveGameButton.localScale = new Vector3(num, num, 1f);
				vImage.color = yesSelectedColor;
				vCircleImage.color = yesSelectedColor;
				xImage.color = noColor;
				xCircleImage.color = noColor;
			}
			else
			{
				exitButton.localScale = new Vector3(num, num, 1f);
				vImage.color = yesColor;
				vCircleImage.color = yesColor;
				xImage.color = noSelectedColor;
				xCircleImage.color = noSelectedColor;
			}
		}
		if (GameLobby.isOnlineGame)
		{
			if (isOpen)
			{
				UpdatePlayer(controllingPlayer);
				return;
			}
			List<Player> list = PlayerHandler.Get().PlayerList();
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i].IsLocalPlayer)
				{
					updateUnOpenend(list[i]);
				}
			}
			return;
		}
		if (isOpen)
		{
			UpdatePlayer(controllingPlayer);
			return;
		}
		List<Player> list2 = PlayerHandler.Get().PlayerList();
		for (int j = 0; j < list2.Count; j++)
		{
			updateUnOpenend(list2[j]);
			if (isOpen)
			{
				break;
			}
		}
	}
}
public class HandleAbilitySelectUI : MonoBehaviour
{
	[SerializeField]
	private AbilitySelectCircle abilitySelectCirclePrefab;

	[SerializeField]
	private Sprite[] LoserCharacters = new Sprite[4];

	[SerializeField]
	private Sprite[] WinnerCharacters = new Sprite[3];

	[SerializeField]
	private Sprite[] SpecialCharacters = new Sprite[1];

	[SerializeField]
	private Settings settings;

	[SerializeField]
	private float Separation;

	private AbilitySelectCircle[] Selectors;

	private bool IsInitialized;

	public void NotifySomeoneIsBlockedByOpenAbilityList(int blockedPlayerId)
	{
		bool flag = false;
		for (int i = 0; i < Selectors.Length; i++)
		{
			Player player = PlayerHandler.Get().GetPlayer(Selectors[i].GetPlayerId());
			if (player == null)
			{
				continue;
			}
			if (GameLobby.isOnlineGame)
			{
				List<SteamConnection> connectedPlayers = SteamManager.instance.connectedPlayers;
				bool flag2 = false;
				for (int j = 0; j < connectedPlayers.Count; j++)
				{
					if ((ulong)connectedPlayers[j].id == (ulong)player.steamId)
					{
						flag2 = !connectedPlayers[j].lobby_isReady;
						break;
					}
				}
				if (player.Id != blockedPlayerId && flag2)
				{
					flag = true;
					Selectors[i].Wiggle();
				}
			}
			else if (player.HasAbilitySelectOpenend && player.Id != blockedPlayerId)
			{
				flag = true;
				Selectors[i].Wiggle();
			}
		}
		if (flag)
		{
			AudioManager.Get().Play("smallError");
		}
	}

	private void Awake()
	{
	}

	private void Init()
	{
		Selectors = new AbilitySelectCircle[PlayerHandler.Get().NumberOfPlayers()];
		List<Player> list = PlayerHandler.Get().PlayerList();
		Vector2 vector = Vector2.left * Separation * (PlayerHandler.Get().NumberOfPlayers() - 1);
		for (int i = 0; i < PlayerHandler.Get().NumberOfPlayers(); i++)
		{
			Selectors[i] = UnityEngine.Object.Instantiate(abilitySelectCirclePrefab, base.transform);
			Selectors[i].trans.anchoredPosition = vector + Vector2.right * i * Separation;
			Selectors[i].Init(list[i].Id, isWinner: false);
		}
		for (int j = 0; j < list.Count; j++)
		{
			list[j].playerDied -= OnPlayerDied;
			list[j].playerDied += OnPlayerDied;
			list[j].playerWon -= OnPlayerWon;
			list[j].playerWon += OnPlayerWon;
		}
		IsInitialized = true;
	}

	private void OnPlayerDied(int playerId, CauseOfDeath causeOfDeath)
	{
		if (PlayerHandler.Get().HasAliveTeammate(playerId))
		{
			return;
		}
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].Team == PlayerHandler.Get().GetPlayer(playerId).Team)
			{
				ShowLoserCircle(list[i]);
			}
		}
	}

	private void ShowLoserCircle(Player player)
	{
		for (int num = Selectors.Length - 1; num >= 0; num--)
		{
			if (Selectors[num].IsDisabled())
			{
				Selectors[num].SetCharacterSprite(LoserCharacters[(int)player.CauseOfDeath]);
				Selectors[num].SetPlayer(player.Id, isWinner: false);
				break;
			}
		}
	}

	private void SetWinnerSprite(int playerId, AbilitySelectCircle circle)
	{
		Player player = PlayerHandler.Get().GetPlayer(playerId);
		int value = player.Kills - player.KillsAtStartOfRound;
		value = Mathf.Clamp(value, 0, WinnerCharacters.Length - 1);
		if (player.CauseOfDeath == CauseOfDeath.NotDeadYet || player.CauseOfDeath == CauseOfDeath.Other)
		{
			if (player.playersEatenCountThisRound > 0)
			{
				circle.SetCharacterSprite(SpecialCharacters[0]);
			}
			else
			{
				circle.SetCharacterSprite(WinnerCharacters[value]);
			}
		}
		else
		{
			circle.SetCharacterSprite(LoserCharacters[(int)player.CauseOfDeath]);
		}
	}

	private void OnPlayerWon(int playerId)
	{
		for (int i = 0; i < Selectors.Length; i++)
		{
			if (Selectors[i].IsDisabled())
			{
				SetWinnerSprite(playerId, Selectors[i]);
				Selectors[i].SetPlayer(playerId, isWinner: true);
				return;
			}
		}
		for (int j = 0; j < Selectors.Length; j++)
		{
			if (Selectors[j].GetPlayerId() == playerId && !Selectors[j].isWinner)
			{
				SetWinnerSprite(playerId, Selectors[j]);
				Selectors[j].SetPlayer(playerId, isWinner: true);
				break;
			}
		}
	}

	private void OnEnable()
	{
		SceneManager.sceneLoaded += OnSceneLoaded;
	}

	private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
	{
		bool flag = SceneManager.GetActiveScene().buildIndex <= Constants.ColorSelectorSceneIndex(settings.GameMode);
		if (IsInitialized && flag)
		{
			for (int i = 0; i < Selectors.Length; i++)
			{
				UnityEngine.Object.Destroy(Selectors[i].trans.gameObject);
			}
			Selectors = null;
			IsInitialized = false;
		}
		else if (!IsInitialized && !flag)
		{
			Init();
		}
		if (!IsInitialized)
		{
			return;
		}
		for (int j = 0; j < Selectors.Length; j++)
		{
			if (PlayerHandler.Get().GetPlayer(Selectors[j].GetPlayerId()) == null)
			{
				Selectors[j].gameObject.SetActive(value: false);
			}
			else
			{
				Selectors[j].Disable();
			}
		}
	}

	private void OnDisable()
	{
		SceneManager.sceneLoaded -= OnSceneLoaded;
	}
}
