public class KeyBindButton : SelectableMonoBehaviour, IPointerEnterHandler, IEventSystemHandler, IPointerClickHandler, IPointerExitHandler
{
	public CharacterSelectBox charSelectBox;

	public UnityEngine.UI.Image buttonImage;

	public UnityEngine.Color hoverColorAddition;

	public UnityEngine.Color clickColorAddition;

	private UnityEngine.Color baseColor;

	public GameObject FakeArrows;

	public AnimationCurve HoverScaleAnim;

	public GameObject RebindKeysCover;

	public TextMeshProUGUI RebindKeyText;

	public UnityEngine.UI.Image rebindImage;

	public string[] KeyListGamePad;

	public string[] KeyListKeyboardMouse;

	public bool[] MouseOnlyKeyList;

	public Sprite[] CircleIndicators_gamePad;

	public Sprite[] CircleIndicators_keyboard;

	public float[] indicatorRotations_keyboard;

	public TextMeshProUGUI mouseOnlyText;

	private AnimateTransformUI mouseOnlyTextAnimate;

	public RectTransform bindListParentTop;

	public RectTransform bindListParentBottom;

	public TextMeshProUGUI[] bindingListHypens;

	public TextMeshProUGUI[] bindingListLabels;

	public UnityEngine.UI.Image[] bindingListArrows;

	public TextMeshProUGUI[] bindingListChoices;

	private Vector2 bindListParentTopOriginalPos;

	private const int bindListKeys = 4;

	private float baseScale;

	private string[] keyListGamepad_spaced;

	private string[] KeyListKeyboardMouse_spaced;

	private AnimateTransformUI animateOnButtonBinded;

	private AnimateTransformUI[] animateOnButtonWasAlreadyBinded;

	private bool leaveKeyRebind;

	private InputControl[] newBinding_gamepad;

	private InputControl[] newBinding_keyboardMouse;

	private const string onClickSound = "navigateMenu";

	private const string onDone = "accept2";

	private const string onCancel = "decline2";

	private const string onAlreadyUsed = "smallError";

	public float fadeTime = 0.1f;

	private float timeSinceInteracted = 10000f;

	private UnityEngine.Color targetColor;

	private bool isSelected;

	private bool rebindingKeys;

	private int rebindKeyIndex;

	public void Init()
	{
	}

	private void Awake()
	{
		text.font = LocalizedText.localizationTable.GetFont(Settings.Get().Language, useFontWithStroke: false);
		RebindKeyText.font = LocalizedText.localizationTable.GetFont(Settings.Get().Language, useFontWithStroke: false);
		bindListParentTopOriginalPos = bindListParentTop.anchoredPosition;
		animateOnButtonBinded = GetComponent<AnimateTransformUI>();
		mouseOnlyTextAnimate = mouseOnlyText.GetComponent<AnimateTransformUI>();
		animateOnButtonWasAlreadyBinded = new AnimateTransformUI[bindingListChoices.Length];
		for (int i = 0; i < bindingListChoices.Length; i++)
		{
			animateOnButtonWasAlreadyBinded[i] = bindingListChoices[i].GetComponent<AnimateTransformUI>();
		}
		baseScale = base.transform.localScale.x;
		baseColor = buttonImage.color;
		targetColor = baseColor;
		keyListGamepad_spaced = new string[KeyListGamePad.Length];
		KeyListKeyboardMouse_spaced = new string[KeyListKeyboardMouse.Length];
		for (int j = 0; j < KeyListGamePad.Length; j++)
		{
			keyListGamepad_spaced[j] = LocalizedText.localizationTable.GetText(KeyListGamePad[j], Settings.Get().Language).Replace(' ', '\n').Replace('_', ' ');
		}
		for (int k = 0; k < KeyListKeyboardMouse.Length; k++)
		{
			KeyListKeyboardMouse_spaced[k] = LocalizedText.localizationTable.GetText(KeyListKeyboardMouse[k], Settings.Get().Language).Replace(' ', '\n').Replace('_', ' ');
		}
		newBinding_gamepad = new InputControl[KeyListGamePad.Length];
		newBinding_keyboardMouse = new InputControl[KeyListKeyboardMouse.Length];
	}

	public override void SetToPlayerChoices(Player player, int index)
	{
		if (player.UsesKeyboardAndMouse && player.CustomKeyBinding != null)
		{
			newBinding_keyboardMouse = player.CustomKeyBinding;
		}
		else if (player.CustomKeyBinding != null)
		{
			newBinding_gamepad = player.CustomKeyBinding;
		}
		UpdateKeybind();
	}

	private void UpdateKeybind()
	{
		if (charSelectBox.UseskeyboardMouse)
		{
			charSelectBox.playerInit.keybindOverride = newBinding_keyboardMouse;
		}
		else
		{
			charSelectBox.playerInit.keybindOverride = newBinding_gamepad;
		}
	}

	public void SetBaseColor(UnityEngine.Color color)
	{
		baseColor = color;
		targetColor = color;
	}

	private int IsControlAlreadyBinded(InputControl control, InputControl[] occupied)
	{
		for (int i = 0; i < occupied.Length; i++)
		{
			if (occupied[i] == control)
			{
				return i;
			}
		}
		return -1;
	}

	private void LateUpdate()
	{
		if (leaveKeyRebind)
		{
			FinishRebindingKeys();
			leaveKeyRebind = false;
			return;
		}
		if (rebindingKeys)
		{
			if (charSelectBox.UseskeyboardMouse)
			{
				if (Keyboard.current.escapeKey.wasPressedThisFrame)
				{
					leaveKeyRebind = true;
					AudioManager.Get().Play("decline2");
					return;
				}
				foreach (KeyControl allKey in Keyboard.current.allKeys)
				{
					if (!allKey.wasPressedThisFrame)
					{
						continue;
					}
					_ = MouseOnlyKeyList[rebindKeyIndex];
					int num = IsControlAlreadyBinded(allKey, newBinding_keyboardMouse);
					if (num >= 0)
					{
						AudioManager.Get().Play("smallError");
						animateOnButtonWasAlreadyBinded[num].Animate();
						continue;
					}
					newBinding_keyboardMouse[rebindKeyIndex] = allKey;
					rebindKeyIndex++;
					if (rebindKeyIndex >= KeyListKeyboardMouse_spaced.Length)
					{
						leaveKeyRebind = true;
						UpdateKeybind();
						animateOnButtonBinded.Animate();
						AudioManager.Get().Play("accept2");
					}
					else
					{
						UpdateKeyText();
						AudioManager.Get().Play("navigateMenu");
						animateOnButtonBinded.Animate();
					}
					return;
				}
				{
					foreach (InputControl allControl in Mouse.current.allControls)
					{
						if (allControl.path == "/Mouse/press" || !(allControl is ButtonControl) || !((ButtonControl)allControl).wasPressedThisFrame)
						{
							continue;
						}
						int num2 = IsControlAlreadyBinded(allControl, newBinding_keyboardMouse);
						if (num2 >= 0)
						{
							animateOnButtonWasAlreadyBinded[num2].Animate();
							AudioManager.Get().Play("smallError");
							continue;
						}
						newBinding_keyboardMouse[rebindKeyIndex] = allControl;
						rebindKeyIndex++;
						if (rebindKeyIndex >= KeyListKeyboardMouse_spaced.Length)
						{
							leaveKeyRebind = true;
							UpdateKeybind();
							animateOnButtonBinded.Animate();
							AudioManager.Get().Play("accept2");
						}
						else
						{
							UpdateKeyText();
							animateOnButtonBinded.Animate();
							AudioManager.Get().Play("navigateMenu");
						}
						break;
					}
					return;
				}
			}
			if (charSelectBox.currentGamePad.selectButton.wasPressedThisFrame)
			{
				leaveKeyRebind = true;
				AudioManager.Get().Play("decline2");
				return;
			}
			{
				foreach (InputControl allControl2 in charSelectBox.currentGamePad.allControls)
				{
					if (!(allControl2 is ButtonControl) || !((ButtonControl)allControl2).wasPressedThisFrame || allControl2.parent is StickControl || allControl2 == charSelectBox.currentGamePad.startButton || allControl2 == charSelectBox.currentGamePad.selectButton || allControl2.path == "/DualSenseGamepadHID/leftTriggerButton" || allControl2.path == "/DualSenseGamepadHID/rightTriggerButton" || allControl2.path.Contains("/dpad"))
					{
						continue;
					}
					int num3 = IsControlAlreadyBinded(allControl2, newBinding_gamepad);
					if (num3 >= 0)
					{
						animateOnButtonWasAlreadyBinded[num3].Animate();
						AudioManager.Get().Play("smallError");
						continue;
					}
					newBinding_gamepad[rebindKeyIndex] = allControl2;
					rebindKeyIndex++;
					if (rebindKeyIndex >= keyListGamepad_spaced.Length)
					{
						leaveKeyRebind = true;
						UpdateKeybind();
						animateOnButtonBinded.Animate();
						AudioManager.Get().Play("accept2");
					}
					else
					{
						UpdateKeyText();
						animateOnButtonBinded.Animate();
						AudioManager.Get().Play("navigateMenu");
					}
					break;
				}
				return;
			}
		}
		if (isSelected)
		{
			base.transform.localScale = baseScale * Vector2.one * HoverScaleAnim.Evaluate(timeSinceInteracted);
		}
		else
		{
			base.transform.localScale = baseScale * Vector2.one * HoverScaleAnim.Evaluate(HoverScaleAnim.keys[HoverScaleAnim.keys.Length - 1].time - timeSinceInteracted);
		}
		if (!buttonImage.color.Equals(targetColor))
		{
			buttonImage.color = UnityEngine.Color.Lerp(buttonImage.color, targetColor, timeSinceInteracted / fadeTime);
		}
		timeSinceInteracted += Time.deltaTime;
		if (charSelectBox.menuState == CharSelectMenu.select)
		{
			Keyboard current4 = Keyboard.current;
			Gamepad currentGamePad = charSelectBox.currentGamePad;
			if (current4 != null && charSelectBox.UseskeyboardMouse && current4.enterKey.wasPressedThisFrame && isSelected)
			{
				OnClick();
			}
			else if (currentGamePad != null && currentGamePad.aButton.wasPressedThisFrame && isSelected)
			{
				OnClick();
			}
		}
	}

	public override void Activate()
	{
		Select(0);
	}

	public override void DeActivate()
	{
		DeSelect();
	}

	private void DeSelect()
	{
		timeSinceInteracted = 0f;
		isSelected = false;
		targetColor = baseColor;
		FakeArrows.SetActive(value: false);
	}

	public override void Select(int index)
	{
		timeSinceInteracted = 0f;
		isSelected = true;
		text.text = LocalizedText.localizationTable.GetText("rebind keys", Settings.Get().Language);
		targetColor = baseColor + hoverColorAddition;
		FakeArrows.SetActive(value: true);
	}

	private void OnClick()
	{
		timeSinceInteracted = 0f;
		targetColor = baseColor + clickColorAddition;
		RebindAllKeys();
	}

	private void RebindAllKeys()
	{
		if (!rebindingKeys)
		{
			AudioManager.Get().Play("accept");
			if (newBinding_keyboardMouse != null)
			{
				Array.Clear(newBinding_keyboardMouse, 0, newBinding_keyboardMouse.Length);
			}
			if (newBinding_gamepad != null)
			{
				Array.Clear(newBinding_gamepad, 0, newBinding_gamepad.Length);
			}
			rebindingKeys = true;
			charSelectBox.SetInputsEnabled(enabled: false);
			RebindKeysCover.SetActive(value: true);
			rebindKeyIndex = 0;
			UpdateKeyText();
		}
	}

	private void UpdateKeyText()
	{
		if (charSelectBox.UseskeyboardMouse)
		{
			mouseOnlyText.gameObject.SetActive(MouseOnlyKeyList[rebindKeyIndex]);
			RebindKeyText.text = KeyListKeyboardMouse_spaced[rebindKeyIndex];
			rebindImage.sprite = CircleIndicators_keyboard[rebindKeyIndex];
			rebindImage.rectTransform.localEulerAngles = new Vector3(0f, 0f, indicatorRotations_keyboard[rebindKeyIndex]);
			bindListParentTop.anchoredPosition = bindListParentTopOriginalPos;
			bindListParentBottom.gameObject.SetActive(value: true);
			bindingListHypens[0].gameObject.SetActive(value: true);
			bindingListHypens[1].gameObject.SetActive(value: true);
			for (int i = 0; i < bindingListChoices.Length; i++)
			{
				bindingListChoices[i].gameObject.SetActive(value: true);
				if (i < newBinding_keyboardMouse.Length && newBinding_keyboardMouse[i] != null)
				{
					bindingListChoices[i].text = newBinding_keyboardMouse[i].displayName;
				}
				else
				{
					bindingListChoices[i].text = "";
				}
			}
		}
		else
		{
			mouseOnlyText.gameObject.SetActive(value: false);
			RebindKeyText.text = keyListGamepad_spaced[rebindKeyIndex];
			rebindImage.sprite = CircleIndicators_gamePad[rebindKeyIndex];
			bindListParentTop.anchoredPosition = new Vector2(bindListParentTop.anchoredPosition.x, bindListParentTopOriginalPos.y);
			bindListParentBottom.gameObject.SetActive(value: false);
			for (int j = 0; j < bindingListChoices.Length; j++)
			{
				bindingListChoices[j].gameObject.SetActive(value: true);
				if (j < newBinding_gamepad.Length && newBinding_gamepad[j] != null)
				{
					bindingListChoices[j].text = newBinding_gamepad[j].displayName;
				}
				else
				{
					bindingListChoices[j].text = "";
				}
			}
		}
		rebindImage.enabled = rebindImage.sprite != null;
	}

	private void FinishRebindingKeys()
	{
		for (int i = 0; i < animateOnButtonWasAlreadyBinded.Length; i++)
		{
			animateOnButtonWasAlreadyBinded[i].SetToFinalState();
		}
		mouseOnlyTextAnimate.SetToFinalState();
		rebindingKeys = false;
		charSelectBox.SetInputsEnabled(enabled: true);
		RebindKeysCover.SetActive(value: false);
		rebindKeyIndex = 0;
	}

	public void OnPointerClick(PointerEventData eventData)
	{
		if (charSelectBox.menuState == CharSelectMenu.select && !rebindingKeys && charSelectBox.UseskeyboardMouse)
		{
			OnClick();
		}
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		if (charSelectBox.menuState == CharSelectMenu.select && !rebindingKeys && charSelectBox.UseskeyboardMouse)
		{
			charSelectBox.SetSelected(0);
		}
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		if (charSelectBox.menuState == CharSelectMenu.select && charSelectBox.UseskeyboardMouse)
		{
			DeSelect();
		}
	}
}
