public class LocalizedText : MonoBehaviour
{
	private string enText;

	private Language currentLanguage;

	private TextMeshProUGUI textToLocalize;

	private TextMesh textToLocalize2;

	public static LocalizationTable localizationTable;

	public bool useFontWithStroke;

	public bool ignoreFontChange;

	private void Awake()
	{
		textToLocalize = GetComponent<TextMeshProUGUI>();
		textToLocalize2 = GetComponent<TextMesh>();
		if ((bool)textToLocalize)
		{
			enText = textToLocalize.text.ToLower();
		}
		if ((bool)textToLocalize2)
		{
			enText = textToLocalize2.text.ToLower();
		}
	}

	public void UpdateText()
	{
		TMP_FontAsset font = localizationTable.GetFont(Settings.Get().Language, useFontWithStroke);
		currentLanguage = Settings.Get().Language;
		if (textToLocalize != null && !useFontWithStroke && (currentLanguage == Language.ZHCN || currentLanguage == Language.ZHTW || currentLanguage == Language.JP))
		{
			textToLocalize.fontStyle = FontStyles.Normal;
		}
		else if (textToLocalize != null)
		{
			textToLocalize.fontStyle = FontStyles.Bold;
		}
		if (textToLocalize != null)
		{
			textToLocalize.text = localizationTable.GetText(enText, Settings.Get().Language);
		}
		else
		{
			textToLocalize2.text = localizationTable.GetText(enText, Settings.Get().Language);
		}
		if (!ignoreFontChange && textToLocalize != null && textToLocalize.font != font)
		{
			textToLocalize.font = font;
		}
	}

	private void Start()
	{
		UpdateText();
	}

	private void Update()
	{
		if (currentLanguage != Settings.Get().Language)
		{
			UpdateText();
		}
	}
}
public class MainMenu : MonoBehaviour
{
	public AnimationCurve AnimateInOptions;

	public AnimationCurve AnimateOutOptions;

	public float optionAnimateDelay = 0.3f;

	public List<GameObject> ConfiguredMenuItems;

	public bool startDisabled = true;

	private List<Vector2> originalMenuItemPositions;

	private List<RectTransform> MenuItemTransforms;

	private List<IMenuItem> MenuItems;

	private List<int> Indices;

	private List<int> MaxIndices;

	private int yPos;

	private bool isEnabled;

	private float timeSinceEnabled;

	private float timeSinceDisabled;

	public bool IsEnabled => isEnabled;

	private void Start()
	{
		SteamFrame.SetHidden(hide: false);
		Application.targetFrameRate = 300;
		yPos = 0;
		Indices = new List<int>();
		MenuItems = new List<IMenuItem>();
		originalMenuItemPositions = new List<Vector2>();
		MenuItemTransforms = new List<RectTransform>();
		for (int i = 0; i < ConfiguredMenuItems.Count; i++)
		{
			IMenuItem component = ConfiguredMenuItems[i].GetComponent<IMenuItem>();
			if (component != null)
			{
				Indices.Add(0);
				MenuItems.Add(component);
				RectTransform component2 = ConfiguredMenuItems[i].GetComponent<RectTransform>();
				MenuItemTransforms.Add(component2);
				originalMenuItemPositions.Add(component2.anchoredPosition);
			}
		}
		if (startDisabled)
		{
			DisableAll();
			timeSinceDisabled = 1000f;
		}
		else
		{
			EnableAll();
		}
		AudioManager.Get()?.OnEnteredMenus();
		GameSession.inMenus = true;
		if (GameLobby.isOnlineGame && SteamManager.LocalPlayerIsLobbyOwner)
		{
			SteamManager.instance.currentLobby.SetJoinable(b: true);
		}
	}

	private void Awake()
	{
		MenuInputHandler.Instance.MenuMap.Move0.performed -= OnMove;
		MenuInputHandler.Instance.MenuMap.Move0.performed += OnMove;
		MenuInputHandler.Instance.MenuMap.Move1.performed -= OnMove;
		MenuInputHandler.Instance.MenuMap.Move1.performed += OnMove;
		MenuInputHandler.Instance.MenuMap.Move2.performed -= OnMove;
		MenuInputHandler.Instance.MenuMap.Move2.performed += OnMove;
		MenuInputHandler.Instance.MenuMap.Move3.performed -= OnMove;
		MenuInputHandler.Instance.MenuMap.Move3.performed += OnMove;
		MenuInputHandler.Instance.MenuMap.Move4.performed -= OnMove;
		MenuInputHandler.Instance.MenuMap.Move4.performed += OnMove;
	}

	private void OnDestroy()
	{
		MenuInputHandler.Instance.MenuMap.Move0.performed -= OnMove;
		MenuInputHandler.Instance.MenuMap.Move1.performed -= OnMove;
		MenuInputHandler.Instance.MenuMap.Move2.performed -= OnMove;
		MenuInputHandler.Instance.MenuMap.Move3.performed -= OnMove;
		MenuInputHandler.Instance.MenuMap.Move4.performed -= OnMove;
	}

	public void DisableAll()
	{
		for (int i = 0; i < MenuItems.Count; i++)
		{
			MenuItems[i].InputActive = false;
		}
		isEnabled = false;
		timeSinceDisabled = 0f;
	}

	public void EnableAll()
	{
		for (int i = 0; i < MenuItems.Count; i++)
		{
			MenuItems[i].Init();
		}
		AudioManager.Get().Play("menuWhoosh1");
		isEnabled = true;
		yPos = 0;
		MenuItems[0].InputActive = true;
		timeSinceEnabled = 0f;
		timeSinceDisabled = 1000f;
	}

	private void Update()
	{
		timeSinceDisabled += Time.deltaTime;
		timeSinceEnabled += Time.deltaTime;
		if (isEnabled)
		{
			for (int i = 0; i < MenuItems.Count; i++)
			{
				MenuItemTransforms[i].anchoredPosition = originalMenuItemPositions[i] + Vector2.right * AnimateInOptions.Evaluate(timeSinceEnabled - optionAnimateDelay * (float)i);
			}
		}
		else
		{
			for (int j = 0; j < MenuItems.Count; j++)
			{
				MenuItemTransforms[j].anchoredPosition = originalMenuItemPositions[j] + Vector2.up * AnimateOutOptions.Evaluate(timeSinceDisabled - optionAnimateDelay * (float)(MenuItems.Count - 1 - j));
			}
		}
		_ = isEnabled;
	}

	private void OnMove(InputAction.CallbackContext context)
	{
		if (base.isActiveAndEnabled && isEnabled)
		{
			Vector2 vector = context.ReadValue<Vector2>();
			if (vector.y > (float)Constants.DEADZONE)
			{
				AudioManager.Get().Play("navigateMenu");
				Up();
			}
			else if (0f - vector.y > (float)Constants.DEADZONE)
			{
				AudioManager.Get().Play("navigateMenu");
				Down();
			}
			for (int i = 0; i < MenuItems.Count; i++)
			{
				MenuItems[i].InputActive = yPos == i;
			}
			_ = MenuItems[yPos];
		}
	}

	public void Down()
	{
		yPos = (yPos + 1) % MenuItems.Count;
	}

	public void Up()
	{
		yPos = (yPos - 1 + MenuItems.Count) % MenuItems.Count;
	}

	public void Select(int newYPos)
	{
		if (base.isActiveAndEnabled && isEnabled)
		{
			yPos = newYPos;
			for (int i = 0; i < MenuItems.Count; i++)
			{
				MenuItems[i].InputActive = yPos == i;
			}
			_ = MenuItems[yPos];
			AudioManager.Get().Play("navigateMenu");
		}
	}
}
