public class MidGameAbilitySelect : MonoBehaviour
{
	public RectTransform ArrowR;

	public RectTransform ArrowL;

	public RectTransform[] Circles;

	public NamedSpriteList AbilityIcons;

	public NamedSpriteList AbilityIcons_demo;

	public Sprite lockedSprite;

	private NamedSpriteList localAbilityIcons;

	private Player player;

	[HideInInspector]
	public UnityEngine.UI.Image[] CircleImages;

	public UnityEngine.UI.Image[] ArrowImages;

	private RectTransform rectTrans;

	private int[] XPos;

	private int YPos;

	[SerializeField]
	private float circleDistance = 71.7001f;

	[SerializeField]
	private AnimationCurve ScaleAnimation;

	[SerializeField]
	private AnimationCurve RotationAnimation;

	[SerializeField]
	public AnimationCurve ArrowMovementX;

	private bool wasUp;

	private bool wasDown;

	private bool wasRight;

	private bool wasLeft;

	private float timeSinceAbilitySwap;

	private float timeSinceLeftArrowClicked;

	private float timeSinceRightArrowClicked;

	[SerializeField]
	private float XScrollSpeed = 5f;

	[SerializeField]
	private Vector2 movementSensitivity = new Vector2(1f, 1f);

	[SerializeField]
	private float arrowXOffset = 50f;

	public void SetPlayer(int playerId)
	{
		YPos = 0;
		player = PlayerHandler.Get().GetPlayer(playerId);
		CircleImages = new UnityEngine.UI.Image[Settings.Get().NumberOfAbilities];
		rectTrans = GetComponent<RectTransform>();
		rectTrans.anchoredPosition = Vector2.zero;
		XPos = new int[Settings.Get().NumberOfAbilities];
		for (int i = 0; i < Circles.Length; i++)
		{
			if (i >= Settings.Get().NumberOfAbilities)
			{
				Circles[i].gameObject.SetActive(value: false);
				rectTrans.anchoredPosition += Vector2.down * circleDistance;
			}
			else
			{
				CircleImages[i] = Circles[i].transform.GetChild(0).GetComponent<UnityEngine.UI.Image>();
			}
		}
		localAbilityIcons = (SteamManager.instance.dlc.HasDLC() ? AbilityIcons : AbilityIcons_demo);
		for (int j = 0; j < CircleImages.Length; j++)
		{
			int index = j;
			if (XPos.Length == 3)
			{
				switch (j)
				{
				case 2:
					index = 1;
					break;
				case 1:
					index = 2;
					break;
				}
			}
			XPos[j] = localAbilityIcons.IndexOf(player.Abilities[index].name);
			if (XPos[j] < 0)
			{
				XPos[j] = 0;
			}
			CircleImages[j].sprite = localAbilityIcons.GetSprite(XPos[j]);
		}
		ArrowR.anchoredPosition = Circles[YPos].anchoredPosition;
		ArrowL.anchoredPosition = Circles[YPos].anchoredPosition;
	}

	private void Awake()
	{
	}

	private void Start()
	{
		timeSinceAbilitySwap = 10000f;
		timeSinceLeftArrowClicked = 10000f;
		timeSinceRightArrowClicked = 10000f;
	}

	public float TotalYOffset()
	{
		return (float)(3 - Settings.Get().NumberOfAbilities) * circleDistance;
	}

	public void HoverCircle(int index)
	{
		if (player.UsesKeyboardAndMouse)
		{
			AudioManager.Get().Play("navigateMenu");
			YPos = index;
		}
	}

	public void ClickArrow(bool right)
	{
		if (player.UsesKeyboardAndMouse)
		{
			timeSinceAbilitySwap = 0f;
			if (right)
			{
				Right();
			}
			else
			{
				Left();
			}
		}
	}

	private void Down()
	{
		AudioManager.Get().Play("navigateMenu");
		YPos = (YPos + 1) % Settings.Get().NumberOfAbilities;
	}

	private void Up()
	{
		AudioManager.Get().Play("navigateMenu");
		YPos = (YPos - 1 + Settings.Get().NumberOfAbilities) % Settings.Get().NumberOfAbilities;
	}

	private void Left()
	{
		AudioManager.Get().Play("navigateMenu");
		timeSinceLeftArrowClicked = 0f;
		XPos[YPos] = (XPos[YPos] + 1) % localAbilityIcons.sprites.Count;
		if (XPos[YPos] == 0)
		{
			XPos[YPos] = 1;
		}
		UpdatePlayerAbilityChoices();
	}

	private void UpdatePlayerAbilityChoices()
	{
		if (Settings.Get().NumberOfAbilities == 3)
		{
			int index = YPos;
			if (YPos == 2)
			{
				index = 1;
			}
			if (YPos == 1)
			{
				index = 2;
			}
			CircleImages[YPos].sprite = localAbilityIcons.GetSprite(XPos[YPos]);
			player.Abilities[index] = localAbilityIcons.sprites[XPos[YPos]].associatedGameObject;
			player.AbilityIcons[index] = localAbilityIcons.sprites[XPos[YPos]].sprite;
		}
		else
		{
			CircleImages[YPos].sprite = localAbilityIcons.GetSprite(XPos[YPos]);
			player.Abilities[YPos] = localAbilityIcons.sprites[XPos[YPos]].associatedGameObject;
			player.AbilityIcons[YPos] = localAbilityIcons.sprites[XPos[YPos]].sprite;
		}
	}

	private void Right()
	{
		AudioManager.Get().Play("navigateMenu");
		timeSinceRightArrowClicked = 0f;
		XPos[YPos] = (XPos[YPos] - 1 + localAbilityIcons.sprites.Count) % localAbilityIcons.sprites.Count;
		if (XPos[YPos] == 0)
		{
			XPos[YPos] = localAbilityIcons.sprites.Count - 1;
		}
		UpdatePlayerAbilityChoices();
	}

	private void OnEnable()
	{
		YPos = 0;
	}

	private void Update()
	{
		float deltaTime = Time.deltaTime;
		float num = 100f / XScrollSpeed;
		for (int i = 0; i < Circles.Length; i++)
		{
			if (i == YPos)
			{
				Circles[i].localScale = Vector3.one * ScaleAnimation.Evaluate(timeSinceAbilitySwap / num);
				Circles[i].localEulerAngles = Vector3.forward * RotationAnimation.Evaluate(timeSinceAbilitySwap / num);
			}
			else
			{
				Circles[i].localScale = Vector3.one;
				Circles[i].localEulerAngles = Vector3.zero;
			}
		}
		UpdateArrowsPosition(num);
		timeSinceAbilitySwap += deltaTime;
		timeSinceLeftArrowClicked += deltaTime;
		timeSinceRightArrowClicked += deltaTime;
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		bool flag4 = false;
		if (player.UsesKeyboardAndMouse)
		{
			Keyboard current = Keyboard.current;
			flag = current.upArrowKey.wasPressedThisFrame || current.wKey.wasPressedThisFrame;
			flag2 = current.downArrowKey.wasPressedThisFrame || current.sKey.wasPressedThisFrame;
			flag3 = current.rightArrowKey.wasPressedThisFrame || current.dKey.wasPressedThisFrame;
			flag4 = current.leftArrowKey.wasPressedThisFrame || current.aKey.wasPressedThisFrame;
			wasUp = false;
			wasDown = false;
			wasRight = false;
			wasLeft = false;
		}
		else
		{
			Gamepad gamepad = (Gamepad)player.inputDevice;
			Vector2 vector;
			Vector2 vector2;
			Vector2 vector3;
			if (gamepad.IsUsable_())
			{
				vector = gamepad.leftStick.ReadValue();
				vector2 = gamepad.rightStick.ReadValue();
				vector3 = gamepad.dpad.ReadValue();
			}
			else
			{
				vector = Vector2.zero;
				vector2 = Vector2.zero;
				vector3 = Vector2.zero;
			}
			flag = vector.y > (float)Constants.DEADZONE + movementSensitivity.y;
			flag |= vector2.y > (float)Constants.DEADZONE + movementSensitivity.y;
			flag |= vector3.y > (float)Constants.DEADZONE + movementSensitivity.y;
			flag2 = vector.y < 0f - ((float)Constants.DEADZONE + movementSensitivity.y);
			flag2 |= vector2.y < 0f - ((float)Constants.DEADZONE + movementSensitivity.y);
			flag2 |= vector3.y < 0f - ((float)Constants.DEADZONE + movementSensitivity.y);
			flag3 = vector.x > (float)Constants.DEADZONE + movementSensitivity.x;
			flag3 |= vector2.x > (float)Constants.DEADZONE + movementSensitivity.x;
			flag3 |= vector3.x > (float)Constants.DEADZONE + movementSensitivity.x;
			flag4 = vector.x < 0f - ((float)Constants.DEADZONE + movementSensitivity.x);
			flag4 |= vector2.x < 0f - ((float)Constants.DEADZONE + movementSensitivity.x);
			flag4 |= vector3.x < 0f - ((float)Constants.DEADZONE + movementSensitivity.x);
		}
		if (flag && !wasUp)
		{
			wasUp = true;
			Up();
			return;
		}
		if (wasUp && !flag)
		{
			wasUp = false;
			return;
		}
		if (flag2 && !wasDown)
		{
			wasDown = true;
			Down();
			return;
		}
		if (wasDown && !flag2)
		{
			wasDown = false;
			return;
		}
		if (flag3 && !wasRight)
		{
			wasRight = true;
			timeSinceAbilitySwap = 0f;
			Right();
		}
		else if ((wasRight && timeSinceAbilitySwap > num) || !flag3)
		{
			wasRight = false;
		}
		if (flag4 && !wasLeft)
		{
			wasLeft = true;
			timeSinceAbilitySwap = 0f;
			Left();
		}
		else if ((wasLeft && timeSinceAbilitySwap > num) || !flag4)
		{
			wasLeft = false;
		}
	}

	public void SyncArrowPositionToCurrentYPos()
	{
		ArrowR.anchoredPosition = Vector2.up * Circles[YPos].anchoredPosition.y + Vector2.right * arrowXOffset;
		ArrowL.anchoredPosition = Vector2.up * Circles[YPos].anchoredPosition.y + Vector2.left * arrowXOffset;
	}

	private void UpdateArrowsPosition(float animationTime)
	{
		SyncArrowPositionToCurrentYPos();
		ArrowR.anchoredPosition += Vector2.right * ArrowMovementX.Evaluate(timeSinceRightArrowClicked / animationTime);
		ArrowL.anchoredPosition += Vector2.left * ArrowMovementX.Evaluate(timeSinceLeftArrowClicked / animationTime);
	}
}
