public class OptionsButton : MonoBehaviour, IMenuItem
{
	public Constants.Button[] ClickButtons;

	public List<int> players;

	public bool reverse;

	public float timeBeforeBackButtonsAreAvailable = 1f;

	public MainMenu optionsMenu;

	public MainMenu mainMenu;

	private float timeInOptionsMenu;

	public UnityEvent onClick;

	private static bool optionbuttonWasPressedThisFrame;

	public bool InputActive { get; set; }

	private void Awake()
	{
		MenuInputHandler.Instance.MenuMap.Accept.performed -= OnAccept;
		MenuInputHandler.Instance.MenuMap.Accept.performed += OnAccept;
		MenuInputHandler.Instance.MenuMap.Back.performed -= OnBack;
		MenuInputHandler.Instance.MenuMap.Back.performed += OnBack;
	}

	private void OnDestroy()
	{
		MenuInputHandler.Instance.MenuMap.Accept.performed -= OnAccept;
		MenuInputHandler.Instance.MenuMap.Back.performed -= OnBack;
	}

	private void OnAccept(InputAction.CallbackContext context)
	{
		Click();
	}

	public void Click()
	{
		if (InputActive && base.isActiveAndEnabled && !optionbuttonWasPressedThisFrame)
		{
			if (reverse)
			{
				onClick?.Invoke();
				mainMenu.EnableAll();
				optionsMenu.DisableAll();
				AudioManager.Get().Play("return3");
				optionbuttonWasPressedThisFrame = true;
			}
			else
			{
				onClick?.Invoke();
				mainMenu.DisableAll();
				optionsMenu.EnableAll();
				AudioManager.Get().Play("return3");
				optionbuttonWasPressedThisFrame = true;
			}
		}
	}

	private void OnBack(InputAction.CallbackContext context)
	{
		if (reverse && optionsMenu.IsEnabled && timeInOptionsMenu > timeBeforeBackButtonsAreAvailable && base.isActiveAndEnabled)
		{
			mainMenu.EnableAll();
			optionsMenu.DisableAll();
			AudioManager.Get().Play("return");
		}
	}

	private void Update()
	{
		optionbuttonWasPressedThisFrame = false;
		if (optionsMenu.IsEnabled)
		{
			timeInOptionsMenu += Time.deltaTime;
		}
		else
		{
			timeInOptionsMenu = 0f;
		}
	}

	public void Init()
	{
	}
}
public class OrbitItems : MonoUpdatable
{
	public bool rotateItems;

	public float ItemRotationSpeed = 10f;

	public Transform[] items;

	private bool[] ItemsArrived;

	private bool fromLeft;

	public float deltaRotation;

	[SerializeField]
	private AnimationCurve rotationAnimation;

	private AnimationCurve EaseInOut01 = AnimationCurve.EaseInOut(0f, 0f, 1f, 1f);

	private Quaternion currentRotation;

	public float radius = 10f;

	[SerializeField]
	private float wideness = 1f;

	[SerializeField]
	private bool AnimateInItems;

	[SerializeField]
	private Vector2 AnimateInStartOffset;

	[SerializeField]
	private float animateInTime = 2f;

	private float AnimateInDistanceBetweenItems;

	[SerializeField]
	private AnimationCurve AnimateInYPos = AnimationCurve.Constant(0f, 1f, 1f);

	[SerializeField]
	private float Delay;

	public override void Init()
	{
		if (AnimateInItems && items != null && items.Length >= 1)
		{
			fromLeft = AnimateInStartOffset.x < 0f;
			Vector3 vector = base.transform.position + Vector3.down * radius;
			if (!fromLeft)
			{
				vector = base.transform.position + Vector3.up * radius;
			}
			Vector3 vector2 = vector + (Vector3)AnimateInStartOffset;
			Vector3 normalized = (vector - vector2).normalized;
			for (int i = 0; i < items.Length; i++)
			{
				items[i].position = vector2 + normalized * AnimateInDistanceBetweenItems * i;
			}
		}
		currentRotation = Quaternion.Euler(0f, 0f, 360f / (float)items.Length);
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		ItemsArrived = new bool[items.Length];
		AnimateInDistanceBetweenItems = radius * MathF.PI * 2f / (float)items.Length;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (items == null || (float)Updater.SimTimeSinceLevelLoaded < Delay)
		{
			return;
		}
		if (AnimateInItems && AnimateInItems && items != null && items.Length >= 1)
		{
			Vector3 vector = base.transform.position + Vector3.down * radius;
			if (!fromLeft)
			{
				vector = base.transform.position + Vector3.up * radius;
			}
			Vector3 vector2 = vector + (Vector3)AnimateInStartOffset;
			Vector3 normalized = (vector - vector2).normalized;
			float num = AnimateInStartOffset.magnitude / animateInTime;
			for (int i = 0; i < items.Length; i++)
			{
				if (!ItemsArrived[i])
				{
					items[i].position += normalized * num * Time.fixedDeltaTime;
					float time = (items[i].position - vector2).magnitude / Mathf.Abs(AnimateInStartOffset.x);
					items[i].position = new Vector3(items[i].position.x, vector.y + AnimateInYPos.Evaluate(time), items[i].position.z);
					ItemsArrived[i] = Vector3.Dot(vector - items[i].position, normalized) < 0f;
				}
			}
		}
		if (rotateItems)
		{
			for (int j = 0; j < items.Length; j++)
			{
				items[j].transform.Rotate(Vector3.forward, ItemRotationSpeed);
			}
		}
		Quaternion quaternion = Quaternion.Euler(0f, 0f, 360f / (float)items.Length);
		Vector3 vector3 = currentRotation * (fromLeft ? Vector3.down : Vector3.up) * radius;
		for (int k = 0; k < items.Length; k++)
		{
			if (ItemsArrived[k] || !AnimateInItems)
			{
				items[k].position = vector3 + base.transform.position + Vector3.right * wideness * Vector3.Dot(vector3.normalized, Vector3.right);
			}
			vector3 = quaternion * vector3;
		}
		if (ItemsArrived != null && ItemsArrived.Length >= 1 && ItemsArrived[ItemsArrived.Length - 1] && AnimateInItems)
		{
			float num2 = AnimateInStartOffset.magnitude / animateInTime;
			float num3 = MathF.PI * 2f * radius / num2;
			float num4 = 360f / num3 * Time.fixedDeltaTime;
			float time2 = rotationAnimation.keys[rotationAnimation.length - 1].time;
			float num5 = Mathf.Max((float)Updater.SimTimeSinceLevelLoaded - animateInTime - num3, 0f);
			float z = ((!(num5 <= time2)) ? (EaseInOut01.Evaluate((num5 - time2) / 2f) * deltaRotation) : (num4 * rotationAnimation.Evaluate(num5)));
			currentRotation = Quaternion.Euler(new Vector3(0f, 0f, z)) * currentRotation;
		}
		if (!AnimateInItems)
		{
			float z2 = deltaRotation;
			currentRotation = Quaternion.Euler(new Vector3(0f, 0f, z2)) * currentRotation;
		}
	}

	private void OnDrawGizmosSelected()
	{
		Quaternion quaternion = Quaternion.Euler(0f, 0f, 360f / (float)items.Length);
		Vector3 vector = base.transform.up * radius;
		for (int i = 0; i < items.Length; i++)
		{
			items[i].position = vector + base.transform.position + Vector3.right * wideness * Vector3.Dot(vector.normalized, Vector3.right);
			vector = quaternion * vector;
		}
	}
}
