public class PlayButton : MonoBehaviour, IMenuItem
{
	public Settings settings;

	public MainMenu mainMenu;

	public bool startOnlineInstead;

	public bool startTutorialInstead;

	public AnimateInOutUI discordButton;

	public float timeBeforeSceneSwap = 1f;

	private float timeSinceClicked;

	private UnityEngine.AsyncOperation sceneLoading;

	public int NumberOfStates => 0;

	public bool InputActive { get; set; }

	public void Init()
	{
	}

	private void Awake()
	{
		MenuInputHandler.Instance.MenuMap.Accept.performed -= OnClick;
		MenuInputHandler.Instance.MenuMap.Accept.performed += OnClick;
	}

	private void OnDestroy()
	{
		MenuInputHandler.Instance.MenuMap.Accept.performed -= OnClick;
	}

	private void Start()
	{
		timeSinceClicked = 0f;
		sceneLoading = null;
	}

	private void Update()
	{
		if (sceneLoading != null)
		{
			timeSinceClicked += Time.deltaTime;
		}
		if (timeSinceClicked >= timeBeforeSceneSwap)
		{
			sceneLoading.allowSceneActivation = true;
		}
	}

	public void PrepareTutorial(InputDevice deviceUsedToClick)
	{
		for (int i = 0; i < Gamepad.all.Count; i++)
		{
			if (deviceUsedToClick != null && deviceUsedToClick.deviceId == Gamepad.all[i].deviceId)
			{
				TutorialGameHandler.SwapToGamePadNextUpdate = true;
			}
		}
	}

	public void Click()
	{
		if (InputActive && sceneLoading == null && base.isActiveAndEnabled && (!startOnlineInstead || SteamClient.IsValid))
		{
			AudioManager.Get().Play("menuWhoosh1");
			AudioManager.Get().Play("startGame");
			if (startOnlineInstead)
			{
				sceneLoading = SceneManager.LoadSceneAsync("ChSelect_online", LoadSceneMode.Single);
			}
			else if (startTutorialInstead)
			{
				sceneLoading = SceneManager.LoadSceneAsync("Tutorial", LoadSceneMode.Single);
			}
			else
			{
				sceneLoading = SceneManager.LoadSceneAsync("CharacterSelect", LoadSceneMode.Single);
			}
			sceneLoading.allowSceneActivation = false;
			mainMenu.DisableAll();
			discordButton.AnimateIn_reverse();
		}
	}

	private void OnClick(InputAction.CallbackContext context)
	{
		if (startTutorialInstead)
		{
			PrepareTutorial(context.control.device);
		}
		Click();
	}
}
public class ReadyButton : SelectableMonoBehaviour, IPointerEnterHandler, IEventSystemHandler, IPointerClickHandler, IPointerExitHandler
{
	public CharacterSelectBox charSelectBox;

	public UnityEngine.UI.Image buttonImage;

	public UnityEngine.Color hoverColorAddition;

	public UnityEngine.Color clickColorAddition;

	private UnityEngine.Color baseColor;

	public GameObject FakeArrows;

	public AnimationCurve HoverScaleAnim;

	private float baseScale;

	public float fadeTime = 0.1f;

	private float timeSinceInteracted = 10000f;

	private UnityEngine.Color targetColor;

	private bool isSelected;

	private void Awake()
	{
		baseScale = base.transform.localScale.x;
		baseColor = buttonImage.color;
		targetColor = baseColor;
		text.font = LocalizedText.localizationTable.GetFont(Settings.Get().Language, useFontWithStroke: false);
	}

	public void SetBaseColor(UnityEngine.Color color)
	{
		baseColor = color;
		targetColor = color;
	}

	private void Update()
	{
		if (isSelected)
		{
			base.transform.localScale = baseScale * Vector2.one * HoverScaleAnim.Evaluate(timeSinceInteracted);
		}
		else
		{
			base.transform.localScale = baseScale * Vector2.one * HoverScaleAnim.Evaluate(HoverScaleAnim.keys[HoverScaleAnim.keys.Length - 1].time - timeSinceInteracted);
		}
		if (!buttonImage.color.Equals(targetColor))
		{
			buttonImage.color = UnityEngine.Color.Lerp(buttonImage.color, targetColor, timeSinceInteracted / fadeTime);
		}
		timeSinceInteracted += Time.deltaTime;
		if (charSelectBox.menuState == CharSelectMenu.select)
		{
			Keyboard current = Keyboard.current;
			Gamepad currentGamePad = charSelectBox.currentGamePad;
			if ((charSelectBox.UseskeyboardMouse && current.enterKey.wasPressedThisFrame && isSelected) || (currentGamePad != null && (currentGamePad.startButton.wasPressedThisFrame || (currentGamePad.aButton.wasPressedThisFrame && isSelected))))
			{
				OnClick();
			}
		}
	}

	public override void Activate()
	{
		Select(0);
	}

	public override void DeActivate()
	{
		DeSelect();
	}

	private void DeSelect()
	{
		timeSinceInteracted = 0f;
		isSelected = false;
		targetColor = baseColor;
		FakeArrows.SetActive(value: false);
	}

	public override void Select(int index)
	{
		timeSinceInteracted = 0f;
		isSelected = true;
		text.text = LocalizedText.localizationTable.GetText("ready!", Settings.Get().Language);
		targetColor = baseColor + hoverColorAddition;
		FakeArrows.SetActive(value: true);
	}

	private void OnClick()
	{
		timeSinceInteracted = 0f;
		targetColor = baseColor + clickColorAddition;
		charSelectBox.OnEnterReady();
		AudioManager.Get().Play("accept");
	}

	public void OnPointerClick(PointerEventData eventData)
	{
		if (charSelectBox.menuState == CharSelectMenu.select && charSelectBox.UseskeyboardMouse)
		{
			OnClick();
		}
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		if (charSelectBox.menuState == CharSelectMenu.select && charSelectBox.UseskeyboardMouse)
		{
			charSelectBox.SetSelected(6);
		}
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		if (charSelectBox.menuState == CharSelectMenu.select && charSelectBox.UseskeyboardMouse)
		{
			DeSelect();
		}
	}
}
public class ResolutionSelector : MonoBehaviour, IMenuItem
{
	private int optionIndex;

	public Settings settings;

	public TextMeshProUGUI widthTextMesh;

	public TextMeshProUGUI HeightTextMesh;

	private bool inputActive;

	private BindInputAxisToButton[] InputArrows;

	private List<Resolution> resolutions;

	public bool InputActive
	{
		get
		{
			return inputActive;
		}
		set
		{
			inputActive = value;
		}
	}

	private void Awake()
	{
		Init();
	}

	public void Init()
	{
		resolutions = new List<Resolution>(Screen.resolutions.Length);
		for (int i = 0; i < Screen.resolutions.Length; i++)
		{
			bool flag = false;
			for (int j = 0; j < resolutions.Count; j++)
			{
				if (Screen.resolutions[i].width == resolutions[j].width && Screen.resolutions[i].height == resolutions[j].height)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				resolutions.Add(Screen.resolutions[i]);
			}
		}
		int num = 0;
		for (int k = 0; k < resolutions.Count; k++)
		{
			if (resolutions[k].width == settings.ResolutionWidth && resolutions[k].height == settings.ResolutionHeight)
			{
				num = k;
				break;
			}
		}
		optionIndex = num;
		InputArrows = GetComponentsInChildren<BindInputAxisToButton>();
	}

	private void Update()
	{
		widthTextMesh.text = resolutions[optionIndex].width.ToString();
		HeightTextMesh.text = resolutions[optionIndex].height.ToString();
		for (int i = 0; i < InputArrows.Length; i++)
		{
			InputArrows[i].enabled = InputActive;
		}
	}

	public void Next()
	{
		optionIndex = (optionIndex + 1) % resolutions.Count;
		settings.ResolutionWidth = resolutions[optionIndex].width;
		settings.ResolutionHeight = resolutions[optionIndex].height;
		Update();
	}

	public void Previous()
	{
		optionIndex = (optionIndex - 1 + resolutions.Count) % resolutions.Count;
		settings.ResolutionWidth = resolutions[optionIndex].width;
		settings.ResolutionHeight = resolutions[optionIndex].height;
		Update();
	}
}
public class SceneBoundArrowController : MonoBehaviour
{
	private SpriteRenderer[] SceneBoundsArrows;

	[SerializeField]
	private SpriteRenderer SceneBoundArrowPrefab;

	[SerializeField]
	private float WiggleRoom = 1f;

	[SerializeField]
	private float ArrowOffset = 2f;

	[SerializeField]
	private float DistToShake = 2f;

	[SerializeField]
	private float ShakeStr = 2f;

	private Camera mainCam;

	private void Start()
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		SceneBoundsArrows = new SpriteRenderer[list.Count];
		for (int i = 0; i < list.Count; i++)
		{
			SceneBoundsArrows[i] = UnityEngine.Object.Instantiate(SceneBoundArrowPrefab, Vector3.zero, Quaternion.identity);
			SceneBoundsArrows[i].enabled = false;
			SceneBoundsArrows[i].material = list[i].Color;
		}
		mainCam = Camera.main;
	}

	private void Update()
	{
		float num = mainCam.transform.position.x - mainCam.orthographicSize * mainCam.aspect + ArrowOffset;
		float num2 = mainCam.transform.position.x + mainCam.orthographicSize * mainCam.aspect - ArrowOffset;
		float num3 = mainCam.transform.position.y + mainCam.orthographicSize - ArrowOffset;
		float min = (float)SceneBounds.WaterHeight;
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int i = 0; i < list.Count && i < SceneBoundsArrows.Length; i++)
		{
			if (!list[i].IsAlive || list[i].WonThisRound)
			{
				SceneBoundsArrows[i].enabled = false;
				continue;
			}
			float num4 = Mathf.Clamp((float)list[i].Position.x, num, num2);
			float num5 = Mathf.Clamp((float)list[i].Position.y, min, num3);
			float num6 = 1000f;
			if ((float)list[i].Position.x <= num - WiggleRoom)
			{
				num6 = (float)list[i].Position.x - (float)SceneBounds.BlastZone_XMin;
				if ((float)list[i].Position.y >= num3 + WiggleRoom)
				{
					num6 = Mathf.Min(num6, (float)SceneBounds.BlastZone_YMax - (float)list[i].Position.y);
					SceneBoundsArrows[i].enabled = true;
					SceneBoundsArrows[i].transform.rotation = Quaternion.FromToRotation(Vector3.up, (Vector3.left + Vector3.up) * 0.5f);
				}
				else
				{
					SceneBoundsArrows[i].enabled = true;
					SceneBoundsArrows[i].transform.rotation = Quaternion.FromToRotation(Vector3.up, Vector3.left);
				}
			}
			else if ((float)list[i].Position.x >= num2 + WiggleRoom)
			{
				num6 = (float)SceneBounds.BlastZone_XMax - (float)list[i].Position.x;
				if ((float)list[i].Position.y >= num3 + WiggleRoom)
				{
					num6 = Mathf.Min(num6, (float)SceneBounds.BlastZone_YMax - (float)list[i].Position.y);
					SceneBoundsArrows[i].enabled = true;
					SceneBoundsArrows[i].transform.rotation = Quaternion.FromToRotation(Vector3.up, (Vector3.right + Vector3.up) * 0.5f);
				}
				else
				{
					SceneBoundsArrows[i].enabled = true;
					SceneBoundsArrows[i].transform.rotation = Quaternion.FromToRotation(Vector3.up, Vector3.right);
				}
			}
			else if ((float)list[i].Position.y >= num3 + WiggleRoom)
			{
				num6 = (float)SceneBounds.BlastZone_YMax - (float)list[i].Position.y;
				SceneBoundsArrows[i].enabled = true;
				SceneBoundsArrows[i].transform.rotation = Quaternion.identity;
			}
			else
			{
				SceneBoundsArrows[i].enabled = false;
			}
			if (num6 < DistToShake)
			{
				num4 += UnityEngine.Random.value * ShakeStr * (DistToShake - num6 / DistToShake);
				num5 += UnityEngine.Random.value * ShakeStr * (DistToShake - num6 / DistToShake);
			}
			SceneBoundsArrows[i].transform.position = new Vector2(num4, num5);
		}
	}
}
