		abilityIconRenderer.enabled = true;
		BorderRenderer.enabled = true;
		circlesRenderer.enabled = true;
		Skip = false;
	}

	private void Awake()
	{
		animateCircle = GetComponent<AnimateTransformUI>();
		text.font = LocalizedText.localizationTable.GetFont(Settings.Get().Language, useFontWithStroke: false);
		selectedIndex = abilityIcons.IndexOf(abilityIconRenderer.sprite);
	}

	public override void SetToPlayerChoices(Player player, int index)
	{
		if (Settings.Get().NumberOfAbilities == 3)
		{
			switch (index)
			{
			case 2:
				index = 1;
				break;
			case 1:
				index = 2;
				break;
			}
		}
		if (index >= player.Abilities.Count)
		{
			return;
		}
		string text = player.Abilities[index].name;
		int index2 = selectedIndex;
		for (int i = 0; i < abilityIcons.sprites.Count; i++)
		{
			if (abilityIcons.sprites[i].name == text)
			{
				index2 = i;
			}
		}
		Select(index2);
	}

	public override void Select(int index)
	{
		if (index < 0)
		{
			index = selectedIndex;
		}
		else if (index == 0)
		{
			index = ((selectedIndex != 1) ? 1 : (abilityIcons.sprites.Count - 1));
		}
		selectedIndex = index;
		text.text = LocalizedText.localizationTable.GetText(abilityIcons.sprites[selectedIndex].name.ToLower(), Settings.Get().Language);
		if (SteamManager.instance.dlc.HasDLC() || selectedIndex < csb.abilityGrid.abilityIcons_demo.sprites.Count)
		{
			abilityIconRenderer.sprite = abilityIcons.sprites[selectedIndex].sprite;
			abilityIconLockRenderer.enabled = false;
		}
		else
		{
			abilityIconRenderer.sprite = abilityIcons.sprites[selectedIndex].sprite;
			abilityIconLockRenderer.enabled = true;
		}
	}

	public void PlayScaleAnimation()
	{
		animateCircle.Animate();
	}

	public void PlayDelayedScaleAnimation(float delay)
	{
		timeBeforeNewScaleAnimation = delay;
	}

	public override void Move(bool moveRight)
	{
		if (!Skip && csb.menuState != CharSelectMenu.abilityGrid)
		{
			animateCircle.Animate();
			int num = (moveRight ? 1 : (-1));
			int index = (selectedIndex + num + abilityIcons.sprites.Count) % abilityIcons.sprites.Count;
			Select(index);
			AudioManager.Get().Play("navigateMenu2");
		}
	}

	public override void UpdatePlayerInit(ref PlayerInit init, int index)
	{
		int num = ((Settings.Get() == null) ? 3 : Settings.Get().NumberOfAbilities);
		int num2 = selectedIndex;
		if (!SteamManager.instance.dlc.HasDLC() && selectedIndex >= csb.abilityGrid.abilityIcons_demo.sprites.Count)
		{
			num2 = 1;
		}
		if (num == 3)
		{
			switch (index)
			{
			case 0:
				init.ability0 = num2;
				break;
			case 1:
				init.ability2 = num2;
				break;
			case 2:
				init.ability1 = num2;
				break;
			}
		}
		else
		{
			switch (index)
			{
			case 0:
				init.ability0 = num2;
				break;
			case 1:
				init.ability1 = num2;
				break;
			case 2:
				init.ability2 = num2;
				break;
			}
		}
	}

	private void Update()
	{
		if (((Settings.Get() == null) ? 3 : Settings.Get().NumberOfAbilities) == 3)
		{
			circlesRenderer.sprite = circlesSprite_3;
		}
		else
		{
			circlesRenderer.sprite = circlesSprite_1_2;
		}
		timeBeforeNewScaleAnimation -= Time.deltaTime;
		if (timeBeforeNewScaleAnimation < 0f)
		{
			animateCircle.Animate();
			timeBeforeNewScaleAnimation = 1E+10f;
		}
		Keyboard current = Keyboard.current;
		Gamepad currentGamePad = csb.currentGamePad;
		if ((csb.UseskeyboardMouse && (current.dKey.wasPressedThisFrame || current.rightArrowKey.wasPressedThisFrame)) || (currentGamePad != null && (currentGamePad.leftStick.right.wasPressedThisFrame || currentGamePad.dpad.right.wasPressedThisFrame)))
		{
			Move(moveRight: true);
		}
		else if ((csb.UseskeyboardMouse && (current.aKey.wasPressedThisFrame || current.leftArrowKey.wasPressedThisFrame)) || (currentGamePad != null && (currentGamePad.leftStick.left.wasPressedThisFrame || currentGamePad.dpad.left.wasPressedThisFrame)))
		{
			Move(moveRight: false);
		}
	}
}
