	{
		if (GameLobby.isOnlineGame ? CharacterSelectHandler_online.IsColorTaken(playerColors[selectedIndex].colorIndex) : CharacterSelectHandler.IsColorTaken(playerColors[selectedIndex].colorIndex, csb))
		{
			Move(moveRight: true);
		}
		init.color = playerColors[selectedIndex].colorIndex;
	}

	public override void SetToPlayerChoices(Player player, int index)
	{
		for (int i = 0; i < playerColors.Length; i++)
		{
			if (playerColors[i].playerMaterial == player.Color)
			{
				Select(i);
				break;
			}
		}
