		{
			num2 = (num2 + num + playerColors.Length) % playerColors.Length;
		}
		animateOnColorChange.Animate();
		Select(num2);
		wobbleAnimation.PlayWobbleAnimation();
		AudioManager.Get().PlayRandomWithPrefix("transform");
	}

	private void Update()
	{
		Keyboard current = Keyboard.current;
		Gamepad currentGamePad = csb.currentGamePad;
		if ((csb.UseskeyboardMouse && (current.dKey.wasPressedThisFrame || current.rightArrowKey.wasPressedThisFrame)) || (currentGamePad != null && (currentGamePad.leftStick.right.wasPressedThisFrame || currentGamePad.dpad.right.wasPressedThisFrame)))
		{
			Move(moveRight: true);
		}
		else if ((csb.UseskeyboardMouse && (current.aKey.wasPressedThisFrame || current.leftArrowKey.wasPressedThisFrame)) || (currentGamePad != null && (currentGamePad.leftStick.left.wasPressedThisFrame || currentGamePad.dpad.left.wasPressedThisFrame)))
		{
			Move(moveRight: false);
		}
	}
}
public class SelectionBorder : MonoBehaviour
{
	public UnityEngine.Color SelectedBorderColor;

	public UnityEngine.Color UnSelectedBorderColor;

	public UnityEngine.Color SelectedTextColor;

	public UnityEngine.Color UnselectedTextColor;

	private UnityEngine.UI.Image Border;

	public TextMeshProUGUI[] texts;

	public Button[] ButtonsWithTextColors;

	private IMenuItem ParentMenuItem;

	public bool overrideColorIfDemo;

	public bool overrideAlphaIfNotOnSteam;

	public UnityEngine.Color demoOnlyBorderColor;

	public UnityEngine.Color demoOnlyTextColor;

	private void Awake()
	{
		Border = GetComponent<UnityEngine.UI.Image>();
		ParentMenuItem = GetComponentInParent<IMenuItem>();
	}

	private void Update()
	{
		bool flag = !SteamManager.instance.dlc.HasDLC();
		UnityEngine.Color color = ((overrideColorIfDemo && flag) ? demoOnlyBorderColor : UnSelectedBorderColor);
		UnityEngine.Color color2 = ((overrideColorIfDemo && flag) ? demoOnlyBorderColor : SelectedBorderColor);
		UnityEngine.Color color3 = ((overrideColorIfDemo && flag) ? demoOnlyTextColor : UnselectedTextColor);
		UnityEngine.Color color4 = ((overrideColorIfDemo && flag) ? demoOnlyTextColor : SelectedTextColor);
		if (overrideAlphaIfNotOnSteam && !SteamClient.IsValid)
		{
			color3.a = 0.5f;
			color.a = 0.5f;
			color2.a = 0.5f;
			color4.a = 0.5f;
		}
		if (ParentMenuItem.InputActive)
		{
			if (Border != null)
			{
				Border.color = color2;
			}
			if (texts != null)
			{
				for (int i = 0; i < texts.Length; i++)
				{
					texts[i].color = color4;
				}
			}
			if (ButtonsWithTextColors != null)
			{
				for (int j = 0; j < ButtonsWithTextColors.Length; j++)
				{
					ColorBlock colors = ButtonsWithTextColors[j].colors;
					colors.normalColor = color2;
					ButtonsWithTextColors[j].colors = colors;
				}
			}
			return;
		}
		if (Border != null)
		{
			Border.color = color;
		}
		if (texts != null)
		{
			for (int k = 0; k < texts.Length; k++)
			{
				texts[k].color = color3;
			}
		}
		if (ButtonsWithTextColors != null)
		{
			for (int l = 0; l < ButtonsWithTextColors.Length; l++)
			{
				ColorBlock colors2 = ButtonsWithTextColors[l].colors;
				colors2.normalColor = color3;
				ButtonsWithTextColors[l].colors = colors2;
			}
		}
	}
}
public class SelectYourAbilities : MonoBehaviour
{
	[SerializeField]
	private RectTransform SelectAbilitiesText;

	[SerializeField]
	private RectTransform AText;

	[SerializeField]
	private RectTransform UseAbilityText;

	[SerializeField]
	private RectTransform[] bigBlueBox;

	private Vector2 selectAbilitiesPos;

	private Vector2 pos_SelectAbilitiesText;

	private Vector2 pos_AText;

	private Vector2 pos_UseAbilityText;

	private Vector2[] pos_bigBlueBox;

	[SerializeField]
	private Vector2 StartingYOffset = Vector3.up * 100f;

	[SerializeField]
	private AnimationCurve curve;

	[SerializeField]
	private float delay = 0.5f;

	[SerializeField]
	private float selectAbilitiesTextDelay = 0.2f;

	[SerializeField]
	private float selectAbilitiesTextLifeSpan = 3f;

	[SerializeField]
	private float serialDelay = 0.3f;

	[SerializeField]
	private float timeVisible = 5f;

	[SerializeField]
	private float timeInvisible = 7f;

	private void Awake()
	{
		pos_bigBlueBox = new Vector2[bigBlueBox.Length];
		pos_SelectAbilitiesText = SelectAbilitiesText.anchoredPosition;
		pos_AText = AText.anchoredPosition;
		pos_UseAbilityText = UseAbilityText.anchoredPosition;
		for (int i = 0; i < pos_bigBlueBox.Length; i++)
		{
			pos_bigBlueBox[i] = bigBlueBox[i].anchoredPosition;
		}
		SelectAbilitiesText.anchoredPosition += StartingYOffset;
		AText.anchoredPosition += StartingYOffset;
		UseAbilityText.anchoredPosition += StartingYOffset;
		for (int j = 0; j < pos_bigBlueBox.Length; j++)
		{
			bigBlueBox[j].anchoredPosition += StartingYOffset;
		}
	}

	private void Update()
	{
		float num = curve.keys[curve.length - 1].time + serialDelay * 5f;
		float num2 = (Time.timeSinceLevelLoad - delay) % (2f * num + (timeVisible + timeInvisible));
		if (num2 < 0f)
		{
			num2 = 0f;
		}
		else if (num2 >= 2f * num + timeVisible)
		{
			num2 = 0f;
		}
		else if (num2 >= num)
		{
			num2 = Mathf.Max(num + timeVisible - num2, 0f);
		}
		AText.anchoredPosition = pos_AText + StartingYOffset * curve.Evaluate(num2 - serialDelay);
		for (int i = 0; i < pos_bigBlueBox.Length; i++)
		{
			bigBlueBox[i].anchoredPosition = pos_bigBlueBox[i] + StartingYOffset * curve.Evaluate(num2 - serialDelay * 2f);
		}
		float num3 = Time.timeSinceLevelLoad - selectAbilitiesTextDelay;
		if (num3 < 0f)
		{
			num3 = 0f;
		}
		else if (num3 >= 2f * num + selectAbilitiesTextLifeSpan)
		{
			num3 = 0f;
		}
		else if (num3 >= num)
		{
			num3 = Mathf.Max(num + selectAbilitiesTextLifeSpan - num3, 0f);
		}
		SelectAbilitiesText.anchoredPosition = pos_SelectAbilitiesText + StartingYOffset * curve.Evaluate(num3);
	}
}
public class SessionWinner : MonoBehaviour
{
	public float SecondsBeforeYouCanExit;

	public Settings settings;

	private float time;

	private void Start()
	{
		time = 0f;
	}

	private void Update()
	{
		time += Time.deltaTime;
		bool flag = false;
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int i = 0; i < list.Count; i++)
		{
			flag |= list[i].StartButton_isDown_RAW();
		}
		if (flag && time > SecondsBeforeYouCanExit)
		{
			AudioManager.Get().Play("startGame");
			PlayerHandler.Get().PlayerList().Clear();
			SceneManager.LoadScene(Constants.ColorSelectorSceneIndex(settings.GameMode), LoadSceneMode.Single);
		}
	}
}
