[CreateAssetMenu(fileName = "Settings", menuName = "Dynaslimes/Settings", order = 1)]
public class Settings : ScriptableObject
{
	public static string[] languages = new string[14]
	{
		"english", "german", "spanish", "french", "italian", "japanese", "koreana", "polish", "brazilian", "russian",
		"swedish", "turkish", "schinese", "tchinese"
	};

	private static Settings instance;

	public GameModeSelection GameMode;

	private int numberOfAbilities;

	public int TrueNumberOfAbilities => numberOfAbilities;

	public int NumberOfAbilities
	{
		get
		{
			if (GameLobby.nrOfAbilities > 0 && GameLobby.isOnlineGame)
			{
				return GameLobby.nrOfAbilities;
			}
			if (numberOfAbilities <= 0)
			{
				return 2;
			}
			return numberOfAbilities;
		}
		set
		{
			numberOfAbilities = value;
		}
	}

	public bool AllowScreenShake { get; set; }

	public bool Vsync { get; set; }

	public int FullScreen { get; set; }

	public int MusicVolume { get; set; }

	public int SfxVolume { get; set; }

	public int Rumble { get; set; }

	public int ResolutionWidth { get; set; }

	public int ResolutionHeight { get; set; }

	public Language Language { get; set; }

	public int Hide { get; set; }

	public static Settings Get()
	{
		return instance;
	}

	public void Init()
	{
		instance = this;
		numberOfAbilities = PlayerPrefs.GetInt("NumberOfAbilities", 3);
		AllowScreenShake = PlayerPrefs.GetInt("AllowScreenShake", 1) == 1;
		Vsync = PlayerPrefs.GetInt("Vsync", 0) == 1;
		MusicVolume = PlayerPrefs.GetInt("MusicVolume", 7);
		SfxVolume = PlayerPrefs.GetInt("SfxVolume", 10);
		Rumble = PlayerPrefs.GetInt("Rumble", 1);
		FullScreen = PlayerPrefs.GetInt("FullScreen", 1);
		int defaultValue = 0;
		if (SteamClient.IsValid)
		{
			for (int i = 0; i < languages.Length; i++)
			{
				if (SteamApps.GameLanguage.Equals(languages[i]))
				{
					defaultValue = i;
					break;
				}
			}
		}
		Language = (Language)PlayerPrefs.GetInt("Language", defaultValue);
		ResolutionWidth = PlayerPrefs.GetInt("ResolutionWidth", Screen.currentResolution.width);
		ResolutionHeight = PlayerPrefs.GetInt("ResolutionHeight", Screen.currentResolution.height);
		Hide = PlayerPrefs.GetInt("Hide", 0);
		Save();
	}

	public void Save()
	{
		PlayerPrefs.SetInt("NumberOfAbilities", numberOfAbilities);
		PlayerPrefs.SetInt("AllowScreenShake", AllowScreenShake ? 1 : 0);
		PlayerPrefs.SetInt("MusicVolume", MusicVolume);
		PlayerPrefs.SetInt("SfxVolume", SfxVolume);
		PlayerPrefs.SetInt("Rumble", Rumble);
		PlayerPrefs.SetInt("Vsync", Vsync ? 1 : 0);
		PlayerPrefs.SetInt("ResolutionWidth", ResolutionWidth);
		PlayerPrefs.SetInt("ResolutionHeight", ResolutionHeight);
		PlayerPrefs.SetInt("FullScreen", FullScreen);
		PlayerPrefs.SetInt("Hide", Hide);
		FullScreenMode fullScreenMode = ((FullScreen == 0) ? FullScreenMode.Windowed : ((FullScreen == 1) ? FullScreenMode.FullScreenWindow : FullScreenMode.ExclusiveFullScreen));
		if (Screen.currentResolution.width != ResolutionWidth || Screen.currentResolution.height != ResolutionHeight || Screen.fullScreenMode != fullScreenMode)
		{
			Screen.SetResolution(ResolutionWidth, ResolutionHeight, fullScreenMode);
			SettingsInitializer.UpdateQualityLevelBasedOnResolution(ResolutionHeight);
		}
		QualitySettings.vSyncCount = (Vsync ? 1 : 0);
		if (SteamClient.IsValid && SteamManager.instance != null && SteamManager.instance.currentLobby.IsOwnedBy(SteamClient.SteamId))
		{
			GameLobby.nrOfAbilities = numberOfAbilities;
			SteamManager.instance.BroadcastLobbyInitPacket();
		}
		if (Get().Hide == 2)
		{
			SteamFrame.HideAllAvatars();
		}
		else
		{
			SteamFrame.ShowAllAvatars();
		}
	}
}
public class SettingSelector : MonoBehaviour, IMenuItem
{
	private int optionIndex;

	public Settings settings;

	public GameObject[] Images;

	private bool inputActive;

	public string setting;

	public int optionIndexAdd_HACK;

	private BindInputAxisToButton[] InputArrows;

	public UnityEvent[] SetSetting;

	public bool InputActive
	{
		get
		{
			return inputActive;
		}
		set
		{
			inputActive = value;
		}
	}

	private void Awake()
	{
		Init();
	}

	public void Init()
	{
		if (settings != null)
		{
			object value = settings.GetType().GetProperty(setting).GetValue(settings);
			int num = ((!(value.GetType() == typeof(bool))) ? ((int)value + optionIndexAdd_HACK) : ((!(bool)value) ? 1 : 0));
			optionIndex = num;
		}
		else
		{
			optionIndex = 0;
		}
		InputArrows = GetComponentsInChildren<BindInputAxisToButton>();
	}

	private void Update()
	{
		for (int i = 0; i < Images.Length; i++)
		{
			if (optionIndex == i)
			{
				Images[i].SetActive(value: true);
			}
			else
			{
				Images[i].SetActive(value: false);
			}
		}
		for (int j = 0; j < InputArrows.Length; j++)
		{
			InputArrows[j].enabled = InputActive;
		}
	}

	public void Next()
	{
		optionIndex = (optionIndex + 1) % Images.Length;
		SetSetting[optionIndex].Invoke();
		Update();
	}

	public void Previous()
	{
		optionIndex = (optionIndex - 1 + Images.Length) % Images.Length;
		SetSetting[optionIndex].Invoke();
		Update();
	}
}
public class SteamFrame : MonoBehaviour
{
	public static bool IsInitialized;

	private static SteamFrame selfRef;

	public Texture2D MyAvatar;

	private Cache cache;

	public PlayerColors playerColors;

	public SteamManager steamState;

	public SteamFrameButton SelfSquare;

	public List<SteamFrameButton> squares = new List<SteamFrameButton>();

	public UnityEngine.UI.Image[] lookingForPlayersCircles = new UnityEngine.UI.Image[3];

	private RectTransform overlayRectTrans;

	private RectTransform selfSquareRectTrans;

	private int[] currentSquareColors = new int[3] { -1, -1, -1 };

	private int localSquareColor = -1;

	private bool leavingLobby;

	private int nrOfSquares;

	public int buttonSeparation = 73;

	private bool isLobbyOwner;

	public static Texture2D Convert(Steamworks.Data.Image image)
	{
		if (image.Width == 0 || image.Width == 0)
		{
			UnityEngine.Debug.LogError("tried creating a texture of size 0x0 in SteamFrame");
			return Texture2D.blackTexture;
		}
		Texture2D texture2D = new Texture2D((int)image.Width, (int)image.Height, TextureFormat.ARGB32, mipChain: false);
		texture2D.filterMode = FilterMode.Trilinear;
		for (int i = 0; i < image.Width; i++)
		{
			for (int j = 0; j < image.Height; j++)
			{
				Steamworks.Data.Color pixel = image.GetPixel(i, j);
				texture2D.SetPixel(i, (int)image.Height - j, new UnityEngine.Color((int)pixel.r, (int)pixel.g, (int)pixel.b, (int)pixel.a) / 255f);
			}
		}
		texture2D.Apply();
		return texture2D;
	}

	public static void SetHidden(bool hide)
	{
		if (IsInitialized)
		{
			selfRef.gameObject.SetActive(!hide);
		}
	}

	private void Awake()
	{
		if (IsInitialized)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		for (int i = 0; i < squares.Count; i++)
		{
			squares[i].image.materialForRendering.SetColor("_Blue", UnityEngine.Color.white);
		}
		SelfSquare.image.materialForRendering.SetColor("_Blue", UnityEngine.Color.white);
		localSquareColor = -1;
		for (int j = 0; j < currentSquareColors.Length; j++)
		{
			currentSquareColors[j] = -1;
		}
		IsInitialized = true;
		selfRef = this;
		UnityEngine.Object.DontDestroyOnLoad(this);
		selfSquareRectTrans = SelfSquare.GetComponent<RectTransform>();
	}

	public async void LoadOwnAvatar()
	{
		if (!SteamClient.IsValid)
		{
			return;
		}
		Steamworks.Data.Image? image = await SteamFriends.GetMediumAvatarAsync(SteamClient.SteamId);
		if (image.HasValue)
		{
			MyAvatar = Convert(image.Value);
			SelfSquare.image.material.SetTexture("_ProfileTexture", MyAvatar);
			if (Settings.Get().Hide != 2)
			{
				SelfSquare.image.material.SetTexture("_ProfileTexture", MyAvatar);
			}
			else
			{
				SelfSquare.image.material.SetTexture("_ProfileTexture", Texture2D.blackTexture);
			}
		}
	}

	private void Start()
	{
		LoadOwnAvatar();
	}

	public void ClickKickPlayer(int index)
	{
		squares[index].button.enabled = false;
		steamState.KickPlayer(index);
	}

	public void ClickLeave()
	{
		if (!leavingLobby)
		{
			GameSessionHandler.LeaveGame(abandonLobbyEntirely: false, sendOthersBackToAbilitySelect: true);
			leavingLobby = true;
		}
	}

	public void ClickOpenOverlay()
	{
		SteamFriends.OpenOverlay("friends");
	}

	public void UpdateSquareColors(int playerCount)
	{
		for (int i = 0; i < squares.Count; i++)
		{
			if (i < playerCount)
			{
				int lobby_color = steamState.connectedPlayers[i].lobby_color;
				if (steamState.connectedPlayers[i].hasAvatar && currentSquareColors[i] != lobby_color && steamState.connectedPlayers[i].lobby_isReady)
				{
					squares[i].image.materialForRendering.SetColor("_Blue", playerColors[steamState.connectedPlayers[i].lobby_color].playerMaterial.GetColor("_ShadowColor"));
					currentSquareColors[i] = lobby_color;
				}
			}
		}
		if (localSquareColor != CharacterSelectHandler_online.localPlayerInit.color && CharacterSelectHandler_online.IsLocalPlayerReady())
		{
			localSquareColor = CharacterSelectHandler_online.localPlayerInit.color;
			UnityEngine.Color color = playerColors[localSquareColor].playerMaterial.GetColor("_ShadowColor");
			SelfSquare.image.materialForRendering.SetColor("_Blue", color);
		}
	}

	public static void HideAllAvatars()
	{
		if (selfRef != null)
		{
			selfRef.SelfSquare.image.material.SetTexture("_ProfileTexture", Texture2D.blackTexture);
			for (int i = 0; i < SteamManager.instance.connectedPlayers.Count; i++)
			{
				selfRef.squares[i].image.material.SetTexture("_ProfileTexture", Texture2D.blackTexture);
			}
		}
	}

	public static void ShowAllAvatars()
	{
		if (!(selfRef != null))
		{
			return;
		}
		selfRef.SelfSquare.image.material.SetTexture("_ProfileTexture", selfRef.MyAvatar);
		for (int i = 0; i < SteamManager.instance.connectedPlayers.Count; i++)
		{
			if (SteamManager.instance.connectedPlayers[i].hasAvatar)
			{
				selfRef.squares[i].image.material.SetTexture("_ProfileTexture", SteamManager.instance.connectedPlayers[i].avatar);
			}
		}
	}

	private void Update()
	{
		if (!SteamClient.IsValid)
		{
			return;
		}
		int num = 0;
		for (int i = 0; i < steamState.connectedPlayers.Count; i++)
		{
			if (steamState.connectedPlayers[i].hasAvatar)
			{
				num++;
			}
		}
		SelfSquare.button.enabled = num > 0 && (GameSession.inMenus || SteamManager.currentlyLookingForPlayers);
		UpdateSquareColors(num);
		isLobbyOwner = steamState.currentLobby.IsOwnedBy(SteamClient.SteamId);
		if (isLobbyOwner && GameSession.inMenus)
		{
			for (int j = 0; j < squares.Count; j++)
			{
				squares[j].button.enabled = true;
			}
		}
		else
		{
			for (int k = 0; k < squares.Count; k++)
			{
				squares[k].button.enabled = false;
			}
		}
		if (nrOfSquares != num)
		{
			leavingLobby = false;
			nrOfSquares = num;
			for (int l = 0; l < squares.Count; l++)
			{
				if (l < num)
				{
					if (steamState.connectedPlayers[l].hasAvatar)
					{
						if (Settings.Get().Hide != 2)
						{
							squares[l].image.material.SetTexture("_ProfileTexture", steamState.connectedPlayers[l].avatar);
						}
						else
						{
							squares[l].image.material.SetTexture("_ProfileTexture", Texture2D.blackTexture);
						}
						squares[l].gameObject.SetActive(value: true);
						squares[l].button.enabled = isLobbyOwner;
					}
					else
					{
						squares[l].gameObject.SetActive(value: false);
					}
				}
				else
				{
					squares[l].gameObject.SetActive(value: false);
				}
			}
		}
		if (!GameSession.inMenus && Settings.Get().Hide == 2)
		{
			for (int m = 0; m < squares.Count; m++)
			{
				squares[m].image.enabled = false;
			}
			SelfSquare.image.enabled = false;
		}
		else
		{
			for (int n = 0; n < squares.Count; n++)
			{
				squares[n].image.enabled = true;
			}
			SelfSquare.image.enabled = true;
		}
		for (int num2 = 0; num2 < squares.Count; num2++)
		{
			lookingForPlayersCircles[num2].enabled = !squares[num2].gameObject.activeSelf && SteamManager.currentlyLookingForPlayers;
			if (lookingForPlayersCircles[num2].enabled && SteamManager.currentlyLookingForPlayers)
			{
				lookingForPlayersCircles[num2].rectTransform.localEulerAngles += new Vector3(0f, 0f, 84f * Time.deltaTime);
			}
		}
	}
}
