public class SteamSocket : SocketManager
{
	private byte[] messageBuffer = new byte[2048];

	private byte[] ulongConversionArray = new byte[8];

	private byte[] uintConversionArray = new byte[4];

	private byte[] ushortConversionArray = new byte[2];

	private byte[] lobbyPingAckBuffer = new byte[6];

	private byte[] lobbyInitBuffer = new byte[2];

	private byte[] startRequestBuffer = new byte[105];

	private byte[] uiCommunicationBuffer = new byte[1];

	public override void OnConnecting(Connection connection, ConnectionInfo data)
	{
		base.OnConnecting(connection, data);
		UnityEngine.Debug.Log("SocketManager OnConnecting");
	}

	public override void OnConnected(Connection connection, ConnectionInfo data)
	{
		base.OnConnected(connection, data);
		UnityEngine.Debug.Log("New player connected");
	}

	public override void OnDisconnected(Connection connection, ConnectionInfo data)
	{
		base.OnDisconnected(connection, data);
		UnityEngine.Debug.Log("Player disconnected");
	}

	public override void OnMessage(Connection connection, NetIdentity identity, IntPtr data, int size, long messageNum, long recvTime, int channel)
	{
		Marshal.Copy(data, messageBuffer, 0, size);
		if (!identity.SteamId.IsValid)
		{
			UnityEngine.Debug.Log("got message from invalid steamId");
			return;
		}
		SteamId steamId = identity.SteamId;
		if (!new Friend(steamId).IsIn(SteamManager.instance.currentLobby.Id))
		{
			UnityEngine.Debug.Log("Ignored a msg from " + identity.SteamId.ToString());
			return;
		}
		switch (size)
		{
		case 105:
			if (SteamManager.instance.currentLobby.IsOwnedBy(identity.SteamId))
			{
				SteamManager.startParameters = NetworkTools.ReadStartRequest(messageBuffer, ref uintConversionArray, ref ulongConversionArray, ref ushortConversionArray);
				SteamManager.instance.EncodeCurrentStartParameters_forReplay(ref SteamManager.instance.networkClient.EncodedStartRequest, SteamManager.startParameters);
				if (GameSession.inMenus)
				{
					CharacterSelectHandler_online.ForceStartGame();
				}
				else
				{
					SteamManager.ForceLoadNextLevel();
				}
			}
			return;
		case 1:
			switch (NetworkTools.ReadUICom(messageBuffer).PacketTypeAsEnum)
			{
			case UIPacketType.suggestStartGame:
			{
				if (!SteamManager.LocalPlayerIsLobbyOwner)
				{
					break;
				}
				if (GameSession.inMenus)
				{
					CharacterSelectHandler_online.TryStartGame(errorSoundIfFail: false);
					break;
				}
				List<Player> list = PlayerHandler.Get().PlayerList();
				int hostPlayerId = 0;
				for (int n = 0; n < list.Count; n++)
				{
					if (SteamManager.instance.currentLobby.IsOwnedBy(list[n].steamId))
					{
						hostPlayerId = list[n].Id;
					}
				}
				CharacterStatsList.OnNextLevelWasSuggested(hostPlayerId, SteamManager.instance.abilityIcons);
				break;
			}
			case UIPacketType.reject_readyUp:
				CharacterSelectHandler_online.OnReadyUpReject();
				break;
			case UIPacketType.noLongerReady:
			{
				List<SteamConnection> connectedPlayers6 = SteamManager.instance.connectedPlayers;
				for (int num2 = 0; num2 < connectedPlayers6.Count; num2++)
				{
					if (connectedPlayers6[num2].id.Value == (ulong)identity.SteamId)
					{
						connectedPlayers6[num2].lobby_isReady = false;
						break;
					}
				}
				break;
			}
			case UIPacketType.backToAbilitySelect:
				if (SteamManager.instance.currentLobby.IsOwnedBy(identity.SteamId))
				{
					SteamManager.ForceBacktoAbilitySelect();
				}
				break;
			case UIPacketType.InstantBackToAbilitySelect:
				if (GameLobby.isOnlineGame && !GameSession.inMenus)
				{
					SteamManager.ForceBacktoAbilitySelect_instant();
				}
				break;
			case UIPacketType.suggestBackToAbility:
				if (SteamManager.LocalPlayerIsLobbyOwner)
				{
					CharacterStatsList.SuggestBacktoAbilitySelect();
				}
				break;
			case UIPacketType.ForceCloseCurrentGame:
				if (GameLobby.isOnlineGame && !GameSession.inMenus)
				{
					GameSessionHandler.LeaveGame(abandonLobbyEntirely: true);
				}
				break;
			case UIPacketType.ack:
				break;
			}
			return;
		case 3:
		{
			List<SteamConnection> connectedPlayers4 = SteamManager.instance.connectedPlayers;
			for (int l = 0; l < connectedPlayers4.Count; l++)
			{
				if ((ulong)connectedPlayers4[l].id == (ulong)identity.SteamId)
				{
					LobbyStateUpdate lobbyStateUpdate = NetworkTools.ReadLobbyStateUpdate(messageBuffer);
					connectedPlayers4[l].lobby_color = lobbyStateUpdate.color;
					connectedPlayers4[l].lobby_team = lobbyStateUpdate.team;
					connectedPlayers4[l].lobby_isReady = lobbyStateUpdate.isReady > 0;
					break;
				}
			}
			return;
		}
		case 4:
		{
			List<SteamConnection> connectedPlayers5 = SteamManager.instance.connectedPlayers;
			for (int m = 0; m < connectedPlayers5.Count; m++)
			{
				if ((ulong)connectedPlayers5[m].id == (ulong)identity.SteamId)
				{
					SimpleLobbyReady simpleLobbyReady = NetworkTools.ReadSimpleLobbyReady(messageBuffer);
					connectedPlayers5[m].lobby_ability1 = simpleLobbyReady.ability1;
					connectedPlayers5[m].lobby_ability2 = simpleLobbyReady.ability2;
					connectedPlayers5[m].lobby_ability3 = simpleLobbyReady.ability3;
					connectedPlayers5[m].lobby_isReady = true;
					break;
				}
			}
			return;
		}
		case 15:
		{
			LobbyReadyPacket lobbyReadyPacket = NetworkTools.ReadLobbyReadyPacket(messageBuffer, ref ulongConversionArray);
			if (SteamManager.instance.currentLobby.IsOwnedBy(SteamClient.SteamId))
			{
				if (CharacterSelectHandler_online.IsColorTaken(lobbyReadyPacket.color, includeLocalChoice: true))
				{
					SteamManager.instance.SendLobbyReadyReject(identity);
					return;
				}
				SteamManager.instance.BroadcastLobbyReadyPacket(lobbyReadyPacket);
			}
			bool num = (ulong)identity.SteamId == (ulong)SteamManager.instance.currentLobby.Owner.Id;
			bool flag = identity.SteamId.Value == lobbyReadyPacket.steamId;
			if (!num && !flag)
			{
				return;
			}
			List<SteamConnection> connectedPlayers3 = SteamManager.instance.connectedPlayers;
			for (int k = 0; k < connectedPlayers3.Count; k++)
			{
				if (connectedPlayers3[k].id.Value == lobbyReadyPacket.steamId)
				{
					connectedPlayers3[k].lobby_isReady = true;
					connectedPlayers3[k].lobby_color = lobbyReadyPacket.color;
					connectedPlayers3[k].lobby_team = lobbyReadyPacket.team;
					connectedPlayers3[k].lobby_ability1 = lobbyReadyPacket.ability1;
					connectedPlayers3[k].lobby_ability2 = lobbyReadyPacket.ability2;
					connectedPlayers3[k].lobby_ability3 = lobbyReadyPacket.ability3;
					connectedPlayers3[k].ownsFullGame = lobbyReadyPacket.ownsFullGame != 0;
					connectedPlayers3[k].lobby_usesKeyboardAndMouse = lobbyReadyPacket.usesKeyboardAndMouse > 0;
					return;
				}
			}
			CharacterSelectHandler_online.OnReadyUpAccept(lobbyReadyPacket);
			return;
		}
		case 2:
		{
			LobbyInit lobbyInit = NetworkTools.ReadLobbyInit(messageBuffer);
			CharacterSelectHandler_online.OnLobbyInit();
			GameLobby.nrOfAbilities = lobbyInit.nrOfAbilites;
			return;
		}
		case 6:
		{
			if (messageBuffer[0] <= 4)
			{
				break;
			}
			Ack ack = NetworkTools.ReadAck(messageBuffer, ref uintConversionArray);
			if (ack.PacketTypeAsEnum == UIPingType.ack)
			{
				List<SteamConnection> connectedPlayers = SteamManager.instance.connectedPlayers;
				for (int i = 0; i < connectedPlayers.Count; i++)
				{
					if (connectedPlayers[i].id.Value == (ulong)identity.SteamId)
					{
						connectedPlayers[i].ReceiveAck(ack, Time.timeSinceLevelLoad);
						return;
					}
				}
			}
			else
			{
				if (ack.PacketTypeAsEnum != UIPingType.ping)
				{
					break;
				}
				List<SteamConnection> connectedPlayers2 = SteamManager.instance.connectedPlayers;
				for (int j = 0; j < connectedPlayers2.Count; j++)
				{
					if (connectedPlayers2[j].id.Value == (ulong)identity.SteamId)
					{
						NetworkTools.EncodeAckForNetwork(ref lobbyPingAckBuffer, new Ack
						{
							playerId = 6,
							seqNumber = ack.seqNumber
						});
						connectedPlayers2[j].Connection.SendMessage(lobbyPingAckBuffer, SendType.NoNagle);
						return;
					}
				}
			}
			break;
		}
		}
		if (SteamManager.networkClientHandle != null && SteamManager.networkClientHandle.hasBeenInitialized)
		{
			SteamManager.networkClientHandle.ReadPacket(messageBuffer, size);
		}
	}
}
public class SteamConnection : ConnectionManager
{
	public string steamName;

	public SteamId id;

	public ushort readySeqNum;

	public Texture2D avatar;

	public bool hasAvatar;

	public bool beingKicked;

	public bool lobby_isReady;

	public bool lobby_usesKeyboardAndMouse;

	public byte lobby_team;

	public int lobby_color;

	public byte lobby_ability1;

	public byte lobby_ability2;

	public byte lobby_ability3;

	public bool ownsFullGame;

	public uint pingsSentToThisPlayer;

	public uint acksReceivedFromThisPlayer;

	private float ping;

	private static byte[] lobbyInitBuffer = new byte[2];

	public bool haveSentInit_hostonly;

	private Dictionary<uint, float> PingTimes = new Dictionary<uint, float>();

	private uint[] toRemovePingTimes = new uint[256];

	public float Ping => ping;

	public override void OnConnected(ConnectionInfo info)
	{
		base.OnConnected(info);
		List<SteamConnection> connectedPlayers = SteamManager.instance.connectedPlayers;
		if (!SteamManager.instance.currentLobby.IsOwnedBy(SteamClient.SteamId))
		{
			return;
		}
		for (int i = 0; i < connectedPlayers.Count; i++)
		{
			if (connectedPlayers[i].Connected)
			{
				NetworkTools.EncodeLobbyInit(ref lobbyInitBuffer, new LobbyInit
				{
					nrOfAbilites = (byte)Settings.Get().NumberOfAbilities,
					extraByte = 0
				});
				connectedPlayers[i].Connection.SendMessage(lobbyInitBuffer);
				connectedPlayers[i].haveSentInit_hostonly = true;
				break;
			}
		}
	}

	public override void OnDisconnected(ConnectionInfo info)
	{
		base.OnDisconnected(info);
		Connected = false;
	}

	public void SendPing(float timestamp, byte[] ackPingBuffer)
	{
		int num = 100;
		if (PingTimes.Count > num)
		{
			int num2 = 0;
			foreach (KeyValuePair<uint, float> pingTime in PingTimes)
			{
				if (pingTime.Value > 5f)
				{
					toRemovePingTimes[num2] = pingTime.Key;
					num2++;
				}
			}
			for (int i = 0; i < num2 && i < toRemovePingTimes.Length; i++)
			{
				PingTimes.Remove(toRemovePingTimes[i]);
			}
		}
		PingTimes.Add(pingsSentToThisPlayer, timestamp);
		NetworkTools.EncodeAckForNetwork(ref ackPingBuffer, new Ack
		{
			playerId = 5,
			seqNumber = pingsSentToThisPlayer
		});
		Connection.SendMessage(ackPingBuffer, SendType.NoNagle);
		pingsSentToThisPlayer++;
	}

	public void ReceiveAck(Ack ack, float timeOfArrival)
	{
		if (PingTimes.ContainsKey(ack.seqNumber))
		{
			float num = PingTimes[ack.seqNumber];
			ping = EstimatePing(timeOfArrival - num);
			PingTimes.Remove(ack.seqNumber);
		}
	}

	private float EstimatePing(float newLag)
	{
		return newLag;
	}
}
