public class SteamManager : MonoBehaviour
{
	public struct LobbyOwnerRecord
	{
		public int accId;

		public float timeStamp;

		public LobbyOwnerRecord(int accId, float timeStamp)
		{
			this.accId = accId;
			this.timeStamp = timeStamp;
		}
	}

	public DLC dlc = new DLC();

	private uint appId = 1686940u;

	private SteamSocket socket;

	private bool earlyDestroy;

	private ulong lobbyToJoinOnStartup;

	private bool joinLobbyOnStartup;

	private static bool isJoiningAlobbyAtm;

	[HideInInspector]
	public Lobby currentLobby;

	public Host networkClient;

	public List<SteamConnection> connectedPlayers = new List<SteamConnection>();

	public static Host networkClientHandle;

	public int startFrameBuffer = 8;

	public bool checkForDesyncs;

	private float timeSinceLastStartRequest = 100000f;

	private byte[] replay_startRequestBuffer = new byte[105];

	private byte[] startRequestBuffer = new byte[105];

	private byte[] lobbyStateUpdateBuffer = new byte[3];

	private byte[] simpleLobbyStateUpdateBuffer = new byte[4];

	private byte[] lobbyReadyBuffer = new byte[15];

	private byte[] lobbyInitBuffer = new byte[2];

	private ushort nextStartGameSeq = 1;

	public static StartRequestPacket startParameters;

	public static SteamManager instance;

	private byte[] uiCommunicationBuffer = new byte[1];

	private const float timeBeforeReAutoReJoin = 30f;

	private List<LobbyOwnerRecord> recentlyJoinedLobbies = new List<LobbyOwnerRecord>();

	private double timeSinceMatchmakingStarted;

	private static bool currentlyInMatchmaking;

	public static bool currentlyLookingForPlayers;

	[SerializeField]
	private NamedSpriteList abilityIconsFull;

	[SerializeField]
	private NamedSpriteList abilityIconsDemo;

	public static bool LocalPlayerIsLobbyOwner
	{
		get
		{
			if (SteamClient.IsValid)
			{
				return instance.currentLobby.IsOwnedBy(SteamClient.SteamId);
			}
			return false;
		}
	}

	public NamedSpriteList abilityIcons
	{
		get
		{
			if (!dlc.HasDLC())
			{
				return abilityIconsDemo;
			}
			return abilityIconsFull;
		}
	}

	private void Awake()
	{
		UnityEngine.Object.DontDestroyOnLoad(this);
		if (instance != null)
		{
			earlyDestroy = true;
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		instance = this;
		try
		{
			SteamClient.Init(appId, asyncCallbacks: false);
			AchievementHandler.InitializeAchievements();
		}
		catch (Exception message)
		{
			UnityEngine.Debug.LogError("could not log onto steam, either it is not started, it's servers are down, we can't find steam_api dlls or we don't have permission to open appid");
			UnityEngine.Debug.LogError(message);
			ErrorHandlingTextDisconnect.SetMainMenuLogMessage("ERROR: could not connect to Steam");
			return;
		}
		bool flag = false;
		SteamMatchmaking.OnLobbyGameCreated += OnLobbyGameCreatedCallback;
		SteamMatchmaking.OnLobbyCreated += OnLobbyCreatedCallback;
		SteamMatchmaking.OnLobbyEntered += OnLobbyEnteredCallback;
		SteamMatchmaking.OnLobbyMemberJoined += OnLobbyMemberJoinedCallback;
		SteamMatchmaking.OnChatMessage += OnChatMessageCallback;
		SteamMatchmaking.OnLobbyMemberDisconnected += OnLobbyMemberDisconnectedCallback;
		SteamMatchmaking.OnLobbyMemberLeave += OnLobbyMemberLeaveCallback;
		SteamMatchmaking.OnLobbyDataChanged += OnLobbyDataChangedCallback;
		SteamFriends.OnGameLobbyJoinRequested += OnGameLobbyJoinRequestedCallback;
		MonoBehaviour.print(SteamClient.Name);
		bool flag2 = false;
		string[] commandLineArgs = Environment.GetCommandLineArgs();
		string text = null;
		for (int i = 0; i < commandLineArgs.Length; i++)
		{
			if (commandLineArgs[i].Equals("+connect_lobby") && i + 1 < commandLineArgs.Length)
			{
				text = commandLineArgs[i + 1];
				break;
			}
		}
		UnityEngine.Debug.Log(".net Commandline arguments: " + commandLineArgs);
		ulong result = 0uL;
		if (text != null && text != "" && ulong.TryParse(text, out result))
		{
			lobbyToJoinOnStartup = result;
			flag2 = true;
			joinLobbyOnStartup = true;
		}
		if (flag && !flag2)
		{
			flag2 = true;
		}
		if (!flag2)
		{
			createLobby();
		}
		socket = SteamNetworkingSockets.CreateRelaySocket<SteamSocket>();
	}

	private void Start()
	{
		if (joinLobbyOnStartup)
		{
			TryJoinLobby(lobbyToJoinOnStartup);
			joinLobbyOnStartup = false;
		}
	}

	private void TryJoinLobby(ulong id)
	{
		Lobby lobby = new Lobby(id);
		JoinLobby(lobby);
	}

	private async void createLobby()
	{
		await CreateFriendLobby();
		GameLobby.nrOfAbilities = Settings.Get().NumberOfAbilities;
	}

	private void OnGameLobbyJoinRequestedCallback(Lobby arg1, SteamId arg2)
	{
		foreach (Friend member in arg1.Members)
		{
			if ((ulong)member.Id == (ulong)SteamClient.SteamId)
			{
				MonoBehaviour.print("attempted to join a lobby you are already in");
				return;
			}
		}
		JoinLobby(arg1);
		MonoBehaviour.print("OnGameLobbyJoinRequestedCallback");
	}

	private async void JoinLobby(Lobby lobby)
	{
		isJoiningAlobbyAtm = true;
		RoomEnter roomEnter = await lobby.Join();
		if (roomEnter == RoomEnter.Success)
		{
			string data = lobby.GetData("version");
			if (lobby.GetData("version") == Constants.version)
			{
				currentLobby.Leave();
				currentLobby = lobby;
				RegisterAllInLobbyAsRecentlyPlayed(lobby);
				isJoiningAlobbyAtm = false;
			}
			else
			{
				isJoiningAlobbyAtm = false;
				RegisterAllInLobbyAsRecentlyPlayed(lobby);
				string text = "Could not join Lobby due to version mismatch\nYou are on " + Constants.version + "\nLobby is on " + data;
				UnityEngine.Debug.LogError("error joining lobby: " + text);
				ErrorHandlingTextDisconnect.SetMainMenuLogMessage(text);
			}
			CharacterSelectHandler_online.SetTeamColor(currentLobby.MemberCount - 1);
		}
		else
		{
			MonoBehaviour.print("could not join lobby : " + roomEnter);
			isJoiningAlobbyAtm = false;
		}
	}

	private void OnLobbyMemberLeaveCallback(Lobby arg1, Friend arg2)
	{
		if ((ulong)currentLobby.Id != (ulong)arg1.Id)
		{
			return;
		}
		MonoBehaviour.print("LobbyMemberLeft : " + arg2.Name);
		for (int i = 0; i < connectedPlayers.Count; i++)
		{
			if ((ulong)connectedPlayers[i].id == (ulong)arg2.Id)
			{
				connectedPlayers[i].Close();
				connectedPlayers.RemoveAt(i);
				break;
			}
		}
	}

	private void OnLobbyDataChangedCallback(Lobby lobby)
	{
		if ((ulong)currentLobby.Id == (ulong)lobby.Id)
		{
			UpdateLobbyPublicFlag(lobby);
		}
	}

	public void OnLobbyMemberDisconnectedCallback(Lobby arg1, Friend arg2)
	{
		if ((ulong)currentLobby.Id != (ulong)arg1.Id)
		{
			return;
		}
		for (int i = 0; i < connectedPlayers.Count; i++)
		{
			if ((ulong)connectedPlayers[i].id == (ulong)arg2.Id)
			{
				connectedPlayers[i].Close();
				connectedPlayers.RemoveAt(i);
				break;
			}
		}
		MonoBehaviour.print("OnLobbyMemberDisconnectedCallback");
	}

	private void OnChatMessageCallback(Lobby lobby, Friend sender, string msg)
	{
		if ((ulong)currentLobby.Id != (ulong)lobby.Id)
		{
			return;
		}
		MonoBehaviour.print("chat message callback: " + msg);
		if (currentLobby.IsOwnedBy(sender.Id) && SteamClient.Name == msg)
		{
			GameSessionHandler.LeaveGame(abandonLobbyEntirely: false, sendOthersBackToAbilitySelect: true);
		}
		if (msg.StartsWith("joinLobby:") && (GameSession.inMenus || !GameLobby.isOnlineGame))
		{
			string text = msg.Substring(10, msg.Length - 10);
			if (ulong.TryParse(text, out var result) && !isJoiningAlobbyAtm)
			{
				TryJoinLobby(result);
			}
			else if (isJoiningAlobbyAtm)
			{
				MonoBehaviour.print("already joining a lobby, ignoring request to join lobby:" + text);
			}
			else
			{
				MonoBehaviour.print("Could not parse lobbyId:" + text);
			}
		}
	}

	private void OnLobbyMemberJoinedCallback(Lobby lobby, Friend friend)
	{
		if ((ulong)currentLobby.Id == (ulong)lobby.Id)
		{
			MonoBehaviour.print("new player joined the lobby");
			AddMember(lobby, friend);
		}
	}

	private void OnLobbyEnteredCallback(Lobby lobby)
	{
		if ((ulong)currentLobby.Id != (ulong)lobby.Id)
		{
			return;
		}
		CharacterSelectHandler_online.StopWaitingForLobbyReadyUpResponse();
		MonoBehaviour.print("entered a lobby");
		for (int i = 0; i < connectedPlayers.Count; i++)
		{
			connectedPlayers[i].Close();
		}
		connectedPlayers.Clear();
		foreach (Friend member in lobby.Members)
		{
			if ((ulong)member.Id != (ulong)SteamClient.SteamId)
			{
				AddMember(lobby, member);
			}
		}
	}

	private void OnLobbyCreatedCallback(Result arg1, Lobby arg2)
	{
		MonoBehaviour.print("created a lobby");
	}

	private void OnLobbyGameCreatedCallback(Lobby arg1, uint arg2, ushort arg3, SteamId arg4)
	{
		MonoBehaviour.print("OnLobbyGameCreatedCallback");
	}

	private void AddMember(Lobby lobby, Friend newPlayer)
	{
		MonoBehaviour.print("creating new connection to " + newPlayer.Name);
		SteamConnection steamConnection = SteamNetworkingSockets.ConnectRelay<SteamConnection>(newPlayer.Id);
		steamConnection.steamName = newPlayer.Name;
		steamConnection.id = newPlayer.Id;
		connectedPlayers.Add(steamConnection);
		LoadAvatar(steamConnection);
	}

	public async void LoadAvatar(SteamConnection connection)
	{
		Steamworks.Data.Image? image = await SteamFriends.GetMediumAvatarAsync(connection.id);
		if (image.HasValue)
		{
			connection.avatar = SteamFrame.Convert(image.Value);
			connection.hasAvatar = true;
		}
	}

	public async Task<bool> CreateFriendLobby()
	{
		try
		{
			Lobby? lobby = await SteamMatchmaking.CreateLobbyAsync(4);
			if (!lobby.HasValue)
			{
				UnityEngine.Debug.Log("Lobby created but not correctly instantiated");
				throw new Exception();
			}
			currentLobby = lobby.Value;
			currentLobby.SetData("accId", ((int)SteamClient.SteamId.AccountId).ToString());
			currentLobby.SetData("version", Constants.version);
			currentLobby.SetFriendsOnly();
			currentLobby.SetJoinable(b: true);
			return true;
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.Log("Failed to create multiplayer lobby");
			UnityEngine.Debug.Log(ex.ToString());
			return false;
		}
	}

	public void KickPlayer(int connectedPlayerIndex)
	{
		SteamConnection steamConnection = connectedPlayers[connectedPlayerIndex];
		if (!steamConnection.beingKicked)
		{
			currentLobby.SendChatString(steamConnection.steamName);
			steamConnection.beingKicked = true;
		}
	}

	public void LeaveLobby()
	{
		if (SteamClient.IsValid)
		{
			currentLobby.Leave();
			createLobby();
		}
	}

	private void OnDisable()
	{
		if (!earlyDestroy && SteamClient.IsValid)
		{
			currentLobby.Leave();
			socket?.Close();
			for (int i = 0; i < connectedPlayers.Count; i++)
			{
				connectedPlayers[i].Close();
			}
			SteamClient.Shutdown();
		}
	}

	private void InitNetworkClient()
	{
		int localPlayerId = 0;
		if (startParameters.p1_id == SteamClient.SteamId.Value)
		{
			localPlayerId = 1;
		}
		else if (startParameters.p2_id == SteamClient.SteamId.Value)
		{
			localPlayerId = 2;
		}
		else if (startParameters.p3_id == SteamClient.SteamId.Value)
		{
			localPlayerId = 3;
		}
		else if (startParameters.p4_id == SteamClient.SteamId.Value)
		{
			localPlayerId = 4;
		}
		List<Client> list = new List<Client>();
		for (int i = 0; i < connectedPlayers.Count; i++)
		{
			if (connectedPlayers[i].id.Value == startParameters.p1_id && startParameters.nrOfPlayers >= 1)
			{
				list.Add(new Client(1, connectedPlayers[i]));
			}
			else if (connectedPlayers[i].id.Value == startParameters.p2_id && startParameters.nrOfPlayers >= 2)
			{
				list.Add(new Client(2, connectedPlayers[i]));
			}
			else if (connectedPlayers[i].id.Value == startParameters.p3_id && startParameters.nrOfPlayers >= 3)
			{
				list.Add(new Client(3, connectedPlayers[i]));
			}
			else if (connectedPlayers[i].id.Value == startParameters.p4_id && startParameters.nrOfPlayers >= 4)
			{
				list.Add(new Client(4, connectedPlayers[i]));
			}
		}
		networkClient.Init(list, localPlayerId, startParameters.currentLevel, startFrameBuffer, checkForDesyncs);
		networkClientHandle = networkClient;
	}

	public void EncodeCurrentStartParameters_forReplay(ref byte[] result, StartRequestPacket p, bool isLocalGame = false)
	{
		if (!Host.recordReplay)
		{
			return;
		}
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		bool flag4 = false;
		bool flag5 = false;
		bool flag6 = false;
		bool flag7 = false;
		bool flag8 = false;
		if (isLocalGame)
		{
			List<Player> list = PlayerHandler.Get().PlayerList();
			for (int i = 0; i < list.Count; i++)
			{
				if (1 == list[i].Id)
				{
					flag = list[i].UsesKeyboardAndMouse;
					flag5 = true;
				}
				else if (2 == list[i].Id)
				{
					flag2 = list[i].UsesKeyboardAndMouse;
					flag6 = true;
				}
				else if (3 == list[i].Id)
				{
					flag3 = list[i].UsesKeyboardAndMouse;
					flag7 = true;
				}
				else if (4 == list[i].Id)
				{
					flag4 = list[i].UsesKeyboardAndMouse;
					flag8 = true;
				}
			}
		}
		else
		{
			for (int j = 0; j < connectedPlayers.Count; j++)
			{
				if (p.p1_id == (ulong)connectedPlayers[j].id)
				{
					flag = connectedPlayers[j].lobby_usesKeyboardAndMouse;
					flag5 = true;
				}
				else if (p.p2_id == (ulong)connectedPlayers[j].id)
				{
					flag2 = connectedPlayers[j].lobby_usesKeyboardAndMouse;
					flag6 = true;
				}
				else if (p.p3_id == (ulong)connectedPlayers[j].id)
				{
					flag3 = connectedPlayers[j].lobby_usesKeyboardAndMouse;
					flag7 = true;
				}
				else if (p.p4_id == (ulong)connectedPlayers[j].id)
				{
					flag4 = connectedPlayers[j].lobby_usesKeyboardAndMouse;
					flag8 = true;
				}
			}
			if (p.p1_id == (ulong)SteamClient.SteamId)
			{
				flag = CharacterSelectHandler_online.localPlayerInit.usesKeyboardMouse;
				flag5 = true;
			}
			else if (p.p2_id == (ulong)SteamClient.SteamId)
			{
				flag2 = CharacterSelectHandler_online.localPlayerInit.usesKeyboardMouse;
				flag6 = true;
			}
			else if (p.p3_id == (ulong)SteamClient.SteamId)
			{
				flag3 = CharacterSelectHandler_online.localPlayerInit.usesKeyboardMouse;
				flag7 = true;
			}
			else if (p.p4_id == (ulong)SteamClient.SteamId)
			{
				flag4 = CharacterSelectHandler_online.localPlayerInit.usesKeyboardMouse;
				flag8 = true;
			}
		}
		p.p1_id = (ulong)(int)(flag ? 1u : 0u);
		p.p2_id = (ulong)(int)(flag2 ? 1u : 0u);
		p.p3_id = (ulong)(int)(flag3 ? 1u : 0u);
		p.p4_id = (ulong)(int)(flag4 ? 1u : 0u);
		if (!flag5)
		{
			p.p1_ability1 = 0;
		}
		if (!flag6)
		{
			p.p2_ability2 = 0;
		}
		if (!flag7)
		{
			p.p3_ability2 = 0;
		}
		if (!flag8)
		{
			p.p4_ability2 = 0;
		}
		NetworkTools.EncodeStartRequest(ref replay_startRequestBuffer, p);
		networkClient.EncodedStartRequest = new byte[replay_startRequestBuffer.Length];
		replay_startRequestBuffer.CopyTo(result, 0);
	}

	public void StartHostedGame()
	{
