		InitNetworkClient();
	}

	public void HostNextLevel(Player hostPlayer, NamedSpriteList abilityIcons)
	{
		GameSession.CurrentLevel();
		startParameters.frameBufferSize = (byte)Host.CurrentDelayBufferSize;
		startParameters.seed = (uint)Environment.TickCount;
		startParameters.nrOfPlayers = (byte)(connectedPlayers.Count + 1);
		startParameters.currentLevel = GameSession.CurrentLevel();
		List<Player> list = PlayerHandler.Get().PlayerList();
		for (int i = 0; i < list.Count; i++)
		{
			if (hostPlayer.Id == list[i].Id)
			{
				switch (list[i].Id)
				{
				case 1:
					startParameters.p1_ability1 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[0].name);
					if (Settings.Get().NumberOfAbilities > 1)
					{
						startParameters.p1_ability2 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[1].name);
					}
					if (Settings.Get().NumberOfAbilities > 2)
					{
						startParameters.p1_ability3 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[2].name);
					}
					break;
				case 2:
					startParameters.p2_ability1 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[0].name);
					if (Settings.Get().NumberOfAbilities > 1)
					{
						startParameters.p2_ability2 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[1].name);
					}
					if (Settings.Get().NumberOfAbilities > 2)
					{
						startParameters.p2_ability3 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[2].name);
					}
					break;
				case 3:
					startParameters.p3_ability1 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[0].name);
					if (Settings.Get().NumberOfAbilities > 1)
					{
						startParameters.p3_ability2 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[1].name);
					}
					if (Settings.Get().NumberOfAbilities > 2)
					{
						startParameters.p3_ability3 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[2].name);
					}
					break;
				case 4:
					startParameters.p4_ability1 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[0].name);
					if (Settings.Get().NumberOfAbilities > 1)
					{
						startParameters.p4_ability2 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[1].name);
					}
					if (Settings.Get().NumberOfAbilities > 2)
					{
						startParameters.p4_ability3 = (byte)abilityIcons.IndexOf(hostPlayer.Abilities[2].name);
					}
					break;
				}
				continue;
			}
			for (int j = 0; j < connectedPlayers.Count; j++)
			{
				if ((ulong)list[i].steamId == (ulong)connectedPlayers[j].id)
				{
					switch (list[i].Id)
					{
					case 1:
						startParameters.p1_ability1 = connectedPlayers[j].lobby_ability1;
						startParameters.p1_ability2 = connectedPlayers[j].lobby_ability2;
						startParameters.p1_ability3 = connectedPlayers[j].lobby_ability3;
						break;
					case 2:
						startParameters.p2_ability1 = connectedPlayers[j].lobby_ability1;
						startParameters.p2_ability2 = connectedPlayers[j].lobby_ability2;
						startParameters.p2_ability3 = connectedPlayers[j].lobby_ability3;
						break;
					case 3:
						startParameters.p3_ability1 = connectedPlayers[j].lobby_ability1;
						startParameters.p3_ability2 = connectedPlayers[j].lobby_ability2;
						startParameters.p3_ability3 = connectedPlayers[j].lobby_ability3;
						break;
					case 4:
						startParameters.p4_ability1 = connectedPlayers[j].lobby_ability1;
						startParameters.p4_ability2 = connectedPlayers[j].lobby_ability2;
						startParameters.p4_ability3 = connectedPlayers[j].lobby_ability3;
						break;
					}
					break;
				}
			}
		}
		NetworkTools.EncodeStartRequest(ref startRequestBuffer, startParameters);
		instance.EncodeCurrentStartParameters_forReplay(ref instance.networkClient.EncodedStartRequest, startParameters);
		for (int k = 0; k < connectedPlayers.Count; k++)
		{
			connectedPlayers[k].Connection.SendMessage(startRequestBuffer);
		}
	}

	public void HostGame(PlayerInit hostPlayer)
	{
		currentLobby.SetData("LFM", "0");
		currentLobby.SetFriendsOnly();
		currentLobby.SetJoinable(b: false);
		startParameters = default(StartRequestPacket);
		startParameters.seqNum = nextStartGameSeq++;
		startParameters.nrOfPlayers = (byte)(connectedPlayers.Count + 1);
		startParameters.nrOfAbilites = (byte)Settings.Get().NumberOfAbilities;
		startParameters.currentLevel = GameSession.CurrentLevel();
		startParameters.seed = (uint)Environment.TickCount;
		startParameters.p1_id = SteamClient.SteamId;
		startParameters.p1_team = (byte)hostPlayer.team;
		startParameters.p1_color = (byte)hostPlayer.color;
		startParameters.p1_ability1 = (byte)hostPlayer.ability0;
		startParameters.p1_ability2 = (byte)hostPlayer.ability1;
		startParameters.p1_ability3 = (byte)hostPlayer.ability2;
		if (connectedPlayers.Count > 0)
		{
			startParameters.p2_id = connectedPlayers[0].id;
			startParameters.p2_team = connectedPlayers[0].lobby_team;
			startParameters.p2_color = (byte)connectedPlayers[0].lobby_color;
			startParameters.p2_ability1 = connectedPlayers[0].lobby_ability1;
			startParameters.p2_ability2 = connectedPlayers[0].lobby_ability2;
			startParameters.p2_ability3 = connectedPlayers[0].lobby_ability3;
		}
		if (connectedPlayers.Count > 1)
		{
			startParameters.p3_id = connectedPlayers[1].id;
			startParameters.p3_team = connectedPlayers[1].lobby_team;
			startParameters.p3_color = (byte)connectedPlayers[1].lobby_color;
			startParameters.p3_ability1 = connectedPlayers[1].lobby_ability1;
			startParameters.p3_ability2 = connectedPlayers[1].lobby_ability2;
			startParameters.p3_ability3 = connectedPlayers[1].lobby_ability3;
		}
		if (connectedPlayers.Count > 2)
		{
			startParameters.p4_id = connectedPlayers[2].id;
			startParameters.p4_team = connectedPlayers[2].lobby_team;
			startParameters.p4_color = (byte)connectedPlayers[2].lobby_color;
			startParameters.p4_ability1 = connectedPlayers[2].lobby_ability1;
			startParameters.p4_ability2 = connectedPlayers[2].lobby_ability2;
			startParameters.p4_ability3 = connectedPlayers[2].lobby_ability3;
		}
		byte b = (byte)(instance.dlc.HasDLC() ? 1u : 0u);
		for (int i = 0; i < connectedPlayers.Count; i++)
		{
			if (connectedPlayers[i].ownsFullGame)
			{
				b = (byte)(b | (1 << i + 1));
			}
		}
		startParameters.isDemoMask = b;
		NetworkTools.EncodeStartRequest(ref startRequestBuffer, startParameters);
		instance.EncodeCurrentStartParameters_forReplay(ref instance.networkClient.EncodedStartRequest, startParameters);
		for (int j = 0; j < connectedPlayers.Count; j++)
		{
			connectedPlayers[j].Connection.SendMessage(startRequestBuffer);
		}
	}

