	public void BroadcastLocalPlayerIsLobbyReady()
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		Player player = null;
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].IsLocalPlayer)
			{
				player = list[i];
			}
		}
		if (player != null)
		{
			int ability = 0;
			int ability2 = 0;
			int ability3 = 0;
			if (player.Abilities.Count > 0)
			{
				ability = abilityIcons.IndexOf(player.Abilities[0].name);
			}
			if (player.Abilities.Count > 1)
			{
				ability2 = abilityIcons.IndexOf(player.Abilities[1].name);
			}
			if (player.Abilities.Count > 2)
			{
				ability3 = abilityIcons.IndexOf(player.Abilities[2].name);
			}
			BroadcastAbilityChoiceUpdate(ability, ability2, ability3);
		}
	}

