	public void BroadcastLobbyInitPacket()
	{
		if (connectedPlayers != null && connectedPlayers.Count != 0)
		{
			NetworkTools.EncodeLobbyInit(ref lobbyInitBuffer, new LobbyInit
			{
				nrOfAbilites = (byte)Settings.Get().NumberOfAbilities,
				extraByte = 0
			});
			for (int i = 0; i < connectedPlayers.Count; i++)
			{
				connectedPlayers[i].Connection.SendMessage(lobbyInitBuffer);
				connectedPlayers[i].haveSentInit_hostonly = true;
			}
		}
	}

	public bool SendLobbyReadyRequest(LobbyReadyPacket packet)
	{
		NetworkTools.EncodeLobbyReadyPacket(ref lobbyReadyBuffer, packet.color, packet.team, packet.ability1, packet.ability2, packet.ability3, packet.usesKeyboardAndMouse, packet.ownsFullGame != 0, packet.steamId);
		SteamConnection steamConnection = null;
		for (int i = 0; i < connectedPlayers.Count; i++)
		{
			if (currentLobby.IsOwnedBy(connectedPlayers[i].id))
			{
				steamConnection = connectedPlayers[i];
				break;
			}
		}
		if (steamConnection != null)
		{
			steamConnection.Connection.SendMessage(lobbyReadyBuffer);
			return true;
		}
		return false;
	}

	private void OnLevelWasLoaded(int level)
	{
		networkClient = UnityEngine.Object.FindObjectOfType<Host>();
	}

	private void Update()
	{
		if (socket != null)
		{
			socket.Receive(2048);
		}
		SteamClient.RunCallbacks();
		if (connectedPlayers.Count == 0 && GameLobby.isOnlineGame && GameLobby.nrOfAbilities != Settings.Get().TrueNumberOfAbilities)
		{
			GameLobby.nrOfAbilities = Settings.Get().TrueNumberOfAbilities;
		}
		if (LocalPlayerIsLobbyOwner)
		{
			for (int i = 0; i < connectedPlayers.Count; i++)
			{
				if (connectedPlayers[i].Connected && !connectedPlayers[i].haveSentInit_hostonly)
				{
					NetworkTools.EncodeLobbyInit(ref lobbyInitBuffer, new LobbyInit
					{
						nrOfAbilites = (byte)Settings.Get().NumberOfAbilities,
						extraByte = 0
					});
					connectedPlayers[i].Connection.SendMessage(lobbyInitBuffer);
					connectedPlayers[i].haveSentInit_hostonly = true;
					break;
				}
			}
		}
		for (int j = 0; j < recentlyJoinedLobbies.Count; j++)
		{
			if (!(recentlyJoinedLobbies[j].timeStamp < 0f))
			{
				continue;
			}
			bool flag = false;
			foreach (Friend member in currentLobby.Members)
			{
				if (member.Id.AccountId == (uint)recentlyJoinedLobbies[j].accId)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				LobbyOwnerRecord value = recentlyJoinedLobbies[j];
				value.timeStamp = Time.realtimeSinceStartup;
				recentlyJoinedLobbies[j] = value;
			}
		}
		_ = currentlyInMatchmaking;
		if (currentlyLookingForPlayers && !currentlyInMatchmaking)
		{
			currentlyInMatchmaking = true;
			timeSinceMatchmakingStarted = 0.0;
			if (currentLobby.Owner.IsMe && !CharacterSelectHandler_online.hasMods)
			{
				StartMatchmaking(widenSearch: false);
				UnityEngine.Debug.Log("doing a narrow search..");
			}
		}
		else if (!currentlyLookingForPlayers && currentlyInMatchmaking)
		{
			if (currentLobby.Owner.IsMe)
			{
				StopMatchmaking();
			}
			currentlyInMatchmaking = false;
		}
		if (currentlyInMatchmaking)
		{
			timeSinceMatchmakingStarted += Time.deltaTime;
			if (timeSinceMatchmakingStarted > 30.0 && currentLobby.Owner.IsMe && !CharacterSelectHandler_online.hasMods)
			{
				StartMatchmaking(widenSearch: true);
				UnityEngine.Debug.Log("doing an expanded search..");
				timeSinceMatchmakingStarted = 0.0;
			}
		}
	}

	private void StopMatchmaking()
	{
		MonoBehaviour.print("Stopped Matchmaking..");
		currentLobby.SetFriendsOnly();
		if (GameLobby.isOnlineGame && !GameSession.inMenus)
		{
			currentLobby.SetJoinable(b: false);
		}
		else
		{
			currentLobby.SetJoinable(b: true);
		}
	}

	public void UpdateRecentLobbiesList()
	{
		float num = 59f;
		for (int num2 = recentlyJoinedLobbies.Count - 1; num2 >= 0; num2--)
		{
			if (recentlyJoinedLobbies[num2].timeStamp > 0f && Time.realtimeSinceStartup - recentlyJoinedLobbies[num2].timeStamp > num)
			{
				recentlyJoinedLobbies.RemoveAt(num2);
			}
		}
	}

	public void RegisterAllInLobbyAsRecentlyPlayed(Lobby lobby)
	{
		foreach (Friend member in lobby.Members)
		{
			if (!member.IsMe)
			{
				SteamId id = member.Id;
				RegisterAsRecentlyPlayedWith(id.AccountId);
			}
		}
	}

	public void RegisterAsRecentlyPlayedWith(uint u_accId)
	{
		for (int i = 0; i < recentlyJoinedLobbies.Count; i++)
		{
			if (recentlyJoinedLobbies[i].accId == (int)u_accId)
			{
				LobbyOwnerRecord value = recentlyJoinedLobbies[i];
				value.timeStamp = -1f;
				recentlyJoinedLobbies[i] = value;
				return;
			}
		}
		recentlyJoinedLobbies.Add(new LobbyOwnerRecord
		{
			accId = (int)u_accId,
			timeStamp = -1f
		});
	}

	public bool JoinedThisLobbyRecently(int accId)
	{
		for (int i = 0; i < recentlyJoinedLobbies.Count; i++)
		{
			if (recentlyJoinedLobbies[i].accId == accId)
			{
				return true;
			}
		}
		return false;
	}

	private async Task<bool> FindAndJoinLobby(LobbyQuery query, bool widenSearch)
	{
		if (!widenSearch)
		{
			query = query.FilterDistanceClose();
		}
		Lobby[] lobbies = await query.RequestAsync();
		if (isJoiningAlobbyAtm)
		{
			return false;
		}
		if (lobbies != null)
		{
			for (int i = 0; i < lobbies.Length; i++)
			{
				if ((ulong)currentLobby.Id != (ulong)lobbies[i].Id)
				{
					isJoiningAlobbyAtm = true;
					RoomEnter roomEnter = await lobbies[i].Join();
					if (roomEnter == RoomEnter.Success)
					{
						currentLobby.Leave();
						currentLobby = lobbies[i];
						CharacterSelectHandler_online.SetTeamColor(currentLobby.MemberCount - 1);
						isJoiningAlobbyAtm = false;
						return true;
					}
					MonoBehaviour.print("could not join lobby : " + roomEnter);
					MonoBehaviour.print("trying the next one..");
					isJoiningAlobbyAtm = false;
				}
			}
		}
		else if (widenSearch)
		{
			MonoBehaviour.print("no far lobbies available");
		}
		else
		{
			MonoBehaviour.print("no close lobbies available");
		}
		return false;
	}

	private async Task<bool> FindAndMergeToYourLobby(LobbyQuery query, bool widenSearch)
	{
		if (!widenSearch)
		{
			query = query.FilterDistanceClose();
		}
		Lobby[] lobbies = await query.RequestAsync();
		if (lobbies != null)
		{
			for (int i = 0; i < lobbies.Length; i++)
			{
				if ((ulong)currentLobby.Id != (ulong)lobbies[i].Id)
				{
					RoomEnter roomEnter = await lobbies[i].Join();
					if (roomEnter == RoomEnter.Success)
					{
						lobbies[i].SendChatString("joinLobby:" + currentLobby.Id.ToString());
						lobbies[i].Leave();
						return true;
					}
					MonoBehaviour.print("could not join lobby : " + roomEnter);
					MonoBehaviour.print("trying the next one..");
				}
			}
		}
		else if (widenSearch)
		{
			MonoBehaviour.print("no far lobbies available");
		}
		else
		{
			MonoBehaviour.print("no close lobbies available");
		}
		return false;
	}

	private void pauseMatchmaking()
	{
		timeSinceMatchmakingStarted = 22.0;
	}

	private async void StartMatchmaking(bool widenSearch)
	{
		MonoBehaviour.print("Started Matchmaking..");
		currentLobby.SetFriendsOnly();
		currentLobby.SetData("accId", ((int)SteamClient.SteamId.AccountId).ToString());
		UpdateRecentLobbiesList();
		bool multiLobby = currentLobby.MemberCount > 1;
		try
		{
			LobbyQuery farQuery = SteamMatchmaking.LobbyList.WithMaxResults(30).WithKeyValue("version", Constants.version).WithSlotsAvailable(currentLobby.MemberCount);
			for (int i = 0; i < recentlyJoinedLobbies.Count && i < 30; i++)
			{
				farQuery = farQuery.WithNotEqual("accId", recentlyJoinedLobbies[i].accId);
			}
			LobbyQuery query = farQuery.WithNotEqual("oldLobby", 1);
			bool flag = ((!multiLobby) ? (await FindAndJoinLobby(query, widenSearch: false)) : (await FindAndMergeToYourLobby(query, widenSearch: false)));
			if (flag && multiLobby)
			{
				pauseMatchmaking();
				return;
			}
			if (flag)
			{
				return;
			}
			if (widenSearch)
			{
				flag = ((!multiLobby) ? (await FindAndJoinLobby(farQuery, widenSearch: true)) : (await FindAndMergeToYourLobby(farQuery, widenSearch: true)));
				if (flag && multiLobby)
				{
					pauseMatchmaking();
					return;
				}
				if (flag)
				{
					return;
				}
			}
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.Log(ex.ToString());
			UnityEngine.Debug.Log("Error fetching multiplayer lobbies");
			currentLobby.SetData("LFM", "0");
			currentlyInMatchmaking = false;
			currentlyLookingForPlayers = false;
			timeSinceMatchmakingStarted = 0.0;
			return;
		}
		UnityEngine.Debug.Log("setting own lobby public");
		currentLobby.SetPublic();
		if (widenSearch)
		{
			currentLobby.SetData("oldLobby", "1");
		}
		else
		{
			currentLobby.SetData("oldLobby", "0");
		}
	}

	public static void UpdateLobbyPublicFlag(Lobby lobby)
	{
		CharacterSelectHandler_online.CheckForMods();
		if (lobby.GetData("LFM") == "1")
		{
			if (CharacterSelectHandler_online.hasMods)
			{
				instance.LeaveLobby();
				ErrorHandlingTextDisconnect.SetMainMenuLogMessage("That wasn't a bug. Please disable your mods before using matchmaking");
			}
			currentlyLookingForPlayers = true;
		}
		else
		{
			currentlyLookingForPlayers = false;
		}
	}

	private static void ChangePlayerAbilites(Player player, byte ability1, byte ability2, byte ability3, int nrOfAbilities, NamedSpriteList abilityIcons)
	{
		player.Abilities.Clear();
		player.AbilityIcons.Clear();
		if (nrOfAbilities > 0)
		{
			player.Abilities.Add(abilityIcons.sprites[ability1].associatedGameObject);
			player.AbilityIcons.Add(abilityIcons.sprites[ability1].sprite);
		}
		if (nrOfAbilities > 1)
		{
			player.Abilities.Add(abilityIcons.sprites[ability2].associatedGameObject);
			player.AbilityIcons.Add(abilityIcons.sprites[ability2].sprite);
		}
		if (nrOfAbilities > 2)
		{
			player.Abilities.Add(abilityIcons.sprites[ability3].associatedGameObject);
			player.AbilityIcons.Add(abilityIcons.sprites[ability3].sprite);
		}
	}

	public static void ForceBacktoAbilitySelect_instant()
	{
		if (!GameSession.inMenus)
		{
			networkClientHandle.ClearClients();
			networkClientHandle.DeInit();
			if (!GameSessionHandler.HasGameEnded())
			{
				instance?.networkClient?.SaveReplay();
			}
			Updater.PreLevelLoad();
			CharacterStatsList.ForceBackToAbilitySelectImmediately();
		}
	}

	public static void ForceBacktoAbilitySelect()
	{
		if (!GameSession.inMenus)
		{
			networkClientHandle.DeInit();
			if (!GameSessionHandler.HasGameEnded())
			{
				instance?.networkClient?.SaveReplay();
			}
			Updater.PreLevelLoad();
			if (!GameSessionHandler.GameIsPaused)
			{
				CharacterStatsList.ForceBackToAbilitySelectTransitionFade();
			}
			else
			{
				CharacterStatsList.ForceBackToAbilitySelect();
			}
		}
	}

	public static void ForceLoadNextLevel()
	{
		networkClientHandle.DeInit();
		StartRequestPacket startRequestPacket = startParameters;
		List<Player> list = PlayerHandler.Get().PlayerList();
		if (startRequestPacket.nrOfPlayers <= 1)
		{
			GameSessionHandler.LeaveGame(abandonLobbyEntirely: true);
			return;
		}
		for (int num = list.Count - 1; num >= 0; num--)
		{
			if (!list[num].IsLocalPlayer)
			{
				bool flag = false;
				for (int i = 0; i < instance.connectedPlayers.Count; i++)
				{
					if ((ulong)instance.connectedPlayers[i].id == (ulong)list[num].steamId)
					{
						flag = true;
					}
				}
				if (!flag)
				{
					list.RemoveAt(num);
					UnityEngine.Debug.Log("dropping player because they were disconnected");
				}
			}
		}
		for (int j = 0; j < list.Count; j++)
		{
			switch (list[j].Id)
			{
			case 1:
				ChangePlayerAbilites(list[j], startRequestPacket.p1_ability1, startRequestPacket.p1_ability2, startRequestPacket.p1_ability3, startRequestPacket.nrOfAbilites, instance.abilityIcons);
				break;
			case 2:
				ChangePlayerAbilites(list[j], startRequestPacket.p2_ability1, startRequestPacket.p2_ability2, startRequestPacket.p2_ability3, startRequestPacket.nrOfAbilites, instance.abilityIcons);
				break;
			case 3:
				ChangePlayerAbilites(list[j], startRequestPacket.p3_ability1, startRequestPacket.p3_ability2, startRequestPacket.p3_ability3, startRequestPacket.nrOfAbilites, instance.abilityIcons);
				break;
			case 4:
				ChangePlayerAbilites(list[j], startRequestPacket.p4_ability1, startRequestPacket.p4_ability2, startRequestPacket.p4_ability3, startRequestPacket.nrOfAbilites, instance.abilityIcons);
				break;
			}
		}
		GameSession.SetCurrentLevel(startRequestPacket.currentLevel);
		if (!GameSessionHandler.GameIsPaused)
		{
			CharacterStatsList.ForceNextLevelImmediately();
		}
		else
		{
			CharacterStatsList.ForceNextLevelLoad();
		}
	}
}
[Serializable]
public struct TeamColor
{
	public int team;

	public UnityEngine.Color fill;

	public UnityEngine.Color border;

	public UnityEngine.Color saturated;
}
public class TeamSelector : SelectableMonoBehaviour
{
	public CharacterSelectBox csb;

	public TeamColors teams;

	public UnityEngine.UI.Image[] saturatedColorImages;

	public UnityEngine.UI.Image[] fillColorImages;

	public UnityEngine.UI.Image[] borderColorImages;

	public Button[] borderColorButtons;

	public TextMeshProUGUI[] textsToColor;

	public ReadyButton readyButton;

	public KeyBindButton keybindButton;

	public int selectedIndex;

	public float fadeDuration = 1f;

	private float timeSinceSelect = 10000f;

	private AnimateTransformUI animateOnTeamSwap;

	private bool isSelected = true;

	private void Awake()
	{
		animateOnTeamSwap = GetComponent<AnimateTransformUI>();
		text.font = LocalizedText.localizationTable.GetFont(Settings.Get().Language, useFontWithStroke: false);
	}

	private void UpdateColors(float deltaTime)
	{
		timeSinceSelect += deltaTime;
		float t = timeSinceSelect / fadeDuration;
		UnityEngine.Color color = UnityEngine.Color.Lerp(borderColorImages[0].color, teams.teamColors[selectedIndex].border, t);
		UnityEngine.Color color2 = UnityEngine.Color.Lerp(fillColorImages[0].color, teams.teamColors[selectedIndex].fill, t);
		for (int i = 0; i < saturatedColorImages.Length; i++)
		{
			saturatedColorImages[i].color = teams.teamColors[selectedIndex].saturated;
		}
		for (int j = 0; j < fillColorImages.Length; j++)
		{
			fillColorImages[j].color = color2;
		}
		for (int k = 0; k < borderColorImages.Length; k++)
		{
			borderColorImages[k].color = color;
		}
		for (int l = 0; l < borderColorButtons.Length; l++)
		{
			ColorBlock colors = borderColorButtons[l].colors;
			colors.normalColor = color;
			borderColorButtons[l].colors = colors;
		}
		for (int m = 0; m < textsToColor.Length; m++)
		{
			textsToColor[m].color = color;
		}
		readyButton.SetBaseColor(color2);
		keybindButton.SetBaseColor(color2);
	}

	private void OnDisable()
	{
		UpdateColors(100000f);
	}

	public override void SetToPlayerChoices(Player player, int index)
	{
		Select(player.Team);
	}

	public override void Select(int index)
	{
		if (index < 0)
		{
			index = selectedIndex;
		}
		timeSinceSelect = 0f;
		selectedIndex = index;
		text.text = LocalizedText.localizationTable.GetText("team", Settings.Get().Language);
		csb.playerInit.team = index;
	}

	public override void UpdatePlayerInit(ref PlayerInit init, int index)
	{
		init.team = selectedIndex;
	}

	public override void Move(bool moveRight)
	{
		int num = (moveRight ? 1 : (-1));
		int index = (selectedIndex + num + teams.teamColors.Length) % teams.teamColors.Length;
		Select(index);
		AudioManager.Get().Play("navigateMenu2");
		animateOnTeamSwap.Animate();
	}

	public override void Activate()
	{
		isSelected = true;
	}

	public override void DeActivate()
	{
		isSelected = false;
	}

	private void Update()
	{
		if (!fillColorImages[0].color.Equals(teams.teamColors[selectedIndex].fill))
		{
			UpdateColors(Time.deltaTime);
		}
		if (isSelected)
		{
			Keyboard current = Keyboard.current;
			Gamepad currentGamePad = csb.currentGamePad;
			if ((csb.UseskeyboardMouse && (current.dKey.wasPressedThisFrame || current.rightArrowKey.wasPressedThisFrame)) || (currentGamePad != null && (currentGamePad.leftStick.right.wasPressedThisFrame || currentGamePad.dpad.right.wasPressedThisFrame)))
			{
				Move(moveRight: true);
			}
			else if ((csb.UseskeyboardMouse && (current.aKey.wasPressedThisFrame || current.leftArrowKey.wasPressedThisFrame)) || (currentGamePad != null && (currentGamePad.leftStick.left.wasPressedThisFrame || currentGamePad.dpad.left.wasPressedThisFrame)))
			{
				Move(moveRight: false);
			}
		}
	}
}
