public class UnstableProjectile : MonoUpdatable
{
	public Fix vibrationAmplitude = Fix.One;

	public int vibrationFreq = 1;

	private BoplBody body;

	private Vec2 currentOffset;

	private int frame;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		body = GetComponent<BoplBody>();
	}

	public override void Init()
	{
		currentOffset = Vec2.zero;
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		frame++;
		if (frame % vibrationFreq == 0)
		{
			body.position -= currentOffset;
			Vec2 vec = vibrationAmplitude * Updater.RandomUnitVector();
			body.position += vec;
			currentOffset = vec;
		}
	}
}
