public class VectorFieldPlatform : MonoUpdatable
{
	private AnimateVelocity animVel;

	private BoplBody body;

	private StickyRoundedRectangle srr;

	public Fix DelaySeconds = Fix.Zero;

	public Fix orbitSpeed = (Fix)100L;

	public Fix expandSpeed = (Fix)100L;

	public Vec2 centerPoint;

	public Fix normalSpeedFriction = Fix.One;

	private bool hasStarted;

	public Fix DeadZoneDist = (Fix)1f;

	public Fix OrbitAccelerationMulitplier = Fix.One;

	public Fix targetRadius = (Fix)5f;

	public Fix ovalness01 = Fix.One;

	public int gizmoOrbitIterations = 10;

	public override void Init()
	{
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animVel = GetComponent<AnimateVelocity>();
		body = GetComponent<BoplBody>();
		srr = GetComponent<StickyRoundedRectangle>();
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (!GameTime.IsTimeStopped() && !(Updater.SimTimeSinceLevelLoaded < DelaySeconds) && !GameSessionHandler.SuddenDeathInProgress)
		{
			if (!hasStarted)
			{
				hasStarted = true;
				Vec2.NormalizedSafe(centerPoint - body.position);
			}
			body.position += VectorField(body.position, body.velocity, out var newVel);
			body.velocity = newVel;
			animVel.HomePosition = body.position;
		}
	}

	private Vec2 VectorField(Vec2 p1, Vec2 vel, out Vec2 newVel)
	{
		Fix fix = GameTime.FixedTimeStep * GameTime.PlayerTimeScale;
		Vec2 vec = p1 - centerPoint;
		Vec2 vec2 = Vec2.NormalizedSafe(vec);
		Vec2 vec3 = Vec2.MulByNegI(vec2);
		Fix fix2 = Vec2.Dot(vec3, vel);
		Fix fix3 = Vec2.Dot(vec2, vel);
		Vec2 u = vec2 * targetRadius + centerPoint - p1;
		Fix fix4 = Vec2.Dot(vec2, u);
		fix3 += fix4 * fix * expandSpeed;
		if (Vec2.SqrMagnitude(vec) < DeadZoneDist)
		{
			newVel = vec2 * fix3 + vec3 * fix2;
			return Vec2.zero;
		}
		fix2 = Fix.Lerp(fix2, orbitSpeed, fix * OrbitAccelerationMulitplier);
		Fix zero = Fix.Zero;
		if (Fix.Sign(fix2) == Fix.Sign(orbitSpeed))
		{
			if (Fix.Abs(fix2) >= Fix.Abs(orbitSpeed))
			{
				zero = fix2 - orbitSpeed;
				fix2 -= zero;
			}
			else
			{
				zero = Fix.Zero;
			}
		}
		else
		{
			zero = fix2;
			fix2 = Fix.Zero;
		}
		Vec2 vec4 = vec3 * fix2 * fix;
		Vec2 vec5 = Vec2.NormalizedSafe(p1 + vec4 - centerPoint);
		Vec2 vec6 = Vec2.MulByNegI(vec5);
		Fix fix5 = Vec2.Magnitude(vec);
		Vec2 vec7 = vec5 * fix5;
		newVel = vec6 * fix2;
		Vec2 result = vec7 - newVel * GameTime.FixedTimeStep - vec;
		newVel += vec5 * fix3 * normalSpeedFriction + zero * vec3;
		return result;
	}

	private Vec2 GetAnimVelAccel(Vec2 prevPos, Vec2 pos, Vec2 vel)
	{
		return -animVel.mu * vel;
	}

	private void OnDrawGizmosSelected()
	{
		if (animVel == null)
		{
			animVel = GetComponent<AnimateVelocity>();
		}
		if (body == null)
		{
			body = GetComponent<BoplBody>();
		}
		Gizmos.DrawWireSphere((Vector3)centerPoint, Mathf.Sqrt((float)DeadZoneDist));
		Gizmos.DrawWireSphere((Vector3)centerPoint, (float)targetRadius);
		Vec2 vec = (Vec2)base.transform.position;
		Vec2.NormalizedSafe(vec - centerPoint);
		Vec2 vec2 = body.StartVelocity;
		Fix airFriction = body.airFriction01;
		Gizmos.DrawLine((Vector3)vec, (Vector3)(vec + vec2));
		Vec2 vec3 = vec;
		for (int i = 0; i < gizmoOrbitIterations; i++)
		{
			vec3 = vec;
			Vec2 newVel;
			Vec2 vec4 = VectorField(vec, vec2, out newVel);
			Vec2 animVelAccel = GetAnimVelAccel(vec3, vec, vec2);
			vec += vec4;
			vec2 = newVel;
			vec2 += animVelAccel * GameTime.FixedTimeStep;
			vec2 *= airFriction;
			Vec2 vec5 = vec + vec2 * GameTime.FixedTimeStep;
			Gizmos.DrawLine((Vector3)vec3, (Vector3)vec5);
			vec = vec5;
		}
	}
}
public class WaterWaves : MonoBehaviour
{
	[SerializeField]
	private ParticleSystem WavePrefab;

	[SerializeField]
	private float waveOffsetY = -0.2f;

	[SerializeField]
	private float waveOffsetX = 0.2f;

	private ParticleSystem waveLeft;

	private ParticleSystem waveRight;

	private BoplBody body;

	private StickyRoundedRectangle rect;

	private Vector2 leftPos;

	private Vector2 rightPos;

	private BoxCollider2D col;

	private Vector2[] rectCorners = new Vector2[4];

	private int[] orderedIndices = new int[4] { 0, 1, 2, 3 };

	[SerializeField]
	private float DespawnOffset = 0.3f;

	private void Awake()
	{
		body = GetComponent<BoplBody>();
		rect = GetComponent<StickyRoundedRectangle>();
	}

	private void Start()
	{
		if (!Constants.isSpaceLevel)
		{
			waveRight = UnityEngine.Object.Instantiate(WavePrefab, rightPos, Quaternion.identity);
			waveLeft = UnityEngine.Object.Instantiate(WavePrefab, leftPos, Quaternion.identity);
			waveLeft.transform.localScale = new Vector3(waveLeft.transform.localScale.x * -1f, waveLeft.transform.localScale.y, waveLeft.transform.localScale.z);
		}
	}

	private void OnDestroy()
	{
		if (waveRight != null)
		{
			UnityEngine.Object.Destroy(waveRight.gameObject);
		}
		if (waveLeft != null)
		{
			UnityEngine.Object.Destroy(waveLeft.gameObject);
		}
	}

	private void Update()
	{
		if (Constants.isSpaceLevel)
		{
			return;
		}
		if (!waveRight.isPaused && GameTime.IsTimeStopped())
		{
			waveRight.Pause();
		}
		else if (waveRight.isPaused && !GameTime.IsTimeStopped())
		{
			waveRight.Play();
		}
		if (!waveLeft.isPaused && GameTime.IsTimeStopped())
		{
			waveLeft.Pause();
		}
		else if (waveLeft.isPaused && !GameTime.IsTimeStopped())
		{
			waveLeft.Play();
		}
		float num = (float)Constants.WATER_HEIGHT;
		StickyRoundedRectangle.Corners boundingRect = rect.GetBoundingRect();
		rectCorners[0] = (Vector2)boundingRect.tl;
		rectCorners[1] = (Vector2)boundingRect.tr;
		rectCorners[2] = (Vector2)boundingRect.br;
		rectCorners[3] = (Vector2)boundingRect.bl;
		bubbleSort(orderedIndices, rectCorners);
		int i;
		for (i = 0; i < rectCorners.Length && !(rectCorners[orderedIndices[i]].y >= num); i++)
		{
		}
		if (i == 0 || i == 4)
		{
			waveLeft.Stop();
			waveRight.Stop();
			return;
		}
		Vector2 vector;
		Vector2 vector2;
		Vector2 vector3;
		Vector2 vector4;
		if (i == 2)
		{
			if (rectCorners[orderedIndices[0]].x >= rectCorners[orderedIndices[1]].x)
			{
				vector = rectCorners[orderedIndices[0]];
				vector2 = rectCorners[orderedIndices[1]];
				vector3 = rectCorners[orderedIndices[2]];
				vector4 = rectCorners[orderedIndices[3]];
			}
			else
			{
				vector = rectCorners[orderedIndices[1]];
				vector2 = rectCorners[orderedIndices[0]];
				vector3 = rectCorners[orderedIndices[3]];
				vector4 = rectCorners[orderedIndices[2]];
			}
			if (vector3.x < vector4.x)
			{
				Vector2 vector5 = vector3;
				vector3 = vector4;
				vector4 = vector5;
			}
		}
		else
		{
			vector = (vector2 = ((i == 3) ? rectCorners[orderedIndices[3]] : rectCorners[orderedIndices[0]]));
			if (rectCorners[orderedIndices[1]].x <= rectCorners[orderedIndices[2]].x)
			{
				vector4 = rectCorners[orderedIndices[1]];
				vector3 = rectCorners[orderedIndices[2]];
			}
			else
			{
				vector3 = rectCorners[orderedIndices[1]];
				vector4 = rectCorners[orderedIndices[2]];
			}
		}
		_ = leftPos.y;
		_ = rightPos.y;
		vector4 -= vector2;
		leftPos.x = vector4.x * (num - vector2.y) / vector4.y + vector2.x;
		leftPos.y = num;
		vector3 -= vector;
		rightPos.x = vector3.x * (num - vector.y) / vector3.y + vector.x;
		rightPos.y = num;
		leftPos = (Vector2)rect.GetClosestPoint((Vec2)leftPos);
		rightPos = (Vector2)rect.GetClosestPoint((Vec2)rightPos);
		leftPos.y = num;
		rightPos.y = num;
		rightPos.y += waveOffsetY;
		leftPos.y += waveOffsetY;
		rightPos.x += waveOffsetX;
		leftPos.x -= waveOffsetX;
		waveLeft.transform.position = leftPos;
		waveRight.transform.position = rightPos;
		if (rightPos.x - leftPos.x < DespawnOffset)
		{
			waveLeft.Stop();
			waveRight.Stop();
			return;
		}
		if (waveLeft.isStopped)
		{
			waveLeft.Play();
		}
		if (waveRight.isStopped)
		{
			waveRight.Play();
		}
	}

	private void bubbleSort(int[] a, Vector2[] b)
	{
		for (int i = 0; i <= a.Length - 2; i++)
		{
			for (int j = 0; j <= a.Length - 2; j++)
			{
				if (b[a[j]].y > b[a[j + 1]].y)
				{
					int num = a[j + 1];
					a[j + 1] = a[j];
					a[j] = num;
				}
			}
		}
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawSphere(leftPos, 0.4f);
		Gizmos.DrawSphere(rightPos, 0.4f);
	}
}
