public class AnimateVelocity : MonoUpdatable
{
	private Vec2 homePosition;

	public bool HomeIsMovable = true;

	public bool interpolateRotationHome = true;

	private BoplBody body;

	private bool initialized;

	private Fix SuddenDeathTimeStamp;

	private bool inRotationMode;

	private Fix spinTime = (Fix)100000L;

	private AnimationCurveFixed spinCurve;

	public bool inSuddenDeath;

	public Fix homeRotation;

	public Fix rotationSpeed = (Fix)10f;

	public Fix rotationMu = (Fix)(1f / 15f);

	public Fix speed = (Fix)10L;

	public Fix mu = (Fix)3f;

	public AnimationCurveFixed suddenDeathYSpeed;

	public Fix suddenDeathSpeed = (Fix)1f;

	public Fix MaxRandomSuddenDeathDelay = (Fix)1f;

	public Fix SuddenDeathAcceleration = (Fix)0.1f;

	private Fix randomSuddenDeathDelay = Fix.Zero;

	private Fix rotationModeSpeed = (Fix)360L;

	public Fix rotationResistence = (Fix)1L;

	public bool isBeingControlled;

	private bool actAsFloatingPlatformThisFrame;

	public Vec2 HomePosition
	{
		get
		{
			return homePosition;
		}
		set
		{
			if (HomeIsMovable)
			{
				homePosition = value;
			}
		}
	}

	public bool isInRotationMode()
	{
		return inRotationMode;
	}

	public override void Init()
	{
		if (!initialized)
		{
			Initialize(body.position, body.rotation);
		}
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		body = GetComponent<BoplBody>();
	}

	public void Initialize(Vec2 homePosition, Fix homeRotation)
	{
		this.homePosition = homePosition;
		this.homeRotation = (homeRotation % Fix.PiTimes2 + Fix.PiTimes2) % Fix.PiTimes2;
		initialized = true;
		isBeingControlled = false;
		inSuddenDeath = false;
	}

	public void ActivateRotationMode(Fix speedMultiplier, AnimationCurveFixed spinCurve)
	{
		if (HomeIsMovable)
		{
			inRotationMode = true;
			rotationModeSpeed = speedMultiplier;
			spinTime = Fix.Zero;
			this.spinCurve = spinCurve;
		}
	}

	public void ActivateSuddenDeath(bool activate, Fix SuddenDeathTimeStamp)
	{
		HomeIsMovable = activate;
		inSuddenDeath = activate;
		if (activate)
		{
			this.SuddenDeathTimeStamp = SuddenDeathTimeStamp;
			randomSuddenDeathDelay = Updater.RandomFix(Fix.Zero, MaxRandomSuddenDeathDelay);
		}
	}

	public void ActAsFloatingPlatformForAFrame()
	{
		actAsFloatingPlatformThisFrame = true;
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (!inSuddenDeath && GameSessionHandler.SuddenDeathInProgress)
		{
			ActivateSuddenDeath(activate: true, GameSessionHandler.SuddenDeathTimeStamp);
		}
		simDeltaTime *= GameTime.PlayerTimeScale;
		if (inSuddenDeath)
		{
			Fix fix = Updater.SimTimeSinceLevelLoaded - SuddenDeathTimeStamp;
			int num = Mathf.Min((int)(long)(fix * SuddenDeathAcceleration), 5);
			Fix fix2 = suddenDeathSpeed * (Fix)(2 << num);
			homePosition += Vec2.down * suddenDeathYSpeed.Evaluate(fix - randomSuddenDeathDelay) * fix2 * simDeltaTime;
			if (speed <= Fix.Zero && body.gravityScale == Fix.Zero)
			{
				body.gravityScale = Fix.One;
				body.GetComponent<DPhysicsRoundedRect>()?.SetGravityScale(Fix.One);
			}
		}
		Vec2 vec = HomePosition - body.position;
		UnityEngine.Debug.DrawLine((Vector3)HomePosition, (Vector3)body.position, UnityEngine.Color.black);
		Vec2 vec2 = speed * vec - mu * body.velocity;
		if (actAsFloatingPlatformThisFrame)
		{
			vec2 = -mu * body.velocity;
			homePosition = body.position;
		}
		body.AddForce(vec2 * simDeltaTime / body.InverseMass, ForceMode2D.Impulse);
		Fix fix3 = homeRotation;
		if (inRotationMode)
		{
			Fix fix4 = rotationModeSpeed * spinCurve.Evaluate(spinTime);
			homeRotation += GameTime.PlayerTimeScale * simDeltaTime * fix4 / rotationResistence;
			homeRotation = (homeRotation % Fix.PiTimes2 + Fix.PiTimes2) % Fix.PiTimes2;
			spinTime += GameTime.PlayerTimeScale * simDeltaTime;
			if (spinTime >= spinCurve.keys[spinCurve.keys.Length - 1].time)
			{
				inRotationMode = false;
			}
		}
		if (interpolateRotationHome)
		{
			Fix orientation = body.PhysicsBody().orientation;
			Fix fix5 = fix3 - orientation;
			if (Fix.Abs(fix5) > Fix.Pi)
			{
				fix5 = -(Fix)Fix.Sign(fix5) * (Fix.PiTimes2 - Fix.Abs(fix5));
			}
			Fix fix6 = body.angularVelocity + fix5 * rotationSpeed * simDeltaTime;
			body.angularVelocity = fix6 * (Fix.One - rotationMu);
		}
		if (HomePosition.x > 2500L)
		{
			homePosition.x = (Fix)2500L;
		}
		else if (HomePosition.x < -2500L)
		{
			homePosition.x = -(Fix)2500L;
		}
		if (homePosition.y > 2500L)
		{
			homePosition.y = (Fix)2500L;
		}
		else if (homePosition.y < -2500L)
		{
			homePosition.y = -(Fix)2500L;
		}
		actAsFloatingPlatformThisFrame = false;
		UnityEngine.Debug.DrawLine(base.transform.position, base.transform.position + (Vector3)body.PhysicsBody().force * 0.05f, UnityEngine.Color.green, 0.02f);
		UnityEngine.Debug.DrawLine(base.transform.position, base.transform.position + (Vector3)body.velocity * 3f, UnityEngine.Color.magenta, 0.02f);
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = UnityEngine.Color.magenta;
		Gizmos.DrawSphere((Vector2)HomePosition, 1f);
		Gizmos.color = UnityEngine.Color.black;
	}
}
public class BindInputAxisToButton : MonoBehaviour
{
	public bool horizontal = true;

	public bool reverseDirection;

	public bool playSound = true;

	[SerializeField]
	private bool ControlledByAllPlayers = true;

	private InputUpdater inputUpdater;

	public EventSystem eventSystem;

	private Button button;

	private bool clickedPrev;

	public void SetInputUpdate(InputUpdater inputUpdater)
	{
		this.inputUpdater = inputUpdater;
	}

	private void Awake()
	{
		button = GetComponent<Button>();
		if (ControlledByAllPlayers)
		{
			MenuInputHandler.Instance.MenuMap.Move0.performed -= OnMove;
			MenuInputHandler.Instance.MenuMap.Move0.performed += OnMove;
			MenuInputHandler.Instance.MenuMap.Move1.performed -= OnMove;
			MenuInputHandler.Instance.MenuMap.Move1.performed += OnMove;
			MenuInputHandler.Instance.MenuMap.Move2.performed -= OnMove;
			MenuInputHandler.Instance.MenuMap.Move2.performed += OnMove;
			MenuInputHandler.Instance.MenuMap.Move3.performed -= OnMove;
			MenuInputHandler.Instance.MenuMap.Move3.performed += OnMove;
			MenuInputHandler.Instance.MenuMap.Move4.performed -= OnMove;
			MenuInputHandler.Instance.MenuMap.Move4.performed += OnMove;
		}
	}

	private void OnDestroy()
	{
		if (ControlledByAllPlayers)
		{
			MenuInputHandler.Instance.MenuMap.Move0.performed -= OnMove;
			MenuInputHandler.Instance.MenuMap.Move1.performed -= OnMove;
			MenuInputHandler.Instance.MenuMap.Move2.performed -= OnMove;
			MenuInputHandler.Instance.MenuMap.Move3.performed -= OnMove;
			MenuInputHandler.Instance.MenuMap.Move4.performed -= OnMove;
		}
	}

	private void OnMove(InputAction.CallbackContext context)
	{
		if (!base.enabled)
		{
			return;
		}
		float num = ((!reverseDirection) ? 1 : (-1));
		Vector2 vector = context.ReadValue<Vector2>();
		float num2 = (horizontal ? vector.x : vector.y);
		if (!(Mathf.Abs(horizontal ? vector.y : vector.x) > (float)Constants.DEADZONE) && num2 * num > (float)Constants.DEADZONE)
		{
			ExecuteEvents.Execute(button.gameObject, new BaseEventData(eventSystem), ExecuteEvents.submitHandler);
			if (playSound)
			{
				AudioManager.Get().Play("navigateMenu");
			}
		}
	}

	private void Update()
	{
		if (ControlledByAllPlayers || !(inputUpdater != null) || !base.enabled)
		{
			return;
		}
		float num = ((!reverseDirection) ? 1 : (-1));
		Vector2 vector = inputUpdater.ControllerMoveVector();
		float num2 = (horizontal ? vector.x : vector.y);
		if (Mathf.Abs(horizontal ? vector.y : vector.x) > (float)Constants.DEADZONE)
		{
			return;
		}
		bool flag = num2 * num > (float)Constants.DEADZONE;
		if (flag && !clickedPrev)
		{
			ExecuteEvents.Execute(button.gameObject, new BaseEventData(eventSystem), ExecuteEvents.submitHandler);
			if (playSound)
			{
				AudioManager.Get().Play("navigateMenu");
			}
		}
		clickedPrev = flag;
	}
}
public class CanSelfDestruct : MonoBehaviour
{
	public bool TimeBasedSelfDestruct;

	public float lifeSpan;

	public bool KillAfterOneFrame;

	private float timePassed;

	public void Update()
	{
		if (KillAfterOneFrame)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		timePassed += Time.deltaTime;
		if (timePassed > lifeSpan)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	public void SelfDestruct()
	{
		UnityEngine.Object.Destroy(base.gameObject);
	}
}
