public class FlippingTransform : MonoBehaviour
{
	private readonly Vector3 faceRight = new Vector3(1f, 1f, 1f);

	private readonly Vector3 faceLeft = new Vector3(-1f, 1f, 1f);

	private bool isFacingRight = true;

	public void alignTransform(bool facingRight)
	{
		isFacingRight = facingRight;
		base.transform.localScale = (facingRight ? faceRight : faceLeft);
	}

	public void flipFacing()
	{
		base.transform.localScale = (isFacingRight ? faceLeft : faceRight);
		isFacingRight = !isFacingRight;
	}

	public bool facingRight()
	{
		return isFacingRight;
	}
}
public class FollowMainCamera : MonoBehaviour
{
	public bool followX;

	public bool negateX;

	public bool followY;

	public bool negateY;

	public bool followZ;

	public bool negateZ;

	public bool mimicCameraSize;

	public float xMultiplier = 1f;

	public Vector3 offset;

	private Camera thisCamera;

	private Camera mainCamera;

	private void Awake()
	{
		mainCamera = Camera.main;
		thisCamera = GetComponent<Camera>();
	}

	private void LateUpdate()
	{
		Vector3 position = base.transform.position;
		if (followX)
		{
			position.x = (negateX ? (0f - mainCamera.transform.position.x) : mainCamera.transform.position.x);
			position.x *= xMultiplier;
			position.x += offset.x;
		}
		if (followY)
		{
			position.y = (negateY ? (0f - mainCamera.transform.position.y) : mainCamera.transform.position.y);
			position.y += offset.y;
		}
		if (followZ)
		{
			position.z = (negateZ ? (0f - mainCamera.transform.position.z) : mainCamera.transform.position.z);
			position.y += offset.y;
		}
		if (mimicCameraSize && (bool)thisCamera)
		{
			thisCamera.orthographicSize = mainCamera.orthographicSize;
		}
		base.transform.position = position;
	}
}
public class FollowTransform : MonoBehaviour
{
	public Transform Leader;

	public bool DestroyWhenLeaderIsDestroyed;

	public bool DisableRenderersWhenLeaderIsInactive;

	private List<Renderer> Renderers;

	private Rigidbody2D body;

	private Vector3 PositionOffset;

	private bool initializedPosition;

	private void Start()
	{
		if (!initializedPosition)
		{
			Init();
		}
	}

	public void Init()
	{
		PositionOffset = base.transform.localPosition;
		AlignPositionInstantly();
		initializedPosition = true;
	}

	private void Awake()
	{
		Renderers = new List<Renderer>();
		body = GetComponent<Rigidbody2D>();
		GetComponentsInChildren(Renderers);
	}

	private void LateUpdate()
	{
		AlignPosition();
	}

	public void AlignPositionInstantly()
	{
		if (Leader != null)
		{
			base.transform.position = Leader.position + PositionOffset;
			if (body != null)
			{
				body.position = base.transform.position;
			}
		}
	}

	public void AlignPosition()
	{
		if (Leader != null)
		{
			if (body != null)
			{
				body.MovePosition(Leader.position + PositionOffset);
			}
			else
			{
				base.transform.position = Leader.position + PositionOffset;
			}
			if (DisableRenderersWhenLeaderIsInactive && Renderers.Count >= 1)
			{
				for (int i = 0; i < Renderers.Count; i++)
				{
					Renderers[i].enabled = Leader.gameObject.activeInHierarchy;
				}
			}
		}
		else if (DestroyWhenLeaderIsDestroyed)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}
}
public class FullScreenQuad : MonoBehaviour
{
	public float spriteWidth = 2f;

	public float spriteHeight = 2f;

	public bool followMainCamera;

	private Camera mainCamera;

	private void Awake()
	{
		mainCamera = Camera.main;
		UpdateSize();
		base.transform.position = Vector3.zero;
	}

	private void UpdateSize()
	{
		float num = mainCamera.orthographicSize * 2f;
		float num2 = num * mainCamera.aspect;
		base.transform.localScale = new Vector3(num2 / spriteWidth, num / spriteHeight, 1f);
	}

	private void LateUpdate()
	{
		if (followMainCamera)
		{
			base.transform.position = new Vector3(mainCamera.transform.position.x, mainCamera.transform.position.y, base.transform.position.z);
		}
		UpdateSize();
	}
}
public class Gravity : MonoUpdatable
{
	public Fix accel;

	public Fix maxFallSpeed;

	public Fix modifier = Fix.One;

	private PlayerBody body;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		body = GetComponent<PlayerBody>();
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix simDeltaTime)
	{
		if (body.selfImposedVelocity.y > -maxFallSpeed)
		{
			body.selfImposedVelocity = new Vec2(body.selfImposedVelocity.x, body.selfImposedVelocity.y - accel * modifier);
		}
		if (body.selfImposedVelocity.y < -maxFallSpeed)
		{
			body.selfImposedVelocity = new Vec2(body.selfImposedVelocity.x, -maxFallSpeed);
		}
	}
}
public class HashMap_short
{
	public short[] values;

	public int[] keys;

	public int[] next;

	public int[] buckets;

	public int entryCount;

	protected int capacity;

	protected int deletedInd = -1;

	protected int unfilledEntries;

	public void CopyTo(HashMap_short recepient)
	{
		recepient.capacity = capacity;
		recepient.deletedInd = deletedInd;
		recepient.unfilledEntries = unfilledEntries;
		recepient.entryCount = entryCount;
		Array.Copy(buckets, recepient.buckets, buckets.Length);
		Array.Copy(values, recepient.values, capacity);
		Array.Copy(keys, recepient.keys, capacity);
		Array.Copy(next, recepient.next, capacity);
	}

	public HashMap_short(int capacity, int bucketCount)
	{
		this.capacity = capacity;
		values = new short[capacity];
		keys = new int[capacity];
		next = new int[capacity];
		for (int i = 0; i < capacity; i++)
		{
			next[i] = -1;
		}
		buckets = new int[bucketCount];
		for (int j = 0; j < bucketCount; j++)
		{
			buckets[j] = -1;
		}
	}

	public void Add(int key, short value)
	{
		int num = (HashFun(key) & 0x7FFFFFFF) % buckets.Length;
		int num2 = buckets[num];
		for (int num3 = num2; num3 >= 0; num3 = next[num3])
		{
			if (key == keys[num3])
			{
				values[num3] = value;
				return;
			}
		}
		int num4;
		if (unfilledEntries > 0)
		{
			num4 = deletedInd;
			deletedInd = next[deletedInd];
			unfilledEntries--;
		}
		else
		{
			num4 = entryCount;
			entryCount++;
		}
		next[num4] = num2;
		keys[num4] = key;
		values[num4] = value;
		buckets[num] = num4;
	}

	public bool ContainsKey(int key)
	{
		return GetIndex(key) < 0;
	}

	public int GetIndex(int key)
	{
		int num = HashFun(key);
		num = (num & 0x7FFFFFFF) % buckets.Length;
		for (int num2 = buckets[num]; num2 >= 0; num2 = next[num2])
		{
			if (key == keys[num2])
			{
				return num2;
			}
		}
		return -1;
	}

	public bool TryGetValue(int key, out short value)
	{
		int index = GetIndex(key);
		value = -1;
		if (index < 0)
		{
			return false;
		}
		value = values[index];
		return true;
	}

	public bool Remove(int key)
	{
		int num = HashFun(key);
		num = (num & 0x7FFFFFFF) % buckets.Length;
		int num2 = buckets[num];
		int num3 = -1;
		for (int num4 = num2; num4 >= 0; num4 = next[num4])
		{
			if (key == keys[num2])
			{
				if (num3 < 0)
				{
					buckets[num] = next[num4];
				}
				else
				{
					next[num3] = next[num4];
				}
				next[num4] = deletedInd;
				keys[num4] = 0;
				values[num4] = 0;
				deletedInd = num4;
				unfilledEntries++;
				return true;
			}
			num3 = num4;
		}
		return false;
	}

	public void Clear()
	{
		Array.Clear(keys, 0, entryCount);
		Array.Clear(values, 0, entryCount);
		deletedInd = -1;
		unfilledEntries = 0;
		entryCount = 0;
		for (int i = 0; i < capacity; i++)
		{
			next[i] = -1;
		}
		for (int j = 0; j < buckets.Length; j++)
		{
			buckets[j] = -1;
		}
	}

	private int HashFun(int key)
	{
		return key;
	}
}
