public static class InputSystemExtensions
{
	public static bool IsUsable_(this Gamepad gamepad)
	{
		if (gamepad == null)
		{
			return false;
		}
		for (int i = 0; i < InputSystem.disconnectedDevices.Count; i++)
		{
			if (gamepad.deviceId == InputSystem.disconnectedDevices[i].deviceId)
			{
				return false;
			}
		}
		return true;
	}
}
public class InputUpdater : MonoBehaviour
{
	private static bool IsPollingFreqSet = false;

	private Player.InputProfile inputProfile = new Player.InputProfile();

	private Player linkedPlayer;

	private Camera mainCam;

	private PlayerInput playerInput;

	private int ClaimerId = -1;

	private static readonly string[] swappableControls = new string[8] { "Jump", "Ability0", "Ability2", "Ability1", "W", "A", "S", "D" };

	private bool controlSchemeHasBeenInitialized;

	private bool hasBeenInited;

	private float timeRumbling;

	private Rumble prevRumbleState;

	public float rumbleSeconds = 2f;

	public Vector2 ExtraSmallRumbleMotorSpeeds = new Vector2(0.05f, 0.05f);

	public Vector2 SmallRumbleMotorSpeeds = new Vector2(0.2f, 0.1f);

	public Vector2 BigRumbleMotorSpeeds = new Vector2(0.4f, 0.3f);

	public float TensionAccelerationTime = 3f;

	private Vector2 CurrentTension = Vector2.zero;

	private Vector2 move0;

	private Vector2 move1;

	private Vector2 move2;

	private Vector2 mousePos;

	public int GetClaimerId()
	{
		return ClaimerId;
	}

	public void Claim(int playerId)
	{
		ClaimerId = playerId;
	}

	public void UnClaim()
	{
		ClaimerId = -1;
	}

	public bool HasBeenClaimed()
	{
		return ClaimerId >= 0;
	}

	public void Init(int playerId)
	{
		if (GameLobby.isPlayingAReplay)
		{
			return;
		}
		hasBeenInited = true;
		playerInput = GetComponent<PlayerInput>();
		linkedPlayer = PlayerHandler.Get().GetPlayer(playerId);
		mainCam = Camera.main;
		timeRumbling = 0f;
		prevRumbleState = Rumble.None;
		if (!linkedPlayer.UsesKeyboardAndMouse)
		{
			if (linkedPlayer.PlayerHasValidGamepad())
			{
				playerInput.SwitchCurrentControlScheme("GamePad", linkedPlayer.inputDevice);
				controlSchemeHasBeenInitialized = true;
			}
			else
			{
				controlSchemeHasBeenInitialized = false;
			}
		}
		if (linkedPlayer.CustomKeyBinding != null)
		{
			for (int i = 0; i < linkedPlayer.CustomKeyBinding.Length; i++)
			{
				if (linkedPlayer.CustomKeyBinding[i] != null)
				{
					playerInput.currentActionMap.FindAction(swappableControls[i]).ApplyBindingOverride(linkedPlayer.CustomKeyBinding[i].path);
				}
			}
			return;
		}
		for (int j = 0; j < playerInput.currentActionMap.actions.Count; j++)
		{
			int bindingIndex = 0;
			if (linkedPlayer.UsesKeyboardAndMouse && j <= 4 && j > 0)
			{
				bindingIndex = 1;
			}
			if (playerInput.currentActionMap.actions[j].controls.Count == 0)
			{
				playerInput.currentActionMap.actions[j].ApplyBindingOverride(bindingIndex, default(InputBinding));
				if (linkedPlayer.UsesKeyboardAndMouse && j == 4)
				{
					playerInput.currentActionMap.actions[j].ApplyBindingOverride(2, default(InputBinding));
					playerInput.currentActionMap.actions[j].ApplyBindingOverride(3, default(InputBinding));
				}
			}
		}
	}

	private void Awake()
	{
		if (!IsPollingFreqSet)
		{
			InputSystem.pollingFrequency = 120f;
		}
		IsPollingFreqSet = true;
	}

	private void SetMotorSpeeds(Vector2 speeds)
	{
		ReadOnlyArray<Gamepad> all = Gamepad.all;
		for (int i = 0; i < all.Count; i++)
		{
			ReadOnlyArray<InputDevice> devices = playerInput.devices;
			for (int j = 0; j < devices.Count; j++)
			{
				if (all[i].deviceId == devices[j].deviceId)
				{
					if (Settings.Get().Rumble == 2)
					{
						all[i].SetMotorSpeeds(speeds.x * 3f, speeds.y * 3f);
					}
					else
					{
						all[i].SetMotorSpeeds(speeds.x, speeds.y);
					}
				}
			}
		}
	}

	private void PauseMotorSpeeds()
	{
		ReadOnlyArray<Gamepad> all = Gamepad.all;
		for (int i = 0; i < all.Count; i++)
		{
			ReadOnlyArray<InputDevice> devices = playerInput.devices;
			for (int j = 0; j < devices.Count; j++)
			{
				if (all[i].deviceId == devices[j].deviceId)
				{
					all[i].ResetHaptics();
				}
			}
		}
	}

	public static void PauseAllRumble()
	{
		ReadOnlyArray<Gamepad> all = Gamepad.all;
		for (int i = 0; i < all.Count; i++)
		{
			all[i].ResetHaptics();
		}
	}

	private void Update()
	{
		if (linkedPlayer == null || GameLobby.isPlayingAReplay || linkedPlayer.ignoreAllInputs)
		{
			return;
		}
		if (hasBeenInited && !controlSchemeHasBeenInitialized && !linkedPlayer.UsesKeyboardAndMouse && !GameLobby.isPlayingAReplay && linkedPlayer.PlayerHasValidGamepad())
		{
			playerInput.SwitchCurrentControlScheme("GamePad", linkedPlayer.inputDevice);
			controlSchemeHasBeenInitialized = true;
		}
		if (Settings.Get().Rumble != 0)
		{
			if (linkedPlayer.RumbleState == Rumble.BuildTension)
			{
				timeRumbling = 0f;
				if (prevRumbleState != Rumble.BuildTension)
				{
					SetMotorSpeeds(ExtraSmallRumbleMotorSpeeds);
				}
			}
			bool flag = linkedPlayer.RumbleState == Rumble.Small || linkedPlayer.RumbleState == Rumble.Big;
			if ((linkedPlayer.RumbleState == Rumble.Small || linkedPlayer.RumbleState == Rumble.Big) && prevRumbleState != Rumble.Small && prevRumbleState != Rumble.Big)
			{
				timeRumbling = 0f;
				if (linkedPlayer.RumbleState == Rumble.Small)
				{
					SetMotorSpeeds(SmallRumbleMotorSpeeds);
				}
				else
				{
					SetMotorSpeeds(BigRumbleMotorSpeeds);
				}
			}
			timeRumbling = (flag ? (timeRumbling + Time.deltaTime) : 0f);
			if (timeRumbling > rumbleSeconds)
			{
				PauseMotorSpeeds();
				linkedPlayer.Rumble(Rumble.None);
			}
			else if (linkedPlayer.RumbleState == Rumble.None && prevRumbleState != Rumble.None)
			{
				timeRumbling = 0f;
				CurrentTension = Vector2.zero;
				PauseMotorSpeeds();
			}
			prevRumbleState = linkedPlayer.RumbleState;
		}
		if (linkedPlayer.UsesKeyboardAndMouse)
		{
			if (mainCam == null)
			{
				mainCam = Camera.main;
			}
			Vector2 vector = mainCam.ScreenToWorldPoint(mousePos);
			linkedPlayer.mouseWorldPos = vector;
			Vector2 vector2 = (Vector2)((linkedPlayer.InSparkShot || linkedPlayer.InPlatformTransform || linkedPlayer.InMachoThrow) ? linkedPlayer.CustomAimAbilityPosition : linkedPlayer.Position);
			Vector2 vector3 = vector - vector2;
			vector3 = ((!(vector3.SqrMagnitude() < 0.2f)) ? vector3.normalized : Vector2.zero);
			_ = inputProfile.w_IS_DOWN;
			_ = inputProfile.a_IS_DOWN;
			_ = inputProfile.s_IS_DOWN;
			_ = inputProfile.d_IS_DOWN;
			inputProfile.joystickAngleByte = Player.InputProfile.JoyStickAngleByteFromVector((Vec2)vector3);
		}
		else
		{
			Vector2 vector4 = ControllerMoveVector();
			vector4 = ((!(vector4.sqrMagnitude < (float)Constants.DEADZONE * (float)Constants.DEADZONE)) ? vector4.normalized : Vector2.zero);
			inputProfile.joystickAngleByte = Player.InputProfile.JoyStickAngleByteFromVector((Vec2)vector4);
		}
		linkedPlayer.ForceSetInputProfile(inputProfile.startButton_IS_DOWN, inputProfile.selectButton_IS_DOWN, inputProfile.jumpButton_IS_DOWN, inputProfile.firstAbilityButton_IS_DOWN, inputProfile.secondAbilityButton_IS_DOWN, inputProfile.thirdAbilityButton_IS_DOWN, inputProfile.joystickAngleByte, inputProfile.w_IS_DOWN, inputProfile.a_IS_DOWN, inputProfile.s_IS_DOWN, inputProfile.d_IS_DOWN);
	}

	public Vector2 ControllerMoveVector()
	{
		float sqrMagnitude = move0.sqrMagnitude;
		float sqrMagnitude2 = move1.sqrMagnitude;
		float sqrMagnitude3 = move2.sqrMagnitude;
		if (sqrMagnitude >= sqrMagnitude2 && sqrMagnitude >= sqrMagnitude3)
		{
			return move0;
		}
		if (sqrMagnitude2 >= sqrMagnitude && sqrMagnitude2 >= sqrMagnitude3)
		{
			return move1;
		}
		if (sqrMagnitude3 >= sqrMagnitude && sqrMagnitude3 >= sqrMagnitude2)
		{
			return move2;
		}
		return move0;
	}

	public void OnW(InputAction.CallbackContext context)
	{
		inputProfile.UsesMouse = true;
		inputProfile.w_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnA(InputAction.CallbackContext context)
	{
		inputProfile.UsesMouse = true;
		inputProfile.a_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnS(InputAction.CallbackContext context)
	{
		inputProfile.UsesMouse = true;
		inputProfile.s_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnD(InputAction.CallbackContext context)
	{
		inputProfile.UsesMouse = true;
		inputProfile.d_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnMove(InputAction.CallbackContext context)
	{
		move0 = context.ReadValue<Vector2>();
	}

	public void OnMoveFallback0(InputAction.CallbackContext context)
	{
		move1 = context.ReadValue<Vector2>();
	}

	public void OnMoveFallback1(InputAction.CallbackContext context)
	{
		move2 = context.ReadValue<Vector2>();
	}

	public void OnJump(InputAction.CallbackContext context)
	{
		inputProfile.jumpButton_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnAbility0(InputAction.CallbackContext context)
	{
		inputProfile.firstAbilityButton_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnAbility1(InputAction.CallbackContext context)
	{
		inputProfile.secondAbilityButton_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnAbility2(InputAction.CallbackContext context)
	{
		inputProfile.thirdAbilityButton_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnStart(InputAction.CallbackContext context)
	{
		inputProfile.startButton_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnSelect(InputAction.CallbackContext context)
	{
		inputProfile.selectButton_IS_DOWN = context.ReadValueAsButton();
	}

	public void OnAimPosition(InputAction.CallbackContext context)
	{
		inputProfile.UsesMouse = true;
		mousePos = context.ReadValue<Vector2>();
	}

	public void OnControlsChanged()
	{
		inputProfile.Reset();
	}
}
public class KillZone : MonoUpdatable, ICollisionCallback
{
	public GameObject effect;

	public float WaterHeight;

	public void OnCollide(CollisionInformation collision)
	{
		if (collision.layer == LayerMask.NameToLayer("Player"))
		{
			SpawnWaterSplash((Vector2)collision.collider.Pos());
			int playerId = collision.pp.fixTrans.GetComponent<IPlayerIdHolder>().GetPlayerId();
			PlayerHandler.Get().GetPlayer(playerId)?.Kill(Constants.ENVIRONMENTAL_PLAYER_ID, Updater.SimulationTicks, CauseOfDeath.Accident);
			Updater.DestroyFix(collision.pp.fixTrans.gameObject);
		}
		else if (collision.layer == LayerMask.NameToLayer("item"))
		{
			SpawnWaterSplash((Vector2)collision.collider.Pos());
			Updater.DestroyFix(collision.pp.fixTrans.gameObject);
		}
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		GetComponent<DPhysicsBox>().RegisterCollisionCallback(this);
	}

	public override void Init()
	{
	}

	public override bool IsEnabled()
	{
		return false;
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}

	private void SpawnWaterSplash(Vector2 pos)
	{
		pos.y = WaterHeight;
		UnityEngine.Object.Instantiate(effect, pos, Quaternion.identity);
		AudioManager.Get().Play("waterSplash");
	}
}
public class LerpToPos : MonoBehaviour
{
	public Vector3 deltaPosition;

	private Vector3 origin;

	public float SecondsUntilArrival;

	private bool moveTowardsPos;

	private float timePassed;

	private IPlayerIdHolder idHolder;

	private void Awake()
	{
		idHolder = GetComponent<IPlayerIdHolder>();
	}

	private void Start()
	{
		moveTowardsPos = false;
		timePassed = 0f;
		origin = base.transform.localPosition;
	}

	private void Update()
	{
		timePassed += GameTime.DeltaTime(idHolder);
		if (moveTowardsPos)
		{
			float x = Mathf.Lerp(origin.x, deltaPosition.x, Mathf.Min(timePassed / SecondsUntilArrival, 1f));
			float y = Mathf.Lerp(origin.y, deltaPosition.y, Mathf.Min(timePassed / SecondsUntilArrival, 1f));
			base.transform.localPosition = new Vector3(x, y, base.transform.localPosition.z);
		}
		else
		{
			timePassed = 0f;
		}
	}

	public void resetPosition()
	{
		timePassed = 0f;
