public class PlayerAverageCamera : MonoBehaviour
{
	public float cameraSpeed = 1f;

	public float weight = 1E-07f;

	public GameObject abilityList;

	private Camera camera;

	[Range(0f, 1f)]
	public float zoomWeight = 0.1f;

	public float MIN_ZOOM = 13f;

	public float MAX_ZOOM = 25f;

	public float extraZoomRoom = 1f;

	public float outsideLevelX = 1f;

	public float MinHeightAboveFloor;

	public bool useMinMaxForCameraX;

	public bool UpdateX;

	public bool UpdateY;

	public float playerSpawnWeight = 1f;

	public float maxDeltaTime = 0.0666666f;

	public float pixelToUnits = 60f;

	private void Start()
	{
		camera = GetComponent<Camera>();
		base.transform.position = new Vector3(0f, base.transform.position.y, base.transform.position.z);
	}

	private void UpdateCamera()
	{
		List<Player> list = PlayerHandler.Get().PlayerList();
		Vector2 vector = default(Vector2);
		float num = list.Count;
		float num2 = 0f;
		float num3 = 0f;
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].IsAlive)
			{
				Vector2 vector2 = (Vector2)list[i].Position;
				vector += vector2;
				num2 = Mathf.Max(num2, vector2.x);
				num3 = Mathf.Min(num3, vector2.x);
			}
		}
		_ = GameSessionHandler.playerSpawns_readonly;
		vector /= num;
		if (useMinMaxForCameraX)
		{
			vector = new Vector2((num3 + num2) * 0.5f, vector.y);
		}
		float num4 = Mathf.Min(maxDeltaTime, Time.unscaledDeltaTime);
		Vector2 vector3 = (1f - weight * num4) * (Vector2)base.transform.localPosition + weight * num4 * vector;
		float num5 = camera.orthographicSize * camera.aspect + outsideLevelX;
		vector3.x = Mathf.Max((float)SceneBounds.Camera_XMin + num5, vector3.x);
		vector3.x = Mathf.Min((float)SceneBounds.Camera_XMax - num5, vector3.x);
		vector3.x = RoundToNearestPixel(vector3.x);
		vector3.y = Mathf.Max((float)SceneBounds.WaterHeight + MinHeightAboveFloor, vector3.y);
		vector3.y = Mathf.Min((float)SceneBounds.Camera_YMax, vector3.y);
		vector3.y = RoundToNearestPixel(vector3.y);
		if (!UpdateX)
		{
			vector3.x = base.transform.position.x;
		}
		if (!UpdateY)
		{
			vector3.y = base.transform.position.y;
		}
		Vector3 position = new Vector3(vector3.x, vector3.y, base.transform.position.z);
		base.transform.position = position;
		float num6 = 0f;
		float num7 = 0f;
		for (int j = 0; j < list.Count; j++)
		{
			Vector2 vector4 = (Vector2)list[j].Position;
			float b = Mathf.Abs(vector4.x - vector.x);
			num6 = Mathf.Max(num6, b);
			b = Mathf.Abs(vector4.y - vector.y);
			num7 = Mathf.Max(num7, b);
		}
		float num8 = Screen.width / Screen.height;
		num6 *= num8;
		float num9 = Mathf.Max(num6, num7);
		num9 += extraZoomRoom;
		if (num9 > MAX_ZOOM)
		{
			num9 = MAX_ZOOM;
		}
		if (num9 < MIN_ZOOM)
		{
			num9 = MIN_ZOOM;
		}
		float num10 = Mathf.Clamp((1f - zoomWeight * num4) * camera.orthographicSize + zoomWeight * num4 * num9, MIN_ZOOM, MAX_ZOOM);
		if (camera.orthographicSize != num10)
		{
			camera.orthographicSize = num10;
		}
	}

	private void LateUpdate()
	{
		UpdateCamera();
	}

	public float RoundToNearestPixel(float unityUnits)
	{
		return Mathf.Round(unityUnits * pixelToUnits) * (1f / pixelToUnits);
	}
}
