public class RingBufferSimple<T>
{
	private int size;

	private int current;

	public T[] array;

	public int Length => size;

	public T this[int i]
	{
		get
		{
			return array[i];
		}
		set
		{
			array[i] = value;
		}
	}

	public RingBufferSimple(int bufferSize)
	{
		size = bufferSize;
		array = new T[bufferSize];
	}

	public T Current()
	{
		return array[current];
	}

	public void Add(T newObj)
	{
		array[current] = newObj;
		current = (current + 1) % size;
	}
}
public class RingBuffer<T> where T : UnityEngine.Component
{
	private int size;

	private int current;

	private bool reBalance;

	private T[] array;

	public int Length => size;

	public T this[int i]
	{
		get
		{
			return array[i];
		}
		set
		{
			array[i] = value;
		}
	}

	public RingBuffer(int bufferSize, bool reBalance = true)
	{
		size = bufferSize;
		this.reBalance = reBalance;
		array = new T[bufferSize];
	}

	public T Current()
	{
		return array[current];
	}

	public void Add(T newObj)
	{
		if (array[current] != null && reBalance)
		{
			int num = current;
			for (int i = 0; i < array.Length; i++)
			{
				num = (current + i) % size;
				if (array[num] == null)
				{
					for (int j = 0; j < i; j++)
					{
						array[(num - j + size) % size] = array[(num - j - 1 + size) % size];
					}
					array[current] = null;
					break;
				}
			}
		}
		if (array[current] != null)
		{
			Updater.DestroyFix(array[current].gameObject);
		}
		array[current] = newObj;
		current = (current + 1) % size;
	}
}
public class RoutineQueue
{
	public enum RoutineType
	{
		Delay,
		Delay1Update,
		Function,
		Loop
	}

	public struct Routine
	{
		public RoutineType type;

		public Action function;

		public Fix Delay;

		public Func<Fix, bool> loop;
	}

	private Queue<Routine> queue = new Queue<Routine>();

	private Fix TimeDelayed;

	public void Delay(Fix delay)
	{
		queue.Enqueue(new Routine
		{
			type = RoutineType.Delay,
			Delay = delay
		});
	}

	public void Function(Action function)
	{
		queue.Enqueue(new Routine
		{
			type = RoutineType.Function,
			function = function
		});
	}

	public void Delay1Update()
	{
		queue.Enqueue(new Routine
		{
			type = RoutineType.Delay1Update
		});
	}

	public void WhileLoop(Func<Fix, bool> func)
	{
		queue.Enqueue(new Routine
		{
			type = RoutineType.Loop,
			loop = func
		});
	}

	public void Clear()
	{
		queue.Clear();
	}

	public void Update(Fix deltaTime)
	{
		if (queue.Count == 0)
		{
			return;
		}
		Routine routine = queue.Peek();
		switch (routine.type)
		{
		case RoutineType.Delay:
			TimeDelayed += deltaTime;
			if (TimeDelayed > routine.Delay)
			{
				TimeDelayed = Fix.Zero;
				queue.Dequeue();
			}
			break;
		case RoutineType.Delay1Update:
			queue.Dequeue();
			break;
		case RoutineType.Function:
			queue.Dequeue().function();
			break;
		case RoutineType.Loop:
			if (!routine.loop(deltaTime))
			{
				queue.Dequeue();
			}
			break;
		}
	}
}
public static class SceneBounds
{
	public static readonly Fix Camera_XMin = (Fix)(-97.27f);

	public static readonly Fix Camera_XMax = (Fix)97.6f;

	public static readonly Fix Camera_YMax = (Fix)40f;

	private static readonly Fix waterHeight = (Fix)(-11.3f);

	private static readonly Fix spaceWaterHeight = (Fix)(-50f);

	public static readonly Fix Camera_YMin = -(Fix)26L;

	public static readonly Fix BlastZone_XMin = (Fix)(-105L);

	public static readonly Fix BlastZone_XMax = (Fix)105L;

	public static readonly Fix BlastZone_YMax = (Fix)58L;

	public static Fix WaterHeight
	{
		get
		{
			if (!Constants.isSpaceLevel)
			{
				return waterHeight;
			}
			return spaceWaterHeight;
		}
	}

	public static Vec2 ClampInsideCameraMaxBounds(Vec2 pos, Vec2 offset)
	{
		pos.x = Fix.Clamp(pos.x, Camera_XMin + offset.x, Camera_XMax - offset.x);
		pos.y = Fix.Clamp(pos.y, Camera_YMin + offset.y, Camera_YMax - offset.y);
		return pos;
	}

	public static bool IsInSceneBounds(Vec2 pos)
	{
		if (pos.x >= Camera_XMin && pos.x <= Camera_XMax && pos.y >= Camera_YMin)
		{
			return pos.y <= Camera_YMax;
		}
		return false;
	}
}
public class ShakableCamera : MonoBehaviour
{
	private float trauma;

	public float traumaDecayRate = 0.6f;

	public float maxOffset = 1.5f;

	public float perlinSpeed = 16f;

	public float maxTrauma = 1f;

	public bool shakeX = true;

	public bool shakeY = true;

	public Settings settings;

	private float seed = 0.23f;

	private float shake;

	private void Start()
	{
		trauma = 0f;
	}

	public float GetTrauma()
	{
		return trauma;
	}

	public void AddTrauma(float deltaTrauma)
	{
		trauma = Mathf.Min(maxTrauma, trauma + deltaTrauma);
	}

	public void AddMinTrauma(float minTrauma)
	{
		trauma = Mathf.Min(Mathf.Max(trauma, minTrauma), maxTrauma);
	}

	private void Update()
	{
		if (!settings.AllowScreenShake)
		{
			return;
		}
		trauma -= traumaDecayRate * Time.deltaTime;
		trauma = ((trauma < 0f) ? 0f : trauma);
		if (trauma == 0f)
		{
			base.transform.position = Vector3.zero;
			return;
		}
		shake = trauma * trauma;
		float x = 0f;
		float y = 0f;
		if (shakeX)
		{
			x = maxOffset * shake * (Mathf.PerlinNoise(Time.time * perlinSpeed, seed) - 0.5f) * 2f;
		}
		if (shakeY)
		{
			y = maxOffset * shake * (Mathf.PerlinNoise(Time.time * perlinSpeed, seed + 0.5f) - 0.5f) * 2f;
		}
		Vector3 position = new Vector3(x, y, 0f);
		base.transform.position = position;
	}
}
