public static class Tools
{
	public static void print(string msg)
	{
		UnityEngine.Debug.LogFormat(LogType.Log, LogOption.NoStacktrace, null, "{0}", msg);
	}

	public static Vec2 Reflect(Vec2 v, Vec2 n)
	{
		Vec2 vec = Vec2.MulByNegI(n);
		return n * Vec2.Dot(-v, n) + vec * Vec2.Dot(vec, v);
	}

	public static Fix GetRotationFromDirection(Vec2 dir, Vec2 upVector)
	{
		Fix fix = Fix.Acos(Vec2.Dot(Vec2.Normalized(dir), Vec2.Normalized(upVector)));
		if (dir.x > 0L)
		{
			fix = Fix.PiTimes2 - fix;
		}
		return fix;
	}

	public static float Duration(this AnimationCurve curve)
	{
		return curve.keys[curve.keys.Length - 1].time;
	}

	public static Fix Duration(this AnimationCurveFixed curve)
	{
		return curve.keys[curve.keys.Length - 1].time;
	}

	public static void SetRotationFromUpDirection(Vec2 direction, FixTransform t)
	{
		t.up = direction;
	}

	public static void SetRotationFromInput(FixTransform fixTrans, Vec2 input, Fix deadZoneRadius, Vec2 upVector)
	{
		if (!(Fix.Abs(input.x) < deadZoneRadius) || !(Fix.Abs(input.y) < deadZoneRadius))
		{
			Fix fix = Fix.Acos(Vec2.Dot(input, upVector));
			if (input.x > 0L)
			{
				fix = Fix.PiTimes2 - fix;
			}
			fixTrans.rotation = fix * (Fix)180L / Fix.Pi;
		}
	}

	public static Fix Angle2(Vec2 a, Vec2 b)
	{
		Vec2 vec = a * Vec2.Magnitude(b);
		Vec2 vec2 = b * Vec2.Magnitude(a);
		return (Fix)2L * Fix.Atan2(Vec2.Magnitude(vec - vec2), Vec2.Magnitude(vec + vec2));
	}

	public static bool LayerMaskContains(LayerMask mask, string LayerMaskName)
	{
		return ((1 << LayerMask.NameToLayer(LayerMaskName)) & mask.value) != 0;
	}

	public static bool LayerMaskContains(LayerMask mask, int layer)
	{
		return ((1 << layer) & mask.value) != 0;
	}

	public static void Debug_DrawLine_fu(Vec2 from, Vec2 to, UnityEngine.Color c)
	{
		UnityEngine.Debug.DrawLine((Vector3)from, (Vector3)to, c, (float)GameTime.FixedTimeStep);
	}

	public static void Debug_DrawLine(Vec2 from, Vec2 to, UnityEngine.Color c, float time)
	{
		UnityEngine.Debug.DrawLine((Vector3)from, (Vector3)to, c, time);
	}

	public static void Debug_DrawPos_fu(Vec2 pos, UnityEngine.Color c)
	{
		Vector3 vector = new Vector2(0.3f, 0.3f);
		UnityEngine.Debug.DrawLine((Vector3)pos + vector, (Vector3)pos - vector, c, (float)GameTime.FixedTimeStep);
		vector = new Vector2(-0.3f, 0.3f);
		UnityEngine.Debug.DrawLine((Vector3)pos + vector, (Vector3)pos - vector, c, (float)GameTime.FixedTimeStep);
	}

	public static void Debug_DrawPos_u(Vec2 pos, UnityEngine.Color c)
	{
		Vector3 vector = new Vector2(0.3f, 0.3f);
		UnityEngine.Debug.DrawLine((Vector3)pos + vector, (Vector3)pos - vector, c, Time.deltaTime);
		vector = new Vector2(-0.3f, 0.3f);
		UnityEngine.Debug.DrawLine((Vector3)pos + vector, (Vector3)pos - vector, c, Time.deltaTime);
	}

	public static void Debug_DrawPos(Vec2 pos, UnityEngine.Color c, float time)
	{
		Vector3 vector = new Vector2(0.3f, 0.3f);
		UnityEngine.Debug.DrawLine((Vector3)pos + vector, (Vector3)pos - vector, c, time);
		vector = new Vector2(-0.3f, 0.3f);
		UnityEngine.Debug.DrawLine((Vector3)pos + vector, (Vector3)pos - vector, c, time);
	}

	public static void Debug_DrawAABB(AABB bb, UnityEngine.Color c, float time)
	{
		Vector2 vector = (Vector2)bb.min;
		Vector2 vector2 = (Vector2)bb.max;
		Vector2 vector3 = (Vector2)bb.min;
		vector3.y = vector2.y;
		Vector2 vector4 = (Vector2)bb.max;
		vector4.y = vector.y;
		UnityEngine.Debug.DrawLine(vector3, vector2, c, time);
		UnityEngine.Debug.DrawLine(vector2, vector4, c, time);
		UnityEngine.Debug.DrawLine(vector4, vector, c, time);
		UnityEngine.Debug.DrawLine(vector, vector3, c, time);
	}

	public static void Debug_DrawLine_u(Vec2 from, Vec2 to, UnityEngine.Color c)
	{
		UnityEngine.Debug.DrawLine((Vector3)from, (Vector3)to, c, Time.deltaTime);
	}
}
public class VaryScaleWithWorldPos : MonoBehaviour
{
	public float yStrength;

	public float xStrength;

	public Vector2 offset;

	private Vector3 scaleOrigin;

	private void Start()
	{
		scaleOrigin = base.transform.localScale;
	}

	private void Update()
	{
		Vector3 localScale = base.transform.localScale;
		localScale.y = scaleOrigin.y + Mathf.Sin(base.transform.position.x + offset.x) * xStrength + Mathf.Sin(base.transform.position.y + offset.y) * yStrength;
		base.transform.localScale = localScale;
	}
