public class vibrate : MonoUpdatable
{
	public Fix Speed;

	public Fix amplitude;

	private Vec2 startPos;

	private IPlayerIdHolder idHolder;

	private FixTransform fixTrans;

	private Fix cTime = Fix.Zero;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		idHolder = GetComponent<IPlayerIdHolder>();
		fixTrans = GetComponent<FixTransform>();
	}

	public override void Init()
	{
		startPos = fixTrans.position;
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		cTime += GameTime.FixedDeltaTime(idHolder, SimDeltaTime);
		Vec2 vec = new Vec2(Fix.Zero, amplitude * Fix.Sin(Speed * cTime));
		fixTrans.position = startPos + vec;
	}
