			return lang switch
			{
				Language.EN => enFontAsset_stroke, 
				Language.JP => jpFontAsset_stroke, 
				Language.KO => chinese_koreanAsset_stroke, 
				Language.FR => enFontAsset_stroke, 
				Language.IT => enFontAsset_stroke, 
				Language.DE => enFontAsset_stroke, 
				Language.ES => enFontAsset_stroke, 
				Language.PTBR => plFontAsset_stroke, 
				Language.RU => russian_Asset_stroke, 
				Language.TR => plFontAsset_stroke, 
				Language.SE => enFontAsset_stroke, 
				Language.ZHCN => chinese_koreanAsset_stroke, 
				Language.ZHTW => chinese_koreanAsset_stroke, 
				Language.PL => plFontAsset_stroke, 
				_ => enFontAsset_stroke, 
			};
		}
		return lang switch
		{
			Language.EN => enFontAsset, 
			Language.JP => jpFontAsset, 
			Language.KO => chinese_koreanAsset, 
			Language.FR => enFontAsset, 
			Language.IT => enFontAsset, 
			Language.DE => enFontAsset, 
			Language.ES => enFontAsset, 
			Language.PTBR => plFontAsset, 
			Language.RU => russian_Asset, 
			Language.TR => plFontAsset, 
			Language.SE => enFontAsset, 
			Language.ZHCN => chinese_koreanAsset, 
			Language.ZHTW => chinese_koreanAsset, 
			Language.PL => plFontAsset, 
			_ => enFontAsset, 
		};
	}

	public string GetText(string enText, Language lang)
	{
		return lang switch
		{
			Language.EN => enText, 
			Language.JP => getText(enText, jp), 
			Language.KO => getText(enText, ko), 
			Language.FR => getText(enText, fr), 
			Language.IT => getText(enText, it), 
			Language.DE => getText(enText, de), 
			Language.ES => getText(enText, es), 
			Language.PTBR => getText(enText, ptbr), 
			Language.RU => getText(enText, ru), 
			Language.TR => getText(enText, tr), 
			Language.SE => getText(enText, se), 
			Language.ZHCN => getText(enText, zhcn), 
			Language.ZHTW => getText(enText, zhtw), 
			Language.PL => getText(enText, pl), 
			_ => enText, 
		};
	}

	private string getText(string enText, string[] languageArray)
	{
		for (int i = 0; i < languageArray.Length; i++)
		{
			if (enText.Equals(en[i]))
			{
				return languageArray[i];
			}
		}
		UnityEngine.Debug.LogWarning("no translation found for text: " + enText);
		return enText;
	}
}
