	private bool GJK_box2box_distance(Box b1, Box b2, out Fix distance)
	{
		Gizmos.color = UnityEngine.Color.yellow;
		distance = Fix.MaxValue;
		colorForSimplex = 0;
		Simplex simplex = default(Simplex);
		Vec2 vec = b1.center - b2.center;
		simplex.c = PhysTools.SupportFun_box(b1, vec) - PhysTools.SupportFun_box(b2, -vec);
		simplex.b = PhysTools.SupportFun_box(b1, -vec) - PhysTools.SupportFun_box(b2, vec);
		Gizmos.DrawWireSphere((Vector3)simplex.c, 0.2f);
		Gizmos.DrawWireSphere((Vector3)simplex.b, 0.2f);
		simplex.count = 2;
		vec = PhysTools.ClosestPointOnLineToOrigin(simplex.c, simplex.b, Fix.One);
		Gizmos.color = UnityEngine.Color.cyan;
		Gizmos.DrawRay(0.5f * Vector3.zero, -(Vector3)vec);
		Gizmos.color = UnityEngine.Color.green;
		int num = 0;
		if (num < 1000)
		{
			vec = -vec;
			if (vec == Vec2.zero)
			{
				distance = Fix.Zero;
				return true;
			}
			simplex.a = PhysTools.SupportFun_box(b1, vec) - PhysTools.SupportFun_box(b2, -vec);
			Gizmos.DrawWireSphere((Vector3)simplex.a, 0.2f);
			Fix fix = Vec2.Dot(simplex.a, vec);
			Fix fix2 = Vec2.Dot(simplex.c, vec);
			Fix fix3 = (Fix)0.001;
			if (fix - fix2 < fix3)
			{
				distance = Vec2.SqrMagnitude(vec);
				if (distance != Fix.Zero)
				{
					distance = Fix.Sqrt(distance);
				}
				return true;
			}
			drawSimplex(simplex);
			PhysTools.ClosestPointOnLineToOrigin(simplex.c, simplex.a, Fix.One);
			PhysTools.ClosestPointOnLineToOrigin(simplex.a, simplex.b, Fix.One);
			return false;
		}
		return false;
	}

