	private bool minkowski_box_box(Box b1, Box b2, ref Vec2 nearPoint, ref Fix penDepth, ref Vec2 penNormal)
	{
		Vec2 vec = b1.center + b1.right + b1.up;
		Vec2 vec2 = b1.center + b1.right - b1.up;
		Vec2 vec3 = b1.center - b1.right + b1.up;
