		Vec2 vec14 = vec - vec6;
		Vec2 vec15 = vec - vec8;
		Vec2 vec16 = vec2 - vec8;
		if (Vec2.Cross(vec10 - vec9, vec9) < 0L || Vec2.Cross(vec11 - vec10, vec10) < 0L || Vec2.Cross(vec12 - vec11, vec11) < 0L || Vec2.Cross(vec13 - vec12, vec12) < 0L || Vec2.Cross(vec14 - vec13, vec13) < 0L || Vec2.Cross(vec15 - vec14, vec14) < 0L || Vec2.Cross(vec16 - vec15, vec15) < 0L || Vec2.Cross(vec9 - vec16, vec16) < 0L)
