		Fix fix = (Fix)0.5;
		Fix fix2 = fix * b1.inverseExtents.x;
		Fix fix3 = fix * b1.inverseExtents.y;
		Fix fix4 = fix * b2.inverseExtents.x;
		Fix fix5 = fix * b2.inverseExtents.y;
		Vec2 vec17 = Vec2.MulByI(vec10 - vec9) * fix2;
		Vec2 vec18 = Vec2.MulByI(vec12 - vec11) * fix3;
		Vec2 vec19 = Vec2.MulByI(vec14 - vec13) * fix2;
		Vec2 vec20 = Vec2.MulByI(vec16 - vec15) * fix3;
		Vec2 vec21 = Vec2.MulByI(vec11 - vec10);
		Vec2 vec22 = Vec2.MulByI(vec13 - vec12);
		Vec2 vec23 = Vec2.MulByI(vec15 - vec14);
		Vec2 vec24 = Vec2.MulByI(vec9 - vec16);
		if (Vec2.Dot(b1.up, b2.up) < 0L == Vec2.Cross(b1.up, b2.up) < 0L)
		{
			vec21 *= fix5;
			vec22 *= fix4;
			vec23 *= fix5;
			vec24 *= fix4;
		}
		else
		{
			vec21 *= fix4;
			vec22 *= fix5;
			vec23 *= fix4;
			vec24 *= fix5;
		}
		Fix fix6 = Vec2.Dot(vec9, vec17);
		Fix fix7 = Vec2.Dot(vec10, vec21);
		Fix fix8 = Vec2.Dot(vec11, vec18);
		Fix fix9 = Vec2.Dot(vec12, vec22);
		Fix fix10 = Vec2.Dot(vec13, vec19);
		Fix fix11 = Vec2.Dot(vec14, vec23);
		Fix fix12 = Vec2.Dot(vec15, vec20);
		Fix fix13 = Vec2.Dot(vec16, vec24);
		Fix fix14 = fix6;
		int num = 0;
		if (fix6 < fix14)
		{
			fix14 = fix6;
		}
		if (fix7 < fix14)
		{
			fix14 = fix7;
			num = 1;
