	private void clipOverlappingFaces(Vec2 a1, Vec2 a2, Vec2 b1, Vec2 b2, Fix radiusA, Fix radiusB, ref CollisionManifold manifold)
	{
		Vec2 u = a2 - a1;
		bool flag = Vec2.Dot(b1 - a1, u) < 0L;
		bool flag2 = Vec2.Dot(b2 - a2, u) <= 0L;
		bool flag3 = Vec2.Dot(a1 - b2, u) < 0L;
		if (flag && flag2)
		{
			manifold.normal = -manifold.normal;
			manifold.contactPoint = a1 + manifold.normal * radiusA;
		}
		else if (!flag && flag2 && flag3)
		{
			manifold.contactPoint = b2 - manifold.normal * (radiusB - manifold.penetration);
		}
		else if (!flag && flag2 && !flag3)
		{
			manifold.contactPoint = a1 + manifold.normal * radiusA;
		}
		else
		{
			manifold.normal = -manifold.normal;
			manifold.contactPoint = a2 + manifold.normal * radiusA;
		}
	}

	private bool minkowskiFindCircleStuff(Vec2 a, Vec2 b, Vec2 circleB, Vec2 circleA, Fix totalRadius, ref CollisionManifold manifold)
	{
		Vec2 u = b - a;
		Fix fix = Vec2.Dot(a, u);
		Fix fix2 = Vec2.Dot(b, u);
		if (Fix.Zero > fix2)
		{
			Fix fix3 = Vec2.SqrMagnitude(circleA);
			if (fix3 > totalRadius * totalRadius)
			{
				manifold.penetration = -Fix.One;
				return true;
