	private bool minkowski_rbox_rbox_looped(ref RoundedRect rb1, ref RoundedRect rb2, ref CollisionManifold manifold)
	{
		Fix fix = Vec2.Dot(rb2.box.up, rb1.box.up);
		Fix fix2 = Vec2.Dot(rb2.box.right, rb1.box.up);
		bool flag = fix2 < Fix.Zero;
		bool flag2 = fix < Fix.Zero;
		Vec2 vec = ((!flag && !flag2) ? (rb2.box.center + rb2.box.right + rb2.box.up) : ((flag && !flag2) ? (rb2.box.center - rb2.box.right + rb2.box.up) : ((!flag2 || flag) ? (rb2.box.center - rb2.box.right - rb2.box.up) : (rb2.box.center + rb2.box.right - rb2.box.up))));
		if (PhysTools.IsApproximatelyZero(fix))
		{
			return minkowski_rbox_rbox_looped_ParallellAngles(Fix.Zero, fix2, ref rb1, ref rb2, ref manifold);
		}
		if (PhysTools.IsApproximatelyZero(fix2))
		{
			return minkowski_rbox_rbox_looped_ParallellAngles(fix, Fix.Zero, ref rb1, ref rb2, ref manifold);
		}
		cornerBuffer[0] = rb1.box.center + rb1.box.right - rb1.box.up;
		cornerBuffer[2] = rb1.box.center - rb1.box.right - rb1.box.up;
		cornerBuffer[4] = rb1.box.center - rb1.box.right + rb1.box.up;
		cornerBuffer[6] = rb1.box.center + rb1.box.right + rb1.box.up;
		cornerBuffer[1] = cornerBuffer[2];
		cornerBuffer[3] = cornerBuffer[4];
		cornerBuffer[5] = cornerBuffer[6];
		cornerBuffer[7] = cornerBuffer[0];
		Fix fix3 = rb1.radius + rb2.radius;
		Fix fix4 = (Fix)0.5;
		normalLengths[0] = fix4 * rb1.box.inverseExtents.x;
		normalLengths[2] = fix4 * rb1.box.inverseExtents.y;
		normalLengths[4] = normalLengths[0];
		normalLengths[6] = normalLengths[2];
		Fix fix5 = fix4 * rb2.box.inverseExtents.x;
		Fix fix6 = fix4 * rb2.box.inverseExtents.y;
		if (fix < 0L == fix2 < 0L)
		{
			normalLengths[1] = fix6;
			normalLengths[3] = fix5;
			normalLengths[5] = fix6;
			normalLengths[7] = fix5;
		}
		else
		{
			normalLengths[1] = fix5;
			normalLengths[3] = fix6;
			normalLengths[5] = fix5;
			normalLengths[7] = fix6;
		}
		Vec2 vec2 = rb1.box.up;
		cornerBuffer[0] -= vec;
		cornerBuffer[1] -= vec;
		if (checkMinkowskiPoint(0, 1, fix3))
		{
			return false;
		}
		Gizmos.color = UnityEngine.Color.cyan;
		Gizmos.DrawLine((Vector3)cornerBuffer[0], (Vector3)cornerBuffer[1]);
		Gizmos.color = UnityEngine.Color.black;
		for (int i = 2; i < 7; i += 2)
		{
			vec2 = Vec2.MulByNegI(vec2);
			vec = PhysTools.SupportFun_box(rb2.box, vec2);
			cornerBuffer[i] -= vec;
			cornerBuffer[i + 1] -= vec;
			if (checkMinkowskiPoint(i - 1, i, fix3))
			{
				return false;
			}
			if (checkMinkowskiPoint(i, i + 1, fix3))
			{
				return false;
			}
		}
		if (checkMinkowskiPoint(7, 0, fix3))
		{
			return false;
		}
		Fix fix7 = Fix.MaxValue;
		int num = 0;
		for (int j = 0; j < outerCornerBuffer.Length; j++)
		{
			Fix fix8 = Vec2.Dot(outerCornerBuffer[j], normalBuffer[j]);
			if (fix8 < fix7)
			{
				fix7 = fix8;
				num = j;
			}
		}
		Gizmos.color = UnityEngine.Color.red;
		manifold.penetration = fix7;
		int num2 = ((num != 7) ? (num + 1) : 0);
		Vec2 b = cornerBuffer[num2] + normalBuffer[num] * fix3;
		if (num == 0 || num == 2 || num == 4 || num == 6)
		{
			manifold.normal = -normalBuffer[num];
			if (minkowskiFindCircleStuff(outerCornerBuffer[num], b, cornerBuffer[num], cornerBuffer[num2], fix3, ref manifold) && manifold.penetration < Fix.Zero)
			{
