			}
			manifold.contactPoint = PhysTools.SupportFun_box(rb2.box, manifold.normal) + manifold.normal * (rb2.radius - manifold.penetration);
			manifold.normal = -manifold.normal;
			return true;
		}
		manifold.normal = normalBuffer[num];
		if (minkowskiFindCircleStuff(outerCornerBuffer[num], b, cornerBuffer[num], cornerBuffer[num2], fix3, ref manifold))
		{
			if (manifold.penetration < Fix.Zero)
