		return true;
	}

	private bool checkMinkowskiPoint(int i, int i2, Fix totalRadius)
	{
		normalBuffer[i] = Vec2.MulByI(cornerBuffer[i2] - cornerBuffer[i]) * normalLengths[i];
		Vec2 vec = normalBuffer[i] * totalRadius;
		Vec2 vec2 = cornerBuffer[i2] + vec;
		outerCornerBuffer[i] = cornerBuffer[i] + vec;
		return Vec2.Cross(outerCornerBuffer[i] - vec2, vec2) > 0L;
	}

