	private bool GJK_box2box(Box b1, Box b2, out Vec2 nearPoint, out Fix penDepth, out Vec2 penNormal)
	{
		penNormal = Vec2.up;
		penDepth = Fix.Zero;
		nearPoint = Vec2.zero;
		colorForSimplex = 0;
		Vec2 vec = b1.center - b2.center;
		Vec2 vec2 = PhysTools.SupportFun_box(b1, vec) - PhysTools.SupportFun_box(b2, -vec);
		Gizmos.DrawWireSphere((Vector3)vec2, 0.2f);
		Simplex simplex = new Simplex
		{
			c = vec2,
			count = 1
		};
		vec = -simplex.c;
		for (int i = 0; i < 1000; i++)
		{
			switch (simplex.count)
			{
			case 1:
			{
				simplex.b = PhysTools.SupportFun_box(b1, vec) - PhysTools.SupportFun_box(b2, -vec);
				Gizmos.DrawWireSphere((Vector3)simplex.b, 0.2f);
				if (Vec2.Dot(simplex.b, vec) < Fix.Zero)
				{
					return false;
				}
				simplex.count++;
				Gizmos.color = UnityEngine.Color.yellow;
				Vec2 vec7 = simplex.b - simplex.c;
				Vec2 vec8 = PhysTools.TripleProduct(vec7, -simplex.c, vec7);
				if (vec8 == Vec2.zero)
				{
					gjk_helper(b1, b2, ref nearPoint, ref penDepth, ref penNormal);
					return true;
				}
				Gizmos.DrawRay(0.5f * (Vector3)(simplex.c + simplex.b), ((Vector3)vec8).normalized);
				vec = vec8;
				break;
			}
			case 2:
				simplex.a = PhysTools.SupportFun_box(b1, vec) - PhysTools.SupportFun_box(b2, -vec);
				Gizmos.DrawWireSphere((Vector3)simplex.a, 0.2f);
				if (Vec2.Dot(simplex.a, vec) < Fix.Zero)
				{
					return false;
				}
				simplex.count++;
				break;
			case 3:
			{
				drawSimplex(simplex);
				Vec2 vec3 = simplex.c - simplex.a;
				Vec2 vec4 = simplex.b - simplex.a;
				Vec2 v = -simplex.a;
				Vec2 vec5 = -PhysTools.TripleProduct(vec4, vec3, vec4);
				if (vec5 == Vec2.zero)
				{
					gjk_helper(b1, b2, ref nearPoint, ref penDepth, ref penNormal);
					return true;
				}
				Gizmos.color = UnityEngine.Color.green;
				Gizmos.DrawRay(0.5f * (Vector3)(simplex.b + simplex.a), ((Vector3)vec5).normalized);
				if (Vec2.Dot(v, vec5) > Fix.Zero)
				{
					simplex.c = simplex.b;
					simplex.b = simplex.a;
					simplex.count = 2;
					vec = vec5;
					break;
				}
				Vec2 vec6 = -PhysTools.TripleProduct(vec3, vec4, vec3);
				Gizmos.color = UnityEngine.Color.cyan;
				Gizmos.DrawRay(0.5f * (Vector3)(simplex.c + simplex.a), ((Vector3)vec6).normalized);
				if (vec6 == Vec2.zero)
				{
					gjk_helper(b1, b2, ref nearPoint, ref penDepth, ref penNormal);
					return true;
				}
				if (Vec2.Dot(v, vec6) > Fix.Zero)
				{
					simplex.b = simplex.a;
					simplex.count = 2;
					vec = vec6;
					break;
				}
				gjk_helper(b1, b2, ref nearPoint, ref penDepth, ref penNormal);
				return true;
			}
			}
		}
		return false;
	}

	private bool GJK_box2box(Box b1, Box b2)
	{
		colorForSimplex = 0;
		Vec2 vec = b1.center - b2.center;
		Vec2 vec2 = PhysTools.SupportFun_box(b1, vec) - PhysTools.SupportFun_box(b2, -vec);
		Gizmos.DrawWireSphere((Vector3)vec2, 0.2f);
		Simplex simplex = new Simplex
		{
			c = vec2,
			count = 1
		};
		vec = -simplex.c;
		for (int i = 0; i < 1000; i++)
		{
			switch (simplex.count)
			{
			case 1:
			{
				simplex.b = PhysTools.SupportFun_box(b1, vec) - PhysTools.SupportFun_box(b2, -vec);
				Gizmos.DrawWireSphere((Vector3)simplex.b, 0.2f);
				if (Vec2.Dot(simplex.b, vec) < Fix.Zero)
				{
					return false;
				}
				simplex.count++;
				Gizmos.color = UnityEngine.Color.yellow;
				Vec2 vec7 = simplex.b - simplex.c;
				Vec2 vec8 = PhysTools.TripleProduct(vec7, -simplex.c, vec7);
				if (vec8 == Vec2.zero)
				{
					return true;
				}
				Gizmos.DrawRay(0.5f * (Vector3)(simplex.c + simplex.b), ((Vector3)vec8).normalized);
				vec = vec8;
				break;
			}
			case 2:
				simplex.a = PhysTools.SupportFun_box(b1, vec) - PhysTools.SupportFun_box(b2, -vec);
				Gizmos.DrawWireSphere((Vector3)simplex.a, 0.2f);
				if (Vec2.Dot(simplex.a, vec) < Fix.Zero)
				{
					return false;
				}
				simplex.count++;
				break;
			case 3:
			{
				drawSimplex(simplex);
				Vec2 vec3 = simplex.c - simplex.a;
				Vec2 vec4 = simplex.b - simplex.a;
				Vec2 v = -simplex.a;
				Vec2 vec5 = -PhysTools.TripleProduct(vec4, vec3, vec4);
				if (vec5 == Vec2.zero)
				{
					return true;
				}
				Gizmos.color = UnityEngine.Color.green;
				Gizmos.DrawRay(0.5f * (Vector3)(simplex.b + simplex.a), ((Vector3)vec5).normalized);
				if (Vec2.Dot(v, vec5) > Fix.Zero)
				{
					simplex.c = simplex.b;
					simplex.b = simplex.a;
					simplex.count = 2;
					vec = vec5;
					break;
				}
				Vec2 vec6 = -PhysTools.TripleProduct(vec3, vec4, vec3);
				Gizmos.color = UnityEngine.Color.cyan;
				Gizmos.DrawRay(0.5f * (Vector3)(simplex.c + simplex.a), ((Vector3)vec6).normalized);
				if (vec6 == Vec2.zero)
				{
					return true;
				}
				if (Vec2.Dot(v, vec6) > Fix.Zero)
				{
					simplex.b = simplex.a;
					simplex.count = 2;
					vec = vec6;
					break;
				}
				return true;
			}
			}
		}
		return false;
	}

	private void drawSimplex(Simplex simplex)
	{
		Gizmos.color = colors[colorForSimplex];
		colorForSimplex = (colorForSimplex + 1) % colors.Length;
		Gizmos.DrawLine((Vector3)simplex.c, (Vector3)simplex.b);
		Gizmos.DrawLine((Vector3)simplex.b, (Vector3)simplex.a);
		Gizmos.DrawLine((Vector3)simplex.a, (Vector3)simplex.c);
	}

	private void drawMinkowskiDifference(Box b1, Box b2)
	{
		Vec2 vec = b1.center + b1.right + b1.up;
		Vec2 vec2 = b1.center + b1.right - b1.up;
		Vec2 vec3 = b1.center - b1.right + b1.up;
		Vec2 vec4 = b1.center - b1.right - b1.up;
		Vec2 vec5 = b2.center + b2.right + b2.up;
		Vec2 vec6 = b2.center + b2.right - b2.up;
		Vec2 vec7 = b2.center - b2.right + b2.up;
		Vec2 vec8 = b2.center - b2.right - b2.up;
		List<Vector3> list = new List<Vector3>();
		list.Add((Vector3)(vec - vec5));
		list.Add((Vector3)(vec - vec6));
		list.Add((Vector3)(vec - vec7));
		list.Add((Vector3)(vec - vec8));
		list.Add((Vector3)(vec2 - vec5));
		list.Add((Vector3)(vec2 - vec6));
		list.Add((Vector3)(vec2 - vec7));
		list.Add((Vector3)(vec2 - vec8));
		list.Add((Vector3)(vec3 - vec5));
		list.Add((Vector3)(vec3 - vec6));
		list.Add((Vector3)(vec3 - vec7));
		list.Add((Vector3)(vec3 - vec8));
		list.Add((Vector3)(vec4 - vec5));
		list.Add((Vector3)(vec4 - vec6));
		list.Add((Vector3)(vec4 - vec7));
		list.Add((Vector3)(vec4 - vec8));
		Gizmos.color = UnityEngine.Color.black;
		for (int i = 0; i < list.Count; i++)
		{
			for (int j = 0; j < list.Count; j++)
			{
				Gizmos.DrawLine(list[i], list[j]);
			}
		}
	}

	private void drawMinkowskiDifference(RoundedRect rb1, RoundedRect rb2)
	{
		Vec2 vec = rb1.box.center + rb1.box.right + rb1.box.up;
		Vec2 vec2 = rb1.box.center + rb1.box.right - rb1.box.up;
		Vec2 vec3 = rb1.box.center - rb1.box.right + rb1.box.up;
		Vec2 vec4 = rb1.box.center - rb1.box.right - rb1.box.up;
		Fix fix = Vec2.Dot(rb2.box.up, rb1.box.up);
		Fix fix2 = Vec2.Cross(rb2.box.up, rb1.box.up);
		Vec2 vec9;
		Vec2 vec10;
		Vec2 vec11;
		Vec2 vec12;
		if (fix == Fix.Zero || fix2 == Fix.Zero)
		{
			Vec2 vec5 = rb2.box.center + rb1.box.right + rb1.box.up;
			Vec2 vec6 = rb2.box.center + rb1.box.right - rb1.box.up;
			Vec2 vec7 = rb2.box.center - rb1.box.right + rb1.box.up;
			Vec2 vec8 = rb2.box.center - rb1.box.right - rb1.box.up;
			if (fix > Fix.Zero)
			{
				vec9 = vec5;
				vec10 = vec6;
				vec11 = vec7;
				vec12 = vec8;
			}
			else if (fix < Fix.Zero)
			{
				vec9 = -vec5;
				vec10 = -vec6;
				vec11 = -vec7;
				vec12 = -vec8;
			}
			if (!(fix2 > Fix.Zero) && !(fix2 > Fix.Zero))
			{
			}
		}
		else if (fix == Fix.Zero && fix2 >= 0L)
		{
			vec9 = rb2.box.center + rb2.box.right + rb2.box.up;
			vec10 = rb2.box.center - rb2.box.right - rb2.box.up;
			vec11 = rb2.box.center + rb2.box.right - rb2.box.up;
			vec12 = rb2.box.center - rb2.box.right + rb2.box.up;
		}
		else if (fix2 == Fix.Zero)
		{
			vec9 = rb2.box.center + rb2.box.right + rb2.box.up;
			vec10 = rb2.box.center - rb2.box.right - rb2.box.up;
			vec11 = rb2.box.center + rb2.box.right - rb2.box.up;
			vec12 = rb2.box.center - rb2.box.right + rb2.box.up;
		}
		vec9 = PhysTools.SupportFun_box(rb2.box, rb1.box.up);
		vec10 = PhysTools.SupportFun_box(rb2.box, -rb1.box.up);
		vec11 = PhysTools.SupportFun_box(rb2.box, rb1.box.right);
		vec12 = PhysTools.SupportFun_box(rb2.box, -rb1.box.right);
		Vec2 vec13 = vec2 - vec9;
		Vec2 vec14 = vec4 - vec9;
		Vec2 vec15 = vec4 - vec11;
		Vec2 vec16 = vec3 - vec11;
		Vec2 vec17 = vec3 - vec10;
		Vec2 vec18 = vec - vec10;
		Vec2 vec19 = vec - vec12;
		Vec2 vec20 = vec2 - vec12;
		Gizmos.DrawLine((Vector3)vec13, (Vector3)vec14);
		Gizmos.DrawLine((Vector3)vec14, (Vector3)vec15);
		Gizmos.DrawLine((Vector3)vec15, (Vector3)vec16);
		Gizmos.DrawLine((Vector3)vec16, (Vector3)vec17);
		Gizmos.DrawLine((Vector3)vec17, (Vector3)vec18);
		Gizmos.DrawLine((Vector3)vec18, (Vector3)vec19);
		Gizmos.DrawLine((Vector3)vec19, (Vector3)vec20);
		Gizmos.DrawLine((Vector3)vec20, (Vector3)vec13);
		List<Vector3> list = new List<Vector3>();
		list.Add((Vector3)vec13);
		list.Add((Vector3)vec14);
		list.Add((Vector3)vec15);
		list.Add((Vector3)vec16);
		list.Add((Vector3)vec17);
		list.Add((Vector3)vec18);
		list.Add((Vector3)vec19);
		list.Add((Vector3)vec20);
		for (int i = 0; i < list.Count; i++)
		{
			Gizmos.DrawWireSphere(list[i], (float)(radius + radius2));
		}
		list.Add((Vector3)vec13);
		_ = vec2 - vec9;
		_ = vec4 - vec9;
		_ = vec4 - vec11;
		_ = vec3 - vec11;
		_ = vec3 - vec10;
		_ = vec - vec10;
		_ = vec - vec12;
		_ = vec2 - vec12;
		for (int j = 0; j < list.Count - 1; j++)
		{
			Vec2 vec21 = (Vec2)list[j];
			Vec2 vec22 = (Vec2)list[j + 1];
			Vec2 vec23 = Vec2.MulByI(Vec2.NormalizedSafe(vec22 - vec21)) * (radius + radius2);
			Gizmos.DrawLine((Vector3)(vec21 + vec23), (Vector3)(vec22 + vec23));
		}
	}

	private void OnDrawGizmos_old()
	{
		if (!(DetPhysics.Get() == null))
