			Vector3 to2 = vector5 - vector3 - vector2;
			Gizmos.DrawLine(vector6, to);
			Gizmos.DrawLine(vector7, to2);
			vector6 = vector5 + vector + vector4;
			to = vector5 - vector + vector4;
			vector7 = vector5 + vector - vector4;
			to2 = vector5 - vector - vector4;
			Gizmos.DrawLine(to, to2);
			Gizmos.DrawLine(vector6, vector7);
			vector6 = vector5 + vector3 + vector4;
			to = vector5 - vector3 + vector4;
			vector7 = vector5 + vector3 - vector4;
			to2 = vector5 - vector3 - vector4;
			Gizmos.DrawWireSphere(vector6, (float)radius);
			Gizmos.DrawWireSphere(vector7, (float)radius);
			Gizmos.DrawWireSphere(to, (float)radius);
			Gizmos.DrawWireSphere(to2, (float)radius);
			Vector3 vector8 = (Vector3)(Vec2.MulByNegI(upVector2) * extents2.x);
			Vector3 vector9 = (Vector3)(upVector2 * extents2.y);
			Vector3 vector10 = (Vector3)pos2;
			Vector3 vector11 = vector10 + vector8 + vector9;
			Vector3 vector12 = vector10 - vector8 + vector9;
			Vector3 vector13 = vector10 + vector8 - vector9;
			Vector3 to3 = vector10 - vector8 - vector9;
			Gizmos.DrawLine(vector11, vector12);
			Gizmos.DrawLine(vector13, to3);
			Gizmos.DrawLine(vector12, to3);
			Gizmos.DrawLine(vector11, vector13);
		}
	}

