			inverseExtents = new Vec2(Fix.One / extents2.x, Fix.One / extents2.y)
		};
		RoundedRect r = new RoundedRect
		{
			box = box,
			radius = radius
		};
		RoundedRect r2 = new RoundedRect
		{
			box = box2,
			radius = radius2
		};
		_ = Vec2.zero;
		_ = Vec2.up;
		_ = Fix.MaxValue;
		CollisionManifold collisionManifold = default(CollisionManifold);
		for (int i = 0; i < iterations; i++)
