	private void testNewUnrolledCollisionTest()
	{
		upVector2 = Vec2.NormalizedSafe(upVector2);
		Box box = new Box
		{
			center = pos1,
			layer = 1,
			right = new Vec2(rotation) * extents1.x,
			up = Vec2.MulByI(new Vec2(rotation)) * extents1.y,
			inverseExtents = new Vec2(Fix.One / extents1.x, Fix.One / extents1.y)
		};
		Box box2 = new Box
		{
			center = pos2,
			layer = 1,
			right = new Vec2(rotation2) * extents2.x,
			up = Vec2.MulByI(new Vec2(rotation2)) * extents2.y,
			inverseExtents = new Vec2(Fix.One / extents2.x, Fix.One / extents2.y)
		};
		RoundedRect rb = new RoundedRect
		{
			box = box,
			radius = radius
		};
		RoundedRect rb2 = new RoundedRect
		{
