	private void Update()
	{
		if (!hasRunTest)
		{
			testNewCollisionTest();
		}
	}

	private void LateUpdate()
	{
		if (!hasRunTest)
		{
			hasRunTest = true;
			testNewUnrolledCollisionTest();
		}
	}
