public class WobbleAnimation : MonoBehaviour
{
	public UnityEngine.UI.Image idleImage;

	public UnityEngine.UI.Image wobbleImage;

	private bool inIdle = true;

	public Sprite[] idleAnimation;

	public float idle_timePerFrame = 0.16f;

	public Sprite[] wobbleAnimation;

	public float wobble_timePerFrame = 0.16f;

	public int tallSpriteIndex = 2;

	private float tallSpriteProgress;

	public float tallSpriteDuration = 0.3f;

	private float timeSinceAnimSwap;

	private void Awake()
	{
		idleImage.enabled = true;
		wobbleImage.enabled = false;
	}

	public void PlayWobbleAnimation()
	{
		if (!inIdle && timeSinceAnimSwap / wobble_timePerFrame < (float)tallSpriteIndex)
		{
			tallSpriteProgress = 0f;
		}
		timeSinceAnimSwap = 0f;
		inIdle = false;
	}

	private void Update()
	{
		Sprite[] array = (inIdle ? idleAnimation : wobbleAnimation);
		float num = (inIdle ? idle_timePerFrame : wobble_timePerFrame);
		float num2 = timeSinceAnimSwap / num;
		if (num2 > (float)array.Length)
		{
			inIdle = true;
			float num3 = num2 % (float)array.Length;
			timeSinceAnimSwap = num3 * num;
		}
		array = (inIdle ? idleAnimation : wobbleAnimation);
		UnityEngine.UI.Image image = (inIdle ? idleImage : wobbleImage);
		num2 = timeSinceAnimSwap / num;
		int num4 = (int)num2;
		if (tallSpriteProgress < tallSpriteDuration)
		{
			image.sprite = array[tallSpriteIndex];
		}
		else
		{
			image.sprite = array[num4];
		}
		image.enabled = true;
		if (inIdle)
		{
			wobbleImage.enabled = false;
		}
		else
		{
			idleImage.enabled = false;
		}
		timeSinceAnimSwap += Time.deltaTime;
		tallSpriteProgress += Time.deltaTime;
	}
}
