public class Shake : MonoUpdatable
{
	private FixTransform fixTrans;

	public Fix strength = Fix.One;

	private Vec2 prevShake;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (!GameTime.IsTimeStopped())
		{
			Vec2 vec = Updater.RandomInsideUnitCircle() * strength;
			fixTrans.position -= prevShake;
			fixTrans.position += vec;
			prevShake = vec;
		}
	}
}
