	public void SetAnimation(SpriteFrame[] newAnim)
	{
		currentAnimation = newAnim;
	}

	private void Update()
	{
		if (autoPlay)
		{
			timePassed += Time.deltaTime;
			float num = (float)GameTime.FixedTimeStep;
			while (timePassed > num)
			{
				currentFrame++;
				timePassed -= num;
			}
		}
		int num2 = 0;
		for (int i = 0; i < currentAnimation.Length; i++)
		{
			num2 += currentAnimation[i].frameDuration;
		}
		int num3 = currentFrame % num2;
		int num4 = 0;
		for (int j = 0; j < currentAnimation.Length; j++)
		{
			num4 += currentAnimation[j].frameDuration;
			if (num4 > num3)
			{
				num4 = j;
				break;
			}
		}
		spriteRen.sprite = currentAnimation[num4].sprite;
	}
}
[RequireComponent(typeof(Item))]
public class SmokeGrenadeExplode2 : MonoUpdatable, IGrenadeDetonation, ICollisionCallback
{
	public FlammableSmoke Smoke;

	public GameObject SmokeExplosion;

	public Vec2[] cloudOffsets;

	public Fix spread = Fix.One;

	public Fix noise = Fix.One;

	private Item idHolder;

	private FixTransform fixTrans;

	private DPhysicsCircle hitbox;

	private Grenade grenade;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		grenade = GetComponent<Grenade>();
		idHolder = GetComponent<Item>();
		hitbox = GetComponent<DPhysicsCircle>();
		hitbox.RegisterCollisionCallback(this);
		fixTrans = GetComponent<FixTransform>();
	}

	public void Detonate(Vec2 offset, bool isDuplicatedClone)
	{
		Fix rotation = Updater.RandomFix(Fix.Zero, Fix.PiTimes2);
		Vec2 pos = fixTrans.position + offset;
		FlammableSmoke flammableSmoke = FixTransform.InstantiateFixed(Smoke, pos, rotation);
		flammableSmoke.GetComponent<DPhysicsCircle>().Scale = hitbox.Scale;
		flammableSmoke.SetPlayerOwnerId(idHolder.OwnerId);
		if (grenade != null && !grenade.IsDestroyed && grenade.thrower != null && !grenade.thrower.IsDestroyed)
		{
			grenade.thrower.effectBuffer.Add(flammableSmoke);
		}
		if (isDuplicatedClone)
		{
			DetPhysics.Get().AddObjectToDeleteList(flammableSmoke.GetComponent<FixTransform>(), 1200);
		}
		FixTransform.InstantiateFixed(SmokeExplosion, pos, rotation).transform.localScale = Vector3.one * (float)hitbox.Scale;
	}

	public void SpawnCloud()
	{
		for (int i = 0; i < cloudOffsets.Length; i++)
		{
			Vec2 offset = fixTrans.Scale * (cloudOffsets[i] + Updater.RandomInsideUnitCircle() * noise) * spread;
			Detonate(offset, fixTrans.IsDuplicated);
		}
		AudioManager.Get().Play("smokeBombExplosion");
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (!grenade.DetonatesOnOwner || base.IsDestroyed)
		{
			return;
		}
		if (collision.layer == LayerMask.NameToLayer("Projectile") && collision.colliderPP.fixTrans != null)
		{
			Projectile component = collision.colliderPP.fixTrans.GetComponent<Projectile>();
			if (component != null && !component.IgnitesExplosives)
			{
				return;
			}
		}
		Detonate();
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}

	public void Detonate()
	{
		SpawnCloud();
		Updater.DestroyFix(base.gameObject);
	}
}
public class Teleport : MonoUpdatable
{
	private InstantAbility instantAbility;

	private FixTransform fixTrans;

	public Fix upCastOffset;

	public float minSqrDistanceForLineDrawing = 10f;

	public Fix radius;

	public TeleportIndicator tpiPrefab;

	private TeleportIndicator teleportIndicator;

	public ParticleSystem onCastParticlePrefab;

	public ParticleSystem onSpawnIndicatorParticlePrefab;

	public ParticleSystem onCastParticlePrefabSmall;

	public ParticleSystem betweenPortalsParticlePrefab;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
		instantAbility = GetComponent<InstantAbility>();
	}

	public void CastAbility()
	{
		Fix scale = PlayerHandler.Get().GetPlayer(instantAbility.GetPlayerId()).Scale;
		if (teleportIndicator == null || teleportIndicator.IsDestroyed)
		{
			AudioManager.Get().Play("swapIndicator");
			instantAbility.ignoreNextCooldown = true;
			teleportIndicator = FixTransform.InstantiateFixed(tpiPrefab, fixTrans.position + Vec2.up * upCastOffset);
			teleportIndicator.SetParticleColor(instantAbility.GetPlayerMaterial().GetColor("_ShadowColor"));
			teleportIndicator.SetScale(scale);
			teleportIndicator.ownerId = instantAbility.GetPlayerId();
			UnityEngine.Object.Instantiate(onSpawnIndicatorParticlePrefab, (Vector3)fixTrans.position, Quaternion.identity).GetComponent<portalIndicatorParticle>().SetScale((float)scale);
			return;
		}
		instantAbility.ignoreNextCooldown = false;
		AudioManager.Get().Play("swap");
		teleportIndicator.TeleportEveryoneLaterThisFrame(fixTrans.position, radius);
		UpdateParticleScale(UnityEngine.Object.Instantiate(onCastParticlePrefabSmall, (Vector3)fixTrans.position, Quaternion.identity), scale, Fix.One);
		UnityEngine.Object.Instantiate(onCastParticlePrefab, teleportIndicator.transform.position, Quaternion.identity).GetComponent<portalIndicatorParticle>().SetScale((float)scale);
		Vector3 vector = teleportIndicator.transform.position - (Vector3)fixTrans.position;
		if (vector.sqrMagnitude > minSqrDistanceForLineDrawing)
		{
			ParticleSystem.VelocityOverLifetimeModule velocityOverLifetime = UnityEngine.Object.Instantiate(betweenPortalsParticlePrefab, (Vector3)fixTrans.position, Quaternion.identity).velocityOverLifetime;
			velocityOverLifetime.orbitalOffsetX = vector.x;
			velocityOverLifetime.orbitalOffsetY = vector.y;
			float num = 0.25f;
			velocityOverLifetime.radial = (0f - vector.magnitude) / num;
		}
		Vector3 vector2 = teleportIndicator.transform.position - (Vector3)fixTrans.position;
		if (vector2.sqrMagnitude > minSqrDistanceForLineDrawing)
		{
			ParticleSystem.VelocityOverLifetimeModule velocityOverLifetime2 = UnityEngine.Object.Instantiate(betweenPortalsParticlePrefab, teleportIndicator.transform.position, Quaternion.identity).velocityOverLifetime;
			velocityOverLifetime2.orbitalOffsetX = vector2.x;
			velocityOverLifetime2.orbitalOffsetY = vector2.y;
			float num2 = 0.25f;
			velocityOverLifetime2.radial = vector2.magnitude / num2;
		}
	}

	public static void UpdateParticleScale(ParticleSystem particle, Fix scale, Fix prevScale)
	{
		if (scale != prevScale)
		{
			Fix fix = scale / prevScale;
			ParticleSystem particleSystem = particle;
			while (particleSystem != null)
			{
				ParticleSystem.ShapeModule shape = particleSystem.shape;
				shape.radius *= (float)fix;
				particleSystem = ((particleSystem.transform.childCount <= 0) ? null : particleSystem.transform.GetChild(0).GetComponent<ParticleSystem>());
			}
		}
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawWireSphere(base.transform.position, (float)radius);
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}
}
public class TeleportedObjectEffect : MonoUpdatable
{
	public Fix strength = Fix.One;

	private Vec2 prevShake;

	public ParticleSystem spawnParticlePrefab;

	private Fix timePassed;

	public Fix duration;

	private FixTransform objectToReActivate;

	private FixTransform fixTrans;

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		timePassed += SimDeltaTime * GameTime.PlayerTimeScale;
		if (timePassed > duration)
		{
			if (objectToReActivate != null && !objectToReActivate.IsDestroyed)
			{
				objectToReActivate.gameObject.SetActive(value: true);
				UnityEngine.Object.Instantiate(spawnParticlePrefab, objectToReActivate.transform.position, Quaternion.identity);
			}
			Updater.DestroyFix(base.gameObject);
		}
		if (!GameTime.IsTimeStopped())
		{
			Vec2 vec = Updater.RandomInsideUnitCircle() * strength;
			fixTrans.position -= prevShake;
			fixTrans.position += vec;
			prevShake = vec;
		}
	}

	public void Initialize(FixTransform alreadyTeleportedObject, SpriteRenderer objectRen)
	{
		objectToReActivate = alreadyTeleportedObject;
		base.transform.localScale = objectRen.transform.lossyScale;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
	}
}
public interface ISpell
{
	void AddScale(Fix scaleDiff);
}
public class TeleportIndicator : MonoUpdatable, ISpell
{
	private FixTransform fixTrans;

	private BoplBody body;

	private DPhysicsCircle hurtbox;

	public Fix teleportRadius;

	public ParticleSystem coreParticleRef;

	private ParticleSystem particle;

	private int playerLayer;

	private int abilityLayer;

	private int groundLayer;

	private int lethalTerrain;

	[NonSerialized]
	public int ownerId;

	public Fix maxScale;

	public Fix minScale;

	private Fix scale;

	private bool teleportEveryoneThisFrame;

	private Fix playerTeleportRadius;

	private Vec2 playerTeleportPosition;

	public LayerMask teleportableThings;

	private static PhysicsParent[] playerObjectsBuffer = new PhysicsParent[100];

	private static PhysicsParent[] indicatorObjectsBuffer = new PhysicsParent[100];

	public TeleportedObjectEffect teleportingSpriteEffectPrefab;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		fixTrans = GetComponent<FixTransform>();
		body = GetComponent<BoplBody>();
		hurtbox = GetComponent<DPhysicsCircle>();
		playerLayer = LayerMask.NameToLayer("Player");
		abilityLayer = LayerMask.NameToLayer("ability");
		groundLayer = LayerMask.NameToLayer("wall");
		lethalTerrain = LayerMask.NameToLayer("LethalTerrain");
		particle = GetComponent<ParticleSystem>();
		scale = Fix.One;
	}

	public void SetParticleColor(UnityEngine.Color c)
	{
		coreParticleRef.startColor = UnityEngine.Color.Lerp(UnityEngine.Color.white, c, 0.8f);
	}

	public void SetScale(Fix newScale)
	{
		Teleport.UpdateParticleScale(particle, newScale, scale);
		scale = newScale;
	}

	public void AddScale(Fix scaleDiff)
	{
		Fix fix = Fix.Max(Fix.Min(scale + scaleDiff, maxScale), minScale);
		SetScale(fix);
	}

	public void TeleportEveryoneLaterThisFrame(Vec2 position, Fix playerTeleportRadius)
	{
		playerTeleportPosition = position;
		this.playerTeleportRadius = playerTeleportRadius;
		teleportEveryoneThisFrame = true;
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawWireSphere(base.transform.position, (float)teleportRadius);
	}

	private void DoTeleport()
	{
		Player player = PlayerHandler.Get().GetPlayer(ownerId);
		Fix one = Fix.One;
		if (player != null)
		{
			one = player.Scale;
		}
		int num = DetPhysics.Get().CircleCastAll(playerTeleportPosition, playerTeleportRadius * one, teleportableThings, ref playerObjectsBuffer);
		int num2 = DetPhysics.Get().CircleCastAll(fixTrans.position, teleportRadius * scale, teleportableThings, ref indicatorObjectsBuffer);
		Vec2 vec = fixTrans.position - playerTeleportPosition;
		for (int i = 0; i < num; i++)
		{
			teleportObject(playerObjectsBuffer[i].fixTrans, vec);
		}
		for (int j = 0; j < num2; j++)
		{
			bool flag = false;
			for (int k = 0; k < num; k++)
			{
				flag |= indicatorObjectsBuffer[j].instanceId == playerObjectsBuffer[k].instanceId;
			}
			if (!flag)
			{
				teleportObject(indicatorObjectsBuffer[j].fixTrans, -vec);
			}
		}
	}

	private void teleportObject(FixTransform teleportedObj, Vec2 diff)
	{
		if ((teleportedObj.gameObject.layer == groundLayer && !teleportedObj.CompareTag("boulder")) || (teleportedObj.gameObject.layer == lethalTerrain && teleportedObj.GetComponent<IPlatformAttachable>() != null))
		{
			return;
		}
		Fix rotation = teleportedObj.rotation;
		if (teleportedObj.gameObject.layer == playerLayer || teleportedObj.gameObject.layer == abilityLayer)
		{
			PlayerPhysics component = teleportedObj.GetComponent<PlayerPhysics>();
			PlayerBody playerBody = component?.GetPlayerBody();
			if (playerBody != null && !playerBody.IsDestroyed)
			{
				playerBody.AttachRope(null, playerBody.topAttachment);
				component.GetPlayerBody().selfImposedVelocity = Vec2.zero;
			}
			if (component != null && !component.IsDestroyed)
			{
				component.UnGround(nullRotation: true, playSoundEffect: false);
			}
		}
		SpriteRenderer spriteRenderer = teleportedObj.GetComponent<SpriteRenderer>();
		if (spriteRenderer == null)
		{
			spriteRenderer = teleportedObj.GetComponent<SlimeController>()?.GetPlayerSprite();
		}
		if (!(spriteRenderer != null))
		{
			return;
		}
		TeleportedObjectEffect teleportedObjectEffect = FixTransform.InstantiateFixed(teleportingSpriteEffectPrefab, teleportedObj.position, rotation);
		teleportedObjectEffect.Initialize(teleportedObj, spriteRenderer);
		SpriteRenderer component2 = teleportedObjectEffect.GetComponent<SpriteRenderer>();
		component2.sprite = spriteRenderer.sprite;
		if (spriteRenderer.gameObject.layer == LayerMask.NameToLayer("RigidBodyAffector"))
		{
			component2.sprite = null;
			SpriteRenderer component3 = component2.transform.GetChild(0).GetComponent<SpriteRenderer>();
			if (component3 != null)
			{
				component3.sprite = null;
			}
		}
		teleportedObj.position += diff;
		teleportedObj.gameObject.SetActive(value: false);
	}

	public override void Init()
	{
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (teleportEveryoneThisFrame)
		{
			DoTeleport();
			teleportEveryoneThisFrame = false;
			Updater.DestroyFix(this);
			Updater.DestroyFix(body);
			Updater.DestroyFix(hurtbox);
			Updater.DestroyFix(fixTrans);
			ParticleSystem.MainModule main = particle.main;
			main.simulationSpeed = 3.6f;
			particle.Stop();
		}
	}
}
