		TutorialGameHandler.OnMovementArrowAbsorbed();
		Updater.DestroyFix(base.gameObject);
		AudioManager.Get().Play(soundPlayedOnPickup);
	}
}
public class TutorialArrowPickup : MonoUpdatable, ICollisionCallback
{
	private Vec2 startPos;

	public SlimeController sm;

	public int abilityToUnlock;

	private Fix timePassed;

	public Fix hoverSpeed;

	public Fix hoverAmplitude;

	private DPhysicsCircle hitbox;

	public override void Init()
	{
		startPos = hitbox.position;
	}

	public void OnCollide(CollisionInformation collision)
	{
		TutorialGameHandler.UnlockAbility(abilityToUnlock, sm);
		AudioManager.Get().Play("abilityPickup");
		Updater.DestroyFix(base.gameObject);
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		timePassed += SimDeltaTime;
		hitbox.position = startPos + Vec2.up * Fix.Sin(timePassed * hoverSpeed) * hoverAmplitude;
	}

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		hitbox = GetComponent<DPhysicsCircle>();
		hitbox.RegisterCollisionCallback(this);
	}
}
public class TutorialGameHandler : MonoUpdatable
{
	[Serializable]
	public struct TutorialSceneReferences
	{
		public GameObject[] wasd;

		public SpriteRenderer keyboardIndicator;

		public GameObject holdToShootText;

		public GameObject holdToGrenadeText;

		public GameObject clickToDashText;

		public GameObject parent;
	}

	public Material yellowSlimeMaterial;

	public InputUpdater InputUpdaterPrefab;

	public TutorialArrow[] arrows;

	public TutorialSceneReferences textReferences_keyboard;

	public TutorialSceneReferences textReferences_gamePad;

	private TutorialSceneReferences visualReferences;

	public TutorialArrowPickup bowPickup;

	public TutorialArrowPickup grenadePickup;

	public TutorialArrowPickup dashPickup;

	public Sprite[] abilitySprites;

	public Fix[] cooldowns;

	public AnimateGround[] groundsWithDummies;

	private static int movementArrowsAbsorbed;

	private bool hasDash;

	private static TutorialGameHandler selfRef;

	public static bool SwapToGamePadNextUpdate;

	private bool hasPlayedJingle;

	public Fix DelayAfterCompletedTutorial = Fix.One;

	public Fix DelayOfYouWinJingle;

	private bool hasDashed;

	private Fix timePassedSinceDash;

	public Vec2 playerSpawn;

	private InputUpdater inputUpdater;

	public static bool isInTutorial;

	public static void OnMovementArrowAbsorbed()
	{
		movementArrowsAbsorbed++;
	}

	public static void UnlockAbility(int index, SlimeController sm)
	{
		movementArrowsAbsorbed++;
		sm.abilities[index].gameObject.GetComponent<Ability>().Cooldown = selfRef.cooldowns[index];
		sm.AbilityReadyIndicators[index].SetSprite(selfRef.abilitySprites[index]);
		TutorialSceneReferences tutorialSceneReferences = selfRef.textReferences_keyboard;
		switch (index)
		{
		case 0:
			selfRef.groundsWithDummies[0].enabled = true;
			tutorialSceneReferences.holdToShootText.SetActive(value: true);
			tutorialSceneReferences.keyboardIndicator.gameObject.SetActive(value: false);
			break;
		case 1:
			selfRef.groundsWithDummies[1].enabled = true;
			tutorialSceneReferences.holdToGrenadeText.SetActive(value: true);
			tutorialSceneReferences.holdToShootText.SetActive(value: false);
			break;
		case 2:
			tutorialSceneReferences.holdToGrenadeText.SetActive(value: false);
			tutorialSceneReferences.clickToDashText.SetActive(value: true);
			selfRef.hasDash = true;
			break;
		}
		tutorialSceneReferences = selfRef.textReferences_gamePad;
		switch (index)
		{
		case 0:
			selfRef.groundsWithDummies[0].enabled = true;
			tutorialSceneReferences.holdToShootText.SetActive(value: true);
			tutorialSceneReferences.keyboardIndicator.gameObject.SetActive(value: false);
			break;
		case 1:
			selfRef.groundsWithDummies[1].enabled = true;
			tutorialSceneReferences.holdToGrenadeText.SetActive(value: true);
			tutorialSceneReferences.holdToShootText.SetActive(value: false);
			break;
		case 2:
			tutorialSceneReferences.holdToGrenadeText.SetActive(value: false);
			tutorialSceneReferences.clickToDashText.SetActive(value: true);
			selfRef.hasDash = true;
			break;
		}
	}

	public static void SpawnGrenadePickup()
	{
		selfRef.textReferences_gamePad.holdToShootText.SetActive(value: false);
		selfRef.textReferences_keyboard.holdToShootText.SetActive(value: false);
		selfRef.grenadePickup.gameObject.SetActive(value: true);
		movementArrowsAbsorbed--;
	}

	public static void SpawnDashPickup()
	{
		selfRef.dashPickup.gameObject.SetActive(value: true);
		selfRef.textReferences_gamePad.holdToGrenadeText.SetActive(value: false);
		selfRef.textReferences_keyboard.holdToGrenadeText.SetActive(value: false);
		movementArrowsAbsorbed--;
	}

	public static void PickupGreande()
	{
		SlimeController slimeController = UnityEngine.Object.FindObjectOfType<SlimeController>();
		slimeController.abilities[1].GetComponent<Ability>().Cooldown = selfRef.cooldowns[1];
		slimeController.AbilityReadyIndicators[1].SetSprite(selfRef.abilitySprites[1]);
		selfRef.groundsWithDummies[1].enabled = true;
	}

	public override void Init()
	{
		AudioManager.Get()?.Play("go");
		AudioManager.Get()?.OnMatchStarted();
		GameSession.inMenus = false;
	}

	private void Update()
	{
		GameObject[] wasd = selfRef.visualReferences.wasd;
		for (int i = 0; i < wasd.Length; i++)
		{
			if (movementArrowsAbsorbed == i)
			{
				wasd[i].SetActive(value: true);
			}
			else
			{
				wasd[i].SetActive(value: false);
			}
		}
		if (movementArrowsAbsorbed >= wasd.Length - 1)
		{
			visualReferences.keyboardIndicator.gameObject.SetActive(value: false);
			textReferences_gamePad.keyboardIndicator.gameObject.SetActive(value: false);
			textReferences_keyboard.keyboardIndicator.gameObject.SetActive(value: false);
		}
		if (PlayerHandler.Get().NumberOfPlayers() == 0)
		{
			return;
		}
		ReadOnlyArray<Gamepad> all = Gamepad.all;
		Player player = PlayerHandler.Get().GetPlayer(1);
		for (int j = 0; j < all.Count; j++)
		{
			if (SwapToGamePadNextUpdate || ((player.inputDevice == null || all[j].deviceId != player.inputDevice.deviceId) && (all[j].buttonEast.isPressed || all[j].buttonNorth.isPressed || all[j].buttonWest.isPressed || all[j].buttonSouth.isPressed || all[j].startButton.isPressed || all[j].selectButton.isPressed)))
			{
				SwapToGamePadNextUpdate = false;
				player.UsesKeyboardAndMouse = false;
				player.inputDevice = all[j];
				PlayerInput component = inputUpdater.GetComponent<PlayerInput>();
				inputUpdater.Init(player.Id);
				component.ActivateInput();
				visualReferences = textReferences_gamePad;
				textReferences_gamePad.parent.SetActive(value: true);
				textReferences_keyboard.parent.SetActive(value: false);
				return;
			}
		}
		Keyboard current = Keyboard.current;
		Mouse current2 = Mouse.current;
		if (!player.UsesKeyboardAndMouse && (current.anyKey.isPressed || current2.leftButton.isPressed || current2.rightButton.isPressed || current2.middleButton.isPressed || current2.backButton.isPressed || current2.forwardButton.isPressed))
		{
			player.UsesKeyboardAndMouse = true;
			player.inputDevice = null;
			PlayerInput component2 = inputUpdater.GetComponent<PlayerInput>();
			inputUpdater.Init(player.Id);
			component2.SwitchCurrentControlScheme("KeyboardAndMouse", current, current2);
			component2.ActivateInput();
			visualReferences = textReferences_keyboard;
			textReferences_gamePad.parent.SetActive(value: false);
			textReferences_keyboard.parent.SetActive(value: true);
		}
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		Player player = PlayerHandler.Get().GetPlayer(1);
		player.ExtraLife = ReviveStatus.permanentRevive;
		for (int i = 0; i <= movementArrowsAbsorbed && i < arrows.Length; i++)
		{
			if (arrows[i] != null && !arrows[i].gameObject.activeInHierarchy)
			{
				arrows[i].gameObject.SetActive(value: true);
			}
		}
		if (movementArrowsAbsorbed > 3 && bowPickup != null && !bowPickup.IsDestroyed && !bowPickup.gameObject.activeInHierarchy)
		{
			bowPickup.gameObject.SetActive(value: true);
		}
		if (hasDash && player.AbilityButtonIsDown(2))
		{
			textReferences_gamePad.clickToDashText.SetActive(value: false);
			textReferences_keyboard.clickToDashText.SetActive(value: false);
			timePassedSinceDash = Fix.Zero;
			hasDashed = true;
			if (Time.timeSinceLevelLoad < 9f)
			{
				AchievementHandler.TryAwardAchievement(AchievementHandler.AchievementEnum.ClearTheTutorialInLessThan9Seconds);
			}
		}
		if (hasDashed)
		{
			timePassedSinceDash += SimDeltaTime;
			if (hasPlayedJingle && timePassedSinceDash > DelayOfYouWinJingle)
			{
				AudioManager.Get().Play("accept2");
				hasPlayedJingle = false;
			}
			if (timePassedSinceDash > DelayAfterCompletedTutorial)
			{
				ExitTutorial();
			}
		}
		if (player.SelectButton_isDown())
		{
			ExitTutorial();
		}
	}

	private void ExitTutorial()
	{
		PlayerHandler.Get().PlayerList().Clear();
		isInTutorial = false;
		Updater.PreLevelLoad();
		SceneManager.LoadScene("MainMenu");
		Updater.PostLevelLoad();
	}

	private void Awake()
	{
		selfRef = this;
		isInTutorial = true;
		hasPlayedJingle = true;
		visualReferences = textReferences_keyboard;
		textReferences_gamePad.parent.SetActive(value: false);
		textReferences_keyboard.parent.SetActive(value: true);
		textReferences_keyboard.holdToGrenadeText.SetActive(value: false);
		textReferences_keyboard.holdToShootText.SetActive(value: false);
		textReferences_gamePad.holdToGrenadeText.SetActive(value: false);
		textReferences_gamePad.holdToShootText.SetActive(value: false);
		GameLobby.isOnlineGame = false;
		movementArrowsAbsorbed = 0;
		Shader.SetGlobalFloat("_Timestop01", 1f);
		Constants.leveltype = LevelType.grass;
		Updater.RegisterUpdatable(this);
		List<Player> list = new List<Player>(1);
		Player player = new Player
		{
			isProtectedFromTimeStop = true,
			stillAliveThisRound = true,
			Scale = Fix.One,
			SpawnPosition = playerSpawn,
			CanUseAbilities = true,
			Color = yellowSlimeMaterial,
			Id = 1,
			IsLocalPlayer = true,
			Team = 1,
			Position = playerSpawn,
			playersAndClonesStillAlive = 1
		};
		player.IsLocalPlayer = true;
		player.isProtectedFromTimeStop = true;
		player.UsesKeyboardAndMouse = true;
		player.ExtraLife = ReviveStatus.willReviveOnDeath;
		list.Add(player);
		PlayerHandler.Get().SetPlayerList(list);
		inputUpdater = UnityEngine.Object.Instantiate(InputUpdaterPrefab);
		PlayerInput component = inputUpdater.GetComponent<PlayerInput>();
		inputUpdater.Claim(player.Id);
		inputUpdater.Init(player.Id);
		component.ActivateInput();
		PlayerHandler.Get().ResetForNextStage();
		for (int i = 0; i < PlayerHandler.Get().PlayerList().Count; i++)
		{
			PlayerHandler.Get().PlayerList()[i].isProtectedFromTimeStop = false;
		}
		GameTime.PlayerTimeScale = Fix.One;
		List<Player> list2 = PlayerHandler.Get().PlayerList();
		for (int j = 0; j < list2.Count; j++)
		{
			list2[j].WonThisRound = false;
			list2[j].KillsAtStartOfRound = list2[j].Kills;
			list2[j].CauseOfDeath = CauseOfDeath.NotDeadYet;
		}
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawWireSphere((Vector3)playerSpawn, 0.5f);
	}
}
public class TutorialTargetDummy : MonoUpdatable, ICollisionCallback
{
	private DPhysicsBox hitbox;

	public AnimateGround animateGround;

	private bool hasReversed;

	public LayerMask layerMask;

	public bool unlockGrenadeOnDeath;

	public bool unlockDashOnDeath;

	private void Awake()
	{
		hitbox = GetComponent<DPhysicsBox>();
		Updater.RegisterUpdatable(this);
		hitbox.RegisterCollisionCallback(this);
	}

	public override void Init()
	{
	}

	public void OnCollide(CollisionInformation collision)
	{
		if (collision.layer != LayerMask.NameToLayer("wall") && !hasReversed && (layerMask.value & (1 << collision.layer)) != 0 && !(animateGround == null))
		{
			animateGround.Reverse();
			hasReversed = true;
			if (unlockGrenadeOnDeath)
			{
				TutorialGameHandler.SpawnGrenadePickup();
			}
			if (unlockDashOnDeath)
			{
				TutorialGameHandler.SpawnDashPickup();
			}
		}
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
	}
}
public class UseOrb : MonoUpdatable, IAbilityComponent
{
	public AnimationData animData;

	private SpriteAnimator animator;

	private SpriteRenderer spriteRen;

	private PlayerBody body;

	private Ability ability;

	private PlayerPhysics physics;

	private PlayerInfo playerInfo;

	private Player player;

	private DPhysicsBox hurtbox;

	private Orb orb;

	public Orb OrbPrefab;

	private InterruptableAudio enterSound;

	private bool orbSpawned;

	private bool limitOrbDirections;

	private bool hasFired;

	public Fix minAngle_radians_newOrbs;

	private void Awake()
	{
		Updater.RegisterUpdatable(this);
		animator = GetComponent<SpriteAnimator>();
		spriteRen = GetComponent<SpriteRenderer>();
		body = GetComponent<PlayerBody>();
		ability = GetComponent<Ability>();
		physics = GetComponent<PlayerPhysics>();
		hurtbox = GetComponent<DPhysicsBox>();
	}

	public void OnEnterAbility()
	{
		playerInfo = ability.GetPlayerInfo();
		player = PlayerHandler.Get().GetPlayer(playerInfo.playerId);
		spriteRen.material = playerInfo.playerMaterial;
		physics.SyncPhysicsTo(playerInfo);
		hurtbox.UpdatePhysicsPositions();
		body.selfImposedVelocity *= (Fix)0.1;
		UpdateFacing(player.AimVector());
		player.InSparkShot = true;
		hasFired = false;
		orbSpawned = false;
		enterSound = AudioManager.Get().PlayInterruptable("startAura");
		if (orb != null && !orb.IsDestroyed && SceneBounds.IsInSceneBounds(orb.fixTrans.position))
		{
			limitOrbDirections = false;
			animator.beginAnimThenPlayAnim(animData.GetAnimation("enter"), animData.GetAnimation("loop"));
			stopOldOrb();
			return;
		}
		limitOrbDirections = playerInfo.isGrounded;
		if (orb != null && !orb.IsDestroyed)
		{
			Updater.DestroyFix(orb.gameObject);
		}
		animator.beginAnimThenDoAction(animData.GetAnimation("enter"), SpawnOrb);
	}

	private void stopOldOrb()
	{
		orb.SetDirection(player.AimVector());
		orb.Stop();
		orbSpawned = true;
	}

	private void UpdateFacing(Vec2 aimVector)
	{
		int num = ((!(Vec2.Dot(aimVector, body.right) <= 0L)) ? 1 : (-1));
		base.transform.localScale = new Vector3(Mathf.Abs(base.transform.localScale.x) * (float)num, base.transform.localScale.y, base.transform.localScale.z);
	}

	private void SpawnOrb()
	{
		orb = FixTransform.InstantiateFixed(OrbPrefab, firePos());
		orb.GetComponent<DPhysicsCircle>().Scale = body.fixtrans.Scale;
		orb.SetDirection(player.AimVector());
		orb.Initialize(player, playerInfo.AbilityButtonUsedIndex012);
		animator.beginAnim(animData.GetAnimation("loop"), null);
		orbSpawned = true;
	}

	private void Fire(Vec2 aimVector)
	{
		animator.beginAnimThenDoAction(animData.GetAnimation("exit"), ExitAbility);
		hasFired = true;
		AudioManager.Get().PlayWithRandomPitchVariation("fireOrb");
		enterSound.source?.Stop();
		if (orb != null && !orb.IsDestroyed)
		{
			orb.Release(aimVector);
		}
	}

	public override void Init()
	{
	}

	private Vec2 firePos()
	{
		return body.position + body.up * (Fix)4L * body.fixtrans.Scale;
	}

	private void Update()
	{
		if (!hasFired)
		{
			AudioManager.Get().PlayOrContinueLoop("loopAura");
		}
	}

	public override void UpdateSim(Fix SimDeltaTime)
	{
		if (orb != null && !orb.IsDestroyed)
		{
			Vec2 direction = ComputeAimVector();
			if (!hasFired)
			{
				orb.SetDirection(direction);
			}
			player.CustomAimAbilityPosition = orb.fixTrans.position;
		}
		else
		{
			player.CustomAimAbilityPosition = firePos();
		}
		if (!GameTime.IsTimeStoppedFor(player.Id) && !player.AbilityButtonIsDown(playerInfo.AbilityButtonUsedIndex012) && !hasFired && orbSpawned)
		{
			Vec2 aimVector = ComputeAimVector();
			UpdateFacing(aimVector);
			Fire(aimVector);
		}
	}

	private Vec2 ComputeAimVector()
	{
		if (limitOrbDirections)
		{
			Vec2 vec = player.AimVector();
			Vec2 vec2 = Vec2.ComplexMul(body.right, new Vec2(minAngle_radians_newOrbs));
			Fix fix = Vec2.Dot(vec, body.up);
			Fix fix2 = Vec2.Dot(vec2, body.up);
			if (fix < -fix2)
			{
				if (Vec2.Dot(vec, body.right) < 0L)
				{
					vec = -vec2;
				}
				else
				{
					vec2 = Vec2.ComplexMul(body.right, new Vec2(-minAngle_radians_newOrbs));
					vec = vec2;
				}
			}
			return vec;
		}
		return player.AimVector();
	}

	public void ExitAbility(AbilityExitInfo exitInfo)
	{
		exitInfo.selfImposedVelocity = body.selfImposedVelocity;
		exitInfo.externalVelocity = body.externalVelocity;
		exitInfo.isFacingRight = base.transform.localScale.x >= 0f;
		exitInfo.position = body.position;
		exitInfo.groundedSpeed = physics.groundedSpeed;
		exitInfo.isGrounded = physics.IsGrounded();
		exitInfo.justlanded = exitInfo.isGrounded;
		exitInfo.currentlyAttachedGround = physics.getAttachedGround();
		exitInfo.lastSprite = spriteRen.sprite;
		exitInfo.groundedLocalPosition = physics.LocalPlatformPos;
		exitInfo.radius = physics.radius;
		player.InSparkShot = false;
		ability.ExitAbility(exitInfo);
	}

	private void ExitAbility()
	{
		ExitAbility(default(AbilityExitInfo));
	}

	public void OnScaleChanged(Fix scaleMultiplier)
	{
	}
}
