	public static Fix Tan(Fix x)
	{
		long num = x.m_rawValue % 13493037704L;
		bool flag = false;
		if (num < 0)
		{
			num = -num;
			flag = true;
		}
		if (num > 6746518852L)
		{
			flag = !flag;
			num = 6746518852L - (num - 6746518852L);
		}
		Fix fix = new Fix(num) * LutInterval;
		Fix fix2 = Round(fix);
		Fix fix3 = fix - fix2;
		Fix fix4 = new Fix(TanLut[(int)(long)fix2]);
		Fix fix5 = new Fix(TanLut[(int)(long)fix2 + Sign(fix3)]);
		long rawValue = (fix3 * Abs(fix4 - fix5)).m_rawValue;
		long num2 = fix4.m_rawValue + rawValue;
		return new Fix(flag ? (-num2) : num2);
	}

	public static Fix Acos(Fix x)
	{
		if (x < -One || x > One)
		{
			throw new ArgumentOutOfRangeException("x");
		}
		if (x.m_rawValue == 0L)
		{
			return PiOver2;
		}
		Fix fix = Atan(Sqrt(SlowSub(One, SlowMul(x, x))) / x);
		if (x.m_rawValue >= 0)
		{
			return fix;
		}
		return SlowAdd(fix, Pi);
	}

	public static Fix Atan(Fix z)
	{
		if (z.m_rawValue == 0L)
		{
			return Zero;
		}
		bool flag = z.m_rawValue < 0;
		if (flag)
		{
			z = -z;
		}
		Fix y = (Fix)2L;
		Fix y2 = (Fix)3L;
		bool flag2 = z > One;
		if (flag2)
		{
			z = One / z;
		}
		Fix x = One;
		Fix fix = One;
		Fix x2 = SlowMul(z, z);
		Fix fix2 = SlowMul(x2, y);
		Fix fix3 = SlowAdd(x2, One);
		Fix y3 = SlowMul(fix3, y);
		Fix fix4 = fix2;
		Fix fix5 = SlowMul(fix3, y2);
		for (int i = 2; i < 30; i++)
		{
			fix = SlowMul(fix, fix4 / fix5);
			x = SlowAdd(x, fix);
			fix4 = SlowAdd(fix4, fix2);
			fix5 = SlowAdd(fix5, y3);
			if (fix.m_rawValue == 0L)
			{
				break;
			}
		}
		x = SlowMul(x, z) / fix3;
		if (flag2)
		{
			x = SlowSub(PiOver2, x);
		}
		if (flag)
		{
			x = -x;
		}
		return x;
	}

	public static Fix Atan2(Fix y, Fix x)
	{
		long rawValue = y.m_rawValue;
		long rawValue2 = x.m_rawValue;
		if (rawValue2 == 0L)
		{
			if (rawValue > 0)
			{
				return PiOver2;
			}
			if (rawValue == 0L)
			{
				return Zero;
			}
			return -PiOver2;
		}
		Fix fix = y / x;
		if (SlowAdd(One, SlowMul((Fix)0.28m, SlowMul(fix, fix))) == MaxValue)
		{
			if (!(y < Zero))
			{
				return PiOver2;
			}
			return -PiOver2;
		}
		Fix fix2;
		if (SlowAbs(fix) < One)
		{
			fix2 = fix / SlowAdd(One, SlowMul((Fix)0.28m, SlowMul(fix, fix)));
			if (rawValue2 < 0)
			{
				if (rawValue < 0)
				{
					return SlowSub(fix2, Pi);
				}
				return SlowAdd(fix2, Pi);
			}
		}
		else
		{
			fix2 = SlowSub(PiOver2, fix) / SlowAdd(SlowMul(fix, fix), (Fix)0.28m);
			if (rawValue < 0)
			{
				return SlowSub(fix2, Pi);
			}
		}
		return fix2;
	}

