	internal static void GenerateSinLut()
	{
		using StreamWriter streamWriter = new StreamWriter("FixSinLut.cs");
		streamWriter.Write("namespace FixMath.NET \r\n    {\r\n    partial struct Fix \r\n    {\r\n        public static readonly long[] SinLut = new[] \r\n        {");
		int num = 0;
		for (int i = 0; i < 205887; i++)
		{
			double a = (double)i * Math.PI * 0.5 / 205886.0;
			if (num++ % 8 == 0)
			{
				streamWriter.WriteLine();
				streamWriter.Write("            ");
			}
			long rawValue = ((Fix)Math.Sin(a)).m_rawValue;
			streamWriter.Write($"0x{rawValue:X}L, ");
		}
		streamWriter.Write("\r\n        };\r\n    }\r\n    }");
	}

